def write_phase_sequence_html(stats, output_path):
    """
    Generate an HTML file showing, for all intersections and phases, the phase number and timing throughout the entire sequence.
    Includes key metrics (avg bus delay, avg car delay, travel times, etc.) for each intersection.
    """
    try:
        # Collect per-intersection phase sequence and metrics
        phase_rows = []
        for iid, inter_data in getattr(stats, '_inter', {}).items():
            # Try to get phase/timing sequence if available (assume stored as 'phase_sequence' in inter_data)
            phase_seq = inter_data.get('phase_sequence', [])
            for phase_info in phase_seq:
                # phase_info: dict with keys like 'phase', 'start_time', 'end_time', 'duration', etc.
                row = {
                    'IntersectionID': iid,
                    'Phase': phase_info.get('phase'),
                    'StartTime': phase_info.get('start_time'),
                    'EndTime': phase_info.get('end_time'),
                    'Duration': phase_info.get('duration'),
                }
                phase_rows.append(row)
        # If no phase sequence, skip
        if not phase_rows:
            return
        df_phase = phase_rows
        # Collect per-intersection metrics
        metric_rows = []
        for iid, inter_data in getattr(stats, '_inter', {}).items():
            k = stats._kpis_for(iid)
            metric_rows.append({
                'IntersectionID': iid,
                'AvgBusDelay_s': round(k.get('avg_bus_pass_delay_s', 0), 2),
                'AvgCarDelay_s': round(k.get('avg_car_pass_delay_s', 0), 2),
                'AvgTruckDelay_s': round(k.get('avg_truck_pass_delay_s', 0), 2),
                'AvgBusTravelTime_s': round(k.get('avg_bus_tt_s', 0), 2),
                'AvgCarTravelTime_s': round(inter_data.get('avg_car_tt_s', 0), 2),
                'AvgTruckTravelTime_s': round(inter_data.get('avg_truck_tt_s', 0), 2),
            })
        df_metrics = metric_rows

        def _rows_to_html(rows):
            if not rows:
                return '<table><tr><td>(no data)</td></tr></table>'
            headers = list(rows[0].keys())
            lines = ['<table border="1" cellpadding="4" cellspacing="0">',
                     '<tr>' + ''.join(f'<th>{h}</th>' for h in headers) + '</tr>']
            for r in rows:
                lines.append('<tr>' + ''.join(f'<td>{r.get(h, "")}</td>' for h in headers) + '</tr>')
            lines.append('</table>')
            return '\n'.join(lines)

        # Write HTML
        with open(output_path, 'w', encoding='utf-8') as f:
            f.write('<h2>Intersection Phase Sequence</h2>')
            f.write(_rows_to_html(df_phase))
            f.write('<h2>Intersection Key Metrics</h2>')
            f.write(_rows_to_html(df_metrics))
    except Exception as e:
        import traceback
        log_to_file(f"[HTML OUTPUT ERROR] {e}\n{traceback.format_exc()}", force=True)
