def _finite_xy(x_val, y_val):
    try:
        x_f = float(x_val)
        y_f = float(y_val)
    except (TypeError, ValueError):
        return None
    if not (math.isfinite(x_f) and math.isfinite(y_f)):
        return None
    if x_f == 0.0 and y_f == 0.0:
        return None
    return (x_f, y_f)


def _extract_xy_from_point_like(obj):
    if obj is None:
        return None
    if isinstance(obj, (tuple, list)) and len(obj) >= 2:
        return _finite_xy(obj[0], obj[1])

    for _x_attr, _y_attr in (
        ('x', 'y'),
        ('getX', 'getY'),
        ('xCoord', 'yCoord'),
        ('getx', 'gety'),
    ):
        _x = getattr(obj, _x_attr, None)
        _y = getattr(obj, _y_attr, None)
        if _x is None or _y is None:
            continue
        try:
            _x = _x() if callable(_x) else _x
            _y = _y() if callable(_y) else _y
        except Exception:
            continue
        _xy = _finite_xy(_x, _y)
        if _xy is not None:
            return _xy
    return None


def _extract_xy_from_section_info(sec_info):
    if sec_info is None:
        return None
    for _x_attr, _y_attr in (
        ('xSection', 'ySection'),
        ('xSectionTo', 'ySectionTo'),
        ('xcoordTo', 'ycoordTo'),
        ('xTo', 'yTo'),
        ('xDestination', 'yDestination'),
        ('xEnd', 'yEnd'),
        ('x', 'y'),
    ):
        _xy = _finite_xy(getattr(sec_info, _x_attr, None), getattr(sec_info, _y_attr, None))
        if _xy is not None:
            return _xy
    return None


def _extract_xy_from_catalog_object(obj):
    if obj is None:
        return None

    for _meth in ('getPosition', 'getCenter', 'getCentroid', 'center', 'centroid'):
        _fn = getattr(obj, _meth, None)
        if not callable(_fn):
            continue
        try:
            _xy = _extract_xy_from_point_like(_fn())
        except Exception:
            _xy = None
        if _xy is not None:
            return _xy

    _xy = _extract_xy_from_point_like(obj)
    if _xy is not None:
        return _xy

    for _child_meth in ('getNodes', 'getChildNodes', 'getInternalNodes', 'getSubNodes'):
        _fn = getattr(obj, _child_meth, None)
        if not callable(_fn):
            continue
        try:
            _children = list(_fn() or [])
        except Exception:
            continue
        _pts = []
        for _child in _children:
            _cxy = _extract_xy_from_catalog_object(_child)
            if _cxy is not None:
                _pts.append(_cxy)
        if _pts:
            return (
                sum(_p[0] for _p in _pts) / len(_pts),
                sum(_p[1] for _p in _pts) / len(_pts),
            )

    return None


def _resolve_junction_xy_from_model(node_id: int, incoming_sections=None):
    try:
        from PyANGKernel import GKSystem as _GKS
        _model = _GKS.getSystem().getActiveModel()
        if _model is None:
            return None
        _catalog = _model.getCatalog()
        _candidate_ids = []
        if node_id and node_id > 0:
            _candidate_ids.append(int(node_id))
        for _sec_id in incoming_sections or []:
            try:
                _si = AKIInfNetGetSectionANGInf(int(_sec_id))
                _node_to = int(getattr(_si, 'idNodeTo', 0) or 0)
                if _node_to > 0 and _node_to not in _candidate_ids:
                    _candidate_ids.append(_node_to)
            except Exception:
                continue

        for _cid in _candidate_ids:
            try:
                _obj = _catalog.find(_cid)
            except Exception:
                _obj = None
            _xy = _extract_xy_from_catalog_object(_obj)
            if _xy is not None:
                return _xy
    except Exception:
        return None
    return None


def _network_stats_section_ids():
    global _net_stats_sections_cache
    if _net_stats_sections_cache is not None:
        return list(_net_stats_sections_cache)

    _secs: set = set()
    try:
        _n_secs = int(AKIInfNetNbSectionsANG())
        for _si in range(_n_secs):
            _sid = int(AKIInfNetGetSectionANGId(_si))
            if _sid > 0:
                _secs.add(_sid)
    except Exception:
        pass

    if not _secs:
        for _iid_data in getattr(stats, '_inter', {}).values():
            for _sec in _iid_data.get('main_sections', []):
                if isinstance(_sec, int) and _sec > 0:
                    _secs.add(_sec)
            for _sec in _iid_data.get('side_sections', []):
                if isinstance(_sec, int) and _sec > 0:
                    _secs.add(_sec)
        for _ctrl in controllers.values():
            for _sec in getattr(_ctrl, 'incoming_sections', []):
                if _sec and _sec > 0:
                    _secs.add(int(_sec))

    _net_stats_sections_cache = _secs
    return list(_secs)


def _mark_detection_point(junction_id: int, veh_id: int, x: float, y: float,
                          sim_time: float, tier: str, meta: dict = None):
    """
    Record the first detection event for this (junction, vehicle) pair.

    1. Writes a row to detection_points.csv immediately (includes signal_phase
       and bus_phase so the green-wave plot can show green/red status).
    2. Appends a GeoJSON feature (flushed to .geojson in AAPIFinish).
    3. Attempts to colour the vehicle bright red in the Aimsun animation.
       The colour API may not exist in all Aimsun builds — failure is silent.
    """
    global _mark_calls_total, _mark_calls_written
    _mark_calls_total += 1

    if not MARK_DETECTION_POINTS:
        return
    meta = dict(meta or {})
    key = (junction_id, veh_id)
    _last_t = _marked_detections.get(key, -9999.0)
    if not meta.get("force_write") and sim_time - _last_t < _MARK_DET_REARM_S:
        return
    _marked_detections[key] = sim_time
    _mark_calls_written += 1

    # ── Capture current signal phase and configured bus phase ─────────────────
    _signal_phase = -1
    try:
        _signal_phase = ECIGetCurrentPhase(junction_id)
    except Exception:
        pass
    _bus_phase = -1
    try:
        _cfg = INTERSECTIONS_CONFIG.get(junction_id, {})
        _bus_phase = int(_cfg.get("BusPhase", -1) or -1)
    except Exception:
        pass
    _phase_start_t = -1.0
    try:
        _phase_start_t = float(ECIGetStartingTimePhase(junction_id))
    except Exception:
        pass

    meta = dict(meta or {})
    _prearm_status = str(meta.get("prearm_status", "") or "")
    _prearm_eta_s = meta.get("prearm_eta_s", "")
    _prearm_eta_abs_s = meta.get("prearm_eta_abs_s", "")
    _prearm_fired_t = meta.get("prearm_fired_t", "")
    _prearm_resolved_t = meta.get("prearm_resolved_t", "")
    _prearm_note = str(meta.get("prearm_note", "") or "")
    _focus_role = "none"
    _focus_active = 1 if _focus_bus_id > 0 else 0
    if _focus_active:
        _focus_role = "focused_bus" if veh_id == _focus_bus_id else "blocked_by_focus"
    if str(tier).startswith("focus_acquire"):
        _focus_role = "focus_acquire"
    elif str(tier).startswith("focus_suppress"):
        _focus_role = "focus_suppress"
    _focus_held_s = (
        max(0.0, float(sim_time) - float(_focus_start_t))
        if _focus_active and _focus_start_t >= 0.0 else 0.0
    )

    # ── 1. CSV ────────────────────────────────────────────────────────────────
    # Look up the junction centroid so the map can overlay intersection markers.
    _jct_entry = (_jct_xy_cache or {}).get(junction_id)
    _jct_cx = f"{_jct_entry[0]:.3f}" if _jct_entry else ""
    _jct_cy = f"{_jct_entry[1]:.3f}" if _jct_entry else ""
    write_header = not os.path.isfile(_DET_CSV)
    try:
        with open(_DET_CSV, "a", newline="", encoding="utf-8") as f:
            w = csv.writer(f)
            if write_header:
                w.writerow(["sim_time_s", "junction_id", "veh_id",
                             "x", "y", "tier", "signal_phase", "bus_phase",
                             "phase_start_t", "jct_x", "jct_y",
                             "prearm_status", "prearm_eta_s",
                             "prearm_eta_abs_s", "prearm_fired_t",
                             "prearm_resolved_t", "prearm_note",
                             "focus_active", "focus_bus_id", "focus_jct_id",
                             "focus_start_t", "focus_held_s", "focus_role"])
            w.writerow([f"{sim_time:.1f}", junction_id, veh_id,
                        f"{x:.3f}", f"{y:.3f}", tier, _signal_phase, _bus_phase,
                        f"{_phase_start_t:.1f}", _jct_cx, _jct_cy,
                        _prearm_status, _prearm_eta_s, _prearm_eta_abs_s,
                        _prearm_fired_t, _prearm_resolved_t, _prearm_note,
                        _focus_active, _focus_bus_id, _focus_jct_id,
                        f"{_focus_start_t:.1f}", f"{_focus_held_s:.1f}",
                        _focus_role])
    except Exception as _e:
        log_to_file(f"[MARK] CSV write failed: {_e}", force=True)

    # ── 2. GeoJSON feature accumulation ───────────────────────────────────────
    _geojson_features.append({
        "type": "Feature",
        "geometry": {"type": "Point", "coordinates": [x, y]},
        "properties": {
            "junction_id": junction_id,
            "veh_id":      veh_id,
            "sim_time_s":  round(sim_time, 1),
            "tier":        tier,
            "prearm_status": _prearm_status,
            "focus_role": _focus_role,
        },
    })

    # ── 3. Colour vehicle red in Aimsun animation ─────────────────────────────
    # AKIVehSetVehicleColor(veh_id, R, G, B) is available in Aimsun Next ≥22.
    # Looked up via globals() so static analysis doesn't flag an undefined name
    # (it arrives via `from AAPI import *`).  Falls back silently if absent.
    try:
        _color_fn = globals().get("AKIVehSetVehicleColor")
        if _color_fn is not None:
            _color_fn(veh_id, 255, 0, 0)   # bright red
    except Exception:
        pass

    log_to_file(
        f"[MARK] jct={junction_id} v={veh_id} tier={tier} "
        f"xy=({x:.1f},{y:.1f}) t={sim_time:.1f}s"
    )


def _record_wave_event(time_s: float, group_name: str, event: str,
                       source_jct: int = -1, target_jct: int = -1,
                       veh_id: int = -1, eta_s: float = -1.0,
                       lead_s: float = -1.0, note: str = "", **extra):
    """Append a structured coordinator event row for post-run diagnostics."""
    _row = {
        "sim_time_s": round(float(time_s), 1),
        "group": str(group_name),
        "event": str(event),
        "source_jct": int(source_jct),
        "target_jct": int(target_jct),
        "veh_id": int(veh_id),
        "eta_s": round(float(eta_s), 1) if eta_s is not None else -1.0,
        "lead_s": round(float(lead_s), 1) if lead_s is not None else -1.0,
        "note": str(note),
    }
    for _k, _v in extra.items():
        if _v is None:
            continue
        if isinstance(_v, bool):
            _row[str(_k)] = int(_v)
            continue
        try:
            _fv = float(_v)
            _row[str(_k)] = round(_fv, 4)
        except Exception:
            _row[str(_k)] = str(_v)
    _wave_events.append(_row)


def _record_objective_trace(row: dict):
    """Append one objective-evaluation trace row for GE/INS diagnostics."""
    global _objective_trace_header_written
    _fields = [
        "sim_time_s", "junction_id", "veh_id",
        "mode", "decision", "reason",
        "current_phase", "bus_phase",
        "bus_eta_s", "time_to_bp_s", "natural_end_s", "next_red_s",
        "ge_lb_s", "ge_ub_s", "opt_ge_s",
        "bp_lb_s", "bp_ub_s", "opt_bp_s",
        "delay_saved_pax_s", "delay_delta_pax_s", "delay_base_pax_s", "delay_with_strategy_pax_s",
        "no_strategy_delay_pax_s", "strategy_min_delay_pax_s", "delay_rule_pick",
        "wave_active", "focus_bus_id", "note",
    ]
    _row = {}
    for _f in _fields:
        _row[_f] = row.get(_f, "")
    try:
        _write_header = (not _objective_trace_header_written) and (not os.path.isfile(_OBJECTIVE_TRACE_CSV))
        with open(_OBJECTIVE_TRACE_CSV, "a", newline="", encoding="utf-8") as _f_obj:
            _w = csv.DictWriter(_f_obj, fieldnames=_fields)
            if _write_header:
                _w.writeheader()
                _objective_trace_header_written = True
            _w.writerow(_row)
    except Exception as _e:
        log_to_file(f"[OBJ TRACE] write failed: {_e}")


def _track_all_bus_positions(time: float, jct_xy: dict):
    """
    Log every PT-line bus position every _BUS_TRACK_INTERVAL_S seconds.

    Writes: sim_time_s, veh_id, x, y, nearest_jct, dist_m, in_zone, zone_radius_m, event

    event column: 'track' (normal), 'zone_enter' (first time inside zone),
                  'zone_exit' (left zone).

    jct_xy: {junction_id: (x, y, detection_zone_m)} — pre-built from controllers.
    If empty, still records raw bus positions with nearest_jct=-1.
    """
    global _bus_track_last_t, _bus_track_header_written, _presence_snapshot_header_written
    global _bus_zone_state
    global _bus_seen_ids, _bus_last_nearest_jct, _bus_line_id
    global _tracking_zone_presence, _bus_observed_jcts
    global _active_corridor_bus_count
    global _bus_xy   # module-level persistent dict — coordinator reads this
    if time - _bus_track_last_t < _BUS_TRACK_INTERVAL_S:
        return
    _bus_track_last_t = time
    # Rebuild the live zone-presence snapshot from scratch each interval
    _tracking_zone_presence.clear()

    rows = []
    _bus_xy = {}  # veh_id -> (x,y) — replaces module-level dict each scan
    active_veh_ids = set()
    try:
        n_lines = AKIPTGetNumberLines()
        for li in range(n_lines):
            line_id = AKIPTGetIdLine(li)
            n_veh = AKIGetNbVehiclesFollowingPTLine(line_id)
            for vi in range(n_veh):
                veh_id = AKIGetVehicleFollowingPTLine(line_id, vi)
                try:
                    inf = AKIPTVehGetInf(veh_id)
                    if getattr(inf, 'report', -1) < 0:
                        continue
                    bx = float(getattr(inf, 'xCurrentPos', 0.0) or 0.0)
                    by = float(getattr(inf, 'yCurrentPos', 0.0) or 0.0)
                    if bx == 0.0 and by == 0.0:
                        continue
                    bspd = float(getattr(inf, 'CurrentSpeed', 40.0) or 40.0)
                except Exception:
                    continue

                active_veh_ids.add(veh_id)
                _bus_xy[veh_id] = (bx, by)
                # Record which PT line this bus is currently following
                _bus_line_id[veh_id] = line_id

                # ── Section-based detection ───────────────────────────────────
                # If the bus is on a section that feeds a corridor junction,
                # fire an auto-detection even if it hasn't entered the spatial zone.
                # Only mark the NEAREST mapped junction to avoid simultaneous
                # detections at multiple junctions from a shared section.
                try:
                    _bus_sec = int(getattr(inf, 'idSection', -1))
                    if _bus_sec > 0 and _bus_sec in _sec_to_corridor_jct:
                        _sec_jcts = _sec_to_corridor_jct[_bus_sec]
                        _eligible_sec_jcts = []
                        for _jid in _sec_jcts:
                            if _jid in _bus_observed_jcts.get(veh_id, set()):
                                continue
                            _zst = _bus_zone_state.get((veh_id, _jid), "out")
                            if _zst != "out":
                                continue
                            _eligible_sec_jcts.append(_jid)

                        if len(_eligible_sec_jcts) == 1:
                            _mark_detection_point(_eligible_sec_jcts[0], veh_id, bx, by, time, "track-section")
                        elif len(_eligible_sec_jcts) > 1 and jct_xy:
                            _nearest_sec_jct = min(
                                _eligible_sec_jcts,
                                key=lambda _j: math.sqrt(
                                    (bx - jct_xy[_j][0])**2 + (by - jct_xy[_j][1])**2
                                ) if _j in jct_xy else 1e9
                            )
                            _mark_detection_point(_nearest_sec_jct, veh_id, bx, by, time, "track-section")
                        elif len(_eligible_sec_jcts) > 1:
                            _mark_detection_point(_eligible_sec_jcts[0], veh_id, bx, by, time, "track-section")
                except Exception:
                    pass

                if jct_xy:
                    # ── Pre-scan: find the nearest junction newly entering zone ──
                    # When junction detection zones overlap (junctions ~300 m apart,
                    # zones 250 m radius), a single bus can transition from out→in for
                    # multiple junctions in the same scan step.  Restrict zone_enter
                    # events (detection-point marking, route tracking, bus-TT entry)
                    # to the NEAREST newly-entered junction so the bus appears at one
                    # junction at a time and journey charts don't show teleportation.
                    _new_zone_entries_this_step = []
                    _dist_cache_this_bus = {}
                    for _jid_pre, (_jx_pre, _jy_pre, _zr_pre) in jct_xy.items():
                        _d_pre = math.sqrt((bx - _jx_pre)**2 + (by - _jy_pre)**2)
                        _dist_cache_this_bus[_jid_pre] = _d_pre
                        if _d_pre <= _zr_pre and not _bus_zone_state.get((veh_id, _jid_pre), False):
                            _new_zone_entries_this_step.append((_d_pre, _jid_pre))
                    _nearest_new_entry_jct = (
                        min(_new_zone_entries_this_step, key=lambda _x: _x[0])[1]
                        if _new_zone_entries_this_step else None
                    )

                    # Check zone status for EVERY junction (not just nearest)
                    for jid, (jx, jy, zr) in jct_xy.items():
                        d = _dist_cache_this_bus.get(jid) or math.sqrt((bx - jx)**2 + (by - jy)**2)
                        now_in = d <= zr
                        zkey = (veh_id, jid)
                        was_in = _bus_zone_state.get(zkey, False)
                        event = "track"
                        
                        # ── Zone occupancy timeout (120s maximum per bus per junction) ──
                        # Prevents buses from staying "near jct" indefinitely if they slow
                        # down or loop within the detection zone.
                        _ZONE_OCCUPANCY_TIMEOUT_S = 120.0
                        zone_entry_t = _bus_zone_entry_time.get(zkey)
                        if zone_entry_t is not None and time - zone_entry_t > _ZONE_OCCUPANCY_TIMEOUT_S:
                            # Force zone exit if bus has been in zone too long
                            now_in = False
                        
                        if now_in:
                            # Keep live zone-presence snapshot current so that
                            # detect_bus / _detect_bus can use it as Tier 0.
                            _tracking_zone_presence.setdefault(jid, {})[veh_id] = (bx, by, bspd)
                        if now_in and not was_in:
                            _bus_zone_state[zkey] = True
                            _bus_zone_entry_time[zkey] = time  # Record entry time for timeout
                            # Only fire zone_enter events for the nearest newly-entered
                            # junction.  Other overlapping zones are marked in-state so
                            # they don't re-fire, but their events are suppressed so the
                            # bus appears sequentially on the journey chart.
                            if jid == _nearest_new_entry_jct:
                                event = "zone_enter"
                                # ── Record observed corridor-junction route ───────
                                try:
                                    obs = _bus_observed_jcts.setdefault(veh_id, [])
                                    if not obs or obs[-1] != jid:
                                        obs.append(jid)
                                except Exception:
                                    pass
                                # ── Auto-detection point ──────────────────────────
                                try:
                                    _mark_detection_point(jid, veh_id, bx, by, time, "track-zone")
                                except Exception:
                                    pass
                                # ── Bus TT zone-entry ─────────────────────────────
                                try:
                                    stats.record_pt_bus_detection(jid, veh_id, time)
                                except Exception:
                                    pass
                        elif not now_in and was_in:
                            event = "zone_exit"
                            _bus_zone_state[zkey] = False
                            # Clear zone entry time on exit
                            if zkey in _bus_zone_entry_time:
                                del _bus_zone_entry_time[zkey]
                            # ── Bus TT zone-exit ──────────────────────────────
                            try:
                                stats.record_pt_bus_exit(jid, veh_id, time)
                            except Exception:
                                pass
                        # Only log zone events for non-nearest junctions
                        # Always log one row per bus for nearest junction
                        if event != "track":
                            rows.append((
                                f"{time:.1f}", veh_id,
                                f"{bx:.1f}", f"{by:.1f}",
                                jid, f"{d:.0f}",
                                1 if now_in else 0, f"{zr:.0f}", event,
                            ))

                    # Find nearest junction for the main tracking row
                    best_jct = -1
                    best_dist = 1e9
                    best_zone = 0.0
                    for jid, (jx, jy, zr) in jct_xy.items():
                        d = math.sqrt((bx - jx)**2 + (by - jy)**2)
                        if d < best_dist:
                            best_dist = d
                            best_jct = jid
                            best_zone = zr
                    in_zone = 1 if best_dist <= best_zone else 0
                else:
                    best_jct = -1
                    best_dist = -1.0
                    best_zone = 0.0
                    in_zone = 0
                rows.append((
                    f"{time:.1f}", veh_id,
                    f"{bx:.1f}", f"{by:.1f}",
                    best_jct, f"{best_dist:.0f}",
                    in_zone, f"{best_zone:.0f}", "track",
                ))
    except Exception:
        pass

    # Supplement/fallback: some models do not expose PT-line followers reliably,
    # or may omit injected buses from PT APIs. Scan live section vehicles by
    # inferred bus type to capture missing buses.
    if BUS_TRACK_SUPPLEMENT_NETWORK_SCAN or not rows:
        try:
            _bus_type_pos = int(getattr(stats, '_bus_pos', -1) or -1)
        except Exception:
            _bus_type_pos = -1
        if _bus_type_pos > 0:
            _scan_secs = set()
            try:
                _scan_secs.update(int(_s) for _s in _network_stats_section_ids() if int(_s) > 0)
            except Exception:
                pass
            if not _scan_secs:
                for _ctrl in controllers.values():
                    for _s in getattr(_ctrl, 'incoming_sections', []):
                        if _s and _s > 0:
                            _scan_secs.add(int(_s))
                try:
                    for _d in getattr(stats, '_inter', {}).values():
                        for _s in _d.get('all_sections', []):
                            if _s and _s > 0:
                                _scan_secs.add(int(_s))
                except Exception:
                    pass

            seen_fallback = set()
            _supplement_only_missing = bool(rows)
            for _sec in _scan_secs:
                try:
                    _n = max(int(AKIVehStateGetNbVehiclesSection(_sec, True)), 0)
                except Exception:
                    _n = 0
                for _i in range(_n):
                    try:
                        _inf = AKIVehStateGetVehicleInfSection(_sec, _i)
                        _vid = int(getattr(_inf, 'idVeh', -1) or -1)
                        _typ = int(getattr(_inf, 'type', -1) or -1)
                        if _vid <= 0 or _typ != _bus_type_pos or _vid in seen_fallback:
                            continue
                        if _supplement_only_missing and _vid in _bus_xy:
                            continue
                        _bx = float(getattr(_inf, 'xCurrentPos', 0.0) or 0.0)
                        _by = float(getattr(_inf, 'yCurrentPos', 0.0) or 0.0)
                        if _bx == 0.0 and _by == 0.0:
                            continue
                        seen_fallback.add(_vid)
                        active_veh_ids.add(_vid)
                        _bus_xy[_vid] = (_bx, _by)

                        if jct_xy:
                            _best_j = -1
                            _best_d = 1e9
                            _best_z = 0.0
                            for _jid, (_jx, _jy, _zr) in jct_xy.items():
                                _d = math.sqrt((_bx - _jx)**2 + (_by - _jy)**2)
                                if _d < _best_d:
                                    _best_d = _d
                                    _best_j = _jid
                                    _best_z = _zr
                                # Also update zone-presence for supplement buses
                                # so detect_bus Tier 0 can use them
                                if _d <= _zr:
                                    _tracking_zone_presence.setdefault(_jid, {})[_vid] = (_bx, _by, float(getattr(_inf, 'CurrentSpeed', 40.0) or 40.0))
                            _inz = 1 if _best_d <= _best_z else 0
                        else:
                            _best_j = -1
                            _best_d = -1.0
                            _best_z = 0.0
                            _inz = 0

                        rows.append((
                            f"{time:.1f}", _vid,
                            f"{_bx:.1f}", f"{_by:.1f}",
                            _best_j, f"{_best_d:.0f}",
                            _inz, f"{_best_z:.0f}", "track",
                        ))
                    except Exception:
                        continue

    # Update live corridor bus count for queue snapshot
    _active_corridor_bus_count = len(active_veh_ids)

    # Clean up zone state for vehicles no longer on the network
    stale_keys = [k for k in _bus_zone_state if k[0] not in active_veh_ids]
    for k in stale_keys:
        del _bus_zone_state[k]
        # Also clear zone entry times for stale vehicles
        if k in _bus_zone_entry_time:
            del _bus_zone_entry_time[k]

    # Add lifecycle events: first time seen in network and nearest-junction change
    if rows:
        for _r in list(rows):
            _vid = int(_r[1])
            _jid = int(_r[4])
            _bx = _r[2]
            _by = _r[3]
            _dist = _r[5]
            _inz = _r[6]
            _zr = _r[7]
            if _vid not in _bus_seen_ids:
                _bus_seen_ids.add(_vid)
                rows.append((
                    f"{time:.1f}", _vid, _bx, _by,
                    _jid, _dist, _inz, _zr, "enter_system",
                ))
            _prev_j = _bus_last_nearest_jct.get(_vid)
            if _prev_j is not None and _jid != _prev_j and _jid > 0:
                rows.append((
                    f"{time:.1f}", _vid, _bx, _by,
                    _jid, _dist, _inz, _zr, "nearest_jct_change",
                ))
            _bus_last_nearest_jct[_vid] = _jid

    if not rows:
        return
    try:
        write_header = not _bus_track_header_written
        with open(_BUS_TRACKING_CSV, "a", newline="", encoding="utf-8") as f:
            w = csv.writer(f)
            if write_header:
                w.writerow(["sim_time_s", "veh_id", "x", "y",
                            "nearest_jct", "dist_m", "in_zone", "zone_radius_m",
                            "event"])
                _bus_track_header_written = True
            w.writerows(rows)
    except Exception as _e:
        log_to_file(f"[BUS_TRACK] CSV write failed: {_e}")

    # Write a separate 1-second presence snapshot for diagnostics.
    # This keeps event-style detection_points compact while giving
    # continuous per-bus/per-junction state for strategy inspection.
    try:
        if jct_xy and _bus_xy:
            _presence_rows = []
            for _vid, (_bx, _by) in _bus_xy.items():
                _line_id = int(_bus_line_id.get(_vid, -1) or -1)
                _seen_jcts = set()

                _best_j = -1
                _best_d = 1e12
                _best_z = 0.0
                for _jid, (_jx, _jy, _zr) in jct_xy.items():
                    _d = math.sqrt((_bx - _jx) ** 2 + (_by - _jy) ** 2)
                    if _d < _best_d:
                        _best_d = _d
                        _best_j = int(_jid)
                        _best_z = float(_zr)

                if _best_j > 0:
                    _presence_rows.append((
                        f"{time:.1f}", int(_vid), _line_id, _best_j,
                        f"{_best_d:.1f}", f"{_best_z:.1f}",
                        1 if _best_d <= _best_z else 0,
                        "nearest",
                        f"{_bx:.1f}", f"{_by:.1f}",
                    ))
                    _seen_jcts.add(_best_j)

                for _jid, _veh_map in _tracking_zone_presence.items():
                    if int(_jid) in _seen_jcts or _vid not in _veh_map:
                        continue
                    _jxy = jct_xy.get(_jid)
                    if not _jxy:
                        continue
                    _jx, _jy, _zr = _jxy
                    _d = math.sqrt((_bx - _jx) ** 2 + (_by - _jy) ** 2)
                    _presence_rows.append((
                        f"{time:.1f}", int(_vid), _line_id, int(_jid),
                        f"{_d:.1f}", f"{float(_zr):.1f}",
                        1,
                        "in_zone",
                        f"{_bx:.1f}", f"{_by:.1f}",
                    ))

            if _presence_rows:
                _hdr = not _presence_snapshot_header_written
                with open(_PRESENCE_SNAPSHOT_CSV, "a", newline="", encoding="utf-8") as _pf:
                    _pw = csv.writer(_pf)
                    if _hdr:
                        _pw.writerow([
                            "sim_time_s", "veh_id", "line_id", "junction_id",
                            "dist_m", "zone_radius_m", "in_zone", "scope", "x", "y",
                        ])
                        _presence_snapshot_header_written = True
                    _pw.writerows(_presence_rows)
    except Exception as _pe:
        log_to_file(f"[PRESENCE_SNAPSHOT] CSV write failed: {_pe}")


def _write_queue_snapshot(time: float):
    """
    Write per-intersection queue-length snapshot every _QUEUE_SNAP_INTERVAL_S.

    Columns:
        sim_time_s    — simulation time (s)
        junction_id   — intersection ID
        buses_in_zone — distinct buses in detection zone whose PT line serves this junction
        queue_main    — total vehicles on main (bus) approach sections
        queue_side    — total vehicles on side-street sections
        queue_total   — queue_main + queue_side
        queue_slow_main  — slow vehicles (<5 km/h) on main approach sections
        queue_slow_side  — slow vehicles (<5 km/h) on side-street sections
        queue_slow_total — queue_slow_main + queue_slow_side
        tsp_state     — current TSP state string ('IDLE' / 'GE' / 'INS' / 'NORMAL')
        current_phase — current Aimsun phase number at this junction
        delay_total_s — cumulative pax-seconds of total delay at this junction (running total)
        delay_bus_s   — cumulative pax-seconds of bus delay at this junction (running total)
        delay_car_s   — cumulative pax-seconds of car delay at this junction (running total)

    Written to: logs/queue_snapshot_<EXPERIMENT>_<timestamp>.csv
    """
    global _queue_snap_last_t, _queue_snap_header_written

    if time - _queue_snap_last_t < _QUEUE_SNAP_INTERVAL_S:
        return
    _queue_snap_last_t = time

    rows = []
    for iid, ctrl in controllers.items():
        try:
            # Count buses in detection zone, filtered to buses whose PT line serves this junction.
            # Raw zone presence includes ALL PT vehicles within radius — buses on parallel/cross
            # routes inflate the count.  Filter: include bus if its line's route contains iid.
            # Fallback for unknown routes: use _bus_observed_jcts (actual corridor route observed
            # during this simulation).  Only include if the bus has been observed near corridor
            # junctions — prevents cross-route buses from inflating the count.
            raw_zone = _tracking_zone_presence.get(iid, {})
            buses_in_zone = 0
            for _vid in raw_zone:
                _line_id = _bus_line_id.get(_vid, -1)
                _route_jcts = _pt_line_jct_route.get(_line_id) if _line_id > 0 else None
                if _route_jcts is not None:
                    if iid in _route_jcts:
                        buses_in_zone += 1
                else:
                    # Route unknown — fall back to observed junction sequence.
                    # Include only if this bus has been observed specifically entering
                    # THIS junction's zone (recorded in _bus_observed_jcts during the
                    # nearest-zone zone_enter pass).  This prevents cross-route buses
                    # from being counted just because they happen to be physically nearby.
                    _obs = _bus_observed_jcts.get(_vid)
                    if _obs and iid in _obs:
                        buses_in_zone += 1

            # Snapshot vehicles per section (all vehicles, not only slow/queued).
            # Priority: use the controller's topology-resolved approach sections
            # (full approach lanes) rather than stats._inter['main_sections'] which
            # is derived from detector loop positions (often a single short section
            # near the stop line that only captures 1-2 vehicles).
            q_main = 0
            q_side = 0
            q_slow_main = 0
            q_slow_side = 0
            main_secs: set = set(getattr(ctrl, 'incoming_sections', []) or [])
            side_secs: set = set(getattr(ctrl, '_cached_side_sections', None) or [])
            if not main_secs or not side_secs:
                try:
                    _inter_d = stats._inter.get(iid, {})
                    if not main_secs:
                        _sm = set(_inter_d.get('main_sections', []))
                        if _sm:
                            main_secs = _sm
                    if not side_secs:
                        _ss = set(_inter_d.get('side_sections', []))
                        if _ss:
                            side_secs = _ss
                except Exception:
                    pass
            all_secs = main_secs | side_secs

            for sec in all_secs:
                if not sec or sec <= 0:
                    continue
                try:
                    n = max(int(AKIVehStateGetNbVehiclesSection(sec, False)), 0)
                    if sec in main_secs:
                        q_main += n
                    else:
                        q_side += n

                    # Slow-vehicle queue snapshot kept alongside all-vehicle count
                    # so the dashboard can compare occupancy vs standing queue.
                    for vi in range(n):
                        vinf = AKIVehStateGetVehicleInfSection(sec, vi)
                        spd = float(getattr(vinf, 'CurrentSpeed', 0.0) or 0.0)
                        if spd < 5.0:
                            if sec in main_secs:
                                q_slow_main += 1
                            else:
                                q_slow_side += 1
                except Exception:
                    continue

            # TSP state string
            # Prefer explicit local phase-based action flag when active
            # so Harmony GE/INS does not appear as IDLE in diagnostics.
            tsp_state = "NORMAL"
            _flag = int(getattr(ctrl, 'flag', 0) or 0)
            _flag_state = {1: 'GE', 2: 'INS'}.get(_flag, None)
            gb = getattr(ctrl, 'gb', None)
            if gb is not None:
                ts = int(getattr(gb, 'tsp_strategy', 0) or 0)
                if ts in (1, 2, 3):
                    tsp_state = {1: 'GE', 2: 'INS_COMPAT', 3: 'INS_FORCED'}[ts]
                elif _flag_state is not None:
                    tsp_state = _flag_state
                elif getattr(ctrl, '_harmony_prearm', None) is not None:
                    tsp_state = 'PREARM'
                else:
                    tsp_state = 'IDLE'
            elif _flag_state is not None:
                tsp_state = _flag_state

            try:
                cur_phase = ECIGetCurrentPhase(getattr(ctrl, 'node_id', -1))
            except Exception:
                cur_phase = -1

            # Cumulative delay from stats (person-seconds, running total)
            delay_total_s = 0.0
            delay_bus_s   = 0.0
            delay_car_s   = 0.0
            try:
                _id = stats._inter.get(iid, {})
                delay_total_s = float(_id.get('delay_total', 0.0) or 0.0)
                delay_bus_s   = float(_id.get('delay_bus',   0.0) or 0.0)
                delay_car_s   = float(_id.get('delay_car',   0.0) or 0.0)
            except Exception:
                pass

            # ── Shockwave queue estimation ──────────────────────────────────
            # Strategy 1: snapshot physical vehicle count (q_main/q_side above)
            # Strategy 2: shockwave calc from approach flow + red duration
            sw_q_main    = float(q_main)
            sw_q_side    = float(q_side)
            sw_flow_main = 0.0
            sw_den_main  = 0.0
            sw_red_s     = 0.0
            sw_flow_side = 0.0
            sw_strat_main = "snapshot"
            sw_strat_side = "snapshot"
            try:
                _k_jam = float(getattr(ctrl, 'JamDensity', 200))
                _k_sat = float(getattr(ctrl, 'SaturationDensity', 35))
                _q_sat = float(getattr(ctrl, 'SaturationFlow', 1800))
                _upf = np.asarray(getattr(ctrl, 'UpFlowList', []), dtype=float)
                _upd = np.asarray(getattr(ctrl, 'UpDenList',  []), dtype=float)
                _rdt = np.asarray(getattr(ctrl, 'RedDurationList', []), dtype=float)
                # Cap red durations: uninitialised slots have RedStartTimeList=0
                # so red_dur = simulation_time (thousands of seconds).  Any slot
                # > 2× cycle time is stale/uninitialised and must be ignored.
                _max_red_cap = 2.0 * float(getattr(ctrl, 'config', {}).get('CycleTime', 135))
                if _rdt.size > 0:
                    _rdt = np.where(_rdt <= _max_red_cap, _rdt, 0.0)
                if _upf.size > 0 and _rdt.size > 0:
                    _flow_vals = _upf.ravel()
                    _den_vals  = _upd.ravel()
                    _red_vals  = _rdt.ravel()
                    # Only use slots where both flow AND a valid red duration exist
                    _pos_mask  = (_flow_vals > 0) & (_red_vals > 0)
                    if _pos_mask.any():
                        sw_flow_main = float(np.mean(_flow_vals[_pos_mask]))
                        sw_den_main  = float(np.mean(_den_vals[_pos_mask]))
                        sw_red_s     = float(np.max(_red_vals[_pos_mask]))
                        _k_diff  = max(_k_jam - sw_den_main, 1.0)
                        _w_back_kms = (sw_flow_main / 3600.0) / _k_diff
                        _sw_q = (_w_back_kms * sw_red_s) * _k_jam  # q_km * k_jam = n_veh
                        if _sw_q > sw_q_main:
                            sw_q_main    = _sw_q
                            sw_strat_main = "shockwave"
                _suf = np.asarray(getattr(ctrl, 'SideUpFlowList', []), dtype=float)
                if _suf.size > 0:
                    _side_pos = _suf[_suf > 0.0]
                    sw_flow_side = float(np.mean(_side_pos)) if _side_pos.size > 0 else 400.0
                    sw_strat_side = "SideUpFlow" if _side_pos.size > 0 else "default400"
                    if sw_red_s > 0 and sw_flow_side > 0:
                        _k_arr_s  = sw_flow_side * _k_sat / max(_q_sat, 1.0)
                        _k_diff_s = max(_k_jam - _k_arr_s, 1.0)
                        _sw_qs = (sw_flow_side / 3600.0 / _k_diff_s) * sw_red_s * _k_jam
                        if _sw_qs > sw_q_side:
                            sw_q_side  = _sw_qs
                            sw_strat_side = "shockwave"
            except Exception:
                pass

            rows.append((
                f"{time:.1f}", iid, buses_in_zone,
                q_main, q_side, q_main + q_side,
                q_slow_main, q_slow_side, q_slow_main + q_slow_side,
                tsp_state, cur_phase, _active_corridor_bus_count,
                f"{delay_total_s:.1f}", f"{delay_bus_s:.1f}", f"{delay_car_s:.1f}",
                f"{sw_q_main:.1f}", f"{sw_q_side:.1f}",
                f"{sw_flow_main:.0f}", f"{sw_den_main:.2f}", f"{sw_red_s:.1f}",
                f"{sw_flow_side:.0f}", sw_strat_main, sw_strat_side,
            ))
        except Exception:
            continue

    if not rows:
        return
    try:
        write_header = not _queue_snap_header_written
        with open(_QUEUE_SNAPSHOT_CSV, "a", newline="", encoding="utf-8") as f:
            w = csv.writer(f)
            if write_header:
                w.writerow([
                    "sim_time_s", "junction_id", "buses_in_zone",
                    "queue_main", "queue_side", "queue_total",
                    "queue_slow_main", "queue_slow_side", "queue_slow_total",
                    "tsp_state", "current_phase", "corridor_bus_count",
                    "delay_total_s", "delay_bus_s", "delay_car_s",
                    "sw_q_main", "sw_q_side",
                    "sw_flow_main", "sw_density_main", "sw_red_s",
                    "sw_flow_side", "sw_strat_main", "sw_strat_side",
                ])
                _queue_snap_header_written = True
            w.writerows(rows)
    except Exception as _e:
        log_to_file(f"[QUEUE_SNAP] write failed: {_e}")


def resolve_vehicle_type_positions():
    """
    Dynamically detect vehicle type internal positions.
    Works with Car, Truck, Bus or any custom naming.
    """
    car_pos = -1
    bus_pos = -1
    truck_pos = -1

    n_types = AKIVehGetNbVehTypes()

    for pos in range(1, n_types + 1):
        raw = AKIVehGetVehTypeName(pos)
        try:
            name = AKIConvertToAsciiString(raw, True).lower()
        except:
            name = str(raw).lower()
        '''
        _vprint(f"[VEH DETECT] pos={pos} name={name}")
        '''
        if "bus" in name:
            bus_pos = pos
        elif "truck" in name:
            truck_pos = pos
        elif "car" in name:
            car_pos = pos

    return car_pos, bus_pos, truck_pos

def log_to_file(message, force=False):
    """
    Write message to log file.  Only print to the Aimsun console when
    VERBOSE=True OR force=True (used for critical errors that must always show).
    """
    full_msg = f"{datetime.datetime.now().strftime('%H:%M:%S')} | {message}"
    if VERBOSE or force:
        AKIPrintString(full_msg)
    try:
        with open(LOG_FILE, "a", encoding="utf-8") as f:
            f.write(full_msg + "\n")
    except Exception as _log_err:
        AKIPrintString(f"[LOG] file write failed ({LOG_FILE}): {_log_err}")


def _preflight_model_db_health() -> bool:
    """
    Read-only integrity preflight for model companion SQLite files.

    Returns True if all checked files look healthy or preflight is disabled.
    Returns False when corruption is detected in strict mode.
    """
    if not ENABLE_MODEL_DB_PREFLIGHT:
        return True

    try:
        _base = os.path.dirname(os.path.abspath(__file__))
    except Exception:
        _base = os.getcwd()

    _all_sqlite = sorted(
        [p for p in glob.glob(os.path.join(_base, "*.sqlite")) if os.path.isfile(p)],
        key=os.path.getmtime,
        reverse=True,
    )

    if not _all_sqlite:
        log_to_file("[PREFLIGHT] No companion .sqlite files found; skipping DB check", force=True)
        return True

    # Choose the active companion DB instead of scanning every stale file in
    # the folder.  Scanning all *.sqlite can fail a valid recovered run when an
    # unrelated historical model DB is corrupted.
    _candidate_files = []
    _lock_stems = set()
    for _lk in glob.glob(os.path.join(_base, "*.ang.lck")) + glob.glob(os.path.join(_base, "*.sang.lck")):
        try:
            _lock_stems.add(os.path.splitext(os.path.splitext(os.path.basename(_lk))[0])[0])
        except Exception:
            pass
    if _lock_stems:
        for _st in sorted(_lock_stems):
            _p = os.path.join(_base, f"{_st}.sqlite")
            if os.path.isfile(_p):
                _candidate_files.append(_p)

    if not _candidate_files:
        _recover_sqlite = [p for p in _all_sqlite if "_RECOVER" in os.path.basename(p).upper()]
        if _recover_sqlite:
            _candidate_files = [_recover_sqlite[0]]
        else:
            _candidate_files = [_all_sqlite[0]]

    _chosen_names = ", ".join(os.path.basename(_p) for _p in _candidate_files)
    log_to_file(f"[PREFLIGHT] Checking active companion DB(s): {_chosen_names}", force=True)

    _bad = []
    for _p in _candidate_files:
        try:
            _conn = sqlite3.connect(f"file:{_p}?mode=ro", uri=True)
            try:
                _row = _conn.execute("PRAGMA quick_check(1)").fetchone()
            finally:
                _conn.close()
            _msg = str(_row[0]) if _row else "unknown"
            if _msg.lower() == "ok":
                log_to_file(f"[PREFLIGHT] DB OK: {os.path.basename(_p)}", force=True)
            else:
                _bad.append((_p, _msg))
        except Exception as _e:
            _bad.append((_p, f"check_failed: {_e}"))

    if _bad:
        for _p, _why in _bad:
            log_to_file(
                f"[PREFLIGHT] DB CORRUPT: {os.path.basename(_p)} :: {_why}",
                force=True,
            )
        if MODEL_DB_PREFLIGHT_STRICT:
            log_to_file(
                "[FATAL] Model DB preflight failed. Open a recovered .ang/.sang copy and rerun. "
                "Aborting AAPIInit to prevent running on corrupted storage.",
                force=True,
            )
            return False

    return True


def _plot_schedule_recovery():
    """
    Generate a schedule-recovery chart from _ge_events.

    Each row in _ge_events is (sim_time, intersection_id, ge_s, recovery_s).
    The chart shows:
      • Blue bars  — GE granted (seconds stolen from the cycle)
      • Green bars — recovery trimmed from subsequent phases
      • Red bars   — residual (GE - recovery, i.e. unrecovered drift)

    Saved as logs/schedule_recovery_<timestamp>.png
    """
    if not _ge_events:
        log_to_file("[SCHED] No GE events recorded — skipping recovery plot")
        return

    out_path = os.path.join(LOG_DIR,
                            f"schedule_recovery_{_CURRENT_EXPERIMENT}_{timestamp}.png")

    times    = [e[0] for e in _ge_events]
    ge_vals  = [e[2] for e in _ge_events]
    rec_vals = [e[3] for e in _ge_events]
    res_vals = [max(0.0, g - r) for g, r in zip(ge_vals, rec_vals)]
    iids     = [e[1] for e in _ge_events]

    x = list(range(len(_ge_events)))
    labels = [f"t={t:.0f}s\njct{iid}" for t, iid in zip(times, iids)]

    fig, axes = plt.subplots(2, 1, figsize=(max(8, len(x) * 0.6 + 2), 8))

    # Top panel: per-event bar chart
    ax = axes[0]
    w = 0.28
    ax.bar([xi - w for xi in x], ge_vals,  width=w, color='#29b6f6', label='GE granted (s)')
    ax.bar([xi      for xi in x], rec_vals, width=w, color='#00e676', label='Recovered (s)')
    ax.bar([xi + w for xi in x], res_vals,  width=w, color='#ff5252', label='Residual drift (s)')
    ax.set_xticks(x)
    ax.set_xticklabels(labels, fontsize=7, rotation=45, ha='right')
    ax.set_ylabel('seconds')
    ax.set_title(f'Schedule Recovery per GE Event — {_CURRENT_EXPERIMENT} ({CONTROL_MODE})')
    ax.legend(fontsize=8)
    ax.grid(axis='y', alpha=0.3)

    # Bottom panel: cumulative drift over time
    ax2 = axes[1]
    cum_drift = []
    running = 0.0
    for g, r in zip(ge_vals, rec_vals):
        running += max(0.0, g - r)
        cum_drift.append(running)
    ax2.plot(times, cum_drift, color='#ff5252', marker='o', markersize=4, linewidth=1.5,
             label='Cumulative unrecovered drift (s)')
    ax2.axhline(0, color='#00e676', linewidth=0.8, linestyle='--')
    ax2.set_xlabel('simulation time (s)')
    ax2.set_ylabel('cumulative seconds behind schedule')
    ax2.set_title('Cumulative Timing Drift Over Simulation')
    ax2.legend(fontsize=8)
    ax2.grid(alpha=0.3)

    plt.tight_layout()
    plt.savefig(out_path, dpi=120, bbox_inches='tight')
    plt.close(fig)
    log_to_file(f"[SCHED] Schedule recovery plot → {out_path} "
                f"({len(_ge_events)} GE events, "
                f"total_ge={sum(ge_vals):.1f}s "
                f"total_rec={sum(rec_vals):.1f}s "
                f"residual={sum(res_vals):.1f}s)")


def _write_run_summary():
    try:
        g = stats._global_kpis() if hasattr(stats, '_global_kpis') else {}
        with open(_RUN_SUMMARY_TXT, 'w', encoding='utf-8') as f:
            f.write('TSP RUN SUMMARY\n')
            f.write('=' * 80 + '\n')
            f.write(f'Timestamp: {datetime.datetime.now().isoformat()}\n')
            f.write(f'LOG_FILE: {LOG_FILE}\n')
            f.write(f'CONTROL_MODE: {CONTROL_MODE}\n')
            f.write(f'COORDINATED_TSP: {COORDINATED_TSP}\n')
            f.write(f'COORDINATION_ALGO: {COORDINATION_ALGO}\n')
            f.write(f'VERBose: {VERBOSE}\n')
            f.write('\n')
            f.write('[GLOBAL KPIS]\n')
            if g:
                for key, value in sorted(g.items()):
                    f.write(f'  {key}: {value}\n')
            else:
                f.write('  No global KPIs available\n')
            f.write('\n')
            f.write('[CONTROLLER STATUS]\n')
            for iid, ctrl in controllers.items():
                _gb = getattr(ctrl, 'gb', None)
                f.write(f'  Intersection {iid}: node_id={getattr(ctrl, "node_id", None)}')
                if _gb is not None:
                    f.write(
                        f' | bus_sg={getattr(_gb, "bus_sg", None)}'
                        f' | bus_request={getattr(_gb, "bus_request", None)}'
                        f' | external_control={getattr(_gb, "_external_control", None)}'
                        f' | bus_req_count={getattr(_gb, "_gb_bus_request_count", 0)}'
                        f' | activations={getattr(_gb, "_gb_bus_activation_count", 0)}'
                        f' | forced_terminations={getattr(_gb, "_gb_forced_termination_count", 0)}'
                        f' | phase_groups={len(getattr(_gb, "phase_groups", []))}'
                        f' | bus_phase={getattr(_gb, "_bus_aimsun_phase", None)}'
                    )
                f.write('\n')
            f.write('\n')
            f.write('[CORRIDOR SUMMARY]\n')
            if corridor_coordinators:
                for coord in corridor_coordinators:
                    f.write(f'  {coord.summary()}\n')
            else:
                f.write('  No corridor coordinators configured.\n')
    except Exception as e:
        log_to_file(f"[SUMMARY] run summary write failed: {e}", force=True)


def _write_algorithm_explanation_tex():  # noqa: C901
    """Write a multi-page TikZ flowchart document (one page per TSP strategy)."""
    # ------------------------------------------------------------------
    # Shared TikZ preamble
    # ------------------------------------------------------------------
    PREAMBLE = r'''\documentclass[a4paper,10pt]{article}
\usepackage[margin=15mm]{geometry}
\usepackage{tikz}
\usetikzlibrary{shapes.geometric,arrows.meta,positioning,fit,backgrounds,calc}
\usepackage{amsmath}
\usepackage{xcolor}

%% ── Node style palette ──────────────────────────────────────────────────────
\tikzstyle{start}   = [rounded rectangle, draw=black!70, fill=green!25,
                        minimum width=28mm, minimum height=8mm, align=center,
                        font=\small\bfseries]
\tikzstyle{stop}    = [rounded rectangle, draw=black!70, fill=red!25,
                        minimum width=28mm, minimum height=8mm, align=center,
                        font=\small\bfseries]
\tikzstyle{proc}    = [rectangle, draw=black!60, fill=blue!8,
                        minimum width=38mm, minimum height=9mm, align=center,
                        font=\small]
\tikzstyle{procB}   = [rectangle, draw=black!60, fill=blue!18,
                        minimum width=38mm, minimum height=9mm, align=center,
                        font=\small\bfseries]
\tikzstyle{dec}     = [diamond, aspect=2.2, draw=black!70, fill=orange!18,
                        minimum width=44mm, align=center, font=\small]
\tikzstyle{coord}   = [rectangle, draw=teal!70, fill=teal!10,
                        minimum width=38mm, minimum height=9mm, align=center,
                        font=\small\itshape]
\tikzstyle{result}  = [rectangle, rounded corners=3pt, draw=gray!60,
                        fill=gray!12, minimum width=34mm, minimum height=8mm,
                        align=center, font=\small]
\tikzstyle{arr}     = [-{Stealth[scale=1.1]}, thick, black!70]
\tikzstyle{yes}     = [draw=green!50!black, text=green!50!black]
\tikzstyle{no}      = [draw=red!60!black,   text=red!60!black]
\newcommand\YN[2]{\node[font=\tiny, #1] at (#2) {\textbf{#1}};}
\begin{document}
'''
    FOOTER = r'\end{document}' + '\n'

    # ------------------------------------------------------------------
    # Helper: wrap a page in a tikzpicture
    # ------------------------------------------------------------------
    def page(title: str, body: str, caption: str = "") -> str:
        cap = (r'\medskip{\footnotesize\textit{' + caption + r'}}') if caption else ""
        return (
            r'\newpage' + '\n' +
            r'\begin{center}{\large\bfseries ' + title + r'}\end{center}' + '\n' +
            r'\begin{tikzpicture}[node distance=9mm and 16mm, >=Stealth]' + '\n' +
            body + '\n' +
            r'\end{tikzpicture}' + '\n' +
            cap + '\n'
        )

    # ------------------------------------------------------------------
    # Page 1 — NORMAL (no TSP)
    # ------------------------------------------------------------------
    P_NORMAL = r'''
\node[start]  (start)                          {Simulation step};
\node[proc]   (plan)  [below=of start]         {Execute fixed signal plan\\(Aimsun timing tables)};
\node[proc]   (stats) [below=of plan]          {Collect section statistics\\(flow, density, speed)};
\node[stop]   (done)  [below=of stats]         {End of step};
\draw[arr] (start)--(plan);
\draw[arr] (plan) --(stats);
\draw[arr] (stats)--(done);
'''

    # ------------------------------------------------------------------
    # Page 2 — HARMONY_INDEP (local TSP, no coordination)
    # ------------------------------------------------------------------
    P_INDEP = r'''
\node[start]  (start)                          {Simulation step\\(check\_bus\_priority)};
\node[dec]    (det)   [below=of start]         {Bus detected\\on approach?};
\node[proc]   (eta)   [below=of det]           {Compute ETA to stop-line\\(Kalman position + speed)};
\node[dec]    (phase) [below=of eta]           {Current phase\\= Bus phase?};
\node[dec]    (nat)   [right=30mm of phase]    {Bus arrives on\\natural green?};
\node[result] (skip)  [right=22mm of nat]      {No action\\(natural green)};
\node[dec]    (geok)  [below=of phase]         {GE needed\\$\le$ MAX\_GE?};
\node[proc]   (ge)    [below=of geok]          {ECIChangeTimingPhase\\GE = min($\eta$+5,MAX\_GE)};
\node[dec]    (ins)   [right=30mm of geok]     {Bus misses\\natural bus phase?};
\node[proc]   (ins2)  [below=of ins]           {ECIChangeDirectPhase\\INS = min($\eta$+5,MAX\_INS)};
\node[stop]   (done)  [below=22mm of ge]       {Return / next step};
%% edges
\draw[arr] (start)--(det);
\draw[arr] (det)--node[right,font=\tiny\bfseries]{Yes}(eta);
\draw[arr] (det.east)--++(14mm,0)--++(0,-44mm)node[right,font=\tiny\bfseries]{No}
           --++(0,-4mm)--(done.north east);
\draw[arr] (eta)--(phase);
\draw[arr] (phase)--node[right,font=\tiny\bfseries]{Yes}(geok);
\draw[arr] (phase.east)--node[above,font=\tiny\bfseries]{No}(nat);
\draw[arr] (nat.east)--node[above,font=\tiny\bfseries]{Yes}(skip);
\draw[arr] (nat.south)--node[right,font=\tiny\bfseries]{No}(ins);
\draw[arr] (ins)--(ins2);
\draw[arr] (geok)--node[right,font=\tiny\bfseries]{Yes}(ge);
\draw[arr] (geok.east)--node[above,font=\tiny\bfseries]{No -- skip}++(18mm,0);
\draw[arr] (ge)--(done);
\draw[arr] (ins2.south)--++(0,-4mm)-|(done.east);
'''

    # ------------------------------------------------------------------
    # Page 3 — HARMONY_COORD overview (applies to all COORD sub-algos)
    # ------------------------------------------------------------------
    P_COORD_OVERVIEW = r'''
\node[start]   (det)                          {Bus detected at\\junction $j$};
\node[proc]    (kalman) [below=of det]        {Kalman update:\\position $\hat{x}$, speed $\hat{v}$};
\node[proc]    (pred)   [below=of kalman]     {Predict position continuously:\\$\hat{x}_{t+\Delta t}=\hat{x}_t+\hat{v}\Delta t$};
\node[coord]   (coord)  [below=of pred]       {CorridorCoordinator.\\notify\_bus\_at\_junction()};
\node[proc]    (eta_j)  [below=of coord]      {Compute ETAs to all\\downstream junctions $j+1\ldots n$};
\node[coord]   (prearm) [below=of eta_j]      {Set \_harmony\_prearm\\at each downstream IC};
\node[dec]     (fire)   [below=12mm of prearm]{$\eta_{\mathrm{from now}} \in$\\$[0, \eta_{\max}]$?};
\node[proc]    (tsp)    [below=of fire]       {Execute GE or INS\\(coord path)};
\node[proc]    (offset) [below=of tsp]        {Log GREEN\_GRANT + offset\\to green\_offsets\_*.csv};
\node[stop]    (done)   [below=of offset]     {Propagate to next\\junction};
%% right branch — hold
\node[result]  (hold)   [right=28mm of fire]  {Hold prearm\\(check next step)};
%% edges
\draw[arr] (det)--(kalman);
\draw[arr] (kalman)--(pred);
\draw[arr] (pred)--(coord);
\draw[arr] (coord)--(eta_j);
\draw[arr] (eta_j)--(prearm);
\draw[arr] (prearm)--(fire);
\draw[arr] (fire)--node[right,font=\tiny\bfseries]{Yes}(tsp);
\draw[arr] (fire.east)--node[above,font=\tiny\bfseries]{No}(hold);
\draw[arr] (tsp)--(offset);
\draw[arr] (offset)--(done);
'''

    # ------------------------------------------------------------------
    # Page 4 — KALMAN detail
    # ------------------------------------------------------------------
    P_KALMAN = r'''
\node[start]  (obs)                           {New bus position $z_t$\\from section detector};
\node[proc]   (pred)  [below=of obs]          {Kalman predict:\\$\hat{x}^-_{t}=F\hat{x}_{t-1}$\\$P^-_t=FP_{t-1}F^\top+Q$};
\node[proc]   (upd)   [below=of pred]         {Kalman update:\\$K=P^-H^\top(HP^-H^\top+R)^{-1}$\\$\hat{x}_t=\hat{x}^-_t+K(z_t-H\hat{x}^-_t)$};
\node[proc]   (eta_k) [below=of upd]          {ETA to target:\\$\eta=(\tilde{x}_{\rm target}-\hat{x}_t)/\hat{v}_t$};
\node[dec]    (sigma) [below=of eta_k]        {$\sigma(\eta)\le$\\$\max(60,\;0.5\,\eta)$\,s?};
\node[proc]   (prearm)[below=of sigma]        {Issue pre-arm\\with $\eta$ to downstream IC};
\node[result] (skip)  [right=28mm of sigma]   {Uncertainty too high\\--- skip pre-arm};
%% Continuous advance (runs every step)
\node[coord]  (adv)   [right=30mm of pred]    {step(): advance all\\trackers by $\Delta t$\\(even without detection)};
\draw[arr] (obs)--(pred);
\draw[arr] (pred)--(upd);
\draw[arr] (upd)--(eta_k);
\draw[arr] (eta_k)--(sigma);
\draw[arr] (sigma)--node[right,font=\tiny\bfseries]{Yes}(prearm);
\draw[arr] (sigma.east)--node[above,font=\tiny\bfseries]{No}(skip);
\draw[arr] (pred.east)--++(4mm,0)--(adv.west);
'''

    # ------------------------------------------------------------------
    # Page 5 — SHOCKWAVE ETA correction
    # ------------------------------------------------------------------
    P_SHOCKWAVE = r'''
\node[proc]   (eta0)                          {Kalman ETA = $\eta_0$};
\node[proc]   (q)     [below=of eta0]         {Read upstream queue $Q_u$\\and flow $q_{\rm up}$ at junction $j$};
\node[proc]   (sw1)   [below=of q]            {Shockwave 1 (front of queue):\\$w_1 = Q_{\rm SAT}\cdot(K_{\rm SAT}-K_u)^{-1}$};
\node[proc]   (sw2)   [below=of sw1]          {Shockwave 2 (queue discharge):\\$w_2 = Q_{\rm SAT}\cdot(K_{\rm SAT}-K_{\rm JAM})^{-1}$};
\node[proc]   (tcl)   [below=of sw2]          {Queue clearance time:\\$t_{\rm clear}=Q_u / (Q_{\rm SAT}-q_{\rm up})$};
\node[dec]    (comp)  [below=of tcl]          {$\eta_0 < t_{\rm clear}$?};
\node[proc]   (adj)   [below=of comp]         {$\eta_{\rm adj}=\eta_0+t_{\rm clear}-\eta_0$\\(bus must wait for clearance)};
\node[result] (pass)  [right=28mm of comp]    {$\eta_{\rm adj}=\eta_0$\\(bus clears queue)};
\node[proc]   (pre)   [below=of adj]          {Issue pre-arm with $\eta_{\rm adj}$};
\draw[arr] (eta0)--(q);
\draw[arr] (q)--(sw1);
\draw[arr] (sw1)--(sw2);
\draw[arr] (sw2)--(tcl);
\draw[arr] (tcl)--(comp);
\draw[arr] (comp)--node[right,font=\tiny\bfseries]{Yes}(adj);
\draw[arr] (comp.east)--node[above,font=\tiny\bfseries]{No}(pass);
\draw[arr] (adj)--(pre);
'''

    # ------------------------------------------------------------------
    # Page 6 — ADAPTIVE lead time
    # ------------------------------------------------------------------
    P_ADAPTIVE = r'''
\node[proc]   (eta0)                          {Kalman ETA = $\eta_0$};
\node[proc]   (shw)   [below=of eta0]         {Apply SHOCKWAVE correction\\$\eta_{\rm sw}$};
\node[proc]   (adp)   [below=of shw]          {Adaptive lead time:\\$L=\min\!\bigl(\max(L_{\min},\;\eta_{\rm sw}\cdot\alpha),\;L_{\max}\bigr)$\\$\alpha=$ congestion factor from queue model};
\node[proc]   (parm)  [below=of adp]          {Pre-arm issued at\\$T_{\rm issue}=T_{\rm now}+\eta_{\rm sw}-L$};
\node[dec]    (rdy)   [below=of parm]         {$T_{\rm now}\ge T_{\rm issue}$?};
\node[proc]   (fire)  [below=of rdy]          {Fire TSP action\\(GE or INS)};
\node[result] (wait)  [right=28mm of rdy]     {Wait — re-evaluate\\next step (ETA refresh)};
\draw[arr] (eta0)--(shw);
\draw[arr] (shw)--(adp);
\draw[arr] (adp)--(parm);
\draw[arr] (parm)--(rdy);
\draw[arr] (rdy)--node[right,font=\tiny\bfseries]{Yes}(fire);
\draw[arr] (rdy.east)--node[above,font=\tiny\bfseries]{No}(wait);
'''

    # ------------------------------------------------------------------
    # Page 7 — OBJECTIVE function
    # ------------------------------------------------------------------
    P_OBJECTIVE = r'''
\node[proc]   (eta0)                          {Kalman ETA = $\eta_0$,\\shockwave correction applied};
\node[proc]   (cands)[below=of eta0]          {Enumerate candidate lead times:\\$L \in \{L_{\min}, \ldots, L_{\max}\}$ (1\,s steps)};
\node[proc]   (obj)  [below=of cands]         {For each $L$, evaluate:\\$J(L)=\alpha\cdot B_{\rm saved}-\beta\cdot C_{\rm displaced}$\\$B$=bus persons, $C$=car persons};
\node[proc]   (best) [below=of obj]           {Select $L^*=\arg\max J(L)$};
\node[dec]    (rdy)  [below=of best]          {$T_{\rm now}\ge T_{\rm issue}(L^*)$?};
\node[proc]   (fire) [below=of rdy]           {Fire TSP action\\(GE or INS) at $L^*$};
\node[result] (wait) [right=28mm of rdy]      {Hold --- re-evaluate\\next step};
\draw[arr] (eta0)--(cands);
\draw[arr] (cands)--(obj);
\draw[arr] (obj)--(best);
\draw[arr] (best)--(rdy);
\draw[arr] (rdy)--node[right,font=\tiny\bfseries]{Yes}(fire);
\draw[arr] (rdy.east)--node[above,font=\tiny\bfseries]{No}(wait);
'''

    # ------------------------------------------------------------------
    # Page 8 — What coordination adds (comparison)
    # ------------------------------------------------------------------
    P_COMPARISON = r'''
%% Independent column
\node[procB]  (ind_det)                       {Independent TSP:\\bus detected at $j$};
\node[proc]   (ind_eta) [below=of ind_det]    {Local ETA computed\\(single junction)};
\node[proc]   (ind_act) [below=of ind_eta]    {GE / INS fired locally\\if bus in window};
\node[result] (ind_r)   [below=of ind_act]    {Downstream junctions\\unaware of bus};

%% Coordinated column
\node[procB]  (co_det)  [right=48mm of ind_det]{Coordinated TSP:\\bus detected at $j$};
\node[coord]  (co_kal)  [below=of co_det]     {Kalman tracker update\\(continuous prediction)};
\node[coord]  (co_cor)  [below=of co_kal]     {CorridorCoordinator:\\ETAs to $j+1\ldots n$};
\node[coord]  (co_pre)  [below=of co_cor]     {Pre-arms issued\\at downstream ICs};
\node[proc]   (co_act)  [below=of co_pre]     {GE / INS fired at\\each junction on arrival};
\node[result] (co_r)    [below=of co_act]     {Green wave propagates\\through corridor};

%% divider
\draw[dashed, gray!50] ($(ind_det.north east)!0.5!(co_det.north west)$)
  -- ($(ind_r.south east)!0.5!(co_r.south west)$);

%% arrows independent
\draw[arr] (ind_det)--(ind_eta);
\draw[arr] (ind_eta)--(ind_act);
\draw[arr] (ind_act)--(ind_r);

%% arrows coordinated
\draw[arr] (co_det)--(co_kal);
\draw[arr] (co_kal)--(co_cor);
\draw[arr] (co_cor)--(co_pre);
\draw[arr] (co_pre)--(co_act);
\draw[arr] (co_act)--(co_r);
'''

    # ------------------------------------------------------------------
    # Assemble document
    # ------------------------------------------------------------------
    body = (
        PREAMBLE
        + r'\begin{center}{\LARGE\bfseries Logan Road Corridor --- TSP Strategy Flowcharts}'
          r'\\\medskip{\normalsize Generated by intersection\_controller.py'
          r' \texttt{\_write\_algorithm\_explanation\_tex()}}\end{center}' + '\n'
        + r'\tableofcontents' + '\n'
        + r'\addcontentsline{toc}{section}{NORMAL (no TSP)}'
        + page(r'Strategy: NORMAL (no TSP)', P_NORMAL,
               r'Fixed Aimsun signal plans run without intervention.')
        + r'\addcontentsline{toc}{section}{HARMONY\_INDEP (local TSP)}'
        + page(r'Strategy: HARMONY\_INDEP (local TSP only)', P_INDEP,
               r'Each intersection detects buses and acts locally. '
               r'No downstream coordination.')
        + r'\addcontentsline{toc}{section}{HARMONY\_COORD (overview)}'
        + page(r'Strategy: HARMONY\_COORD --- coordination overview', P_COORD_OVERVIEW,
               r'Applies to all COORD sub-algorithms (KALMAN / SHOCKWAVE / ADAPTIVE / OBJECTIVE). '
               r'The CorridorCoordinator pre-arms downstream intersections when a bus is detected.')
        + r'\addcontentsline{toc}{section}{KALMAN ETA detail}'
        + page(r'KALMAN --- ETA estimation detail', P_KALMAN,
               r'1-D constant-velocity Kalman filter. '
               r'$F=[1,\Delta t; 0,1]$, $Q=\mathrm{diag}(3,0.5)$, $R=900\,\mathrm{m}^2$. '
               r'Sigma gate: $\sigma \le \max(60, 0.5\,\eta)$ seconds.')
        + r'\addcontentsline{toc}{section}{SHOCKWAVE ETA correction}'
        + page(r'SHOCKWAVE --- queue-clearance ETA correction', P_SHOCKWAVE,
               r'LWR triangular model: $K_{\rm JAM}=150$, $K_{\rm SAT}=45$, '
               r'$Q_{\rm SAT}=1800$\,veh/h. Added on top of KALMAN ETA.')
        + r'\addcontentsline{toc}{section}{ADAPTIVE lead time}'
        + page(r'ADAPTIVE --- dynamic lead time', P_ADAPTIVE,
               r'Lead time $L$ scales with current queue density. '
               r'Combines shockwave correction with a congestion scaling factor $\alpha$.')
        + r'\addcontentsline{toc}{section}{OBJECTIVE function maximisation}'
        + page(r'OBJECTIVE --- person-level benefit maximisation', P_OBJECTIVE,
               r'$J = \alpha B_{\rm saved} - \beta C_{\rm displaced}$. '
               r'Weights: $\alpha=$\texttt{COORD\_OBJ\_ALPHA}, '
               r'$\beta=$\texttt{COORD\_OBJ\_BETA}.')
        + r'\addcontentsline{toc}{section}{Coordination vs.\ independent comparison}'
        + page(r'What coordination adds (independent vs.\ coordinated)', P_COMPARISON,
               r'Left: independent TSP --- each junction acts alone. '
               r'Right: coordinated TSP --- a single bus detection pre-arms the entire corridor.')
        + r'\addcontentsline{toc}{section}{t\_poz: Time to Point of Zero}'
        + page(r'$t_{\rm poz}$: Time to Point of Zero (queue)', r'''
\node[proc]  (det)                           {Bus detected on approach:\\Kalman position $\hat{x}$, speed $\hat{v}$};
\node[proc]  (eta) [below=of det]            {ETA to stop-line:\\$\eta = d_{\rm poz} / \hat{v}$\quad (distance / speed)};
\node[proc]  (act) [below=of eta]            {TSP action chosen (GE/INS/NO\_ACTION)\\Bus-phase delay after action: $d_{\rm act}$};
\node[proc]  (est) [below=of act]            {\textbf{Estimated} $t_{\rm poz}$:\\$\hat{t}_{\rm poz} = T_{\rm now} + \eta + d_{\rm act}$};
\node[proc]  (meas)[below=of est]            {\textbf{Measured} $t_{\rm poz}$ (when bus exits):\\$t_{\rm poz} = T_{\rm exit} - T_{\rm checkin}$};
\node[proc]  (tt)  [below=of meas]           {Travel-time reward term:\\$\Delta\mathrm{TT} = \bar{t}_{\rm poz}^{\rm no\text{-}act} - t_{\rm poz}^{\rm act}$\quad (positive = improvement)};
\draw[arr] (det)--(eta);
\draw[arr] (eta)--(act);
\draw[arr] (act)--(est);
\draw[arr] (est)--(meas);
\draw[arr] (meas)--(tt);
''', r'$t_{\rm poz}$ = time for the bus to travel from the detection point '
     r'to the far end of the stop-line zone (Point of Zero queue). '
     r'Estimated each cycle; measured empirically when the bus exits the POZ sensor.')
        + r'\addcontentsline{toc}{section}{DCTSP reward modes (MARL / INV\_DELAY / V2X / SELFORG)}'
        + page(r'DCTSP reward modes', r'''
\node[procB] (gr)                            {GLOBAL\_REWARD\_MODE};
\node[proc]  (marl) [below=14mm of gr]       {\textbf{MARL} (default):\\$R = w_h\,\Delta\sigma + (1-w_h)\,\Delta c_{\rm cpd}$\\$w_h=0.6$, $\Delta\sigma=\sigma_{\rm in}-\sigma_{\rm out}$};
\node[proc]  (inv)  [right=30mm of marl]     {\textbf{INV\_DELAY}:\\$R = 1/(1+\delta_{\rm bus}) - 1/(1+\delta_{\rm car})$\\normalised inverse delay};
\node[proc]  (v2x)  [right=30mm of inv]      {\textbf{V2X}:\\$R = R_{\rm bus} - R_{\rm car}$\\V2X occupancy-weighted};
\node[proc]  (so)   [below=18mm of marl]     {\textbf{SELFORG} (override):\\SE rule: $\mathrm{dur} = \delta_{\rm eff} \times f_{\rm SE}$\\clipped to $[SE_{\min}, SE_{\max}]$\\applied when $\delta_{\rm eff}\ge\delta_{\min}$ AND ratio$\le$FACTOR};
\draw[arr] (gr.south)--++(0,-6mm)--++(0,0)-|(marl.north);
\draw[arr] (gr.south)--++(0,-6mm)-|(inv.north);
\draw[arr] (gr.south)--++(0,-6mm)-|(v2x.north);
\draw[arr] (marl.south)--++(0,-6mm)--(so.north);
''', r'All modes share the same 7-action evaluation loop '
     r'(NO\_ACTION + GE\{5,10,15\} + INS\{10,15,20\}). '
     r'SELFORG overrides the greedy-best with the deterministic SE rule from '
     r'Cesme \& Furth (2014) \S4. ZIG replaces the discrete loop entirely.')
        + r'\addcontentsline{toc}{section}{DCTSP Q-table (RL)}'
        + page(r'DCTSP Q-table (reinforcement learning)', r'''
\node[proc]  (state)                         {State discretisation:\\$s = (\lfloor\sigma_{\rm in}/10\rfloor,\;\lfloor\eta/5\rfloor,\;\text{phase})$};
\node[proc]  (eps)   [below=of state]        {$\varepsilon$-greedy selection:\\with prob.\ $\varepsilon$: random action\\else: $a^* = \arg\max_a Q(s,a)$};
\node[proc]  (exec)  [below=of eps]          {Execute action, observe reward $r$};
\node[proc]  (td)    [below=of exec]         {TD($\lambda$) update (pending until bus exits POZ):\\$Q(s,a) \leftarrow Q(s,a) + \alpha\bigl[r + \gamma\max_{a'}Q(s',a') - Q(s,a)\bigr]$};
\node[proc]  (save)  [below=of td]           {Q-table persists across replications\\of same experiment; reset on experiment change};
\draw[arr] (state)--(eps);
\draw[arr] (eps)--(exec);
\draw[arr] (exec)--(td);
\draw[arr] (td)--(save);
''', r'Action space: 7 candidates (0=NO\_ACTION, 1--3=GE\,5/10/15\,s, '
     r'4--6=INS\,10/15/20\,s). '
     r'State tuple discretised to $\approx$2\,s$\times$5\,s$\times$N\_phases bins. '
     r'$\varepsilon$ decays from 0.3 to 0.05 over 500 updates.')
        + r'\addcontentsline{toc}{section}{DCTSP-ZIG shockwave-optimal selection}'
        + page(r'DCTSP-ZIG (Zero-Interference-Grant)', r'''
\node[start]  (entry)                        {Bus detected; NO\_ACTION delay $\delta_0$\\remaining red $r_{\rm rem}$, $\sigma_{\rm in}$};
\node[proc]   (sw)    [below=of entry]       {LWR shockwave optimal duration:\\$w_b=q_{\rm arr}/(k_{\rm jam}-k_{\rm arr})$\\$N_q=w_b\,T_{\rm red}\,k_{\rm jam}$\\$t_{\rm sw}=N_q/(q_{\rm sat}-q_{\rm arr})$\quad clipped to $[t_{\min},t_{\max}]$};
\node[proc]   (cands) [below=of sw]          {4 actions evaluated:\\GE: $t_{\rm ge}=\text{miss\_by}+t_{\rm sw}$\\INS\_POST: overhead$=r_{\rm rem}+t_{\rm ig}$\\INS\_PRETERM: overhead$=t_{\rm ig}=3$\,s (cut current phase)\\NO\_ACTION: baseline};
\node[dec]    (eff)   [below=of cands]       {$\delta_{\rm eff}=\max(0,\delta_0-\Delta_{\rm ov})\ge\delta_{\min}$?};
\node[dec]    (sat)   [below=of eff]         {side\_ratio\\$\le$ZIG\_BALANCE\_FACTOR?};
\node[proc]   (best)  [below=of sat]         {Apply greedy-best action\\(GE / INS\_POST / INS\_PRETERM)};
\node[result] (noact) [right=30mm of sat]    {NO\_ACTION\\(saturation avoidance)};
\node[result] (skip)  [right=30mm of eff]    {Keep greedy-best\\(delay too small)};
\draw[arr] (entry)--(sw);
\draw[arr] (sw)--(cands);
\draw[arr] (cands)--(eff);
\draw[arr] (eff)--node[right,font=\tiny\bfseries]{Yes}(sat);
\draw[arr] (eff.east)--node[above,font=\tiny\bfseries]{No}(skip);
\draw[arr] (sat)--node[right,font=\tiny\bfseries]{Yes$\le$}(best);
\draw[arr] (sat.east)--node[above,font=\tiny\bfseries]{No$>$}(noact);
''', r'$t_{\rm ig}=3$\,s intergreen transition overhead. '
     r'$\Delta_{\rm ov}=$ZIG\_PHASE\_OVERLAP\_S (phase-overlap correction, IEEE ICARCE 2023). '
     r'INS\_POST relies on natural sequence; INS\_PRETERM forces immediate phase switch.')
        + FOOTER
    )

    try:
        with open(_ALGORITHM_EXPLANATION_TEX, 'w', encoding='utf-8') as f:
            f.write(body)
        log_to_file(
            f"[SUMMARY] TikZ strategy flowcharts written → {_ALGORITHM_EXPLANATION_TEX}",
            force=True)
    except Exception as e:
        log_to_file(f"[SUMMARY] algorithm explanation write failed: {e}", force=True)


def _vprint(msg):
    """
    Verbose-gated console print.
    Calls AKIPrintString only when VERBOSE=True.
    Use this instead of bare AKIPrintString for all non-critical output so
    that setting VERBOSE=False silences everything in one place.
    """
    if VERBOSE:
        AKIPrintString(msg)


# =============================================================================
# CONTROL MODE
#
#   "NORMAL"          — Fixed signal plan, no bus priority.
#
#   "URTSP"           — Unrestricted TSP: green extension (GE) or phase
#                       insertion (INS) at each junction independently.
#
#   "REWARD_TSP"      — Cost-benefit TSP: each step scores GE / INS / hold
#                       in passenger-delay units and takes the best action.
#
#   "DRL_DENSITY"     — Density-aware reward TSP (DRL-style reward shaping):
#                       same action space as REWARD_TSP, with an extra
#                       network-density penalty term to suppress actions that
#                       increase corridor congestion under high load.
#
#   "MPC_TSP"         — Receding-horizon reward control (MPC-style):
#                       chooses GE / INS / hold by maximizing an immediate
#                       reward plus discounted terminal cost for residual bus
#                       delay, projected recovery debt, and offset drift.
#
#   "HARMONY"         — Phase-based coordination: GE + phase insertion at
#                       each junction; the Corridor Coordinator (CC) pre-arms
#                       downstream junctions as a bus moves along the route.
#
#   "DYNAOPAC"        — Discrete-time best-action: every second the optimizer
#                       tests all candidate durations across all junctions and
#                       activates the network-optimal action (corridor-aware).
#
#   "DYNAOPAC_HARMONY"— Discrete-time best-action + phase-based coordination:
#                       optimizer and CC pre-arming run together.

# =============================================================================
# GLOBAL REWARD MODE (anticipatory coordinated offset)
# =============================================================================
CONTROL_MODE = "DRL_DENSITY"
GROUP_BASED_BUS_PRIORITY = False
DRL_ALLOW_MULTI_BUS_PARALLEL = True
REWARD_ENABLE_PREARM = False

# =============================================================================
# LEAN MODE — intersection_controller_lean.py
# =============================================================================
# This file is a fork of intersection_controller.py that disables all legacy
# and experimental strategies, keeping only:
#   • BARGAIN_SPM  — Nash bargaining game (AnsariEsfeh & Kattan 2025)
#   • HS_EXT       — Harmony-Search duration optimizer (Geem et al. 2001)
#   • DCTSP_ZIG    — Rule-based ZIG heuristic (baseline)
#   • RL/BXT       — Q-learning (Chanloha et al. 2014) — kept as RL baseline
#   • NO_TSP       — signal coordination without TSP actions (control baseline)
#
# Disabled strategies (code still present but never activated):
#   META_TSP_MODE, MDN_DELAY_MODE, REWARD_INV_DELAY_MODE, QUEUE_MODEL_MODE,
#   BXT_MODE (overridden below), DYNAOPAC_HARMONY, MPC_TSP, SELFORG, V2X
#
# To use this file, select it in Aimsun's Python script path instead of
# intersection_controller.py.
#
# Batch experiments to use with this fork (in batch_runner.py):
#   EXPERIMENTS = [
#       {'name': 'NO_TSP',            ...},
#       {'name': 'DCTSP_ZIG',         ...},
#       {'name': 'DCTSP_BARGAIN_SPM', 'BARGAIN_SPM_MODE': True, ...},
#       {'name': 'DCTSP_HSExt',       'BARGAIN_SPM_MODE': True, 'HS_EXT_MODE': True, ...},
#   ]
LEAN_MODE = True
# =============================================================================

# Enable this for the batch experiment that requires global reward aggregation
GLOBAL_REWARD_MODE = False
try:
    from run_config import GLOBAL_REWARD_MODE as _GRM
    GLOBAL_REWARD_MODE = bool(_GRM)
except Exception:
    pass

# Inverse-delay reward variant (DCTSP_INV_DELAY batch experiment).
# When True, _dctsp_eval_action uses  r = 1 / (avg_delay + INV_DELAY_EPSILON)
# instead of the Hu et al. headway + CPD formulation.
# The denominator is the passenger-weighted average delay per bus-equivalent
# after the candidate action:
#   D̄ = (bus_delay_after × bus_occ
#         + α_car × (cross_pax_s_now + cross_pax_s_oc)) / bus_occ
# where cross_pax_s_oc is the future OC recovery cost (cross-traffic delay
# incurred when the signal corrects the cycle shift in the next cycle).
REWARD_INV_DELAY_MODE = False

# ── Bargaining-Game SPM mode (Ansari Esfeh & Kattan 2025, TRC 181) ─────────
# Approximate the paper's cooperative phase bargaining inside the existing
# DCTSP candidate evaluator using current ETA detection levels.
#
# Detection levels (by ETA to stop line) drive the bus bargaining weight:
#   immediate: eta < BG_DET_LVL_IMM_S
#   near:      BG_DET_LVL_IMM_S .. BG_DET_LVL_NEAR_S
#   far:       BG_DET_LVL_NEAR_S .. BG_DET_LVL_FAR_S
#   very far:  eta >= BG_DET_LVL_FAR_S
#
# Reward form (bus-equivalent seconds):
#   R = w_h*Δheadway + (1-w_h)*(w_bus(level)*bus_saved + main_car_saved - risk*side_cost)/bus_occ
#
# main_car_saved = D/D/1 delay saved by main-approach cars when TSP grants them
#                 additional green (symmetric to cross-approach cost formula).
# side_cost      = cross-approach D/D/1 delay added by the TSP action,
#                 risk-adjusted by BG_SPM_RISK_WEIGHT × saturation CV.
BARGAIN_SPM_MODE = True
BG_DET_LVL_IMM_S = 4.0
BG_DET_LVL_NEAR_S = 12.0
BG_DET_LVL_FAR_S = 24.0
BG_BUS_W_IMM = 1.6
BG_BUS_W_NEAR = 1.35
BG_BUS_W_FAR = 1.1
BG_BUS_W_VFAR = 0.95
BG_SPM_RISK_WEIGHT = 1.8
BG_EQ_FAIRNESS_WEIGHT = 0.55
BG_MIN_BUS_DELAY_S = 5.0
# Gate threshold in total pax·s (reward units since reward is in pax·s).
# Equivalent to BG_MIN_GAIN_S=5.0 bus-equiv-seconds × BusOcc=40 pax/bus.
BG_MIN_GAIN_S = 5.0
# Tall-bus (double-deck / articulated) occupancy boost for BARGAIN mode.
# If the detected bus length exceeds BG_TALL_BUS_LENGTH_M metres its effective
# occupancy is multiplied by BG_TALL_BUS_OCC_MULT so the reward fairly weights
# the larger passenger count.  Set BG_TALL_BUS_LENGTH_M=999 to disable.
BG_TALL_BUS_LENGTH_M  = 15.0   # metres — e.g. articulated ≥ 15 m
BG_TALL_BUS_OCC_MULT  = 2.0    # occupancy multiplier (default 40×2=80 pax)
# ── Schedule adherence and actual-load weighting ─────────────────────────────
# BG_USE_ACTUAL_LOAD=True: replace the fixed BusOcc parameter with the live
#   currentLoad field from InfPTVeh (actual pax on board at time of detection).
#   This gives a more accurate reward for half-empty vs standing-room-only buses.
# BG_USE_SCHEDULE=True: estimate how late the bus is relative to its timetable
#   at the next stop, and scale effective occupancy upward for late buses.
#   Lateness = ETA_next_stop_actual - nextServiceTime (positive = late).
#   Multiplier = 1 + max(0, lateness / BG_LATENESS_REF_S) × BG_LATENESS_SENSITIVITY
#   A bus 60s late (ref=60) with sensitivity=1.5 gets 2.5× occupancy weight.
# Both features require InfPTVeh.report >= 0 (PT vehicle in simulation).
BG_USE_ACTUAL_LOAD        = True    # use inf.currentLoad instead of fixed BusOcc
BG_USE_SCHEDULE           = True    # scale weight by schedule lateness
BG_LATENESS_REF_S         = 60.0   # reference lateness (s): 1-minute behind → 2× weight
BG_LATENESS_SENSITIVITY   = 1.5    # lateness weight sensitivity (multiplier per ref_s)
# ── Global discrete-time signal evaluation ───────────────────────────────────
# When GLOBAL_EVAL_DT > 0, AAPIPostManage evaluates ALL intersection controllers
# at a fixed time step regardless of bus detection.  This enables:
#   • Green reallocation (GR) triggered by car queue imbalance alone (no bus needed)
#   • Continuous phase offset adjustment for corridor coordination
# Bus-specific actions (GE, ER, PI) still require B_{i,t}=1.
# Set GLOBAL_GR_THRESHOLD_VEH to suppress GR when cross-queue imbalance is small.
GLOBAL_EVAL_DT            = 5.0    # evaluation interval (s); 0 = disabled
GLOBAL_GR_MODE            = False  # enable car-queue green reallocation without bus
GLOBAL_GR_THRESHOLD_VEH   = 5.0    # minimum queue imbalance (veh) to trigger GR
_global_eval_last_t: float = -999.0 # last time global eval fired
# Cascade multiplier: the local triangle-area car-cost formula only captures
# direct blocking at this intersection.  In congested conditions the actual
# network disruption (spillback, offset shift, residual queues over multiple
# cycles) is empirically ~2-3× the local estimate.  BG_CASCADE_MULT corrects
# this without touching NETWORK_FACTOR (which would also affect ZIG/MARL).
# Calibrated from 5-seed batch: bad seeds (302, 304) showed ~2.5× underestimate.
# Set to 1.5 so that combined with the SPM risk_mult (~1.4–1.7) the total
# effective multiplier is 2.1–2.6× — matching the empirical cascade ratio
# without suppressing too many beneficial actions in good seeds.
BG_CASCADE_MULT = 2.0
# Moving-bottleneck blend weight for ensemble bus-delay estimate.
# The kinematic model (_reward_estimate_no_action) ignores queue effects and
# returns 0 when the bus arrives during green even behind a residual queue.
# BG_MB_WEIGHT×mb_delay_s adds the LWR moving-bottleneck queue component so
# the effective bus delay is never badly underestimated.  Conservative (0.30)
# so it doesn't dominate over the kinematic estimate when queues are genuinely
# small.  Tune via run_config.py BG_MB_WEIGHT.  Set 0.0 to restore pure
# kinematic behaviour.
BG_MB_WEIGHT          = 0.30   # fraction of mb_delay blended into ensemble_delay
# Small inertia bonus applied to NO_ACTION in BARGAIN_SPM mode.
# Makes TSP actions need to overcome a slightly higher bar than the raw
# gain threshold, preventing noise-driven marginal insertions.
BG_NO_ACTION_BONUS_S  = 20.0   # pax·s inertia bonus for NO_ACTION (≈ 0.5s × 40 pax/bus)
# ── Harmony-Search action-duration optimizer (_HSExt variant) ────────────────
# When HS_EXT_MODE is True, replaces the discrete GE/GR/INS candidate loops
# with a Harmony Search (Geem et al. 2001) that finds the continuous optimal
# duration in [HS_EXT_T_MIN, HS_EXT_T_MAX] for each of three action types:
#   GR (GREEN_REALLOC), GE (green extension), INS (phase insertion / PI).
# Rules enforced in _dctsp_hs_ext_find_action:
#   t* < HS_EXT_T_MIN (5 s) → search space enforces this; < 5 s never returned
#   t* > HS_EXT_T_MAX (20 s) → hard-capped at 20 s
# Ref: Geem, Z.W., Kim, J.H., Loganathan, G.V. (2001). A new heuristic
#      optimization algorithm: Harmony search. Simulation, 76(2), 60–68.
HS_EXT_MODE   = False   # enable Harmony-Search duration optimizer
HS_EXT_T_MIN  = 5.0    # minimum action duration (s); <5s → rejected
HS_EXT_T_MAX  = 20.0   # maximum action duration (s); >20s → hard cap
HS_EXT_HMS    = 5      # Harmony Memory Size
HS_EXT_HMCR   = 0.75   # Harmony Memory Consideration Rate
HS_EXT_PAR    = 0.35   # Pitch Adjustment Rate
HS_EXT_BW     = 2.0    # Pitch adjustment bandwidth (s)
HS_EXT_NITER  = 20     # HS iterations per action type
# Prediction-vs-actual store: veh_id → (jct_id, detect_t, eta_s, ens, kin, dd1, mb)
_dctsp_pred_store: dict = {}
# Effective occupancy for the currently-evaluated detection; reset each cycle.
_bg_bus_occ_eff: float = 0.0   # 0 = use self.BusOcc (standard)

# ── MDN Delay Extension (Zhu et al. 2026, JTEPBS.TEENG-9465) ─────────────────
# Movement-wise delay distribution estimation using a 3-component analytical
# Mixture Density Network (MDN) approximation.
#
# Replaces _dctsp_cross_traffic_delay_s() with a full-intersection total delay
# estimate via per-approach mixture models.  Each approach j has K=3 components:
#   k=0  free-flow  : vehicles arrive during green → delay ≈ 0
#   k=1  stop-delay : vehicles arrive during red → Webster uniform delay r_j/2
#   k=2  overflow   : residual queue persists into next cycle → extra wait
#
# Mixture weights (π_0, π_1, π_2) depend on v/c ratio and g/C ratio.
# Delay Distribution Transform (DDT) from Eq. (7) of Zhu et al.: z = y^p, p=0.5
# ensures the heavy-tailed delay distribution is stabilised for estimation.
#
# When MDN_DELAY_MODE = True, the reward in _dctsp_eval_action uses:
#   R = w_hw × Δheadway + (1-w_hw) × (mdn_NO_ACTION − mdn_action) / bus_occ
# This delta-based formula gives consistent pax·s scale (same as MARL) with no
# upper bound and proper discrimination even in heavy-traffic conditions.
MDN_DELAY_MODE = False
MDN_DDT_POWER  = 0.5    # DDT power transform p (Zhu et al. 2026 default = 0.5)
MDN_N_COMPONENTS = 3    # number of Gaussian mixture components
MDN_EPSILON    = 0.5    # legacy denominator floor — no longer used in reward formula
                        # (reward now uses delta: mdn_NA - mdn_act) / bus_occ + hw_delta

# ── Queue-based delay estimation (D/D/1 + Webster deterministic queue model) ──
# When QUEUE_MODEL_MODE = True, the reward in _dctsp_eval_action uses a
# physically grounded D/D/1 queue model to estimate bus delay based on:
#   • Current queue length at bus approach (MaxQueueLength[0])
#   • Arrival rate at bus approach (UpFlowList[0])
#   • Saturation flow rate (SaturationFlow / QUEUE_MODEL_SAT_FLOW_VPH)
#   • Remaining red time and bus ETA to stop line
#
# This improves on the kinematic "catch-the-green-or-miss-it" model by
# accounting for the service delay the bus incurs behind residual queue vehicles
# even when it arrives during a green phase.
#
# Reference: deterministic D/D/1 model (May 1990, Newell 1965); queue delay
# approach consistent with Webster (1958) and HCM 2010 signalised intersection
# control delay (Equation 19-3).  Probabilistic extensions (overflow correction)
# from Akcelik (1988) / TRB Part B 2009 queue length distribution paper.
QUEUE_MODEL_MODE         = False
QUEUE_MODEL_SAT_FLOW_VPH = 1800.0  # saturation flow override if SaturationFlow not set (veh/h)

# Buffer for per-intersection rewards (sim step → reward)
_global_reward_buffer = {}

def _reset_global_reward_buffer():
    global _global_reward_buffer
    _global_reward_buffer = {}

def _record_intersection_reward(jct_id, reward):
    global _global_reward_buffer
    _global_reward_buffer[jct_id] = float(reward)

def _aggregate_global_reward():
    """
    Return mean Yang-Fan CPD reward (pax-s) across intersections that reported
    a reward this cycle.  Returns 0.0 if the buffer is empty.
    """
    if not _global_reward_buffer:
        return 0.0
    return sum(_global_reward_buffer.values()) / max(len(_global_reward_buffer), 1)

def _aggregate_global_reward_as_offset_s(bus_occ=40.0):
    """
    Convert the buffered DC TSP reward (now in bus-equivalent SECONDS) to a
    small time offset for the next intersection's GE cap.

    Reward is already in seconds — no BusOcc division needed.
    Clip to [0, +4] s: only positive signal propagates (upstream success →
    downstream gets a slightly larger GE window); negative signal is dropped
    so a bad upstream decision doesn't cascade forward.
    """
    mean_reward_s = _aggregate_global_reward()
    return max(0.0, min(4.0, mean_reward_s))

def _apply_offset_to_next_intersection(source_jct_id: int, offset_s: float):
    """
    Apply future_offset_s only to the IMMEDIATE next managed intersection
    downstream of source_jct_id in any corridor that contains it.
    Does NOT touch all intersections at once.
    """
    if abs(offset_s) < 0.5:
        return
    for coord in corridor_coordinators:
        route = getattr(coord, 'route_inter_ids', [])
        try:
            idx = route.index(source_jct_id)
        except ValueError:
            continue
        if idx + 1 < len(route):
            next_id = route[idx + 1]
            ctrl = controllers.get(next_id)
            if ctrl is not None:
                ctrl.set_future_offset(offset_s)
                log_to_file(
                    f"[GLOBAL_REWARD] offset={offset_s:+.2f}s → next jct={next_id} "
                    f"(source={source_jct_id})",
                    force=True)
                return

# =============================================================================
# CORRIDOR COORDINATOR (CC) SETTINGS
#
# The Corridor Coordinator tracks each bus along the route using a Kalman
# filter, predicts arrival time at each downstream junction, and fires a
# pre-arm request early enough for that junction to complete its current
# phase and be ready on green when the bus arrives.
#
# COORDINATED_TSP
#   True  — CC is active; junctions in the same INTERSECTION_GROUPS entry
#           coordinate their signals (pre-arm up to MAX_PRE_ARM junctions
#           ahead of the current bus position).
#   False — Each junction runs independently; no pre-arming.
#
# COORDINATION_ALGO   — ETA prediction method used by CC.
#
#   "KALMAN"    — 1-D Kalman filter on position + speed.  Best for free-flow
#                 or lightly congested conditions.
#
#   "SHOCKWAVE" — Kalman ETA plus a queue-clearance correction: when the
#                 downstream junction has a large queue, adds the time for
#                 the discharge wave to reach the stop line.
#
#   "OBJECTIVE" — Variable lead time: CC picks the lead that maximises
#                   J = COORD_OBJ_ALPHA * bus_delay_saved  (pax-s)
#                     - COORD_OBJ_BETA  * normal_traffic_displaced  (pax-s)
#                 Tune ALPHA / BETA to balance bus priority vs. general delay.
#
#   "ADAPTIVE"  — Hybrid: Kalman ETA → shockwave correction under congestion
#                 → dynamic lead scaled by ETA uncertainty and phase-remaining.
#
# COORD_OBJ_ALPHA / COORD_OBJ_BETA apply only with COORDINATION_ALGO="OBJECTIVE".
# =============================================================================
COORDINATED_TSP = True   # True = CC active (corridor coordination)

MAX_GE_EXTENSION_S   = 15.0   # Max green extension per bus request (s)
MAX_BP_INSERTION_S   = 65.0   # Max bus-phase insertion per request (s)
# Maximum ETA for which any TSP strategy will be evaluated.  Buses further
# than this from the stop line are too far for a meaningful GE or INS and
# should only be tracked/counted, not acted on.
MAX_STRATEGY_ETA_S   = 75.0   # matches MAX_PREARM_HORIZON_S — sync if changed
INS_TRIGGER_MARGIN_S = 5.0    # Require bus ETA to exceed natural end by this margin before INS
INS_CLEARANCE_BUFFER_S = 8.0  # Add clearance buffer to ETA when deciding if natural bus phase is truly catchable
INS_MAX_WAIT_TRIGGER_S = 8.0  # If predicted wait for next natural bus phase exceeds this, evaluate INS
# Adaptive bounds for INS trigger margin. A larger ETA should require a
# slightly larger miss of the natural window before forcing insertion.
INS_TRIGGER_MARGIN_MIN_S = 3.0
INS_TRIGGER_MARGIN_MAX_S = 12.0

# ── DC TSP multi-agent reward (GLOBAL_REWARD_MODE) ───────────────────────────
# Implements Eq. 6 from Hu et al. (2025) Transportmetrica B:
#   r_t = Σ_n [ w_h*(|σ_n^in| - |σ_n^out|) + (1-w_h)*(T̄_n^POZ - T_n^POZ) ]
# scaled to pax-seconds so bus passengers (BusOcc) are weighted against cars.
#
# Action space per intersection (evaluated every detection event):
#   GE   — extend the current bus-green phase by {5, 10, 15} s
#   INS  — insert bus phase with duration = BusPhaseDuration + {-10,-5,0,+5,+10,+15} s
#   NO_ACTION — hold current signal plan
DCTSP_W_H           = 0.6    # headway weight (Eq. 6); paper default = 0.6
# Car-traffic penalty weight.  Applied to (other_delay_pax_s / BusOcc) so the
# result stays in bus-equivalent seconds — directly comparable to headway/travel
# improvements that are already in seconds.  0.40 means ~1 bus-pax second of car
# delay costs the same as 0.40 s of bus headway improvement.
DCTSP_CAR_WEIGHT    = 0.40
DCTSP_GE_ACTIONS         = [5.0, 10.0, 15.0]    # GE candidates (s)
# INS durations kept short so cross-traffic disruption is bounded and recoverable.
DCTSP_INS_DURATIONS      = [10.0, 15.0, 20.0]
DCTSP_MIN_INS_DURATION_S = 10.0   # hard floor
DCTSP_MAX_INS_DURATION_S = 20.0   # hard ceiling — 20 s is enough to clear most phases
# Intergreen transition overhead for pre-terminated phase insertion.
# INS_PRETERM truncates the current phase immediately; the bus phase starts
# after this many seconds (amber + all-red clearance interval).
INS_INTERGREEN_S         = 3.0
# ── EARLY_RED: cut the current non-bus phase short so the bus phase arrives sooner ──
# EARLY_RED differs from INS_PRETERM in that NO extra bus green is inserted;
# the bus simply benefits from its naturally-scheduled phase starting earlier.
# action_param = seconds to cut from the current non-bus phase.
# Feasible only when current_phase != BusPhase; clipped to remaining_red_s − INS_INTERGREEN_S.
# Cost: current cross-traffic phase loses action_param seconds of committed green.
# Benefit: bus phase starts action_param s sooner → bus delay reduced by min(cut, no_act_delay).
DCTSP_ER_ACTIONS = [10.0, 20.0, 30.0]   # early-red cut candidates (s)
# ── CONGESTION GATE: suppress TSP at near-saturated network conditions ────────
# Literature (Dion et al. 2004; Duerr 2000): TSP with green extension or
# phase insertion is counter-productive when the network is near saturation —
# any green added to the bus phase must be taken from already-overloaded cross
# phases, causing secondary queuing that more than offsets the bus benefit.
# When enabled, TSP actions are blocked (NO_ACTION forced) when the mean
# cross-phase flow exceeds DCTSP_CONGESTION_GATE_FRACTION × SaturationFlow.
DCTSP_CONGESTION_GATE = True
DCTSP_CONGESTION_GATE_FRACTION = 0.75

# ── MULTI-CYCLE SATURATION CORRECTION for cross-traffic delay model ───────────
# The D/D/1 discharge-tail model underestimates cross-traffic delay at near-
# saturated intersections because it captures only a single-cycle effect.
# Near saturation (v/c > X_THR), residual queues accumulate over successive
# cycles and total delay grows as ≈ 1/(1-x)  (HCM 2010 Eq. 16-5 overflow term).
# This per-phase multiplier inside _dctsp_cross_traffic_delay_s corrects for
# multi-cycle spillback so the reward model does not fire TSP at junctions
# where the actual car-network cost far exceeds the modelled value.
DCTSP_MULTI_CYCLE_X_THR   = 0.70   # v/c ratio above which correction is applied
DCTSP_MULTI_CYCLE_X_FLOOR = 0.05   # floor for (1-x): caps multiplier at 1/0.05=20×

# ── GREEN_REALLOC: split/shift planned bus green instead of adding green ───
# Reallocate part of the planned bus green to arrive earlier for an approaching
# bus by cutting the current non-bus phase.  No net new green is created.
DCTSP_GREEN_REALLOC_MODE = True
DCTSP_GR_ACTIONS = [5.0, 10.0, 15.0]     # reallocation cut candidates (s)
# Fraction of cut time recovered by shortening planned bus green later in cycle.
# 1.0 means full reallocation (no net green increase).
GREEN_REALLOC_RECOVER_FRACTION = 1.0

# ── DCTSP-ZIG (Zero-Interference-Grant) shockwave-optimal selection ──────────
# ZIG replaces the discrete {5,10,15,20} s candidate search with a single
# analytically-derived optimal duration computed from the LWR shockwave
# queue-discharge model (Newell 1993 / Daganzo 1994 triangular FD):
#
#   w_b  = q_arr / (k_jam − k_arr)       [km/s] back-propagation wave speed
#   N_q  = w_b × T_red × k_jam           [veh]  estimated queue at green onset
#   t_cl = N_q / (q_sat − q_arr)         [s]    time to fully discharge queue
#
# Action space (4 discrete actions, 1 optimal duration each):
#   NO_ACTION    — hold current signal plan.
#   GE           — green extension; t_opt = miss_by + t_cl (covers missed green
#                  AND clears queued vehicles ahead of the bus).
#   INS_POST     — phase insertion AFTER the current phase ends naturally;
#                  overhead = remaining_red_s + INS_INTERGREEN_S.  No forced
#                  phase switch; relies on natural signal sequence.
#   INS_PRETERM  — phase insertion with immediate pre-termination of the
#                  current phase; overhead = INS_INTERGREEN_S = 3 s only.
#                  Additional cross-traffic cost for cutting current phase short.
#
# Phase-overlap correction (IEEE ICARCE 2023, GTE for phase-overlapping
# intersections):  effective_delay = max(0, no_act_delay − ZIG_PHASE_OVERLAP_S)
# Saturation avoidance: side_ratio = side_pax_pressure / bus_pax_pressure;
#   if side_ratio > ZIG_BALANCE_FACTOR → force NO_ACTION.
DCTSP_ZIG_MODE = False
ZIG_PHASE_OVERLAP_S = 3.0
ZIG_BALANCE_FACTOR = 1.0

# ── DCTSP-MP-ECTM (Bao et al. 2026, Transportmetrica B 14(1) 2625383) ────────
# Mathematical Programming + Enhanced Cell Transmission Model TSP control.
#
# Minimises total passenger delay Z = Σ_t [α_bus×n_bus(t) + α_car×D_side(t)]×Δt
# (Eq. 23) over one signal cycle horizon by grid-searching extension
# δ ∈ [MP_ECTM_MIN_EXT_S, MP_ECTM_MAX_EXT_S].
#
# CTM queue dynamics (Eq. 2-9) model the bus-approach cell:
#   • During red  : n(t+1) = n(t) + q_arr × Δt              (Eq. 2)
#   • During green: n(t+1) = n(t) + q_arr × Δt − q_out × Δt (Eq. 2)
#     where q_out = min(q_sat, n(t)/Δt)                      (Eq. 3-4)
#   • Vehicle delay (Eq. 21): D(t) = n(t) × Δt  [veh·s]
#   • Passenger delay (Eq. 22): PD(t) = α_bus × D_bus(t) + α_car × D_side(t)
#
# Initial bus-approach queue estimated via LWR shockwave model (same as ZIG).
# Side-street cost uses _dctsp_cross_traffic_delay_s() (existing model).
#
# Signal constraints enforced (Eq. 24-31):
#   g_min ≤ g_p ≤ g_max   (green duration bounds)
#   0 ≤ δ ≤ MP_ECTM_MAX_EXT_S  (extension bound for bus phase only)
#
# Saturation avoidance: side_ratio > MP_ECTM_BALANCE_FACTOR → NO_ACTION.
# Bus-delay threshold: eff_delay < SELFORG_MIN_BUS_DELAY_S → NO_ACTION.
MP_ECTM_MODE = False
MP_ECTM_DT_S = 1.0
MP_ECTM_MIN_EXT_S = 3.0
MP_ECTM_MAX_EXT_S = 20.0
MP_ECTM_CAR_OCC = 1.2
MP_ECTM_BALANCE_FACTOR = 1.0

# ── DCTSP-BXT (Chanloha et al. 2014, Comput. J. 57(3) 451-466) ──────────────
# CTM-Based Multiagent Q-Learning with Transit Signal Priority.
# "Red-light delay" reward ϒ(t) = Σ_approaches_at_red n_i(t)·Δt·occ_i  (Eq. 29-32).
# Q(s,a) ← Q(s,a) + α·[ϒ(t) + γ·min_a'Q(s',a') − Q(s,a)]  (Eq. 33, min not max).
# DOI: 10.1093/comjnl/bxt126
BXT_MODE = False
BXT_DT_S = 1.0
BXT_EPSILON = 0.1
BXT_ALPHA = 0.01
BXT_GAMMA = 0.005
BXT_CAR_OCC = 1.2
BXT_BALANCE_FACTOR = 1.0
# Q-table for BXT (separate from MARL's _dctsp_q_table):
# {jct_id: {state_bin: [Q_a0, ..., Q_a6]}}
_dctsp_bxt_q_table: dict = {}

# ── META_TSP: System-optimal adaptive transit signal priority ────────────────
# META_TSP minimises TOTAL system passenger delay across ALL vehicles
# (buses + cars + trucks) using CTM queue simulation with an adaptive bus
# priority weight that scales with headway deviation (schedule lateness).
#
# Objective (one signal cycle horizon):
#   Z(a) = w_bus(σ) × bus_delay_after(a) × BusOcc
#          + w_car × cross_delay(a) × est_car_pax
#
# Adaptive bus weight (Hu et al. 2025 headway-adherence, extended):
#   w_bus(σ) = META_BASE_BUS_WEIGHT
#              + META_HW_SENSITIVITY × clip(|σ_in| / META_HW_REF_S, 0, 1)
#   When on-time (σ ≈ 0): w_bus = BASE_WEIGHT → equal treatment
#   When severely late (|σ| ≫ HW_REF): w_bus → BASE + HW_SENS → strong priority
#
# Multi-horizon cost:
#   Z_full(a) = Z_immediate(a) + META_OC_WEIGHT × Z_oc_recovery(a)
#   Z_oc_recovery: cross-traffic pax-s cost of signal-cycle recovery in next cycle
#
# Acts only when improvement ≥ META_MIN_THRESHOLD_PAX_S (conservative gate
# that prevents marginal interventions from degrading network throughput).
# Saturation avoidance: side_ratio > META_BALANCE_FACTOR → NO_ACTION
#
# References:
#   Bao et al. (2026) Transportmetrica B 14(1) 2625383 — total pax-delay objective
#   Hu et al. (2025) DCTSP Eq. 6 — headway-adherence weighting
#   Chanloha et al. (2014) Comput. J. 57(3) — CTM queue simulation
#   Newell (1993) / Daganzo (1994) — LWR shockwave-optimal duration
META_TSP_MODE           = False
META_DT_S               = 1.0     # CTM time step (s)
META_BASE_BUS_WEIGHT    = 1.0     # base bus occupancy weight (= car weight when on-time)
META_HW_SENSITIVITY     = 1.5     # max additional weight when severely late
META_HW_REF_S           = 60.0   # headway deviation for full sensitivity (s)
META_MIN_THRESHOLD_PAX_S= 10.0   # min net pax·s benefit to trigger TSP action
META_BALANCE_FACTOR     = 1.2    # side_ratio ≤ this → allow TSP (slightly relaxed vs SELFORG 1.0)
META_MIN_BUS_DELAY_S    = 3.0    # minimum bus delay (s) before evaluating TSP
META_OC_WEIGHT          = 0.4    # weight on future OC-recovery cross-traffic cost
META_CAR_OCC            = 1.2    # average car occupancy for cross-traffic delay (pax/veh)

# Periodic corridor replan: once per cycle, re-check offset alignment for all
# managed intersection pairs and apply a forward OC if drift > threshold.
DCTSP_REPLAN_INTERVAL_S  = 110.0  # seconds between replans (≈ one signal cycle)
# ── Unified reward weights (DCTSP_MARL) — paper Hu et al. 2025 Eq. 6 ──────────
# Reward = wh * ΔHeadway  +  (1-wh) * ΔNetPaxDelay
#
#   wh:       headway-adherence weight; paper default = 0.6.
#             Raise to prioritise schedule regularity over total delay.
#   (1-wh):   net passenger delay reduction weight (= 0.4 at default).
#             CPD_delta = (bus_pax_saved_s - car_pax_cost_s) / BusOcc  [bus-equivalent seconds]
#             Car delay is captured in CPD_delta via _dctsp_cross_traffic_delay_s;
#             no separate throughput penalty is needed or applied.
DCTSP_W_PAX_DELAY   = 1.0 - DCTSP_W_H   # net pax-delay weight = (1 - wh) = 0.4
DCTSP_W_TRAVEL_TIME = 0.0                # POZ travel-time term retired; set to 0
DCTSP_W_HEADWAY     = DCTSP_W_H          # headway term = wh = 0.6
# Offset-correction thresholds (forward OC, per DC TSP paper § "Impact of OC")
DCTSP_OC_THRESH_S   = 3.0    # minimum offset error (s) that triggers a forward OC
DCTSP_OC_MAX_ADJ_S  = 15.0   # maximum phase adjustment (s) per forward-OC event

# ── Reward-TSP weights  (REWARD_TSP mode only) ────────────────────────────────
# Score = -ALPHA*bus_delay_saved - BETA*other_delay_cost - GAMMA*side_delay_cost
# Bus delay reduction remains the primary signal.
# Other-traffic delay and density stay in the objective, but as softer penalties
# so the controller still accepts useful bus-priority actions when they help the
# corridor overall.
REWARD_ALPHA = 1.0
REWARD_BETA = 1.0
REWARD_GAMMA = 1.0
REWARD_DENSITY = 1.0
# Floor added to the average-delay denominator in REWARD_INV_DELAY_MODE.
# Units: bus-equivalent seconds.
#   ε = 1.0  → max reward = 1/(0+1) = 1.0 when delay=0 (confusing "clip at 1")
#   ε = 0.5  → max reward = 1/(0+0.5) = 2.0 (broader range, less confusion)
# A smaller epsilon makes the reward surface steeper and pushes max away from 1.0
# so that the NO_ACTION "ceiling" is clearly distinguishable from action rewards.
INV_DELAY_EPSILON = 1.0
# Car-traffic weight used ONLY in REWARD_INV_DELAY_MODE.
# Kept separate from DCTSP_CAR_WEIGHT (0.40) so the two experiments can use
# different trade-offs: a higher value here makes the INV_DELAY formula more
# sensitive to cross-traffic cost and can produce genuinely different action
# selection from DCTSP_MARL at moderate-to-high car volumes.
INV_DELAY_CAR_WEIGHT = 2.0

# V2X reward mode (DCTSP_V2X experiment) — inspired by BOCS (Hu et al. 2026, ITI).
# Uses TOTAL intersection delay (full bus-phase blocking + action + OC recovery)
# instead of the incremental delta, so the reward reflects the complete impact
# on all road users (total traffic throughput).
# Adds a crowding penalty (BOCS Eq 21) to penalise filling an overloaded bus.
#
#   r = 1 / (D_total + C_crowd + V2X_EPSILON)
#
#   D_total = (bus_delay_after × bus_occ
#              + α_car × total_car_pax_s) / bus_occ  +  |σ_out|
#
#   total_car_pax_s = _dctsp_cross_traffic_delay_s(bp_dur + action_s)   [GE]
#                   = _dctsp_cross_traffic_delay_s(action_s)            [INS]
#                   = _dctsp_cross_traffic_delay_s(bp_dur)              [NO_ACTION]
#                   + _dctsp_cross_traffic_delay_s(oc_s)                [GE/INS only]
#
#   C_crowd = V2X_CROWDING_SCALE × max(0, (bus_occ - V2X_MAX_BUS_OCC) / V2X_MAX_BUS_OCC)²
REWARD_V2X_MODE = False
V2X_MAX_BUS_OCC = 80.0
V2X_CROWDING_SCALE = 10.0
V2X_EPSILON = 1.0
# V2X balance guard (analogous to ZIG_BALANCE_FACTOR).
# Root cause of V2X over-application: D_total normalises car cost by bus_occ (≈25),
# making car_term ≈ 2-14 s while bus_delay ≈ 30-80 s → TSP fires for almost any delay.
# Fix: add a direct pax·s cost-benefit check before accepting a TSP action.
#   ratio = (DCTSP_CAR_WEIGHT × total_car_pax_s) / (bus_delay_no_act × bus_occ)
#   block when ratio > V2X_BALANCE_FACTOR (i.e., car cost > X% of bus pax saving)
# 0.50: block when car pax cost > 50% of bus pax savings (same as ZIG default)
V2X_BALANCE_FACTOR = 1.0

# Self-organizing control during temporary oversaturation (Cesme & Furth 2014, Section 4)
# + phase-overlap correction (IEEE ICARCE 2023: GTE for Phase Overlapping Intersections).
#
# When REWARD_SELFORG_MODE=True:
#   - The RL block (Q-table / epsilon-greedy) is SKIPPED entirely.  The SE rule is the
#     only decision maker — purely deterministic, no learning.
#   - Phase-overlap correction (IEEE ICARCE 2023): at intersections where the bus phase
#     overlaps an adjacent phase (some bus movements continue into the next phase),
#     the bus is not fully stopped during the "delay" window.  The effective delay is:
#         effective_delay = max(0, no_act_delay − SELFORG_PHASE_OVERLAP_S)
#     Set SELFORG_PHASE_OVERLAP_S to the measured overlap duration at this intersection.
#   - Trigger: effective_delay ≥ SELFORG_MIN_BUS_DELAY_S
#              (any meaningful bus delay justifies considering TSP)
#   - Balance criterion: side_pressure / bus_pressure ≤ SELFORG_BALANCE_FACTOR
#         bus_pressure  = effective_delay × BusOcc
#         side_pressure = (OtherDelay + SideDelayBaseline) × car_occ
#     Act when bus_pressure ≥ side_pressure × (1/BALANCE_FACTOR)
#     (Cesme & Furth: extend the current phase while its cumulative delay exceeds
#      the cumulative delay on waiting approaches)
#   - If triggered & balance met → SE action:
#       SE duration = clip(effective_delay × SELFORG_SE_FRACTION,
#                          SELFORG_MIN_SE_S, SELFORG_MAX_SE_S)
#       rounded to nearest standard duration {5, 10, 15, 20}
#       Action type: GE if current_phase == BusPhase, else INS
#   - If effective_delay < SELFORG_MIN_BUS_DELAY_S → keep greedy-best (not NO_ACTION)
#   - If balance fails (side dominates) → force NO_ACTION
REWARD_SELFORG_MODE = False
SELFORG_MIN_BUS_DELAY_S = 10.0
SELFORG_BALANCE_FACTOR = 1.0
SELFORG_MAX_SE_S = 30.0
SELFORG_MIN_SE_S = 5.0
SELFORG_SE_FRACTION = 0.5
SELFORG_PHASE_OVERLAP_S = 5.0
                                     # (IEEE ICARCE 2023 phase-overlap correction)

# Minimum bus delay (s) before each reward mode will commit to a TSP action.
# When no_action_bus_delay < threshold the candidate scores 0 (NO_ACTION wins).
# This creates genuine behavioural divergence between the three modes:
#   DCTSP_MARL       — no threshold (acts for any positive delay)
#   DCTSP_INV_DELAY  — default 0 s; batch sets e.g. 5 s
#   DCTSP_V2X        — default 0 s; batch sets e.g. 12 s
INV_DELAY_MIN_DELAY_S = 0.0
V2X_MIN_DELAY_S = 0.0
# ── Network amplification factor (all DCTSP reward modes) ────────────────────
# The local triangle-area estimate in _dctsp_cross_traffic_delay_s captures
# ONLY the direct queue-blocking at this intersection.  It ignores:
#   1. Downstream signal-coordination disruption (green-wave offset shift)
#   2. Queue spillback propagation (blocked veh can't enter the next intersection)
#   3. Network amplification (~3-8× per LWR theory on a coordinated corridor)
#
# Setting NETWORK_FACTOR > 1.0 corrects this underestimation so that the reward
# function properly discourages actions whose real network impact outweighs the
# bus benefit.  Empirical calibration (results vs NO_TSP baseline):
#   1.0 → current behaviour (local cost only → all DCTSP modes worse than NO_TSP)
#   4.0 → INV_DELAY and V2X fire fewer high-disruption actions
#   5.0 → ZIG / META_TSP fire actions only for significant bus benefit
#
# Default = 1.0 (backward compatible with existing logged results).
# Set per-experiment in batch_runner.py reward_overrides.
NETWORK_FACTOR = 1.0
REWARD_THROUGHPUT_TOL = 0.25   # vehicle-equivalent tolerance for the hard throughput constraint
REWARD_GE_MIN_DELAY_S = 1.0    # skip GE candidate evaluation when no-action bus delay is negligible
REWARD_GE_CANDIDATES = [5.0, 10.0, 15.0, 20.0]  # candidate GE durations (s)
# Reward-v2: action-cost and adaptive side-street weighting.
# These keep priority actions useful for buses while discouraging overuse when
# cross-street pressure is already high.
REWARD_ACTION_COST_GE = 0.15    # pax-s equivalent penalty per second of GE
REWARD_ACTION_COST_INS = 0.30   # pax-s equivalent penalty per second of INS
REWARD_SIDE_MULT_BASE = 1.0     # minimum multiplier on side-street delay penalty
REWARD_SIDE_MULT_MAX = 2.0      # maximum multiplier on side-street delay penalty
REWARD_SIDE_PRESSURE_GAIN = 1.2 # queue-pressure gain for adaptive side multiplier
REWARD_SIDE_RED_GAIN = 0.35     # extra sensitivity to long added red times
# Lookahead reward term: penalize actions that create future schedule/offset
# disturbance likely to require corrective trimming in upcoming cycles.
REWARD_FUTURE_ENABLE = True
REWARD_FUTURE_DEBT_GAIN = 0.35    # weight on projected unrecovered debt (pax-s equivalent)
REWARD_FUTURE_OFFSET_GAIN = 0.20  # weight on projected offset misalignment cost
REWARD_FUTURE_HORIZON_CYCLES = 1.5  # lookahead horizon in cycle-length units
# Per-junction priority rate budget: maximum cumulative GE+INS seconds per
# simulated hour.  Once a junction exceeds this rate the budget penalty grows
# linearly, making additional grants progressively less attractive.
# Set to 0 to disable.  900 s/hr ≈ 15 s of priority per minute (comparable
# to HARMONY_COORD's observed rate of ~13 s/min).
REWARD_PRIORITY_BUDGET_S = 900.0   # s of priority per simulated hour

# ── Q-learning (Bellman TD) — shared by all DCTSP reward modes ───────────────
# Tabular Q-learning with ε-greedy exploration running across the corridor.
# The estimated immediate reward r̂(s, a) from _dctsp_eval_action is the
# one-step signal.  The Bellman bootstrap adds γ·max_a' Q(s', a') using the
# Q-values at the NEXT junction this bus visits, connecting decisions across
# the corridor into a proper MDP:
#
#   Q(s,a) ← Q(s,a) + α · [r̂ + γ·max_a'Q(s',a') − Q(s,a)]
#
# Q-values are initialised from estimated rewards on first state visit so the
# agent starts with a useful prior rather than a zero table.
# The Q-table persists across replications of the SAME experiment (learning
# accumulates over seeds) but is reset when the experiment changes.
RL_LEARNING_RATE = 0.1    # α — Bellman TD step size
RL_DISCOUNT      = 0.9    # γ — future-reward discount factor (across junctions)
RL_EPSILON       = 0.15   # ε — exploration probability (ε-greedy)
# Action space — order must match DCTSP_GE_ACTIONS + DCTSP_INS_DURATIONS so
# that label→index mapping is consistent with _dctsp_eval_action output.
DCTSP_RL_ACTION_SPACE = [
    ('NO_ACTION',  0.0),
    ('GE',   5.0), ('GE',  10.0), ('GE',  15.0),
    ('INS', 10.0), ('INS', 15.0), ('INS', 20.0),
    # EARLY_RED actions — only feasible when current_phase != BusPhase.
    # When on the bus phase these will evaluate like NO_ACTION (action_s=0 clipped),
    # so RL will never prefer them over real actions in that state.
    ('EARLY_RED', 10.0), ('EARLY_RED', 20.0), ('EARLY_RED', 30.0),
    # GREEN_REALLOC actions — shift planned bus green earlier without adding
    # net green to the cycle.
    ('GREEN_REALLOC', 5.0), ('GREEN_REALLOC', 10.0), ('GREEN_REALLOC', 15.0),
]
# Q-table: {jct_id: {state_bin: [Q_a0, Q_a1, ..., Q_a6]}}
_dctsp_q_table:    dict = {}
# Pending cross-junction TD transitions: {veh_id: (jct_id, state_bin, action_idx, r_est)}
# Completed when the bus arrives at the next managed intersection.
_dctsp_pending_td: dict = {}
# Per-vehicle entry record for measured delay feedback.
# Populated at detection; consumed at POZ checkout.
# Key: veh_id  Value: (junction_id, action_type, action_param, entry_time_s,
#                       rl_state, action_idx)
_poz_action_log: dict = {}

# Reward high-density guardrail: progressively reduce intervention strength as
# network density rises. This prevents reward mode from over-prioritizing buses
# when the corridor is already saturated.
REWARD_DENSITY_GUARD_ON = True
# Tuned for observed runs where network density trends in the 17-18 veh/km range.
# Trigger earlier so reward mode reduces interventions before reaching saturation.
REWARD_DENSITY_SOFT_VKM = 13.5          # start trimming GE aggressiveness
REWARD_DENSITY_HARD_VKM = 15.0          # stronger cap + insertion suppression
REWARD_DENSITY_EMERG_VKM = 16.5         # emergency cap (very high congestion)
REWARD_GUARD_GE_SOFT_CAP_S = 8.0        # max GE when density >= SOFT
REWARD_GUARD_GE_HARD_CAP_S = 3.0        # max GE when density >= HARD/EMERG
REWARD_GUARD_ALLOW_INS_IF_LATE_S = 35.0 # allow INS above HARD only for very late buses

# ── MPC_TSP (receding-horizon decision score over reward candidates) ─────────
# decision_score = immediate_reward + MPC_DISCOUNT * terminal_value
# where terminal_value penalizes residual bus delay + projected debt/offset.
MPC_DISCOUNT = 0.65
MPC_RESIDUAL_BUS_GAIN = 0.25
MPC_TERMINAL_DEBT_GAIN = 0.20
MPC_TERMINAL_OFFSET_GAIN = 0.15
MPC_TERMINAL_DENSITY_GAIN = 0.10

# ── CC ETA algorithm parameters ───────────────────────────────────────────────
COORDINATION_ALGO = "KALMAN"  # "KALMAN" | "SHOCKWAVE" | "OBJECTIVE" | "ADAPTIVE"
COORD_OBJ_ALPHA      = 1.0       # bus passenger-delay weight  (OBJECTIVE mode)
COORD_OBJ_BETA       = 0.5       # general-traffic weight      (OBJECTIVE mode)
PREARM_MAX_SIGMA_S   = 30.0      # max ETA uncertainty (s) to allow a pre-arm;
                                  #   tighter gate prevents uncertain long-range predictions
                                  #   from triggering pre-arms across multiple intersections
MAX_PREARM_HORIZON_S = 75.0      # pre-arm look-ahead window (s)
