BUS_FREQUENCY_MULTIPLIER = 1        # 2 = double buses, 3 = triple, etc.
TARGET_PT_LINE_IDS       = []       # [] = all lines, or e.g. [101, 102]

# ── ADD THIS FUNCTION ─────────────────────────────────────────────────────

def _vehicle_type_name(pos):
    """
    Return the lowercase name string for vehicle type at position pos.

    Aimsun versions differ in what AKIVehGetVehTypeName returns:
      - Newer SDK  : a Python str directly
      - Older SDK  : an opaque SWIG 'unsigned short *' object that needs
                     AKIConvertToAsciiString to decode
      - Some builds: AKIConvertToAsciiString itself returns another SWIG
                     object (the bug seen in the log: '<swig object...>')

    We try every known decoding path and fall back to an empty string rather
    than letting a '<swig object…>' leak into the keyword matching.
    """
    try:
        raw = AKIVehGetVehTypeName(pos)
    except Exception:
        return ""

    # Path 1 — raw is already a plain Python string
    if isinstance(raw, str):
        return raw.lower()

    # Path 2 — AKIConvertToAsciiString returns a plain string
    try:
        converted = AKIConvertToAsciiString(raw, True)
        if isinstance(converted, str):
            return converted.lower()
        # converted is also a SWIG object — try str() on it and check
        s = str(converted)
        if "<swig" not in s:
            return s.lower()
    except Exception:
        pass

    # Path 3 — try AKIConvertToAsciiString with False flag (some versions differ)
    try:
        converted2 = AKIConvertToAsciiString(raw, False)
        if isinstance(converted2, str):
            return converted2.lower()
        s2 = str(converted2)
        if "<swig" not in s2:
            return s2.lower()
    except Exception:
        pass

    # Path 4 — try direct str() on the raw object
    s_raw = str(raw)
    if "<swig" not in s_raw:
        return s_raw.lower()

    # Path 5 — ctypes.wstring_at for UTF-16 (unsigned short* on Windows)
    # AKIVehGetVehTypeName returns unsigned short* which is UTF-16LE on Windows.
    try:
        import ctypes
        ptr_str = str(raw)
        if "0x" in ptr_str:
            ptr_val = int(ptr_str.split("0x")[1].rstrip(">").strip(), 16)
            name_w = ctypes.wstring_at(ptr_val)
            if name_w:
                return name_w.lower()
    except Exception:
        pass

    # Path 6 — ctypes.string_at for narrow (char*) encoding
    try:
        import ctypes
        ptr_str = str(raw)
        if "0x" in ptr_str:
            ptr_val = int(ptr_str.split("0x")[1].rstrip(">").strip(), 16)
            name_b = ctypes.string_at(ptr_val, 64)  # max 64 bytes
            name_decoded = name_b.decode("utf-16-le", errors="replace").split("\x00")[0]
            if name_decoded.isprintable() and len(name_decoded) > 0:
                return name_decoded.lower()
            name_decoded2 = name_b.decode("utf-8", errors="replace").split("\x00")[0]
            if name_decoded2.isprintable() and len(name_decoded2) > 0:
                return name_decoded2.lower()
    except Exception:
        pass

    # All paths failed — return empty; caller will rely on PT-line inference
    return ""


def _scan_named_vehicle_type_positions():
    car_pos = -1
    bus_pos = -1
    truck_pos = -1
    nb_types = AKIVehGetNbVehTypes()
    # Always log type names to file so we can diagnose non-English/coded type names
    log_to_file(f"[VEH SCAN] Total vehicle types: {nb_types}")
    for pos in range(1, nb_types + 1):
        name_str = _vehicle_type_name(pos)
        log_to_file(f"[VEH SCAN]   type pos={pos} name='{name_str}'")
        if not name_str:
            log_to_file(
                f"[VEH SCAN]   WARNING pos={pos} name unresolvable — "
                f"will rely on PT-line inference for bus type"
            )
        if bus_pos <= 0 and any(x in name_str for x in ("bus", "transit", "pt", "autobus", "ligne", "omnibus")):
            bus_pos = pos
        elif truck_pos <= 0 and any(x in name_str for x in ("truck", "heavy", "hgv", "lgv", "goods", "freight")):
            truck_pos = pos
        elif car_pos <= 0 and any(x in name_str for x in ("car", "pv", "private", "auto", "vehicle", "voiture", "pkw")):
            car_pos = pos
    return car_pos, bus_pos, truck_pos


def _infer_bus_type_pos_from_pt():
    """
    Infer the bus vehicle-type position by counting vehicle types on PT lines.
    Also tries AKIPTGetVehTypeOfLine (faster; available in some SDK versions).
    Returns the most common type position seen on PT lines, or -1 if none found.
    """
    counts = collections.Counter()

    try:
        n_lines = AKIPTGetNumberLines()
    except Exception:
        n_lines = 0

    for li in range(n_lines):
        try:
            line_id = AKIPTGetIdLine(li)
        except Exception:
            continue

        # Fast path: ask the line directly for its vehicle type (SDK 22+)
        # Wrapped in getattr so it fails silently if this API isn't available.
        try:
            _fn = globals().get("AKIPTGetVehTypeOfLine")
            if _fn is not None:
                vt = _fn(line_id)
                if vt > 0:
                    counts[int(vt)] += 10   # weight fast-path hits
                    continue
        except Exception:
            pass

        # Slow path: iterate vehicles on the line
        try:
            n_veh = AKIGetNbVehiclesFollowingPTLine(line_id)
        except Exception:
            continue
        for vi in range(n_veh):
            try:
                veh_id = AKIGetVehicleFollowingPTLine(line_id, vi)
                inf = AKIPTVehGetInf(veh_id)
                if getattr(inf, 'report', -1) >= 0 and getattr(inf, 'type', -1) > 0:
                    counts[int(inf.type)] += 1
            except Exception:
                continue

    return counts.most_common(1)[0][0] if counts else -1


def _build_pt_line_corridor_routes():
    """
    Build route-aware maps so coordination only targets junctions a bus will
    actually visit, using its filed PT plan from the Aimsun model.

    Populates four module-level dicts:
      _corridor_jct_incoming  {jct_id: set(section_ids)}  ← approach sections per junction
      _sec_to_corridor_jct    {section_id: [jct_id, ...]} ← reverse map
      _pt_line_section_set    {line_id: set(section_ids)}  ← every section on that PT line
      _pt_line_jct_route      {line_id: [jct_id, ...]}    ← ordered corridor junctions the
                                                              line passes through

    Called once from AAPISimulationReady after corridor positions are set.
    """
    global _corridor_jct_incoming, _sec_to_corridor_jct, _pt_line_section_set, _pt_line_jct_route

    # ── Step 1: build junction → incoming-section map from live controllers ───
    jct_incoming: dict = {}
    for jct_id, ctrl in controllers.items():
        secs = set()
        # primary approach sections (main corridor + topology fallback)
        for s in getattr(ctrl, 'incoming_sections', []):
            if isinstance(s, int) and s > 0:
                secs.add(s)
        # also include side sections so a bus using a side approach is caught
        for s in getattr(ctrl, 'side_sections', []):
            if isinstance(s, int) and s > 0:
                secs.add(s)
        if secs:
            jct_incoming[jct_id] = secs

    _corridor_jct_incoming = jct_incoming

    # ── Step 2: reverse map — section → which corridor junctions it feeds ─────
    sec_to_jct: dict = {}
    for jct_id, secs in jct_incoming.items():
        for sec_id in secs:
            sec_to_jct.setdefault(sec_id, []).append(jct_id)

    _sec_to_corridor_jct = sec_to_jct

    # ── Step 3: iterate every PT line, build section set + ordered jct list ───
    line_section_set: dict = {}
    line_jct_route: dict = {}

    try:
        n_lines = int(AKIPTGetNumberLines())
    except Exception:
        n_lines = 0

    for li in range(n_lines):
        try:
            line_id = AKIPTGetIdLine(li)
        except Exception:
            continue
        if line_id <= 0:
            continue

        try:
            n_secs = int(AKIPTGetNumberSectionsInLine(line_id))
        except Exception:
            n_secs = 0

        secs_on_line: list = []
        for si in range(n_secs):
            try:
                sec_id = int(AKIPTGetIdSectionInLine(line_id, si))
                if sec_id > 0:
                    secs_on_line.append(sec_id)
            except Exception:
                continue

        line_section_set[line_id] = set(secs_on_line)

        # Walk sections in route order; record the first time each corridor
        # junction is encountered (avoids double-counting loops)
        seen_jcts: set = set()
        ordered_jcts: list = []
        for sec_id in secs_on_line:
            for jct_id in sec_to_jct.get(sec_id, []):
                if jct_id not in seen_jcts:
                    seen_jcts.add(jct_id)
                    ordered_jcts.append(jct_id)

        if ordered_jcts:
            line_jct_route[line_id] = ordered_jcts

    _pt_line_section_set = line_section_set
    _pt_line_jct_route   = line_jct_route

    total_lines  = len(line_jct_route)
    total_routes = sum(len(v) for v in line_jct_route.values())
    log_to_file(
        f"[PT-ROUTE] Built corridor route map: {total_lines} PT lines cross "
        f"corridor junctions | {total_routes} (line,jct) pairs | "
        f"corridor junctions covered: "
        + str(sorted(jct_incoming.keys()))
    )


def _log_startup_bus_demand_snapshot(label: str = "init"):
    """
    Log a single startup snapshot of PT-line bus demand visibility.

    Includes:
      - PT line count
      - total PT-line vehicle entries
      - unique PT vehicle ids
      - unique vehicles matching inferred bus type
    """
    try:
        _n_lines = int(AKIPTGetNumberLines())
    except Exception:
        _n_lines = 0

    _all_ids = set()
    _bus_ids = set()
    _entries = 0

    _bus_type = int(getattr(stats, '_bus_pos', -1) or -1)
    if _bus_type <= 0:
        try:
            _bus_type = int(_infer_bus_type_pos_from_pt() or -1)
        except Exception:
            _bus_type = -1

    for _li in range(_n_lines):
        try:
            _line_id = AKIPTGetIdLine(_li)
            _n = int(AKIGetNbVehiclesFollowingPTLine(_line_id))
        except Exception:
            continue
        _entries += max(_n, 0)
        for _vi in range(max(_n, 0)):
            try:
                _vid = int(AKIGetVehicleFollowingPTLine(_line_id, _vi))
                if _vid <= 0:
                    continue
                _all_ids.add(_vid)
                _inf = AKIPTVehGetInf(_vid)
                _typ = int(getattr(_inf, 'type', -1) or -1)
                if _bus_type > 0 and _typ == _bus_type:
                    _bus_ids.add(_vid)
            except Exception:
                continue

    log_to_file(
        f"[DEMAND] startup snapshot ({label}) | pt_lines={_n_lines} "
        f"pt_entries={_entries} unique_pt_veh={len(_all_ids)} "
        f"bus_type_pos={_bus_type} unique_bus_veh={len(_bus_ids)}",
        force=True,
    )


def _choose_car_type_pos(bus_pos, truck_pos, preferred_pos=-1):
    nb_types = AKIVehGetNbVehTypes()
    exclude = {p for p in (bus_pos, truck_pos) if p and p > 0}
    if preferred_pos > 0 and preferred_pos not in exclude:
        return preferred_pos
    for pos in range(1, nb_types + 1):
        if pos in exclude:
            continue
        name_str = _vehicle_type_name(pos)
        if any(x in name_str for x in ("car", "pv", "private", "auto")):
            return pos
    for pos in range(1, nb_types + 1):
        if pos not in exclude:
            return pos
    return -1




class BusKalmanTracker:
    """
    State vector: [position_m, speed_m_s]
    Transition:   constant-velocity model  (F = [[1, dt], [0, 1]])
    Observation:  position only            (H = [1, 0])
    """

    DEFAULT_SPEED_MS = 11.0   # ≈ 40 km/h initial speed prior

    def __init__(self, initial_pos_m: float = 0.0):
        self.x = np.array([initial_pos_m, self.DEFAULT_SPEED_MS], dtype=float)
        self.P = np.diag([400.0, 16.0])     # initial state covariance (pos±20m, spd±4m/s)
        # Process noise: Q scales with dt inside predict().
        # q_pos=3 m²/s (bus can jerk, stop at lights), q_spd=0.5 m²/s³ (acceleration noise)
        self.Q = np.diag([3.0, 0.5])
        # Observation noise: std≈30 m accounts for detector placement uncertainty
        # A larger R makes predictions less sensitive to individual position fixes
        # and keeps speed estimates smooth across multiple junctions.
        self.R = 900.0
        self.last_t: float = None
        # Track the corridor-group index of the last junction this bus was seen at.
        # Used by the coordinator to determine travel direction.
        self._prev_inter_idx: int = -1

    def predict(self, dt: float):
        dt = max(dt, 0.0)
        F  = np.array([[1.0, dt], [0.0, 1.0]])
        self.x = F @ self.x
        self.P = F @ self.P @ F.T + self.Q * dt

    def update(self, obs_pos_m: float):
        H    = np.array([1.0, 0.0])
        innov = obs_pos_m - self.x[0]
        S    = float(H @ self.P @ H) + self.R
        K    = self.P @ H / S
        self.x = self.x + K * innov
        self.P = (np.eye(2) - np.outer(K, H)) @ self.P
        # Clamp speed to plausible urban bus range [4, 20] m/s (14–72 km/h)
        # A tighter clamp prevents numerical drift and keeps ETAs realistic.
        self.x[1] = max(4.0, min(20.0, abs(self.x[1]))) * (1.0 if self.x[1] >= 0 else -1.0)

    def update_speed_from_travel(self, prev_pos_m: float, curr_pos_m: float,
                                  elapsed_s: float):
        """
        When a bus reaches a new junction we have a direct measurement of
        average speed over the inter-junction segment.  Fuse that observation
        into the state as a second Kalman update step.

        This is far more informative than position-only updates because it
        corrects the velocity component directly, leading to better ETAs at
        the next downstream junction.
        """
        if elapsed_s < 5.0:
            return   # avoid division by near-zero if timestamps are too close
        actual_speed = (curr_pos_m - prev_pos_m) / elapsed_s   # signed m/s
        # Clamp to plausible range before fusing
        actual_speed = max(4.0, min(20.0, abs(actual_speed))) * (1.0 if actual_speed >= 0 else -1.0)
        # Kalman update for speed observation:  H_v = [0, 1]
        H_v   = np.array([0.0, 1.0])
        R_v   = 4.0                                # speed obs noise var (std ≈ 2 m/s)
        innov = actual_speed - self.x[1]
        S_v   = float(H_v @ self.P @ H_v) + R_v
        K_v   = self.P @ H_v / S_v
        self.x = self.x + K_v * innov
        self.P = (np.eye(2) - np.outer(K_v, H_v)) @ self.P
        # Re-clamp after speed update
        self.x[1] = max(4.0, min(20.0, abs(self.x[1]))) * (1.0 if self.x[1] >= 0 else -1.0)

    def eta(self, target_pos_m: float, current_time: float) -> float:
        """
        Estimated arrival time (sim seconds) at target_pos_m.
        Handles both northbound (velocity > 0) and southbound (velocity < 0).
        Returns a very large number if the bus is moving away from the target.
        """
        dist  = target_pos_m - self.x[0]   # positive = target is ahead (north)
        speed = self.x[1]                   # positive = northbound
        if abs(dist) < 1.0:
            return current_time             # already at target
        if speed > 0 and dist > 0:          # northbound, target ahead
            return current_time + dist / speed
        if speed < 0 and dist < 0:          # southbound, target behind
            return current_time + abs(dist) / abs(speed)
        # Bus heading away from target — effectively unreachable
        return current_time + 99999.0

    def uncertainty_s(self, target_pos_m: float) -> float:
        """1-sigma arrival-time uncertainty (seconds)."""
        dist  = abs(target_pos_m - self.x[0])
        speed = max(abs(self.x[1]), 1.0)
        # propagate position and speed variance to time variance
        var_t = self.P[0, 0] / speed**2 + self.P[1, 1] * (dist / speed**2)**2
        return math.sqrt(max(var_t, 0.0))


# =============================================================================
# CORRIDOR COORDINATOR
# Groups of intersections on the same corridor run their GroupBasedControllers
# in a coordinated way.
#
# When COORDINATED_TSP=False (default): pure state-sync logging only.
# When COORDINATED_TSP=True: Kalman-filter prediction arms downstream
#   intersections before the bus arrives, creating a rolling green wave.
#
# Coordination flow (COORDINATED_TSP=True):
#   1. Bus gets priority at intersection[i]  →  GroupBasedController calls
#      coordinator.notify_bus_granted(veh_id, jct_i, time, bus_sg)
#   2. Coordinator updates the Kalman tracker for that vehicle and predicts
#      arrival ETA at jct[i+1], [i+2], [i+3]
#   3. Each step(), when (ETA - current_time) ≤ PRE_GREEN_LEAD_S, the
#      coordinator fires bus_request on that downstream controller so it
#      has a green phase ready on arrival.
# =============================================================================

class CorridorCoordinator:
    """
    Corridor Coordinator (CC) — links junctions along a bus route so that
    a priority grant at junction[i] automatically pre-arms junction[i+1..n].

    How it works
    ------------
    1. Bus detected at junction[i] → CC is notified via notify_bus_at_junction().
    2. CC computes an ETA for each downstream junction using the configured
       COORDINATION_ALGO (KALMAN / SHOCKWAVE / OBJECTIVE / ADAPTIVE).
    3. When ETA - PRE_GREEN_LEAD_S is reached, CC fires a pre-arm request on
       the downstream junction's GroupBasedController (or sets _harmony_prearm
       on a phase-based IntersectionController).
    4. The downstream junction holds its bus phase ready so the bus arrives
       into green rather than red.
    5. Pre-arm requests expire after PRE_REQ_TIMEOUT_S if the bus is delayed
       or diverts; the junction then returns to its normal cycle.
    """

    LOG_CORRIDOR_INTERVAL = 30.0   # seconds between periodic state dumps
    # ── Pre-arm lead time ─────────────────────────────────────────────────────
    # How many seconds before estimated bus arrival to fire the pre-arm request.
    # Must be large enough for the downstream junction to:
    #   (a) finish its current phase (worst-case ~50 s for long cycles)
    #   (b) execute intergreen (~5 s)
    #   (c) ramp up its bus phase before the bus reaches the stop line
    # 25 s was too short — a junction mid-phase routinely has 30–50 s remaining,
    # so the bus arrived before the phase could be set up, defeating coordination.
    # 50 s covers worst-case phase-remaining + intergreen for all Logan Rd junctions.
    PRE_GREEN_LEAD_S          = 50.0
    MIN_EFFECTIVE_PREARM_LEAD_S = 10.0  # discard prearm if bus is already this close
    MAX_PRE_ARM               = 1      # pre-arm only the immediately next junction
    PRE_REQ_TIMEOUT_S         = 90.0   # stale pre-request expiry
    MIN_UNMANAGED_DELAY_S = 10.0   # delay buffer per unmanaged in-system junction
    MAX_UNMANAGED_DELAY_S = 25.0

    def __init__(self, group_name: str, inter_ids: list, controllers_map: dict):
        self.name = group_name
        # GB controllers (GROUP_BASED_* modes) — full coordination support.
        self.inter_ids = [
            iid for iid in inter_ids
            if iid in controllers_map and controllers_map[iid].gb is not None
        ]
        self._ctrl_map = {iid: controllers_map[iid].gb for iid in self.inter_ids}

        # HARMONY IntersectionControllers — simplified coordination support.
        # Indexed by inter_id → IntersectionController (no gb attribute).
        # pre-arm sets _harmony_prearm on the controller; check_bus_priority handles it.
        self._ic_map: dict = {
            iid: controllers_map[iid]
            for iid in inter_ids
            if iid in controllers_map and controllers_map[iid].gb is None
        }
        # Merged inter_ids includes both GB and IC intersections
        self.inter_ids = list(dict.fromkeys(self.inter_ids + list(self._ic_map.keys())))
        route_ids = list(CORRIDOR_ROUTE_GROUPS.get(group_name, inter_ids))
        self.route_inter_ids = []
        for iid in route_ids:
            if iid in INTERSECTIONS_CONFIG or iid in self.inter_ids:
                self.route_inter_ids.append(iid)
        for iid in self.inter_ids:
            if iid not in self.route_inter_ids:
                self.route_inter_ids.append(iid)
        self._route_index = {iid: idx for idx, iid in enumerate(self.route_inter_ids)}
        self._last_log_t   = -self.LOG_CORRIDOR_INTERVAL
        self._last_sync_t  = -999.0
        self._sync_count   = 0

        # Kalman tracking state
        # {veh_id: BusKalmanTracker}
        self._trackers: dict = {}
        # Corridor positions along the route (metres from first intersection)
        # Populated by set_corridor_positions() in AAPISimulationReady.
        self.corridor_pos: dict = {}
        # Pre-green requests: {inter_id: (veh_id, eta_t, bus_sg, issued_t, source_jct)}
        self._pre_requests: dict = {}
        self._pre_arm_count: int = 0

        # ── Coord-prearm outcome statistics ───────────────────────────────────
        # Answers "did the coordinator actually deliver a green wave?"
        # Key metrics:
        #   fired    — pre-arm request was set on downstream gb.bus_request
        #   success  — bus physically arrived at that junction during green phase
        #              (logged by GroupBasedController when it activates a coord-sourced request)
        #   missed   — pre-arm fired but bus was still in red on arrival
        #              (this happens when ETA is off or phase didn't have time to cycle)
        #   expired  — pre-request timed out (bus took a different route or was delayed > PRE_REQ_TIMEOUT_S)
        #   discarded— pre-arm fired but GB discarded it (cooldown, no bus_sg, wrong state)
        #   eta_errors_s — list of (actual_arrival − predicted_eta) values, for calibration
        #                  positive = bus arrived later than predicted
        #                  negative = bus arrived earlier than predicted
        self._prearm_stats: dict = {
            "fired":        0,
            "success":      0,
            "missed":       0,
            "expired":      0,
            "discarded":    0,
            "late_success": 0,
            "late_success_delay_s": 0.0,
            "eta_errors_s": [],
        }
        # Tracking: {(inter_id, veh_id): (eta_t, fired_at_t)} for outcome reporting
        self._fired_prearms: dict = {}
        # Lightweight diagnostics to confirm whether algorithm variants are
        # changing queue ETA and pre-arm lead decisions in practice.
        self._algo_diag: dict = {
            "queued": 0,
            "sw_adj_count": 0,
            "sw_adj_total_s": 0.0,
            "sw_adj_max_s": 0.0,
            "adaptive_fire_count": 0,
            "adaptive_dynamic_count": 0,
            "adaptive_lead_total_s": 0.0,
            "adaptive_lead_min_s": 1e9,
            "adaptive_lead_max_s": 0.0,
        }

        # ── Coordination wave state ───────────────────────────────────────────
        # When a bus is granted priority at any corridor junction a "wave" begins.
        # During the wave ALL other junctions block INDEPENDENT bus detections;
        # only coordinator-fired (pre-armed) requests are allowed through.
        # The ban lifts once all pre-requests for that wave vehicle have resolved.
        #
        # _wave_active     : True while a green-wave is in progress
        # _wave_veh_id     : vehicle that triggered the wave
        # _wave_origin     : junction ID where the wave started
        # _wave_served_ids : junctions that have already been pre-armed this wave
        #                    (once served, ban lifts individually for that junction)
        self._wave_active:     bool  = False
        self._wave_veh_id:     int   = -1
        self._wave_origin:     int   = -1
        self._wave_served_ids: set   = set()
        # Junctions where sigma was too high to pre-arm — wave ban is lifted so
        # they can run independent detection instead of waiting for a stale prearm.
        self._wave_uncertain_jcts: set = set()
        # Logged once per (from_jct, target_jct) pair when sigma or horizon gate
        # blocks a pre-arm.  Prevents log spam while keeping diagnostics visible.
        self._prearm_skip_logged_jcts: set = set()

        log_to_file(
            f"[CORRIDOR] group={self.name} members={self.inter_ids} "
            f"route={self.route_inter_ids} "
            f"(GB={len(self._ctrl_map)} IC-HARMONY={len(self._ic_map)} "
            f"of {len(inter_ids)} configured) "
            f"coordinated_tsp={COORDINATED_TSP}"
        )

        # Wire back-reference into each GB controller so it can call
        # notify_bus_granted() without needing the global list.
        for gb in self._ctrl_map.values():
            gb._corridor_coord = self
        # Wire back-reference into HARMONY IntersectionControllers too.
        for ic in self._ic_map.values():
            ic._corridor_coord = self

        # ── Per-bus grant time tracker (for offset computation) ──────────────────────
        # {veh_id: {jct_id: sim_time_s}} — updated in notify_bus_granted.
        self._grant_times: dict = {}
        # {(veh_id, jct_id): last_logged_time_s} — suppress duplicate log rows
        self._last_offset_logged: dict = {}
        # {(veh_id, jct_id): last_notify_t} — debounce repeated grant callbacks
        # from the same junction while a bus is still in the same detection zone.
        self._last_grant_notify_t: dict = {}

    # ------------------------------------------------------------------
    def _shockwave_eta_adjust(self, next_gb, next_bus_sg, eta: float, next_ic=None):
        """
        Queue-aware ETA correction using shockwave discharge logic.

        Uses the PREDICTED peak queue from the intersection's own shockwave
        model (MaxQueueLength, already computed from UpFlowList + shockwave
        speeds) rather than the live vehicle count.  The live count is always
        0 at pre-arm time (the bus hasn't arrived yet), which is why the old
        implementation never produced a non-zero correction.

        Falls back to live queue count if the model has no estimate yet.
        For HARMONY intersections (next_gb=None, next_ic set), uses live
        vehicle counts on approach sections as a queue proxy.

        Returns
        -------
        (eta_adj, queue_len_veh, eta_delta, sw_diag)
        """
        # Default parameters
        sat_flow  = 1800.0
        jam_den   = 150.0
        sat_den   = 45.0
        headway_s = 2.0
        n_lanes = 1
        sw_diag = {
            "sat_flow_vph": sat_flow,
            "jam_den_vpkm": jam_den,
            "sat_den_vpkm": sat_den,
            "headway_s": headway_s,
            "queue_len_veh": 0.0,
            "queue_clearance_s": 0.0,
            "wave_delay_s": 0.0,
            "shockwave_w4_ms": 0.0,
            "queue_len_m": 0.0,
        }

        if next_gb is not None:
            try:
                sat_flow = max(getattr(next_gb, 'SaturationFlow', 1800.0), 100.0)
                jam_den  = max(getattr(next_gb, 'JamDensity',     150.0),  10.0)
                sat_den  = max(getattr(next_gb, 'SaturationDensity', 45.0), 5.0)
                n_lanes  = max(getattr(next_gb, 'NumberOfLanes',    1),       1)
                headway_s = max(1.2, 3600.0 / sat_flow)
                sw_diag.update({
                    "sat_flow_vph": sat_flow,
                    "jam_den_vpkm": jam_den,
                    "sat_den_vpkm": sat_den,
                    "headway_s": headway_s,
                    "n_lanes": float(n_lanes),
                })

                bus_phase = getattr(next_gb, 'bus_phase', None)
                phase_idx = 0
                if bus_phase is not None and hasattr(next_gb, 'PhaseIndex'):
                    phase_idx = next_gb.PhaseIndex.get(bus_phase, 0)

                mql = getattr(next_gb, 'MaxQueueLength', None)
                queue_len = 0
                if mql is not None and phase_idx < len(mql) and len(mql[phase_idx]) > 0:
                    max_queue_m = float(mql[phase_idx][0])
                    if max_queue_m > 0.5:
                        queue_len = max(1, int(max_queue_m * jam_den / 1000.0 * n_lanes))

                if queue_len <= 0:
                    q = next_gb._compute_queue()
                    queue_len = max(int(q.get(next_bus_sg, 0)), 0)

                if queue_len <= 0:
                    try:
                        q_all = next_gb._compute_queue()
                        queue_len = max((int(v or 0) for v in q_all.values()), default=0)
                    except Exception:
                        queue_len = 0
            except Exception:
                queue_len = 0

        elif next_ic is not None:
            # HARMONY IntersectionController — no GB, use section vehicle counts
            try:
                queue_len = 0
                headway_s = 2.0
                # Count stopped/slow vehicles on approach sections as queue proxy
                for sec_id in getattr(next_ic, 'incoming_sections', []):
                    try:
                        n_veh = max(int(AKIVehStateGetNbVehiclesSection(sec_id, True)), 0)
                        stopped = 0
                        for vi in range(n_veh):
                            try:
                                vinf = AKIVehStateGetVehicleInfSection(sec_id, vi)
                                spd = float(getattr(vinf, 'CurrentSpeed', 0.0) or 0.0)
                                if spd < 5.0:  # km/h — effectively queued
                                    stopped += 1
                            except Exception:
                                continue
                        queue_len += stopped
                    except Exception:
                        continue
            except Exception:
                queue_len = 0
        else:
            return eta, 0, 0.0, sw_diag

        if queue_len <= 0:
            return eta, 0, 0.0, sw_diag

        try:
            # queue_clearance_s: time for all queued vehicles to pass the stopline
            # at saturation flow (simple headway model).
            queue_clearance_s = queue_len * headway_s

            # wave_delay_s: time for the discharge wave to travel back through
            # the entire queue to the bus.
            #   queue_distance_m = queue_len / jam_den_per_m
            #   discharge_wave_speed_ms = ShockwaveSpeed4 (m/s)
            # NOTE: ShockwaveSpeed4 already returns m/s (not km/h), so no
            # extra unit conversion is needed.  The old formula
            # "queue_len / w4 / (jam_den-sat_den) * 1000" was wrong — it
            # double-divided by density and produced the same value as
            # queue_clearance_s, giving an artificially large sw_adj.
            w4 = abs(ShockwaveSpeed4(sat_flow, jam_den, sat_den))  # m/s
            queue_m = queue_len * 1000.0 / max(jam_den, 1.0)       # m
            wave_delay_s = queue_m / max(w4, 0.001)                 # s

            # Use the smaller of the two estimates; cap at 30 s so a single
            # pre-arm event cannot create an excessively long insertion.
            eta_delta = min(queue_clearance_s, wave_delay_s, 30.0)
            sw_diag.update({
                "queue_len_veh": float(queue_len),
                "queue_clearance_s": float(queue_clearance_s),
                "wave_delay_s": float(wave_delay_s),
                "shockwave_w4_ms": float(w4),
                "queue_len_m": float(queue_m),
            })
            return eta + eta_delta, queue_len, eta_delta, sw_diag
        except Exception:
            return eta, 0, 0.0, sw_diag

    # ------------------------------------------------------------------
    def _record_prearm_fired(self, inter_id: int, veh_id: int, eta_t: float,
                             fired_at_t: float, source_jct: int = -1,
                             algo: str = "", lead_reason: str = ""):
        # Do NOT overwrite an existing active prearm entry.  Once a prearm has
        # been fired for a (junction, bus) pair, keep the original eta/fired_t
        # so that _record_prearm_success (which pops the entry) only logs
        # ONE success per logical prearm event.  Re-overwriting here would let
        # the coordinator re-populate the entry every management step, causing
        # prearm_success to fire on every subsequent notify_bus_granted call.
        key = (inter_id, veh_id)
        if key in self._fired_prearms:
            return  # already pending — skip (deduplication)
        self._prearm_stats["fired"] += 1
        self._fired_prearms[key] = (
            float(eta_t), float(fired_at_t), int(source_jct),
            str(algo or COORDINATION_ALGO), str(lead_reason or "fixed")
        )
        # Lift the wave ban for this junction as soon as its prearm is committed.
        # Without this the junction stays banned until notify_bus_granted fires,
        # which may never happen if the coordinator never re-arms it.
        self._wave_served_ids.add(inter_id)
        # Deduplicate: only write a wave event if no recent prearm_fired was written
        # for this (veh_id, inter_id) pair within 60 s.  Prevents wave-event CSV spam
        # when the coordinator re-evaluates ETA on every step while a bus is in transit.
        if not hasattr(self, '_prearm_fired_log_t'):
            self._prearm_fired_log_t = {}
        _fire_key = (veh_id, inter_id)
        _last_log = self._prearm_fired_log_t.get(_fire_key, -999.0)
        if fired_at_t - _last_log < 60.0:
            return   # suppress duplicate within 60 s window
        self._prearm_fired_log_t[_fire_key] = fired_at_t
        _src = int(source_jct) if int(source_jct) > 0 else int(self._wave_origin)
        _algo = str(algo or COORDINATION_ALGO)
        _record_wave_event(
            fired_at_t, self.name, "prearm_fired",
            source_jct=_src,
            target_jct=inter_id,
            veh_id=veh_id,
            eta_s=max(0.0, float(eta_t) - float(fired_at_t)),
            note=str(lead_reason or "fixed"),
            algo=_algo,
        )

    # ------------------------------------------------------------------
    def _record_prearm_discarded(self, inter_id: int):
        self._prearm_stats["discarded"] += 1
        _record_wave_event(
            AKIGetCurrentSimulationTime(), self.name, "prearm_discarded",
            source_jct=self._wave_origin,
            target_jct=inter_id,
            veh_id=self._wave_veh_id,
        )

    # ------------------------------------------------------------------
    def _record_prearm_success(self, inter_id: int, veh_id: int, actual_t: float):
        key = (inter_id, veh_id)
        rec = self._fired_prearms.pop(key, None)
        if rec is None:
            return
        eta_t = float(rec[0])
        _fired_t = float(rec[1])
        _source_jct = int(rec[2]) if len(rec) >= 3 else int(self._wave_origin)
        _algo = str(rec[3]) if len(rec) >= 4 else str(COORDINATION_ALGO)
        self._prearm_stats["success"] += 1
        eta_err_s = float(actual_t) - float(eta_t)
        self._prearm_stats["eta_errors_s"].append(eta_err_s)
        if eta_err_s > 0.0:
            self._prearm_stats["late_success"] += 1
            self._prearm_stats["late_success_delay_s"] += eta_err_s
        _record_wave_event(
            actual_t, self.name, "prearm_success",
            source_jct=_source_jct,
            target_jct=inter_id,
            veh_id=veh_id,
            eta_s=eta_err_s,
            note=("late" if eta_err_s > 0.0 else "on_time_or_early"),
            algo=_algo,
        )
        _xy = (_jct_xy_cache or {}).get(inter_id, (0.0, 0.0))
        _mark_detection_point(
            inter_id, veh_id, _xy[0], _xy[1], actual_t,
            f"coord-prearm-success/{COORDINATION_ALGO}",
            {
                "force_write": True,
                "prearm_status": "success",
                "prearm_eta_s": round(max(0.0, float(eta_t) - float(_fired_t)), 1),
                "prearm_eta_abs_s": round(float(eta_t), 1),
                "prearm_fired_t": round(float(_fired_t), 1),
                "prearm_resolved_t": round(float(actual_t), 1),
                "prearm_note": (
                    f"{_algo}:late" if eta_err_s > 0.0 else f"{_algo}:on_time_or_early"
                ),
            },
        )

    # ------------------------------------------------------------------
    def _expire_fired_prearms(self, time: float):
        """Close unresolved fired pre-arms as misses after ETA grace period."""
        # 50 s grace: handles buses that are ~50 s slower than predicted
        # (e.g., Kalman over-estimated speed, bus caught at an unmanaged junction).
        # 30 s was too tight — buses 35 s late had their prearm expire just before arrival.
        grace_s = 50.0
        stale = []
        for key, rec in self._fired_prearms.items():
            eta_t = float(rec[0])
            _fired_t = float(rec[1])
            _source_jct = int(rec[2]) if len(rec) >= 3 else int(self._wave_origin)
            _algo = str(rec[3]) if len(rec) >= 4 else str(COORDINATION_ALGO)
            if time > eta_t + grace_s:
                stale.append((key, eta_t, _source_jct, _algo))
        for key, eta_t, _source_jct, _algo in stale:
            inter_id, veh_id = key
            self._fired_prearms.pop(key, None)
            self._prearm_stats["missed"] += 1
            _record_wave_event(
                time, self.name, "prearm_missed",
                source_jct=_source_jct,
                target_jct=inter_id,
                veh_id=veh_id,
                note="arrival_after_eta_grace",
                algo=_algo,
            )
            _xy = (_jct_xy_cache or {}).get(inter_id, (0.0, 0.0))
            _mark_detection_point(
                inter_id, veh_id, _xy[0], _xy[1], time,
                f"coord-prearm-missed/{COORDINATION_ALGO}",
                {
                    "force_write": True,
                    "prearm_status": "missed",
                    "prearm_eta_abs_s": round(float(eta_t), 1),
                    "prearm_resolved_t": round(float(time), 1),
                    "prearm_note": f"{_algo}:arrival_after_eta_grace",
                },
            )

    # ------------------------------------------------------------------
    def set_corridor_positions(self, pos_map: dict):
        """
        Set corridor positions (metres from first intersection) for each member.
        Called from AAPISimulationReady once junction XY is available.
        pos_map: {inter_id: float}
        """
        self.corridor_pos = dict(pos_map)
        log_to_file(
            f"[CORRIDOR] group={self.name} corridor positions set: "
            + ", ".join(f"{iid}:{pos:.0f}m" for iid, pos in sorted(pos_map.items()))
        )

    # ------------------------------------------------------------------
    def _iter_managed_targets(self, at_inter_id: int, is_northbound: bool,
                              veh_id: int = -1) -> list:
        """
          Return the immediate next managed intersection in corridor route order
          that this bus will actually visit.

        Priority:
          1. Bus's filed PT route (from _pt_line_jct_route via _bus_line_id).
                 Only the next managed junction explicitly in the bus's route is
                 returned — so a bus not stopping at junction X won't trigger a
                 pre-arm there, and long-range predictions are avoided.
          2. Geographic corridor order (_route_index / inter_ids) — fallback
             when the bus's PT route is unknown.
        """
        managed = set(self.inter_ids)

        # ── Attempt PT-route-aware targeting ─────────────────────────────────
        if veh_id > 0:
            line_id = _bus_line_id.get(veh_id, -1)
            if line_id > 0:
                route_jcts = _pt_line_jct_route.get(line_id)  # [jct_id, ...] in route order
                if route_jcts:
                    # Find this junction in the bus's route
                    try:
                        my_route_pos = route_jcts.index(at_inter_id)
                    except ValueError:
                        my_route_pos = -1

                    if my_route_pos >= 0:
                        # Slice ahead (direction already known from route order)
                        ahead = route_jcts[my_route_pos + 1:]
                        targets = [j for j in ahead if j in managed][:1]
                        if LOG_CORRIDOR and targets:
                            log_to_file(
                                f"[PT-ROUTE TARGETS] bus={veh_id} line={line_id} "
                                f"jct={at_inter_id} → {targets} (from PT route)"
                            )
                        return targets
                    # Bus line is known but this junction is not on that route.
                    # Do NOT fall back to geographic targets, otherwise prearms can
                    # jump to unrelated intersections.
                    if LOG_CORRIDOR:
                        log_to_file(
                            f"[PT-ROUTE MISMATCH] bus={veh_id} line={line_id} "
                            f"jct={at_inter_id} not in route — suppress prearm"
                        )
                    return []

        # ── Fallback tier 2: observed-route targeting ─────────────────────────
        # Use the per-bus zone-enter history (_bus_observed_jcts) to determine
        # which corridor junctions this bus has already passed through.
        # If we can confirm which managed junctions are ALREADY BEHIND the bus,
        # we can safely pre-arm the next N in the same direction without risking
        # arming junctions the bus won't visit.
        #
        # Logic:
        #  • Collect all observed junctions for this bus in entry order.
        #  • Find at_inter_id in the observed sequence.
        #  • All junctions after it (in route_inter_ids order that match the
        #    observed direction) are candidate targets, but only the immediate
        #    next managed junction is returned.
        if veh_id > 0:
            observed = _bus_observed_jcts.get(veh_id, [])
            if len(observed) >= 1:
                # Build the corridor-position of each observed junction.
                obs_in_route = [j for j in observed if j in self._route_index]
                if obs_in_route:
                    # Determine direction from the sequence of observed junctions.
                    obs_route_indices = [self._route_index[j] for j in obs_in_route]
                    if len(obs_route_indices) >= 2:
                        # Direction is determined by the trend of route indices.
                        nb_votes = sum(1 for a, b in zip(obs_route_indices, obs_route_indices[1:]) if b > a)
                        sb_votes = len(obs_route_indices) - 1 - nb_votes
                        observed_is_nb = (nb_votes >= sb_votes)
                    else:
                        observed_is_nb = is_northbound  # trust caller when only 1 observed

                    at_route_idx = self._route_index.get(at_inter_id)
                    if at_route_idx is not None:
                        step = 1 if observed_is_nb else -1
                        idx = at_route_idx + step
                        targets = []
                        while 0 <= idx < len(self.route_inter_ids) and len(targets) < 1:
                            iid = self.route_inter_ids[idx]
                            if iid in managed:
                                targets.append(iid)
                            idx += step
                        if targets:
                            if LOG_CORRIDOR:
                                log_to_file(
                                    f"[OBS-ROUTE TARGETS] bus={veh_id} "
                                    f"observed={obs_in_route} dir={'NB' if observed_is_nb else 'SB'} "
                                    f"jct={at_inter_id} → {targets} (from observed route)"
                                )
                            return targets

        # ── Fallback tier 3: geographic corridor order (direction only) ───────
        # Last resort when neither PT route nor observed history is available.
        # Restrict to the IMMEDIATE next junction only to avoid arming junctions
        # the bus won't reach.  Once that junction grants and calls
        # notify_bus_granted, the next pre-arm will be queued with updated info.
        route_idx = self._route_index.get(at_inter_id)
        if route_idx is None:
            try:
                my_idx = self.inter_ids.index(at_inter_id)
            except ValueError:
                return []
            if is_northbound:
                return self.inter_ids[my_idx + 1:my_idx + 2]
            lo = max(0, my_idx - 1)
            return list(reversed(self.inter_ids[lo:my_idx]))

        step = 1 if is_northbound else -1
        idx = route_idx + step
        targets = []
        while 0 <= idx < len(self.route_inter_ids) and len(targets) < 1:
            iid = self.route_inter_ids[idx]
            if iid in managed:
                targets.append(iid)
            idx += step
        return targets

    # ------------------------------------------------------------------
    def _estimate_unmanaged_delay_s(self, inter_id: int) -> float:
        """Estimate expected delay at an unmanaged system junction."""
        cfg = INTERSECTIONS_CONFIG.get(inter_id, {}) or {}
        phase_durs = cfg.get("GreenPhaseDuration") or []
        cycle_s = 0.0
        try:
            cycle_s = sum(float(x) for x in phase_durs if x not in (None, ""))
        except Exception:
            cycle_s = 0.0

        bus_green_s = None
        try:
            bus_green_s = float(cfg.get("BusPhaseDuration"))
        except Exception:
            bus_green_s = None
        if bus_green_s in (None, 0.0) and phase_durs:
            try:
                bus_phase = int(cfg.get("BusPhase", 1) or 1)
                if 1 <= bus_phase <= len(phase_durs):
                    bus_green_s = float(phase_durs[bus_phase - 1])
            except Exception:
                bus_green_s = None

        if cycle_s > 0.0 and bus_green_s is not None:
            red_s = max(cycle_s - max(bus_green_s, 0.0), 0.0)
            return min(
                self.MAX_UNMANAGED_DELAY_S,
                max(self.MIN_UNMANAGED_DELAY_S, 0.35 * red_s),
            )

        return self.MIN_UNMANAGED_DELAY_S

    # ------------------------------------------------------------------
    def _route_gap_delay_s(self, from_inter_id: int, to_inter_id: int) -> float:
        """Return ETA slack for unmanaged intersections between two managed nodes."""
        from_idx = self._route_index.get(from_inter_id)
        to_idx = self._route_index.get(to_inter_id)
        if from_idx is None or to_idx is None or from_idx == to_idx:
            return 0.0

        lo, hi = sorted((from_idx, to_idx))
        managed = set(self.inter_ids)
        gap_delay_s = 0.0
        for iid in self.route_inter_ids[lo + 1:hi]:
            if iid in managed:
                continue
            gap_delay_s += self._estimate_unmanaged_delay_s(iid)
        return gap_delay_s

    # ------------------------------------------------------------------
    def is_wave_banned(self, inter_id: int) -> bool:
        """
        Return True if junction inter_id should block independent bus detections.

        A junction is banned when:
          • A coordination wave is active (COORDINATED_TSP=True)
          • The junction is not yet in _wave_served_ids
            (served = the coordinator has already pre-armed it this wave)

        Once the coordinator pre-arms junction[j] and the pre-request fires,
        junction[j] is added to _wave_served_ids and its ban is lifted so it
        can react normally to the pre-armed request.
        """
        if not COORDINATED_TSP or not self._wave_active:
            return False
        if inter_id in self._wave_uncertain_jcts:
            return False   # sigma too high to pre-arm — let independent detection run
        if inter_id in self._wave_served_ids:
            return False   # already served — ban lifted
        # Only ban the immediately queued next junction.
        # All other corridor junctions run independent TSP detection.
        return inter_id in self._pre_requests

    # ------------------------------------------------------------------
    def notify_bus_granted(self, veh_id: int, at_inter_id: int,
                           time: float, bus_sg=None):
        """
        Called by GroupBasedController._activate_for_bus when bus priority
        is activated at at_inter_id.  Updates the Kalman tracker and
        schedules pre-green requests at downstream intersections.
        Only active when COORDINATED_TSP=True and corridor positions are set.
        """
        if not COORDINATED_TSP or not self.corridor_pos:
            return

        at_pos = self.corridor_pos.get(at_inter_id)
        if at_pos is None:
            return

        # If this junction had an active pre-arm record for this bus, mark outcome.
        self._record_prearm_success(at_inter_id, veh_id, time)

        # Debounce grant spam from repeated natural-green checks at the same
        # junction. Without this, the same bus can retrigger notify_bus_granted()
        # every step and create contradictory direction flips + out-of-order
        # downstream pre-arms in the dashboard.
        _notify_key = (int(veh_id), int(at_inter_id))
        _last_notify_t = self._last_grant_notify_t.get(_notify_key, -9999.0)
        if (time - _last_notify_t) < 8.0:
            if LOG_CORRIDOR:
                log_to_file(
                    f"[CORRIDOR DEDUP] suppress notify bus={veh_id} jct={at_inter_id} "
                    f"dt={time - _last_notify_t:.1f}s"
                )
            return
        self._last_grant_notify_t[_notify_key] = float(time)

        # Track grants per bus. Keep a snapshot of prior grants for offset
        # computation; then record this grant immediately for downstream logic.
        _bus_grants = self._grant_times.setdefault(veh_id, {})
        _prev_grants = dict(_bus_grants)
        _bus_grants[at_inter_id] = time

        # Update (or create) Kalman tracker for this vehicle
        tracker = self._trackers.get(veh_id)
        _tracker_is_new = (tracker is None)
        if tracker is None:
            tracker = BusKalmanTracker(initial_pos_m=at_pos)
            self._trackers[veh_id] = tracker
        else:
            prev_pos = tracker.x[0]
            prev_t   = tracker.last_t
            if prev_t is not None:
                tracker.predict(max(time - prev_t, 0.0))
            tracker.update(at_pos)
            # Fuse direct speed measurement from inter-junction travel time
            if prev_t is not None and prev_t < time:
                tracker.update_speed_from_travel(prev_pos, at_pos, time - prev_t)
        tracker.last_t = time

        # ── Determine travel direction from junction-sequence history ──────────
        my_idx = self._route_index.get(at_inter_id, -1)
        if my_idx < 0:
            return

        prev_idx = tracker._prev_inter_idx
        if prev_idx >= 0 and prev_idx != my_idx:
            # We know which junction the bus came from → reliable direction
            is_northbound = (my_idx > prev_idx)
            # Align Kalman velocity sign with observed direction
            spd = abs(tracker.x[1])
            tracker.x[1] = spd if is_northbound else -spd
        else:
            # First detection in this corridor — assume northbound (positive velocity)
            is_northbound = (tracker.x[1] >= 0)
        tracker._prev_inter_idx = my_idx

        # ── Compute and log green-wave offset from previous junction ────────────────
        _at_idx = self._route_index.get(at_inter_id, -1)
        _prev_candidates = []
        for j, t in _prev_grants.items():
            _j_idx = self._route_index.get(j, -1)
            if _j_idx < 0:
                continue
            if is_northbound:
                if _j_idx < _at_idx:
                    _prev_candidates.append((_j_idx, j, t))
            else:
                if _j_idx > _at_idx:
                    _prev_candidates.append((_j_idx, j, t))

        if _prev_candidates:
            if is_northbound:
                _, _prev_jct, _prev_t = max(_prev_candidates, key=lambda x: x[0])
            else:
                _, _prev_jct, _prev_t = min(_prev_candidates, key=lambda x: x[0])

            _offset_s  = time - _prev_t
            # Fix: corridor_pos for the first junction is 0.0 (falsy), so use
            # an explicit None-check instead of `or at_pos`.
            _prev_pos = self.corridor_pos.get(_prev_jct)
            _dist_m   = abs(at_pos - (_prev_pos if _prev_pos is not None else at_pos))
            # Speed sanity: if implied speed >25 m/s (90 km/h) or offset <5 s,
            # this is almost certainly a wave/pre-arm grant, not an actual traversal.
            _speed_est_raw = _dist_m / max(_offset_s, 0.1)
            _quality   = ("wave/pre-arm" if (_offset_s < 5.0 or _speed_est_raw > 25.0)
                          else "observed")
            # For readability in logs/plots, cap displayed speed to a plausible
            # urban bus range; keep the raw value for diagnostics.
            _speed_est_eff = min(max(_speed_est_raw, 0.0), 20.0)
            _speed_flag = "capped" if _speed_est_raw > 20.0 else "ok"
            # Suppress duplicate log rows: only log if grant time changed since last log.
            _log_key = (veh_id, at_inter_id)
            _last_logged_t = self._last_offset_logged.get(_log_key, -999.0)
            _should_log = (abs(time - _last_logged_t) > 1.0)
            if _should_log:
                self._last_offset_logged[_log_key] = time
                log_to_file(
                    f"[GREEN_OFFSET] bus={veh_id} "
                    f"jct{_prev_jct}->{at_inter_id} "
                    f"offset={_offset_s:.1f}s dist={_dist_m:.0f}m "
                    f"speed_eff={_speed_est_eff:.1f}m/s speed_raw={_speed_est_raw:.1f}m/s "
                    f"[{_quality}|{_speed_flag}|{'NB' if is_northbound else 'SB'}] "
                    f"(grant_prev={_prev_t:.1f}s grant_now={time:.1f}s)",
                    force=True)
                # Append to offset CSV
                try:
                    import csv as _csv_mod
                    _offset_header_written = bool(globals().get('_offset_header_written', False))
                    _row_off = {
                        'sim_time_s': round(time, 1),
                        'experiment': _CURRENT_EXPERIMENT,
                        'group':      self.name,
                        'veh_id':     veh_id,
                        'from_jct':   _prev_jct,
                        'to_jct':     at_inter_id,
                        'offset_s':   round(_offset_s, 2),
                        'dist_m':     round(_dist_m, 1),
                        'speed_est_ms': round(_speed_est_eff, 2),
                        'speed_raw_ms': round(_speed_est_raw, 2),
                        'speed_flag': _speed_flag,
                        'quality':    _quality,
                        'grant_from_t': round(_prev_t, 1),
                        'grant_to_t':   round(time, 1),
                    }
                    _write_hdr = not _offset_header_written
                    with open(_OFFSET_CSV, 'a', newline='') as _f_off:
                        _w = _csv_mod.DictWriter(_f_off, fieldnames=list(_row_off.keys()))
                        if _write_hdr:
                            _w.writeheader()
                            globals()['_offset_header_written'] = True
                        _w.writerow(_row_off)
                except Exception as _oe:
                    log_to_file(f"[OFFSET CSV] write failed: {_oe}")

        # ── Prearm pass-gate: only queue downstream prearms if bus speed is healthy ──────────
        # When notify_bus_granted() is called, the bus has just ARRIVED at at_inter_id
        # (it won the green wave, received TSP, or got natural green). At this moment,
        # the bus might still be accelerating from the stop line.  If we immediately
        # queue prearms for junction[next] based on kinematic ETA, the prearm fires
        # before the bus has left junction[at_inter_id], creating a "too early" prearm.
        #
        # Gate: Only queue prearms if:
        #   1. This is NOT the first time we see this bus (tracker existed before), OR
        #   2. The tracker's speed estimate is > 4 m/s (bus actively traveling, not stopped)
        #
        # This ensures prearms queue only after the bus has demonstrated movement.
        _bus_speed_ms = abs(tracker.x[1])
        _should_queue_prearms = (not _tracker_is_new) or (_bus_speed_ms > 4.0)
        if not _should_queue_prearms and LOG_CORRIDOR:
            log_to_file(
                f"[PREARM GATE] bus={veh_id} jct={at_inter_id} speed={_bus_speed_ms:.1f}m/s — "
                f"skip queuing prearms (bus still accelerating at stop line)"
            )

        if LOG_CORRIDOR:
            _dir_tag = "NB" if is_northbound else "SB"
            _vprint(
                f"[CORRIDOR KF] t={time:.1f} bus={veh_id} granted "
                f"jct={at_inter_id} pos={at_pos:.0f}m "
                f"spd={tracker.x[1]:.1f}m/s ({tracker.x[1]*3.6:.0f}km/h) dir={_dir_tag}"
            )
        _record_wave_event(
            time, self.name, "grant",
            source_jct=at_inter_id,
            target_jct=at_inter_id,
            veh_id=veh_id,
            note=("northbound" if is_northbound else "southbound"),
        )

        # Start (or refresh) a coordination wave.
        # All other junctions get a ban on independent bus detection until
        # each of them is individually pre-armed and served.
        if COORDINATED_TSP:
            _wave_is_new = (veh_id != self._wave_veh_id)
            if _wave_is_new:
                # New bus — fully reset wave state so served-set doesn't carry over
                self._wave_served_ids     = {at_inter_id}
                self._wave_uncertain_jcts = set()
            else:
                # Same bus continuing down corridor — accumulate served junctions
                # (resetting here was the root cause of repeated pre-arm spam:
                # each downstream grant cleared upstream junctions from served_ids,
                # making them eligible for another pre-arm on the next eval step)
                self._wave_served_ids.add(at_inter_id)
            self._wave_active  = True
            self._wave_veh_id  = veh_id
            self._wave_origin  = at_inter_id
            if LOG_CORRIDOR:
                _vprint(
                    f"[CORRIDOR WAVE] t={time:.1f} WAVE {'START' if _wave_is_new else 'CONTINUE'} bus={veh_id} "
                    f"origin=jct{at_inter_id} dir={'NB' if is_northbound else 'SB'} — "
                    f"served={self._wave_served_ids}"
                )

        _allowed_targets = set(self._iter_managed_targets(at_inter_id, is_northbound, veh_id=veh_id)[:1])
        
        # ── Strict guard: ensure only the immediate next junction gets prearms ──
        # CRITICAL: Prearms should ONLY be queued for the immediate next managed junction.
        # If somehow more than one target is selected, this is a bug and must be logged.
        if len(_allowed_targets) > 1:
            log_to_file(
                f"[PREARM GUARD ERROR] bus={veh_id} from_jct={at_inter_id} "
                f"_allowed_targets has {len(_allowed_targets)} targets: {_allowed_targets} "
                f"— should be exactly 1 or 0. Limiting to first target only.",
                force=True
            )
            _allowed_targets = set(list(_allowed_targets)[:1])
        
        if self._pre_requests:
            _removed_targets = []
            for _tid, _req in list(self._pre_requests.items()):
                try:
                    _r_veh = int(_req[0])
                except Exception:
                    _r_veh = -1
                if _r_veh != int(veh_id):
                    continue
                if _tid in _allowed_targets:
                    continue
                del self._pre_requests[_tid]
                _removed_targets.append(int(_tid))

            for _old_tid in _removed_targets:
                _record_wave_event(
                    time, self.name, "prearm_superseded",
                    source_jct=at_inter_id,
                    target_jct=_old_tid,
                    veh_id=veh_id,
                    note="grant advanced to immediate next target",
                )

        for next_id in _allowed_targets:
            next_pos = self.corridor_pos.get(next_id)
            # Sanity check: target must be in direction of travel
            if next_pos is None:
                continue
            if is_northbound and next_pos <= at_pos:
                continue   # next junction must be north (larger pos)
            if not is_northbound and next_pos >= at_pos:
                continue   # next junction must be south (smaller pos)
            
            # ── Apply prearm pass-gate ───────────────────────────────────
            # Skip queuing prearms if bus speed indicates it hasn't cleared the stop line.
            # This prevents prearms from firing before the bus has actually entered the corridor.
            if not _should_queue_prearms:
                if LOG_CORRIDOR:
                    log_to_file(
                        f"[PREARM GATE SKIP] bus={veh_id} from={at_inter_id} to={next_id} "
                        f"speed={_bus_speed_ms:.1f}m/s ≤ 4.0 threshold"
                    )
                continue
            
            # Signal-aware ETA: chains through intermediate junctions, adding
            # kinematic travel + expected red-wait at each signal encountered
            # before the target.  Falls back to pure kinematic when position data
            # is unavailable for intermediates.
            _eta_kinematic  = tracker.eta(next_pos, time)
            eta             = self._signal_aware_eta(at_inter_id, next_id, tracker, time)
            # Bail if ETA is unreachable (bus heading wrong way — shouldn't happen)
            if eta > time + 99000:
                continue
            _signal_delay_contrib = max(0.0, eta - _eta_kinematic)
            gap_delay_s = 0.0   # now folded into signal_aware_eta
            sigma = tracker.uncertainty_s(next_pos)
            next_gb  = self._ctrl_map.get(next_id)
            next_ic  = self._ic_map.get(next_id)
            next_bus_sg = next_gb.bus_sg if next_gb else None

            # ── Prearm quality gate ───────────────────────────────────────
            # Skip queuing if the ETA prediction is too uncertain (sigma above threshold)
            # or the remaining travel time is so long that GE would exceed the
            # hard cap. This prevents wasted prearms that are likely to miss.
            _eta_from_now = eta - time
            # Proportional sigma gate: the arrival-time uncertainty (sigma) naturally
            # scales with inter-junction distance.  A fixed 35 s threshold blocks ALL
            # pre-arms beyond ~900 m.  Allow sigma up to 50 % of ETA (capped at 60 s
            # floor) so that uncertainty is judged relative to the prediction horizon.
            _PREARM_SIGMA_FLOOR = float(globals().get('PREARM_MAX_SIGMA_S', 120.0) or 120.0)
            _PREARM_MAX_SIGMA = max(_PREARM_SIGMA_FLOOR, 0.80 * max(_eta_from_now, 0.0))
            if sigma > _PREARM_MAX_SIGMA:
                # Lift the wave ban for this junction so it can run its own
                # independent detection rather than wait for a stale prearm.
                self._wave_uncertain_jcts.add(next_id)
                _skip_key_sigma = (at_inter_id, next_id, "sigma")
                if _skip_key_sigma not in self._prearm_skip_logged_jcts:
                    self._prearm_skip_logged_jcts.add(_skip_key_sigma)
                    log_to_file(
                        f"[PREARM SKIP SIGMA] group={self.name} "
                        f"from=jct{at_inter_id} to=jct{next_id} "
                        f"sigma={sigma:.1f}s > {_PREARM_MAX_SIGMA:.0f}s — "
                        f"prediction too uncertain (dist={(abs(next_pos - at_pos)):.0f}m) "
                        f"→ jct{next_id} added to _wave_uncertain_jcts",
                        force=True
                    )
                elif LOG_CORRIDOR:
                    log_to_file(
                        f"[CORRIDOR SKIP QUEUE] jct={next_id} bus={veh_id} "
                        f"sigma={sigma:.1f}s > {_PREARM_MAX_SIGMA:.0f}s — prediction too uncertain"
                    )
                continue
            # Don't queue prearms where the bus is more than ~90 s away —
            # beyond that the ETA is too stale and produces prearms that fire
            # at junctions the bus won't reach for 6+ minutes.
            # Use MAX_PREARM_HORIZON_S global if set, otherwise default to 90 s
            # (same cap used in _process_pre_requests).
            _max_prearm_horizon_s = float(
                getattr(self, '_max_prearm_horizon_s', float(globals().get('MAX_PREARM_HORIZON_S', 90.0) or 90.0))
            )
            # Route-order guard: refuse to prearm a junction that the bus has
            # already passed.  Compare the target's route-index against the
            # highest route-index seen in the bus's observed-junction history.
            # If next_id's index ≤ last observed index the bus is heading away
            # from it (or already served it) — skip.
            _next_route_idx = self._route_index.get(next_id, -1)
            if _next_route_idx >= 0:
                _obs_jcts = _bus_observed_jcts.get(veh_id, [])
                if _obs_jcts:
                    _obs_indices = [self._route_index[j] for j in _obs_jcts if j in self._route_index]
                    if _obs_indices:
                        _max_obs_idx = max(_obs_indices)
                        _min_obs_idx = min(_obs_indices)
                        # Determine direction from observed history
                        if is_northbound and _next_route_idx <= _max_obs_idx:
                            if LOG_CORRIDOR:
                                log_to_file(
                                    f"[PREARM SKIP OBS] bus={veh_id} next_id={next_id} "
                                    f"route_idx={_next_route_idx} <= max_observed={_max_obs_idx} "
                                    "— bus has already passed this junction, skipping prearm"
                                )
                            continue
                        if not is_northbound and _next_route_idx >= _min_obs_idx:
                            if LOG_CORRIDOR:
                                log_to_file(
                                    f"[PREARM SKIP OBS] bus={veh_id} next_id={next_id} "
                                    f"route_idx={_next_route_idx} >= min_observed={_min_obs_idx} "
                                    "— bus has already passed this junction (SB), skipping prearm"
                                )
                            continue
            if _eta_from_now > _max_prearm_horizon_s:
                _skip_key_horizon = (at_inter_id, next_id, "horizon")
                if _skip_key_horizon not in self._prearm_skip_logged_jcts:
                    self._prearm_skip_logged_jcts.add(_skip_key_horizon)
                    log_to_file(
                        f"[PREARM SKIP HORIZON] group={self.name} "
                        f"from=jct{at_inter_id} to=jct{next_id} "
                        f"eta_in={_eta_from_now:.0f}s > horizon={_max_prearm_horizon_s:.0f}s — "
                        f"junction too far ahead (dist={(abs(next_pos - at_pos)):.0f}m)",
                        force=True
                    )
                elif LOG_CORRIDOR:
                    log_to_file(
                        f"[CORRIDOR SKIP QUEUE] jct={next_id} bus={veh_id} "
                        f"eta_in={_eta_from_now:.0f}s > horizon={_max_prearm_horizon_s:.0f}s"
                    )
                continue

            eta_base = eta
            queue_len = 0
            eta_delta = 0.0
            eta_adj = eta
            sw_diag = {}

            # Queue-aware ETA correction in SHOCKWAVE and ADAPTIVE modes.
            if COORDINATION_ALGO in ("SHOCKWAVE", "ADAPTIVE"):
                eta_adj, queue_len, eta_delta, sw_diag = self._shockwave_eta_adjust(
                    next_gb, next_bus_sg, eta, next_ic=next_ic)
                if LOG_CORRIDOR and eta_delta > 0.0:
                    log_to_file(
                        f"[CORRIDOR SW] jct={next_id} queue={queue_len}veh "
                        f"ETA_base={eta:.1f}s wave_adj=+{eta_delta:.1f}s ETA_adj={eta_adj:.1f}s"
                    )
                eta = eta_adj

            if LOG_CORRIDOR and _signal_delay_contrib > 0.5:
                _vprint(
                    f"[CORRIDOR SIG] from=jct{at_inter_id} to=jct{next_id} "
                    f"signal_delay=+{_signal_delay_contrib:.1f}s "
                    f"(kinematic={_eta_kinematic - time:.0f}s + sig={_signal_delay_contrib:.0f}s)"
                )

            # ── Offset correction ─────────────────────────────────────────────
            # Principle (green-wave coordination, per Tandfonline 2025 / IEEE 2023):
            #   ideal_offset = inter-junction distance / bus_design_speed
            #   actual_offset = grant_time_mod_cycle at at_inter_id →
            #                   natural_bp_start_mod_cycle at next_id
            #   offset_error  = (bus_arrives_at_next - nearest_bp_green_start)
            #
            # If the bus arrives during red at next_id, adjust the pre-arm ETA to
            # account for the offset error.  This ensures the GE/INS at next_id
            # fires at the right moment rather than relying on the raw kinematic ETA.
            #
            # The correction is also logged to the offset CSV so the offset_error
            # distribution can be visualised in the dashboard.
            _oc_offset_error_s = 0.0
            try:
                _cycle_len = float(self.config.get('CycleTime', 135)
                                   if hasattr(self, 'config') else 135.0)
                _next_ic2 = self._ic_map.get(next_id)
                if _next_ic2 is not None:
                    _next_jct_id = getattr(_next_ic2, 'node_id', next_id)
                    _n_phases = int(ECIGetNumberPhases(_next_jct_id))
                    _bp_at_next = getattr(_next_ic2, 'BusPhase', 1) or 1
                    if _n_phases > 0:
                        # Walk the phase sequence starting from now to find
                        # when the bus phase at next_id will next be green.
                        _cur_ph_next  = int(ECIGetCurrentPhase(_next_jct_id))
                        _ph_start_now = float(ECIGetStartingTimePhase(_next_jct_id))
                        _t_cursor     = float(time)
                        _bp_green_start = None
                        for _step in range(_n_phases + 1):
                            _ph = ((_cur_ph_next - 1 + _step) % _n_phases) + 1
                            _dur = float(GetPhaseDuration(_next_jct_id, _ph, 0.0) or 0)
                            if _dur < 0.5:
                                _dur = _cycle_len / max(_n_phases, 1)
                            if _step == 0:
                                _elapsed_in_ph = max(0.0, time - _ph_start_now)
                                _remaining     = max(0.0, _dur - _elapsed_in_ph)
                                if _ph == _bp_at_next:
                                    _bp_green_start = time  # already in bus phase
                                    break
                                _t_cursor = time + _remaining
                            else:
                                if _ph == _bp_at_next:
                                    _bp_green_start = _t_cursor
                                    break
                                _t_cursor += _dur

                        if _bp_green_start is not None:
                            # offset_error = bus_arrival_ETA - nearest_bus_phase_green_start
                            # Positive: bus arrives after green starts (ideal — or late)
                            # Negative: bus arrives before green starts (early)
                            _raw_offset_error_s = eta - _bp_green_start
                            # Wrap to nearest-cycle representation so diagnostics and
                            # correction logic stay bounded (avoid +600 s artifacts).
                            if _cycle_len > 1.0:
                                _oc_offset_error_s = (
                                    (_raw_offset_error_s + 0.5 * _cycle_len) % _cycle_len
                                ) - 0.5 * _cycle_len
                            else:
                                _oc_offset_error_s = _raw_offset_error_s
                            _bp_green_dur = float(
                                getattr(_next_ic2, 'BusPhaseDuration', 0) or 0
                            )
                            _aligned = (-5.0 <= _oc_offset_error_s <= _bp_green_dur)
                            try:
                                setattr(_next_ic2, '_last_offset_error_s', float(_oc_offset_error_s))
                                setattr(_next_ic2, '_last_offset_error_t', float(time))
                                # Also record on the SOURCE junction so its reward
                                # lookahead can see the offset quality its grants
                                # create downstream (closes the A→B feedback loop).
                                _src_ic = self._ic_map.get(at_inter_id)
                                if _src_ic is not None:
                                    _src_ic._last_downstream_offset_s = float(_oc_offset_error_s)
                                    _src_ic._last_downstream_offset_t = float(time)
                            except Exception:
                                pass
                            if not _aligned and abs(_oc_offset_error_s) < _cycle_len * 0.5:
                                # ── ETA correction (all modes) ─────────────────
                                # Shift ETA toward green start so the pre-arm fires
                                # with the correct timing reference.
                                _corr = max(-15.0, min(15.0, -_oc_offset_error_s))
                                eta   = eta + _corr
                                if LOG_CORRIDOR:
                                    log_to_file(
                                        f"[OFFSET_CORR] jct{at_inter_id}→jct{next_id} "
                                        f"bus={veh_id} err={_oc_offset_error_s:.1f}s "
                                        f"corr={_corr:+.1f}s "
                                        f"bp_green={_bp_green_start:.1f}s ETA→{eta:.1f}s"
                                    )

                                # ── Forward OC — physical signal shift (DC TSP paper)
                                # For GLOBAL_REWARD_MODE (DCTSP_MARL): proactively
                                # shift the signal at the downstream junction so the
                                # bus phase aligns with the projected bus arrival.
                                # Contrast with backward OC (post-grant recovery at
                                # upstream junction) and with the pre-arm (GE/INS at
                                # last minute). Forward OC adjusts timing NOW, before
                                # the bus arrives, maintaining corridor progression.
                                if GLOBAL_REWARD_MODE and abs(_oc_offset_error_s) > DCTSP_OC_THRESH_S:
                                    try:
                                        _foc_node = getattr(_next_ic2, 'node_id', next_id)
                                        _foc_cur  = int(ECIGetCurrentPhase(_foc_node))
                                        _foc_bp   = int(getattr(_next_ic2, 'BusPhase', 1) or 1)
                                        _foc_bp_dur = float(getattr(_next_ic2, 'BusPhaseDuration', 30) or 30)
                                        if _foc_cur != _foc_bp:  # only adjust non-bus phase
                                            _foc_ps   = float(ECIGetStartingTimePhase(_foc_node))
                                            _foc_cur_dur = float(GetPhaseDuration(_foc_node, _foc_cur, 0.0) or 30.0)
                                            _foc_elapsed = max(0.0, time - _foc_ps)
                                            _foc_remain  = max(5.0, _foc_cur_dur - _foc_elapsed)
                                            _foc_new_dur = _foc_cur_dur   # default (no change)
                                            _foc_adj_label = 'NONE'
                                            if _oc_offset_error_s < 0:
                                                # Bus arrives BEFORE green: advance green
                                                # by truncating current non-bus phase.
                                                _advance = min(abs(_oc_offset_error_s),
                                                               DCTSP_OC_MAX_ADJ_S, _foc_remain - 5.0)
                                                if _advance > 2.0:
                                                    _foc_new_dur = max(5.0, _foc_cur_dur - _advance)
                                                    _foc_adj_label = f'ADVANCE_{_advance:.1f}s'
                                            else:
                                                # Bus arrives AFTER green ends: delay green
                                                # by extending current non-bus phase.
                                                _excess = max(0.0,
                                                              _oc_offset_error_s - _foc_bp_dur)
                                                _delay  = min(_excess, DCTSP_OC_MAX_ADJ_S)
                                                if _delay > 2.0:
                                                    _foc_new_dur = min(_foc_cur_dur + _delay, 120.0)
                                                    _foc_adj_label = f'DELAY_{_delay:.1f}s'
                                            if _foc_adj_label != 'NONE':
                                                ECIChangeTimingPhase(
                                                    _foc_node, _foc_cur, _foc_new_dur, 0.0)
                                                # Log drift from initial (preserved baseline)
                                                _init_dur = _initial_phase_timings.get(
                                                    next_id, {}).get(_foc_cur, _foc_cur_dur)
                                                _drift = _foc_new_dur - _init_dur
                                                log_to_file(
                                                    f"[FORWARD_OC] {_foc_adj_label} "
                                                    f"jct{at_inter_id}→jct{next_id} "
                                                    f"err={_oc_offset_error_s:.1f}s "
                                                    f"new_dur={_foc_new_dur:.1f}s "
                                                    f"drift_from_init={_drift:+.1f}s "
                                                    f"(base={_init_dur:.1f}s)",
                                                    force=True)
                                    except Exception as _foc_e:
                                        pass  # forward OC is advisory
                            # Record offset quality in the offset CSV
                            try:
                                import csv as _csv_mod2
                                _offset_header_written = bool(globals().get('_offset_header_written', False))
                                _row_oc = {
                                    'sim_time_s':    round(time, 1),
                                    'experiment':    _CURRENT_EXPERIMENT,
                                    'group':         self.name,
                                    'veh_id':        veh_id,
                                    'from_jct':      at_inter_id,
                                    'to_jct':        next_id,
                                    'offset_s':      round(_oc_offset_error_s, 2),
                                    'dist_m':        round(abs(next_pos - at_pos), 1),
                                    'speed_est_ms':  round(min((_dist_m / max(eta - time, 0.1)) if eta > time else 0.0, 20.0), 2),
                                    'speed_raw_ms':  round((_dist_m / max(eta - time, 0.1)) if eta > time else 0.0, 2),
                                    'speed_flag':    ('capped' if (eta > time and (_dist_m / max(eta - time, 0.1)) > 20.0) else 'ok'),
                                    'quality':       'aligned' if _aligned else 'misaligned',
                                    'grant_from_t':  round(time, 1),
                                    'grant_to_t':    round(eta, 1),
                                }
                                _write_hdr_oc = not _offset_header_written
                                with open(_OFFSET_CSV, 'a', newline='') as _f_oc:
                                    _w_oc = _csv_mod2.DictWriter(
                                        _f_oc, fieldnames=list(_row_oc.keys()))
                                    if _write_hdr_oc:
                                        _w_oc.writeheader()
                                        globals()['_offset_header_written'] = True
                                    _w_oc.writerow(_row_oc)
                            except Exception as _oc_csv_e:
                                pass  # non-critical
            except Exception as _oc_e:
                pass  # offset correction is advisory; never block the pre-arm

            # ── Deduplication: skip re-queuing if this (junction, bus) was already
            # fired recently.  Without this, every upstream grant re-queues the
            # same downstream junctions causing prearm spam in the wave events CSV.
            _prev_fire = self._fired_prearms.get((next_id, veh_id))
            if _prev_fire is not None:
                _prev_fire_t = float(_prev_fire[1])
                if time - _prev_fire_t < 150.0:  # 150 s cooldown per (junction, bus)
                    if LOG_CORRIDOR:
                        log_to_file(
                            f"[CORRIDOR DEDUP] skipping re-queue jct={next_id} "
                            f"bus={veh_id} — already fired {time - _prev_fire_t:.0f}s ago"
                        )
                    continue

            # Enforce MAX_PRE_ARM: count active queued + fired pre-arms for this bus.
            # Without this guard, multiple downstream junctions within the horizon
            # would all be queued simultaneously, causing "pre-arming too long through
            # multiple intersections".
            _active_prearms = (
                sum(1 for (_iid, _vid) in self._fired_prearms if _vid == veh_id)
                + sum(1 for _iid, (_vid2, *_) in self._pre_requests.items() if _vid2 == veh_id)
            )
            if _active_prearms >= self.MAX_PRE_ARM:
                if LOG_CORRIDOR:
                    log_to_file(
                        f"[PREARM LIMIT] bus={veh_id} already has {_active_prearms} "
                        f"active pre-arm(s) (MAX={self.MAX_PRE_ARM}) — skipping jct={next_id}"
                    )
                continue

            self._pre_requests[next_id] = (veh_id, eta, next_bus_sg, time, at_inter_id)
            self._pre_arm_count += 1
            self._algo_diag["queued"] = int(self._algo_diag.get("queued", 0) or 0) + 1
            if COORDINATION_ALGO in ("SHOCKWAVE", "ADAPTIVE") and eta_delta > 0.0:
                self._algo_diag["sw_adj_count"] = int(self._algo_diag.get("sw_adj_count", 0) or 0) + 1
                self._algo_diag["sw_adj_total_s"] = float(self._algo_diag.get("sw_adj_total_s", 0.0) or 0.0) + float(eta_delta)
                self._algo_diag["sw_adj_max_s"] = max(
                    float(self._algo_diag.get("sw_adj_max_s", 0.0) or 0.0),
                    float(eta_delta),
                )
            if LOG_CORRIDOR:
                _algo_tag = f"[{COORDINATION_ALGO}]"
                log_to_file(
                    f"[CORRIDOR {_algo_tag}] Pre-arm jct={next_id} bus={veh_id} "
                    f"SG={next_bus_sg} ETA={eta:.1f}s "
                    f"(+{eta - time:.0f}s ±{sigma:.0f}s) dist={next_pos - at_pos:.0f}m"
                )
                log_to_file(
                    f"[CORRIDOR DECISION] algo={COORDINATION_ALGO} stage=queue "
                    f"from={at_inter_id} to={next_id} bus={veh_id} "
                    f"eta_base={eta_base:.1f} eta_final={eta:.1f} eta_delta={eta_delta:.1f} "
                    f"sig_delay={_signal_delay_contrib:.1f} queue={queue_len} sigma={sigma:.1f}"
                )
            _record_wave_event(
                time, self.name, "prearm_queued",
                source_jct=at_inter_id,
                target_jct=next_id,
                veh_id=veh_id,
                eta_s=max(0.0, eta - time),
                note=COORDINATION_ALGO,
                algo=COORDINATION_ALGO,
                sigma_s=sigma,
                signal_delay_s=_signal_delay_contrib,
                eta_base_s=max(0.0, eta_base - time),
                eta_final_s=max(0.0, eta - time),
                eta_delta_s=eta_delta,
                **sw_diag,
            )

    # ------------------------------------------------------------------
    def _signal_delay_at_s(self, inter_id: int, arrive_t: float, time: float) -> float:
        """
        Estimate how long (seconds) a bus will wait at junction inter_id
        if it arrives at absolute simulation time arrive_t.

        Queries the live Aimsun phase state at the current sim-time and
        projects the phase sequence forward to arrive_t, returning the
        gap between arrive_t and the start of the next green window for
        the bus direction.

        Falls back to _estimate_unmanaged_delay_s when phase data is
        unavailable (e.g., junctions not under Aimsun external control).
        """
        gb = self._ctrl_map.get(inter_id)
        cfg = INTERSECTIONS_CONFIG.get(inter_id, {}) or {}

        # Which Aimsun phase carries the bus at this junction?
        bus_phase_num: int = 1
        if gb is not None:
            bp = getattr(gb, '_bus_aimsun_phase', None)
            if bp is not None:
                bus_phase_num = int(bp)
            jct_id = gb.junction_id
        else:
            try:
                bus_phase_num = int(cfg.get("BusPhase", 1) or 1)
            except Exception:
                bus_phase_num = 1
            jct_id = inter_id

        try:
            n_phases = int(ECIGetNumberPhases(jct_id))
            if n_phases <= 0:
                return self._estimate_unmanaged_delay_s(inter_id)

            current_phase = int(ECIGetCurrentPhase(jct_id))
            phase_start_t = float(ECIGetStartingTimePhase(jct_id))
            phase_elapsed = max(0.0, time - phase_start_t)

            # Walk one full cycle from the current position, building the
            # absolute timeline for each phase.
            # cycle_timeline: [(phase_num, abs_start, abs_end), ...]
            cycle_timeline = []
            t_cursor = time
            for step in range(n_phases):
                ph = ((current_phase - 1 + step) % n_phases) + 1
                raw_dur = float(GetPhaseDuration(jct_id, ph, 0.0))
                dur = max(raw_dur, 1.0)   # guard against zero-duration phases
                if step == 0:
                    # Current phase: already partially elapsed
                    remaining = max(0.0, dur - phase_elapsed)
                    t_start = phase_start_t
                    t_end   = time + remaining
                else:
                    t_start = t_cursor
                    t_end   = t_cursor + dur
                cycle_timeline.append((ph, t_start, t_end))
                t_cursor = t_end

            cycle_len = t_cursor - time   # total remaining cycle duration

            # First occurrence of the bus phase in this cycle
            green_start = None
            green_end   = None
            for ph, t_s, t_e in cycle_timeline:
                if ph == bus_phase_num:
                    green_start = t_s
                    green_end   = t_e
                    break

            if green_start is None or cycle_len <= 0:
                return self._estimate_unmanaged_delay_s(inter_id)

            if arrive_t >= green_start and arrive_t < green_end:
                return 0.0    # arrives during green — no wait

            if arrive_t < green_start:
                return green_start - arrive_t   # wait until green opens

            # Bus arrives after this cycle's green — project forward by full cycles
            cycles_ahead = math.ceil((arrive_t - green_end) / cycle_len)
            next_green_start = green_start + cycles_ahead * cycle_len
            return max(0.0, next_green_start - arrive_t)

        except Exception:
            return self._estimate_unmanaged_delay_s(inter_id)

    # ------------------------------------------------------------------
    def _signal_aware_eta(self, from_id: int, to_id: int,
                          tracker: 'BusKalmanTracker', time: float) -> float:
        """
        Signal-aware estimated arrival time (sim-seconds) at to_id.

        Rather than pure distance/speed, walks every junction in
        route_inter_ids between from_id and to_id, computing at each step:
          1. Kinematic travel time from the last known position to this junction
          2. Expected red wait at this junction (_signal_delay_at_s)

        The accumulated position+time is used as input to the next kinematic
        leg. Falls back to tracker.eta() when route position data is
        unavailable for intermediate junctions.

        The Kalman tracker state is read but never modified here; regular
        tracker.update() behaviour is undisturbed.
        """
        from_idx = self._route_index.get(from_id)
        to_idx   = self._route_index.get(to_id)
        to_pos   = self.corridor_pos.get(to_id)

        if from_idx is None or to_idx is None or to_pos is None:
            return (tracker.eta(to_pos, time)
                    if to_pos is not None else time + 99999.0)

        lo, hi = sorted((from_idx, to_idx))
        intermediates = self.route_inter_ids[lo + 1: hi]  # exclusive of endpoints

        if not intermediates:
            return tracker.eta(to_pos, time)

        # Propagate at current tracker speed; fall back to default if stalled
        spd = abs(tracker.x[1])
        if spd < 0.5:
            spd = BusKalmanTracker.DEFAULT_SPEED_MS

        # Walk intermediates in route direction
        is_northbound = (to_idx > from_idx)
        step_jcts = intermediates if is_northbound else list(reversed(intermediates))

        t_cursor   = time
        pos_cursor = tracker.x[0]  # current bus position along corridor (m)

        for jct_id in step_jcts:
            jct_pos = self.corridor_pos.get(jct_id)
            if jct_pos is None:
                # No corridor position — add fixed delay estimate and continue
                t_cursor += self._estimate_unmanaged_delay_s(jct_id)
                continue

            dist_m   = abs(jct_pos - pos_cursor)
            t_arrive = t_cursor + dist_m / spd
            t_cursor = t_arrive + self._signal_delay_at_s(jct_id, t_arrive, time)
            pos_cursor = jct_pos

        # Final kinematic leg from last intermediate to target junction
        dist_final = abs(to_pos - pos_cursor)
        t_cursor += dist_final / spd
        return t_cursor

    # ------------------------------------------------------------------
    def _objective_lead_time(self, gb, bus_sg, eta_t: float, time: float,
                              tracker) -> float:
        """
        OBJECTIVE mode: compute the pre-arm lead time that maximises:
          J = COORD_OBJ_ALPHA * bus_delay_saved_persons
            - COORD_OBJ_BETA  * normal_throughput_displaced_persons

        This avoids the perverse incentive of pure delay minimisation
        (fewer vehicles served → lower total delay) by explicitly including
        a throughput benefit term.  Lead times from 5 to 60 s are evaluated;
        the one with the highest J is returned.

        Parameters
        ----------
        gb       : GroupBasedController at the downstream intersection
        bus_sg   : signal group for bus at that intersection
        eta_t    : estimated arrival time (absolute sim seconds)
        time     : current sim time
        tracker  : BusKalmanTracker for this vehicle
        """
        BUS_OCC     = getattr(gb, 'BusOcc',   40.0)
        NORMAL_OCC  = getattr(gb, 'CarOcc',    1.5)
        MAX_RED_WAIT = getattr(gb, '_eta_max_s', 60.0)   # typical max red wait

        try:
            queue    = gb._compute_queue()
            q_bus_sg = queue.get(bus_sg, 0)
        except Exception:
            q_bus_sg = 0

        # Arrival time uncertainty: 1-sigma from Kalman tracker
        try:
            target_pos = self.corridor_pos.get(
                next(iid for iid, c in self._ctrl_map.items() if c is gb), None)
            sigma = tracker.uncertainty_s(target_pos) if target_pos else 15.0
        except Exception:
            sigma = 15.0

        best_J    = -1e9
        best_lead = self.PRE_GREEN_LEAD_S   # fallback to fixed default

        for lead in range(5, 65, 5):
            eta_in = eta_t - time   # seconds until bus arrives
            # P[bus arrives during green] grows as lead / (2*sigma)
            p_green = min(1.0, max(0.0, lead / (2.0 * sigma + 1.0)))

            # Delay saved for bus: avoided red wait × occupancy
            # Maximum possible red wait capped at MAX_RED_WAIT
            delay_saved = min(eta_in, MAX_RED_WAIT) * p_green * BUS_OCC

            # Normal-traffic cost: pre-arming disrupts normal phases for ~lead s.
            # Queue at downstream * occupancy * fractional green lost.
            green_fraction_lost = lead / max(self.PRE_GREEN_LEAD_S * 2, 30.0)
            throughput_lost = q_bus_sg * NORMAL_OCC * green_fraction_lost

            J = COORD_OBJ_ALPHA * delay_saved - COORD_OBJ_BETA * throughput_lost
            if J > best_J:
                best_J    = J
                best_lead = float(lead)

        if LOG_CORRIDOR:
            _vprint(
                f"[CORRIDOR OBJ] Optimal lead={best_lead:.0f}s "
                f"J={best_J:.1f} sigma={sigma:.1f}s q={q_bus_sg}"
            )
        return best_lead

    # ------------------------------------------------------------------
    def _next_managed_target_from_tracker(self, veh_id: int) -> int:
        """
        Infer the immediate next managed junction from current Kalman state
        (position + direction) while preserving corridor-wide route knowledge.
        """
        trk = self._trackers.get(veh_id)
        if trk is None or not self.corridor_pos:
            return -1

        try:
            pos_m = float(trk.x[0])
            vel_ms = float(trk.x[1])
        except Exception:
            return -1

        is_nb = vel_ms >= 0.0
        managed = set(self.inter_ids)

        ordered = []
        for iid in self.route_inter_ids:
            p = self.corridor_pos.get(iid)
            if p is not None:
                ordered.append((iid, float(p)))
        if not ordered:
            return -1

        nearest_iid = min(ordered, key=lambda t: abs(t[1] - pos_m))[0]
        base_idx = self._route_index.get(nearest_iid)
        if base_idx is None:
            return -1

        step = 1 if is_nb else -1
        idx = base_idx + step
        while 0 <= idx < len(self.route_inter_ids):
            iid = self.route_inter_ids[idx]
            if iid in managed:
                return int(iid)
            idx += step
        return -1

    # ------------------------------------------------------------------
    def _has_passed_source_jct(self, veh_id: int, source_jct: int,
                               is_northbound: bool, min_pass_m: float = 25.0) -> bool:
        """True when tracker position is at least min_pass_m past source_jct."""
        trk = self._trackers.get(veh_id)
        src_pos = self.corridor_pos.get(source_jct)
        if trk is None or src_pos is None:
            return False
        try:
            pos_m = float(trk.x[0])
            pass_m = max(5.0, float(min_pass_m))
        except Exception:
            return False
        if is_northbound:
            return pos_m >= (float(src_pos) + pass_m)
        return pos_m <= (float(src_pos) - pass_m)

    # ------------------------------------------------------------------
    def _process_pre_requests(self, time: float, timeSta: float):
        """Fire pre-green requests when the bus is within the algorithm's lead time."""
        for inter_id, req in list(self._pre_requests.items()):
            if len(req) >= 5:
                veh_id, eta_t, bus_sg, issued_t, source_jct = req
            else:
                veh_id, eta_t, bus_sg, issued_t = req
                source_jct = -1

            # Enforce that prearms always retain a valid source junction context.
            # Requests without source are unsafe to retarget/fire and can jump route.
            if source_jct <= 0:
                if LOG_CORRIDOR:
                    log_to_file(
                        f"[PREARM DROP] jct={inter_id} bus={veh_id} "
                        f"missing source_jct (legacy/invalid request)"
                    )
                del self._pre_requests[inter_id]
                continue

            # If PT line is known, ensure source_jct belongs to that line route.
            _line_id = _bus_line_id.get(veh_id, -1)
            _line_route = _pt_line_jct_route.get(_line_id) if _line_id > 0 else None
            if _line_route and source_jct not in _line_route:
                if LOG_CORRIDOR:
                    log_to_file(
                        f"[PREARM DROP] jct={inter_id} bus={veh_id} src={source_jct} "
                        f"not on PT route line={_line_id}"
                    )
                del self._pre_requests[inter_id]
                continue

            _tracker_live = self._trackers.get(veh_id)
            _is_nb = True
            if _tracker_live is not None:
                try:
                    _is_nb = float(_tracker_live.x[1]) >= 0.0
                except Exception:
                    _is_nb = True

            # Re-evaluate immediate-next target at fire time using intended
            # route first (PT route / observed route), then tracker fallback.
            expected_next = -1
            if source_jct > 0:
                _intended = self._iter_managed_targets(source_jct, _is_nb, veh_id=veh_id)
                if _intended:
                    expected_next = int(_intended[0])
            if expected_next <= 0:
                expected_next = self._next_managed_target_from_tracker(veh_id)

            # Hard gate: do not fire downstream prearm until the bus has physically
            # moved past the source junction that queued this request.
            _pass_gate_m = float(globals().get('PREARM_SOURCE_PASS_M', 25.0) or 25.0)
            if source_jct > 0 and _tracker_live is not None:
                if not self._has_passed_source_jct(veh_id, source_jct, _is_nb, _pass_gate_m):
                    if LOG_CORRIDOR:
                        log_to_file(
                            f"[PREARM HOLD] bus={veh_id} src={source_jct} tgt={inter_id} "
                            f"waiting_pass>{_pass_gate_m:.0f}m before fire"
                        )
                    continue

            if expected_next > 0 and expected_next != inter_id:
                if LOG_CORRIDOR:
                    log_to_file(
                        f"[CORRIDOR RETARGET] bus={veh_id} queued_jct={inter_id} "
                        f"expected_next={expected_next} source={source_jct}"
                    )
                _target_pos = self.corridor_pos.get(expected_next)
                _tracker_live = self._trackers.get(veh_id)
                if _target_pos is not None and _tracker_live is not None:
                    try:
                        eta_new = float(_tracker_live.eta(_target_pos, time))
                    except Exception:
                        eta_new = float(eta_t)
                else:
                    eta_new = float(eta_t)

                _new_gb = self._ctrl_map.get(expected_next)
                new_bus_sg = _new_gb.bus_sg if _new_gb is not None else bus_sg
                self._pre_requests[expected_next] = (
                    veh_id, eta_new, new_bus_sg, time,
                    source_jct if source_jct > 0 else inter_id,
                )
                del self._pre_requests[inter_id]
                _record_wave_event(
                    time, self.name, "prearm_retarget",
                    source_jct=self._wave_origin,
                    target_jct=expected_next,
                    veh_id=veh_id,
                    eta_s=max(0.0, eta_new - time),
                    note=f"old={inter_id}",
                    old_target_jct=inter_id,
                    expected_target_jct=expected_next,
                )
                continue

            _max_prearm_horizon_s = float(
                getattr(self, '_max_prearm_horizon_s', float(globals().get('MAX_PREARM_HORIZON_S', 90.0) or 90.0))
            )
            if (eta_t - time) > _max_prearm_horizon_s:
                del self._pre_requests[inter_id]
                self._record_prearm_discarded(inter_id)
                _record_wave_event(
                    time, self.name, "prearm_discarded",
                    source_jct=self._wave_origin,
                    target_jct=inter_id,
                    veh_id=veh_id,
                    eta_s=max(0.0, eta_t - time),
                    note=f"over_horizon>{_max_prearm_horizon_s:.0f}s",
                )
                continue

            # Stale: bus never arrived or took a different route
            if time - issued_t > self.PRE_REQ_TIMEOUT_S or eta_t - time < -30.0:
                del self._pre_requests[inter_id]
                self._prearm_stats["expired"] += 1
                log_to_file(
                    f"[CORRIDOR PREARM] EXPIRED jct={inter_id} bus={veh_id} "
                    f"age={time - issued_t:.0f}s ETA_was={eta_t:.1f}s now={time:.1f}s"
                )
                _record_wave_event(
                    time, self.name, "prearm_expired",
                    source_jct=self._wave_origin,
                    target_jct=inter_id,
                    veh_id=veh_id,
                    eta_s=eta_t - time,
                )
                continue

            # ── Dynamic lead time computation ─────────────────────────────────
            # Standard fixed-lead fires PRE_GREEN_LEAD_S seconds before ETA.
            # OBJECTIVE algo computes a bus-delay-vs-throughput optimal lead.
            # In addition, we add "phase_lead" — the minimum time the downstream
            # junction needs to finish its current phase and enter intergreen so
            # that the bus phase is ready on arrival.  This prevents the bus from
            # arriving before the pre-armed phase even starts.
            gb = self._ctrl_map.get(inter_id)
            lead_reason = "fixed"
            lead_sigma = None
            phase_lead = 0.0
            if COORDINATION_ALGO == "OBJECTIVE" and gb is not None and bus_sg is not None:
                _tracker = self._trackers.get(veh_id)
                if _tracker is not None:
                    lead_s = self._objective_lead_time(gb, bus_sg, eta_t, time, _tracker)
                    lead_reason = "objective"
                else:
                    lead_s = self.PRE_GREEN_LEAD_S
                    lead_reason = "objective-fallback"
            elif COORDINATION_ALGO == "ADAPTIVE":
                lead_s = self.PRE_GREEN_LEAD_S
                lead_reason = "adaptive-base"
                _tracker = self._trackers.get(veh_id)
                if _tracker is not None:
                    try:
                        _target = self.corridor_pos.get(inter_id)
                        _sigma = _tracker.uncertainty_s(_target) if _target is not None else 12.0
                    except Exception:
                        _sigma = 12.0
                    lead_sigma = _sigma
                    # Adaptive lead: scale with uncertainty.  Low sigma (confident
                    # prediction) → shorter lead; high sigma → longer lead.
                    # Formula: base of 15s + 3×sigma, clamped to [20, 75].
                    # At sigma=8 → 39s, sigma=12 → 51s, sigma=20 → 75s.
                    _adaptive_lead = max(20.0, min(75.0, 15.0 + 3.0 * _sigma))
                    lead_s = _adaptive_lead
                    lead_reason = "adaptive-sigma"
            else:
                lead_s = self.PRE_GREEN_LEAD_S   # KALMAN and SHOCKWAVE: base fixed lead
                lead_reason = "fixed"

            # Add phase-transition overhead if the downstream junction exposes it
            if gb is not None:
                phase_lead = getattr(gb, '_min_lead_for_phase_change_s', 0.0)
                lead_s = max(lead_s, phase_lead)

            if LOG_CORRIDOR:
                _sigma_txt = f"{lead_sigma:.1f}" if lead_sigma is not None else "na"
                log_to_file(
                    f"[CORRIDOR DECISION] algo={COORDINATION_ALGO} stage=fire "
                    f"jct={inter_id} bus={veh_id} eta_in={eta_t - time:.1f} "
                    f"lead={lead_s:.1f} phase_lead={phase_lead:.1f} "
                    f"base_lead={self.PRE_GREEN_LEAD_S:.1f} sigma={_sigma_txt} reason={lead_reason}"
                )

            if COORDINATION_ALGO == "ADAPTIVE":
                self._algo_diag["adaptive_fire_count"] = int(self._algo_diag.get("adaptive_fire_count", 0) or 0) + 1
                self._algo_diag["adaptive_lead_total_s"] = float(self._algo_diag.get("adaptive_lead_total_s", 0.0) or 0.0) + float(lead_s)
                self._algo_diag["adaptive_lead_min_s"] = min(
                    float(self._algo_diag.get("adaptive_lead_min_s", 1e9) or 1e9),
                    float(lead_s),
                )
                self._algo_diag["adaptive_lead_max_s"] = max(
                    float(self._algo_diag.get("adaptive_lead_max_s", 0.0) or 0.0),
                    float(lead_s),
                )
                if abs(float(lead_s) - float(self.PRE_GREEN_LEAD_S)) > 0.1:
                    self._algo_diag["adaptive_dynamic_count"] = int(self._algo_diag.get("adaptive_dynamic_count", 0) or 0) + 1

            # ── Refresh ETA from live Kalman before fire check ─────────────
            # The stored eta_t was computed at queue time.  If the tracker has
            # been updated since then, use its current estimate so the fire
            # condition reacts to the bus's actual progress.  This prevents
            # prearms firing when the bus is already at (or past) the target.
            _tracker_live_pre = self._trackers.get(veh_id)
            _target_pos_pre   = self.corridor_pos.get(inter_id)
            if _tracker_live_pre is not None and _target_pos_pre is not None:
                try:
                    _refreshed_eta = _tracker_live_pre.eta(_target_pos_pre, time)
                    if _refreshed_eta is not None:
                        _prev_eta_t = float(eta_t)
                        eta_t = float(_refreshed_eta)
                        # Keep queued request ETA aligned to the latest tracker
                        # estimate so fire/horizon checks don't act on stale ETA.
                        if abs(eta_t - _prev_eta_t) > 0.5 and inter_id in self._pre_requests:
                            self._pre_requests[inter_id] = (
                                veh_id, eta_t, bus_sg, issued_t, source_jct
                            )
                            if LOG_CORRIDOR:
                                log_to_file(
                                    f"[PREARM ETA REFRESH] jct={inter_id} bus={veh_id} "
                                    f"eta_in {_prev_eta_t - time:.1f}s -> {eta_t - time:.1f}s"
                                )
                except Exception:
                    pass

            # Re-apply horizon gate after ETA refresh so requests that moved far
            # out in time do not fire too early with stale queue-time ETA.
            if (eta_t - time) > _max_prearm_horizon_s:
                del self._pre_requests[inter_id]
                self._record_prearm_discarded(inter_id)
                _record_wave_event(
                    time, self.name, "prearm_discarded",
                    source_jct=source_jct,
                    target_jct=inter_id,
                    veh_id=veh_id,
                    eta_s=max(0.0, eta_t - time),
                    note=f"over_horizon_refreshed>{_max_prearm_horizon_s:.0f}s",
                )
                continue

            # Discard prearm if the bus is already too close to benefit.
            # With < MIN_PREARM_LEAD_S lead time the downstream signal cannot
            # finish its current phase and enter the bus phase in time.
            _min_prearm_lead_s = float(
                getattr(self, 'MIN_EFFECTIVE_PREARM_LEAD_S',
                        globals().get('MIN_EFFECTIVE_PREARM_LEAD_S', 10.0) or 10.0)
            )
            if eta_t - time < _min_prearm_lead_s:
                del self._pre_requests[inter_id]
                self._prearm_stats.setdefault("too_late_to_act", 0)
                self._prearm_stats["too_late_to_act"] += 1
                _record_wave_event(
                    time, self.name, "prearm_discarded",
                    source_jct=source_jct,
                    target_jct=inter_id,
                    veh_id=veh_id,
                    eta_s=max(0.0, eta_t - time),
                    note="too_late_to_act",
                )
                if LOG_CORRIDOR:
                    log_to_file(
                        f"[PREARM TOO LATE] jct={inter_id} bus={veh_id} "
                        f"eta_in={eta_t - time:.1f}s < min={_min_prearm_lead_s:.0f}s — discarded"
                    )
                continue

            if eta_t - time <= lead_s:
                # ── Revalidate ETA with current Kalman state ──────────
                # The prearm was queued earlier — recheck that the tracker
                # still predicts a reasonable arrival.  If the live ETA
                # now exceeds the original by more than 30 s the bus may
                # have been delayed or diverted; skip the fire.
                _tracker_live = self._trackers.get(veh_id)
                _target_pos   = self.corridor_pos.get(inter_id)
                if _tracker_live is not None and _target_pos is not None:
                    try:
                        _live_eta = _tracker_live.eta(_target_pos, time)
                        if _live_eta is not None and _live_eta > eta_t + 30.0:
                            if LOG_CORRIDOR:
                                log_to_file(
                                    f"[CORRIDOR SKIP FIRE] jct={inter_id} bus={veh_id} "
                                    f"live_eta={_live_eta:.1f}s vs queued_eta={eta_t:.1f}s "
                                    f"— bus delayed, skipping prearm fire"
                                )
                            del self._pre_requests[inter_id]
                            self._prearm_stats.setdefault("revalidation_skip", 0)
                            self._prearm_stats["revalidation_skip"] += 1
                            continue
                    except Exception:
                        pass

                if gb is not None and bus_sg is not None and gb.bus_request is None:
                    # Respect the per-vehicle cooldown at the target junction
                    cooldown_ok = not (
                        veh_id == getattr(gb, '_last_served_veh_id', None)
                        and time - getattr(gb, '_last_served_time', -9999.0)
                        < getattr(gb, '_served_veh_timeout', 120.0)
                    )
                    if not cooldown_ok:
                        # Cooldown active — bus recently served at this junction.
                        # Record as prearm_skipped so the dashboard coord-flow can
                        # show that the coordinator saw the bus but chose not to act.
                        _record_wave_event(
                            time, self.name, "prearm_skipped",
                            source_jct=self._wave_origin,
                            target_jct=inter_id,
                            veh_id=veh_id,
                            eta_s=max(0.0, eta_t - time),
                            note="cooldown",
                        )
                        del self._pre_requests[inter_id]
                        self._prearm_stats.setdefault("skipped_cooldown", 0)
                        self._prearm_stats["skipped_cooldown"] += 1
                        continue
                    if cooldown_ok:
                        gb.bus_request = bus_sg
                        gb._active_bus_veh_id = veh_id
                        gb._bus_eta = max(0.0, eta_t - time)
                        gb._bus_det_time = time
                        # Mark as coordinator-sourced so the detection suppression
                        # logic in _detect_bus/_detect_bus_urtsp knows to let it through.
                        gb._coord_sourced_request = True
                        # Lift the wave ban for this junction: it is now reacting
                        # to coordination, not acting independently.
                        self._wave_served_ids.add(inter_id)
                        self._record_prearm_fired(
                            inter_id, veh_id, eta_t, time,
                            source_jct=source_jct,
                            algo=COORDINATION_ALGO,
                            lead_reason=lead_reason,
                        )
                        # Use the bus's live position (from position tracker) so
                        # prearm marks show WHERE the bus was when the prearm
                        # fired, not where the downstream junction is.  This
                        # prevents all coord-prearm dots from piling up on the
                        # junction centroid when many buses are served.
                        _bus_live_xy = _bus_xy.get(veh_id)
                        _prearm_x = _bus_live_xy[0] if _bus_live_xy else 0.0
                        _prearm_y = _bus_live_xy[1] if _bus_live_xy else 0.0
                        if not _bus_live_xy:
                            _junc_xy_fb = getattr(gb, '_junction_xy_cache', None)
                            if _junc_xy_fb:
                                _prearm_x, _prearm_y = _junc_xy_fb
                        _mark_detection_point(
                            inter_id, veh_id, _prearm_x, _prearm_y,
                            time, f"coord-prearm/{COORDINATION_ALGO}",
                            {
                                "force_write": True,
                                "prearm_status": "fired",
                                "prearm_eta_s": round(max(0.0, eta_t - time), 1),
                                "prearm_eta_abs_s": round(float(eta_t), 1),
                                "prearm_fired_t": round(float(time), 1),
                                "prearm_note": lead_reason,
                            },
                        )
                        if LOG_CORRIDOR:
                            _vprint(
                                f"[CORRIDOR {COORDINATION_ALGO}] Pre-green FIRED "
                                f"jct={inter_id} bus={veh_id} SG={bus_sg} "
                                f"ETA_in={eta_t - time:.1f}s lead={lead_s:.0f}s "
                                f"— ban lifted for jct{inter_id}"
                            )
                elif inter_id in self._ic_map:
                    # HARMONY intersection — set _harmony_prearm so check_bus_priority
                    # applies TSP immediately using the Kalman ETA.
                    ic = self._ic_map[inter_id]
                    if ic._harmony_prearm is None:
                        ic._harmony_prearm = (veh_id, eta_t, time)
                        self._wave_served_ids.add(inter_id)
                        self._record_prearm_fired(
                            inter_id, veh_id, eta_t, time,
                            source_jct=source_jct,
                            algo=COORDINATION_ALGO,
                            lead_reason=lead_reason,
                        )
                        # Same as GB path: mark bus's live position, not junction.
                        _bus_live_xy_h = _bus_xy.get(veh_id)
                        _prearm_hx = _bus_live_xy_h[0] if _bus_live_xy_h else 0.0
                        _prearm_hy = _bus_live_xy_h[1] if _bus_live_xy_h else 0.0
                        if not _bus_live_xy_h:
                            try:
                                _junc_xy_h = ic._get_junction_xy()
                                if _junc_xy_h:
                                    _prearm_hx, _prearm_hy = _junc_xy_h
                            except Exception:
                                pass
                        _mark_detection_point(
                            inter_id, veh_id, _prearm_hx, _prearm_hy,
                            time, f"coord-prearm-harmony/{COORDINATION_ALGO}",
                            {
                                "force_write": True,
                                "prearm_status": "fired",
                                "prearm_eta_s": round(max(0.0, eta_t - time), 1),
                                "prearm_eta_abs_s": round(float(eta_t), 1),
                                "prearm_fired_t": round(float(time), 1),
                                "prearm_note": lead_reason,
                            },
                        )
                        if LOG_CORRIDOR:
                            _vprint(
                                f"[CORRIDOR {COORDINATION_ALGO}] HARMONY Pre-arm FIRED "
                                f"jct={inter_id} bus={veh_id} "
                                f"ETA_in={eta_t - time:.1f}s lead={lead_s:.0f}s"
                            )
                del self._pre_requests[inter_id]

    # ------------------------------------------------------------------
    def _check_wave_complete(self, time: float):
        """
        Lift the corridor wave ban once all pre-requests for the current wave
        have been resolved (fired or expired) AND every pre-armed junction has
        cleared its coordinated bus phase (bus_request is None).

        Also expires a wave that has been running for > 2 × PRE_REQ_TIMEOUT_S
        as a safety net against buses that never arrive.
        """
        if not self._wave_active:
            return

        # Safety expiry
        # (we store wave start time lazily — use issued_t of the last stale check)
        # Simple heuristic: if no pre_requests remain and all served junctions
        # have cleared their bus_request, the wave is done.
        pending = bool(self._pre_requests)
        any_coord_pending = any(
            getattr(self._ctrl_map.get(iid), 'bus_request', None) is not None
            and getattr(self._ctrl_map.get(iid), '_coord_sourced_request', False)
            for iid in self._wave_served_ids
            if iid != self._wave_origin
        )
        # Also check HARMONY intersections: wave is pending while _harmony_prearm is set
        any_harmony_pending = any(
            getattr(self._ic_map.get(iid), '_harmony_prearm', None) is not None
            for iid in self._wave_served_ids
            if iid != self._wave_origin
        )

        if not pending and not any_coord_pending and not any_harmony_pending:
            self._wave_active     = False
            self._wave_veh_id     = -1
            self._wave_origin     = -1
            self._wave_served_ids = set()
            if LOG_CORRIDOR:
                _vprint(
                    f"[CORRIDOR WAVE] t={time:.1f} WAVE COMPLETE — "
                    f"independent TSP ban fully lifted for all corridor junctions"
                )
            _record_wave_event(
                time, self.name, "wave_complete",
                source_jct=-1,
                target_jct=-1,
                veh_id=-1,
            )

    # ------------------------------------------------------------------
    def step(self, time: float, timeSta: float):
        """Called every simulation step from AAPIPostManage."""
        if not self._ctrl_map and not self._ic_map:
            return

        # Process Kalman pre-green requests first (works for both GB and HARMONY modes)
        if COORDINATED_TSP:
            self._process_pre_requests(time, timeSta)
            self._expire_fired_prearms(time)
            self._check_wave_complete(time)

        # ── Keep Kalman trackers current between junction detections ────────────────
        # Advance each tracker by the elapsed time so that ETA queries always
        # reflect the bus's CURRENT estimated position, not its state at the
        # last junction.  Without this, a bus detected at position=0 would
        # always return an ETA based on position=0, not position=speed*dt.
        for _trk_vid, _trk in self._trackers.items():
            if _trk.last_t is not None and time > _trk.last_t + 0.5:
                _trk.predict(time - _trk.last_t)
                _trk.last_t = time

        # ── Refresh pending pre-request ETAs with current shockwave state ─────────
        # The ETA queued in _pre_requests was computed when the bus was at the
        # previous junction.  As the bus travels (tracker advances above) and
        # queue conditions change, the ETA shifts.  Refresh it every
        # _ETA_REFRESH_INTERVAL_S so the timing window fires at the right moment.
        _ETA_REFRESH_INTERVAL_S = 1.0
        if COORDINATED_TSP and self._pre_requests:
            _refresh_due = time - getattr(self, '_last_eta_refresh_t', -999.0) >= _ETA_REFRESH_INTERVAL_S
            if _refresh_due:
                self._last_eta_refresh_t = time
                for _ri_id, _req in list(self._pre_requests.items()):
                    _rv = _req[0]   # veh_id
                    _re = _req[1]   # eta_t
                    _rs = _req[2]   # bus_sg
                    _ri = _req[3]   # issued_t
                    _rsrc = _req[4] if len(_req) >= 5 else -1
                    if _re < time - 5.0:   # already past ETA — skip
                        continue
                    _trk_live = self._trackers.get(_rv)
                    _tgt_pos  = self.corridor_pos.get(_ri_id)
                    if _trk_live is None or _tgt_pos is None:
                        continue
                    # Source junction for signal_aware_eta: use wave origin or source
                    _src_id = self._wave_origin if self._wave_origin > 0 else _rsrc
                    if _src_id > 0 and _src_id in self._route_index:
                        _new_eta = self._signal_aware_eta(_src_id, _ri_id, _trk_live, time)
                    else:
                        _new_eta = _trk_live.eta(_tgt_pos, time)
                    # Apply shockwave queue correction
                    _n_gb  = self._ctrl_map.get(_ri_id)
                    _n_ic  = self._ic_map.get(_ri_id)
                    _n_sg  = _n_gb.bus_sg if _n_gb else None
                    if COORDINATION_ALGO in ("SHOCKWAVE", "ADAPTIVE"):
                        _new_eta, _, _, _ = self._shockwave_eta_adjust(
                            _n_gb, _n_sg, _new_eta, next_ic=_n_ic)
                    # Only update if changed by > 5 s to avoid jitter
                    if abs(_new_eta - _re) > 5.0:
                        self._pre_requests[_ri_id] = (_rv, _new_eta, _rs, _ri, _rsrc)
                        if LOG_CORRIDOR:
                            log_to_file(
                                f"[ETA_REFRESH] jct={_ri_id} bus={_rv} "
                                f"old_eta_in={_re - time:.1f}s new_eta_in={_new_eta - time:.1f}s "
                                f"delta={_new_eta - _re:+.1f}s")

        states    = {iid: c.state            for iid, c in self._ctrl_map.items()}
        n_groups  = {iid: len(c.phase_groups) for iid, c in self._ctrl_map.items()}
        bus_reqs  = {iid: c.bus_request       for iid, c in self._ctrl_map.items()}

        n_idle       = sum(1 for s in states.values() if s == GroupBasedController.IDLE)
        n_green      = sum(1 for s in states.values() if s == GroupBasedController.GREEN)
        n_intergreen = sum(1 for s in states.values() if s == GroupBasedController.INTERGREEN)
        any_bus_req  = any(v is not None for v in bus_reqs.values())

        # ── Periodic state dump ───────────────────────────────────────────────
        if LOG_CORRIDOR and time - self._last_log_t >= self.LOG_CORRIDOR_INTERVAL:
            self._last_log_t = time
            detail = " | ".join(
                f"{iid}:{states[iid][:1]}pg{n_groups[iid]}"
                for iid in self.inter_ids
            )
            _vprint(
                f"[CORRIDOR] t={time:.0f} group={self.name} "
                f"idle={n_idle} green={n_green} ig={n_intergreen} "
                f"bus_req={any_bus_req} | {detail}"
            )

        # ── Group sync detection ──────────────────────────────────────────────
        all_idle = n_idle == len(self._ctrl_map)
        if all_idle and not any_bus_req and time - self._last_sync_t > 5.0:
            self._last_sync_t = time
            self._sync_count += 1
            if LOG_CORRIDOR:
                _vprint(
                    f"[CORRIDOR SYNC] t={time:.0f} group={self.name} "
                    f"sync#{self._sync_count} — all {len(self._ctrl_map)} members IDLE "
                    f"(phase_groups={list(n_groups.values())})"
                )

    # ------------------------------------------------------------------
    def summary(self) -> str:
        _late_n = int(self._prearm_stats.get('late_success', 0) or 0)
        _late_sum = float(self._prearm_stats.get('late_success_delay_s', 0.0) or 0.0)
        _late_avg = (_late_sum / _late_n) if _late_n > 0 else 0.0
        _fired = int(self._prearm_stats.get('fired', 0) or 0)
        _success = int(self._prearm_stats.get('success', 0) or 0)
        _succ_pct = (100.0 * _success / _fired) if _fired > 0 else 0.0
        _q = int(self._algo_diag.get('queued', 0) or 0)
        _sw_n = int(self._algo_diag.get('sw_adj_count', 0) or 0)
        _sw_sum = float(self._algo_diag.get('sw_adj_total_s', 0.0) or 0.0)
        _sw_avg = (_sw_sum / _sw_n) if _sw_n > 0 else 0.0
        _sw_max = float(self._algo_diag.get('sw_adj_max_s', 0.0) or 0.0)
        _adp_n = int(self._algo_diag.get('adaptive_fire_count', 0) or 0)
        _adp_dyn = int(self._algo_diag.get('adaptive_dynamic_count', 0) or 0)
        _adp_sum = float(self._algo_diag.get('adaptive_lead_total_s', 0.0) or 0.0)
        _adp_avg = (_adp_sum / _adp_n) if _adp_n > 0 else 0.0
        _adp_min = float(self._algo_diag.get('adaptive_lead_min_s', 1e9) or 1e9)
        _adp_max = float(self._algo_diag.get('adaptive_lead_max_s', 0.0) or 0.0)
        if _adp_n <= 0 or _adp_min >= 1e8:
            _adp_min = 0.0
        return (
            f"CorridorCoordinator group={self.name} "
            f"members={self.inter_ids} syncs={self._sync_count} "
            f"algo={COORDINATION_ALGO} "
            f"pre_arms_issued={self._pre_arm_count} "
            f"pre_arms_pending={len(self._pre_requests)} "
            f"fired={self._prearm_stats.get('fired', 0)} "
            f"success={self._prearm_stats.get('success', 0)} "
            f"success_pct={_succ_pct:.1f}% "
            f"missed={self._prearm_stats.get('missed', 0)} "
            f"expired={self._prearm_stats.get('expired', 0)} "
            f"discarded={self._prearm_stats.get('discarded', 0)} "
            f"late_success={_late_n} "
            f"late_success_delay_s={_late_sum:.1f} "
            f"avg_late_success_delay_s={_late_avg:.1f} "
            f"sw_adj={_sw_n}/{_q} sw_adj_avg_s={_sw_avg:.1f} sw_adj_max_s={_sw_max:.1f} "
            f"adp_dynamic={_adp_dyn}/{_adp_n} adp_lead_avg_s={_adp_avg:.1f} "
            f"adp_lead_min_s={_adp_min:.1f} adp_lead_max_s={_adp_max:.1f}"
        )

    # ------------------------------------------------------------------
    def periodic_replan(self, time: float, timeSta: float, ctrl_map: dict):
        """
        Once per DCTSP_REPLAN_INTERVAL_S, walk every consecutive managed
        intersection pair in the corridor and apply a forward offset correction
        if the signal timing has drifted from the ideal green-band alignment.

        This is the "cycle-level forward OC" described in the DC TSP paper —
        independent of bus events, maintaining synchronisation continuously.
        Only active when GLOBAL_REWARD_MODE = True and corridor positions are set.
        """
        if not GLOBAL_REWARD_MODE or not self.corridor_pos:
            return
        if not hasattr(self, '_last_replan_t'):
            self._last_replan_t = -9999.0
        if time - self._last_replan_t < DCTSP_REPLAN_INTERVAL_S:
            return
        self._last_replan_t = time

        route = self.route_inter_ids
        design_speed_ms = 10.0   # 36 km/h typical bus operating speed

        for i in range(len(route) - 1):
            src_id = route[i]
            tgt_id = route[i + 1]
            src_ctrl = ctrl_map.get(src_id)
            tgt_ctrl = ctrl_map.get(tgt_id)
            if src_ctrl is None or tgt_ctrl is None:
                continue
            try:
                src_pos  = self.corridor_pos.get(src_id, 0.0)
                tgt_pos  = self.corridor_pos.get(tgt_id, 0.0)
                dist_m   = abs(tgt_pos - src_pos)
                travel_s = dist_m / max(design_speed_ms, 1.0)

                src_node = getattr(src_ctrl, 'node_id', src_id)
                tgt_node = getattr(tgt_ctrl, 'node_id', tgt_id)
                src_bp   = int(getattr(src_ctrl, 'BusPhase', 1) or 1)
                tgt_bp   = int(getattr(tgt_ctrl, 'BusPhase', 1) or 1)
                src_bp_dur = float(getattr(src_ctrl, 'BusPhaseDuration', 30) or 30)

                # Time until src bus phase green
                src_cur  = int(ECIGetCurrentPhase(src_node))
                src_pl   = getattr(src_ctrl, 'phase_list', [])
                src_t_to_bp = 0.0
                if src_cur != src_bp and src_pl and src_cur in src_pl:
                    ci = src_pl.index(src_cur)
                    ps = float(ECIGetStartingTimePhase(src_node))
                    rem = max(0.0, float(GetPhaseDuration(src_node, src_cur, timeSta))
                              - max(0.0, time - ps))
                    src_t_to_bp = rem
                    for k in range(1, len(src_pl)):
                        ph = src_pl[(ci + k) % len(src_pl)]
                        if ph == src_bp:
                            break
                        src_t_to_bp += float(GetPhaseDuration(src_node, ph, timeSta) or 0)

                # Ideal bus arrival at tgt = midpoint of src green + travel time
                ideal_arrive = time + src_t_to_bp + src_bp_dur * 0.5 + travel_s

                # Time until tgt bus phase green
                tgt_cur  = int(ECIGetCurrentPhase(tgt_node))
                tgt_pl   = getattr(tgt_ctrl, 'phase_list', [])
                tgt_t_to_bp = 0.0
                if tgt_cur != tgt_bp and tgt_pl and tgt_cur in tgt_pl:
                    ci2 = tgt_pl.index(tgt_cur)
                    ps2 = float(ECIGetStartingTimePhase(tgt_node))
                    rem2 = max(0.0, float(GetPhaseDuration(tgt_node, tgt_cur, timeSta))
                               - max(0.0, time - ps2))
                    tgt_t_to_bp = rem2
                    for k in range(1, len(tgt_pl)):
                        ph2 = tgt_pl[(ci2 + k) % len(tgt_pl)]
                        if ph2 == tgt_bp:
                            break
                        tgt_t_to_bp += float(GetPhaseDuration(tgt_node, ph2, timeSta) or 0)

                tgt_bp_dur  = float(getattr(tgt_ctrl, 'BusPhaseDuration', 30) or 30)
                tgt_green_mid = time + tgt_t_to_bp + tgt_bp_dur * 0.5

                # Offset error: positive = ideal arrives late vs green mid
                offset_err = ideal_arrive - tgt_green_mid
                if abs(offset_err) <= 8.0:
                    continue   # within tolerance — no correction

                # Apply forward OC: shift tgt's current non-bus phase
                if tgt_cur != tgt_bp:
                    _correction = max(-12.0, min(12.0, offset_err))
                    _cur_dur = float(GetPhaseDuration(tgt_node, tgt_cur, timeSta) or 30.0)
                    _new_dur = max(5.0, min(120.0, _cur_dur + _correction))
                    if abs(_new_dur - _cur_dur) > 1.0:
                        ECIChangeTimingPhase(tgt_node, tgt_cur, _new_dur, timeSta)
                        _record_wave_event(
                            time, self.name, "periodic_replan",
                            source_jct=src_id, target_jct=tgt_id,
                            note=f"err={offset_err:+.1f}s corr={_correction:+.1f}s",
                        )
                        log_to_file(
                            f"[PERIODIC_REPLAN] group={self.name} "
                            f"jct{src_id}→jct{tgt_id} "
                            f"offset_err={offset_err:+.1f}s "
                            f"correction={_correction:+.1f}s "
                            f"new_dur={_new_dur:.1f}s",
                            force=True)
            except Exception:
                pass   # advisory — never crash the simulation


# module-level list populated in AAPIInit
corridor_coordinators: list = []


# ── Q-learning helper functions ───────────────────────────────────────────────

def _rl_state_bin(sigma_in: float, bus_eta_s: float,
                  no_action_delay: float, phase_is_bus: bool) -> tuple:
    """Discretise the per-decision state into a hashable 4-tuple (s_b, e_b, d_b, p_b).

    sigma_in (headway deviation, s):
        0 early-large (<-30), 1 early-small (-30 to -5), 2 on-time (-5 to 5),
        3 late-small (5 to 20), 4 late-large (20 to 60), 5 very-late (>60)
    bus_eta_s (estimated seconds to stop-line):
        0 immediate (0-5), 1 near (5-15), 2 medium (15-30), 3 far (>30)
    no_action_delay (expected delay without TSP, s):
        0 none (0-2), 1 small (2-10), 2 medium (10-30), 3 large (>30)
    phase_is_bus:
        0 non-bus phase active (INS is the natural help), 1 bus phase active (GE)
    """
    if sigma_in < -30:    s_b = 0
    elif sigma_in < -5:   s_b = 1
    elif sigma_in <= 5:   s_b = 2
    elif sigma_in <= 20:  s_b = 3
    elif sigma_in <= 60:  s_b = 4
    else:                 s_b = 5
    if bus_eta_s < 5:    e_b = 0
    elif bus_eta_s < 15: e_b = 1
    elif bus_eta_s < 30: e_b = 2
    else:                e_b = 3
    if no_action_delay < 2:    d_b = 0
    elif no_action_delay < 10: d_b = 1
    elif no_action_delay < 30: d_b = 2
    else:                      d_b = 3
    return (s_b, e_b, d_b, int(phase_is_bus))


def _rl_get_q(jct_id: int, state_bin: tuple, init_vals=None) -> list:
    """Return (and lazily initialise) the Q-value list for (jct, state).

    init_vals — list of estimated rewards per action from _dctsp_eval_action.
    Used only on first visit to seed the table with a useful prior.
    """
    n   = len(DCTSP_RL_ACTION_SPACE)
    tbl = _dctsp_q_table.setdefault(int(jct_id), {})
    if state_bin not in tbl:
        tbl[state_bin] = (list(init_vals)
                          if (init_vals is not None and len(init_vals) == n)
                          else [0.0] * n)
    return tbl[state_bin]


def _rl_update_q(jct_id: int, state_bin: tuple, action_idx: int,
                 r_est: float, next_jct_id: int, next_state_bin: tuple,
                 next_init_vals=None) -> float:
    """Q-learning Bellman TD update across two consecutive intersections.

      Q(s,a) ← Q(s,a) + α · [r + γ·max_a' Q(s',a') − Q(s,a)]

    Returns the signed TD error (for logging).
    """
    q_cur  = _rl_get_q(jct_id, state_bin)
    q_next = _rl_get_q(next_jct_id, next_state_bin, next_init_vals)
    td_target             = r_est + RL_DISCOUNT * max(q_next)
    td_error              = td_target - q_cur[action_idx]
    q_cur[action_idx]    += RL_LEARNING_RATE * td_error
    return td_error


# ─────────────────────────────────────────────────────────────────────────────
# BXT CTM Q-learning helpers (Chanloha et al. 2014, Comput. J. bxt126)
# ─────────────────────────────────────────────────────────────────────────────

def _bxt_state_bin(n0_bus: float, side_ratio: float,
                   phase_is_bus: bool, bus_eta_s: float) -> tuple:
    """Discretise the per-decision state into a hashable 4-tuple (b_b, s_b, p_b, e_b).

    Follows the CTM cell-count state formulation from Chanloha et al. (2014)
    Eq. 1-3: state captures bus-approach queue, cross-traffic saturation,
    current phase, and bus proximity.

    n0_bus    (estimated bus-approach queue, veh):
        0 empty   (0-2 veh), 1 light (2-8), 2 medium (8-20), 3 heavy (>20)
    side_ratio (side pax pressure / bus pax pressure, dimensionless):
        0 low (<0.3), 1 moderate (0.3-0.8), 2 high (0.8-1.5), 3 saturated (>1.5)
    phase_is_bus:
        0 non-bus phase active, 1 bus phase active
    bus_eta_s (ETA to stop line, s):
        0 immediate (0-5), 1 near (5-15), 2 medium (15-30), 3 far (>30)
    """
    if n0_bus < 2.0:    b_b = 0
    elif n0_bus < 8.0:  b_b = 1
    elif n0_bus < 20.0: b_b = 2
    else:               b_b = 3

    if side_ratio < 0.3:  s_b = 0
    elif side_ratio < 0.8: s_b = 1
    elif side_ratio < 1.5: s_b = 2
    else:                  s_b = 3

    if bus_eta_s < 5.0:   e_b = 0
    elif bus_eta_s < 15.0: e_b = 1
    elif bus_eta_s < 30.0: e_b = 2
    else:                  e_b = 3

    return (b_b, s_b, int(phase_is_bus), e_b)


def _bxt_get_q(jct_id: int, state_bin: tuple, init_vals=None) -> list:
    """Return (and lazily initialise) the BXT Q-value list for (jct, state).

    Uses _dctsp_bxt_q_table (separate from MARL's _dctsp_q_table) so the two
    learning algorithms do not interfere.
    """
    n   = len(DCTSP_RL_ACTION_SPACE)
    tbl = _dctsp_bxt_q_table.setdefault(int(jct_id), {})
    if state_bin not in tbl:
        tbl[state_bin] = (list(init_vals)
                          if (init_vals is not None and len(init_vals) == n)
                          else [0.0] * n)
    return tbl[state_bin]


def _bxt_update_q(jct_id: int, state_bin: tuple, action_idx: int,
                  r_bxt: float) -> float:
    """
    BXT single-step Q update (no cross-junction bootstrapping).

      Q(s,a) ← Q(s,a) + α·[r_bxt − Q(s,a)]

    The paper uses γ=0.005 for very short-horizon discounting; since we do
    not have the next-state available at decision time (the bus has not yet
    crossed the intersection) we use a terminal update (equivalent to setting
    Q(s',·)=0, matching the paper's within-episode update).
    Returns the TD error.
    """
    q_cur = _bxt_get_q(jct_id, state_bin)
    td_err            = r_bxt - q_cur[action_idx]
    q_cur[action_idx] += float(BXT_ALPHA) * td_err
    return td_err

class IntersectionController:
    def set_future_offset(self, offset_s):
        """Set the offset for the next cycle (anticipatory coordination)."""
        self.future_offset_s = float(offset_s)
        log_to_file(f"[GLOBAL_REWARD] inter={self.id} set future_offset={offset_s:.2f}s", force=True)

    def __init__(self, config):

        # ── static config ─────────────────────────────────────────────
        self.config  = config
        raw_id = config['IntersectionID']
        if not isinstance(raw_id, int):
            raise TypeError(
                f"IntersectionID must be int, got {type(raw_id).__name__}: {raw_id!r} "
                f"— check intersection_configs.py for unfilled placeholder IDs")
        
        self.id = raw_id
        self.TSPStrategy =0
        self.current_phase = 1
        self.stats   = stats
        self.CarOcc  = config['CarOcc']
        self.BusOcc  = config['BusOcc']
        self.id      = config["IntersectionID"]
        # node_id: the Aimsun-internal node ID for all topology/signal API calls.
        # Start with any explicitly configured override, defaulting to self.id.
        # _resolve_node_id() (called after section tracking is set up) will
        # auto-correct this via section topology if the configured value is wrong.
        self.node_id = config.get("AimsunNodeID", self.id)

        self.BusPhase         = config.get("BusPhase", 2)

        # BusPhaseDuration — use config value if present, otherwise discover
        # from Aimsun live plan.  Allows minimal configs with just IntersectionID.
        _bpd = config.get("BusPhaseDuration")
        if _bpd is None:
            try:
                _bpd = GetPhaseDuration(self.id, self.BusPhase, 0.0)
                if not _bpd or _bpd <= 0:
                    _bpd = 30.0
            except Exception:
                _bpd = 30.0
        self.BusPhaseDuration = float(_bpd)

        self.BusDet           = config.get("BusDet", [])
        self.main_sections = config.get('MainSections', [])
        self.side_sections = config.get('SideSections', [])
        self.call_sections = config.get(
            'call_sections',
            config.get('BusCallDetectors',
                    config.get('BusDet', []))
        )

        # These three fields are optional — minimal configs may omit them.
        # Default to empty so downstream code sees a consistent type (list/dict).
        self.UpDetList        = config.get("UpDetList", [])
        self.SignalGroupIDList = config.get("SignalGroupIDList", [])
        self.PhaseIndex       = config.get("PhaseIndex", {})
        self.VehLength        = config.get("VehLength", 4.5)
        self.DetLength        = config.get("DetLength", 5)
        self.JamDensity       = config.get("JamDensity", 200)
        self.SaturationDensity= config.get("SaturationDensity", 35)
        self.SaturationFlow   = config.get("SaturationFlow", 1800)
        self.GE_lower_bound   = config.get("GE_lower_bound", 0)
        self.GE_upper_bound   = config.get("GE_upper_bound", 20)
        self.BP_lower_bound   = config.get("BP_lower_bound", 5)
        self.BP_upper_bound   = config.get("BP_upper_bound", 60)
                # === TSP COOLDOWN (prevents spam) ===
        self.last_tsp_action_time = 0.0          # ← ADD THIS
        self.tsp_cooldown_seconds = 60.0         # 60 s = one full cycle on most plans
        # Per-bus approach detection debounce: {bus_id: last_detection_record_t}
        # Prevents per-step recording inflating skip/detection counts.
        # Reset when a bus leaves the zone (zone_exit) or after 120 s.
        self._approach_det_t: dict = {}   # bus_id -> sim_time of last stat record
        if "DetDistance" in self.config:
            d = self.config["DetDistance"]
            if not isinstance(d, (list, tuple)) or len(d) == 0:
                self.config["DetDistance"] = [[50.0]]
            elif not isinstance(d[0], (list, tuple)):
                self.config["DetDistance"] = [d]
        else:
            self.config["DetDistance"] = [[50.0]]
        self.DetDistance = self.config["DetDistance"]
         
        self.max_iterations   = config.get("max_iterations", 20)
        self.harmony_memory_size = config.get("harmony_memory_size", 10)
        self.hmcr             = config.get("hmcr", 0.9)
        self.par              = config.get("par", 0.3)
        self.NumberOfLanes    = config.get("NumberOfLanes", 1)

        self.CarOcc = config.get('CarOcc', 1.2)
        self.BusOcc = config.get('BusOcc', 40.0)
        self.TruckOcc = config.get('TruckOcc', self.CarOcc)
        

        # ── URTSP config — read from config dict or use defaults ──────
        u = URTSP_DEFAULTS
        self.urtsp_ge_extension      = min(config.get("GE_extension", u["GE_extension"]), MAX_GE_EXTENSION_S)
        self.urtsp_ins_min           = config.get("insertion_min_duration",  u["insertion_min_duration"])
        self.urtsp_ins_max           = config.get("insertion_max_duration",  u["insertion_max_duration"])
        self.urtsp_cycle_length      = config.get("cycle_length",            u["cycle_length"])
        self.urtsp_detection_window  = config.get("detection_window_m",      u["detection_window_m"])
        self.urtsp_pt_line_filter    = config.get("priority_pt_line_ids",    u["priority_pt_line_ids"])

        # call detectors: prefer dedicated URTSP list, else use BusDet
        self.urtsp_call_det_ids = config.get("BusCallDetectors", self.BusDet)
        self.urtsp_exit_det_ids = config.get("BusExitDetectors", [])

        # ── resolve detector geometry once at init ────────────────────
        self._urtsp_call_geometry = {}   # {det_id: (section_id, ini_pos, fin_pos)}
        self._urtsp_exit_geometry = {}
        self._resolve_urtsp_geometry()

        # ── URTSP runtime state (instance variables — no globals) ─────
        self._urtsp_flag               = 0      # 0=idle 1=extension 2=insertion
        self._urtsp_prev_phase         = -1
        self._urtsp_prev_phase_elapsed = -1.0
        self._urtsp_insertion_start    = -1.0
        self._urtsp_granted_this_cycle = False
        self._urtsp_cycle_reset_time   = -1.0
        self._urtsp_served_veh_ids     = set()
        self._urtsp_active_veh_id      = -1
        self._urtsp_bus_phase_nominal  = GetPhaseDuration(self.node_id, self.BusPhase, 0.0)
        # end-of-run counters
        self._urtsp_n_detections   = 0
        self._urtsp_n_extensions   = 0
        self._urtsp_n_insertions   = 0
        self._urtsp_n_exit_clears  = 0
        self._urtsp_n_cap_clears   = 0

        # ── DC TSP POZ travel-time tracking (GLOBAL_REWARD_MODE) ────────────
        # Tracks rolling mean POZ travel time (T̄_n^POZ in Eq. 6).
        # Updated when a bus completes its run through the intersection zone.
        self._poz_travel_times: list  = []     # rolling last 10 POZ travel times (s)
        self._mean_poz_t:       float = 30.0   # rolling mean T̄_POZ (s)
        self._poz_checkin_t:    dict  = {}     # {veh_id: checkin_sim_time_s}
        # Rolling mean POZ transit time observed under NO_ACTION at this junction.
        # Used as the empirical NO_TSP baseline for actual delay-saving computation.
        # Initialised to _mean_poz_t; updated every time the bus exits without TSP.
        self._no_action_poz_ema_s: float = 30.0

        # ── Headway tracking for graduated GE and early-bus truncation ──────
        # Implements D2 TSP / DC TSP proposals 4 & 5:
        #   σ > 0  → bus is late  → scale GE up proportionally
        #   σ < 0  → bus is early → truncate current extension or skip new one
        self._hw_last_veh_id:   int   = -1     # veh_id of last detected bus
        self._hw_last_detect_t: float = -1.0   # time of last NEW bus detection
        self._hw_observed:      list  = []     # rolling inter-bus gaps (s), max 10
        self._hw_mean_s:        float = 300.0  # rolling mean headway (default 5 min)
        self._hw_sigma_current: float = 0.0    # σ for the bus currently detected

        # ── GroupBasedController sub-controller (GROUP_BASED modes only) ──
        # Always None for HARMONY / URTSP / REWARD_TSP / NORMAL modes.
        # Set by GroupBasedController.__init__ when CONTROL_MODE is group-based.
        self.gb = None

        # ── Corridor coordination back-reference (HARMONY mode) ──────────
        # Set by CorridorCoordinator.__init__ when CONTROL_MODE == "HARMONY".
        # None when this intersection is not part of a coordinated group.
        self._corridor_coord    = None
        # Pre-arm request fired by coordinator: (veh_id, eta_t, issued_t).
        # When set, check_bus_priority applies TSP immediately without waiting
        # for local detector presence (Kalman ETA replaces BusSpeed-based ETA).
        self._harmony_prearm    = None

        # ── general dynamic state ─────────────────────────────────────
        self.prev_total_delay   = 0.0
        self.TSPActiveTime      = 0
        self.flag               = 0      # used by HARMONY / NORMAL paths
        self.previous_phase     = None
        self.last_detected_bus_id = -1
        self.incoming_sections  = []
        self._initialize_section_tracking()
        self._resolve_node_id()   # verify/auto-fix node_id after sections are known
        self.phase_list         = []

        num_phases = ECIGetNumberPhases(self.id)
        self.phase_list = list(range(1, num_phases + 1))

        stats_car_pos = getattr(self.stats, '_car_pos', -1)
        stats_bus_pos = getattr(self.stats, '_bus_pos', -1)
        scan_car_pos, scan_bus_pos, scan_truck_pos = _scan_named_vehicle_type_positions()

        self.bus_type_pos = stats_bus_pos if stats_bus_pos > 0 else scan_bus_pos
        if self.bus_type_pos <= 0:
            cfg_bus_pos = safe_float(config.get('BUS_TYPE_POS', -1), -1.0)
            self.bus_type_pos = int(cfg_bus_pos) if cfg_bus_pos > 0 else -1

        self.car_type_pos = stats_car_pos if stats_car_pos > 0 else scan_car_pos
        if self.car_type_pos <= 0:
            self.car_type_pos = _choose_car_type_pos(
                self.bus_type_pos,
                scan_truck_pos if scan_truck_pos > 0 else getattr(self.stats, '_truck_pos', -1),
                preferred_pos=self.car_type_pos)

        if LOG_INIT: AKIPrintString(f"[INIT] Inter {self.id} | car_type_pos={self.car_type_pos} bus_type_pos={self.bus_type_pos}")
        self.print_config_summary()
        if LOG_INIT: AKIPrintString(f"[INIT] Phase list: {self.phase_list}")

        self.initialize_state()
        # Warmup: suppress TSP for the first two signal cycles so the
        # network can settle before any priority decisions are made.
        _warmup = 2.0 * float(self.config.get('CycleTime', 135))
        self.TSPActiveTime = _warmup

        initial_state = self.build_state()
        state_dim  = len(initial_state)
        action_dim = len(self.UpDetList)
        # ── RL agent — only load when mode is RL ──────────────────────
        self.rl_agent   = None
        self.TRAIN_MODE = False
        if CONTROL_MODE == 'RL':
            try:
                from rl_agent import RLIntersectionAgent
                self.rl_agent   = RLIntersectionAgent(state_dim, action_dim, algorithm='DQN')
                self.TRAIN_MODE = True
                self.rl_agent.load_model("trained_model.pth")
                if LOG_INIT: AKIPrintString(f"[RL] Agent loaded for intersection {self.id}")
            except Exception as e:
                _vprint(f"[RL] WARNING: Could not load RL agent: {e}")

        if LOG_URTSP: AKIPrintString(f"[URTSP] Intersection {self.id} ready | "
                       f"mode={CONTROL_MODE} | "
                       f"call_dets={self.urtsp_call_det_ids} | "
                       f"exit_dets={self.urtsp_exit_det_ids}")

    # =========================================================================
    # URTSP — GEOMETRY RESOLUTION
    # =========================================================================


    
    
    def _resolve_urtsp_geometry(self):
        """Cache section_id and positions for call and exit detectors."""
        for det_id in self.urtsp_call_det_ids:
            props = AKIDetGetPropertiesDetectorById(det_id)
            if props.report < 0:
                if LOG_URTSP: AKIPrintString(f"[URTSP] WARNING: call det {det_id} not found")
                continue
            self._urtsp_call_geometry[det_id] = (
                props.IdSection, props.InitialPosition, props.FinalPosition)
            if LOG_URTSP: AKIPrintString(f"[URTSP] call det={det_id} "
                           f"section={props.IdSection} "
                           f"pos=[{props.InitialPosition:.1f},{props.FinalPosition:.1f}]m")

        for det_id in self.urtsp_exit_det_ids:
            props = AKIDetGetPropertiesDetectorById(det_id)
            if props.report < 0:
                if LOG_URTSP: AKIPrintString(f"[URTSP] WARNING: exit det {det_id} not found")
                continue
            self._urtsp_exit_geometry[det_id] = (
                props.IdSection, props.InitialPosition, props.FinalPosition)
            if LOG_URTSP: AKIPrintString(f"[URTSP] exit det={det_id} "
                           f"section={props.IdSection} "
                           f"pos=[{props.InitialPosition:.1f},{props.FinalPosition:.1f}]m")

        # read nominal bus-phase duration from background plan
        self._urtsp_bus_phase_nominal = GetPhaseDuration(
            self.id, self.BusPhase, 0.0)
        if LOG_URTSP: AKIPrintString(f"[URTSP] bus phase nominal = {self._urtsp_bus_phase_nominal:.1f}s")

    
    
    def _resolve_urtsp_geometry(self):
        for det_id in self.urtsp_call_det_ids:
            props = AKIDetGetPropertiesDetectorById(det_id)
            if props.report >= 0:
                self._urtsp_call_geometry[det_id] = (props.IdSection, props.InitialPosition, props.FinalPosition)

        for det_id in self.urtsp_exit_det_ids:
            props = AKIDetGetPropertiesDetectorById(det_id)
            if props.report >= 0:
                self._urtsp_exit_geometry[det_id] = (props.IdSection, props.InitialPosition, props.FinalPosition)

        self._urtsp_bus_phase_nominal = GetPhaseDuration(self.node_id, self.BusPhase, 0.0)
    
    # =========================================================================
    # URTSP — PT VEHICLE HELPERS
    # =========================================================================

    def _get_pt_vehicles(self):
        """
        Return list of (line_id, inf) for PT vehicles AND injected buses.
        Primary: scan registered PT lines.
        Fallback: scan bus vehicles directly on call sections (catches
                  injected buses not registered as PT line vehicles).
        """
        result = []
        seen   = set()
        allowed = set(self.urtsp_pt_line_filter) if self.urtsp_pt_line_filter else None

        # ── Primary: registered PT lines ─────────────────────────────
        for li in range(AKIPTGetNumberLines()):
            line_id = AKIPTGetIdLine(li)
            if allowed is not None and line_id not in allowed:
                continue
            for vi in range(AKIGetNbVehiclesFollowingPTLine(line_id)):
                veh_id = AKIGetVehicleFollowingPTLine(line_id, vi)
                inf    = AKIPTVehGetInf(veh_id)
                if inf.report >= 0:
                    result.append((line_id, inf))
                    seen.add(veh_id)

        # ── Fallback: scan bus vehicles directly on call sections ─────
        for det_id, (sec_id, _, _) in self._urtsp_call_geometry.items():
            n = AKIVehStateGetNbVehiclesSection(sec_id, True)
            for i in range(n):
                inf = AKIVehStateGetVehicleInfSection(sec_id, i)
                if inf.idVeh in seen:
                    continue
                if inf.type != self.bus_type_pos:
                    continue
                result.append((-1, inf))
                seen.add(inf.idVeh)

        return result

    def _scan_urtsp_call(self, pt_vehicles):
        """
        Scan call detector zones for an unserved eligible bus.
        Scans from position 0 to fin_pos + window to catch approaching buses.
        Returns (veh_id, line_id, det_id, pos) or (-1,-1,-1,-1.0).
        """
        w = self.urtsp_detection_window
        for det_id, (sec_id, ini_pos, fin_pos) in self._urtsp_call_geometry.items():
            # Widen UPSTREAM only — fin_pos is the intended downstream boundary.
            # Matches TSP_single_intersection: detect_ini widened by window,
            # detect_fin preserved as fin_pos so buses that already passed are excluded.
            detect_ini = max(0.0, fin_pos - w)
            detect_fin = fin_pos
            for line_id, inf in pt_vehicles:
                if inf.idSection != sec_id:
                    continue
                if not (detect_ini <= inf.CurrentPos <= detect_fin):
                    continue
                veh_id = inf.idVeh
                pos    = inf.CurrentPos
                if veh_id in self._urtsp_served_veh_ids:
                    pass
                elif self._urtsp_flag != 0:
                    _vprint(
                        f"[URTSP] SKIP veh={veh_id} line={line_id} "
                        f"pos={pos:.1f}m reason=tsp_active(flag={self._urtsp_flag})")
                    self._urtsp_served_veh_ids.add(veh_id)
                elif self._urtsp_granted_this_cycle:
                    _vprint(
                        f"[URTSP] SKIP veh={veh_id} line={line_id} "
                        f"pos={pos:.1f}m reason=already_granted_this_cycle")
                    self._urtsp_served_veh_ids.add(veh_id)
                else:
                    _vprint(
                        f"[URTSP] BUS IN ZONE | veh={veh_id} line={line_id} "
                        f"sec={sec_id} pos={pos:.1f}m zone=[{detect_ini:.1f},{detect_fin:.1f}]m")
                    return veh_id, line_id, det_id, pos
        return -1, -1, -1, -1.0

    def _check_urtsp_exit(self, veh_id, pt_vehicles):
        for _, (sec_id, _, fin_pos) in self._urtsp_exit_geometry.items():
            detect_ini = 0.0
            detect_fin = fin_pos + self.urtsp_detection_window
            for _, inf in pt_vehicles:
                if inf.idVeh == veh_id and inf.idSection == sec_id:
                    if detect_ini <= inf.CurrentPos <= detect_fin:
                        return True
        return False

    def _bus_on_call_section(self, veh_id, pt_vehicles):
        """Return True if veh_id is still on any call detector section."""
        for _, (sec_id, _, _) in self._urtsp_call_geometry.items():
            for _, inf in pt_vehicles:
                if inf.idVeh == veh_id and inf.idSection == sec_id:
                    return True
        return False

    # =========================================================================
    # URTSP — MAIN STATE MACHINE  (replaces run_normal / check_bus_priority)
    # =========================================================================

    def run_urtsp(self, time, timeSta, acycle):
        # ── Diagnostic every 300s: confirm buses are on call sections ──
        if int(time) % 300 == 0 and int(time) != getattr(self, '_last_diag_t', -1):
            self._last_diag_t = int(time)
            pt_count = len(self._get_pt_vehicles())
            for det_id, (sec_id, ini, fin) in self._urtsp_call_geometry.items():
                n = AKIVehStateGetNbVehiclesSection(sec_id, True)
                _vprint(
                    f"[URTSP] DIAG t={time:.0f}s inter={self.id} "
                    f"det={det_id} sec={sec_id} "
                    f"veh_on_section={n} pt_vehicles={pt_count}")

        current_phase  = ECIGetCurrentPhase(self.node_id)
        phase_start    = ECIGetStartingTimePhase(self.node_id)
        phase_elapsed  = time - phase_start
        phase_duration = GetPhaseDuration(self.node_id, current_phase, timeSta)

        pt_vehicles = self._get_pt_vehicles()

        # ── per-cycle grant reset ─────────────────────────────────────
        if self._urtsp_granted_this_cycle and time >= self._urtsp_cycle_reset_time:
            if LOG_URTSP: AKIPrintString(f"[URTSP] cycle grant reset at t={time:.1f}s")
            self._urtsp_granted_this_cycle = False

        # ── expire served_veh_ids ─────────────────────────────────────
        self._urtsp_served_veh_ids = {
            vid for vid in self._urtsp_served_veh_ids
            if self._bus_on_call_section(vid, pt_vehicles)
        }

        # ── FLAG 1: GREEN EXTENSION active ────────────────────────────
        if self._urtsp_flag == 1:
            if current_phase != self.BusPhase:
                self.reset_bus_color(self._urtsp_active_veh_id)
                if LOG_URTSP: AKIPrintString(f"[URTSP] EXTENSION ENDED | t={time:.1f}s "
                               f"resumed phase={current_phase}")
                self._urtsp_flag           = 0
                self._urtsp_active_veh_id  = -1
                _release_focus(time, "urtsp_ge_done")
            return

        # ── FLAG 2: PHASE INSERTION active ───────────────────────────
        if self._urtsp_flag == 2:
            insertion_elapsed = time - self._urtsp_insertion_start
            min_ok      = insertion_elapsed >= self.urtsp_ins_min
            bus_cleared = min_ok and self._check_urtsp_exit(
                self._urtsp_active_veh_id, pt_vehicles)
            cap_reached = insertion_elapsed >= self.urtsp_ins_max

            if bus_cleared or cap_reached:
                self.reset_bus_color(self._urtsp_active_veh_id)
                reason          = "exit_detector" if bus_cleared else "cap"
                restore_elapsed = self._urtsp_prev_phase_elapsed if bus_cleared else 0.0
                _vprint(
                    f"[URTSP] INSERTION ENDED | t={time:.1f}s | reason={reason} "
                    f"duration={insertion_elapsed:.1f}s | "
                    f"restoring phase={self._urtsp_prev_phase} elapsed={restore_elapsed:.1f}s")
                ECIChangeDirectPhase(self.node_id, self._urtsp_prev_phase,
                                     timeSta, time, acycle, restore_elapsed)
                if bus_cleared:
                    self._urtsp_n_exit_clears += 1
                    self.stats.record_tsp_event(self.id, 'exit_clear')
                else:
                    self._urtsp_n_cap_clears  += 1
                    self.stats.record_tsp_event(self.id, 'cap_clear')
                self._urtsp_flag               = 0
                self._urtsp_prev_phase         = -1
                self._urtsp_prev_phase_elapsed = -1.0
                self._urtsp_insertion_start    = -1.0
                self._urtsp_active_veh_id      = -1
                _release_focus(time, "urtsp_ins_done")
            return

        # ── IDLE: scan call detectors ─────────────────────────────────
        veh_id, line_id, det_id, pos = self._scan_urtsp_call(pt_vehicles)
        if veh_id < 0:
            return

        # ── Global bus focus gate ─────────────────────────────────────
        if _is_focus_blocked(veh_id, self.id, time):
            if LOG_URTSP:
                _vprint(
                    f"[BUS_FOCUS] t={time:.1f} inter={self.id} "
                    f"v={veh_id} SUPPRESSED — focus bus={_focus_bus_id}")
            _mark_detection_point(self.id, veh_id, 0.0, 0.0,
                                  time, "focus_suppress")
            return

        self._urtsp_n_detections        += 1
        self._urtsp_served_veh_ids.add(veh_id)
        self._urtsp_granted_this_cycle   = True
        self._urtsp_cycle_reset_time     = time + self.urtsp_cycle_length
        self.stats.record_tsp_event(self.id, 'detection')

        remaining = max(0.0, phase_duration - phase_elapsed)
        _vprint(
            f"[URTSP] DETECTED | t={time:.1f}s | veh={veh_id} line={line_id} "
            f"det={det_id} pos={pos:.1f}m | phase={current_phase} "
            f"elapsed={phase_elapsed:.1f}s dur={phase_duration:.1f}s rem={remaining:.1f}s")

        # ── Headway deviation σ (proposals 4 & 5) ────────────────────
        # _hw_update_sigma is called in detect_bus._hit for IC-detect path;
        # call it here too for URTSP detector-based detection so _hw_sigma_current
        # is always fresh at the moment the GE decision is made.
        if veh_id != self._hw_last_veh_id:
            self._hw_update_sigma(veh_id, time)
        _sigma        = self._hw_sigma_current          # s, positive=late negative=early
        _hw_have_hist = len(self._hw_observed) >= 2
        _hw_mean      = max(self._hw_mean_s, 30.0)

        # ── Strategy 1: GREEN EXTENSION ───────────────────────────────
        if current_phase == self.BusPhase:
            # ── Proposal 5: early-bus truncation (DC TSP case-4) ─────
            # When the bus arrived sooner than 25 % of the mean headway,
            # shorten the current phase to minimum green rather than
            # extending it — keeps the cycle tight for the bus behind.
            _EARLY_FRAC = 0.25
            if _hw_have_hist and _sigma < -_EARLY_FRAC * _hw_mean:
                _trunc_dur = max(phase_elapsed + float(self.GE_lower_bound or 5.0),
                                 self._urtsp_bus_phase_nominal * 0.5)
                _trunc_dur = min(_trunc_dur, phase_duration)   # never lengthen
                ECIChangeTimingPhase(self.node_id, current_phase, _trunc_dur, timeSta)
                self._urtsp_active_veh_id = veh_id
                self._urtsp_flag          = 1
                self._urtsp_n_extensions += 1
                self.highlight_bus(veh_id)
                if veh_id and veh_id > 0:
                    _acquire_focus(veh_id, self.id, time)
                self.stats.record_tsp_event(self.id, 'extension')
                _vprint(
                    f"[URTSP] EARLY TRUNCATE | σ={_sigma:.0f}s mean={_hw_mean:.0f}s "
                    f"trunc_dur={_trunc_dur:.1f}s (proposal 5)")
            else:
                # ── Proposal 4: headway-graduated extension ───────────
                _ge_lb = float(self.GE_lower_bound) if self.GE_lower_bound > 0 else 5.0
                _ge_ub = min(float(self.GE_upper_bound), MAX_GE_EXTENSION_S)
                if _hw_have_hist and _sigma > 0:
                    _ext_frac = min(1.0, _sigma / _hw_mean)
                    _urtsp_ge = _ge_lb + _ext_frac * (_ge_ub - _ge_lb)
                else:
                    _urtsp_ge = self.urtsp_ge_extension   # fall back to config flat value
                new_dur = self._urtsp_bus_phase_nominal + _urtsp_ge
                _vprint(
                    f"[URTSP] GREEN EXTENSION | new_dur={new_dur:.1f}s "
                    f"(nominal={self._urtsp_bus_phase_nominal:.1f}s "
                    f"+ {_urtsp_ge:.1f}s σ={_sigma:.0f}s proposal 4)")
                ECIChangeTimingPhase(self.node_id, current_phase, new_dur, timeSta)
                self._urtsp_active_veh_id = veh_id
                self._urtsp_flag          = 1
                self._urtsp_n_extensions += 1
                self.highlight_bus(veh_id)
                if veh_id and veh_id > 0:
                    _acquire_focus(veh_id, self.id, time)
                self.stats.record_tsp_event(self.id, 'extension')

        # ── Strategy 2: PHASE INSERTION ───────────────────────────────
        else:
            _vprint(
                f"[URTSP] PHASE INSERTION | inserting phase={self.BusPhase} "
                f"interrupted phase={current_phase} at {phase_elapsed:.1f}s")
            self._urtsp_prev_phase         = current_phase
            self._urtsp_prev_phase_elapsed = phase_elapsed
            self._urtsp_insertion_start    = time
            self._urtsp_active_veh_id      = veh_id
            ECIChangeDirectPhase(self.node_id, self.BusPhase,
                                 timeSta, time, acycle, 0)
            self._urtsp_flag            = 2
            self._urtsp_n_insertions   += 1
            self.highlight_bus(veh_id)
            if veh_id and veh_id > 0:
                _acquire_focus(veh_id, self.id, time)
            self.stats.record_tsp_event(self.id, 'insertion')

    def get_urtsp_summary(self):
        """Return a summary string for AAPIFinish."""
        return (
            f"[URTSP] intersection={self.id} | "
            f"detections={self._urtsp_n_detections} | "
            f"extensions={self._urtsp_n_extensions} | "
            f"insertions={self._urtsp_n_insertions} | "
            f"exit_det_clears={self._urtsp_n_exit_clears} | "
            f"cap_clears={self._urtsp_n_cap_clears}"
        )

    def _hw_update_sigma(self, veh_id: int, detect_t: float) -> float:
        """
        Update rolling mean inter-bus headway and return σ = actual_gap − mean.

        Positive σ: bus arrived later than the running average → late bus.
        Negative σ: bus arrived sooner than the running average → early bus.
        Returns 0.0 when there is insufficient history (< 2 observations) so
        that the first two buses after startup are treated as on-time.

        Side-effects: updates _hw_last_veh_id, _hw_last_detect_t,
        _hw_observed, _hw_mean_s, _hw_sigma_current.
        """
        sigma = 0.0
        if self._hw_last_veh_id != veh_id and self._hw_last_detect_t > 0.0:
            gap = detect_t - self._hw_last_detect_t
            if 30.0 < gap < 1800.0:
                self._hw_observed.append(gap)
                if len(self._hw_observed) > 10:
                    self._hw_observed = self._hw_observed[-10:]
                self._hw_mean_s = sum(self._hw_observed) / len(self._hw_observed)
                if len(self._hw_observed) >= 2:
                    sigma = gap - self._hw_mean_s
        self._hw_last_veh_id   = veh_id
        self._hw_last_detect_t = detect_t
        self._hw_sigma_current = sigma
        return sigma

    # ------------------------------------------------------------------
    def _dctsp_record_poz_checkin(self, veh_id: int, time: float):
        """Record bus check-in time for POZ travel-time tracking (Eq. 6)."""
        self._poz_checkin_t[veh_id] = time

    def _dctsp_record_poz_checkout(self, veh_id: int, time: float):
        """
        Record bus check-out, update rolling mean T̄_POZ, and feed the trip into
        Simulation_Stats so that sim_bus_delay (traj_bus_delay path) is non-zero.

        Also computes the **actual measured delay saving** vs the NO_ACTION baseline
        (entry-to-exit transit time compared with the smoothed NO_ACTION average).
        For MARL runs, this triggers a **terminal Q-update** so the Q-table learns
        from real observed outcomes rather than only model-estimated rewards.

        Entry time is the checkin recorded at detection; exit time is now.
        Actual POZ transit time = exit − entry.
        NO_ACTION baseline = `_no_action_poz_ema_s` (exponentially smoothed
        average transit time observed for NO_ACTION decisions at this junction).
        Positive saving  = bus transited faster than the no-TSP average.
        """
        # Release one-action guard so a subsequent trip can act independently.
        self._dctsp_clear_acted(veh_id)

        cin = self._poz_checkin_t.pop(veh_id, None)
        if cin is not None and time > cin:
            t_poz = time - cin
            if 3.0 < t_poz < 300.0:
                self._poz_travel_times.append(t_poz)
                if len(self._poz_travel_times) > 10:
                    self._poz_travel_times = self._poz_travel_times[-10:]
                self._mean_poz_t = (sum(self._poz_travel_times)
                                    / len(self._poz_travel_times))
            # Push the trip into Simulation_Stats trajectory tracker.
            try:
                self.stats.record_pt_bus_exit(self.id, veh_id, time)
            except Exception:
                pass

            # ── Measured delay feedback ───────────────────────────────────
            # Consume the entry action record if present.
            _rec = _poz_action_log.pop(int(veh_id), None)
            if _rec is not None and 3.0 < t_poz < 300.0:
                (_rec_jct, _rec_atype, _rec_aparam,
                 _rec_entry_t, _rec_state, _rec_aidx) = _rec

                # Update NO_ACTION baseline (EMA α=0.15 for slow adaptation).
                if _rec_atype == 'NO_ACTION':
                    self._no_action_poz_ema_s = (
                        0.85 * self._no_action_poz_ema_s + 0.15 * t_poz)

                # Actual delay saving relative to NO_ACTION baseline.
                # Positive  → TSP helped the bus (or natural green was quick).
                # Negative  → TSP hurt (e.g. wrong-phase GE extended the wait).
                actual_saving_s = self._no_action_poz_ema_s - t_poz
                actual_reward   = actual_saving_s * float(self.BusOcc)

                log_to_file(
                    f"[POZ_MEASURED] inter={self.id} bus={veh_id} "
                    f"entry={_rec_entry_t:.1f}s exit={time:.1f}s "
                    f"t_poz={t_poz:.1f}s baseline={self._no_action_poz_ema_s:.1f}s "
                    f"actual_saving={actual_saving_s:.1f}s "
                    f"action={_rec_atype}_{_rec_aparam:.0f}s "
                    f"actual_r={actual_reward:.2f}pax·s",
                    force=True)

                # Prediction-vs-actual validation log.
                # Compares the predicted bus delay at detection time against
                # the observed t_poz (time spent in phase-of-interest zone).
                _pred = _dctsp_pred_store.pop(int(veh_id), None)
                if _pred is not None:
                    (_p_jct, _p_t, _p_eta,
                     _p_ens, _p_kin, _p_dd1, _p_mb) = _pred
                    log_to_file(
                        f"[PRED_ACTUAL] jct={self.id} bus={veh_id} "
                        f"det_t={_p_t:.1f}s eta={_p_eta:.1f}s "
                        f"pred_kin={_p_kin:.1f}s pred_dd1={_p_dd1:.1f}s "
                        f"pred_mb={_p_mb:.1f}s pred_ens={_p_ens:.1f}s "
                        f"actual_t_poz={t_poz:.1f}s "
                        f"err_ens={_p_ens - t_poz:.1f}s err_kin={_p_kin - t_poz:.1f}s",
                        force=True)

                # Terminal Q-update for MARL: use measured reward as target.
                # This is a terminal (no bootstrap) update: Q(s,a) += α·(r_meas − Q(s,a))
                # Only applied when RL Q-table is active (not SELFORG, not ZIG).
                if (GLOBAL_REWARD_MODE
                        and not REWARD_SELFORG_MODE
                        and not DCTSP_ZIG_MODE
                        and not MP_ECTM_MODE
                        and not BXT_MODE
                        and _rec_state is not None
                        and _rec_aidx is not None):
                    try:
                        q_cur = _rl_get_q(_rec_jct, _rec_state)
                        # Terminal update (no future junction available yet):
                        # treat the measured outcome as the full TD target.
                        q_cur[_rec_aidx] += RL_LEARNING_RATE * (
                            actual_reward - q_cur[_rec_aidx])
                        log_to_file(
                            f"[DCTSP_RL] TERMINAL jct={_rec_jct} bus={veh_id} "
                            f"a={_rec_aidx} r_meas={actual_reward:.4f} "
                            f"Q_new={q_cur[_rec_aidx]:.4f}",
                            force=False)
                    except Exception as _qt_e:
                        log_to_file(f"[DCTSP_RL] terminal Q-update error: {_qt_e}",
                                    force=False)

                # Terminal Q-update for BXT (Chanloha et al. 2014 Eq. 33):
                # Q(s,a) ← Q(s,a) + α · [r_bxt_measured − Q(s,a)]
                # Uses _dctsp_bxt_q_table; separate from MARL path.
                if (GLOBAL_REWARD_MODE
                        and BXT_MODE
                        and _rec_state is not None
                        and _rec_aidx is not None):
                    try:
                        _bxt_td = _bxt_update_q(
                            int(_rec_jct), _rec_state, int(_rec_aidx), actual_reward)
                        _bxt_q_new = _dctsp_bxt_q_table.get(int(_rec_jct), {}).get(
                            _rec_state, [0.0] * 7)[int(_rec_aidx)]
                        log_to_file(
                            f"[BXT] TERMINAL jct={_rec_jct} bus={veh_id} "
                            f"a={_rec_aidx} r_meas={actual_reward:.4f} "
                            f"td={_bxt_td:+.4f} Q_new={_bxt_q_new:.4f}",
                            force=False)
                    except Exception as _bxt_te:
                        log_to_file(f"[BXT] terminal Q-update error: {_bxt_te}",
                                    force=False)

    def _dctsp_cross_traffic_delay_s(self, action_s: float,
                                       queue_elapsed_s: float = 0.0,
                                       phases: list = None) -> float:
        """
        Total passenger-seconds of ADDITIONAL delay caused by action_s seconds
        of bus-phase priority (GE or INS).

        By default (phases=None) computes delay for ALL CROSS-APPROACH phases
        (UpFlowList[1..n]).  Pass phases=[0] to compute the MAIN-APPROACH
        equivalent — used to quantify how much delay main-approach cars SAVE
        when TSP grants them additional green time.

        Full D/D/1 shockwave integral — three terms (Webster 1958 / HCM 2010):
          (1) Queue     — Q_0 cars already at red, each delayed action_s more.
                          Q_0 = q * queue_elapsed_s.  Pass queue_elapsed_s > 0
                          for GE right-phase (BusPhaseDuration / 2 recommended).
                          Leave 0 for INS / GE wrong-phase (cross-traffic is green).
          (2) Triangle  — new arrivals during action_s window, avg wait = action_s/2.
          (3) Discharge — after the extension ends cross-traffic faces an
                          over-run queue Q_end = Q_0 + q*action_s that must clear
                          at net rate s_eff = s - q before steady state is restored.
                          Delay = Q_end² / (2 * s_eff).  This is the shockwave
                          discharge tail and dominates at high saturation (x > 0.7).
                          s_eff is floored at 10 % of saturation flow to bound the
                          result when x → 1 (near-saturated approaches).
        """
        try:
            cross_pax_s = 0.0
            car_occ     = max(float(self.CarOcc), 1.0)
            sat_flow_vps = float(
                getattr(self, 'SaturationFlow', QUEUE_MODEL_SAT_FLOW_VPH) or
                QUEUE_MODEL_SAT_FLOW_VPH
            ) / 3600.0
            n_phases = len(self.UpFlowList)
            _phase_iter = phases if phases is not None else range(1, n_phases)
            for p in _phase_iter:
                if p < 0 or p >= n_phases:
                    continue
                row = self.UpFlowList[p]
                avg_flow_vph = float(np.mean(row)) if len(row) > 0 else 0.0
                if avg_flow_vph <= 0:
                    continue
                flow_vps = avg_flow_vph / 3600.0

                # Existing queue at start of extension
                Q_0 = flow_vps * max(0.0, queue_elapsed_s)

                # (1) Existing-queue delay: each of Q_0 vehicles waits action_s more
                _phase_delay = Q_0 * action_s * car_occ

                # (2) Triangle: new arrivals during action_s → avg wait = action_s/2
                _phase_delay += flow_vps * action_s * (action_s / 2.0) * car_occ

                # (3) Discharge tail: D/D/1 shockwave integral
                #     Queue at end of extension = Q_0 + q*action_s.
                #     Net discharge rate s_eff = s - q; floor at 10 % of s so
                #     near-saturated approaches stay bounded.
                s_eff = max(sat_flow_vps - flow_vps,
                            sat_flow_vps * 0.10)
                Q_end = Q_0 + flow_vps * action_s
                _phase_delay += (Q_end ** 2) / (2.0 * s_eff) * car_occ

                # (4) Multi-cycle saturation correction (HCM 2010 Eq. 16-5).
                #     Near saturation (x > DCTSP_MULTI_CYCLE_X_THR), residual
                #     queues accumulate over many cycles so total delay ∝ 1/(1-x).
                #     This corrects for multi-cycle spillback that the single-cycle
                #     D/D/1 model cannot capture, preventing reward over-optimism at
                #     near-saturated cross-approaches where TSP is counter-productive.
                #
                #     IMPORTANT: mc_mult is applied ONLY to cross-approach phases
                #     (p > 0, i.e. phases=None default).  For the main approach
                #     (p == 0, called via phases=[0]) this function estimates CAR
                #     SAVINGS from TSP — applying mc_mult there would inflate
                #     estimated benefits by 1/(1-x) at congested junctions and
                #     cause over-insertion.  Main-approach benefit is bounded by
                #     the actual queue served; no multi-cycle amplification applies.
                _x_phase = flow_vps / max(sat_flow_vps, 1e-9)
                if p != 0 and _x_phase > float(DCTSP_MULTI_CYCLE_X_THR):
                    _mc_mult = 1.0 / max(
                        1.0 - _x_phase, float(DCTSP_MULTI_CYCLE_X_FLOOR))
                    _phase_delay *= _mc_mult

                cross_pax_s += _phase_delay

            # NETWORK_FACTOR corrects for downstream coordination disruption and
            # queue spillback beyond this intersection.
            return max(0.0, cross_pax_s * float(NETWORK_FACTOR))
        except Exception:
            return 0.0

    def _queue_model_bus_delay_s(self, bus_eta_s: float, remaining_red_s: float,
                                  action_type: str, action_param: float) -> float:
        """
        D/D/1 queue-based bus delay at a signalised intersection.

        Improves on the kinematic "catch-the-green-or-miss-it" model by using
        observed queue length and arrival-rate data to estimate the service time
        the bus must wait behind residual vehicles, even when it arrives during
        the green phase.

        Model (deterministic D/D/1, consistent with Webster 1958 and HCM 2010):
          • Q_cur  – current max queue at bus approach (from MaxQueueLength[0])
          • q_vps  – arrival rate at bus approach (from UpFlowList[0], veh/s)
          • s_vps  – saturation discharge rate (from SaturationFlow, veh/s)
          • s_eff  – net discharge during green = max(0, s_vps − q_vps)

        Three arrival-time cases:
          Case 1 – bus arrives before green (eta ≤ r_rem):
            delay = (r_rem − eta) + (Q_cur + q·eta) / s
          Case 2 – bus arrives during green (r_rem < eta ≤ r_rem + g):
            residual_queue = max(0, Q_green − s_eff·t_into_green)
            delay = residual_queue / s
          Case 3 – bus misses the green (eta > r_rem + g):
            Overflow queue at start of next cycle is estimated; the bus waits
            for that queue to be served at the next green.
        """
        try:
            cycle_s = float(self.config.get('CycleTime', 135))
            base_g  = float(getattr(self, 'BusPhaseDuration', 30) or 30)

            # ── Apply action to signal timing ─────────────────────────────────
            r_rem = max(0.0, float(remaining_red_s))
            g_s   = base_g
            if action_type.startswith('GE'):
                g_s = base_g + float(action_param)
            elif action_type == 'INS':
                # INS inserts bus phase immediately; model: remaining_red shrinks by
                # the intergreen overhead (action_param already encodes the net cut).
                r_rem = max(0.0, r_rem - float(action_param))
            elif (action_type.startswith('ER') or action_type.startswith('EARLY_RED')
                or action_type.startswith('GR') or action_type.startswith('GREEN_REALLOC')):
                # EARLY_RED cuts cross-traffic phase short → bus green starts sooner.
                r_rem = max(0.0, r_rem - float(action_param))

            # ── Traffic parameters ────────────────────────────────────────────
            # Saturation flow: use measured value if available, else global default.
            raw_sat = float(getattr(self, 'SaturationFlow', 0) or 0)
            s_vph   = raw_sat if raw_sat > 100 else float(QUEUE_MODEL_SAT_FLOW_VPH)
            s_vps   = s_vph / 3600.0

            # Arrival rate at bus approach (veh/s).
            q_vps = 0.0
            if (hasattr(self, 'UpFlowList') and len(self.UpFlowList) > 0
                    and len(self.UpFlowList[0]) > 0):
                q_vps = max(0.0, float(np.mean(self.UpFlowList[0])) / 3600.0)

            # Current observed queue at bus approach.
            # MaxQueueLength is in METRES (LWR shockwave formula); convert to vehicles
            # using jam density k_jam = 0.125 veh/m (≡ 8 m per vehicle spacing).
            _k_jam_dd1 = 0.125   # veh/m
            _Q_cur_m = 0.0
            if (hasattr(self, 'MaxQueueLength') and len(self.MaxQueueLength) > 0
                    and len(self.MaxQueueLength[0]) > 0):
                _Q_cur_m = max(0.0, float(np.mean(self.MaxQueueLength[0])))
            Q_cur = _Q_cur_m * _k_jam_dd1   # metres → vehicles

            # Net discharge rate during green (veh/s); clamp to avoid div-by-zero.
            s_eff = max(0.001, s_vps - q_vps)
            eta   = max(0.0, float(bus_eta_s))

            # ── Case 1: bus arrives before green ──────────────────────────────
            if eta <= r_rem:
                # Queue when bus arrives (D/D/1 deterministic: arrivals accumulate).
                Q_at_bus = Q_cur + q_vps * eta
                red_wait = r_rem - eta          # time bus waits at red
                # Service time: all Q_at_bus vehicles ahead drain at s_vps once green.
                queue_service_s = Q_at_bus / s_vps if s_vps > 0 else 0.0
                return max(0.0, red_wait + queue_service_s)

            # ── Case 2: bus arrives during green ──────────────────────────────
            elif eta <= r_rem + g_s:
                t_into = eta - r_rem            # seconds into the green phase
                Q_g    = Q_cur + q_vps * r_rem  # queue accumulated by green start
                # Residual queue when bus arrives: subtract net discharges since green.
                Q_remain = max(0.0, Q_g - s_eff * t_into)
                if Q_remain <= 0 or s_vps <= 0:
                    return 0.0
                return Q_remain / s_vps         # time for bus to clear remaining queue

            # ── Case 3: bus misses the green — waits for next cycle ────────────
            else:
                # Queue remaining at end of this green (overflow vehicles).
                Q_g          = Q_cur + q_vps * r_rem
                Q_overflow   = max(0.0, Q_g - s_eff * g_s)
                # Arrivals during inter-green period (cycle − g_s seconds).
                Q_at_next_g  = Q_overflow + q_vps * (cycle_s - g_s)
                next_green_s = r_rem + cycle_s  # approximate next bus green start

                if eta <= next_green_s:
                    # Bus arrives before next green.
                    red_wait_2     = next_green_s - eta
                    arrivals_extra = q_vps * max(0.0, eta - (r_rem + g_s))
                    Q_at_bus_2     = Q_at_next_g + arrivals_extra
                    queue_s_2      = Q_at_bus_2 / s_vps if s_vps > 0 else 0.0
                    # Clamp to one cycle to prevent accumulation across missed cycles.
                    _cycle_cap = float(self.config.get('CycleTime', 135))
                    return float(np.clip(red_wait_2 + queue_s_2, 0.0, _cycle_cap))
                else:
                    # Bus arrives during next green.
                    t_into_2  = eta - next_green_s
                    Q_remain2 = max(0.0, Q_at_next_g - s_eff * t_into_2)
                    return max(0.0, Q_remain2 / s_vps if s_vps > 0 else 0.0)

        except Exception as _dd1_exc:
            try:
                log_to_file(f"[DD1_DEBUG] exception in _queue_model_bus_delay_s: {_dd1_exc}",
                            force=False)
            except Exception:
                pass
            return 0.0

    def _mb_bus_delay_s(self, bus_eta_s: float, remaining_red_s: float,
                        action_type: str = 'NO_ACTION',
                        action_param: float = 0.0) -> float:
        """
        Moving-bottleneck bus delay estimate (LWR / kinematic-wave theory).

        Models the bus as a moving bottleneck approaching a queued column of
        vehicles at a signalised intersection.  The method follows the
        shockwave framework described in:

            Newell (1998) "A moving bottleneck"; Daganzo (2006) "In traffic flow,
            cellular automata = kinematic waves"; and the dynamic-programming
            extension in Zheng et al. (2019) Transportation Research Part C
            (S0968090X1831492X).

        Key model parameters (drawn from live intersection state):
          v_b  – bus free speed to stop line (m/s); approximated as
                 d_b / bus_eta_s where d_b = 500 m default detection range.
          q_b  – bus-approach arrival flow (veh/s) from UpFlowList[0].
          k_j  – jam density (veh/m); default 0.125 veh/m (= 8 m/veh spacing).
          v_f  – free-flow speed (m/s); default 50 km/h = 13.9 m/s.
          w    – backward shockwave speed (m/s) = q_b / (k_j - q_b/v_f).
          Q_0  – current queue length at stop line (veh) from MaxQueueLength[0].

        Steps:
          1. Bus distance to stop line: d_b = v_b × bus_eta_s.
          2. Queue tail at time 0:       x_tail = Q_0 / k_j (m from stop line).
          3. Time for bus to intercept growing queue tail:
                t* = (d_b - x_tail) / (v_b + w)   [if d_b > x_tail]
                t* = 0                              [bus already in queue]
          4. Queue vehicles ahead of bus at t*:
                N_ahead = k_j × (x_tail + w × t*)
          5. Service time behind queue:
                t_srv = N_ahead / s_vps            [s_vps from SaturationFlow]
          6. Signal state at bus arrival (t* + bus_eta_s from now):
                If signal is red at that moment, add the remaining red portion.
          7. Under GE/INS: effective remaining_red is reduced (same adjustment
             as the kinematic estimator).

        Returns estimated bus delay at the stop line in seconds (≥ 0).
        """
        try:
            # ── Flow / state from current intersection ─────────────────────────
            q_vph = 0.0
            if (hasattr(self, 'UpFlowList') and len(self.UpFlowList) > 0
                    and len(self.UpFlowList[0]) > 0):
                q_vph = float(np.mean(self.UpFlowList[0]))
            q_vps = q_vph / 3600.0           # arrival rate veh/s

            s_vps = 0.0
            if hasattr(self, 'SaturationFlow') and self.SaturationFlow:
                # SaturationFlow is a scalar int (veh/h); do NOT subscript it.
                s_vps = float(self.SaturationFlow) / 3600.0
            if s_vps <= 0:
                s_vps = 1800.0 / 3600.0      # default 1800 veh/h

            # MaxQueueLength is stored in METRES (from LWR shockwave formula:
            # abs(w2*w1*r/denom)).  For this model, x_tail_0 [m] is used
            # directly — no unit conversion needed.
            Q_0_m = 0.0
            if (hasattr(self, 'MaxQueueLength') and len(self.MaxQueueLength) > 0
                    and len(self.MaxQueueLength[0]) > 0):
                Q_0_m = max(0.0, float(np.mean(self.MaxQueueLength[0])))

            # ── Fundamental diagram parameters ──────────────────────────────────
            k_jam    = 0.125           # jam density veh/m (8 m per vehicle)
            v_f      = 50.0 / 3.6     # free-flow speed m/s (50 km/h)
            k_arr    = q_vps / max(v_f, 0.1)   # arrival density veh/m

            # Backward shockwave speed (LWR triangular FD):
            #   w = q_arr / (k_jam - k_arr)   [m/s, positive = propagates upstream]
            denom_w  = max(k_jam - k_arr, 1e-6)
            w        = q_vps / denom_w         # m/s

            # ── Bus kinematic parameters ─────────────────────────────────────────
            _det_range_m = 500.0              # default detection range from stop line
            v_b = _det_range_m / max(float(bus_eta_s), 1.0)  # m/s
            d_b = v_b * float(bus_eta_s)      # distance to stop line at t=0

            # ── Queue tail position (m from stop line, upstream positive) ────────
            # Q_0_m is already in metres; x_tail_0 = Q_veh / k_jam = (Q_m*k_jam)/k_jam = Q_m
            x_tail_0 = Q_0_m   # metres from stop line

            # ── Time for bus to intercept the queue tail ─────────────────────────
            if d_b <= x_tail_0:
                # Bus is already within the queue → intercept is immediate
                t_star = 0.0
            else:
                # Bus closes at (v_b + w) m/s on the retreating queue tail
                t_star = (d_b - x_tail_0) / max(v_b + w, 0.01)

            # ── Queue ahead of bus at intercept time ─────────────────────────────
            x_tail_at_t = x_tail_0 + w * t_star   # queue tail has grown upstream
            N_ahead = k_jam * x_tail_at_t          # vehicles ahead of bus at join

            # ── Signal state when bus reaches the back of the queue ──────────────
            # Adjust remaining red for the candidate action (same as kinematic model)
            if action_type == 'NO_ACTION':
                _adj_red = float(remaining_red_s)
            elif action_type == 'GE':
                # GE extends bus phase → if bus phase is current, remaining red = 0
                _adj_red = 0.0
            elif action_type in ('INS', 'INS_POST', 'INS_PRETERM'):
                _preterm = max(0.0, float(remaining_red_s) - float(INS_INTERGREEN_S))
                _adj_red = max(0.0, float(remaining_red_s) - _preterm - float(action_param))
            elif action_type in ('EARLY_RED', 'GREEN_REALLOC'):
                _cut = min(float(action_param),
                           max(0.0, float(remaining_red_s) - float(INS_INTERGREEN_S)))
                _adj_red = max(0.0, float(remaining_red_s) - _cut)
            else:
                _adj_red = float(remaining_red_s)

            # Time bus joins the back of the queue relative to now:
            t_join = t_star    # seconds from now

            # Residual red at bus join time
            red_at_join = max(0.0, _adj_red - t_join)

            # ── Service delay behind queue ──────────────────────────────────────
            # Time to clear N_ahead vehicles at saturation rate s_vps
            s_eff    = max(0.0, s_vps - q_vps)   # net discharge rate
            t_srv    = N_ahead / max(s_eff, 0.01) if N_ahead > 0 else 0.0

            # Total delay = red residual + queue service time
            bus_delay = red_at_join + t_srv

            # Clamp: delay cannot exceed one full cycle
            _cycle_s = float(self.config.get('CycleTime', 135))
            return float(np.clip(bus_delay, 0.0, _cycle_s))

        except Exception as _mb_exc:
            try:
                log_to_file(f"[MB_DEBUG] exception in _mb_bus_delay_s: {_mb_exc} "
                            f"(SatFlow={getattr(self,'SaturationFlow',None)!r} "
                            f"UpFlow={type(getattr(self,'UpFlowList',None)).__name__} "
                            f"Q={type(getattr(self,'MaxQueueLength',None)).__name__})",
                            force=False)
            except Exception:
                pass
            return 0.0

    def __mdndelayextension(self, phase_idx: int, green_s: float,
                            cycle_s: float) -> tuple:
        """
        Movement-Wise Delay Distribution Estimation (Zhu et al. 2026, JTEPBS.TEENG-9465).

        Implements an *analytical* 3-component Mixture Density Network (MDN) that
        mirrors the structure of the deep-learning MDN in the paper but derives
        mixture weights and component means directly from the current intersection
        state (flow, queue, signal timing) — no offline training required.

        The paper's key contributions adapted here:
          • K=3 Gaussian mixture components represent distinct traffic regimes:
              k=0  free-flow    : arrive during green, no queue stop    (μ ≈ 0)
              k=1  uniform stop : arrive during red, Webster uniform    (μ = r/2)
              k=2  overflow     : residual queue persists → extra cycle (μ = N_res/q_d)
          • Movement-Wise Coefficient (MWC): mixture weights are per-approach
              (phase_idx) — each movement has independent (π_0, π_1, π_2).
          • Delay Distribution Transform (DDT, Eq. 7): z = y^p, p=0.5
              Stabilises heavy-tailed delay distributions.  Expected delay in
              original space uses inverse transform: E[y] = (Σ_k π_k √μ_k)².

        Parameters
        ----------
        phase_idx : int  — approach (phase list index); 0 = bus/main, 1+ = cross-traffic
        green_s   : float — effective green allocated to this approach (s)
        cycle_s   : float — signal cycle length (s)

        Returns
        -------
        (expected_delay_s, delay_std_s, delay_p95_s, (pi, mu, sigma))
          expected_delay_s : E[d] from MDN (s)
          delay_std_s      : standard deviation of the mixture (s)
          delay_p95_s      : 95th-percentile approximation (μ + 1.645σ, clipped) (s)
          (pi, mu, sigma)  : tuple of K-element lists for inspection / logging
        """
        try:
            q_sat  = max(float(self.SaturationFlow), 1.0)          # veh/h
            k_sat  = max(float(self.SaturationDensity), 1.0)
            k_jam  = max(float(self.JamDensity), k_sat + 1.0)

            # ── Upstream flow for this approach ───────────────────────────────
            if phase_idx < len(self.UpFlowList) and len(self.UpFlowList[phase_idx]) > 0:
                q_arr_vph = float(np.mean(self.UpFlowList[phase_idx]))
            else:
                q_arr_vph = 0.0
            q_arr_vph = max(0.0, q_arr_vph)

            red_s = max(0.0, cycle_s - green_s)
            g_C   = green_s / max(cycle_s, 1.0)      # green fraction (g/C)

            # v/c ratio: demand per capacity (capacity = q_sat × g/C)
            capacity_vph = q_sat * g_C
            rho = q_arr_vph / max(capacity_vph, 1.0)   # v/c; can exceed 1 if over-sat

            # ── Residual queue from previous cycle (LWR shockwave) ────────────
            # MaxQueueLength is stored in METRES (LWR shockwave formula).
            # Convert to vehicles using k_jam (veh/km → veh/m = k_jam/1000).
            if (phase_idx < len(self.MaxQueueLength)
                    and len(self.MaxQueueLength[phase_idx]) > 0):
                N_max_m = float(np.mean(self.MaxQueueLength[phase_idx]))
                N_max   = N_max_m * (k_jam / 1000.0)   # m → veh
            else:
                # Estimate from shockwave if array missing
                q_arr_vps = q_arr_vph / 3600.0
                k_arr     = q_arr_vps * k_jam / max(q_sat / 3600.0, 1e-9)
                w_b       = q_arr_vps / max(k_jam - k_arr, 1.0)
                N_max     = max(0.0, w_b * red_s * k_jam)

            q_d_vps = max(0.0, q_sat / 3600.0 - q_arr_vph / 3600.0)  # net discharge
            N_res   = max(0.0, N_max - q_d_vps * green_s)  # residual after green ends

            # ── Component 2: overflow delay ───────────────────────────────────
            mu_overflow = N_res / max(q_d_vps, 1e-9) if N_res > 0.1 else 0.0
            # clip to one full red + cycle (can't wait more than ~2 cycles)
            mu_overflow = min(mu_overflow, red_s + cycle_s)

            # ── Mixture weights (MWC — movement-specific) ─────────────────────
            # π_0 (free-flow): fraction of vehicles arriving during green that find
            #   no queue ahead.  Approximated by min(g/C, 1) × (1 − min(ρ, 1)).
            pi_0 = min(g_C, 1.0) * max(0.0, 1.0 - min(rho, 1.0))
            # π_2 (overflow): only present when over-saturated (ρ > 1).
            pi_2 = max(0.0, min(rho - 1.0, 1.0) / max(rho, 1.0)) if rho > 1.0 else 0.0
            # π_1 (stop): everything else.
            pi_1 = max(0.0, 1.0 - pi_0 - pi_2)

            # Normalise so Σπ = 1
            pi_sum = pi_0 + pi_1 + pi_2
            if pi_sum < 1e-9:
                pi_0, pi_1, pi_2 = 0.0, 1.0, 0.0
                pi_sum = 1.0
            pi_0 /= pi_sum
            pi_1 /= pi_sum
            pi_2 /= pi_sum

            # ── Component means ───────────────────────────────────────────────
            mu_0 = 2.0              # small lost-time / start-up delay (s)
            mu_1 = max(0.0, red_s / 2.0)   # Webster uniform delay: E[wait] = r/2
            mu_2 = max(0.0, mu_overflow)

            # ── Component standard deviations ─────────────────────────────────
            sig_0 = 1.0
            sig_1 = max(1.0, red_s / 6.0)     # std of uniform U[0, r] = r/√12
            sig_2 = max(1.0, mu_2 / 2.0)

            pi  = [pi_0,  pi_1,  pi_2]
            mu  = [mu_0,  mu_1,  mu_2]
            sig = [sig_0, sig_1, sig_2]

            # ── DDT: power transform z = y^p, p = MDN_DDT_POWER (default 0.5) ─
            # Expected delay in transformed space: E[z] = Σ_k π_k × √μ_k
            # Inverse transform: E[y] = E[z]^(1/p) = E[z]² (for p=0.5)
            p = float(MDN_DDT_POWER)
            z_k    = [max(0.0, m) ** p for m in mu]
            E_z    = sum(pi[k] * z_k[k] for k in range(MDN_N_COMPONENTS))
            # Inverse DDT for expected delay in original space
            E_y    = E_z ** (1.0 / max(p, 1e-9))

            # ── Mixture variance (law of total variance) ───────────────────────
            # Var[y] ≈ Σ_k π_k × (σ_k² + μ_k²) − (Σ_k π_k × μ_k)²
            E_y_naive = sum(pi[k] * mu[k] for k in range(MDN_N_COMPONENTS))
            E_y2      = sum(pi[k] * (sig[k]**2 + mu[k]**2) for k in range(MDN_N_COMPONENTS))
            var_y     = max(0.0, E_y2 - E_y_naive**2)
            std_y     = var_y ** 0.5

            # 95th percentile approximation (normal approximation on mixture)
            p95_y = E_y + 1.645 * std_y

            return (max(0.0, E_y), max(0.0, std_y), max(0.0, p95_y), (pi, mu, sig))

        except Exception:
            # Graceful fallback: simple uniform-delay estimate
            red_fb = max(0.0, cycle_s - green_s)
            return (red_fb / 2.0, red_fb / 6.0, red_fb * 0.9, ([0, 1, 0], [0, red_fb/2, 0], [1, red_fb/6, 1]))

    def _mdn_total_intersection_delay(self, action_type: str,
                                      action_param: float,
                                      no_action_bus_delay: float,
                                      remaining_red_s: float = 0.0) -> float:
        """
        Compute total person-delay across ALL intersection approaches using
        the MDN delay estimator (__mdndelayextension) for the given candidate action.

        This provides the *current-status vs strategy* comparison that was missing
        from the incremental _dctsp_cross_traffic_delay_s() approach: rather than
        estimating only the *additional* car delay caused by an action, this function
        estimates the *total* expected delay across all movements under each action,
        enabling a true baseline-vs-strategy reward signal.

        Returns total person-delay in pax·s for this action.
        """
        try:
            cycle_s = float(self.config.get('CycleTime', 135))
            bp_dur  = float(getattr(self, 'BusPhaseDuration', 30) or 30)
            bus_occ = max(float(self.BusOcc), 1.0)
            car_occ = max(float(self.CarOcc), 1.0)
            n_phases = max(len(self.UpFlowList), 1)

            # ── Green allocation per approach under this action ────────────────
            # Bus approach (phase_idx=0): green = bp_dur ± action_s
            # Cross-traffic (phase_idx≥1): green = remaining cycle share
            if action_type == 'NO_ACTION':
                bus_green_s  = bp_dur
                side_extra_s = 0.0
            elif action_type == 'GE':
                bus_green_s  = bp_dur + float(action_param)
                side_extra_s = 0.0  # GE only extends bus phase; side gets same share
            elif action_type in ('INS', 'INS_POST', 'INS_PRETERM'):
                # Insertion inserts action_param seconds of bus green.
                # Cross-traffic loses TWO segments this cycle:
                #   1. The pre-termination cut of the currently-active phase:
                #      preterm_cut = max(0, remaining_red_s − INS_INTERGREEN_S)
                #   2. The inserted bus green itself: action_param seconds.
                # Without remaining_red_s the old code set side_extra_s=0 and
                # side_lost_s_ea=0 (INS dur < bp_dur → bus_extra_s=0), so the
                # MDN saw ZERO cross-traffic cost for INS — leading to enormous
                # positive rewards and 2.6× worse car delay vs NO_TSP.
                bus_green_s = float(action_param)
                _preterm_cut = max(0.0, float(remaining_red_s) - float(INS_INTERGREEN_S))
                _total_stolen = _preterm_cut + float(action_param)
                # Distribute the stolen time evenly across side approaches.
                # side_extra_s < 0 means each side approach loses |side_extra_s| s.
                side_extra_s = -_total_stolen / max(n_phases - 1, 1)
            elif action_type in ('EARLY_RED', 'GREEN_REALLOC'):
                # Bus gets its normal scheduled green; one cross-phase loses action_param s.
                # We approximate the cross-traffic impact by distributing the cut evenly
                # across all side phases (conservative: actual impact is concentrated on
                # the truncated phase, which gets it worse than the average suggests).
                bus_green_s  = bp_dur
                side_extra_s = -float(action_param) / max(n_phases - 1, 1)  # side loses proportionally
            else:
                bus_green_s  = bp_dur
                side_extra_s = 0.0

            # Cross-traffic loses time proportionally when bus phase is extended
            bus_extra_s     = max(0.0, bus_green_s - bp_dur)
            n_side          = max(n_phases - 1, 1)
            side_lost_s_ea  = bus_extra_s / n_side  # seconds each side approach loses

            total_pax_s = 0.0

            for ph in range(n_phases):
                if ph < len(self.UpFlowList) and len(self.UpFlowList[ph]) > 0:
                    q_vph = float(np.mean(self.UpFlowList[ph]))
                else:
                    q_vph = 0.0
                if ph == 0:
                    # Bus approach: always contribute this bus's delay × its occupancy
                    # directly — NOT scaled by q_vph/cycle.  Rationale:
                    #   • We are evaluating the delay of THIS specific bus (1 event).
                    #   • UpFlowList[0] is often empty early in the simulation or at
                    #     bus-only approaches, causing q_vph=0 and making the bus
                    #     saving invisible (NA_total == act_total) → zero reward.
                    #   • bus_delay × bus_occ (pax·s) is the correct per-event unit;
                    #     dividing by bus_occ in the caller restores units to
                    #     bus-equivalent seconds, matching the paper formula.
                    E_d = max(0.0, no_action_bus_delay)
                    total_pax_s += E_d * bus_occ
                    continue  # skip q_vph check and cross-traffic MDN branch

                if q_vph <= 0:
                    continue

                # Cross-traffic approaches (ph >= 1) — MDN × flow × cycle × car_occ
                # Effective green = nominal share minus any time ceded to bus
                # (side_lost_s_ea from GE extension) plus any direct cut
                # (side_extra_s < 0 for EARLY_RED which truncates a side phase).
                side_green_s = max(2.0,
                    (cycle_s - bp_dur) / n_side + side_extra_s - side_lost_s_ea)
                E_d, _, _, _ = self.__mdndelayextension(ph, side_green_s, cycle_s)
                total_pax_s += E_d * q_vph / 3600.0 * cycle_s * car_occ

            return max(0.0, total_pax_s)

        except Exception:
            return 0.0

    def _dctsp_eval_action(self, action_type: str, action_param: float,
                           sigma_in: float, no_action_bus_delay: float,
                           bus_eta_s: float, wrong_phase: bool = False,
                           remaining_red_s: float = 0.0) -> tuple:
        """
        Unified passenger-delay + throughput reward (bus·seconds, positive = better).

        Combines three objectives from the DC TSP / DQN-TSP literature:
          1. Cumulative Person Delay reduction (Yang & Fan 2023, Eq. 6-7):
             CPD_delta = bus_pax_saved_s - car_pax_cost_s
          2. POZ travel-time improvement (Hu et al. 2023, DC TSP):
             TT_delta = T̄_POZ - T_POZ_action
          3. Headway-adherence term (Hu et al. 2023, D2 TSP Eq. 6):
             HW_delta = |σ_in| - |σ_out|

        Throughput constraint: if the estimated cross-traffic loss from an action
        exceeds DCTSP_TPUT_TOL × total approach flow, a per-vehicle penalty is
        applied to the reward so the agent avoids blocking excess demand.

        action_type : 'NO_ACTION' | 'GE' | 'INS'
        action_param: GE seconds, or INS total duration (s); 0 for NO_ACTION.
        wrong_phase : True when GE is evaluated while the bus phase is NOT active
                      (extends the non-bus phase → bus delayed further).

        Returns (reward, sigma_out_s, t_poz_s)
        """
        bus_occ  = max(float(self.BusOcc), 1.0)
        mean_poz = (self._mean_poz_t if len(self._poz_travel_times) >= 2
                    else bus_eta_s + max(5.0, no_action_bus_delay))

        # ── Per-action kinematics ─────────────────────────────────────────────
        if action_type == 'NO_ACTION':
            bus_delay_after = max(0.0, no_action_bus_delay)
            t_poz           = bus_eta_s + bus_delay_after
            sigma_out       = sigma_in + bus_delay_after
            action_s        = 0.0
            cross_pax_s     = 0.0

        elif action_type == 'GE':
            action_s = float(action_param)
            if wrong_phase:
                # GE extends the current NON-bus phase → bus must wait longer.
                # Bus delay increases by the full extension amount.
                bus_delay_after = no_action_bus_delay + action_s
                sigma_out       = sigma_in + action_s      # headway deviation worsens
                cross_pax_s     = 0.0                      # cross traffic benefits (not penalised)
            elif no_action_bus_delay > 0.0:
                # Derive how many seconds the bus will miss the current green by.
                # With the corrected estimate: no_action_delay = _max_delay - _miss_by
                # so _miss_by = _max_delay - no_action_delay.
                _cycle_ge = float(self.config.get('CycleTime', 135))
                _max_d_ge = max(_cycle_ge - float(self.BusPhaseDuration), 0.0)
                _miss_by  = max(0.0, _max_d_ge - no_action_bus_delay)
                if action_s >= _miss_by:
                    # Extension covers the miss — bus catches the extended green.
                    bus_delay_after = 0.0
                    sigma_out       = (sigma_in - no_action_bus_delay
                                       if sigma_in > 0 else sigma_in)
                else:
                    # Extension too short — bus still misses; next bus phase is
                    # delayed by action_s so the total wait increases.
                    bus_delay_after = no_action_bus_delay + action_s
                    sigma_out       = sigma_in + action_s
                # Cross-traffic is at red; cars already queued (~BusPhaseDur/2 worth)
                # are each delayed action_s more — pass queue_elapsed_s for accuracy.
                _ge_q_elapsed = float(getattr(self, 'BusPhaseDuration', 30) or 30) / 2.0
                cross_pax_s = self._dctsp_cross_traffic_delay_s(
                    action_s, queue_elapsed_s=_ge_q_elapsed)
            else:
                bus_delay_after = 0.0
                sigma_out       = sigma_in
                _ge_q_elapsed = float(getattr(self, 'BusPhaseDuration', 30) or 30) / 2.0
                cross_pax_s     = self._dctsp_cross_traffic_delay_s(
                    action_s, queue_elapsed_s=_ge_q_elapsed)
            t_poz       = bus_eta_s + bus_delay_after

        elif action_type in ('INS', 'INS_POST'):
            action_s   = float(action_param)
            # INS_POST: overhead = remaining current-phase time + intergreen (exact).
            # Legacy 'INS': fixed 5 s overhead (insertion setup approximation).
            overhead_s = (float(remaining_red_s) + float(INS_INTERGREEN_S)
                          if action_type == 'INS_POST'
                          else 5.0)
            # Feasibility window: green runs from t=overhead_s to t=overhead_s+action_s.
            # Bus arrives at t=bus_eta_s (stop-line ETA from now).
            ins_green_end = overhead_s + action_s
            if bus_eta_s > ins_green_end:
                # Infeasible: green expires before bus arrives.
                bus_delay_after = no_action_bus_delay
                sigma_out       = sigma_in + no_action_bus_delay if sigma_in >= 0 else sigma_in
            else:
                # Feasible: bus catches the inserted green.
                # If bus arrives before green starts (eta < overhead) it waits at stop.
                # If bus arrives during green (eta >= overhead) it passes immediately.
                bus_delay_after = max(0.0, overhead_s - bus_eta_s)
                saved_s         = max(0.0, no_action_bus_delay - bus_delay_after)
                sigma_out       = (sigma_in - saved_s) if sigma_in > 0 else sigma_in
            t_poz = bus_eta_s + bus_delay_after
            if action_type == 'INS':
                # Standard INS: current phase cut immediately → amber/setup (overhead_s=5 s)
                # then bus green (action_s).  Full blockage = overhead_s + action_s.
                # Cross-traffic was GREEN (Q_0 ≈ 0); use full window so triangle and
                # discharge terms reflect the entire red period imposed on them.
                cross_pax_s = self._dctsp_cross_traffic_delay_s(overhead_s + action_s)
            else:  # INS_POST: waited for current phase to end; cross-traffic was RED.
                # remaining_red_s of queue had ALREADY built during normal cycle — that
                # is baseline cost, not additional.  EXTRA blocking = intergreen + bus phase.
                # Pre-existing queue at start of extra blockage = flow × remaining_red_s.
                cross_pax_s = self._dctsp_cross_traffic_delay_s(
                    float(INS_INTERGREEN_S) + action_s,
                    queue_elapsed_s=float(remaining_red_s))

        elif action_type == 'INS_PRETERM':
            action_s   = float(action_param)
            # INS_PRETERM: current phase is truncated immediately; bus phase starts
            # after INS_INTERGREEN_S = 3 s of amber/all-red clearance.  Much shorter
            # overhead than INS_POST because we do not wait for the current phase to end.
            overhead_s    = float(INS_INTERGREEN_S)
            ins_green_end = overhead_s + action_s
            if bus_eta_s > ins_green_end:
                bus_delay_after = no_action_bus_delay
                sigma_out       = sigma_in + no_action_bus_delay if sigma_in >= 0 else sigma_in
            else:
                bus_delay_after = max(0.0, overhead_s - bus_eta_s)
                saved_s         = max(0.0, no_action_bus_delay - bus_delay_after)
                sigma_out       = (sigma_in - saved_s) if sigma_in > 0 else sigma_in
            t_poz       = bus_eta_s + bus_delay_after
            # Pre-termination cost: total blockage = committed-green cut (_preterm_cut)
            # + intergreen transition + bus phase.  Modelled as one continuous red period
            # so queue buildup and discharge are computed over the full window.
            _preterm_cut = max(0.0, float(remaining_red_s) - float(INS_INTERGREEN_S))
            cross_pax_s  = self._dctsp_cross_traffic_delay_s(
                _preterm_cut + float(INS_INTERGREEN_S) + action_s)

        elif action_type == 'EARLY_RED':
            # EARLY_RED when wrong_phase=True (current = cross-traffic phase):
            #   Cut the current non-bus phase short by action_param seconds.
            #   The bus phase arrives action_param s sooner in the natural cycle.
            #   NO extra bus green is inserted — bus gets only its normal bp_dur.
            #
            # EARLY_RED when wrong_phase=False (current = bus phase):
            #   Cut the current BUS phase short by action_param seconds.
            #   Cross-traffic gets action_param extra seconds this cycle.
            #   Bus impact depends on whether the bus can still use the shortened green.
            if wrong_phase:
                # Cross-traffic phase cut → bus comes sooner (existing logic)
                action_s = min(float(action_param),
                               max(0.0, float(remaining_red_s) - float(INS_INTERGREEN_S)))
                if action_s <= 0.0:
                    bus_delay_after = max(0.0, no_action_bus_delay)
                    sigma_out       = sigma_in + bus_delay_after
                    t_poz           = bus_eta_s + bus_delay_after
                    cross_pax_s     = 0.0
                else:
                    # Bus phase starts action_s sooner → bus delay decreases by min(cut, delay).
                    bus_delay_after = max(0.0, no_action_bus_delay - action_s)
                    saved_s         = max(0.0, no_action_bus_delay - bus_delay_after)
                    sigma_out       = (sigma_in - saved_s) if sigma_in > 0 else sigma_in
                    t_poz           = bus_eta_s + bus_delay_after
                    # Cost: cross-traffic loses action_s committed green PLUS the
                    # intergreen transition before bus phase starts (cars decelerate
                    # during amber — full blockage = action_s + INS_INTERGREEN_S).
                    cross_pax_s     = self._dctsp_cross_traffic_delay_s(
                        action_s + float(INS_INTERGREEN_S))
            else:
                # Bus phase cut → cross-traffic gains, bus may lose
                remaining_bp_s = max(0.0, float(remaining_red_s))
                action_s = min(float(action_param),
                               max(0.0, remaining_bp_s - float(INS_INTERGREEN_S)))
                if action_s <= 0.0:
                    bus_delay_after = max(0.0, no_action_bus_delay)
                    sigma_out       = sigma_in + bus_delay_after
                    t_poz           = bus_eta_s + bus_delay_after
                    cross_pax_s     = 0.0
                elif no_action_bus_delay > 0.0:
                    # Bus was going to miss current green anyway → delay unchanged.
                    # Cross-traffic gains action_s seconds (modelled as negative cost).
                    bus_delay_after = no_action_bus_delay
                    sigma_out       = sigma_in + bus_delay_after
                    t_poz           = bus_eta_s + bus_delay_after
                    cross_pax_s     = -self._dctsp_cross_traffic_delay_s(action_s)
                elif float(bus_eta_s) < remaining_bp_s - action_s:
                    # Bus still catches the shortened green → no delay change.
                    bus_delay_after = 0.0
                    sigma_out       = sigma_in
                    t_poz           = bus_eta_s
                    cross_pax_s     = -self._dctsp_cross_traffic_delay_s(action_s)
                else:
                    # Bus was going to catch green but cut forces a miss.
                    # After ER_BP, the bus phase ends in (remaining_bp_s - action_s) s;
                    # cross-traffic then runs (cycle - bp_dur) s; next bus green starts at
                    #   (remaining_bp_s - action_s) + (cycle - bp_dur) from now.
                    # Bus delay = that offset minus bus_eta_s.
                    _cycle_s_er = float(self.config.get('CycleTime', 135))
                    _bp_dur_er  = float(getattr(self, 'BusPhaseDuration', 30) or 30)
                    bus_delay_after = max(0.0,
                        (_cycle_s_er - _bp_dur_er) + remaining_bp_s - action_s - float(bus_eta_s))
                    sigma_out   = sigma_in + bus_delay_after
                    t_poz       = bus_eta_s + bus_delay_after
                    cross_pax_s = -self._dctsp_cross_traffic_delay_s(action_s)

        elif action_type == 'GREEN_REALLOC':
            # GREEN_REALLOC: net-zero green reallocation in two modes:
            #
            # wrong_phase=True  (bus phase is NOT currently active):
            #   Cut the current non-bus phase so the bus phase starts earlier.
            #   Recover by shortening the planned bus phase by the same amount.
            #   Net cross-traffic green change = 0 (cut now, recover later).
            #
            # wrong_phase=False (bus phase IS currently active):
            #   Extend the current bus phase (same kinematics as GE).
            #   Recover by shortening the NEXT non-bus phase by the same amount.
            #   Cross-traffic cost ≈ 0 (recovery fraction = 1.0 offsets the cut).
            #   This makes GR a zero-cost GE: same bus benefit, no car penalty.
            if not wrong_phase:
                # Right-phase: extend current bus green, recover from next non-bus.
                action_s = float(action_param)
                if no_action_bus_delay > 0.0:
                    _cycle_gr = float(self.config.get('CycleTime', 135))
                    _max_d_gr = max(_cycle_gr - float(self.BusPhaseDuration), 0.0)
                    _miss_by_gr = max(0.0, _max_d_gr - no_action_bus_delay)
                    if action_s >= _miss_by_gr:
                        # Extension covers the miss — bus catches the extended green.
                        bus_delay_after = 0.0
                        sigma_out = (sigma_in - no_action_bus_delay
                                     if sigma_in > 0 else sigma_in)
                    else:
                        # Extension too short — bus still misses; adds to next wait.
                        bus_delay_after = no_action_bus_delay + action_s
                        sigma_out = sigma_in + action_s
                else:
                    bus_delay_after = 0.0
                    sigma_out = sigma_in
                t_poz = bus_eta_s + bus_delay_after
                # Recovery shortens the NEXT non-bus phase — cross-traffic pays for
                # this deferred cut just as they would for a GE extension.  The
                # 'net-zero' accounting over two cycles is still valid for total
                # cycle balance, but within this cycle the cross-traffic cost is real.
                cross_pax_s = self._dctsp_cross_traffic_delay_s(action_s)
            else:
                action_s = min(float(action_param),
                               max(0.0, float(remaining_red_s) - float(INS_INTERGREEN_S)))
                if action_s <= 0.0:
                    bus_delay_after = max(0.0, no_action_bus_delay)
                    sigma_out       = sigma_in + bus_delay_after
                    t_poz           = bus_eta_s + bus_delay_after
                    cross_pax_s     = 0.0
                else:
                    bus_delay_after = max(0.0, no_action_bus_delay - action_s)
                    saved_s         = max(0.0, no_action_bus_delay - bus_delay_after)
                    sigma_out       = (sigma_in - saved_s) if sigma_in > 0 else sigma_in
                    t_poz           = bus_eta_s + bus_delay_after
                    # Immediate cross-phase cut cost is partially/fully offset by
                    # downstream recovery when planned bus green is shortened.
                    # Cross-traffic loses action_s of committed green NOW.
                    # Recovery comes from shortening the FUTURE bus phase —
                    # that is a bus cost, not a car credit.  Charge full cut.
                    _c_now = self._dctsp_cross_traffic_delay_s(action_s)
                    cross_pax_s = _c_now

        else:
            return 0.0, sigma_in, bus_eta_s

        sigma_out = max(sigma_out, sigma_in - self._hw_mean_s)

        # ── Objective 1: cumulative person delay (CPD) reduction ──────────────
        # Bus passengers saved: delay eliminated × occupancy (pax·s).
        # Car passengers lost : cross-traffic delay × average car occupancy.
        # Divide by bus_occ so the unit stays comparable with the TT/HW terms
        # that are inherently in bus-seconds.
        bus_delay_no_act  = max(0.0, no_action_bus_delay)
        bus_pax_saved_s   = (bus_delay_no_act - bus_delay_after) * bus_occ
        car_pax_cost_s    = cross_pax_s                           # already in pax·s
        cpd_delta         = (bus_pax_saved_s - car_pax_cost_s) / max(bus_occ, 1.0)

        # ── Objective 2: POZ travel-time improvement ──────────────────────────
        tt_delta  = mean_poz - t_poz          # +ve when action shortens travel time

        # ── Objective 3: headway-adherence improvement ─────────────────────────
        hw_delta  = abs(sigma_in) - abs(sigma_out)  # +ve when headway deviation shrinks

        # ── Combined reward (paper Hu et al. 2025 Eq. 6, adapted for total delay) ──
        # R = wh × Δheadway + (1-wh) × ΔNetPaxDelay
        # Car delay is already accounted for in cpd_delta (via cross_pax_s).
        # No separate throughput penalty is applied — it double-counted car cost
        # and the formula was wrong (penalised 85 % of all lost vehicles always).
        # MDN totals are initialised here; set inside elif MDN_DELAY_MODE below
        # so they can be reused in the post-reward logging block (avoids a second
        # expensive call to _mdn_total_intersection_delay).
        _mdn_na_pax_s  = 0.0
        _mdn_act_pax_s = 0.0

        # Pre-compute cross-traffic baseline (cross-traffic delay during normal bus phase).
        # Used in MARL else-branch reward and in the total-delay logging block below.
        # Computing once here avoids a duplicate _dctsp_cross_traffic_delay_s call.
        _bus_phase_dur      = float(getattr(self, 'BusPhaseDuration', 30) or 30)
        _baseline_car_pax_s = self._dctsp_cross_traffic_delay_s(_bus_phase_dur)

        if REWARD_INV_DELAY_MODE:
            # Inverse-total-cost reward: r = 1 / (cost + ε)
            #
            # NO_ACTION:  r = 1 / (no_action_bus_delay + ε)
            #   The typical encountered delay is the natural baseline.
            #   TSP actions beat it only if they reduce the weighted total
            #   cost below the no-intervention delay — no artificial threshold.
            #
            # Uniform formula for ALL action types:
            #   r = 1 / (D̄_after + |σ_out| + ε)
            #   D̄_after = (bus_delay_after × occ
            #                + α_car × (cross_pax_s + future_oc_cost)   ← 0 for NO_ACTION
            #               ) / occ
            #   |σ_out|  = absolute headway deviation after the action.
            #   cross_pax_s = 0 for NO_ACTION (no action → no additional
            #                 cross-traffic blockage), actual cost for GE/INS.
            #   ε = INV_DELAY_EPSILON floor.
            if action_s > 0:
                _oc_s = min(action_s, float(DCTSP_OC_MAX_ADJ_S))
                _future_cross_pax_s = self._dctsp_cross_traffic_delay_s(_oc_s)
            else:
                _future_cross_pax_s = 0.0
            _delay_term = (bus_delay_after * bus_occ
                           + INV_DELAY_CAR_WEIGHT * (cross_pax_s
                                                     + _future_cross_pax_s)
                           ) / max(bus_occ, 1.0)
            _hw_term = abs(sigma_out)
            reward = max(0.0,
                         1.0 / (_delay_term + _hw_term + float(INV_DELAY_EPSILON)))

        elif REWARD_V2X_MODE:
            # V2X / BOCS-inspired reward:  r = 1 / (D_total + C_crowd + ε)
            #
            # Uniform formula for ALL action types (same as INV_DELAY):
            #   r = 1 / (D_total + C_crowd + ε)
            # NO_ACTION:  cross-traffic cost = 0 (no action taken), but
            #   bus_delay_after and |σ_out| are the actual no-intervention values.
            # GE / INS:   D_total accounts for the FULL bus-phase blocking duration
            #   plus OC recovery; C_crowd = quadratic crowding penalty.
            if action_s > 0:   # GE or INS
                _bp_v2x = float(self.config.get('BusPhaseDuration', 30.0))
                if action_type == 'GE':
                    _block_v2x = _bp_v2x + action_s
                    _oc_v2x    = min(action_s, float(DCTSP_OC_MAX_ADJ_S))
                else:  # INS
                    _block_v2x = action_s
                    _oc_v2x    = min(action_s, float(DCTSP_OC_MAX_ADJ_S))
                _total_car_v2x = (self._dctsp_cross_traffic_delay_s(_block_v2x)
                                  + self._dctsp_cross_traffic_delay_s(_oc_v2x))
                # V2X balance guard (ZIG-style cost-benefit check on total pax·s).
                # Root cause of +37% car delay: D_total divides car_pax_cost by bus_occ≈25
                # → car_term ≈ 3-14s while bus_delay ≈ 30-80s → TSP fires for all delays.
                # Fix: block when car pax cost > V2X_BALANCE_FACTOR × bus pax saved.
                #   ratio = DCTSP_CAR_WEIGHT × total_car_pax_s / (no_act_delay × bus_occ)
                #   V2X_BALANCE_FACTOR=0.50 (same as ZIG): block when car > 50% of bus saving
                # With NF=5, INS_10 at 400vph×3ph: car_pax=125, ratio=0.7×125/(30×25)=0.12 → fires
                # With NF=5, INS_10 at 2000vph×8ph: car_pax=1667, ratio=0.7×1667/(15×25)=3.1 → blocked
                _v2x_bus_pax_saved = max(no_action_bus_delay - bus_delay_after, 0.0) * bus_occ
                _v2x_car_pax_cost  = DCTSP_CAR_WEIGHT * _total_car_v2x
                _v2x_balance_ratio = _v2x_car_pax_cost / max(_v2x_bus_pax_saved, 1.0)
                _v2x_blocked       = _v2x_balance_ratio > float(V2X_BALANCE_FACTOR)
                _d_total_v2x = ((bus_delay_after * bus_occ
                                 + DCTSP_CAR_WEIGHT * _total_car_v2x)
                                / max(bus_occ, 1.0)
                                + abs(sigma_out))
                _crowd_ratio = max(0.0,
                                   (bus_occ - float(V2X_MAX_BUS_OCC)) / float(V2X_MAX_BUS_OCC))
                _crowd_v2x   = float(V2X_CROWDING_SCALE) * _crowd_ratio ** 2
                # Normalise to [0,1]: reward = ε/(cost+ε).
                # Without normalisation, reward = 1/ε when cost=0, so with ε=0.5
                # NO_ACTION on an on-time bus would score 2.0 — exceeding TSP actions.
                _eps_v2x = float(V2X_EPSILON)
                if _v2x_blocked:
                    # Car network cost exceeds bus pax savings → assign NO_ACTION reward
                    # so the greedy selector naturally picks NO_ACTION over this candidate.
                    _na_d_v2x = no_action_bus_delay + abs(sigma_out)
                    reward = _eps_v2x / (_na_d_v2x + _eps_v2x)
                else:
                    reward = _eps_v2x / (_d_total_v2x + _crowd_v2x + _eps_v2x)
            else:  # NO_ACTION — same structure: no cross-traffic action cost,
                   # but headway deviation and delay are included for symmetry.
                _d_total_v2x = (bus_delay_after
                                + abs(sigma_out))
                _crowd_ratio = max(0.0,
                                   (bus_occ - float(V2X_MAX_BUS_OCC)) / float(V2X_MAX_BUS_OCC))
                _crowd_v2x   = float(V2X_CROWDING_SCALE) * _crowd_ratio ** 2
                _eps_v2x = float(V2X_EPSILON)
                reward = _eps_v2x / (_d_total_v2x + _crowd_v2x + _eps_v2x)

        elif MDN_DELAY_MODE:
            # MDN total-intersection delay reward — delta formulation.
            #
            # R = w_hw × Δheadway + (1-w_hw) × mdn_cpd_delta
            #
            # mdn_cpd_delta = (mdn_NO_ACTION_total − mdn_action_total) / bus_occ
            #
            # This is the same structure as the paper formula (else branch) but
            # replaces the kinematic _dctsp_cross_traffic_delay_s() car-cost
            # estimate with the full MDN-modelled intersection delay across ALL
            # approaches — a proper current-status vs strategy comparison.
            #
            # Benefits of delta over the previous 1/(X+ε) form:
            #   • Consistent scale with MARL (bus-equivalent seconds) — no 2.0 cap
            #   • Heavy-traffic rewards are large (large savings) not small (large X)
            #   • NO_ACTION always gets mdn_delta=0 → reward = hw_delta only
            #     (0 when on-time, negative when late — correct)
            #   • GE/INS that help: mdn_NA > mdn_act → positive reward
            #   • GE in wrong-phase: mdn_act > mdn_NA → negative reward
            #
            # Fallback: when UpFlowList is empty (all flows = 0), both MDN totals
            # return 0, giving mdn_cpd_delta = 0. In this case the MDN adds no
            # signal over hw_delta alone. We fall back to the paper cpd_delta so
            # that INS/GE actions at zero-flow intersections still receive a
            # meaningful positive reward signal and the Q-table can learn.
            _mdn_act_pax_s = self._mdn_total_intersection_delay(
                action_type, action_param, bus_delay_after,
                remaining_red_s=remaining_red_s)
            _mdn_na_pax_s  = self._mdn_total_intersection_delay(
                'NO_ACTION', 0.0, bus_delay_no_act,
                remaining_red_s=0.0)
            if _mdn_na_pax_s > 0.0 or _mdn_act_pax_s > 0.0:
                # MDN has flow data — use the full delta reward.
                _mdn_cpd_delta = (_mdn_na_pax_s - _mdn_act_pax_s) / max(bus_occ, 1.0)
                reward = (DCTSP_W_HEADWAY * hw_delta
                        + DCTSP_W_PAX_DELAY * _mdn_cpd_delta)
            else:
                # No flow data: fall back to paper cpd_delta for proper signal strength.
                _mdn_cpd_delta = cpd_delta
                reward = (DCTSP_W_HEADWAY * hw_delta
                        + DCTSP_W_PAX_DELAY * cpd_delta)

        elif QUEUE_MODEL_MODE:
            # Queue-based delay reward — D/D/1 deterministic queue model.
            #
            # R = w_hw × Δheadway + (1-w_hw) × queue_cpd_delta
            #
            # queue_cpd_delta = (queue_NA_delay − queue_act_delay) × bus_occ / bus_occ
            #                   − cross_pax_s / bus_occ
            #
            # Uses the current observed queue (MaxQueueLength[0]) and arrival rate
            # (UpFlowList[0]) together with signal timing to estimate how long the
            # bus must wait behind residual vehicles, even when it arrives during
            # the green phase.  Cross-traffic cost is still the triangle-area estimate
            # from _dctsp_cross_traffic_delay_s (same as the paper formula).
            _qm_na_s  = self._queue_model_bus_delay_s(
                bus_eta_s, remaining_red_s, 'NO_ACTION', 0.0)
            _qm_act_s = self._queue_model_bus_delay_s(
                bus_eta_s, remaining_red_s, action_type, action_param)
            _qm_bus_saved_s = (_qm_na_s - _qm_act_s) * bus_occ   # pax·s
            _qm_cpd_delta   = (_qm_bus_saved_s - cross_pax_s) / max(bus_occ, 1.0)
            reward = (DCTSP_W_HEADWAY * hw_delta
                    + DCTSP_W_PAX_DELAY * _qm_cpd_delta)

        elif BARGAIN_SPM_MODE:
            # Bargaining-game inspired reward with stochastic shockwave risk.
            # ETA detection level controls bus bargaining power so near buses get
            # higher priority while very-far buses behave more cooperatively.
            if bus_eta_s < float(BG_DET_LVL_IMM_S):
                _bg_w_bus = float(BG_BUS_W_IMM)
            elif bus_eta_s < float(BG_DET_LVL_NEAR_S):
                _bg_w_bus = float(BG_BUS_W_NEAR)
            elif bus_eta_s < float(BG_DET_LVL_FAR_S):
                _bg_w_bus = float(BG_BUS_W_FAR)
            else:
                _bg_w_bus = float(BG_BUS_W_VFAR)

            # Tall-bus occupancy override: articulated/double-deck buses carry
            # more passengers so their effective delay weight is higher.
            _bg_eff_occ = float(_bg_bus_occ_eff) if _bg_bus_occ_eff > 0.0 else bus_occ

            # SPM-like stochastic risk: combine cross-flow variability (CV)
            # and saturation ratio into a conservative multiplier on car delay.
            # IMPORTANT: use only RECENT UpFlowList entries (last 5 timesteps).
            # Using all historical entries dilutes peak-congestion signals with
            # low-flow warmup data → sat_ratio near 0 → risk_mult ≈ 1.0 even
            # during AM peak → the cascade underestimation bug in bad seeds.
            _bg_risk_mult = 1.0
            try:
                _bg_up = np.asarray(getattr(self, 'UpFlowList', []), dtype=float)
                if _bg_up.ndim >= 2 and _bg_up.shape[0] > 1:
                    # Use last min(5, n_cols) timesteps of cross-phase flows
                    _bg_n_recent = min(5, _bg_up.shape[1]) if _bg_up.shape[1] > 0 else 0
                    _bg_cross = _bg_up[1:, -_bg_n_recent:].ravel() if _bg_n_recent > 0 else np.asarray([], dtype=float)
                else:
                    _bg_cross = np.asarray([], dtype=float)
                _bg_cross = _bg_cross[_bg_cross > 0.0]
                if _bg_cross.size > 0:
                    _bg_mean = float(np.mean(_bg_cross))
                    _bg_std  = float(np.std(_bg_cross))
                    _bg_cv   = _bg_std / max(_bg_mean, 1e-6)
                    _bg_sat_ratio = _bg_mean / max(float(getattr(self, 'SaturationFlow', 1800.0)), 1.0)
                    _bg_unc = min(1.0, 0.5 * _bg_cv + 0.5 * _bg_sat_ratio)
                    _bg_risk_mult = 1.0 + float(BG_SPM_RISK_WEIGHT) * _bg_unc
            except Exception:
                _bg_risk_mult = 1.0

            # Cascade multiplier: empirical correction for multi-cycle spillback
            # effects not captured by the local triangle-area car-cost formula.
            # NOTE: do NOT clamp to 0. For ER_BP actions, car_pax_cost_s is
            # NEGATIVE (cross-traffic gains green time → car benefit).  Clamping
            # to max(0,…) would erase that benefit entirely, making all ER_BP
            # variants produce the same reward as NO_ACTION.
            _bg_car_cost_s = float(car_pax_cost_s) * _bg_risk_mult * float(BG_CASCADE_MULT)

            # ── Main-corridor car savings (symmetric to cross-approach cost) ───
            # When TSP grants the bus phase additional green, ALL vehicles on the
            # main approach (not just the bus) avoid the delay they would have
            # incurred if those seconds were given to a cross-approach instead.
            # Computed with the same D/D/1 formula as _bg_car_cost_s but for
            # phase-0 (bus/main approach) flow.
            # For NO_ACTION (action_s ≤ 0) this returns 0, preserving neutrality.
            # For ER_BP (EARLY_RED, not wrong_phase), the bus phase is CUT — the main
            # approach does NOT gain green time from this action (it loses it).  Using
            # D/D/1(action_s) here produced a false positive "main-corridor saving" of
            # 50+ pax·s that could push ER_BP above NO_ACTION even for on-time buses.
            if action_type == 'EARLY_RED' and not wrong_phase:
                _bg_main_car_s = 0.0
            else:
                _bg_main_car_s = self._dctsp_cross_traffic_delay_s(
                    max(0.0, action_s), phases=[0])

            # ── POZ-anchored bus saving + headway signal ─────────────────────────
            # Replace kinematic bus_pax_saved_s AND hw_delta with estimates anchored
            # to the observed POZ (entry/exit detector) travel times.
            #
            # Root cause of broken rewards in prior runs:
            #   (1) Kinematic no_action_bus_delay overestimates by 36-85 s
            #       (pred_kin=95 s vs actual_t_poz=10 s in PRED_ACTUAL logs).
            #   (2) hw_delta used sigma_out from kinematic delay → for a 16 s-late
            #       bus with pred=62 s delay, hw_delta = -(62+16) − |−46| ≈ −62 s
            #       → DCTSP_W_HEADWAY × (−62) × 40 = −1488 pax·s swamps everything.
            #
            # Fix: derive both bus saving and headway correction from POZ observables.
            #   _no_action_poz_ema_s — EMA (α=0.15) of measured t_poz for NO_ACTION
            #                          buses; true do-nothing baseline (≈27-30 s).
            #   _poz_travel_times    — last 10 measured t_poz values (all actions);
            #                          min of ≥3 = free-flow transit proxy (≈5-8 s).
            #   _bg_poz_after        — expected t_poz after the specific action.
            #   _bg_poz_saving_s     — signed: +ve action shortens bus transit.
            #   _bg_sigma_out        — headway deviation after action (POZ-anchored).
            #   _bg_hw_delta         — headway improvement (positive = better schedule).
            _bg_poz_baseline = float(getattr(self, '_no_action_poz_ema_s', 30.0))
            _poz_tt          = list(getattr(self, '_poz_travel_times', []))
            # Free-flow proxy: mean of 3 fastest when ≥5 obs, else single minimum,
            # else 30 % of baseline (ensures a sensible fallback at run start).
            if len(_poz_tt) >= 5:
                _bg_poz_ff = float(np.mean(sorted(_poz_tt)[:3]))
            elif len(_poz_tt) >= 3:
                _bg_poz_ff = float(min(_poz_tt))
            else:
                _bg_poz_ff = max(_bg_poz_baseline * 0.30, 5.0)
            # Per-bus no-action POZ transit estimate: free-flow traversal time plus
            # any red-wait the bus would incur without TSP.
            # More accurate than the 30 s EMA for individual buses:
            #   kin_delay=0   → na_poz_est = ff          (bus already at green, saving=0 ✓)
            #   kin_delay=11.6→ na_poz_est = 9+11.6=20.6 (bus waits 11.6 s at red)
            #   kin_delay=52.7→ na_poz_est = 9+52.7=61.7 (large delay → large saving ✓)
            # This replaces the single 30 s EMA baseline which under-credited savings
            # for highly delayed buses and over-credited for low-delay buses.
            _bg_na_poz_est = _bg_poz_ff + max(0.0, float(no_action_bus_delay))

            # Effective sigma: bus's predicted schedule deviation AFTER this junction
            # when NO action is taken.  sigma_in is measured at the DETECTION point
            # (upstream of stop line); the bus will still incur no_action_bus_delay
            # at the red before it clears the junction.  Using raw sigma_in as the
            # headway baseline makes on-time buses (sigma_in=0, kin_delay>0) appear
            # to worsen headway when TSP makes them cross early — the correct reference
            # is the post-junction sigma the bus WOULD have without TSP.
            # Example: sigma_in=0, kin_delay=11.6 → eff_sigma=11.6; GR_5 brings
            # sigma_out to 0, hw_delta=|11.6|-|0|=+11.6 (improvement) instead of
            # the old |0|-|-21|=-21 (spurious penalty that blocked all TSP).
            _bg_sigma_in_eff = float(sigma_in) + max(0.0, float(no_action_bus_delay))

            # ── Expected t_poz after each action type ────────────────────────────
            # Note the asymmetry between GE and EARLY_RED for wrong_phase:
            #   GE  wrong_phase=True  → extends non-bus phase  → bus DELAYED more
            #   ER  wrong_phase=True  → cuts   non-bus phase   → bus benefits sooner
            #   GR  wrong_phase=True  → cuts   non-bus phase   → same as ER_WP
            if action_type == 'NO_ACTION':
                _bg_poz_after = _bg_na_poz_est            # no change vs effective baseline
            elif action_type == 'GE' and wrong_phase:
                # GE extends the current non-bus phase → bus must wait longer
                _bg_poz_after = _bg_na_poz_est + float(action_param)
            elif action_type in ('INS', 'INS_POST', 'INS_PRETERM'):
                # Overhead before inserted green (matches kinematic block overhead_s),
                # then free-flow transit through zone.
                # Infeasibility guard: if bus arrives AFTER inserted green expires,
                # no benefit — treat same as NO_ACTION (saves nothing).
                if action_type == 'INS':
                    _bg_ins_oh = 5.0
                elif action_type == 'INS_POST':
                    _bg_ins_oh = float(remaining_red_s) + float(INS_INTERGREEN_S)
                else:   # INS_PRETERM
                    _bg_ins_oh = float(INS_INTERGREEN_S)
                _bg_ins_end = _bg_ins_oh + float(action_param)
                if bus_eta_s > _bg_ins_end:
                    # Bus arrives after inserted green expires — infeasible, no saving
                    _bg_poz_after = _bg_na_poz_est
                else:
                    _bg_poz_after = _bg_ins_oh + _bg_poz_ff
            elif action_type == 'EARLY_RED' and not wrong_phase:
                # ER_BP: cuts bus phase early → cross-traffic gains green.
                # The bus is neutral: if kin_delay>0 the bus phase isn't even active;
                # if kin_delay=0 the bus already cleared.  Set after = na_poz_est so
                # saving = 0 and bus_pax_saved = 0 for ALL delay levels — ER_BP value
                # comes purely from the cross-traffic term (_bg_car_cost_s negative).
                # Using _bg_poz_baseline (fixed 30 s) gave false +31 s savings for
                # very late buses (na_poz_est=61.7 > baseline=30 → saving=31.7 > 0).
                _bg_poz_after = _bg_na_poz_est
            else:
                # GE correct phase, GR (both modes), ER_WP → bus catches green:
                #   → free-flow transit through zone
                _bg_poz_after = _bg_poz_ff

            # Signed POZ saving: positive = action shortens bus transit vs effective baseline
            _bg_poz_saving_s    = _bg_na_poz_est - _bg_poz_after
            # Per-passenger saving × effective occupancy = total bus pax·s saved
            _bg_poz_bus_saved_s = max(0.0, _bg_poz_saving_s) * _bg_eff_occ

            # ── POZ-anchored headway signal (using effective sigma) ───────────────
            # _bg_sigma_in_eff = sigma_in + kin_delay is the bus's EXPECTED schedule
            # deviation AFTER the junction if no TSP is applied.  The POZ saving then
            # moves the bus from eff_sigma towards 0 (for GE/GR) or only partially
            # (for INS with overhead).  Using raw sigma_in instead would treat on-time
            # buses (sigma_in=0, kin_delay>0) as if TSP makes them undesirably early
            # (sigma_in - saving < 0 → hw_delta < 0 → reward dominated by -penalty).
            _bg_sigma_out = _bg_sigma_in_eff - _bg_poz_saving_s
            try:
                # Clamp: can't over-correct beyond mean headway improvement
                _bg_sigma_out = max(_bg_sigma_out, _bg_sigma_in_eff - float(self._hw_mean_s))
            except Exception:
                pass
            _bg_hw_delta = abs(_bg_sigma_in_eff) - abs(_bg_sigma_out)

            # ── Bargaining payoff: total main-corridor gain vs side-street cost ─
            # total_main = weighted bus benefit + unweighted main-approach car gain
            # total_side = cross-approach car delay (risk-adjusted)
            # _bg_w_bus weights bus passengers higher for near-detection events
            # (see BG_BUS_W_* params); main-approach cars are counted at 1×.
            _bg_total_main = _bg_w_bus * _bg_poz_bus_saved_s + _bg_main_car_s
            # ── Total net pax·s — all components in pax·s ───────────────────────
            #   _bg_poz_bus_saved_s = POZ delay saving × occ  (entry/exit per pax)
            #   _bg_main_car_s      = D/D/1 integral × car_occ  (main-approach vehicles)
            #   _bg_car_cost_s      = D/D/1 integral × car_occ × risk × cascade
            _bg_net_pax_s = _bg_total_main - _bg_car_cost_s

            # Reward in total passenger·seconds (pax·s):
            #   HW term   = POZ-anchored Δheadway × bus_occ (schedule adherence)
            #   Delay term = net pax·s saved (bus entry/exit + main cars − cross cars)
            # Both terms in pax·s → physically consistent weighting.
            reward = (DCTSP_W_HEADWAY * _bg_hw_delta * _bg_eff_occ
                    + DCTSP_W_PAX_DELAY * _bg_net_pax_s)
            # Inertia bonus for NO_ACTION: TSP actions must provide positive net gain
            # above BG_MIN_GAIN_S pax·s threshold to be selected.
            if action_type == 'NO_ACTION':
                reward += float(BG_NO_ACTION_BONUS_S)
            # Override kinematic bus_pax_saved_s with POZ-anchored value for correct
            # REWARD_DEBUG logging.  The kinematic value is negative for GR/GE when
            # the bus misses the extended green (bus_delay_after > no_action_delay),
            # creating the confusing "negative bus_save → positive reward" appearance
            # in the dashboard.  POZ-anchored value is 0 or positive.
            bus_pax_saved_s = _bg_poz_bus_saved_s
            # Override kinematic sigma_out with POZ-anchored value so the returned
            # sigma_out (used in GATE logs, POZ_MEASURED lines, best-action logging)
            # reflects the actual expected headway deviation, not a 36-85 s overestimate.
            sigma_out = _bg_sigma_out

        else:
            # Total-delay-aware MARL reward (Hu et al. 2025 Eq. 6 + baseline cost).
            #
            # Standard:  R = w_hw × Δhw + (1-w_hw) × cpd_delta
            # Extended:  R = w_hw × Δhw + (1-w_hw) × (cpd_delta − baseline_norm)
            #
            # where  baseline_norm = cross_traffic_delay_during_normal_bus_phase / bus_occ
            #
            # Adding the baseline makes NO_ACTION negative when the intersection is
            # congested — even when the bus arrives at a green phase with zero delay,
            # the cross-traffic is still paying the cost of the bus-phase cycle.
            # reward_delta between any two actions is UNCHANGED (baseline is constant
            # at the moment of detection), so action RANKING and action SELECTION are
            # identical. Only the absolute reward level is shifted, making "reward=0"
            # no longer the implicit neutral for NO_ACTION in a busy intersection.
            #
            # NO_ACTION: cpd_delta = 0 → R = w_hw × Δhw − (1-w_hw) × baseline_norm
            #   → negative proportional to intersection baseline car delay (correct)
            # GE/INS that saves bus: cpd_delta > 0; if saved ≥ baseline → R > 0
            # GE/INS wrong-phase / over-extension: cpd_delta < 0 → R more negative
            _baseline_norm = _baseline_car_pax_s / max(bus_occ, 1.0)
            reward = (DCTSP_W_HEADWAY * hw_delta
                    + DCTSP_W_PAX_DELAY * (cpd_delta - _baseline_norm))
        # ── Total intersection delay (bus + other vehicles) ───────────────────
        # self.OtherDelay is only populated by GE_Objective_Function (old GE-based
        # strategies); for the DCTSP path it is always 0.  Use the UpFlowList-based
        # estimate (_dctsp_cross_traffic_delay_s) for the per-cycle baseline car cost
        # so no_strategy_delay_pax_s and strategy_delay_pax_s reflect real traffic.
        # When MDN_DELAY_MODE is active, use the full-intersection MDN estimates
        # so the logged values confirm the strategy is being evaluated correctly.
        # When QUEUE_MODEL_MODE is active, use the queue-model bus delay estimates.
        # _bus_phase_dur and _baseline_car_pax_s are pre-computed above the reward
        # branches — reuse them here to avoid a duplicate _dctsp_cross_traffic_delay_s call.
        if MDN_DELAY_MODE:
            # Reuse the MDN totals computed inside elif MDN_DELAY_MODE above
            # (avoids a second call to _mdn_total_intersection_delay).
            no_strategy_delay_pax_s = _mdn_na_pax_s
            strategy_delay_pax_s    = _mdn_act_pax_s
        elif QUEUE_MODEL_MODE:
            no_strategy_delay_pax_s = _qm_na_s * bus_occ + _baseline_car_pax_s
            strategy_delay_pax_s    = _qm_act_s * bus_occ + _baseline_car_pax_s + car_pax_cost_s
        else:
            if BARGAIN_SPM_MODE:
                # Use POZ-anchored estimates for total delay logging so that the
                # REWARD_DEBUG NA_total/act_total fields are consistent with the
                # reward signal (both POZ-based rather than kinematic).
                # _bg_poz_baseline/_bg_poz_after/_bg_eff_occ are always defined
                # here because BARGAIN_SPM_MODE=True → the block above ran.
                no_strategy_delay_pax_s = _bg_na_poz_est * _bg_eff_occ + _baseline_car_pax_s
                strategy_delay_pax_s    = _bg_poz_after   * _bg_eff_occ + _baseline_car_pax_s + car_pax_cost_s
            else:
                no_strategy_delay_pax_s = bus_delay_no_act * bus_occ + _baseline_car_pax_s
                strategy_delay_pax_s    = bus_delay_after  * bus_occ + _baseline_car_pax_s + car_pax_cost_s
        return (reward, sigma_out, t_poz,
                bus_pax_saved_s, car_pax_cost_s,
                no_strategy_delay_pax_s, strategy_delay_pax_s)

    # ─────────────────────────────────────────────────────────────────────────
    # Harmony-Search action-duration optimizer (_HSExt variant)
    # ─────────────────────────────────────────────────────────────────────────

    def _dctsp_hs_ext_find_action(self, sigma_in: float, kin_delay: float,
                                   bus_eta_s: float,
                                   wrong_phase_ge: bool = False,
                                   remaining_red_s: float = 0.0) -> list:
        """Harmony-Search (_HSExt) continuous action-duration optimizer.

        Considers three action types — GREEN_REALLOC (GR), GE, and INS (PI /
        phase insertion) — and finds the continuous optimal duration in
        [HS_EXT_T_MIN, HS_EXT_T_MAX] = [5, 20] s for each using the Geem et al.
        (2001) Harmony Search metaheuristic with the D/D/1 shockwave reward.

        Rules enforced:
            t* < HS_EXT_T_MIN (5 s)  — search space enforces lower bound;
                                        t < 5 s is never returned
            t* > HS_EXT_T_MAX (20 s) — hard-capped at 20 s before evaluation

        HS parameters read from globals:
            HS_EXT_HMS    — Harmony Memory Size
            HS_EXT_HMCR   — Harmony Memory Consideration Rate
            HS_EXT_PAR    — Pitch Adjustment Rate
            HS_EXT_BW     — Pitch bandwidth (seconds)
            HS_EXT_NITER  — Iterations per action type

        Returns:
            list of _dctsp_rows entries (one per action type):
            (label, t_opt, reward, sigma_out, t_poz,
             bus_saved_s, car_cost_s, no_strategy_pax_s, strategy_pax_s)
        """
        import random as _hs_rng

        _t_min = float(HS_EXT_T_MIN)
        _t_max = float(HS_EXT_T_MAX)

        # ── Recompute BARGAIN_SPM invariants (mirrors _dctsp_eval_action) ────
        _bl  = float(getattr(self, '_no_action_poz_ema_s', 30.0))
        _tt  = list(getattr(self, '_poz_travel_times', []))
        if len(_tt) >= 5:
            _ff = float(np.mean(sorted(_tt)[:3]))
        elif len(_tt) >= 3:
            _ff = float(min(_tt))
        else:
            _ff = max(_bl * 0.30, 5.0)
        _na_poz  = _ff + max(0.0, float(kin_delay))
        _eff_sig = float(sigma_in) + max(0.0, float(kin_delay))
        _eff_occ = (float(_bg_bus_occ_eff) if float(_bg_bus_occ_eff) > 0.0
                    else max(float(getattr(self, 'BusOcc', 40.0)), 1.0))
        _eta = float(bus_eta_s)
        _w_bus = (float(BG_BUS_W_IMM)  if _eta < float(BG_DET_LVL_IMM_S)  else
                  float(BG_BUS_W_NEAR) if _eta < float(BG_DET_LVL_NEAR_S) else
                  float(BG_BUS_W_FAR)  if _eta < float(BG_DET_LVL_FAR_S)  else
                  float(BG_BUS_W_VFAR))
        try:
            _up = np.asarray(getattr(self, 'UpFlowList', []), dtype=float)
            if _up.ndim >= 2 and _up.shape[0] > 1 and _up.shape[1] > 0:
                _cr = _up[1:, :].ravel()
                _cr = _cr[_cr > 0.0]
                _sat_r = (float(np.mean(_cr)) /
                          max(float(getattr(self, 'SaturationFlow', 1800.0)), 1.0)
                          if _cr.size > 0 else 0.5)
                _cv_r  = (float(np.std(_cr)) / max(float(np.mean(_cr)), 1.0)
                          if _cr.size > 1 else 0.0)
            else:
                _sat_r, _cv_r = 0.5, 0.0
        except Exception:
            _sat_r, _cv_r = 0.5, 0.0
        _risk    = 1.0 + float(BG_SPM_RISK_WEIGHT) * min(0.5 * _cv_r + 0.5 * _sat_r, 1.0)
        _cascade = float(BG_CASCADE_MULT)
        _hw_mean = float(getattr(self, '_hw_mean_s', 120.0))
        _ins_oh  = 5.0   # phase-insertion overhead (seconds)

        # ── Inline BARGAIN_SPM reward (fast path for HS iterations) ──────────
        def _obj(act: str, t: float, wp: bool) -> float:
            _t = max(_t_min, min(_t_max, float(t)))
            if act in ('GR', 'GE') and not wp:
                _af = _ff                      # bus catches green → free-flow transit
            elif act == 'INS':
                _af = (_ins_oh + _ff) if (_eta < _ins_oh + _t) else _na_poz
            else:                              # GE wrong-phase: extends non-bus phase
                _af = _na_poz + _t
            _sav  = _na_poz - _af
            _bps  = max(0.0, _sav) * _eff_occ
            _so   = max(_eff_sig - _sav, _eff_sig - _hw_mean)
            _hw_d = abs(_eff_sig) - abs(_so)
            try:
                _cc = self._dctsp_cross_traffic_delay_s(_t) * _risk * _cascade
            except Exception:
                _cc = 0.0
            _mc = 0.0
            if act in ('GR', 'GE') and not wp:
                try:
                    _mc = self._dctsp_cross_traffic_delay_s(_t, phases=[0])
                except Exception:
                    pass
            return (float(DCTSP_W_HEADWAY) * _hw_d * _eff_occ
                    + float(DCTSP_W_PAX_DELAY) * (_w_bus * _bps + _mc - _cc))

        # ── Harmony Search for a single (action_type, wrong_phase) pair ──────
        def _hs(act: str, wp: bool) -> float:
            _hms   = max(2, int(HS_EXT_HMS))
            _hmcr  = float(HS_EXT_HMCR)
            _par   = float(HS_EXT_PAR)
            _bw    = float(HS_EXT_BW)
            _niter = max(1, int(HS_EXT_NITER))
            # Initialise Harmony Memory with evenly-spaced values in [t_min, t_max]
            HM   = [_t_min + (_t_max - _t_min) * i / max(_hms - 1, 1)
                    for i in range(_hms)]
            HM_r = [_obj(act, t, wp) for t in HM]
            for _ in range(_niter):
                nt = (_hs_rng.choice(HM) if _hs_rng.random() < _hmcr
                      else _hs_rng.uniform(_t_min, _t_max))
                if _hs_rng.random() < _par:
                    nt = max(_t_min, min(_t_max, nt + _hs_rng.uniform(-_bw, _bw)))
                nr = _obj(act, nt, wp)
                wi = HM_r.index(min(HM_r))
                if nr > HM_r[wi]:
                    HM[wi] = nt
                    HM_r[wi] = nr
            bi = HM_r.index(max(HM_r))
            return HM[bi]

        # ── Evaluate each action type, return rows for _dctsp_rows ───────────
        rows = []
        for _short, _full, _wp, _lbl in (
                ('GR',  'GREEN_REALLOC', wrong_phase_ge, 'GR_HSExt'),
                ('GE',  'GE',            wrong_phase_ge, 'GE_HSExt'),
                ('INS', 'INS',           False,          'INS_HSExt')):
            try:
                t_opt = max(_t_min, min(_t_max, _hs(_short, _wp)))
                _r, _so, _tp, _bps, _cpc, _nsd, _std = self._dctsp_eval_action(
                    _full, t_opt, sigma_in, kin_delay, bus_eta_s,
                    wrong_phase=_wp, remaining_red_s=remaining_red_s)
                rows.append((_lbl, t_opt, _r, _so, _tp, _bps, _cpc, _nsd, _std))
                log_to_file(
                    f"[HS_EXT] {_short}: t_opt={t_opt:.1f}s r={_r:.2f} "
                    f"σ_out={_so:.0f}s bus_save={_bps:.1f} car_cost={_cpc:.1f}",
                    force=False)
            except Exception as _he:
                log_to_file(f"[HS_EXT] {_short} error: {_he}", force=True)
        return rows

    # ─────────────────────────────────────────────────────────────────────────
    # One-action-per-bus-per-junction guard helpers
    # ─────────────────────────────────────────────────────────────────────────

    def _dctsp_check_acted(self, veh_id: int, sim_t: float) -> bool:
        """Return True if this bus already committed to an action at this junction."""
        key = (int(veh_id), self.id)
        entry = _bus_acted_at_jct.get(key)
        if entry is None:
            return False
        _, _, acted_t = entry
        if sim_t - acted_t > DCTSP_ACTED_TTL_S:
            _bus_acted_at_jct.pop(key, None)
            return False
        return True

    def _dctsp_set_acted(self, veh_id: int, action_type: str,
                         param: float, sim_t: float):
        """Record that this bus has used its single action at this junction."""
        _bus_acted_at_jct[(int(veh_id), self.id)] = (action_type, param, sim_t)

    def _dctsp_clear_acted(self, veh_id: int):
        """Release the guard when the bus checks out of the POZ."""
        _bus_acted_at_jct.pop((int(veh_id), self.id), None)

    # ─────────────────────────────────────────────────────────────────────────
    # DCTSP-ZIG helpers
    # ─────────────────────────────────────────────────────────────────────────

    def _shockwave_optimal_green_s(self, min_s: float = 5.0,
                                   max_s: float = 20.0) -> float:
        """
        Optimal green duration from the LWR triangular fundamental diagram
        (Newell 1993 / Daganzo 1994).

        Queue-discharge model
        ---------------------
        Shockwave back-speed:  w_b  = q_arr / (k_jam − k_arr)   [km/s]
        Queue at green onset:  N_q  = w_b × T_red × k_jam       [veh]
        Net discharge rate:    q_d  = q_sat − q_arr              [veh/s]
        Queue clearance time:  t_cl = N_q / q_d                  [s]

        t_cl is the time from green onset for every queued vehicle on the
        bus approach to have discharged through the stop line.  It is used
        as the optimal GE extension or INS phase duration so that the bus
        (and the queue ahead of it) can clear without residual delay.

        Parameters
        ----------
        min_s : minimum returnable duration (s)  [default: 5 s]
        max_s : maximum returnable duration (s)  [default: 20 s]

        Returns the computed t_cl clipped to [min_s, max_s].
        Falls back to 10 s if the shockwave arrays are unavailable.
        """
        try:
            q_sat_vps = float(getattr(self, 'SaturationFlow', 1800)) / 3600.0
            k_jam     = float(getattr(self, 'JamDensity', 200.0))

            upf = np.asarray(self.UpFlowList, dtype=float)
            rdt = np.asarray(self.RedDurationList, dtype=float)

            if upf.ndim < 2 or upf.shape[0] == 0 or rdt.shape[0] == 0:
                return float(np.clip(10.0, min_s, max_s))

            # Bus approach = phase index 0 (BusPhase row in the shockwave arrays)
            upf_bus = upf[0].ravel()
            rdt_bus = rdt[0].ravel()

            pos_flow = upf_bus[upf_bus > 0.0]
            pos_red  = rdt_bus[(rdt_bus > 0.0) & (rdt_bus < 2.0 * float(
                self.config.get('CycleTime', 135)))]  # cap stale red values

            q_arr_vph = float(np.mean(pos_flow)) if pos_flow.size > 0 else 0.0
            t_red_s   = float(np.max(pos_red))   if pos_red.size  > 0 else 30.0
            q_arr_vps = q_arr_vph / 3600.0

            # Back-propagation shockwave speed (km/s)
            k_arr  = q_arr_vps * k_jam / max(q_sat_vps, 1e-9)
            w_back = q_arr_vps / max(k_jam - k_arr, 1.0)   # km/s

            # Estimated queue length (vehicles) at bus-phase green onset
            N_q = max(0.0, w_back * t_red_s * k_jam)

            # Net discharge: positive only when saturation flow beats arrival
            q_discharge = max(0.0, q_sat_vps - q_arr_vps)
            t_clear     = (N_q / q_discharge) if q_discharge > 0.01 else float(max_s)

            return float(np.clip(t_clear, min_s, max_s))
        except Exception:
            return float(np.clip(10.0, min_s, max_s))

    def dctsp_zig(
        self,
        time: float,
        timeSta: float,
        acycle: float,
        bus_eta_s: float,
        veh_id: int,
        current_phase: int,
        no_act_delay: float,
        sigma_in: float,
        remaining_red_s: float = 0.0,
    ) -> tuple:
        """
        DCTSP-ZIG (Zero-Interference-Grant) action selection.

        Replaces the discrete {5, 10, 15, 20} s candidate search with a
        single shockwave-optimal duration t_sw computed by
        _shockwave_optimal_green_s(), then evaluates exactly four actions:

            NO_ACTION    — hold current signal plan.
            GE           — green extension of the bus phase.
                           Optimal duration: t_ge = miss_by + t_sw
                           (covers the bus's missed-green gap PLUS clears
                           the queued vehicles ahead of it).
            INS_POST     — phase insertion *after* the current phase ends
                           naturally.  Overhead = remaining_red_s +
                           INS_INTERGREEN_S; bus does not force a phase change.
                           Relies on the natural signal sequence running to the
                           bus phase.
            INS_PRETERM  — phase insertion with immediate pre-termination of
                           the current phase.  Overhead = INS_INTERGREEN_S
                           (3 s) only.  Includes extra cross-traffic cost for
                           cutting the current phase short.

        Phase-overlap correction (IEEE ICARCE 2023):
            effective_delay = max(0, no_act_delay − ZIG_PHASE_OVERLAP_S)

        Saturation avoidance:
            side_ratio = side_pax_pressure / bus_pax_pressure
            if side_ratio > ZIG_BALANCE_FACTOR  →  force NO_ACTION

        Parameters
        ----------
        time            : current simulation time (s).
        timeSta         : Aimsun time stamp.
        acycle          : current cycle offset.
        bus_eta_s       : estimated bus ETA to stop line (s).
        veh_id          : Aimsun vehicle ID of the approaching bus.
        current_phase   : current Aimsun phase index.
        no_act_delay    : estimated bus delay under NO_ACTION (s).
        sigma_in        : current headway deviation (s), +ve = late.
        remaining_red_s : remaining seconds left in the current (non-bus)
                          phase; used to compute INS_POST and INS_PRETERM
                          overhead and pre-termination cross-traffic cost.

        Returns
        -------
        (best_type, best_param, best_r, best_r_delta,
         best_sigma_out, best_t_poz, rows)

        rows is a list of 9-tuples (label, param, reward, sigma_out, t_poz,
        bus_pax_saved_s, car_pax_cost_s, no_strategy_delay, strategy_delay)
        matching the _dctsp_rows format used in the reward-cycle CSV.
        """
        # ── Phase-overlap effective delay ─────────────────────────────────
        eff_delay = max(0.0, float(no_act_delay) - float(ZIG_PHASE_OVERLAP_S))

        # ── Shockwave-optimal duration ────────────────────────────────────
        t_sw = self._shockwave_optimal_green_s(
            min_s=float(DCTSP_MIN_INS_DURATION_S),
            max_s=float(DCTSP_MAX_INS_DURATION_S),
        )
        # GE optimal: miss_by covers the gap the bus misses, t_sw clears queue
        _wrong_phase = (current_phase != self.BusPhase)
        _cycle_s     = float(self.config.get('CycleTime', 135))
        _max_d       = max(_cycle_s - float(self.BusPhaseDuration), 0.0)
        _miss_by     = max(0.0, _max_d - float(no_act_delay))
        t_ge = float(np.clip(_miss_by + t_sw,
                              float(DCTSP_MIN_INS_DURATION_S),
                              float(MAX_GE_EXTENSION_S)))

        log_to_file(
            f"[ZIG] inter={self.id} t={time:.1f} bus={veh_id} "
            f"sw_t_cl={t_sw:.1f}s miss_by={_miss_by:.1f}s "
            f"t_ge={t_ge:.1f}s t_ins={t_sw:.1f}s "
            f"remaining_red={remaining_red_s:.1f}s overlap={ZIG_PHASE_OVERLAP_S:.1f}s "
            f"eff_delay={eff_delay:.1f}s",
            force=False)

        # ── Evaluate all 4 actions ────────────────────────────────────────
        rows: list = []
        r_na, so_na, tp_na, bps_na, cpc_na, nsd_na, std_na = self._dctsp_eval_action(
            'NO_ACTION', 0.0, sigma_in, no_act_delay, bus_eta_s)
        rows.append(('NO_ACTION', 0.0, r_na, so_na, tp_na, bps_na, cpc_na, nsd_na, std_na))

        # GE wrong-phase = extending a NON-bus phase → bus is delayed further.
        # Even when the bus is early (hw_delta turns positive) this is anti-TSP:
        # it harms bus passengers and cross-traffic, and corrupts the reward signal.
        # Only evaluate GE when the bus phase is already current (wrong_phase=False).
        if not _wrong_phase:
            r_ge, so_ge, tp_ge, bps_ge, cpc_ge, nsd_ge, std_ge = self._dctsp_eval_action(
                'GE', t_ge, sigma_in, no_act_delay, bus_eta_s,
                wrong_phase=False)
            rows.append((f'GE_{t_ge:.0f}', t_ge, r_ge, so_ge, tp_ge,
                         bps_ge, cpc_ge, nsd_ge, std_ge))

        r_ip, so_ip, tp_ip, bps_ip, cpc_ip, nsd_ip, std_ip = self._dctsp_eval_action(
            'INS_POST', t_sw, sigma_in, no_act_delay, bus_eta_s,
            remaining_red_s=remaining_red_s)
        rows.append((f'INS_POST_{t_sw:.0f}', t_sw, r_ip, so_ip, tp_ip,
                     bps_ip, cpc_ip, nsd_ip, std_ip))

        r_ipt, so_ipt, tp_ipt, bps_ipt, cpc_ipt, nsd_ipt, std_ipt = self._dctsp_eval_action(
            'INS_PRETERM', t_sw, sigma_in, no_act_delay, bus_eta_s,
            remaining_red_s=remaining_red_s)
        rows.append((f'INS_PRETERM_{t_sw:.0f}', t_sw, r_ipt, so_ipt, tp_ipt,
                     bps_ipt, cpc_ipt, nsd_ipt, std_ipt))

        # Plain INS candidates (fixed 5 s overhead) with standard MARL durations.
        # ZIG's INS_POST/INS_PRETERM use shockwave-optimal t_sw which is often
        # longer (20 s) and has higher overhead than a short plain INS (10 s).
        # Adding these ensures ZIG never misses the MARL-optimal short insertion.
        for _zi_dur in [10.0, 15.0, 20.0]:
            _zi_dur = float(np.clip(_zi_dur,
                                    float(DCTSP_MIN_INS_DURATION_S),
                                    float(DCTSP_MAX_INS_DURATION_S)))
            r_zi, so_zi, tp_zi, bps_zi, cpc_zi, nsd_zi, std_zi = self._dctsp_eval_action(
                'INS', _zi_dur, sigma_in, no_act_delay, bus_eta_s)
            rows.append((f'INS_{_zi_dur:.0f}', _zi_dur, r_zi, so_zi, tp_zi,
                         bps_zi, cpc_zi, nsd_zi, std_zi))

        # EARLY_RED — only when on the wrong phase (cutting the bus phase is pointless).
        if _wrong_phase:
            r_er, so_er, tp_er, bps_er, cpc_er, nsd_er, std_er = self._dctsp_eval_action(
                'EARLY_RED', t_sw, sigma_in, no_act_delay, bus_eta_s,
                remaining_red_s=remaining_red_s)
            rows.append((f'ER_{t_sw:.0f}', t_sw, r_er, so_er, tp_er,
                         bps_er, cpc_er, nsd_er, std_er))

        # ── Greedy best across all candidates ────────────────────────────
        best_lbl, best_param = 'NO_ACTION', 0.0
        best_r, best_so, best_tp = r_na, so_na, tp_na
        for (lbl, par, r, so, tp, *_) in rows:
            if r > best_r:
                best_r = r; best_lbl = lbl; best_param = par
                best_so = so; best_tp = tp
        # Recover clean type string (strip duration suffix)
        best_type = (best_lbl if '_' not in best_lbl
                     else ('GE'          if best_lbl.startswith('GE_')         else
                           'INS_POST'    if best_lbl.startswith('INS_POST_')   else
                           'INS_PRETERM' if best_lbl.startswith('INS_PRETERM_') else
                           'INS'         if best_lbl.startswith('INS_')         else
                           'EARLY_RED'   if best_lbl.startswith('ER_')          else
                           best_lbl))
        best_r_delta = best_r - r_na

        # ── Phase-overlap + saturation-avoidance override ─────────────────
        if eff_delay < float(SELFORG_MIN_BUS_DELAY_S):
            # Effective delay too small to justify intervention → keep greedy.
            log_to_file(
                f"[ZIG] BELOW_MIN inter={self.id} t={time:.1f} bus={veh_id} "
                f"eff={eff_delay:.1f}s < {SELFORG_MIN_BUS_DELAY_S:.1f}s "
                f"→ keep greedy {best_type}",
                force=False)
        else:
            # Cost-benefit saturation avoidance.
            #
            # Previous approach used self.OtherDelay for side pressure, which is
            # almost always ~0 (not reliably populated), so the check NEVER triggered
            # and ZIG fired maximum-duration actions on every detection, producing
            # +256% entry delay vs NO_TSP.
            #
            # New approach: compare the cross-traffic cost of the greedy-best action
            # (car_pax_cost_s from the evaluated rows, which already includes
            # NETWORK_FACTOR) against the bus pax-seconds saved.  This is a direct
            # cost-benefit ratio:
            #   _zig_ratio = car_pax_cost / max(bus_pax_saved, 1)
            #   < ZIG_BALANCE_FACTOR (0.75) → bus benefit dominates → fire
            #   ≥ ZIG_BALANCE_FACTOR         → cross-traffic cost too high → NO_ACTION
            #
            # With NETWORK_FACTOR=5.0, a 15s GE that saves 40s × 40pax = 1600 pax·s
            # for the bus but costs 5 × 67.5 = 337.5 pax·s cross-traffic gives
            # ratio = 337.5 / 1600 = 0.21 → fires (bus wins).
            # For INS_PRETERM with 47s preterm cut: cost = 5 × 663 = 3315 pax·s,
            # ratio = 3315 / 1600 = 2.07 → NO_ACTION (network disruption too high).
            try:
                if best_type != 'NO_ACTION':
                    # Use the GREEDY BEST action's saved/cost for the ratio.
                    # (Previous code used max(saved-cost) which is a different
                    # action than the greedy-best and allows, e.g., GE wrong-phase
                    # to slip through because a well-behaved INS passes the check.)
                    _best_row = next((r for r in rows if r[0] == best_lbl), None)
                    if _best_row is not None:
                        _best_saved = float(_best_row[5])
                        _best_cost  = float(_best_row[6])
                    else:
                        _best_saved = 1.0
                        _best_cost  = 0.0
                    if _best_saved <= 0.0:
                        # Bus would be harmed (saved ≤ 0) → force NO_ACTION
                        _zig_ratio = float('inf')
                    else:
                        _zig_ratio = _best_cost / _best_saved
                else:
                    _zig_ratio = 0.0
            except Exception:
                _zig_ratio = 0.0

            if _zig_ratio > float(ZIG_BALANCE_FACTOR):
                # Cross-street pressure dominates → force NO_ACTION.
                log_to_file(
                    f"[ZIG] SATUR_AVOID inter={self.id} t={time:.1f} bus={veh_id} "
                    f"eff={eff_delay:.1f}s side_ratio={_zig_ratio:.2f} > "
                    f"{ZIG_BALANCE_FACTOR:.2f} → NO_ACTION",
                    force=True)
                best_type = 'NO_ACTION'; best_param = 0.0
                best_r = r_na; best_r_delta = 0.0
                best_so = so_na; best_tp = tp_na
            else:
                log_to_file(
                    f"[ZIG] ACT inter={self.id} t={time:.1f} bus={veh_id} "
                    f"eff={eff_delay:.1f}s side_ratio={_zig_ratio:.2f} "
                    f"→ {best_type}_{best_param:.0f}s "
                    f"r={best_r:.4f} Δr={best_r_delta:+.4f}",
                    force=True)

        return (best_type, best_param, best_r, best_r_delta, best_so, best_tp, rows)

    # ─────────────────────────────────────────────────────────────────────────
    # DCTSP-MP-ECTM: Mathematical Programming with Enhanced Cell Transmission
    # ─────────────────────────────────────────────────────────────────────────

    def dctsp_mp_ectm(
        self,
        time: float,
        timeSta: float,
        acycle: float,
        bus_eta_s: float,
        veh_id: int,
        current_phase: int,
        no_act_delay: float,
        sigma_in: float,
        remaining_red_s: float = 0.0,
    ) -> tuple:
        """
        DCTSP-MP-ECTM: Mathematical Programming + Enhanced Cell Transmission
        Model TSP action selection.

        Reference
        ---------
        Bao Z., Liu C., Zheng F. & Tang Y. (2026). "An integrated control
        strategy for urban roads: a dynamic shared bus lane strategy combined
        with transit signal priority control." *Transportmetrica B: Transport
        Dynamics*, 14(1), 2625383.
        DOI: 10.1080/21680566.2026.2625383

        Method
        ------
        Solves the intersection signal optimisation problem (Eq. 33-37) by
        grid-searching the TSP extension duration δ ∈ [MP_ECTM_MIN_EXT_S,
        MP_ECTM_MAX_EXT_S] and evaluating total passenger delay Z(δ) for each
        candidate:

            Z(δ) = ECTM_bus_delay(δ) × α_bus  +  D_side(δ) × α_car  (Eq. 23)

        ECTM bus-approach cell (1D, simplified from Eq. 2-9):
            During red  : n(t+1) = min(n(t) + q_arr·Δt, N_jam)     (Eq. 2)
            During green: q_out  = min(q_sat, n(t)/Δt)              (Eq. 3)
                          n(t+1) = max(0, n(t) + q_arr·Δt − q_out·Δt)
            Vehicle delay (Eq. 21): D_m(t) = n_m(t) × Δt  [veh·s]
            Passenger delay (Eq. 22): PD_bus = D_bus × BusOcc

        Side-street cost D_side(δ) uses the existing cross-traffic shockwave
        model (_dctsp_cross_traffic_delay_s) for each action type:
            GE(δ)        : side loses δ seconds from their next green
            INS_POST(δ)  : side waits remaining_red_s + INTERGREEN + δ total
            INS_PRETERM(δ): side loses remaining_red_s – INTERGREEN of current
                           green AND gets bus phase δ inserted

        Initial bus-approach queue N_q estimated via LWR back-shockwave
        (Newell 1993 / Daganzo 1994), same model as _shockwave_optimal_green_s.

        Signal constraints (Eq. 24-31):
            MP_ECTM_MIN_EXT_S ≤ δ ≤ MP_ECTM_MAX_EXT_S
            Cycle length preserved (side-street green absorbed into δ cost)

        Saturation avoidance (same guard as ZIG / SELFORG):
            eff_delay = max(0, no_act_delay − ZIG_PHASE_OVERLAP_S)
            if eff_delay < SELFORG_MIN_BUS_DELAY_S  → NO_ACTION
            if side_ratio > MP_ECTM_BALANCE_FACTOR   → NO_ACTION

        Returns
        -------
        (best_type, best_param, best_r, best_r_delta,
         best_sigma_out, best_t_poz, rows)

        rows is a list of 9-tuples (label, param, reward, sigma_out, t_poz,
        bus_pax_saved_s, car_pax_cost_s, no_strategy_delay, strategy_delay)
        compatible with the _dctsp_rows reward-cycle CSV format.
        """
        dt          = float(MP_ECTM_DT_S)
        q_sat_vps   = float(getattr(self, 'SaturationFlow', 1800.0)) / 3600.0
        k_jam       = float(getattr(self, 'JamDensity', 200.0))
        _bus_occ    = float(getattr(self, 'BusOcc', 40.0))
        _cycle_s    = float(self.config.get('CycleTime', 135.0))
        _bus_g_base = float(getattr(self, 'BusPhaseDuration', 20.0))
        _wrong_phase = (int(current_phase) != int(self.BusPhase))

        # ── Estimate initial bus-approach queue (LWR, same as ZIG) ───────────
        try:
            upf     = np.asarray(self.UpFlowList, dtype=float)
            rdt     = np.asarray(self.RedDurationList, dtype=float)
            upf_bus = upf[0].ravel() if upf.ndim >= 2 and upf.shape[0] > 0 \
                      else np.zeros(1)
            rdt_bus = rdt[0].ravel() if rdt.ndim >= 2 and rdt.shape[0] > 0 \
                      else np.zeros(1)
            pos_flow = upf_bus[upf_bus > 0.0]
            pos_red  = rdt_bus[(rdt_bus > 0.0) & (rdt_bus < 2.0 * _cycle_s)]
            q_arr_bus_vps = (float(np.mean(pos_flow)) / 3600.0
                             if pos_flow.size > 0 else 300.0 / 3600.0)
            t_red_past    = (float(np.max(pos_red))
                             if pos_red.size > 0 else 60.0)
            k_arr_b  = q_arr_bus_vps * k_jam / max(q_sat_vps, 1e-9)
            w_back_b = q_arr_bus_vps / max(k_jam - k_arr_b, 1.0)
            n0_bus   = max(0.0, w_back_b * t_red_past * k_jam)
        except Exception:
            q_arr_bus_vps = 300.0 / 3600.0
            n0_bus        = 5.0

        # Soft per-cell capacity cap ≈ 15 % of jam density (≈ 30 veh for k_jam=200)
        _cap_veh = k_jam * 0.15

        # ── ECTM 1D cell simulator (Eq. 2-9, Eq. 21-22) ──────────────────────
        def _ctm_delay_pax(n0, q_arr, q_sat, t_wait, g_dur, occ):
            """
            Simulate one CTM cell for t_wait-second red followed by g_dur-second
            green.  Returns total passenger delay (pax·s) = Σ_t n(t)·Δt × occ.
            """
            delay = 0.0
            n = max(0.0, float(n0))
            for _ in range(max(0, int(round(float(t_wait) / dt)))):
                n = min(n + q_arr * dt, _cap_veh)
                delay += n * dt
            for _ in range(max(0, int(round(float(g_dur) / dt)))):
                q_out = min(q_sat, n / max(dt, 1e-9))
                n = max(0.0, n + q_arr * dt - q_out * dt)
                delay += n * dt
            return delay * float(occ)

        # ── NO_ACTION baseline (Eq. 23 with δ=0) ─────────────────────────────
        if _wrong_phase:
            _t_wait_na = float(remaining_red_s)
            _g_bus_na  = _bus_g_base
        else:
            _t_wait_na = 0.0
            _g_bus_na  = float(remaining_red_s)   # remaining green for bus phase

        d_bus_na  = _ctm_delay_pax(n0_bus, q_arr_bus_vps, q_sat_vps,
                                    _t_wait_na, _g_bus_na, _bus_occ)
        d_side_na = float(self._dctsp_cross_traffic_delay_s(0.0))
        z_na      = d_bus_na + d_side_na

        # ── Grid search over δ ∈ [MP_ECTM_MIN_EXT_S, MP_ECTM_MAX_EXT_S] ─────
        _d_min  = float(MP_ECTM_MIN_EXT_S)
        _d_max  = float(MP_ECTM_MAX_EXT_S)
        _d_step = float(dt)          # 1-second grid (Δt resolution)

        best_z     = z_na            # objective under NO_ACTION
        best_delta = 0.0
        best_atype = 'NO_ACTION'

        for _d_raw in np.arange(_d_min, _d_max + _d_step * 0.5, _d_step):
            delta = float(_d_raw)

            if not _wrong_phase:
                # ── GE: extend running bus phase by δ (Eq. 27) ───────────────
                # Bus approach: already in green, green extended to remaining+δ.
                d_bus = _ctm_delay_pax(
                    n0_bus, q_arr_bus_vps, q_sat_vps,
                    0.0, float(remaining_red_s) + delta, _bus_occ)
                # Side streets: their next green is pushed back by δ seconds.
                d_side = float(self._dctsp_cross_traffic_delay_s(delta))
                z_ge   = d_bus + d_side
                if z_ge < best_z:
                    best_z = z_ge; best_delta = delta; best_atype = 'GE'

            else:
                # ── INS_POST: wait for current phase to end, then insert δ ───
                # Bus waits remaining_red_s + INS_INTERGREEN_S, then gets δ green.
                t_wait_post = float(remaining_red_s) + float(INS_INTERGREEN_S)
                d_bus_post  = _ctm_delay_pax(
                    n0_bus, q_arr_bus_vps, q_sat_vps,
                    t_wait_post, delta, _bus_occ)
                # Side loses their green by (remaining_red_s + INTERGREEN + δ)
                # from the perspective of delay caused to ALL side approaches.
                d_side_post = float(self._dctsp_cross_traffic_delay_s(
                    t_wait_post + delta))
                z_post = d_bus_post + d_side_post
                if z_post < best_z:
                    best_z = z_post; best_delta = delta; best_atype = 'INS_POST'

                # ── INS_PRETERM: cut current phase now, insert δ green ────────
                # Bus waits only INS_INTERGREEN_S then gets δ green.
                # Pre-termination cost: side loses (remaining_red_s-INTERGREEN)
                # seconds of current green that was already allocated to them.
                _cut    = max(0.0, float(remaining_red_s) - float(INS_INTERGREEN_S))
                d_bus_pt = _ctm_delay_pax(
                    n0_bus, q_arr_bus_vps, q_sat_vps,
                    float(INS_INTERGREEN_S), delta, _bus_occ)
                d_side_pt = (
                    float(self._dctsp_cross_traffic_delay_s(
                        float(INS_INTERGREEN_S) + delta))
                    + float(self._dctsp_cross_traffic_delay_s(_cut)))
                z_pt = d_bus_pt + d_side_pt
                if z_pt < best_z:
                    best_z = z_pt; best_delta = delta; best_atype = 'INS_PRETERM'

        # ── Saturation avoidance / min-delay guard ────────────────────────────
        eff_delay = max(0.0, float(no_act_delay) - float(ZIG_PHASE_OVERLAP_S))
        _satur_override = False

        if eff_delay < float(SELFORG_MIN_BUS_DELAY_S):
            best_atype = 'NO_ACTION'; best_delta = 0.0; _satur_override = True
            log_to_file(
                f"[MP_ECTM] BELOW_MIN inter={self.id} t={time:.1f} bus={veh_id} "
                f"eff={eff_delay:.1f}s < {SELFORG_MIN_BUS_DELAY_S:.1f}s "
                f"→ NO_ACTION", force=False)
        else:
            try:
                _o_occ = self._estimated_other_vehicle_occupancy()
                _o_d   = (safe_float(self._safe_array_sum(self.OtherDelay))
                          + safe_float(self._safe_array_sum(
                              getattr(self, 'SideDelayBaseline',
                                      np.zeros(1, dtype=float)))))
                _bus_p  = eff_delay * _bus_occ
                _side_p = max(0.0, _o_d) * float(_o_occ)
                _ratio  = _side_p / max(_bus_p, 1.0)
            except Exception:
                _ratio = 0.0

            if _ratio > float(MP_ECTM_BALANCE_FACTOR):
                best_atype = 'NO_ACTION'; best_delta = 0.0; _satur_override = True
                log_to_file(
                    f"[MP_ECTM] SATUR_AVOID inter={self.id} t={time:.1f} bus={veh_id} "
                    f"side_ratio={_ratio:.2f} > {MP_ECTM_BALANCE_FACTOR:.2f} "
                    f"→ NO_ACTION", force=True)

        log_to_file(
            f"[MP_ECTM] inter={self.id} t={time:.1f} bus={veh_id} "
            f"n0={n0_bus:.1f}veh q_arr={q_arr_bus_vps*3600:.0f}vph "
            f"Z_na={z_na:.1f} Z*={best_z:.1f} δ*={best_delta:.1f}s "
            f"{'override' if _satur_override else 'chosen'}={best_atype}",
            force=True)

        # ── Evaluate chosen action via _dctsp_eval_action for CSV rewards ─────
        r_na, so_na, tp_na, bps_na, cpc_na, nsd_na, std_na = self._dctsp_eval_action(
            'NO_ACTION', 0.0, sigma_in, no_act_delay, bus_eta_s)
        rows = [('NO_ACTION', 0.0, r_na, so_na, tp_na, bps_na, cpc_na, nsd_na, std_na)]

        if best_atype != 'NO_ACTION' and best_delta > 0.0:
            r_act, so_act, tp_act, bps_act, cpc_act, nsd_act, std_act = \
                self._dctsp_eval_action(
                    best_atype, best_delta, sigma_in, no_act_delay, bus_eta_s,
                    wrong_phase=_wrong_phase, remaining_red_s=remaining_red_s)
            rows.append((
                f'{best_atype}_{best_delta:.0f}', best_delta,
                r_act, so_act, tp_act, bps_act, cpc_act, nsd_act, std_act))
            best_r       = r_act
            best_so      = so_act
            best_tp      = tp_act
            best_r_delta = r_act - r_na
        else:
            best_atype   = 'NO_ACTION'
            best_delta   = 0.0
            best_r       = r_na
            best_so      = so_na
            best_tp      = tp_na
            best_r_delta = 0.0

        return (best_atype, best_delta, best_r, best_r_delta,
                best_so, best_tp, rows)

    # ─────────────────────────────────────────────────────────────────────────
    # DCTSP-BXT: CTM-Based Multiagent Q-Learning (Chanloha et al. 2014)
    # ─────────────────────────────────────────────────────────────────────────

    def dctsp_bxt(
        self,
        time: float,
        timeSta: float,
        acycle: float,
        bus_eta_s: float,
        veh_id: int,
        current_phase: int,
        no_act_delay: float,
        sigma_in: float,
        remaining_red_s: float = 0.0,
    ) -> tuple:
        """
        DCTSP-BXT: CTM-Based Multiagent Q-Learning with Transit Signal Priority.

        Reference
        ---------
        Chanloha P., Chinrungrueng J., Usaha W. & Aswakul C. (2014).
        "Cell Transmission Model-Based Multiagent Q-Learning for Network-Scale
        Signal Control With Transit Priority." *The Computer Journal*, 57(3),
        451-466.  DOI: 10.1093/comjnl/bxt126

        Method
        ------
        Adapts the paper's CTM-BRT Q-learning framework to the Aimsun DC TSP
        intersection controller:

        1. **CTM state estimation** (Eq. 1-3):
           Estimate bus-approach queue n0_bus and side pressure from Aimsun
           shockwave arrays (UpFlowList, RedDurationList, SaturationFlow,
           JamDensity) using the same LWR back-shockwave model as MP_ECTM.

        2. **CTM red-light delay reward** (Eq. 29-32):
           ϒ(action) = bus_approach_red_delay × BusOcc
                      + side_approach_red_delay × BXT_CAR_OCC
           where each term is simulated step-by-step using the same
           _ctm_delay_pax kernel as MP_ECTM.
           R_bxt(action) = -ϒ(action)  [maximised when delay is minimised]

        3. **ε-greedy action selection** (paper Algorithm, step 2):
           With probability BXT_EPSILON, choose uniformly from the 7 candidates.
           Otherwise choose a = argmax Q(s, a) from the BXT Q-table.

        4. **Q-table update** (Eq. 33, adapted):
           At checkout, _bxt_update_q() applies:
           Q(s,a) ← Q(s,a) + α · [R_bxt_measured − Q(s,a)]
           Parameters: BXT_ALPHA=0.01, BXT_GAMMA=0.005 (paper Table 1).

        Action space: same 7 discrete actions as MARL:
          {NO_ACTION, GE_5, GE_10, GE_15, INS_10, INS_15, INS_20}

        State space (Eq. 1-3 adapted):
          (bus_queue_bin 0-3, side_ratio_bin 0-3, phase_is_bus 0/1, eta_bin 0-3)
          = 4×4×2×4 = 128 states; tabular Q-table.

        Returns
        -------
        (best_type, best_param, best_r, best_r_delta,
         best_sigma_out, best_t_poz, rows)

        rows: list of 9-tuples (label, param, reward, sigma_out, t_poz,
        bus_pax_saved_s, car_pax_cost_s, no_strategy_delay, strategy_delay)
        compatible with the _dctsp_rows reward-cycle CSV format.
        Also stores the state and chosen action_idx in _poz_action_log for
        the terminal BXT Q-update at checkout.
        """
        import random as _rnd_bxt

        dt           = float(BXT_DT_S)
        q_sat_vps    = float(getattr(self, 'SaturationFlow', 1800.0)) / 3600.0
        k_jam        = float(getattr(self, 'JamDensity', 200.0))
        _bus_occ     = float(getattr(self, 'BusOcc', 40.0))
        _car_occ     = float(BXT_CAR_OCC)
        _cycle_s     = float(self.config.get('CycleTime', 135.0))
        _bus_g_base  = float(getattr(self, 'BusPhaseDuration', 20.0))
        _wrong_phase = (int(current_phase) != int(self.BusPhase))

        # ── Estimate initial bus-approach queue n0 (LWR, Eq. 5-7) ────────────
        try:
            upf     = np.asarray(self.UpFlowList, dtype=float)
            rdt     = np.asarray(self.RedDurationList, dtype=float)
            upf_bus = upf[0].ravel() if upf.ndim >= 2 and upf.shape[0] > 0 \
                      else np.zeros(1)
            rdt_bus = rdt[0].ravel() if rdt.ndim >= 2 and rdt.shape[0] > 0 \
                      else np.zeros(1)
            pos_flow = upf_bus[upf_bus > 0.0]
            pos_red  = rdt_bus[(rdt_bus > 0.0) & (rdt_bus < 2.0 * _cycle_s)]
            q_arr_bus_vps = (float(np.mean(pos_flow)) / 3600.0
                             if pos_flow.size > 0 else 300.0 / 3600.0)
            t_red_past    = (float(np.max(pos_red))
                             if pos_red.size > 0 else 60.0)
            k_arr_b  = q_arr_bus_vps * k_jam / max(q_sat_vps, 1e-9)
            w_back_b = q_arr_bus_vps / max(k_jam - k_arr_b, 1.0)
            n0_bus   = max(0.0, w_back_b * t_red_past * k_jam)
        except Exception:
            q_arr_bus_vps = 300.0 / 3600.0
            n0_bus        = 5.0

        _cap_veh = k_jam * 0.15   # soft cell capacity cap

        # ── CTM 1D cell red-light delay simulator (Eq. 12, 29-30) ────────────
        def _ctm_red_delay(n0, q_arr, q_sat, t_wait_red, g_dur, occ):
            """Return total pax-seconds accumulated while cell faces red.
            Red phase: t_wait_red seconds. Green phase: g_dur seconds.
            Only counts delay during red (vehicles accumulated = red-light delay).
            """
            delay = 0.0
            n = max(0.0, float(n0))
            for _ in range(max(0, int(round(float(t_wait_red) / dt)))):
                n = min(n + q_arr * dt, _cap_veh)
                delay += n * dt            # Eq. 29: (1-G)·n·Δt; G=0 during red
            for _ in range(max(0, int(round(float(g_dur) / dt)))):
                q_out = min(q_sat, n / max(dt, 1e-9))
                n = max(0.0, n + q_arr * dt - q_out * dt)
                # Green phase: G=1 → delay contribution = 0 per Eq. 29-30
            return delay * float(occ)

        # ── BXT red-light delay per action (Eq. 29-32) ───────────────────────
        # Map each of the 7 action candidates to a CTM scenario and compute ϒ.
        # ϒ(action) = bus_red_delay + side_red_delay (Eq. 32)
        # R_bxt = -ϒ  [we maximise reward, paper minimises ϒ]

        def _bxt_reward_for(atype: str, aparam: float) -> tuple:
            """Return (r_bxt, side_action_s) where r_bxt = -ϒ."""
            a_s = float(aparam)
            if atype == 'NO_ACTION':
                # Bus faces no_act_delay seconds at red then natural green.
                if _wrong_phase:
                    t_wait = float(remaining_red_s)
                    g_bus  = _bus_g_base
                else:
                    t_wait = 0.0
                    g_bus  = float(remaining_red_s)   # remaining green on bus phase
                d_bus   = _ctm_red_delay(n0_bus, q_arr_bus_vps, q_sat_vps,
                                         t_wait, g_bus, _bus_occ)
                d_side  = float(self._dctsp_cross_traffic_delay_s(0.0))
                return -(d_bus + d_side), 0.0

            elif atype == 'GE':
                if not _wrong_phase:
                    # Extend running bus green by a_s: bus still in green
                    d_bus  = _ctm_red_delay(n0_bus, q_arr_bus_vps, q_sat_vps,
                                            0.0, float(remaining_red_s) + a_s, _bus_occ)
                    d_side = float(self._dctsp_cross_traffic_delay_s(a_s))
                else:
                    # Wrong-phase GE: extends non-bus phase, bus waits longer
                    d_bus  = _ctm_red_delay(n0_bus, q_arr_bus_vps, q_sat_vps,
                                            float(remaining_red_s) + a_s, _bus_g_base, _bus_occ)
                    d_side = float(self._dctsp_cross_traffic_delay_s(0.0))
                return -(d_bus + d_side), a_s

            elif atype == 'INS':
                # INS_POST: bus waits remaining_red_s + INS_INTERGREEN_S then gets a_s green
                t_wait = float(remaining_red_s) + float(INS_INTERGREEN_S)
                d_bus  = _ctm_red_delay(n0_bus, q_arr_bus_vps, q_sat_vps,
                                        t_wait, a_s, _bus_occ)
                d_side = float(self._dctsp_cross_traffic_delay_s(t_wait + a_s))
                return -(d_bus + d_side), t_wait + a_s

            return 0.0, 0.0

        # ── Build CTM-reward vector for all 7 actions ─────────────────────────
        bxt_rewards = []
        for (_atype, _aparam) in DCTSP_RL_ACTION_SPACE:
            _rb, _ = _bxt_reward_for(_atype, _aparam)
            bxt_rewards.append(_rb)

        # ── BXT CTM state → Q-table bins ─────────────────────────────────────
        try:
            _bxt_o_occ  = self._estimated_other_vehicle_occupancy()
            _bxt_o_d    = (
                safe_float(self._safe_array_sum(self.OtherDelay))
                + safe_float(self._safe_array_sum(
                    getattr(self, 'SideDelayBaseline', np.zeros(1, dtype=float)))))
            _eff_delay  = max(0.0, float(no_act_delay) - float(ZIG_PHASE_OVERLAP_S))
            _bus_p      = _eff_delay * _bus_occ
            _side_p     = max(0.0, _bxt_o_d) * float(_bxt_o_occ)
            _side_ratio = _side_p / max(_bus_p, 1.0)
        except Exception:
            _side_ratio = 0.0
        _bxt_state = _bxt_state_bin(n0_bus, _side_ratio,
                                    not _wrong_phase, float(bus_eta_s))

        # ── ε-greedy selection (paper Algorithm step 2) ───────────────────────
        _use_explore = (_rnd_bxt.random() < float(BXT_EPSILON))
        q_vals = _bxt_get_q(self.id, _bxt_state, init_vals=bxt_rewards)
        if _use_explore:
            _chosen_idx = _rnd_bxt.randrange(len(DCTSP_RL_ACTION_SPACE))
        else:
            _chosen_idx = max(range(len(q_vals)), key=lambda i: q_vals[i])
        _chosen_atype, _chosen_aparam = DCTSP_RL_ACTION_SPACE[_chosen_idx]

        log_to_file(
            f"[BXT] inter={self.id} t={time:.1f} bus={veh_id} "
            f"state={_bxt_state} n0={n0_bus:.1f}veh side_ratio={_side_ratio:.2f} "
            f"explore={_use_explore} chosen={_chosen_atype}_{_chosen_aparam:.0f}s "
            f"r_bxt={bxt_rewards[_chosen_idx]:.2f}",
            force=True)

        # ── Saturation avoidance (same guard as ZIG/MP_ECTM) ─────────────────
        eff_delay = max(0.0, float(no_act_delay) - float(ZIG_PHASE_OVERLAP_S))
        _satur_override = False
        if eff_delay < float(SELFORG_MIN_BUS_DELAY_S):
            _chosen_atype  = 'NO_ACTION'
            _chosen_aparam = 0.0
            _chosen_idx    = 0
            _satur_override = True
            log_to_file(
                f"[BXT] BELOW_MIN inter={self.id} eff={eff_delay:.1f}s → NO_ACTION",
                force=False)
        elif _side_ratio > float(BXT_BALANCE_FACTOR):
            _chosen_atype  = 'NO_ACTION'
            _chosen_aparam = 0.0
            _chosen_idx    = 0
            _satur_override = True
            log_to_file(
                f"[BXT] SATUR_AVOID inter={self.id} side_ratio={_side_ratio:.2f} "
                f"> {BXT_BALANCE_FACTOR:.2f} → NO_ACTION", force=True)

        # ── Evaluate chosen action via _dctsp_eval_action for CSV rows ────────
        r_na, so_na, tp_na, bps_na, cpc_na, nsd_na, std_na = self._dctsp_eval_action(
            'NO_ACTION', 0.0, sigma_in, no_act_delay, bus_eta_s)
        rows = [('NO_ACTION', 0.0, r_na, so_na, tp_na, bps_na, cpc_na, nsd_na, std_na)]

        if _chosen_atype != 'NO_ACTION' and _chosen_aparam > 0.0:
            r_act, so_act, tp_act, bps_act, cpc_act, nsd_act, std_act = \
                self._dctsp_eval_action(
                    _chosen_atype, _chosen_aparam, sigma_in, no_act_delay, bus_eta_s,
                    wrong_phase=_wrong_phase, remaining_red_s=remaining_red_s)
            rows.append((
                f'{_chosen_atype}_{_chosen_aparam:.0f}', _chosen_aparam,
                r_act, so_act, tp_act, bps_act, cpc_act, nsd_act, std_act))
            best_r       = r_act
            best_so      = so_act
            best_tp      = tp_act
            best_r_delta = r_act - r_na
        else:
            _chosen_atype   = 'NO_ACTION'
            _chosen_aparam  = 0.0
            best_r          = r_na
            best_so         = so_na
            best_tp         = tp_na
            best_r_delta    = 0.0

        # ── Store state+action for terminal Q-update at checkout ──────────────
        # Stored in _poz_action_log under a 'BXT' flag so checkout can distinguish
        # and route to _bxt_update_q instead of the MARL terminal update.
        if int(veh_id) not in _poz_action_log:
            _poz_action_log[int(veh_id)] = (
                self.id, _chosen_atype, _chosen_aparam, time,
                _bxt_state, _chosen_idx)

        return (_chosen_atype, _chosen_aparam, best_r, best_r_delta,
                best_so, best_tp, rows)

    # =========================================================================
    # META_TSP: System-optimal adaptive transit signal priority
    # =========================================================================

    def dctsp_meta(
        self,
        time: float,
        timeSta: float,
        acycle: float,
        bus_eta_s: float,
        veh_id: int,
        current_phase: int,
        no_act_delay: float,
        sigma_in: float,
        remaining_red_s: float = 0.0,
    ) -> tuple:
        """
        META_TSP: Multi-criteria Enhanced Transit Signal Priority for
        All-traffic Optimisation.

        Philosophy
        ----------
        Unlike all other DCTSP strategies (which maximise a bus-centric
        reward), META_TSP *minimises total system passenger delay* across
        every road user (bus + car + truck).  Bus priority is applied
        only when it produces a net benefit to the whole system, and the
        strength of priority scales with how late the bus is (headway
        deviation σ_in).

        Objective
        ---------
        Z(a) = w_bus(σ) × bus_delay_after(a) × BusOcc
               + META_CAR_OCC × cross_delay(a)            [pax·s, 1 cycle]

        where the adaptive bus weight (Hu et al. 2025 headway, extended):
          w_bus(σ) = META_BASE_BUS_WEIGHT
                     + META_HW_SENSITIVITY
                       × clip(|σ_in| / META_HW_REF_S, 0, 1)

        Multi-horizon:  Z_full = Z + META_OC_WEIGHT × Z_oc_recovery
        Z_oc_recovery penalises the cross-traffic cost of the signal-cycle
        offset recovery that must follow any GE or INS action.

        Decision gate
        -------------
        Act only when: Z(NO_ACTION) - Z(best) ≥ META_MIN_THRESHOLD_PAX_S
        This conservative threshold prevents marginal interventions from
        degrading network throughput when the benefit is negligible.

        Saturation avoidance (same guard as ZIG/MP_ECTM/BXT):
          eff_delay = max(0, no_act_delay - ZIG_PHASE_OVERLAP_S)
          eff_delay < META_MIN_BUS_DELAY_S  → NO_ACTION
          side_ratio > META_BALANCE_FACTOR   → NO_ACTION

        Action space
        ------------
        All 7 discrete candidates PLUS two shockwave-optimal candidates
        (GE_opt and INS_opt computed from the LWR queue-clearance model).

        References
        ----------
        Bao et al. (2026) Transportmetrica B 14(1) 2625383
        Hu et al. (2025) DCTSP Eq. 6 — headway-adherence weighting
        Chanloha et al. (2014) Comput. J. 57(3) — CTM queue simulation
        Newell (1993) / Daganzo (1994) — LWR shockwave-optimal duration

        Returns
        -------
        (best_type, best_param, best_r, best_r_delta,
         best_sigma_out, best_t_poz, rows)
        rows: list of 9-tuples compatible with reward-cycle CSV format.
        """
        dt          = float(META_DT_S)
        bus_occ     = float(getattr(self, 'BusOcc', 40.0))
        car_occ     = float(META_CAR_OCC)
        _cycle_s    = float(self.config.get('CycleTime', 135.0))
        _bus_g_base = float(getattr(self, 'BusPhaseDuration', 20.0))
        _wrong_phase = (int(current_phase) != int(self.BusPhase))
        q_sat_vps   = float(getattr(self, 'SaturationFlow', 1800.0)) / 3600.0
        k_jam       = float(getattr(self, 'JamDensity', 200.0))

        # ── Adaptive bus weight: increases when bus is late (Hu et al. 2025) ──
        _hw_factor = float(np.clip(
            abs(float(sigma_in)) / max(float(META_HW_REF_S), 1.0),
            0.0, 1.0))
        _w_bus = float(META_BASE_BUS_WEIGHT) + float(META_HW_SENSITIVITY) * _hw_factor

        # ── Effective delay (ZIG phase-overlap correction) ────────────────────
        eff_delay = max(0.0, float(no_act_delay) - float(ZIG_PHASE_OVERLAP_S))

        # ── Saturation avoidance / minimum-delay guard ────────────────────────
        try:
            _o_occ_m = self._estimated_other_vehicle_occupancy()
            _o_d_m   = (safe_float(self._safe_array_sum(self.OtherDelay))
                        + safe_float(self._safe_array_sum(
                            getattr(self, 'SideDelayBaseline', np.zeros(1, dtype=float)))))
            _bus_p_m  = eff_delay * bus_occ
            _side_p_m = max(0.0, _o_d_m) * float(_o_occ_m)
            _side_ratio_m = _side_p_m / max(_bus_p_m, 1.0)
        except Exception:
            _side_ratio_m = 0.0

        if eff_delay < float(META_MIN_BUS_DELAY_S):
            log_to_file(
                f"[META_TSP] BELOW_MIN inter={self.id} t={time:.1f} bus={veh_id} "
                f"eff={eff_delay:.1f}s < {META_MIN_BUS_DELAY_S:.1f}s → NO_ACTION",
                force=False)
            r_na, so_na, tp_na, bps_na, cpc_na, nsd_na, std_na = self._dctsp_eval_action(
                'NO_ACTION', 0.0, sigma_in, no_act_delay, bus_eta_s)
            rows = [('NO_ACTION', 0.0, r_na, so_na, tp_na, bps_na, cpc_na, nsd_na, std_na)]
            return ('NO_ACTION', 0.0, r_na, 0.0, so_na, tp_na, rows)

        if _side_ratio_m > float(META_BALANCE_FACTOR):
            log_to_file(
                f"[META_TSP] SATUR_AVOID inter={self.id} t={time:.1f} bus={veh_id} "
                f"side_ratio={_side_ratio_m:.2f} > {META_BALANCE_FACTOR:.2f} → NO_ACTION",
                force=True)
            r_na, so_na, tp_na, bps_na, cpc_na, nsd_na, std_na = self._dctsp_eval_action(
                'NO_ACTION', 0.0, sigma_in, no_act_delay, bus_eta_s)
            rows = [('NO_ACTION', 0.0, r_na, so_na, tp_na, bps_na, cpc_na, nsd_na, std_na)]
            return ('NO_ACTION', 0.0, r_na, 0.0, so_na, tp_na, rows)

        # ── LWR bus-approach queue estimate (same as ZIG / MP_ECTM) ──────────
        try:
            upf     = np.asarray(self.UpFlowList, dtype=float)
            rdt     = np.asarray(self.RedDurationList, dtype=float)
            upf_bus = upf[0].ravel() if upf.ndim >= 2 and upf.shape[0] > 0 \
                      else np.zeros(1)
            rdt_bus = rdt[0].ravel() if rdt.ndim >= 2 and rdt.shape[0] > 0 \
                      else np.zeros(1)
            pos_flow = upf_bus[upf_bus > 0.0]
            pos_red  = rdt_bus[(rdt_bus > 0.0) & (rdt_bus < 2.0 * _cycle_s)]
            q_arr_vps = (float(np.mean(pos_flow)) / 3600.0
                         if pos_flow.size > 0 else 300.0 / 3600.0)
            t_red_past = (float(np.max(pos_red))
                          if pos_red.size > 0 else 60.0)
            k_arr  = q_arr_vps * k_jam / max(q_sat_vps, 1e-9)
            w_back = q_arr_vps / max(k_jam - k_arr, 1.0)
            n0_bus = max(0.0, w_back * t_red_past * k_jam)
        except Exception:
            q_arr_vps = 300.0 / 3600.0
            n0_bus    = 5.0

        _cap_veh = k_jam * 0.15

        # ── CTM 1D cell total-delay simulator ────────────────────────────────
        def _ctm_total_pax_delay(n0, q_arr, q_sat, t_wait, g_dur, occ):
            """Total passenger delay (pax·s) over [wait+green] window."""
            delay = 0.0
            n = max(0.0, float(n0))
            for _ in range(max(0, int(round(float(t_wait) / dt)))):
                n = min(n + q_arr * dt, _cap_veh)
                delay += n * dt
            for _ in range(max(0, int(round(float(g_dur) / dt)))):
                q_out = min(q_sat, n / max(dt, 1e-9))
                n = max(0.0, n + q_arr * dt - q_out * dt)
                delay += n * dt
            return delay * float(occ)

        # ── Shockwave-optimal duration (ZIG LWR model) ────────────────────────
        t_sw = self._shockwave_optimal_green_s(
            min_s=float(DCTSP_MIN_INS_DURATION_S),
            max_s=float(DCTSP_MAX_INS_DURATION_S),
        )
        _max_d  = max(_cycle_s - _bus_g_base, 0.0)
        _miss_by = max(0.0, _max_d - float(no_act_delay))
        t_ge_opt = float(np.clip(_miss_by + t_sw,
                                  float(DCTSP_MIN_INS_DURATION_S),
                                  float(MAX_GE_EXTENSION_S)))

        # ── META_TSP total system cost function ───────────────────────────────
        def _meta_z(atype: str, aparam: float) -> float:
            """
            Total system pax·s cost for one signal cycle.
            Z = w_bus × CTM_bus_delay + car_occ × cross_delay
              + META_OC_WEIGHT × car_occ × oc_recovery_cross_delay
            """
            a_s = float(aparam)
            oc_s = min(a_s, float(DCTSP_OC_MAX_ADJ_S)) if a_s > 0.0 else 0.0

            if atype == 'NO_ACTION':
                if _wrong_phase:
                    t_wait = float(remaining_red_s)
                    g_bus  = _bus_g_base
                else:
                    t_wait = 0.0
                    g_bus  = float(remaining_red_s)
                d_bus  = _ctm_total_pax_delay(n0_bus, q_arr_vps, q_sat_vps,
                                              t_wait, g_bus, bus_occ)
                d_cross = float(self._dctsp_cross_traffic_delay_s(0.0))
                return _w_bus * d_bus + car_occ * d_cross

            elif atype == 'GE':
                if not _wrong_phase:
                    g_dur_ge = float(remaining_red_s) + a_s
                    if bus_eta_s > g_dur_ge:
                        # Bus misses even the extended green → no bus benefit
                        d_bus = _ctm_total_pax_delay(n0_bus, q_arr_vps, q_sat_vps,
                                                     0.0, float(remaining_red_s),
                                                     bus_occ)
                    else:
                        d_bus = _ctm_total_pax_delay(n0_bus, q_arr_vps, q_sat_vps,
                                                     0.0, g_dur_ge, bus_occ)
                    d_cross = float(self._dctsp_cross_traffic_delay_s(a_s))
                    d_oc    = float(self._dctsp_cross_traffic_delay_s(oc_s))
                    return _w_bus * d_bus + car_occ * (d_cross
                                                       + float(META_OC_WEIGHT) * d_oc)
                else:
                    # Wrong-phase GE extends non-bus phase → bus waits longer
                    d_bus = _ctm_total_pax_delay(n0_bus, q_arr_vps, q_sat_vps,
                                                 float(remaining_red_s) + a_s,
                                                 _bus_g_base, bus_occ)
                    d_cross = float(self._dctsp_cross_traffic_delay_s(0.0))
                    return _w_bus * d_bus + car_occ * d_cross

            elif atype in ('INS', 'INS_POST'):
                t_wait = float(remaining_red_s) + float(INS_INTERGREEN_S)
                ins_green_end = t_wait + a_s
                if bus_eta_s > ins_green_end:
                    # Bus arrives after inserted green → no bus benefit
                    d_bus = _ctm_total_pax_delay(n0_bus, q_arr_vps, q_sat_vps,
                                                 float(remaining_red_s), _bus_g_base,
                                                 bus_occ)
                else:
                    d_bus  = _ctm_total_pax_delay(n0_bus, q_arr_vps, q_sat_vps,
                                                  t_wait, a_s, bus_occ)
                d_cross = float(self._dctsp_cross_traffic_delay_s(t_wait + a_s))
                d_oc    = float(self._dctsp_cross_traffic_delay_s(oc_s))
                return _w_bus * d_bus + car_occ * (d_cross
                                                   + float(META_OC_WEIGHT) * d_oc)

            elif atype == 'INS_PRETERM':
                t_wait = float(INS_INTERGREEN_S)
                _cut   = max(0.0, float(remaining_red_s) - t_wait)
                ins_green_end = t_wait + a_s
                if bus_eta_s > ins_green_end:
                    # Bus arrives after inserted green → preterm costs cross-traffic
                    # with no bus benefit; use NO_ACTION equivalent bus delay.
                    d_bus = _ctm_total_pax_delay(n0_bus, q_arr_vps, q_sat_vps,
                                                 float(remaining_red_s), _bus_g_base,
                                                 bus_occ)
                else:
                    d_bus  = _ctm_total_pax_delay(n0_bus, q_arr_vps, q_sat_vps,
                                                  t_wait, a_s, bus_occ)
                d_cross = (float(self._dctsp_cross_traffic_delay_s(t_wait + a_s))
                           + float(self._dctsp_cross_traffic_delay_s(_cut)))
                d_oc    = float(self._dctsp_cross_traffic_delay_s(oc_s))
                return _w_bus * d_bus + car_occ * (d_cross
                                                   + float(META_OC_WEIGHT) * d_oc)

            return float('inf')

        # ── Evaluate all candidates ───────────────────────────────────────────
        # Discrete: 7 standard candidates
        _candidates: list = [
            ('NO_ACTION', 0.0),
        ]
        for _ge in DCTSP_GE_ACTIONS:
            _candidates.append(('GE', float(_ge)))
        for _ins in DCTSP_INS_DURATIONS:
            _candidates.append(('INS', float(_ins)))
        # Shockwave-optimal candidates (LWR-derived)
        if t_ge_opt not in DCTSP_GE_ACTIONS:
            _candidates.append(('GE', t_ge_opt))       # GE_opt
        if t_sw not in DCTSP_INS_DURATIONS:
            _candidates.append(('INS', t_sw))           # INS_opt (shockwave)
        # INS_PRETERM shockwave optimal (when wrong phase, faster bus relief)
        if _wrong_phase:
            _candidates.append(('INS_PRETERM', t_sw))

        # Compute Z for all candidates
        _z_na    = _meta_z('NO_ACTION', 0.0)
        best_atype  = 'NO_ACTION'
        best_aparam = 0.0
        best_z      = _z_na
        for (_at, _ap) in _candidates:
            _z = _meta_z(_at, _ap)
            if _z < best_z:
                best_z = _z; best_atype = _at; best_aparam = _ap

        # ── Conservative gate: act only if improvement ≥ threshold ───────────
        _improvement_pax_s = _z_na - best_z
        if _improvement_pax_s < float(META_MIN_THRESHOLD_PAX_S):
            best_atype  = 'NO_ACTION'
            best_aparam = 0.0
            log_to_file(
                f"[META_TSP] BELOW_THRESH inter={self.id} t={time:.1f} "
                f"bus={veh_id} improve={_improvement_pax_s:.1f}pax·s "
                f"< {META_MIN_THRESHOLD_PAX_S:.1f} → NO_ACTION "
                f"best_cand={best_atype}_{best_aparam:.0f}s Z_na={_z_na:.1f}",
                force=True)
        else:
            # Log Z for each candidate to understand what was considered
            _z_log_parts = []
            for (_at, _ap) in _candidates:
                _z_cand = _meta_z(_at, _ap)
                _z_log_parts.append(f"{_at}_{_ap:.0f}={_z_cand:.1f}")
            log_to_file(
                f"[META_TSP] ACT inter={self.id} t={time:.1f} bus={veh_id} "
                f"w_bus={_w_bus:.2f}(σ={sigma_in:.0f}s) "
                f"Z_na={_z_na:.1f} Z*={best_z:.1f} "
                f"improve={_improvement_pax_s:.1f}pax·s "
                f"→ {best_atype}_{best_aparam:.0f}s "
                f"candidates=[{' | '.join(_z_log_parts)}]",
                force=True)

        log_to_file(
            f"[META_TSP] SUMMARY inter={self.id} t={time:.1f} bus={veh_id} "
            f"eff={eff_delay:.1f}s side_ratio={_side_ratio_m:.2f} "
            f"w_bus={_w_bus:.2f} t_sw={t_sw:.1f}s t_ge_opt={t_ge_opt:.1f}s "
            f"Z_na={_z_na:.1f} Z*={best_z:.1f} chosen={best_atype}_{best_aparam:.0f}s "
            f"wrong_phase={_wrong_phase} n_candidates={len(_candidates)}",
            force=True)

        # ── Build _dctsp_rows via _dctsp_eval_action for CSV ─────────────────
        # Evaluate all 7 standard MARL candidates so the dashboard reward table
        # is fully populated (no '—' cells), even though META_TSP selected its
        # action via the CTM objective rather than the MARL reward.
        rows = []
        _std_cands = [
            ('NO_ACTION', 0.0),
            ('GE', 5.0), ('GE', 10.0), ('GE', 15.0),
            ('INS', 10.0), ('INS', 15.0), ('INS', 20.0),
        ]
        for _rc_at, _rc_ap in _std_cands:
            _r_rc, _so_rc, _tp_rc, _bps_rc, _cpc_rc, _nsd_rc, _std_rc = \
                self._dctsp_eval_action(
                    _rc_at, _rc_ap, sigma_in, no_act_delay, bus_eta_s,
                    wrong_phase=_wrong_phase, remaining_red_s=remaining_red_s)
            _lbl_rc = _rc_at if _rc_at == 'NO_ACTION' else f'{_rc_at}_{_rc_ap:.0f}'
            rows.append((_lbl_rc, _rc_ap, _r_rc, _so_rc, _tp_rc,
                         _bps_rc, _cpc_rc, _nsd_rc, _std_rc))
        # Also include the chosen action if it's a shockwave-optimal non-standard param
        _best_lbl = (best_atype if best_atype == 'NO_ACTION'
                     else f'{best_atype}_{best_aparam:.0f}')
        if best_atype != 'NO_ACTION' and not any(r[0] == _best_lbl for r in rows):
            _r_bc, _so_bc, _tp_bc, _bps_bc, _cpc_bc, _nsd_bc, _std_bc = \
                self._dctsp_eval_action(
                    best_atype, best_aparam, sigma_in, no_act_delay, bus_eta_s,
                    wrong_phase=_wrong_phase, remaining_red_s=remaining_red_s)
            rows.append((_best_lbl, best_aparam, _r_bc, _so_bc, _tp_bc,
                         _bps_bc, _cpc_bc, _nsd_bc, _std_bc))

        r_na  = next(r[2] for r in rows if r[0] == 'NO_ACTION')
        so_na = next(r[3] for r in rows if r[0] == 'NO_ACTION')
        tp_na = next(r[4] for r in rows if r[0] == 'NO_ACTION')
        if best_atype != 'NO_ACTION':
            _br = next((r for r in rows if r[0] == _best_lbl), None)
            if _br is not None:
                best_r = _br[2]; best_so = _br[3]; best_tp = _br[4]
                best_r_delta = best_r - r_na
            else:
                best_r = r_na; best_so = so_na; best_tp = tp_na; best_r_delta = 0.0
        else:
            best_atype   = 'NO_ACTION'
            best_aparam  = 0.0
            best_r       = r_na
            best_so      = so_na
            best_tp      = tp_na
            best_r_delta = 0.0

        return (best_atype, best_aparam, best_r, best_r_delta,
                best_so, best_tp, rows)

    # =========================================================================
    # EXISTING METHODS — unchanged from original
    # =========================================================================

    def initialize_state(self):

        # n_phases must cover every detector group in UpDetList AND every
        # PhaseIndex value used in the config.  When NumberOfPhases is absent
        # (e.g. kg configs that omit it), derive the minimum required size so
        # UpDetCountList[i] and friends don't raise IndexError at i=1+.
        _cfg_n_phases = self.config.get("NumberOfPhases", None)
        _det_groups   = max(len(self.UpDetList), 1)
        _phase_idx_max = (max(self.PhaseIndex.values()) + 1
                          if self.PhaseIndex else 1)
        if _cfg_n_phases is not None:
            n_phases = max(int(_cfg_n_phases), _det_groups, _phase_idx_max, 1)
        else:
            n_phases = max(_det_groups, _phase_idx_max, 1)

        n_lanes  = max(self.NumberOfLanes, 1)
        n_busdet = max(len(self.BusDet), 1)
        # Queue arrays must be wide enough for all detectors in the largest UpDetList group.
        # After NB+SB merge a group may have more detectors than n_lanes.
        _max_group = max((len(g) for g in self.UpDetList if g), default=1)
        n_cols = max(n_lanes, _max_group)
        
        
        self.BusPresence           = np.zeros((1, n_busdet))
        self.BusSpeed              = np.zeros((1, n_busdet))

        self.UpDetCountList        = np.zeros((n_phases, n_cols))
        self.UpDetOccList          = np.zeros((n_phases, n_cols))
        self.UpAveOccList          = np.zeros((n_phases, n_cols))
        self.RedStartTimeList      = np.zeros((n_phases, n_cols))
        self.GreenStartTimeList    = np.zeros((n_phases, n_cols))
        self.RedDurationList       = np.zeros((n_phases, n_cols))
        self.GreenDurationList     = np.zeros((n_phases, n_cols))
        self.UpFlowList            = np.zeros((n_phases, n_cols))
        self.UpDenList             = np.zeros((n_phases, n_cols))
        self.ShockwaveSpeed1List   = np.zeros((n_phases, n_cols))
        self.ShockwaveSpeed2List   = np.zeros((n_phases, n_cols))
        self.ShockwaveSpeed3List   = np.zeros((n_phases, n_cols))
        self.ShockwaveSpeed4List   = np.zeros((n_phases, n_cols))
        self.MaxQueueLength        = np.zeros((n_phases, n_cols))
        self.MaxQueueLengthTime    = np.zeros((n_phases, n_cols))
        self.MinQueueLength        = np.zeros((n_phases, n_cols))
        self.MinQueueLengthTime    = np.zeros((n_phases, n_cols))
        self.QueueDissTime         = np.zeros((n_phases, n_cols))
        self.NextRedStartTime      = np.zeros((n_phases, n_cols))

        # Harmony Search arrays
        self.HSRedStartTimeList    = np.zeros((n_phases, n_cols))
        self.HSRedDurationList     = np.zeros((n_phases, n_cols))
        self.HSGreenStartTimeList  = np.zeros((n_phases, n_cols))
        self.HSGreenDurationList   = np.zeros((n_phases, n_cols))
        self.HSNextRedStartTime    = np.zeros((n_phases, n_cols))
        self.HSUpFlowList          = np.zeros((n_phases, n_cols))
        self.HSUpDenList           = np.zeros((n_phases, n_cols))
        self.HSShockwaveSpeed1List = np.zeros((n_phases, n_cols))
        self.HSShockwaveSpeed3List = np.zeros((n_phases, n_cols))
        self.HSMaxQueueLength      = np.zeros((n_phases, n_cols))
        self.HSMaxQueueLengthTime  = np.zeros((n_phases, n_cols))
        self.HSMinQueueLength      = np.zeros((n_phases, n_cols))

        self.BusDelay              = np.zeros((n_phases, n_cols))
        self.OtherDelay            = np.zeros((n_phases, n_cols))
        self.TotalVeh              = np.zeros((n_phases, n_cols))

        side_secs = self._get_side_sections()
        n_side = max(len(side_secs), 1)
        self.SideUpFlowList        = np.zeros(n_side)
        self.SideUpDenList         = np.zeros(n_side)
        self.SideShockwaveSpeed1   = np.zeros(n_side)
        self.SideShockwaveSpeed3   = np.zeros(n_side)
        self._side_red_start       = np.zeros(n_side)
        self._side_last_phase      = ECIGetCurrentPhase(self.node_id)

        # Persistent per-vehicle delay tracking for side sections.
        # Key: (section_id, vehicle_id); value: last measured delay (s).
        # Initialised here so collect_delay never has to check hasattr.
        self._side_stoptime_prev: dict = {}

        # Profile all approach sections once at startup (geometry + ff time).
        try:
            self._profile_sections()
        except Exception:
            pass

        # Other state variables
        self.BusJoinQueueTime      = np.zeros((n_phases, n_cols))
        self.BusStoplineTime       = np.zeros((n_phases, n_cols))
        self.BusPhaseMinDuration   = np.zeros((n_phases, n_cols))
        self.HSQueueDissTime       = np.zeros((n_phases, n_cols))

        self.step_delay            = 0.0
        self.TSPActiveTime         = 0.0
        self.flag                  = 0
        self.previous_phase        = ECIGetCurrentPhase(self.node_id)
        self.last_detected_bus_id  = -1

        # Sentinel values
        self.BusPhaseEndTime       = 1e9
        self.TimeToTerminateBusPhase = 1e9

        # ── Cycle-recovery state (GE only) ────────────────────────────────────
        # When a green extension of X seconds is granted the cycle is "in debt".
        # After the GE ends, remaining phases are shortened proportionally so the
        # cycle re-aligns with its nominal start offset as quickly as possible.
        # _ge_debt_s  : seconds still owed (decremented as phases absorb it)
        # _ge_opt_GE  : the extension that was granted (for logging)
        self._ge_debt_s  = 0.0
        self._ge_opt_GE  = 0.0

        # _nominal_phase_durations: lazily-populated on first GE.
        # Stores the ORIGINAL plan durations so cycle recovery always trims
        # relative to the base (not relative to a previously-trimmed value).
        # Without this, repeated GEs compound trimming → permanent short greens.
        self._nominal_phase_durations: dict = {}

        # _phases_to_restore: set after trimming — {phase: nominal_dur}.
        # Restored to their nominals when BusPhase next becomes current
        # (i.e. start of the next signal cycle), ensuring trimmed durations
        # only apply for ONE cycle.
        self._phases_to_restore: dict = {}
        self._restore_fired_this_cycle: bool = False

        if LOG_INIT: AKIPrintString(f"[INIT] Inter {self.id} | phases={n_phases} | lanes={n_lanes} | busdets={n_busdet} | arrays initialized safely")

    def _get_inter_state(self):
        inter_map = getattr(self.stats, '_inter', None)
        if inter_map is None:
            return None
        return inter_map.get(self.id)

    def _normalize_sections(self, sections):
        if sections is None:
            return []

        if isinstance(sections, np.ndarray):
            sections = sections.tolist()
        elif isinstance(sections, str):
            sections = sections.replace(';', ',').split(',')
        elif isinstance(sections, (int, float, np.integer, np.floating)):
            sections = [sections]
        else:
            try:
                sections = list(sections)
            except TypeError:
                sections = [sections]

        normalized = []
        seen = set()
        for sec in sections:
            sec_val = safe_float(sec, default=-1.0)
            if sec_val <= 0.0:
                continue
            sec_id = int(sec_val)
            if sec_id not in seen:
                seen.add(sec_id)
                normalized.append(sec_id)
        return normalized

    def _derive_sections_from_detectors(self):
        sections = []
        seen = set()
        invalid_dets = []
        valid_dets = []
        for phase in self.UpDetList:
            for det_id in phase:
                det_info = AKIDetGetPropertiesDetectorById(det_id)
                if getattr(det_info, 'report', -1) < 0:
                    invalid_dets.append(det_id)
                    continue
                valid_dets.append(det_id)
                sec_id = int(getattr(det_info, 'IdSection', 0) or 0)
                if sec_id > 0 and sec_id not in seen:
                    seen.add(sec_id)
                    sections.append(sec_id)
        if invalid_dets:
            # Scan ALL detectors in the model and report any whose IDs are
            # adjacent (±2000) to the invalid IDs — helpful for finding the real IDs.
            _nearby = {}
            _all_det_sec = {}   # det_id → section_id for every valid detector in model
            try:
                n_all = AKIDetGetNumberDetectors()
                for _di in range(n_all):
                    _did = AKIDetGetIdDetector(_di)
                    _p = AKIDetGetPropertiesDetectorById(_did)
                    if getattr(_p, 'report', -1) >= 0:
                        _dsec = getattr(_p, 'IdSection', -1)
                        _all_det_sec[_did] = _dsec
                        for _bad in invalid_dets:
                            if abs(_did - _bad) <= 2000:
                                _nearby[_did] = _dsec
            except Exception:
                pass

            # Junction-based scan: find detectors on turn-origin sections that are
            # NOT in the valid-detector section list — identifies missing approach dets
            _junction_cands = {}
            if True:   # always run: even partial valid_dets can miss an approach
                try:
                    n_turns = AKIInfNetGetNbTurnsInNode(self.node_id)
                    _turn_orig_secs = set()
                    for _ti in range(n_turns):
                        try:
                            _tsec = AKIInfNetGetOriginSectionInTurn(self.node_id, _ti)
                            if _tsec > 0:
                                _turn_orig_secs.add(_tsec)
                        except Exception:
                            pass
                    _missing_secs = _turn_orig_secs - set(sections)
                    for _did, _dsec in _all_det_sec.items():
                        if _dsec in _missing_secs:
                            _junction_cands[_did] = _dsec
                except Exception:
                    pass

            log_to_file(
                f"[INIT_WARN] inter={self.id} "
                f"{len(invalid_dets)} INVALID detector IDs (report<0): {invalid_dets} — "
                f"buses on their sections will NOT be detected. "
                f"Valid detectors: {valid_dets} → sections: {sections}. "
                f"Nearby valid IDs (±2000): {_nearby}. "
                f"Junction-approach candidates: {_junction_cands}")
        return sections

    def _resolve_node_id(self):
        """
        Verify self.node_id is a valid Aimsun node ID by calling
        AKIInfNetGetNbTurnsInNode.  If it returns a negative error code,
        auto-discover the real node ID by querying idNodeTo on each known
        approach section.  Logs the result so the operator can update
        intersection_configs.py with the correct AimsunNodeID.
        """
        test = AKIInfNetGetNbTurnsInNode(self.node_id)
        if test >= 0:
            # Already valid — nothing to do
            return

        # node_id is wrong: find the real node from approach sections
        if LOG_NODE_ID:
            log_to_file(
                f"[NODE_ID] inter={self.id} node_id={self.node_id} invalid "
                f"(AKIInfNetGetNbTurnsInNode returned {test}) — auto-discovering ..."
            )
        candidates = {}   # node_id → count of sections pointing to it
        for sec_id in self.incoming_sections:
            try:
                si = AKIInfNetGetSectionANGInf(sec_id)
                if si.report >= 0 and si.idNodeTo > 0:
                    candidates[si.idNodeTo] = candidates.get(si.idNodeTo, 0) + 1
            except Exception:
                pass

        if candidates:
            best = max(candidates, key=candidates.get)
            # NODE_ID resolution is always logged — critical config hint
            log_to_file(
                f"[NODE_ID] inter={self.id} auto-resolved node_id "
                f"{self.node_id} → {best}  "
                f"(votes: {candidates})  "
                f"*** add AimsunNodeID: {best} to intersection_configs.py ***"
            )
            self.node_id = best
        else:
            # Always log failure — it means signal control is broken
            log_to_file(
                f"[NODE_ID] inter={self.id} could not auto-resolve node_id — "
                f"all approach sections returned report<0 (transit links). "
                f"Signal control and topology calls will be broken for this junction."
            )

    def _initialize_section_tracking(self):
        inter_state = self._get_inter_state()  # may be None if stats not yet registered
        detector_secs = self._derive_sections_from_detectors()

        main_secs = self._normalize_sections(self.config.get('MainSections', []))
        if not main_secs and inter_state is not None:
            main_secs = self._normalize_sections(inter_state.get('main_sections', []))
        for sec_id in detector_secs:
            if sec_id not in main_secs:
                main_secs.append(sec_id)

        side_secs = self._normalize_sections(self.config.get('SideSections', []))
        if not side_secs and inter_state is not None:
            side_secs = self._normalize_sections(inter_state.get('side_sections', []))

        # Topology fallback: when ALL configured detectors are invalid (or BusDet is empty),
        # detector_secs and main_secs are both empty → detect_bus and collect_delay find
        # no sections to scan.  Fall back to every turn-origin section at this junction so
        # the controller can still detect buses and measure delay without physical detectors.
        self._topo_fallback_main = False  # True = main_secs came from topology, not detectors
        if not main_secs:
            try:
                _topo_seen = set()
                _topo_secs = []
                n_turns = AKIInfNetGetNbTurnsInNode(self.node_id)
                for _ti in range(n_turns):
                    try:
                        _tsec = AKIInfNetGetOriginSectionInTurn(self.node_id, _ti)
                        if _tsec > 0 and _tsec not in _topo_seen:
                            _topo_seen.add(_tsec)
                            _topo_secs.append(_tsec)
                    except Exception:
                        pass
                if _topo_secs:
                    main_secs = _topo_secs
                    self._topo_fallback_main = True
                    if LOG_SECTION:
                        log_to_file(
                            f"[SECTION] inter={self.id} no valid detector sections — "
                            f"topology fallback: incoming_sections={main_secs}")
            except Exception:
                pass

        self.incoming_sections = list(main_secs)
        self.config['MainSections'] = list(main_secs)
        self.config['SideSections'] = list(side_secs)

        if inter_state is not None:
            inter_state['main_sections'] = list(main_secs)
            inter_state['side_sections'] = list(side_secs)

    def _validate_section_ids(self, sec_ids):
        """Return only section IDs that exist in this Aimsun model."""
        valid = []
        for sid in sec_ids:
            try:
                result = AKIVehStateGetNbVehiclesSection(sid, False)
                if result >= 0:
                    valid.append(sid)
            except Exception:
                pass
        return valid

    def _classify_sections_by_geometry(self, section_ids):
        """
        Split approach sections into main (corridor, N-S) and side (cross-street, E-W)
        using their geometric orientation relative to the junction centroid.

        Used when no UpDetList detector sections are configured — the only reliable AAPI
        way to distinguish Logan Road (N-S) approaches from cross-street (E-W) approaches.

        Returns (main_secs, side_secs) as lists of int section IDs.
        Falls back to (all_sections, []) if coordinates are unavailable.
        """
        jct_xy = self._get_junction_xy()
        if jct_xy is None:
            return list(section_ids), []

        jx, jy = float(jct_xy[0]), float(jct_xy[1])
        # Try alternate XY attribute names used across Aimsun versions
        _XY_ATTRS = [
            ('xSection',     'ySection'),
            ('xSectionTo',   'ySectionTo'),
            ('xcoordTo',     'ycoordTo'),
            ('xTo',          'yTo'),
            ('xDestination', 'yDestination'),
            ('xcoord',       'ycoord'),
            ('x',            'y'),
        ]

        main_secs, side_secs, unknown_secs = [], [], []
        for sec_id in section_ids:
            try:
                si = AKIInfNetGetSectionANGInf(int(sec_id))
                if getattr(si, 'report', -1) < 0:
                    unknown_secs.append(sec_id)
                    continue
                sx, sy = None, None
                for xa, ya in _XY_ATTRS:
                    _x = getattr(si, xa, None)
                    _y = getattr(si, ya, None)
                    if _x is not None and _y is not None:
                        try:
                            _xf, _yf = float(_x), float(_y)
                            if not (_xf == 0.0 and _yf == 0.0):
                                sx, sy = _xf, _yf
                                break
                        except (TypeError, ValueError):
                            pass
                if sx is None:
                    unknown_secs.append(sec_id)
                    continue
                # Direction vector: from junction centroid → section coordinate.
                # For an incoming section, this vector points AWAY from the junction
                # towards the section's upstream end.
                dx = abs(sx - jx)
                dy = abs(sy - jy)
                if dx < 1.0 and dy < 1.0:
                    # Section centroid essentially at junction — can't determine direction
                    unknown_secs.append(sec_id)
                    continue
                # N-S approach: |dy| dominates; E-W approach: |dx| dominates
                if dy >= dx:
                    main_secs.append(sec_id)   # N-S → Logan Road main corridor
                else:
                    side_secs.append(sec_id)   # E-W → cross-street
            except Exception:
                unknown_secs.append(sec_id)

        # Unknowns are conservatively assigned to main so they use partial stats
        main_secs.extend(unknown_secs)
        if LOG_SIDE_DISC:
            log_to_file(
                f"[SIDE_DISC] inter={self.id} geometry-split: "
                f"main={main_secs} side={side_secs} unknown_kept_main={unknown_secs}"
            )
        return main_secs, side_secs

    def _auto_discover_side_sections(self):
        """
        Discover side-street approach sections feeding into this junction node.
        Uses AKIInfNetGetNbTurnsInNode / AKIInfNetGetOriginSectionInTurn to enumerate
        all incoming sections at the junction, then excludes the main corridor sections
        (those that contain upstream detectors).

        CACHING POLICY:
          • Cache the result only when the AAPI scan itself succeeded (n_turns queried).
          • When the scan fails (exception) or is skipped (_topo_fallback_main), return []
            WITHOUT caching so the next collect_delay call retries.  This prevents a
            transient Aimsun API unavailability at startup from permanently locking in
            an empty side-section set for the whole simulation.
        """
        if hasattr(self, '_cached_side_sections'):
            return self._cached_side_sections

        main_sec_ids = set(self._derive_sections_from_detectors())
        # When all configured detectors are invalid, _derive_sections_from_detectors()
        # returns [].  If incoming_sections was populated from real detectors, use it
        # as the exclusion set.  But if it was populated by topology fallback (no
        # detectors at all), using it would exclude ALL sections → 0 side sections.
        # In that case, use Stats topology discovery which has PyANGKernel info
        # about section names/directions to correctly identify side streets.
        if not main_sec_ids and getattr(self, 'incoming_sections', None):
            if getattr(self, '_topo_fallback_main', False):
                # No detector sections — all incoming_sections came from topology.
                # Use geometric orientation (N-S vs E-W) to split main from side.
                # This is reliable for Logan Road which runs roughly N-S.
                _geo_main, _geo_side = self._classify_sections_by_geometry(
                    self.incoming_sections)
                if _geo_side:
                    # Geometry split succeeded: cache result and refine main sections
                    self._cached_side_sections = _geo_side
                    _inter_d = (self.stats._inter.get(self.id, {})
                                if self.stats else {})
                    if not _inter_d.get('main_sections'):
                        _inter_d['main_sections'] = _geo_main
                        self.config['MainSections'] = _geo_main
                        # Narrow incoming_sections to corridor-only (N-S) sections
                        self.incoming_sections = _geo_main
                        self._topo_fallback_main = False  # geometry split is reliable
                    if LOG_SIDE_DISC:
                        log_to_file(
                            f"[SIDE_DISC] inter={self.id} topo-fallback: "
                            f"geometry resolved main={_geo_main} side={_geo_side}")
                    return _geo_side
                # Geometry couldn't split (coordinates unavailable) — still uncached
                if LOG_SIDE_DISC:
                    log_to_file(
                        f"[SIDE_DISC] inter={self.id} topo-fallback: "
                        f"geometry also failed — treating all incoming as main")
                return []   # intentionally uncached — retry on next call
            main_sec_ids = set(self.incoming_sections)
            if LOG_SIDE_DISC:
                log_to_file(
                    f"[SIDE_DISC] inter={self.id} no detector sections — "
                    f"using incoming_sections as main_sec_ids={sorted(main_sec_ids)}")
        side_secs = []
        tried_method = "none"

        try:
            n_turns = AKIInfNetGetNbTurnsInNode(self.node_id)
            tried_method = "AKIInfNetGetNbTurnsInNode"
            if LOG_SIDE_DISC:
                log_to_file(
                    f"[SIDE_DISC] inter={self.id} node={self.node_id} "
                    f"junction has {n_turns} turns; "
                    f"main_secs={sorted(main_sec_ids)}")

            seen = set()
            for t_idx in range(n_turns):
                try:
                    sec_id = AKIInfNetGetOriginSectionInTurn(self.node_id, t_idx)
                except Exception:
                    continue
                if sec_id <= 0 or sec_id in seen:
                    continue
                seen.add(sec_id)
                if sec_id in main_sec_ids:
                    continue
                try:
                    if AKIVehStateGetNbVehiclesSection(sec_id, False) < 0:
                        continue
                except Exception:
                    continue
                side_secs.append(sec_id)

        except Exception as ex:
            if LOG_SIDE_DISC:
                log_to_file(
                    f"[SIDE_DISC] inter={self.id} turn-based scan error: {ex} — "
                    f"NOT caching empty result (will retry next call)")
            # AAPI call failed — do NOT cache, allow retry
            return []

        # ── Resolve connectors → real upstream queuing sections ──────────────
        # Turn-origin sections in Aimsun are often short connector links (<200 m)
        # that carry no simulated vehicles.  The real approach section where vehicles
        # queue is one (sometimes two) hops upstream.  Replace each connector with
        # its upstream real section so the per-vehicle delay scan finds actual traffic.
        if side_secs:
            side_secs = self._resolve_real_approach_sections(side_secs, main_sec_ids)

        # AAPI scan succeeded (even if n_turns == 0, that is a valid answer).
        # Cache the result so subsequent calls skip the AAPI overhead.
        self._cached_side_sections = side_secs
        if LOG_SIDE_DISC:
            log_to_file(
                f"[SIDE_DISC] inter={self.id} method={tried_method} "
                f"found {len(side_secs)} side sections (after resolve): {side_secs}")
        if side_secs:
            self.config['SideSections'] = side_secs
        return side_secs

    def _resolve_real_approach_sections(self, raw_secs: list, main_sec_ids: set) -> list:
        """
        Replace short connector sections with their real upstream queuing sections.

        Aimsun models often place a short connector link (<200 m) immediately before
        a signalised junction node.  These connectors appear as turn-origin sections
        but carry NO simulated traffic — vehicles queue on the UPSTREAM real section.

        For each section in raw_secs:
          1. If its length >= CONNECTOR_THRESHOLD_M, assume it is a real road section.
          2. Otherwise:
             a. Read the section's origin node (idNodeOrigin) from the network info.
             b. Scan turns at that origin node to find which one has THIS connector
                as its destination.
             c. Return the ORIGIN section of that turn — the real queuing section.
          3. Any resolved section that is itself a connector (still short) is resolved
             one additional hop.  The process stops after 3 hops to avoid infinite loops.
          4. Exclude resolved sections that are already in main_sec_ids.
        """
        CONNECTOR_THRESHOLD_M = 200.0
        MAX_HOPS = 3

        def _resolve_one(sec_id: int, depth: int) -> int:
            if depth >= MAX_HOPS:
                return sec_id
            try:
                si = AKIInfNetGetSectionANGInf(sec_id)
                if getattr(si, 'report', -1) < 0:
                    return sec_id
                if float(si.length) >= CONNECTOR_THRESHOLD_M:
                    return sec_id  # real section, done
                origin_node = int(getattr(si, 'idNodeOrigin', -1) or -1)
                if origin_node <= 0:
                    return sec_id
                n = int(AKIInfNetGetNbTurnsInNode(origin_node))
                for ti in range(n):
                    try:
                        dest = int(AKIInfNetGetDestinationSectionInTurn(origin_node, ti))
                        if dest == sec_id:
                            origin = int(AKIInfNetGetOriginSectionInTurn(origin_node, ti))
                            if origin > 0 and origin != sec_id:
                                return _resolve_one(origin, depth + 1)
                    except Exception:
                        continue
            except Exception:
                pass
            return sec_id

        resolved = []
        seen = set()
        for sec in raw_secs:
            real = _resolve_one(sec, 0)
            if real > 0 and real not in main_sec_ids and real not in seen:
                seen.add(real)
                resolved.append(real)
        return resolved

    def _get_side_sections(self):
        # First try config / stats stored IDs, but validate and resolve them
        candidate = self._normalize_side_sections(self.config.get('SideSections', []))
        if not candidate:
            inter_state = self._get_inter_state()
            if inter_state is not None:
                candidate = self._normalize_side_sections(inter_state.get('side_sections', []))

        if candidate:
            valid = self._validate_section_ids(candidate)
            if valid:
                # Resolve connectors → real approach sections before caching.
                # Also clear any stale _cached_side_sections so the resolved
                # sections get properly cached on next auto-discover call.
                main_ids = set(self.incoming_sections) | set(
                    (self._get_inter_state() or {}).get('main_sections', []))
                resolved = self._resolve_real_approach_sections(valid, main_ids)
                if resolved:
                    self.config['SideSections'] = resolved
                    # Update discovery cache so repeated calls return resolved secs
                    self._cached_side_sections = resolved
                    if LOG_SIDE_DISC and set(resolved) != set(valid):
                        log_to_file(
                            f"[SIDE_DISC] inter={self.id} connector→real resolve: "
                            f"{sorted(valid)} → {sorted(resolved)}")
                    return resolved
                # Resolved to empty — fall through to auto-discovery
            # All stored IDs were invalid — fall through to auto-discovery

        return self._auto_discover_side_sections()

    def _normalize_side_sections(self, side_secs):
        return self._normalize_sections(side_secs)

    def _ensure_side_section_arrays(self, side_secs, time):
        n = max(len(side_secs), 1)
        if len(self.SideUpFlowList) == n:
            return
        self.SideUpFlowList      = np.zeros(n)
        self.SideUpDenList       = np.zeros(n)
        self.SideShockwaveSpeed1 = np.zeros(n)
        self.SideShockwaveSpeed3 = np.zeros(n)

    def _profile_sections(self):
        """
        Build a permanent cache of static section geometry for all approach
        sections (main + side) at this junction.  Called once at startup so
        the delay measurement paths never call AKIInfNetGetSectionANGInf
        during simulation hot-path.

        Cache key: section_id (int)
        Cache value: {
            'length_m': float,     # section length in metres
            'ff_time_s': float,    # free-flow travel time (length / speed_limit)
            'n_lanes':   int,      # number of trafficable lanes
            'sat_flow':  float,    # saturation flow for this section (veh/h/lane)
            'jam_density': float,  # jam density (veh/km)
        }
        """
        if hasattr(self, '_sec_profile'):
            return  # already built

        cache = {}
        # Use _get_side_sections() (which now resolves connectors) so the profile
        # covers real queuing sections, not Aimsun connector links.
        _side = self._get_side_sections()
        all_secs = list(set(self.incoming_sections) | set(_side))
        for sec in all_secs:
            try:
                si       = AKIInfNetGetSectionANGInf(sec)
                length_m = max(float(si.length),    1.0)
                spd_ms   = max(float(si.speedLimit) / 3.6, 1.0)   # km/h → m/s
                n_lanes  = max(int(si.nbCentralLanes) + int(si.nbSideLanes), 1)
                ff_s     = length_m / spd_ms
                cache[sec] = {
                    'length_m':   length_m,
                    'ff_time_s':  ff_s,
                    'n_lanes':    n_lanes,
                    # Use junction-level saturation flow if available; otherwise
                    # fall back to Aimsun default ~1800 veh/h/lane.
                    'sat_flow':   float(getattr(self, 'SaturationFlow', 1800)),
                    'jam_density': float(getattr(self, 'JamDensity', 150)),
                }
            except Exception:
                cache[sec] = {
                    'length_m': 100.0, 'ff_time_s': 10.0,
                    'n_lanes': 1, 'sat_flow': 1800.0, 'jam_density': 150.0,
                }
        self._sec_profile = cache
        # Also seed the legacy side_ff_cache so Priority-B fallback
        # (if ever reached) picks up the correct values immediately.
        if not hasattr(self, '_side_ff_cache'):
            self._side_ff_cache = {}
        for sec, prof in cache.items():
            self._side_ff_cache[sec] = prof['ff_time_s']
        if LOG_SIDE_DISC:
            log_to_file(
                f"[PROFILE] inter={self.id} profiled {len(cache)} sections: "
                + ", ".join(f"{s}(ff={v['ff_time_s']:.1f}s,{v['n_lanes']}ln)"
                            for s, v in cache.items())
            )

    def _compute_spillback_penalty(self, extra_time_s):
        """
        Estimate the corridor-spillback pax-delay cost caused by phase-debt
        recovery trimming non-bus phases after a GE or phase insertion.

        When non-bus phases are trimmed to recover the time given to the bus,
        phases already operating near saturation (v/c > threshold) will have
        overflow vehicles that cannot clear in the shortened window.  Those
        vehicles spill back into the upstream arterial, forming a residual
        queue that: (a) delays subsequent buses approaching from upstream, and
        (b) extends red-phase arrivals on the corridor for the next cycle.

        Model (linear-ramp overflow):
          - Trim for phase i: proportional share of extra_time_s
            (mirrors the debt-recovery logic in _recover_ge_debt)
          - Overflow vehicles: max(0, q_i × trim_i / 3600)
            where q_i is upstream flow for phase i
          - Wait penalty per overflow vehicle ≈ 1 full signal cycle
          - Penalty scales 0→1 linearly from v/c=threshold to v/c=threshold+0.15

        The return value is in the same units as total_pax_delay (pax-seconds
        equivalent) so it can be added directly to the objective.
        """
        extra_time_s = max(safe_float(extra_time_s), 0.0)
        if extra_time_s <= 0.0 or len(self.UpFlowList) < 2:
            return 0.0

        vc_threshold  = float(self.config.get('SpillbackVcThreshold', 0.80))
        cycle_s       = float(self.config.get('CycleTime', 135))
        min_floor     = float(self.config.get('MinGreen', 5.0))
        sat_flow      = max(float(self.SaturationFlow), 1.0)

        # Build headroom table mirroring _recover_ge_debt's proportional logic
        _phase_list  = getattr(self, 'phase_list', [])
        headrooms    = []
        total_hr     = 0.0
        for _i_sp in range(1, len(self.UpFlowList)):
            _ph_sp = (
                _phase_list[_i_sp]
                if _phase_list and _i_sp < len(_phase_list)
                else _i_sp
            )
            _nom_sp = self._nominal_phase_durations.get(_ph_sp)
            if not _nom_sp or _nom_sp <= 0:
                _nom_sp = max(
                    (cycle_s - float(self.BusPhaseDuration))
                    / max(len(self.UpFlowList) - 1, 1),
                    15.0)
            _nom_sp = max(float(_nom_sp), min_floor)
            _hr_sp  = max(0.0, min(_nom_sp - min_floor, _nom_sp * 0.50))
            headrooms.append(_hr_sp)
            total_hr += _hr_sp

        if total_hr < 0.5:
            return 0.0

        other_occ = self._estimated_other_vehicle_occupancy()
        penalty_pax_s = 0.0

        for _k_sp, _hr_sp in enumerate(headrooms):
            _i_sp = _k_sp + 1
            if _i_sp >= len(self.UpFlowList) or _hr_sp <= 0.0:
                continue
            # Mean upstream flow across detectors for this phase
            _flows = self.UpFlowList[_i_sp]
            _q_sp  = sum(float(v) for v in _flows) / max(len(_flows), 1)
            _vc_sp = _q_sp / sat_flow
            if _vc_sp <= vc_threshold:
                continue
            # Proportional trim for this phase
            _trim_sp      = min(_hr_sp, extra_time_s * (_hr_sp / total_hr))
            # Overflow vehicles that couldn't clear in the trimmed window
            _overflow_veh = _q_sp * _trim_sp / 3600.0
            # Linear ramp: penalty scales 0→1 from vc_threshold to threshold+0.15
            _scale        = min(1.0, (_vc_sp - vc_threshold) / 0.15)
            # Each overflow vehicle waits ~one additional cycle (conservative)
            penalty_pax_s += _overflow_veh * cycle_s * _scale * other_occ

        return penalty_pax_s

    def _compute_side_delay_penalty(self, extra_red, _suppress_log=False):
        extra_red = max(safe_float(extra_red), 0.0)
        if extra_red <= 0.0 or not hasattr(self, 'SideUpFlowList') or len(self.SideUpFlowList) == 0:
            return 0.0, 0.0

        side_other_delay = 0.0
        side_total_veh = 0.0
        w2_side = abs(ShockwaveSpeed2(
            self.SaturationFlow, self.SaturationDensity, self.JamDensity))
        if w2_side <= 1e-6:
            return 0.0, 0.0

        jam_density = max(safe_float(self.JamDensity), 0.0)
        sat_density = max(safe_float(self.SaturationDensity), 0.0)

        for idx in range(len(self.SideUpFlowList)):
            q_s = max(safe_float(self.SideUpFlowList[idx]), 0.0)
            if q_s < 1.0:
                continue

            k_s = min(max(safe_float(self.SideUpDenList[idx]), 0.0), jam_density)
            w1_s = abs(safe_float(self.SideShockwaveSpeed1[idx]))
            w3_s = abs(safe_float(self.SideShockwaveSpeed3[idx]))
            denom_s = w2_side - w1_s
            if denom_s <= 1e-6 or w3_s <= 1e-6:
                continue

            side_max_q = w2_side * w1_s * extra_red / denom_s
            if side_max_q <= 0.0:
                continue

            jam_term = max(jam_density - k_s, 0.0) / 1000.0
            sat_term = max(sat_density - k_s, 0.0) / 1000.0
            side_diss = side_max_q / w3_s
            side_delay_veh_s = (
                side_max_q * extra_red * 0.5 * jam_term
                + side_diss * side_max_q * 0.5 * sat_term)
            side_other_delay += side_delay_veh_s
            side_total_veh += q_s * extra_red / 3600.0

        # compute raw vehicle counts for each side section for the log
        _side_secs_log = self._get_side_sections()
        _side_nveh = []
        for _ss in _side_secs_log:
            try:
                _side_nveh.append(int(AKIVehStateGetNbVehiclesSection(_ss, False)))
            except Exception:
                _side_nveh.append(-1)
        # estimated queue lengths (max queue from shockwave model, converted to vehicles)
        _veh_len = max(self.VehLength, 1.0) + 2.0  # vehicle + gap
        _qlen_veh = [round(float(self.SideUpFlowList[_k]) * extra_red / 3600.0, 1)
                     for _k in range(len(self.SideUpFlowList))]
        if not _suppress_log:
            log_to_file(
                f"[SIDE_OBJ] inter={self.id} extra_red={extra_red:.2f} "
                f"side_secs={_side_secs_log} "
                f"n_veh={_side_nveh} "
                f"flow={[round(float(v),1) for v in self.SideUpFlowList]} "
                f"den={[round(float(v),2) for v in self.SideUpDenList]} "
                f"q_veh={_qlen_veh} "
                f"delay={side_other_delay:.2f} veh={side_total_veh:.2f}"
            )

        return side_other_delay, side_total_veh

    def _reset_harmony_work_arrays(self):
        for arr_name in (
            'BusDelay', 'OtherDelay', 'TotalVeh', 'HSMinQueueLength',
            'HSMaxQueueLength', 'HSMaxQueueLengthTime', 'HSQueueDissTime',
            'BusJoinQueueTime', 'BusStoplineTime', 'BusPhaseMinDuration'
        ):
            arr = getattr(self, arr_name, None)
            if arr is not None:
                arr.fill(0.0)

    @staticmethod
    def _safe_array_sum(arr):
        return float(np.nan_to_num(arr, nan=0.0, posinf=0.0, neginf=0.0).sum())

    def _finalize_objective_stats(self, bus_delay_total, other_delay_total,
                                  total_veh, avg_passenger_delay):
        bus_delay_total = max(safe_float(bus_delay_total), 0.0)
        other_delay_total = max(safe_float(other_delay_total), 0.0)
        total_veh = max(safe_float(total_veh), 0.0)
        avg_passenger_delay = max(safe_float(avg_passenger_delay), 0.0)
        return bus_delay_total, other_delay_total, total_veh, avg_passenger_delay

    def _estimated_other_vehicle_occupancy(self):
        inter_state = self._get_inter_state() or {}
        car_passages = max(safe_float(inter_state.get('car_veh_passages', 0.0)), 0.0)
        truck_passages = max(safe_float(inter_state.get('truck_veh_passages', 0.0)), 0.0)
        car_occ = max(safe_float(self.CarOcc), 0.0)
        truck_occ = max(safe_float(getattr(self, 'TruckOcc', self.CarOcc)), 0.0)
        total_other_passages = car_passages + truck_passages
        if total_other_passages <= 1e-6:
            return max(car_occ, 1e-6)
        total_other_pax_equiv = car_passages * car_occ + truck_passages * truck_occ
        return max(total_other_pax_equiv / total_other_passages, 1e-6)

    
    def _sample_side_sections(self, time):
        """
        Virtual detector for side sections using instantaneous density.

        Scans live vehicle count on each side section, converts to density
        via section length (AKIInfNetGetSectionANGInf), then derives flow
        from the LWR triangular model. No aggregation periods needed.
        """
        side_secs = self._get_side_sections()
        if not side_secs:
            return

        self._ensure_side_section_arrays(side_secs, time)

        _nveh_log = []
        _len_log  = []

        # Pre-compute main corridor flow as a turning-ratio reference for virtual sections.
        # Use the mean of non-zero values from UpFlowList (main approach detector readings).
        _main_flow_ref = 0.0
        try:
            _uf = np.asarray(self.UpFlowList, dtype=float).ravel()
            _uf_pos = _uf[_uf > 0.0]
            if _uf_pos.size > 0:
                _main_flow_ref = float(np.mean(_uf_pos))
        except Exception:
            pass

        for idx, sec_id in enumerate(side_secs):
            # Try vehicle state first (for physically simulated sections)
            _nveh_raw = int(AKIVehStateGetNbVehiclesSection(sec_id, False))
            _in_sim   = (_nveh_raw >= 0)
            n_veh     = _nveh_raw if _in_sim else 0

            # Resolve geometry — skip density computation if geometry is invalid.
            sec_len_m   = None
            n_lanes_sec = 1
            try:
                _sec_inf = AKIInfNetGetSectionANGInf(sec_id)
                if getattr(_sec_inf, 'report', -1) >= 0:
                    _raw_len = float(_sec_inf.length)
                    if _raw_len > 0.0:
                        sec_len_m   = _raw_len
                        n_lanes_sec = max(int(_sec_inf.nbCentralLanes) + int(_sec_inf.nbSideLanes), 1)
            except Exception:
                pass

            geom_valid = sec_len_m is not None and sec_len_m > 0.0

            if _in_sim and n_veh > 0 and geom_valid:
                # Section has physical vehicles — use density from vehicle count
                density_per_lane = n_veh / n_lanes_sec / max(sec_len_m / 1000.0, 0.001)
                k_sat  = max(float(self.SaturationDensity), 1.0)
                k_jam  = max(float(self.JamDensity),        k_sat + 1.0)
                k      = min(density_per_lane, k_jam)
                if k <= k_sat:
                    flow = k * self.SaturationFlow / k_sat
                else:
                    flow = self.SaturationFlow * (k_jam - k) / max(k_jam - k_sat, 1.0)
                density = k
            else:
                # Section not in dynamic simulation (-4002), empty, or geometry invalid.
                # Estimate arrival flow using section-level accumulated stats first,
                # then a turning-ratio from the main approach, then a small default.
                _est_flow = 0.0

                # Tier 1: section-specific cumulative stats (most accurate for virtual secs)
                try:
                    _sg = AKIEstGetGlobalStatisticsSection(sec_id, -1)
                    if getattr(_sg, 'report', -1) == 0 and float(getattr(_sg, 'count', 0) or 0) > 0 and time > 0:
                        _est_flow = float(_sg.count) / max(time / 3600.0, 1.0 / 3600.0)
                except Exception:
                    pass

                # Tier 2: recent partial stats (more up-to-date than global for longer runs)
                if _est_flow <= 0.0:
                    try:
                        _window = max(0.0, time - 300.0)  # last 5 min
                        _sp = AKIEstGetParcialStatisticsSection(sec_id, _window, -1)
                        if getattr(_sp, 'report', -1) == 0 and float(getattr(_sp, 'count', 0) or 0) > 0:
                            _est_flow = float(_sp.count) * 3600.0 / max(time - _window, 1.0)
                    except Exception:
                        pass

                # Tier 3: turning-ratio estimate from main approach flow.
                # Minor approaches typically carry 10-20% of the main corridor flow.
                if _est_flow <= 0.0 and _main_flow_ref > 0.0:
                    _est_flow = _main_flow_ref * 0.15

                # Tier 4: conservative default (low enough not to dominate delay)
                if _est_flow <= 0.0:
                    # Urban minor cross-street: 400 veh/h is a reasonable default
                    # (was 150, which severely underestimated side delay)
                    _est_flow = 400.0

                flow    = min(_est_flow, float(self.SaturationFlow))
                density = flow * float(self.SaturationDensity) / max(self.SaturationFlow, 1.0)

            self.SideUpFlowList[idx]      = flow
            self.SideUpDenList[idx]       = density
            self.SideShockwaveSpeed1[idx] = ShockwaveSpeed1(flow, self.JamDensity, density)
            self.SideShockwaveSpeed3[idx] = ShockwaveSpeed3(
                self.SaturationFlow, flow, self.SaturationDensity, density)
            _nveh_log.append(n_veh)
            _len_log.append(round(sec_len_m, 0) if sec_len_m is not None else 'N/A')

        # Throttle: only log every 60 s to avoid flooding the log file
        if not hasattr(self, '_side_scan_log_t'):
            self._side_scan_log_t = -999.0
        if time - self._side_scan_log_t >= 60.0:
            self._side_scan_log_t = time
            log_to_file(
                f"[SIDE_SCAN] inter={self.id} t={time:.0f} "
                f"secs={side_secs} "
                f"n_veh={_nveh_log} len_m={_len_log} "
                f"flow={[round(float(v),1) for v in self.SideUpFlowList]} "
                f"den={[round(float(v),2) for v in self.SideUpDenList]}"
            )
    
    def build_state(self):
        state = []
        for sec in self.incoming_sections:
            stat = AKIEstGetParcialStatisticsSection(
                sec, AKIGetCurrentSimulationTime(), 50)
            state.append(min(stat.count / 50.0, 1.0))

        bus_presence = 1.0 if np.any(self.BusPresence) else 0.0
        state.append(bus_presence)
        state.append(min(np.max(self.BusSpeed) / 20.0, 1.0) if bus_presence else 0.0)

        current_phase = ECIGetCurrentPhase(self.node_id)
        num_phases    = len(self.UpDetList)
        phase_one_hot = [0.0] * num_phases
        if 1 <= current_phase <= num_phases:
            phase_one_hot[current_phase - 1] = 1.0
        state.extend(phase_one_hot)

        start_time  = ECIGetStartingTimePhase(self.node_id)
        time_in_phase = AKIGetCurrentSimulationTime() - start_time
        state.append(min(time_in_phase / 60.0, 1.0))

        return np.array(state, dtype=np.float32)

    def collect_detector_data(self):
        """
        Update UpDetCountList from physical detectors where available.
        Also builds _det_sec_cache for the section-scan fallback used in
        update_queue_model when aggregated counts are still 0.
        """
        if not hasattr(self, '_prev_updet_counter'):
            self._prev_updet_counter = {}
        if not hasattr(self, '_det_sec_cache'):
            # Build once: {(i,j): (sec_id, sec_len_m)} for every valid detector
            self._det_sec_cache = {}
            for i in range(len(self.UpDetList)):
                for j, det_id in enumerate(self.UpDetList[i]):
                    props = AKIDetGetPropertiesDetectorById(det_id)
                    if props.report >= 0:
                        try:
                            sec_len = float(AKIInfNetGetSectionANGInf(props.IdSection).length)
                        except Exception:
                            sec_len = 50.0
                        self._det_sec_cache[(i, j)] = (props.IdSection, max(sec_len, 1.0))

        for i in range(len(self.UpDetList)):
            for j in range(len(self.UpDetList[i])):
                det_id = self.UpDetList[i][j]
                count = AKIDetGetCounterAggregatedbyId(det_id, 0)
                if count >= 0:
                    prev = self._prev_updet_counter.get(det_id)
                    if prev is None:
                        delta = max(count, 0)
                    elif count >= prev:
                        delta = count - prev
                    else:
                        delta = max(count, 0)
                    self._prev_updet_counter[det_id] = count
                    self.UpDetCountList[i][j] += delta

    def detect_bus_old(self, time):
        """
        Position-based continuous bus detection.

        Instead of polling whether a bus is physically over a detector at the
        exact 1-second tick, we scan ALL PT vehicles on call sections every
        step and compute their ETA to the stop line.  BusPresence[0][i] is
        set to 1 if any bus is within cycle_length seconds of arrival.
        BusSpeed[0][i] holds that bus's live speed in m/s.

        This eliminates missed detections caused by the 1-second sampling
        interval — a bus travelling at 50 km/h covers ~14 m per tick, so it
        can easily skip over a narrow detector zone.  Using live position data
        instead means we never miss it.
        """
        self.BusPresence[:] = 0
        self.BusSpeed[:]    = 0.0
        if not hasattr(self, '_bus_eta'):
            self._bus_eta = {}
        self._bus_eta.clear()
        self._detected_buses = []

        # Build det_sec_map: section_id -> [(det_index, det_distance_m, det_final_pos)]
        det_sec_map = {}
        for i, det_id in enumerate(self.BusDet):
            props = AKIDetGetPropertiesDetectorById(det_id)
            if props.report >= 0:
                sec = props.IdSection
                det_dist_group = self.config["DetDistance"][0]
                dist = det_dist_group[i] if i < len(det_dist_group) else 50.0
                det_sec_map.setdefault(sec, []).append((i, dist, props.FinalPosition))

        if not det_sec_map:
            # All physical detector IDs are invalid in this Aimsun model — fall back
            # to scanning incoming_sections directly with a default distance estimate.
            for sec_id in self.incoming_sections:
                try:
                    sec_len_m = float(AKIInfNetGetSectionANGInf(sec_id).length)
                except Exception:
                    sec_len_m = 50.0
                sec_len_m = max(sec_len_m, 1.0)
                det_sec_map[sec_id] = [(0, sec_len_m, sec_len_m)]

        if not det_sec_map:
            return

        lookahead = self.urtsp_cycle_length   # accept buses arriving within one cycle

        seen = set()

        def _record_detected_bus(det_idx, veh_id, speed_ms, remaining, eta):
            prev_eta = self._bus_eta.get(det_idx, (None, 1e9))[1]
            if self.BusPresence[0][det_idx] == 0 or eta < prev_eta:
                self.BusPresence[0][det_idx]    = 1
                self.BusSpeed[0][det_idx]       = speed_ms
                self.last_detected_bus_id       = veh_id
                self._bus_eta[det_idx]          = (veh_id, eta, remaining, speed_ms)
            self._detected_buses.append({
                'detector_index': det_idx,
                'vehicle_id': veh_id,
                'eta_s': eta,
                'remaining_m': remaining,
                'speed_mps': speed_ms,
            })

        # ── Primary: registered PT line vehicles ─────────────────────
        # Periodic diagnostic: every 5 min, log where ALL PT buses are so we
        # can confirm whether any ever reach the detector sections.
        _diag_pt_t = int(time) // 300
        _do_pt_diag = (_diag_pt_t != getattr(self, '_pt_diag_t', -1))
        if _do_pt_diag:
            self._pt_diag_t = _diag_pt_t
        _pt_on_det_sec = []   # (veh_id, section, eta)
        _pt_elsewhere  = []   # (veh_id, section)  — not on det_sec_map
        try:
            n_lines = AKIPTGetNumberLines()
            for li in range(n_lines):
                try:
                    line_id = AKIPTGetIdLine(li)
                    n_vehs  = AKIGetNbVehiclesFollowingPTLine(line_id)
                except Exception:
                    continue
                for vi in range(n_vehs):
                    try:
                        veh_id = AKIGetVehicleFollowingPTLine(line_id, vi)
                        if veh_id in seen:
                            continue
                        inf = AKIPTVehGetInf(veh_id)
                        if inf.report < 0:
                            continue
                        seen.add(veh_id)
                        if inf.idSection not in det_sec_map:
                            if _do_pt_diag:
                                _pt_elsewhere.append((veh_id, inf.idSection))
                            continue
                        speed_ms  = max(inf.CurrentSpeed / 3.6, 0.5)
                        for i, det_dist, det_fin in det_sec_map[inf.idSection]:
                            if inf.CurrentPos <= det_fin:
                                remaining = (det_fin - inf.CurrentPos) + det_dist
                            else:
                                remaining = max(0.0, det_dist - (inf.CurrentPos - det_fin))
                            eta = remaining / speed_ms
                            if _do_pt_diag:
                                _pt_on_det_sec.append((veh_id, inf.idSection, round(eta, 1)))
                            if eta <= lookahead:
                                _record_detected_bus(i, veh_id, speed_ms, remaining, eta)
                    except Exception:
                        continue
        except Exception:
            pass
        if _do_pt_diag:
            log_to_file(
                f"[PT_SCAN] inter={self.id} t={time:.0f} "
                f"det_sec_map_secs={list(det_sec_map.keys())} "
                f"on_det_secs={_pt_on_det_sec} "
                f"elsewhere(veh,sec)={_pt_elsewhere[:10]}"  # cap at 10
            )

        # ── Fallback: direct section scan for injected buses ─────────
        for sec, det_entries in det_sec_map.items():
            try:
                n = AKIVehStateGetNbVehiclesSection(sec, True)
                for vi in range(n):
                    inf = AKIVehStateGetVehicleInfSection(sec, vi)
                    if _do_pt_diag and inf.idVeh not in seen:
                        # Log every vehicle type found on detector sections
                        log_to_file(
                            f"[FALLBACK_SCAN] inter={self.id} t={time:.0f} "
                            f"sec={sec} veh={inf.idVeh} type={inf.type} "
                            f"bus_type_pos={self.bus_type_pos} "
                            f"pos={inf.CurrentPos:.1f} speed={inf.CurrentSpeed:.1f}"
                        )
                    if inf.idVeh in seen or inf.type != self.bus_type_pos:
                        continue
                    seen.add(inf.idVeh)
                    speed_ms  = max(inf.CurrentSpeed / 3.6, 0.5)
                    for i, det_dist, det_fin in det_entries:
                        if inf.CurrentPos <= det_fin:
                            remaining = (det_fin - inf.CurrentPos) + det_dist
                        else:
                            remaining = max(0.0, det_dist - (inf.CurrentPos - det_fin))
                        eta = remaining / speed_ms
                        if eta <= lookahead:
                            _record_detected_bus(i, inf.idVeh, speed_ms, remaining, eta)
            except Exception:
                continue
    
    
    def detect_bus_semi(self, time):
        """
        Production‑safe bus detection.

        ✔ Works with PT vehicles
        ✔ Works without detectors
        ✔ Works if bus type inference changes
        ✔ Cannot throw NameError
        """

        # Reset presence arrays
        self.BusPresence[:] = 0
        self.BusSpeed[:]    = 0.0
        self.last_detected_bus_id = -1

        # Always define this
        bus_found = False

        # ─────────────────────────────────────────────
        # 1️⃣ Primary: PT line vehicles
        # ─────────────────────────────────────────────
        try:
            n_lines = AKIPTGetNumberLines()
        except Exception:
            n_lines = 0

        for li in range(n_lines):
            try:
                line_id = AKIPTGetIdLine(li)
                n_vehs  = AKIGetNbVehiclesFollowingPTLine(line_id)
            except Exception:
                continue

            for vi in range(n_vehs):
                try:
                    veh_id = AKIGetVehicleFollowingPTLine(line_id, vi)
                    inf    = AKIPTVehGetInf(veh_id)

                    if inf.report < 0:
                        continue

                    if inf.idSection in self.incoming_sections:
                        self.BusPresence[0][0] = 1
                        self.BusSpeed[0][0]    = max(inf.CurrentSpeed / 3.6, 0.5)
                        self.last_detected_bus_id = veh_id
                        bus_found = True
                        break

                except Exception:
                    continue

            if bus_found:
                break

        # ─────────────────────────────────────────────
        # 2️⃣ Fallback: direct section scan
        # ─────────────────────────────────────────────
        if not bus_found:

            for sec in self.incoming_sections:
                try:
                    n = AKIVehStateGetNbVehiclesSection(sec, True)

                    for i in range(n):
                        inf = AKIVehStateGetVehicleInfSection(sec, i)

                        if inf.type == self.bus_type_pos:
                            self.BusPresence[0][0] = 1
                            self.BusSpeed[0][0]    = max(inf.CurrentSpeed / 3.6, 0.5)
                            self.last_detected_bus_id = inf.idVeh
                            bus_found = True
                            break

                    if bus_found:
                        break

                except Exception:
                    continue
    
    def _get_junction_xy(self):
        """
        Return the X,Y centroid of this junction.  Tries several coordinate
        field name variants used across Aimsun versions:
          Aimsun 22/26: xSection/ySection (centroid) or xSectionTo/ySectionTo
          Older builds:  xcoordTo/ycoordTo
        Falls back to turn-origin sections from the junction topology if
        incoming_sections are all transit links (report<0).
        Result is cached only on success — retries every call until resolved.
        """
        if getattr(self, '_junction_xy', None) is not None:
            return self._junction_xy   # already resolved — fast path

        xs, ys = [], []

        # First try incoming_sections (detector-based approach sections)
        for sec_id in self.incoming_sections:
            try:
                si = AKIInfNetGetSectionANGInf(sec_id)
                if si.report >= 0:
                    _xy = _extract_xy_from_section_info(si)
                    if _xy is not None:
                        xs.append(_xy[0])
                        ys.append(_xy[1])
            except Exception:
                pass

        # If that yielded nothing, try all turn-origin sections at the junction
        if not xs:
            try:
                n_turns = AKIInfNetGetNbTurnsInNode(self.node_id)
                for ti in range(max(n_turns, 0)):
                    try:
                        sec_id = AKIInfNetGetOriginSectionInTurn(self.node_id, ti)
                        if sec_id <= 0:
                            continue
                        si = AKIInfNetGetSectionANGInf(sec_id)
                        if si.report >= 0:
                            _xy = _extract_xy_from_section_info(si)
                            if _xy is not None:
                                xs.append(_xy[0])
                                ys.append(_xy[1])
                    except Exception:
                        pass
            except Exception:
                pass

        if xs:
            self._junction_xy = (sum(xs) / len(xs), sum(ys) / len(ys))
            if LOG_JUNC_XY:
                log_to_file(
                    f"[JUNC_XY] inter={self.id} resolved={self._junction_xy} "
                    f"from {len(xs)} sections"
                )
            return self._junction_xy

        _model_xy = _resolve_junction_xy_from_model(self.node_id, self.incoming_sections)
        if _model_xy is not None:
            self._junction_xy = _model_xy
            log_to_file(
                f"[JUNC_XY] IC inter={self.id} resolved via model "
                f"-> ({_model_xy[0]:.1f}, {_model_xy[1]:.1f})"
            )
            return self._junction_xy

        # Still nothing — log once (always, regardless of flag) to help diagnose
        if not getattr(self, '_junc_xy_warn_logged', False):
            self._junc_xy_warn_logged = True
            try:
                si = AKIInfNetGetSectionANGInf(self.incoming_sections[0])
                fields = {k: getattr(si, k, '?') for k in dir(si) if not k.startswith('_')}
            except Exception:
                fields = {}
            log_to_file(
                f"[JUNC_XY_FAIL] inter={self.id} cannot resolve junction coordinates. "
                f"incoming_sections={self.incoming_sections} "
                f"section_ANGInf_fields={fields}"
            )
        return None

    def detect_bus(self, time):
        """
        Coordinate-distance bus detection — robust against transit links.

        PT buses in Aimsun travel through transit-link sections whose IDs return
        report<0 from AKIInfNetGetSectionANGInf (no topology info).  Section-based
        detection therefore never fires.  Instead we:

        1. Get the junction centroid X,Y from the 'to' coordinates of approach sections.
        2. For every active PT line vehicle, compute Euclidean distance to the junction.
        3. If distance <= detection_radius_m and type==bus_type_pos → detect.
        4. Fallback: direct section scan on incoming_sections for type==bus_type_pos.

        Periodic [PT_SCAN] log (every 5 min) shows all PT vehicles, their coordinates,
        and distances so we can verify the radius is appropriate.
        """

        self.BusPresence[:] = 0
        self.BusSpeed[:]    = 0.0
        self.last_detected_bus_id = -1
        if isinstance(getattr(self, '_bus_eta', None), dict):
            self._bus_eta.clear()
        else:
            self._bus_eta = {}

        # Detection radius: ~1 cycle length at 50 km/h ≈ 1875 m, capped at 500 m to
        # avoid false positives from buses at nearby parallel intersections.
        detection_radius_m = min(self.urtsp_cycle_length * 14.0, 500.0)

        # Junction centroid (cached after first call)
        junc_xy = self._get_junction_xy()

        # Periodic diagnostic throttle: every 5 minutes — only when LOG_PT_SCAN=True
        _diag_t = int(time) // 300
        _do_diag = LOG_PT_SCAN and (_diag_t != getattr(self, '_db_diag_t', -1))
        if _do_diag:
            self._db_diag_t = _diag_t
        _pt_info = []   # (veh_id, dist_m, speed) for diagnostic

        seen = set()
        jx = jy = None
        if junc_xy is not None:
            jx, jy = junc_xy
        _bus_type_is_provisional = bool(globals().get('_bus_type_provisional', False))

        _prev_presence = int(self.BusPresence[0][0]) if len(self.BusPresence[0]) else 0

        def _hit(veh_id, speed_kph, hit_x=None, hit_y=None):
            speed_ms = max(speed_kph / 3.6, 0.5)
            if jx is not None and hit_x is not None and _jct_xy_cache:
                try:
                    _self_dist = math.sqrt((float(hit_x) - jx) ** 2 + (float(hit_y) - jy) ** 2)
                    _nearest_jid, _nearest_dist = min(
                        (
                            (int(_jid), math.sqrt((float(hit_x) - float(_xy[0])) ** 2 + (float(hit_y) - float(_xy[1])) ** 2))
                            for _jid, _xy in _jct_xy_cache.items()
                            if _xy is not None and len(_xy) >= 2
                        ),
                        key=lambda _item: _item[1],
                    )
                    # Only let the nearest junction claim the live IC-detect.
                    # This suppresses overlapping-junction artefacts where one
                    # bus position creates simultaneous detections several
                    # hundred metres upstream of multiple intersections.
                    if _nearest_jid != self.id and (_self_dist - _nearest_dist) > 25.0:
                        return
                except Exception:
                    pass
            # Compute ETA BEFORE setting presence so a far bus never enters
            # the strategy path.  Geographic distance to the junction centroid
            # over-estimates travel distance around corners, so allow 30 %
            # headroom above MAX_STRATEGY_ETA_S.
            if not isinstance(getattr(self, '_bus_eta', None), dict):
                self._bus_eta = {}
            if jx is not None and hit_x is not None:
                _dist_m = ((float(hit_x) - jx) ** 2 + (float(hit_y) - jy) ** 2) ** 0.5
            else:
                _dist_m = float(self.config.get("DetDistance", [[50.0]])[0][0])
            _eta_s = _dist_m / speed_ms

            _mx = hit_x if hit_x is not None else (jx if jx is not None else 0.0)
            _my = hit_y if hit_y is not None else (jy if jy is not None else 0.0)

            if _eta_s > MAX_STRATEGY_ETA_S * 1.3:
                # Bus is in the zone but too far for any strategy.
                # Still record detection in stats and log file so the
                # shockwave dashboard shows it — but do NOT arm TSP.
                try:
                    self.stats.record_pt_bus_detection(self.id, veh_id, time)
                except Exception:
                    pass
                _mark_detection_point(self.id, veh_id, _mx, _my, time,
                                      "IC-detect-far",
                                      {"prearm_note": f"eta_too_far={_eta_s:.0f}s"})
                return  # do NOT set BusPresence / BusSpeed

            # Bus is close enough — arm TSP state.
            self.BusPresence[0][0]    = 1
            self.BusSpeed[0][0]       = speed_ms
            self.last_detected_bus_id = veh_id
            self._bus_eta[0] = (veh_id, _eta_s, _dist_m, speed_ms)
            # Update headway σ when a new (or returning) bus enters the zone.
            if veh_id != self._hw_last_veh_id:
                self._hw_update_sigma(veh_id, time)
            # Record the bus passage in stats (works for transit-link buses that
            # never appear on regular approach sections)
            try:
                self.stats.record_pt_bus_detection(self.id, veh_id, time)
            except Exception:
                pass
            # Detection-point marker
            _mark_detection_point(self.id, veh_id, _mx, _my, time, "IC-detect")

        # ── Tier 0: position-tracker zone-presence supplement ───────────────
        # _track_all_bus_positions maintains _tracking_zone_presence with buses
        # confirmed inside this junction's detection zone at the last 5-second
        # interval.  Buses on transit-link sections (report<0) won't appear in
        # the PT API scan below, so this Tier 0 fills that gap.
        for _tz_vid, (_tz_bx, _tz_by, _tz_spd) in list(
                _tracking_zone_presence.get(self.id, {}).items()):
            if _tz_vid not in seen:
                seen.add(_tz_vid)
                _hit(_tz_vid, _tz_spd, _tz_bx, _tz_by)

        # ── Tier 1: PT line vehicle scan ────────────────────────────────────
        # Always runs regardless of whether junction coordinates are available.
        # When coordinates are known: accept buses within detection_radius_m.
        # When coordinates are unknown: accept buses on any incoming_section
        #   OR any bus whose section leads directly to this junction (idNodeTo).
        try:
            n_lines = AKIPTGetNumberLines()
        except Exception:
            n_lines = 0

        for li in range(n_lines):
            try:
                line_id = AKIPTGetIdLine(li)
                n_vehs  = AKIGetNbVehiclesFollowingPTLine(line_id)
            except Exception:
                continue
            for vi in range(n_vehs):
                try:
                    veh_id = AKIGetVehicleFollowingPTLine(line_id, vi)
                    if veh_id in seen:
                        continue
                    inf = AKIPTVehGetInf(veh_id)
                    if inf.report < 0:
                        continue
                    seen.add(veh_id)
                    if self.bus_type_pos > 0 and not _bus_type_is_provisional and inf.type != self.bus_type_pos:
                        continue

                    if jx is not None:
                        # Primary path: coordinate distance
                        dx   = float(inf.xCurrentPos) - jx
                        dy   = float(inf.yCurrentPos) - jy
                        dist = (dx * dx + dy * dy) ** 0.5
                        if _do_diag:
                            _pt_info.append(
                                f"v={veh_id} d={dist:.0f}m "
                                f"spd={inf.CurrentSpeed:.0f}kph "
                                f"sec={inf.idSection}"
                            )
                        if dist <= detection_radius_m:
                            _hit(veh_id, inf.CurrentSpeed,
                                 float(inf.xCurrentPos), float(inf.yCurrentPos))
                    else:
                        # Fallback path — coordinates not yet available.
                        # Build/use a cached set of all sections that feed into
                        # this junction (turn-origin sections from topology).
                        if not hasattr(self, '_turn_origin_secs'):
                            _tos = set(self.incoming_sections)
                            try:
                                _nt = AKIInfNetGetNbTurnsInNode(self.node_id)
                                for _ti in range(max(_nt, 0)):
                                    try:
                                        _ts = AKIInfNetGetOriginSectionInTurn(self.node_id, _ti)
                                        if _ts > 0:
                                            _tos.add(_ts)
                                    except Exception:
                                        pass
                            except Exception:
                                pass
                            self._turn_origin_secs = _tos

                        sec_id = inf.idSection
                        matched = sec_id in self._turn_origin_secs
                        if not matched:
                            try:
                                si = AKIInfNetGetSectionANGInf(sec_id)
                                if si.report >= 0 and si.idNodeTo == self.node_id:
                                    matched = True
                            except Exception:
                                pass
                        if _do_diag:
                            _pt_info.append(
                                f"v={veh_id} sec={sec_id} "
                                f"spd={inf.CurrentSpeed:.0f}kph "
                                f"matched={matched}"
                            )
                        if matched:
                            _hit(veh_id, inf.CurrentSpeed,
                                 float(getattr(inf, 'xCurrentPos', 0.0)),
                                 float(getattr(inf, 'yCurrentPos', 0.0)))
                except Exception:
                    continue

        # ── Tier 2: direct section scan on approach sections ────────────────
        if not any(self.BusPresence[0]):
            for sec_id in self.incoming_sections:
                try:
                    n = AKIVehStateGetNbVehiclesSection(sec_id, True)
                    for vi in range(n):
                        inf = AKIVehStateGetVehicleInfSection(sec_id, vi)
                        if inf.idVeh in seen:
                            continue
                        if self.bus_type_pos <= 0 or _bus_type_is_provisional or inf.type == self.bus_type_pos:
                            _hit(inf.idVeh, inf.CurrentSpeed)
                            break
                except Exception:
                    continue
                if any(self.BusPresence[0]):
                    break

        # ── Periodic diagnostic ─────────────────────────────────────────────
        if _do_diag:
            log_to_file(
                f"[PT_SCAN] inter={self.id} t={time:.0f} "
                f"junc_xy={junc_xy} radius={detection_radius_m:.0f}m "
                f"n_lines={n_lines} bus_type_pos={self.bus_type_pos} "
                f"turn_origin_secs={sorted(getattr(self,'_turn_origin_secs',set()))} "
                f"BusPresence={self.BusPresence[0][0]} "
                f"all_type3_buses=[{'; '.join(_pt_info)}]"
            )
    def _populate_flow_from_sections(self, time):
        """
        Populate UpFlowList / UpDenList for the current red phase from live
        vehicle counts on main approach sections when no physical UpDetList
        detectors are configured.

        Called by update_queue_model() once per cycle step when UpDetList is empty.
        Uses incoming_sections (N-S corridor approaches) and the same LWR
        triangular model used by _sample_side_sections.
        """
        if not self.incoming_sections:
            return
        if len(self.UpFlowList) == 0:
            return

        # Only use sections with valid geometry and length >= MIN_APPROACH_LEN_M
        MIN_APPROACH_LEN_M = 20.0
        _max_flow = max(self.SaturationFlow * 1.5, 3600.0)
        k_sat  = max(float(self.SaturationDensity), 1.0)
        k_jam  = max(float(self.JamDensity), k_sat + 1.0)
        q_sat  = max(float(self.SaturationFlow), 1.0)

        flow_samples  = []
        n_lanes_total = 0

        for sec_id in self.incoming_sections:
            try:
                _si = AKIInfNetGetSectionANGInf(int(sec_id))
                if getattr(_si, 'report', -1) < 0:
                    continue
                sec_len_m = float(getattr(_si, 'length', 0.0) or 0.0)
                if sec_len_m < MIN_APPROACH_LEN_M:
                    continue
                n_lanes = max(
                    int(getattr(_si, 'nbCentralLanes', 0)) + int(getattr(_si, 'nbSideLanes', 0)), 1)
            except Exception:
                continue

            try:
                n_veh = max(int(AKIVehStateGetNbVehiclesSection(sec_id, False)), 0)
            except Exception:
                n_veh = 0

            sec_len_km = sec_len_m / 1000.0
            density_per_lane = n_veh / n_lanes / max(sec_len_km, 0.001)
            k = min(density_per_lane, k_jam)
            if k <= k_sat:
                _flow = k * q_sat / k_sat
            else:
                _flow = q_sat * (k_jam - k) / max(k_jam - k_sat, 1.0)
            _flow = min(max(_flow, 0.0), _max_flow)
            # Weight by lane count so multi-lane sections dominate
            flow_samples.extend([_flow] * n_lanes)
            n_lanes_total += n_lanes

        if not flow_samples:
            return

        mean_flow = float(np.mean(flow_samples))
        mean_den  = mean_flow * k_sat / q_sat

        # Broadcast to all phase/lane slots in UpFlowList.
        # Write unconditionally — the RedDurationList guard was intended to avoid
        # writing during green phases, but RedDurationList is only updated AFTER
        # this function returns (later in update_queue_model), so on the first
        # call it is all-zeros and the guard always prevents writing.
        for i in range(len(self.UpFlowList)):
            for j in range(len(self.UpFlowList[i])):
                self.UpFlowList[i][j] = mean_flow
                self.UpDenList[i][j]  = mean_den

    def update_queue_model(self, time):
        det_sec_cache = getattr(self, '_det_sec_cache', {})
        # Maximum plausible approach flow: 1.5× saturation (handles multi-turn aggregation)
        _max_flow = max(self.SaturationFlow * 1.5, 3600.0)

        # Always pre-populate UpFlowList from live section vehicle counts.
        # Detector counts (where available and non-zero) override these values
        # in the loop below — but this ensures approach flow is never 0 simply
        # because a detector returned a zero count during a green phase.
        _has_det = any(d > 0 for row in self.UpDetList for d in row)
        self._populate_flow_from_sections(time)

        for i in range(len(self.UpDetList)):
            for j in range(len(self.UpDetList[i])):
                red_duration = time - self.RedStartTimeList[i][j]
                if red_duration > 0:
                    self.RedDurationList[i][j] = red_duration
                    # Clamp red_duration to at least 5 s before converting count→flow
                    # to prevent explosion when the sim first enters red on the last step.
                    _red_dur_clamped = max(red_duration, 5.0)

                    if self.UpDetCountList[i][j] > 0:
                        # Preferred: aggregated detector count → flow rate
                        flow = self.UpDetCountList[i][j] * 3600.0 / _red_dur_clamped
                        # Safety cap: never exceed 1.5× saturation flow
                        flow = min(flow, _max_flow)
                    else:
                        # Fallback: instantaneous density from live vehicle scan
                        sec_info = det_sec_cache.get((i, j))
                        if sec_info is not None:
                            sec_id, sec_len_m = sec_info
                            try:
                                n_veh = max(int(AKIVehStateGetNbVehiclesSection(sec_id, False)), 0)
                            except Exception:
                                n_veh = 0
                            try:
                                _sec_inf = AKIInfNetGetSectionANGInf(sec_id)
                                n_lanes_sec = max(
                                    int(getattr(_sec_inf, 'nbCentralLanes', 0))
                                    + int(getattr(_sec_inf, 'nbSideLanes', 0)), 1)
                            except Exception:
                                n_lanes_sec = max(self.NumberOfLanes, 1)
                            density_per_lane = n_veh / n_lanes_sec / max(sec_len_m / 1000.0, 0.001)
                            # Cap at 90% SatDen so shockwave denominator stays non-zero
                            density_fallback = min(density_per_lane, self.SaturationDensity * 0.9)
                            flow = density_fallback * self.SaturationFlow / max(self.SaturationDensity, 1.0)
                        else:
                            # No detector count and no detector-section cache entry.
                            # _populate_flow_from_sections() ran unconditionally above
                            # and may have set a section-scan estimate — keep it.
                            flow = self.UpFlowList[i][j] if self.UpFlowList[i][j] > 0 else 0.0

                    self.UpFlowList[i][j] = flow
                    # LWR: k = q / v_f = q * k_sat / q_sat  (v_f = q_sat/k_sat)
                    self.UpDenList[i][j] = (
                        flow * self.SaturationDensity / self.SaturationFlow
                        if self.SaturationFlow > 0 else 0.0)

                    self.ShockwaveSpeed1List[i][j] = ShockwaveSpeed1(
                        self.UpFlowList[i][j], self.JamDensity, self.UpDenList[i][j])
                    self.ShockwaveSpeed2List[i][j] = ShockwaveSpeed2(
                        self.SaturationFlow, self.SaturationDensity, self.JamDensity)
                    self.ShockwaveSpeed3List[i][j] = ShockwaveSpeed3(
                        self.SaturationFlow, self.UpFlowList[i][j],
                        self.SaturationDensity, self.UpDenList[i][j])
                    self.ShockwaveSpeed4List[i][j] = ShockwaveSpeed4(
                        self.SaturationFlow, self.JamDensity, self.SaturationDensity)

                    w1 = self.ShockwaveSpeed1List[i][j]
                    w2 = self.ShockwaveSpeed2List[i][j]
                    w3 = self.ShockwaveSpeed3List[i][j]
                    w4 = self.ShockwaveSpeed4List[i][j]
                    denom = abs(w2) - abs(w1)
                    if abs(denom) < 1e-6:
                        continue

                    # Cap red_duration for queue-length computation to one cycle.
                    # RedStartTimeList is initialised to 0; uninitialised slots
                    # therefore have red_duration ≈ sim_time (hundreds–thousands of
                    # seconds), which causes MaxQueueLength to inflate proportionally
                    # (e.g. |w2×w1×1879s| = 4000m+).  A real red phase in a fixed-
                    # cycle controller cannot exceed cycle_s, so any larger value is
                    # stale or unset and must be clamped.
                    _cycle_s_q = float(self.config.get('CycleTime', 135))
                    _rd_q = min(red_duration, _cycle_s_q)
                    self.MaxQueueLength[i][j]     = abs(w2 * w1 * _rd_q / denom)
                    self.MaxQueueLengthTime[i][j] = (
                        self.RedStartTimeList[i][j] + abs(w2) * _rd_q / denom)

                    if abs(w3) > 1e-6:
                        self.QueueDissTime[i][j] = (
                            self.MaxQueueLengthTime[i][j]
                            + self.MaxQueueLength[i][j] / abs(w3))
                    else:
                        self.QueueDissTime[i][j] = self.MaxQueueLengthTime[i][j]

                    # Residual queue for next cycle
                    nrs = self.NextRedStartTime[i][j]
                    if self.QueueDissTime[i][j] > nrs and abs(w3) > 1e-6 and abs(w4) > 1e-6:
                        self.MinQueueLength[i][j] = (
                            (self.MaxQueueLength[i][j] / abs(w3)
                             + self.MaxQueueLengthTime[i][j] - nrs)
                            / (1.0 / abs(w3) + 1.0 / abs(w4)))
                        self.MinQueueLengthTime[i][j] = (
                            nrs + self.MinQueueLength[i][j] / abs(w4))
                    else:
                        self.MinQueueLength[i][j]     = 0.0
                        self.MinQueueLengthTime[i][j] = 0.0

        # When UpDetList is empty the loop above never fires, so ShockwaveSpeed1List
        # and MaxQueueLength are never computed even though UpFlowList is now
        # populated by _populate_flow_from_sections.  Compute them here.
        if not self.UpDetList:
            _max_rd = 2.0 * float(self.config.get('CycleTime', 135))
            for i in range(len(self.UpFlowList)):
                for j in range(len(self.UpFlowList[i])):
                    q = self.UpFlowList[i][j]
                    k = self.UpDenList[i][j]
                    if q <= 0:
                        continue
                    # Only use RedStartTimeList if it was actually set at a phase
                    # transition (> 0).  If still 0 (uninitialised), compute a
                    # proxy red duration from the current signal phase timing.
                    _rst = self.RedStartTimeList[i][j]
                    if _rst > 0:
                        red_dur = min(time - _rst, _max_rd)
                    else:
                        # Estimate from phase timing if available; else skip.
                        try:
                            _cp = ECIGetCurrentPhase(self.node_id)
                            _ps = ECIGetStartingTimePhase(self.node_id)
                            red_dur = min(max(time - _ps, 0.0), _max_rd)
                        except Exception:
                            red_dur = 0.0
                    if red_dur > 0:
                        self.RedDurationList[i][j] = red_dur
                    self.ShockwaveSpeed1List[i][j] = ShockwaveSpeed1(q, self.JamDensity, k)
                    self.ShockwaveSpeed2List[i][j] = ShockwaveSpeed2(
                        self.SaturationFlow, self.SaturationDensity, self.JamDensity)
                    self.ShockwaveSpeed3List[i][j] = ShockwaveSpeed3(
                        self.SaturationFlow, q, self.SaturationDensity, k)
                    self.ShockwaveSpeed4List[i][j] = ShockwaveSpeed4(
                        self.SaturationFlow, self.JamDensity, self.SaturationDensity)
                    w1 = self.ShockwaveSpeed1List[i][j]
                    w2 = self.ShockwaveSpeed2List[i][j]
                    w3 = self.ShockwaveSpeed3List[i][j]
                    w4 = self.ShockwaveSpeed4List[i][j]
                    denom = abs(w2) - abs(w1)
                    if abs(denom) < 1e-6:
                        continue
                    rd = self.RedDurationList[i][j]
                    self.MaxQueueLength[i][j]     = abs(w2 * w1 * rd / denom)
                    self.MaxQueueLengthTime[i][j] = (
                        self.RedStartTimeList[i][j] + abs(w2) * rd / denom)
                    if abs(w3) > 1e-6:
                        self.QueueDissTime[i][j] = (
                            self.MaxQueueLengthTime[i][j]
                            + self.MaxQueueLength[i][j] / abs(w3))
                    else:
                        self.QueueDissTime[i][j] = self.MaxQueueLengthTime[i][j]
                    nrs = self.NextRedStartTime[i][j]
                    if self.QueueDissTime[i][j] > nrs and abs(w3) > 1e-6 and abs(w4) > 1e-6:
                        self.MinQueueLength[i][j] = (
                            (self.MaxQueueLength[i][j] / abs(w3)
                             + self.MaxQueueLengthTime[i][j] - nrs)
                            / (1.0 / abs(w3) + 1.0 / abs(w4)))
                    else:
                        self.MinQueueLength[i][j] = 0.0

        # Refresh virtual side-section detector data for use in GE/BP objectives.
        self._sample_side_sections(time)

    def highlight_bus(self, veh_id):
        strategy_name = {1: "GREEN EXTENSION", 2: "PHASE INSERTION"}.get(self.TSPStrategy, "UNKNOWN")
        if LOG_TSP_EVT: AKIPrintString(f"[TSP EVENT] ▶ START | {strategy_name} | veh={veh_id} | inter={self.id}")

    def reset_bus_color(self, veh_id):
        if LOG_TSP_EVT: AKIPrintString(f"[TSP EVENT] ■ END   | veh={veh_id} | inter={self.id}")

    def enforce_starvation_protection(self, time, timeSta, acycle):
        MAX_RED       = 1200000
        current_phase = ECIGetCurrentPhase(self.node_id)
        for phase_id in self.phase_list:
            if phase_id == current_phase or phase_id not in self.PhaseIndex:
                continue
            phase_index = self.PhaseIndex[phase_id]
            red_time    = time - self.RedStartTimeList[phase_index][0]
            if red_time > MAX_RED:
                _vprint(f"STARVATION: phase {phase_id} red for {red_time:.0f}s")
                ECIChangeDirectPhase(self.node_id, phase_id, timeSta, time, acycle, 0)
                return

    def apply_action(self, action, timeSta, time, acycle):
        current_phase = ECIGetCurrentPhase(self.node_id)
        start         = ECIGetStartingTimePhase(self.node_id)
        time_in_phase = time - start
        MIN_GREEN     = 5
        MAX_GREEN     = 60
        if time_in_phase < MIN_GREEN:
            return
        if time_in_phase >= MAX_GREEN:
            next_phase = (current_phase % len(self.phase_list)) + 1
            _vprint(f"MAX_GREEN override → phase {next_phase}")
            ECIChangeDirectPhase(self.node_id, next_phase, timeSta, time, acycle, 0)
            return
        if action < len(self.phase_list):
            target_phase = self.phase_list[action]
            if target_phase != current_phase:
                ECIChangeDirectPhase(self.node_id, target_phase, timeSta, time, acycle, 0)

    def run_rl(self, time, timeSta, acycle):
        state  = self.build_state()
        action = self.rl_agent.select_action(state)
        self.apply_action(action, timeSta, time, acycle)
        reward = -self.step_delay
        self.prev_total_delay = self.step_delay
        next_state = self.build_state()
        if self.TRAIN_MODE:
            self.rl_agent.update(reward, next_state, done=False)

    # ──────────────────────────────────────────────────────────────────────────
    # REWARD_TSP — action-reward based TSP using delay cost-benefit analysis
    # ──────────────────────────────────────────────────────────────────────────
    # Inspired by the MDP framework in Helmstedt & Possingham (2017):
    #   V(s,t) = max_a [ R(s,a) + Σ T_a(s,s')·V(s',t+1) ]
    #
    # Here we use a myopic (one-step lookahead) version:
    #   best_action = argmax_a R(s,a)
    # where R(s,a) = -α·ΔD_bus(a) - β·ΔD_other(a) - γ·ΔD_side(a)
    #
    # Actions evaluated:
    #   NO_ACTION  — do nothing; bus waits for natural green
    #   GE_k       — extend current green by k seconds (if bus phase is active)
    #   INS        — insert bus phase immediately (if bus phase is not active)
    # ──────────────────────────────────────────────────────────────────────────

    def _reward_estimate_no_action(self, time, timeSta, bus_eta_s):
        """Estimate bus delay if no TSP action is taken."""
        cycle = float(self.config.get('CycleTime', 135))
        # Worst-case delay a bus can ever face is one full red phase = cycle - BusPhaseDuration.
        # Use this as a cap so far-away buses (eta >> cycle) don't inflate the estimate.
        _max_delay = max(cycle - float(self.BusPhaseDuration), 0.0)

        current_phase = ECIGetCurrentPhase(self.node_id)
        if current_phase == self.BusPhase:
            # Bus phase is active — how much time remains?
            _ps = ECIGetStartingTimePhase(self.node_id)
            _pd = GetPhaseDuration(self.node_id, current_phase, timeSta)
            _remain = max(0.0, _pd - (time - _ps))
            if bus_eta_s <= _remain:
                return 0.0  # bus makes the natural green
            # Bus misses this green by _miss_by seconds.
            # Next bus green starts at (_remain + _max_delay) from now.
            # Bus arrives at bus_eta_s from now.
            # Actual wait = max(0, next_bus_green_start - bus_arrival)
            #             = max(0, (_remain + _max_delay) - bus_eta_s)
            #             = max(0, _max_delay - (bus_eta_s - _remain))
            _miss_by = bus_eta_s - _remain
            return max(0.0, _max_delay - _miss_by)
        else:
            # Compute time until next BusPhase green
            _ps_now = ECIGetStartingTimePhase(self.node_id)
            _elapsed = max(0.0, time - _ps_now)
            _rem_cur = max(0.0,
                GetPhaseDuration(self.node_id, current_phase, timeSta) - _elapsed)
            _time_to_bp = _rem_cur
            try:
                _ci = self.phase_list.index(current_phase)
                _bi = self.phase_list.index(self.BusPhase)
                _n  = len(self.phase_list)
                _steps = (_bi - _ci) % _n
                for _k in range(1, _steps):
                    _ph = self.phase_list[(_ci + _k) % _n]
                    _time_to_bp += GetPhaseDuration(self.node_id, _ph, timeSta)
            except Exception:
                _time_to_bp = cycle
            if bus_eta_s <= _time_to_bp + self.BusPhaseDuration:
                return max(0.0, _time_to_bp - bus_eta_s)
            # Bus misses the next natural green — cap at one full red wait
            return min(_max_delay, max(0.0, _time_to_bp + cycle - bus_eta_s))

    def _reward_objective_snapshot(self, extra_side_red: float = 0.0):
        """
        Snapshot the current objective arrays in passenger-delay units.

        This lets REWARD_TSP compare actions using the same occupancy-weighted
        delay logic as the harmony objective functions.
        """
        other_occ = self._estimated_other_vehicle_occupancy()
        bus_delay_s = max(self._safe_array_sum(self.BusDelay), 0.0)
        other_delay_s = max(self._safe_array_sum(self.OtherDelay), 0.0)
        side_delay_s = 0.0
        side_total_veh = 0.0
        if extra_side_red > 1e-6:
            try:
                side_delay_s, side_total_veh = self._compute_side_delay_penalty(extra_side_red)
            except Exception:
                side_delay_s = 0.0
                side_total_veh = 0.0
        side_delay_s = max(safe_float(side_delay_s), 0.0)
        bus_occ = max(safe_float(self.BusOcc), 0.0)
        total_veh = self._safe_array_sum(self.TotalVeh) + safe_float(side_total_veh)
        total_pax_delay = bus_delay_s * bus_occ + other_delay_s * other_occ + side_delay_s * other_occ
        return {
            "bus_delay_s": bus_delay_s,
            "other_delay_s": other_delay_s,
            "side_delay_s": side_delay_s,
            "bus_delay_pax_s": bus_delay_s * bus_occ,
            "other_delay_pax_s": other_delay_s * other_occ,
            "side_delay_pax_s": side_delay_s * other_occ,
            "total_veh": max(safe_float(total_veh), 0.0),
            "total_pax_delay": max(safe_float(total_pax_delay), 0.0),
        }

    def _reward_priority_budget_penalty(self, action_s: float, time: float) -> float:
        """
        Return a penalty (pax-s) proportional to how far the per-junction
        priority usage rate exceeds the budget cap.

        Budget: at most REWARD_PRIORITY_BUDGET_S seconds of GE+INS per
        simulated hour (default 900 s/hr = 15 s/min).  Once the running
        rate exceeds the cap the penalty grows linearly with the excess,
        making the reward function progressively reluctant to grant more.
        """
        if not REWARD_PRIORITY_BUDGET_S or action_s <= 0.0:
            return 0.0
        try:
            used_s  = float(getattr(self, '_priority_used_s', 0.0))
            elapsed = max(1.0, time - float(getattr(self, '_priority_window_start', time)))
            rate    = used_s / elapsed           # s of priority per s of sim time
            cap_rate = REWARD_PRIORITY_BUDGET_S / 3600.0   # convert to per-second
            excess  = max(0.0, rate - cap_rate)
            if excess <= 0.0:
                return 0.0
            other_occ = self._estimated_other_vehicle_occupancy()
            sat_flow  = max(float(self.SaturationFlow), 1.0)
            penalty   = excess * action_s * sat_flow / 3600.0 * other_occ
            return max(0.0, penalty)
        except Exception:
            return 0.0

    def _reward_side_pressure(self) -> float:
        """Return normalized side-street pressure in [0, 1+] from queue/flow proxies."""
        try:
            sat_flow = max(float(self.SaturationFlow), 1.0)
            side_vc_vals = []
            side_q_vals = []

            # Approach index 0 is bus/mainline; side approaches start from 1.
            for _pi in range(1, len(self.UpFlowList)):
                _flows = self.UpFlowList[_pi]
                _qs = self.MaxQueueLength[_pi] if self.MaxQueueLength is not None else None
                if _flows is None or len(_flows) == 0:
                    continue
                _avg_flow = sum(max(0.0, float(v)) for v in _flows) / max(len(_flows), 1)
                _avg_q = 0.0
                if _qs is not None and len(_qs) > 0:
                    _avg_q = sum(max(0.0, float(v)) for v in _qs) / max(len(_qs), 1)
                side_vc_vals.append(_avg_flow / sat_flow)
                side_q_vals.append(_avg_q / sat_flow)

            if not side_vc_vals:
                return 0.0

            avg_vc = sum(side_vc_vals) / len(side_vc_vals)
            max_vc = max(side_vc_vals)
            avg_qr = (sum(side_q_vals) / len(side_q_vals)) if side_q_vals else 0.0

            # Start increasing pressure once side flow approaches saturation.
            pressure = (
                max(0.0, avg_vc - 0.55)
                + 0.5 * max(0.0, max_vc - 0.75)
                + 0.4 * max(0.0, avg_qr - 0.25)
            )
            return max(0.0, pressure)
        except Exception:
            return 0.0

    def _reward_side_multiplier(self, extra_red_s: float) -> float:
        """Adaptive multiplier on side-street delay penalty."""
        try:
            pressure = self._reward_side_pressure()
            red_term = REWARD_SIDE_RED_GAIN * max(0.0, float(extra_red_s)) / 20.0
            mult = REWARD_SIDE_MULT_BASE + REWARD_SIDE_PRESSURE_GAIN * pressure + red_term
            return max(REWARD_SIDE_MULT_BASE, min(REWARD_SIDE_MULT_MAX, mult))
        except Exception:
            return REWARD_SIDE_MULT_BASE

    def _reward_action_cost_penalty(self, action_name: str, action_s: float) -> float:
        """Per-action effort penalty to discourage excessive priority duration."""
        s = max(0.0, float(action_s))
        if s <= 0.0:
            return 0.0
        if action_name == 'GE':
            return REWARD_ACTION_COST_GE * s
        if action_name == 'INS':
            return REWARD_ACTION_COST_INS * s
        return 0.0

    def _reward_live_network_density_vkm(self) -> float:
        """Best-effort live network density estimate (veh/km)."""
        # Prefer the time-averaged incremental network samples (updated during run).
        try:
            _n = int(getattr(self.stats, '_incr_net_samples', 0) or 0)
            _s = float(getattr(self.stats, '_incr_net_density_sum', 0.0) or 0.0)
            if _n > 0 and _s > 0.0:
                return max(0.0, _s / _n)
        except Exception:
            pass
        # Fallback: most recent network aggregate, if available.
        try:
            _d = float(getattr(self.stats, '_net_avg_density_vkm', 0.0) or 0.0)
            if _d > 0.0:
                return _d
        except Exception:
            pass
        # Final fallback: local intersection average density.
        try:
            return max(0.0, float(self.stats._inter_dsf_avg(self.id, 'density_sum') or 0.0))
        except Exception:
            return 0.0

    def _reward_density_guardrail(self, bus_eta_s: float):
        """Return (density_vkm, ge_cap_s, allow_insertion, guard_mode)."""
        d = self._reward_live_network_density_vkm()
        ge_cap = float(MAX_GE_EXTENSION_S)
        allow_ins = True
        mode = 'off'
        if not REWARD_DENSITY_GUARD_ON:
            return d, ge_cap, allow_ins, mode

        mode = 'normal'
        if d >= REWARD_DENSITY_EMERG_VKM:
            ge_cap = min(ge_cap, float(REWARD_GUARD_GE_HARD_CAP_S))
            allow_ins = False
            mode = 'emergency'
        elif d >= REWARD_DENSITY_HARD_VKM:
            ge_cap = min(ge_cap, float(REWARD_GUARD_GE_HARD_CAP_S))
            allow_ins = bool(bus_eta_s >= float(REWARD_GUARD_ALLOW_INS_IF_LATE_S))
            mode = 'hard'
        elif d >= REWARD_DENSITY_SOFT_VKM:
            ge_cap = min(ge_cap, float(REWARD_GUARD_GE_SOFT_CAP_S))
            mode = 'soft'

        return d, ge_cap, allow_ins, mode

    def _reward_future_outcome_penalty(self, disturbance_s, time, timeSta, current_phase):
        """Estimate lookahead penalty from projected recovery debt + offset drift."""
        if not REWARD_FUTURE_ENABLE:
            return 0.0, 0.0, 0.0
        try:
            disturbance_s = max(0.0, float(disturbance_s))
        except Exception:
            disturbance_s = 0.0
        if disturbance_s <= 0.0:
            return 0.0, 0.0, 0.0

        try:
            recoverable = max(0.0, float(self._reward_get_recoverable(current_phase, timeSta)))
        except Exception:
            recoverable = 0.0
        current_debt = max(0.0, float(getattr(self, '_ge_debt_s', 0.0) or 0.0))
        projected_debt = max(0.0, current_debt + disturbance_s - recoverable)

        cycle_s = max(30.0, float(self.config.get('CycleTime', 135.0) or 135.0))
        horizon_s = max(30.0, cycle_s * float(REWARD_FUTURE_HORIZON_CYCLES))

        cross_flow_vph = 0.0
        try:
            if self.UpFlowList is not None and len(self.UpFlowList) > 1:
                for _pi in range(1, len(self.UpFlowList)):
                    _f = self.UpFlowList[_pi]
                    if _f is not None and len(_f) > 0:
                        cross_flow_vph += sum(max(0.0, float(v)) for v in _f) / max(len(_f), 1)
        except Exception:
            cross_flow_vph = 0.0
        other_occ = self._estimated_other_vehicle_occupancy()

        # If recoverable slack is low, part of the disturbance becomes future
        # offset error that must be corrected by later cycles.
        projected_offset_s = max(0.0, disturbance_s - max(0.0, recoverable - current_debt))

        # Fold in recent measured offset misalignment from corridor pre-arm
        # diagnostics when available (decayed by age).
        # self._last_offset_error_s  — set when THIS junction was the downstream
        #   target (reflects corridor quality approaching this junction).
        # self._last_downstream_offset_s — set by CorridorCoordinator when THIS
        #   junction fired a grant and the next junction's offset was measured;
        #   this is the direct signal for how well THIS junction's GE decisions
        #   align the bus phase at the NEXT downstream junction.
        try:
            _obs_off = abs(float(getattr(self, '_last_offset_error_s', 0.0) or 0.0))
            _obs_t = float(getattr(self, '_last_offset_error_t', -1e9) or -1e9)
            _age = max(0.0, float(time) - _obs_t)
            _decay = max(0.0, 1.0 - (_age / max(60.0, cycle_s)))
            projected_offset_s = max(projected_offset_s, _obs_off * _decay)
        except Exception:
            pass
        try:
            _ds_off = abs(float(getattr(self, '_last_downstream_offset_s', 0.0) or 0.0))
            _ds_t = float(getattr(self, '_last_downstream_offset_t', -1e9) or -1e9)
            _ds_age = max(0.0, float(time) - _ds_t)
            _ds_decay = max(0.0, 1.0 - (_ds_age / max(60.0, cycle_s)))
            projected_offset_s = max(projected_offset_s, _ds_off * _ds_decay)
        except Exception:
            pass

        veh_exposed = cross_flow_vph * min(horizon_s, disturbance_s + projected_debt) / 3600.0
        debt_penalty = float(REWARD_FUTURE_DEBT_GAIN) * veh_exposed * projected_debt * other_occ
        offset_penalty = float(REWARD_FUTURE_OFFSET_GAIN) * veh_exposed * projected_offset_s * other_occ
        return max(0.0, debt_penalty + offset_penalty), projected_debt, projected_offset_s

    def _reward_evaluate_ge(self, ge_s, time, timeSta, bus_eta_s):
        """
        Evaluate a green extension under a throughput-constrained delay objective.

        Returns (reward, bus_saved_pax_s, other_added_pax_s, side_added_pax_s, throughput_gap_veh).
        """
        no_action_bus_delay = self._reward_estimate_no_action(time, timeSta, bus_eta_s)
        bus_occ = max(safe_float(self.BusOcc), 0.0)
        # In the bus phase, GE directly reduces waiting by up to ge_s seconds.
        bus_saved = max(0.0, min(max(no_action_bus_delay, 0.0), max(ge_s, 0.0)) * bus_occ)

        self.GE_Objective_Function(0.0, time)
        base_cost = self._reward_objective_snapshot(extra_side_red=0.0)

        self.GE_Objective_Function(ge_s, time)
        ge_cost = self._reward_objective_snapshot(extra_side_red=ge_s)

        other_increase = max(
            0.0,
            ge_cost["other_delay_pax_s"] - base_cost["other_delay_pax_s"],
        )
        side_delay = max(
            0.0,
            ge_cost["side_delay_pax_s"] - base_cost["side_delay_pax_s"],
        )

        # ── Arrival-rate correction ───────────────────────────────────────────
        # The snapshot only captures vehicles already queued. Add the delay
        # cost for cars that will ARRIVE during the GE window but are not yet
        # in the OtherDelay array.
        try:
            other_occ = self._estimated_other_vehicle_occupancy()
            # UpFlowList[0] is bus approach; non-bus approaches start at index 1
            cross_flow_vph = 0.0
            if self.UpFlowList is not None and len(self.UpFlowList) > 1:
                for _pi in range(1, len(self.UpFlowList)):
                    _f = self.UpFlowList[_pi]
                    if _f is not None and len(_f) > 0:
                        cross_flow_vph += sum(max(0.0, float(v)) for v in _f) / max(len(_f), 1)
            arriving_veh = cross_flow_vph * ge_s / 3600.0
            arrival_correction = arriving_veh * (ge_s * 0.5) * other_occ
            other_increase = max(other_increase, arrival_correction)
        except Exception:
            pass

        throughput_gap = ge_cost["total_veh"] - base_cost["total_veh"]
        # Apply adaptive side weighting, action-cost penalty, and budget penalty
        side_mult = self._reward_side_multiplier(ge_s)
        action_cost = self._reward_action_cost_penalty('GE', ge_s)
        budget_penalty = self._reward_priority_budget_penalty(ge_s, time)
        future_penalty, projected_debt, projected_offset_s = self._reward_future_outcome_penalty(
            ge_s, time, timeSta, self.BusPhase)
        reward = (bus_saved
                  - REWARD_BETA  * other_increase
                  - (REWARD_GAMMA * side_mult) * side_delay
                  - REWARD_DENSITY * self._reward_density_penalty(ge_s)
                  - future_penalty
                  - budget_penalty
                  - action_cost)
        if throughput_gap < -REWARD_THROUGHPUT_TOL:
            reward = -1e9

        if GLOBAL_REWARD_MODE:
            # Yang & Fan (2025) CPD signal: net person-delay reduction.
            # r = bus_saved_pax_s - other_increase_pax_s - side_delay_pax_s
            # This is the only value that should enter the global buffer —
            # not the raw GE duration and not the full multi-penalty reward.
            _cpd_signal = float(bus_saved) - float(other_increase) - float(side_delay)
            _record_intersection_reward(self.id, _cpd_signal)
        return reward, bus_saved, other_increase, side_delay, throughput_gap, future_penalty, projected_debt, projected_offset_s

    def _reward_evaluate_insertion(self, ins_dur, time, timeSta, bus_eta_s):
        """
        Evaluate a phase insertion under a throughput-constrained delay objective.

        Returns (reward, bus_saved_pax_s, other_added_pax_s, side_added_pax_s, throughput_gap_veh).
        """
        # Bus delay saved: difference between waiting for natural green and insertion
        no_action_bus_delay = self._reward_estimate_no_action(time, timeSta, bus_eta_s)
        baseline_bus_cost = max(0.0, no_action_bus_delay) * max(safe_float(self.BusOcc), 0.0)
        
        # Baseline: delays WITHOUT insertion (no extra red on other phases)
        self.BP_Objective_Function(0.0, time)
        base_cost = self._reward_objective_snapshot(extra_side_red=0.0)
        
        # With insertion, bus gets green immediately
        self.BP_Objective_Function(ins_dur, time)
        action_cost = self._reward_objective_snapshot(extra_side_red=ins_dur + 5.0)
        bus_saved = max(0.0, baseline_bus_cost - action_cost["bus_delay_pax_s"])

        # Other-traffic delay: DELTA (with insertion - without insertion)
        other_increase = max(0.0, action_cost["other_delay_pax_s"] - base_cost["other_delay_pax_s"])
        side_delay = max(0.0, action_cost["side_delay_pax_s"] - base_cost["side_delay_pax_s"])

        throughput_gap = action_cost["total_veh"] - base_cost["total_veh"]
        # Apply adaptive side weighting, action-cost penalty, and budget penalty
        side_mult = self._reward_side_multiplier(ins_dur + 5.0)
        action_cost = self._reward_action_cost_penalty('INS', ins_dur)
        budget_penalty = self._reward_priority_budget_penalty(ins_dur, time)
        future_penalty, projected_debt, projected_offset_s = self._reward_future_outcome_penalty(
            ins_dur + 5.0, time, timeSta, current_phase=int(ECIGetCurrentPhase(self.node_id) or 1))
        reward = (bus_saved
                  - REWARD_BETA  * other_increase
                  - (REWARD_GAMMA * side_mult) * side_delay
                  - REWARD_DENSITY * self._reward_density_penalty(ins_dur + 5.0)
                  - future_penalty
                  - budget_penalty
                  - action_cost)
        if throughput_gap < -REWARD_THROUGHPUT_TOL:
            reward = -1e9

        return reward, bus_saved, other_increase, side_delay, throughput_gap, future_penalty, projected_debt, projected_offset_s

    def _reward_density_penalty(self, extra_red_s):
        """Estimate density-driven spillback penalty (pax-s equivalent)."""
        extra_red_s = max(safe_float(extra_red_s), 0.0)
        if extra_red_s <= 0.0:
            return 0.0

        try:
            sat_flow = max(float(self.SaturationFlow), 1.0)
            sat_den = max(float(getattr(self, 'SaturationDensity', 35.0) or 35.0), 1.0)
            cycle_s = float(self.config.get('CycleTime', 135.0))
            other_occ = self._estimated_other_vehicle_occupancy()

            non_bus_q = []
            for _pi in range(1, len(self.UpFlowList)):
                _flows = self.UpFlowList[_pi]
                if _flows is None or len(_flows) == 0:
                    continue
                _q = sum(max(0.0, float(_v)) for _v in _flows) / max(len(_flows), 1)
                non_bus_q.append(_q)
            if not non_bus_q:
                return 0.0

            avg_q = sum(non_bus_q) / len(non_bus_q)
            max_q = max(non_bus_q)
            avg_vc = avg_q / sat_flow

            avg_den = 0.0
            try:
                avg_den = max(0.0, float(self.stats._inter_dsf_avg(self.id, 'density_sum') or 0.0))
            except Exception:
                avg_den = 0.0
            den_ratio = avg_den / sat_den

            # Activate only when already congested.
            congestion = (
                max(0.0, avg_vc - 0.70)
                + max(0.0, den_ratio - 0.75)
                + max(0.0, (max_q / sat_flow) - 0.85) * 0.5
            )
            if congestion <= 0.0:
                return 0.0

            overflow_veh = max_q * extra_red_s / 3600.0
            return max(0.0, overflow_veh * cycle_s * other_occ * congestion)
        except Exception:
            return 0.0

    def run_reward_tsp(self, time, timeSta, acycle):
        """Run reward-based or MPC-style local TSP decision logic."""
        # Phase restoration (same as HARMONY - reuse existing method)
        self.restore_phase_if_needed(time, timeSta, acycle)

        # Cooldown guard after a grant
        if time - self.last_tsp_action_time < self.tsp_cooldown_seconds:
            return

        # Short re-evaluation debounce after a NO_ACTION decision.
        if time < getattr(self, '_reward_no_action_until', -1.0):
            return

        # Already active - do not re-evaluate
        if self.flag != 0:
            return
        if getattr(self, '_tsp_cycle_grant_until', -1.0) > time:
            return

        current_phase = ECIGetCurrentPhase(self.node_id)
        if current_phase < 0:
            return

        # Corridor pre-arm check (reward modes)
        _prearm = getattr(self, '_harmony_prearm', None)
        if REWARD_ENABLE_PREARM and _prearm is not None and self.TSPStrategy == 0:
            _pa_veh, _pa_eta_t, _pa_issued_t = _prearm
            _eta_from_now = _pa_eta_t - time
            if _eta_from_now < -20.0 or time - _pa_issued_t > 120.0:
                self._harmony_prearm = None
            elif 0.0 <= _eta_from_now <= getattr(self, '_eta_max_s', 90.0):
                self._harmony_prearm = None
                self._run_reward_tsp_evaluate(
                    time, timeSta, acycle, current_phase,
                    _eta_from_now, _pa_veh)
                return

        # Bus detection check
        _n_det_slots = max(len(self.BusDet), 1)
        bus_detected = False
        bus_speed = 0.0
        det_idx = 0
        for i in range(_n_det_slots):
            if self.BusSpeed[0][i] > 0:
                bus_speed = self.BusSpeed[0][i]
                det_idx = i
                bus_detected = True
                break

        if not bus_detected:
            return

        # Approach debounce for detection stats (30 s per bus approach)
        _det_vid_chk = self.last_detected_bus_id
        _reward_stats_ok = True
        if _det_vid_chk and _det_vid_chk > 0:
            _last_rec = self._approach_det_t.get(_det_vid_chk, -999.0)
            if (time - _last_rec) < 30.0:
                _reward_stats_ok = False
            else:
                self._approach_det_t[_det_vid_chk] = time

        # Global bus focus gate
        _det_vid = self.last_detected_bus_id
        if _det_vid and _det_vid > 0 and _is_focus_blocked(_det_vid, self.id, time):
            if LOG_REWARD:
                _vprint(
                    f"[REWARD_TSP] t={time:.1f} inter={self.id} "
                    f"v={_det_vid} focus_suppress - focus bus={_focus_bus_id}")
            _mark_detection_point(self.id, _det_vid, 0.0, 0.0, time, "focus_suppress")
            self.stats.record_tsp_event(self.id, 'detection')
            return

        # Compute bus ETA
        eta_info = getattr(self, '_bus_eta', {}).get(det_idx)
        _det_dist_fb = (
            self.config['DetDistance'][0][det_idx]
            if self.config.get('DetDistance') and len(self.config['DetDistance']) > 0
            and det_idx < len(self.config['DetDistance'][0])
            else 200.0
        )
        bus_eta_s = eta_info[1] if eta_info else (_det_dist_fb / bus_speed)

        # Skip evaluation when bus is too far away to benefit from TSP.
        _cycle = float(self.config.get('CycleTime', 135))
        if bus_eta_s > 2.0 * _cycle:
            self._reward_no_action_until = time + 5.0
            return

        self._run_reward_tsp_evaluate(
            time, timeSta, acycle, current_phase, bus_eta_s, _det_vid,
            stats_ok=_reward_stats_ok)

    def _run_reward_tsp_evaluate(self, time, timeSta, acycle,
                                  current_phase, bus_eta_s, veh_id,
                                  stats_ok: bool = True):
        if veh_id and veh_id > 0 and _is_focus_blocked(veh_id, self.id, time):
            if LOG_REWARD:
                _vprint(
                    f"[REWARD_TSP] t={time:.1f} inter={self.id} "
                    f"v={veh_id} focus_suppress — focus bus={_focus_bus_id}")
            _mark_detection_point(self.id, veh_id, 0.0, 0.0, time, "focus_suppress")
            if stats_ok:
                self.stats.record_tsp_event(self.id, 'detection')
            return

        if not hasattr(self, '_reward_diag'):
            self._reward_diag = collections.Counter()
        if not hasattr(self, '_reward_diag_last_bucket'):
            self._reward_diag_last_bucket = -1

        self._reward_diag['eval'] += 1

        def _emit_reward_diag_if_due():
            _bucket = int(time) // 300
            if _bucket == self._reward_diag_last_bucket:
                return
            self._reward_diag_last_bucket = _bucket
            _d = self._reward_diag
            log_to_file(
                f"[REWARD_DIAG] inter={self.id} t={time:.0f} "
                f"eval={int(_d.get('eval', 0))} "
                f"no_action={int(_d.get('no_action', 0))} "
                f"ge={int(_d.get('action_ge', 0))} "
                f"ins={int(_d.get('action_ins', 0))} "
                f"noact_ge_inapp={int(_d.get('no_action_ge_inapplicable', 0))} "
                f"noact_ins_guard={int(_d.get('no_action_ins_guard_block', 0))} "
                f"noact_no_pos={int(_d.get('no_action_no_positive_action', 0))} "
                f"noact_pos_alt={int(_d.get('no_action_positive_alt_not_chosen', 0))} "
                f"ge_cap_skip={int(_d.get('ge_skipped_cap', 0))}"
            )

        # ── DC TSP multi-agent path (GLOBAL_REWARD_MODE) ─────────────────────
        # Each intersection acts as an independent agent evaluating Eq. 6 reward
        # over a discrete action space and returning early.
        # Wrapped in try-except so any internal failure falls through to NO_ACTION
        # rather than propagating to the outer update() exception handler which
        # would call stop_simulation() and leave Aimsun with empty stats.
        if GLOBAL_REWARD_MODE:
          try:
            # ── Forward OC (DC TSP paper): use coordinator pre-arm ETA if
            # available so the agent acts proactively on the bus arrival time
            # predicted by the Kalman tracker, not just local detection distance.
            _prearm = getattr(self, '_harmony_prearm', None)
            if _prearm is not None:
                _pa_veh, _pa_eta_t, _pa_issued_t = _prearm
                _pa_eta_rem = _pa_eta_t - time
                if 2.0 < _pa_eta_rem < MAX_STRATEGY_ETA_S:
                    bus_eta_s = _pa_eta_rem    # use Kalman ETA (more accurate)
                    if _pa_veh and _pa_veh > 0:
                        veh_id = _pa_veh
            # Consume pre-arm — DCTSP agent makes the full decision
            self._harmony_prearm = None

            # ── One-action-per-bus-per-junction guard ─────────────────────────
            # Each bus is allowed exactly ONE action (NO_ACTION / GE / INS) per
            # pass through this intersection.  If the bus was already served (e.g.
            # triggered by pre-arm and now detected at closer range), skip silently.
            if self._dctsp_check_acted(veh_id, time):
                log_to_file(
                    f"[DCTSP] inter={self.id} t={time:.1f} bus={veh_id} "
                    f"SKIPPED — one-action guard active",
                    force=False)
                return

            self._dctsp_record_poz_checkin(veh_id, time)
            _no_act_delay = self._reward_estimate_no_action(time, timeSta, bus_eta_s)
            _sigma_in     = self._hw_sigma_current

            # ── Validation delay estimates (all methods, NO_ACTION only) ──────
            # Computed once per detection for cross-method comparison in the CSV.
            # kinematic = _no_act_delay (already computed from _reward_estimate_no_action)
            # dd1       = D/D/1 queue model
            # mb        = moving bottleneck LWR model
            try:
                # Compute time-to-bus-green: how many seconds until the bus approach
                # sees a green signal.  This is NOT simply the remaining time in the
                # current phase — that would pass remaining-green as "remaining red"
                # when the bus phase is active, giving completely wrong DD1/MB results.
                #
                # Rule:
                #   • bus phase active → remaining_red = 0 (green is now; DD1/MB
                #     will enter Case 2 or 3 based on bus_eta_s vs g_s)
                #   • other phase active → sum remaining current phase + all
                #     intermediate phases until bus green starts
                _current_phase_now = current_phase
                if _current_phase_now == self.BusPhase:
                    _remaining_red_now = 0.0   # bus phase is currently green
                else:
                    _ps_val = ECIGetStartingTimePhase(self.node_id)
                    _pd_val = GetPhaseDuration(self.node_id, _current_phase_now, timeSta)
                    _rem_cur = max(0.0, float(_pd_val) - (float(time) - float(_ps_val)))
                    _tg = _rem_cur
                    try:
                        _ci = self.phase_list.index(_current_phase_now)
                        _bi = self.phase_list.index(self.BusPhase)
                        _n  = len(self.phase_list)
                        _steps = (_bi - _ci) % _n
                        for _k in range(1, _steps):
                            _ph = self.phase_list[(_ci + _k) % _n]
                            _tg += GetPhaseDuration(self.node_id, _ph, timeSta)
                    except Exception:
                        pass
                    _remaining_red_now = _tg
            except Exception:
                _remaining_red_now = 0.0
            _dd1_delay_s = self._queue_model_bus_delay_s(
                bus_eta_s, _remaining_red_now, 'NO_ACTION', 0.0)
            _mb_delay_s  = self._mb_bus_delay_s(
                bus_eta_s, _remaining_red_now, 'NO_ACTION', 0.0)

            # ── Ensemble bus-delay: kinematic + fraction of LWR moving-bottleneck ──
            # The kinematic model (_reward_estimate_no_action) ignores queue effects
            # and returns 0 when the bus arrives during green, even if a residual queue
            # of 10–20 vehicles means the bus will wait 15–30 s at the stop line.
            # BG_MB_WEIGHT × mb_delay adds this component conservatively so the
            # threshold gate and reward formula are not misled by underestimation.
            # IMPORTANT: MB only augments when kinematic already predicts real delay.
            # If kin=0 the bus arrives during natural green — MB background congestion
            # must NOT trigger BARGAIN_SPM; bus has no delay so gate should fail.
            if _no_act_delay >= 1.0:
                _ensemble_delay = max(_no_act_delay, _mb_delay_s * float(BG_MB_WEIGHT))
            else:
                _ensemble_delay = _no_act_delay  # trust kin=0: bus is not delayed

            # Debug log so every future run can be inspected for correctness.
            # Shows the three prediction methods alongside phase/queue context.
            try:
                _q_m_dbg = 0.0
                if (hasattr(self, 'MaxQueueLength') and self.MaxQueueLength
                        and len(self.MaxQueueLength) > 0
                        and len(self.MaxQueueLength[0]) > 0):
                    _q_m_dbg = float(np.mean(self.MaxQueueLength[0]))
                log_to_file(
                    f"[DELAYVAL] jct={self.id} t={round(time,1)}s "
                    f"phase={current_phase}(bus={self.BusPhase}) "
                    f"eta={round(bus_eta_s,1)}s rem_red={round(_remaining_red_now,1)}s "
                    f"kin={round(_no_act_delay,1)}s dd1={round(_dd1_delay_s,1)}s "
                    f"mb={round(_mb_delay_s,1)}s ens={round(_ensemble_delay,1)}s "
                    f"Q={round(_q_m_dbg,1)}m",
                    force=False)
            except Exception:
                pass

            _best_r       = -1e9
            _best_type    = 'NO_ACTION'
            _best_param   = 0.0
            _best_sigma_out = _sigma_in + max(0.0, _ensemble_delay)
            _best_t_poz     = bus_eta_s + max(0.0, _ensemble_delay)
            _dctsp_rows   = []   # for reward-cycle CSV

            # ── Tall-bus occupancy detection for BARGAIN mode ─────────────
            # Articulated / double-deck buses carry more passengers.  If their
            # Aimsun vehicle length exceeds BG_TALL_BUS_LENGTH_M the effective
            # occupancy is scaled up, increasing the bus side of the Nash
            # bargaining trade-off and making TSP more justified.
            global _bg_bus_occ_eff
            _bg_bus_occ_eff = 0.0
            if BARGAIN_SPM_MODE:
                try:
                    _sta = AKIVehGetStaticInf(int(veh_id))
                    if _sta.report >= 0 and float(_sta.length) > float(BG_TALL_BUS_LENGTH_M):
                        _bg_bus_occ_eff = max(float(self.BusOcc), 1.0) * float(BG_TALL_BUS_OCC_MULT)
                        log_to_file(
                            f"[BARGAIN_SPM] TALL_BUS bus={veh_id} len={_sta.length:.1f}m "
                            f"occ_std={self.BusOcc:.0f} occ_eff={_bg_bus_occ_eff:.0f}",
                            force=True)
                except Exception:
                    pass

            # ── Actual passenger load + schedule lateness weighting ───────────
            # Uses InfPTVeh.currentLoad (live pax count) and nextServiceTime
            # (scheduled arrival at next stop) to compute a lateness-weighted
            # effective occupancy.  See comprehensive_mp.tex Eq. (lateness_weight).
            #
            # Fields used from InfPTVeh:
            #   currentLoad          — actual pax on board right now
            #   nextServiceTime      — scheduled time at next stop (s from sim start)
            #   distanceNextStop     — metres to next stop (m)
            #   CurrentSpeed         — km/h → converted to m/s
            #   theoreticalGenerationTime — scheduled departure from origin (s)
            #   SystemGenerationT    — actual departure time (s)
            if BARGAIN_SPM_MODE:
                try:
                    _pt_inf = AKIPTVehGetInf(int(veh_id))
                    if _pt_inf.report >= 0:
                        # ── Actual load ───────────────────────────────────────
                        if BG_USE_ACTUAL_LOAD:
                            _actual_load = float(getattr(_pt_inf, 'currentLoad', 0.0) or 0.0)
                            if _actual_load > 1.0:
                                if _bg_bus_occ_eff > 0.0:
                                    # tall-bus already applied: preserve ratio
                                    _tall_ratio = _bg_bus_occ_eff / max(float(self.BusOcc), 1.0)
                                    _bg_bus_occ_eff = _actual_load * _tall_ratio
                                else:
                                    _bg_bus_occ_eff = _actual_load
                        # ── Schedule lateness ─────────────────────────────────
                        _lateness_s = 0.0
                        if BG_USE_SCHEDULE:
                            _next_svc_t = float(getattr(_pt_inf, 'nextServiceTime', 0.0) or 0.0)
                            _dist_next  = float(getattr(_pt_inf, 'distanceNextStop', -1.0) or -1.0)
                            _spd_mps    = max(float(getattr(_pt_inf, 'CurrentSpeed', 0.0) or 0.0) / 3.6, 0.5)
                            if _next_svc_t > 0.0 and _dist_next >= 0.0:
                                # Primary: ETA at next stop vs scheduled
                                _eta_next_stop = time + (_dist_next / _spd_mps)
                                _lateness_s = _eta_next_stop - _next_svc_t
                            else:
                                # Fallback: generation lateness
                                _theo_gen   = float(getattr(_pt_inf, 'theoreticalGenerationTime', 0.0) or 0.0)
                                _actual_gen = float(getattr(_pt_inf, 'SystemGenerationT', 0.0) or 0.0)
                                if _theo_gen > 0.0:
                                    _lateness_s = _actual_gen - _theo_gen
                        # ── Apply lateness multiplier ─────────────────────────
                        if _lateness_s > 0.0:
                            # Cap lateness contribution at 5× reference to
                            # prevent runaway weights from extreme deviations.
                            _late_mult = 1.0 + (
                                min(_lateness_s, 5.0 * float(BG_LATENESS_REF_S))
                                / max(float(BG_LATENESS_REF_S), 1.0)
                            ) * float(BG_LATENESS_SENSITIVITY)
                            _base_occ = _bg_bus_occ_eff if _bg_bus_occ_eff > 0.0 else float(self.BusOcc)
                            _bg_bus_occ_eff = max(_base_occ, 1.0) * _late_mult
                            log_to_file(
                                f"[SCHEDULE] bus={veh_id} inter={self.id} t={time:.1f} "
                                f"late={_lateness_s:.1f}s mult={_late_mult:.2f} "
                                f"occ_eff={_bg_bus_occ_eff:.1f}",
                                force=False)
                except Exception:
                    pass

            # NO_ACTION baseline
            _r_na, _so_na, _tp_na, _bps_na, _cpc_na, _nsd_na, _std_na = self._dctsp_eval_action(
                'NO_ACTION', 0.0, _sigma_in, _ensemble_delay, bus_eta_s)
            _best_r = _r_na; _best_std = _std_na
            _dctsp_rows.append(('NO_ACTION', 0.0, _r_na, _so_na, _tp_na, _bps_na, _cpc_na, _nsd_na, _std_na))

            # ── Congestion gate: suppress TSP at near-saturated network ────────
            # When DCTSP_CONGESTION_GATE=True and the mean recent cross-phase flow
            # exceeds DCTSP_CONGESTION_GATE_FRACTION × SaturationFlow, all TSP
            # candidates are skipped and NO_ACTION is the only evaluated option.
            # Literature: Dion et al. (2004), Duerr (2000) — TSP is counter-
            # productive near saturation; green extension causes secondary queuing.
            _cg_blocked = False
            if DCTSP_CONGESTION_GATE:
                try:
                    _cg_up = np.asarray(getattr(self, 'UpFlowList', []), dtype=float)
                    _cg_sat = 0.0
                    if _cg_up.ndim >= 2 and _cg_up.shape[0] > 1:
                        _cg_n = min(5, _cg_up.shape[1]) if _cg_up.shape[1] > 0 else 0
                        _cg_cross = (_cg_up[1:, -_cg_n:].ravel()
                                     if _cg_n > 0 else np.asarray([], dtype=float))
                        _cg_cross = _cg_cross[_cg_cross > 0.0]
                        if _cg_cross.size > 0:
                            _cg_sat = float(np.mean(_cg_cross)) / max(
                                float(getattr(self, 'SaturationFlow', 1800.0)), 1.0)
                    _cg_blocked = _cg_sat > float(DCTSP_CONGESTION_GATE_FRACTION)
                    if _cg_blocked:
                        log_to_file(
                            f"[CONGESTION_GATE] inter={self.id} t={time:.1f} "
                            f"sat_ratio={_cg_sat:.2f} > gate={DCTSP_CONGESTION_GATE_FRACTION:.2f}"
                            f" → NO_ACTION forced", force=False)
                except Exception:
                    _cg_blocked = False

            if not _cg_blocked:
                # Density guard — shared with existing reward path
                try:
                    _dens_live, _ge_cap_s, _allow_ins, _guard_mode = \
                        self._reward_density_guardrail(bus_eta_s)
                except Exception:
                    _dens_live, _ge_cap_s, _allow_ins, _guard_mode = 0.0, MAX_GE_EXTENSION_S, True, "none"

                # ── Phase timing — used by ER, GR, and HS_EXT modes ─────────
                _wrong_phase_ge = (current_phase != self.BusPhase)
                try:
                    _ps_er = ECIGetStartingTimePhase(self.node_id)
                    _pd_er = GetPhaseDuration(self.node_id, current_phase, timeSta)
                    _rem_er = max(0.0, float(_pd_er) - (float(time) - float(_ps_er)))
                except Exception:
                    _rem_er = 0.0

                if HS_EXT_MODE:
                    # ── _HSExt: Harmony Search over {GR, GE, INS} in [5, 20] s ──
                    # Replaces discrete GE/GR/INS candidate loops.
                    # D/D/1 shockwave model is the HS objective; optimal duration
                    # is found continuously rather than from a fixed set {5,10,15}.
                    for _hrow in self._dctsp_hs_ext_find_action(
                            _sigma_in, _ensemble_delay, bus_eta_s,
                            wrong_phase_ge=_wrong_phase_ge,
                            remaining_red_s=_rem_er):
                        _lbl, _t, _r, _so, _tp, _bps, _cpc, _nsd, _std = _hrow
                        _dctsp_rows.append(_hrow)
                        log_to_file(
                            f"[DCTSP_HS] inter={self.id} t={time:.1f} {_lbl} "
                            f"t_opt={_t:.1f}s r={_r:.2f} σ_out={_so:.0f}s "
                            f"bus_save={_bps:.1f} car_cost={_cpc:.1f}",
                            force=True)
                        _ft = ('GREEN_REALLOC' if _lbl.startswith('GR_')
                               else _lbl.split('_')[0])
                        if _r > _best_r and (not BARGAIN_SPM_MODE or _bps > 0.0):
                            _best_r = _r; _best_type = _ft; _best_param = _t
                            _best_sigma_out = _so; _best_t_poz = _tp; _best_std = _std

                else:
                    # ── Standard discrete candidates: GE, INS, ER, GR ─────────
                    # GE when current == bus_phase: extends the correct phase (beneficial).
                    # GE when current != bus_phase: extends the wrong phase (wrong_phase=True),
                    #   bus_delay increases by action_s — always harmful.  Evaluated for
                    #   logging/diagnosis only; NEVER allowed to update best_action.
                    #   NOTE: when sigma_in < 0 (bus ahead), hw_delta CAN be positive for
                    #   wrong-phase GE (regularising headway by deliberately delaying the bus).
                    #   This caused wrong-phase GE_5 to be chosen 15/64 times in prior runs.
                    #   Fix: `and not _wrong_phase_ge` guard below prevents selection.
                    # INS when current != bus_phase: standard beneficial insertion.
                    # INS when current == bus_phase and delay > 0: inserts phase immediately
                    #   after current green ends (still helpful if bus misses current green).
                    # INS when current == bus_phase and delay <= 0: overhead only, reward < 0.
                    for _ge in DCTSP_GE_ACTIONS:
                        if _ge > MAX_GE_EXTENSION_S or _ge > _ge_cap_s:
                            continue
                        _r, _so, _tp, _bps, _cpc, _nsd, _std = self._dctsp_eval_action(
                            'GE', _ge, _sigma_in, _ensemble_delay, bus_eta_s,
                            wrong_phase=_wrong_phase_ge)
                        _dctsp_rows.append((f'GE_{_ge:.0f}', _ge, _r, _so, _tp, _bps, _cpc, _nsd, _std))
                        log_to_file(
                            f"[DCTSP] inter={self.id} t={time:.1f} GE_{_ge:.0f}s "
                            f"{'(wrong-phase,eval-only)' if _wrong_phase_ge else ''}"
                            f"r={_r:.2f}s σ_out={_so:.0f}s T_POZ={_tp:.1f}s")
                        # Wrong-phase GE harms the bus and corrupts the headway signal
                        # (sigma regularisation via deliberate bus delay is anti-TSP).
                        # Evaluate for diagnostics but never select as best action.
                        if _r > _best_r and not _wrong_phase_ge:
                            _best_r = _r; _best_type = 'GE'; _best_param = _ge
                            _best_sigma_out = _so; _best_t_poz = _tp; _best_std = _std

                    # INS candidates — always evaluated; density guard still applies
                    if _allow_ins:
                        for _ins_dur in DCTSP_INS_DURATIONS:
                            _ins_dur = max(DCTSP_MIN_INS_DURATION_S,
                                           min(DCTSP_MAX_INS_DURATION_S, float(_ins_dur)))
                            _r, _so, _tp, _bps, _cpc, _nsd, _std = self._dctsp_eval_action(
                                'INS', _ins_dur, _sigma_in, _ensemble_delay, bus_eta_s)
                            _dctsp_rows.append((f'INS_{_ins_dur:.0f}', _ins_dur, _r, _so, _tp, _bps, _cpc, _nsd, _std))
                            log_to_file(
                                f"[DCTSP] inter={self.id} t={time:.1f} INS_{_ins_dur:.0f}s "
                                f"{'(redundant)' if not _wrong_phase_ge else ''}"
                                f"r={_r:.2f}s σ_out={_so:.0f}s")
                            # BARGAIN_SPM: only choose INS when the bus actually benefits.
                            # If bus cannot catch the inserted window (bus_save=0), INS
                            # disrupts cross-traffic for no bus gain — veto it.
                            if _r > _best_r and (not BARGAIN_SPM_MODE or _bps > 0.0):
                                _best_r = _r; _best_type = 'INS'; _best_param = _ins_dur
                                _best_sigma_out = _so; _best_t_poz = _tp; _best_std = _std

                    # ── EARLY_RED candidates — evaluated for BOTH phases ───────
                    # Wrong-phase (cross-traffic): cutting the cross-traffic phase brings
                    #   the bus phase sooner → beneficial for bus, small cross-traffic cost.
                    # Bus-phase: cutting the bus phase early gives cross-traffic extra green.
                    #   Reward is positive only when bus was already going to miss current
                    #   green (cross benefits, bus unaffected).  If bus would have caught
                    #   the green, cutting it creates a miss → large negative reward.
                    #   Agent learns the correct tradeoff automatically.
                    for _er_cut in DCTSP_ER_ACTIONS:
                        _r, _so, _tp, _bps, _cpc, _nsd, _std = self._dctsp_eval_action(
                            'EARLY_RED', _er_cut, _sigma_in, _ensemble_delay, bus_eta_s,
                            wrong_phase=_wrong_phase_ge, remaining_red_s=_rem_er)
                        _er_lbl = f'ER_{_er_cut:.0f}' if _wrong_phase_ge else f'ER_BP_{_er_cut:.0f}'
                        _dctsp_rows.append(
                            (_er_lbl, _er_cut, _r, _so, _tp, _bps, _cpc, _nsd, _std))
                        log_to_file(
                            f"[DCTSP] inter={self.id} t={time:.1f} {_er_lbl} "
                            f"rem={_rem_er:.1f}s r={_r:.2f} σ_out={_so:.0f}s "
                            f"{'(bus-phase-cut)' if not _wrong_phase_ge else ''}")
                        # BARGAIN_SPM: only choose ER when the bus actually benefits
                        # (bps > 0 means the phase cut genuinely helps this bus).
                        if _r > _best_r and (not BARGAIN_SPM_MODE or _bps > 0.0):
                            _best_r = _r; _best_type = 'EARLY_RED'; _best_param = _er_cut
                            _best_sigma_out = _so; _best_t_poz = _tp; _best_std = _std

                    # ── GREEN_REALLOC candidates (zero net-cost alternative to GE/ER) ─
                    # Evaluated for BOTH phases:
                    #   Right-phase (bus active): zero-cost GE — extends current bus green
                    #     and recovers from the next non-bus phase.  Strictly better than
                    #     plain GE (same bus benefit, no car penalty).  Competes with INS.
                    #   Wrong-phase (non-bus active): advance bus phase by cutting current
                    #     non-bus phase, recovering from future bus phase.
                    if DCTSP_GREEN_REALLOC_MODE:
                        for _gr_cut in DCTSP_GR_ACTIONS:
                            _r, _so, _tp, _bps, _cpc, _nsd, _std = self._dctsp_eval_action(
                                'GREEN_REALLOC', _gr_cut, _sigma_in, _ensemble_delay, bus_eta_s,
                                wrong_phase=_wrong_phase_ge, remaining_red_s=_rem_er)
                            _gr_lbl = f'GR_{_gr_cut:.0f}'
                            _dctsp_rows.append(
                                (_gr_lbl, _gr_cut, _r, _so, _tp, _bps, _cpc, _nsd, _std))
                            log_to_file(
                                f"[DCTSP] inter={self.id} t={time:.1f} {_gr_lbl} "
                                f"{'(wrong-phase)' if _wrong_phase_ge else '(right-phase/zero-cost)'} "
                                f"rem={_rem_er:.1f}s r={_r:.2f} σ_out={_so:.0f}s",
                                force=False)
                            if _r > _best_r:
                                _best_r = _r; _best_type = 'GREEN_REALLOC'; _best_param = _gr_cut
                                _best_sigma_out = _so; _best_t_poz = _tp; _best_std = _std

            # ── Per-detection reward summary (every detection, not throttled) ──
            # Shows all candidate rewards so the selection process is transparent.
            # Verify: (a) baseline_car is non-zero when cross-streets are busy,
            #         (b) NO_ACTION has a negative reward ∝ current system cost,
            #         (c) TSP actions are chosen only when improvement > car cost.
            try:
                _dbg_bp   = float(getattr(self, 'BusPhaseDuration', 30) or 30)
                _dbg_bcar = self._dctsp_cross_traffic_delay_s(_dbg_bp)
                _dbg_poz_bl  = float(getattr(self, '_no_action_poz_ema_s', 30.0))
                _dbg_poz_tt  = list(getattr(self, '_poz_travel_times', []))
                _dbg_poz_ff  = float(min(_dbg_poz_tt)) if len(_dbg_poz_tt) >= 3 else max(_dbg_poz_bl * 0.30, 5.0)
                _dbg_parts = [
                    f"[REWARD_DEBUG] inter={self.id} t={time:.1f} bus={veh_id}"
                    f" eta={bus_eta_s:.1f}s kin_delay={_no_act_delay:.1f}s ens_delay={_ensemble_delay:.1f}s"
                    f" baseline_car={_dbg_bcar:.1f}pax·s σ_in={_sigma_in:.0f}s"
                    f" poz_baseline={_dbg_poz_bl:.1f}s poz_ff={_dbg_poz_ff:.1f}s"
                    f" na_poz={_dbg_poz_ff + max(0.0, _no_act_delay):.1f}s eff_σ={_sigma_in + max(0.0, _no_act_delay):.1f}s"
                ]
                for _lbl, _lparam, _lr, _lso, _ltp, _lbps, _lcpc, _lnsd, _lstd in _dctsp_rows:
                    _dbg_parts.append(
                        f" | {_lbl}: r={_lr:.2f}"
                        f" σ_out={_lso:.0f}s"
                        f" NA_total={_lnsd:.1f} act_total={_lstd:.1f}"
                        f" bus_save={_lbps:.1f} car_cost={_lcpc:.1f}")
                _dbg_parts.append(f" → BEST={_best_type}_{_best_param:.0f}s r={_best_r:.4f}")
                log_to_file("".join(_dbg_parts), force=True)
            except Exception:
                pass
            # ── REWARD_AUDIT: Throttled overview with measured car delay ──────
            # Logs every ~10th detection for a concise cross-check against Aimsun
            # cumulative statistics (measured_car_cumul grows with simulation time).
            # baseline_car = UpFlowList estimate of per-cycle cross-traffic cost;
            # no_action_total / best_action_total = full system cost pax·s.
            try:
                _audit_counter = getattr(self, '_reward_audit_counter', 0) + 1
                self._reward_audit_counter = _audit_counter
                if _audit_counter % 10 == 1:
                    _aud_bp_dur = float(getattr(self, 'BusPhaseDuration', 30) or 30)
                    _aud_baseline_car = self._dctsp_cross_traffic_delay_s(_aud_bp_dur)
                    _aud_best_p = float(_best_param) if _best_type != 'NO_ACTION' else 0.0
                    _aud_cross = self._dctsp_cross_traffic_delay_s(_aud_best_p)
                    _aud_main  = self._dctsp_cross_traffic_delay_s(_aud_best_p, phases=[0])
                    _aud_measured_car = 0.0
                    if stats_ok and hasattr(self.stats, '_inter'):
                        _aud_measured_car = float(
                            self.stats._inter.get(self.id, {}).get('delay_car', 0.0) or 0.0)
                    log_to_file(
                        f"[REWARD_AUDIT] inter={self.id} t={time:.0f}s #det={_audit_counter}"
                        f" bus={veh_id} eta={bus_eta_s:.1f}s"
                        f" no_act_bus_delay={_no_act_delay:.1f}s"
                        f" baseline_car={_aud_baseline_car:.1f}pax·s"
                        f" no_action_total={_nsd_na:.1f}pax·s"
                        f" best_action_total={_best_std:.1f}pax·s"
                        f" best_cross_cost={_aud_cross:.1f}pax·s"
                        f" best_main_car_saved={_aud_main:.1f}pax·s"
                        f" measured_car_cumul={_aud_measured_car:.1f}pax·s"
                        f" best={_best_type}_{_best_param:.0f}s r={_best_r:.4f}",
                        force=True)
            except Exception:
                pass

            # ── RL: Bellman TD update + ε-greedy action selection ─────────────
            # All candidate rewards have been estimated.  Now:
            #   1. Map evaluated rows to action-space indices.
            #   2. If this bus has a pending transition from its PREVIOUS junction,
            #      complete the bellman update: Q(s,a) += α[r + γ·maxQ(s',·) − Q(s,a)]
            #   3. ε-greedy: with probability ε explore uniformly; otherwise exploit.
            #   4. Override the greedy-best (_best_type etc.) with the RL choice.
            #   5. Store the pending transition for completion at the next junction.
            try:
                if REWARD_SELFORG_MODE: raise StopIteration  # SE rule replaces RL
                if DCTSP_ZIG_MODE:      raise StopIteration  # ZIG override replaces RL
                if MP_ECTM_MODE:        raise StopIteration  # MP-ECTM replaces RL
                if BXT_MODE:            raise StopIteration  # BXT CTM Q-learning replaces RL
                if META_TSP_MODE:       raise StopIteration  # META_TSP replaces RL
                if BARGAIN_SPM_MODE:    raise StopIteration  # bargaining-game mode replaces RL
                import random as _rnd_mod
                _RL_LABEL_TO_IDX = {
                    'NO_ACTION': 0,
                    'GE_5':  1, 'GE_10':  2, 'GE_15':  3,
                    'INS_10': 4, 'INS_15': 5, 'INS_20': 6,
                    'ER_10':  7, 'ER_20':  8, 'ER_30':  9,
                    'GR_5': 10, 'GR_10': 11, 'GR_15': 12,
                }
                _rl_state = _rl_state_bin(
                    _sigma_in, bus_eta_s, _no_act_delay,
                    current_phase == self.BusPhase)
                # Build available-action list and initial Q-seed vector.
                _rl_avail  = []
                _rl_init_q = [0.0] * len(DCTSP_RL_ACTION_SPACE)
                for _rrow in _dctsp_rows:
                    _ai = _RL_LABEL_TO_IDX.get(_rrow[0])
                    if _ai is not None:
                        _rl_avail.append((_ai, _rrow))
                        _rl_init_q[_ai] = _rrow[2]   # raw estimated reward

                # Complete pending TD transition from this bus's previous junction.
                _rl_pending = _dctsp_pending_td.pop(int(veh_id), None)
                if _rl_pending is not None:
                    _pj, _ps, _pa, _pr = _rl_pending
                    _rl_td_err = _rl_update_q(
                        _pj, _ps, _pa, _pr, self.id, _rl_state, _rl_init_q)
                    log_to_file(
                        f"[DCTSP_RL] TD jct={_pj}→{self.id} bus={veh_id} "
                        f"a={_pa} r_prev={_pr:.4f} td_err={_rl_td_err:+.4f}",
                        force=False)

                # ε-greedy selection.
                # Constrain the exploration pool to non-regret candidates:
                # only actions whose estimated reward is >= NO_ACTION reward.
                # This prevents exploration from executing wrong-phase GE
                # (extends the non-bus phase → bus waits longer) or infeasible
                # INS actions that pay cross-traffic cost without helping the bus.
                _rl_na_r = next((rr[2] for rr in _dctsp_rows
                                 if rr[0] == 'NO_ACTION'), 0.0)
                _rl_explore_pool = [(ai, rr) for ai, rr in _rl_avail
                                    if rr[2] >= _rl_na_r]
                if not _rl_explore_pool:  # safety: always keep NO_ACTION in pool
                    _rl_explore_pool = [(ai, rr) for ai, rr in _rl_avail
                                        if rr[0] == 'NO_ACTION'] or _rl_avail[:1]
                _q_vals    = _rl_get_q(self.id, _rl_state, _rl_init_q)
                _rl_explore = _rnd_mod.random() < RL_EPSILON and len(_rl_explore_pool) > 1
                if _rl_explore:
                    _ai_sel, _row_sel = _rnd_mod.choice(_rl_explore_pool)
                else:
                    _ai_sel, _row_sel = max(_rl_avail, key=lambda _x: _q_vals[_x[0]])

                # Override the greedy-best with the RL-selected action.
                _act_lbl        = _row_sel[0]
                # Map label → canonical action type used by dispatch blocks.
                # Standard labels: 'NO_ACTION', 'GE_5', 'INS_10', 'ER_10' etc.
                # split('_')[0] works for GE/INS but 'ER_10' → 'ER' ≠ 'EARLY_RED'.
                if _act_lbl == 'NO_ACTION':
                    _best_type = 'NO_ACTION'
                elif _act_lbl.startswith('ER_'):
                    _best_type = 'EARLY_RED'
                elif _act_lbl.startswith('GR_'):
                    _best_type = 'GREEN_REALLOC'
                else:
                    _best_type = _act_lbl.split('_')[0]   # 'GE', 'INS', etc.
                _best_param     = _row_sel[1]
                _best_r         = _row_sel[2]
                _best_sigma_out = _row_sel[3]
                _best_t_poz     = _row_sel[4]

                # Store pending cross-junction TD transition.
                _dctsp_pending_td[int(veh_id)] = (self.id, _rl_state, _ai_sel, _best_r)
                # Also log entry record for measured-delay terminal update at checkout.
                _poz_action_log[int(veh_id)] = (
                    self.id, _best_type, _best_param, time, _rl_state, _ai_sel)
                log_to_file(
                    f"[DCTSP_RL] jct={self.id} t={time:.1f} bus={veh_id} "
                    f"state={_rl_state} {'EXPLORE' if _rl_explore else 'EXPLOIT'} "
                    f"→ {_act_lbl} Q={_q_vals[_ai_sel]:.4f} r_est={_best_r:.4f}",
                    force=True)
            except StopIteration:
                log_to_file(
                    f"[DCTSP_RL] non-RL override mode — Q-table bypassed",
                    force=False)
            except Exception as _rl_err:
                log_to_file(f"[DCTSP_RL] error: {_rl_err} — keeping greedy choice",
                            force=True)

            # ── Compute improvement delta: actual raw reward retained in rows ──
            # Raw rewards are kept as-is so the CSV shows true values:
            #   INV_DELAY / V2X modes: 0 < reward  (inverse of cost, no upper cap)
            #   MARL mode:             reward in pax·s  (can be negative)
            # The delta (= raw − NO_ACTION raw) is stored alongside for comparison.
            _r_na_raw = _r_na          # NO_ACTION raw reward (baseline for delta)
            _best_r_delta = _best_r - _r_na_raw   # +ve when TSP beats NO_ACTION

            # Conservative gating for bargaining mode:
            #   1) do not act for low estimated bus delay
            #   2) require a minimum reward gain over NO_ACTION
            if BARGAIN_SPM_MODE:
                _bg_gain = _best_r - _r_na_raw
                if (_ensemble_delay < float(BG_MIN_BUS_DELAY_S)
                        or _bg_gain < float(BG_MIN_GAIN_S)):
                    _best_type = 'NO_ACTION'
                    _best_param = 0.0
                    _best_r = _r_na_raw
                    _best_sigma_out = _so_na
                    _best_t_poz = _tp_na
                    _best_r_delta = 0.0
                    log_to_file(
                        f"[BARGAIN_SPM] GATE inter={self.id} t={time:.1f} bus={veh_id} "
                        f"kin_delay={_no_act_delay:.1f}s ens_delay={_ensemble_delay:.1f}s gain={_bg_gain:.2f}s "
                        f"thr_delay={BG_MIN_BUS_DELAY_S:.1f}s thr_gain={BG_MIN_GAIN_S:.1f}s "
                        f"→ NO_ACTION",
                        force=True)

            log_to_file(
                f"[DCTSP] inter={self.id} t={time:.1f} bus={veh_id} "
                f"σ_in={_sigma_in:.0f}s BEST={_best_type}"
                + (f"_{_best_param:.0f}s" if _best_type != 'NO_ACTION' else "")
                + f" r={_best_r:.4f} Δr={_best_r_delta:+.4f} (NA={_r_na_raw:.4f}) "
                f"σ_out={_best_sigma_out:.0f}s T_POZ={_best_t_poz:.1f}s",
                force=True)

            # ── Self-organizing control override (Cesme & Furth 2014 §4 +
            #    IEEE ICARCE 2023 phase-overlap correction) ──────────────────
            # Runs ONLY when REWARD_SELFORG_MODE=True.  The RL block above was
            # skipped entirely (StopIteration), so this rule is the sole
            # decision maker — purely deterministic, no Q-table influence.
            #
            # Phase-overlap correction (IEEE ICARCE 2023):
            #   At intersections where the bus phase overlaps an adjacent phase,
            #   the bus continues moving during the overlap window — so part of
            #   the "no-action delay" is actually covered by the overlap green.
            #   effective_delay = max(0, no_act_delay − SELFORG_PHASE_OVERLAP_S)
            #
            # Decision logic:
            #   1. effective_delay ≥ SELFORG_MIN_BUS_DELAY_S  → consider TSP
            #   2. side_ratio = side_pax_pressure / bus_pax_pressure
            #      side_ratio ≤ SELFORG_BALANCE_FACTOR  → bus side dominates → act
            #      side_ratio  > SELFORG_BALANCE_FACTOR  → cross-street dominates → NO_ACTION
            #   3. SE duration = clip(eff_delay × SE_FRACTION, MIN_SE_S, MAX_SE_S)
            #      rounded to nearest {5, 10, 15, 20}
            #   4. GE if currently on bus phase; INS otherwise
            #   5. effective_delay < SELFORG_MIN_BUS_DELAY_S → keep greedy-best (no override)
            if REWARD_SELFORG_MODE:
                try:
                    _so_other_occ = self._estimated_other_vehicle_occupancy()
                    _so_other_delay_raw = (
                        safe_float(self._safe_array_sum(self.OtherDelay))
                        + safe_float(self._safe_array_sum(
                            getattr(self, 'SideDelayBaseline', np.zeros(1, dtype=float))))
                    )
                    # OtherDelay is only populated in HARMONY/URTSP paths.
                    # In the DCTSP path it is always 0, making the balance check
                    # trivially pass every time (side_ratio = 0 ≤ BALANCE_FACTOR).
                    # Fix: fall back to _dctsp_cross_traffic_delay_s for a realistic
                    # cross-traffic delay estimate when OtherDelay is absent.
                    if _so_other_delay_raw < 1.0:
                        _so_cross_pax_s = self._dctsp_cross_traffic_delay_s(
                            float(SELFORG_MAX_SE_S))
                        # Convert pax·s → veh·s for PCE comparison (see below).
                        _so_car_occ = max(float(self.CarOcc), 1.0)
                        _so_side_veh_s = _so_cross_pax_s / _so_car_occ
                    else:
                        # HARMONY mode: OtherDelay is total vehicle·s from
                        # GE_Objective_Function — already in the right units.
                        _so_side_veh_s = _so_other_delay_raw
                    # Phase-overlap correction: subtract overlap green from delay.
                    _so_eff_delay = max(0.0, float(_no_act_delay)
                                             - float(SELFORG_PHASE_OVERLAP_S))
                    # PCE-weighted balance check (Cesme & Furth 2014 adapted).
                    # Pax·s comparison was broken: bus_occ≈25 vs car_occ≈1.5 means
                    # bus_pressure is always ≈17× side_pressure → ratio≈0.05 always
                    # → balance check NEVER blocked TSP (same failure as OtherDelay=0).
                    # Fix: compare in PCE-equivalents using BUS_PCE=5.
                    #   BUS_PCE=5 is calibrated to match ZIG/INV_DELAY action rates:
                    #   bus_side  = bus_delay × BUS_PCE  (PCE·s)
                    #   car_side  = total_veh·s of cross-traffic delay (veh·s ≈ PCE·s)
                    #   fire when car_side / bus_side ≤ SELFORG_BALANCE_FACTOR
                    # With NF=3, action_s=12s, 400 vph × 2 phases, car_occ=1.5, BUS_PCE=5:
                    #   car_side ≈ 48 veh·s; bus_side = 12s × 5 = 60 → ratio=0.80≤0.85 → fire (borderline)
                    #   bus_side = 20s × 5 = 100 → ratio=0.48≤0.85 → fire (well above min)
                    #   bus_side = 50s × 5 = 250 → ratio=0.19 → always fires for high-delay
                    # BUS_PCE=3 was too small: blocked 150/248 NO_ACTION decisions with
                    # delays > 10s, causing bus delay ≈ NO_TSP level.
                    _BUS_PCE = 5.0  # calibrated: bus ≈ 5 PCE in signal-priority terms
                    _so_bus_pressure  = _so_eff_delay * _BUS_PCE
                    _so_side_pressure = max(0.0, _so_side_veh_s)
                    _so_side_ratio    = _so_side_pressure / max(_so_bus_pressure, 1.0)

                    if _so_eff_delay >= float(SELFORG_MIN_BUS_DELAY_S):
                        if _so_side_ratio <= float(SELFORG_BALANCE_FACTOR):
                            # Bus pressure ≥ side pressure → apply SE.
                            _so_raw_dur = _so_eff_delay * float(SELFORG_SE_FRACTION)
                            _so_dur = float(np.clip(_so_raw_dur,
                                                    float(SELFORG_MIN_SE_S),
                                                    float(SELFORG_MAX_SE_S)))
                            # Select action type first, THEN round to valid candidates.
                            # GE available: DCTSP_GE_ACTIONS = [5, 10, 15] (max 15s).
                            # INS available: DCTSP_INS_DURATIONS = [10, 15, 20] (max 20s).
                            # Using a fixed _so_std=[5,10,15,20] for GE was wrong:
                            #   • GE_20 doesn't exist → silent row-lookup miss.
                            #   • SELFORG_MAX_SE_S=12 → always rounded to 10 (GE_10 every time).
                            # Fix: use the actual available candidates per action type.
                            _so_action = 'GE' if current_phase == self.BusPhase else 'INS'
                            _so_avail  = (list(DCTSP_GE_ACTIONS) if _so_action == 'GE'
                                          else list(DCTSP_INS_DURATIONS))
                            _so_dur = min(_so_avail, key=lambda c: abs(c - _so_dur))
                            log_to_file(
                                f"[SELFORG] SE inter={self.id} t={time:.1f} bus={veh_id} "
                                f"no_act={_no_act_delay:.1f}s overlap={SELFORG_PHASE_OVERLAP_S:.1f}s "
                                f"eff={_so_eff_delay:.1f}s "
                                f"car_veh_s={_so_side_pressure:.1f} "
                                f"bus_pce_s={_so_bus_pressure:.1f} "
                                f"side_ratio={_so_side_ratio:.2f} "
                                f"→ {_so_action}_{_so_dur:.0f}s",
                                force=True)
                            # Override greedy-best with SE rule.
                            # Fallback: if label not found (density guard blocked it),
                            # use the closest evaluated action from _dctsp_rows.
                            _so_label = f"{_so_action}_{int(_so_dur)}"
                            _best_type  = _so_action
                            _best_param = _so_dur
                            _so_found = False
                            for (_r_lbl, _r_par, _r_rew, _r_so, _r_tp,
                                 _r_bps, _r_cpc, _r_nsd, _r_std) in _dctsp_rows:
                                if _r_lbl == _so_label:
                                    _best_r         = _r_rew
                                    _best_sigma_out = _r_so
                                    _best_t_poz     = _r_tp
                                    _best_r_delta   = _best_r - _r_na_raw
                                    _so_found = True
                                    break
                            if not _so_found:
                                # Label not in evaluated rows (density guard skipped it).
                                # Fall back to the best evaluated action of the same type.
                                _so_same_type = [(lbl, par, rew, so, tp)
                                                 for (lbl, par, rew, so, tp, *_)
                                                 in _dctsp_rows
                                                 if lbl.startswith(_so_action + '_')]
                                if _so_same_type:
                                    _fb = max(_so_same_type, key=lambda x: x[2])
                                    _best_type, _best_param = _so_action, _fb[1]
                                    _best_r, _best_sigma_out = _fb[2], _fb[3]
                                    _best_t_poz  = _fb[4]
                                    _best_r_delta = _best_r - _r_na_raw
                                    log_to_file(
                                        f"[SELFORG] fallback: {_so_label} not in rows "
                                        f"→ using {_best_type}_{_best_param:.0f}s",
                                        force=True)
                                else:
                                    # No same-type action available → NO_ACTION
                                    _best_type = 'NO_ACTION'; _best_param = 0.0
                                    _best_r = _r_na_raw; _best_r_delta = 0.0
                                    log_to_file(
                                        f"[SELFORG] fallback: no {_so_action} rows → NO_ACTION",
                                        force=True)
                        else:
                            # Cross-street pressure dominates → NO_ACTION.
                            log_to_file(
                                f"[SELFORG] NO_ACTION inter={self.id} t={time:.1f} "
                                f"bus={veh_id} eff={_so_eff_delay:.1f}s "
                                f"car_veh_s={_so_side_pressure:.1f} "
                                f"bus_pce_s={_so_bus_pressure:.1f} "
                                f"side_ratio={_so_side_ratio:.2f} > "
                                f"{SELFORG_BALANCE_FACTOR:.2f} (side dominates)",
                                force=True)
                            _best_type    = 'NO_ACTION'
                            _best_param   = 0.0
                            _best_r       = _r_na_raw
                            _best_r_delta = 0.0
                    else:
                        # Effective delay below minimum → keep greedy-best, no override.
                        log_to_file(
                            f"[SELFORG] BELOW_MIN inter={self.id} t={time:.1f} "
                            f"bus={veh_id} eff={_so_eff_delay:.1f}s < "
                            f"{SELFORG_MIN_BUS_DELAY_S:.1f}s → greedy {_best_type}"
                            + (f"_{_best_param:.0f}s" if _best_type != 'NO_ACTION' else ""),
                            force=False)
                except Exception as _so_err:
                    log_to_file(f"[SELFORG] error: {_so_err} — keeping greedy best",
                                force=True)

            # ── DCTSP-ZIG shockwave-optimal override ───────────────────────────
            # When DCTSP_ZIG_MODE=True, call dctsp_zig() which returns the best
            # of NO_ACTION / GE / INS_POST / INS_PRETERM using LWR-derived
            # optimal durations.  The result fully replaces the greedy-best from
            # the discrete evaluation above.
            if DCTSP_ZIG_MODE:
                try:
                    _ps_zig   = ECIGetStartingTimePhase(self.node_id)
                    _pd_zig   = GetPhaseDuration(self.node_id, current_phase, timeSta)
                    _rem_zig  = max(0.0, float(_pd_zig) - (float(time) - float(_ps_zig)))
                    (_best_type, _best_param, _best_r, _best_r_delta,
                     _best_sigma_out, _best_t_poz, _zig_rows) = self.dctsp_zig(
                        time, timeSta, acycle, bus_eta_s, veh_id,
                        current_phase, _no_act_delay, _sigma_in,
                        remaining_red_s=_rem_zig)
                    # Use ZIG rows for reward-cycle CSV logging.
                    _dctsp_rows = _zig_rows
                    log_to_file(
                        f"[ZIG] final inter={self.id} t={time:.1f} bus={veh_id} "
                        f"→ {_best_type}_{_best_param:.0f}s "
                        f"r={_best_r:.4f} Δr={_best_r_delta:+.4f}",
                        force=True)
                except Exception as _zig_err:
                    log_to_file(
                        f"[ZIG] error: {_zig_err} — keeping greedy best",
                        force=True)

            # ── DCTSP-MP-ECTM queue-optimisation override ──────────────────────
            # When MP_ECTM_MODE=True, call dctsp_mp_ectm() which solves the MP
            # (Eq. 33-37, Bao et al. 2026) by CTM grid-search over δ and returns
            # the action that minimises total passenger delay Z = bus_delay ×
            # α_bus + side_delay × α_car over a one-cycle horizon.
            # Result fully replaces the greedy-best from the discrete evaluation.
            if MP_ECTM_MODE:
                try:
                    _ps_mp  = ECIGetStartingTimePhase(self.node_id)
                    _pd_mp  = GetPhaseDuration(self.node_id, current_phase, timeSta)
                    _rem_mp = max(0.0,
                                  float(_pd_mp) - (float(time) - float(_ps_mp)))
                    (_best_type, _best_param, _best_r, _best_r_delta,
                     _best_sigma_out, _best_t_poz, _mp_rows) = self.dctsp_mp_ectm(
                        time, timeSta, acycle, bus_eta_s, veh_id,
                        current_phase, _no_act_delay, _sigma_in,
                        remaining_red_s=_rem_mp)
                    _dctsp_rows = _mp_rows
                    log_to_file(
                        f"[MP_ECTM] final inter={self.id} t={time:.1f} bus={veh_id} "
                        f"→ {_best_type}_{_best_param:.0f}s "
                        f"r={_best_r:.4f} Δr={_best_r_delta:+.4f}",
                        force=True)
                except Exception as _mp_err:
                    log_to_file(
                        f"[MP_ECTM] error: {_mp_err} — keeping greedy best",
                        force=True)

            # ── DCTSP-BXT CTM Q-learning override ────────────────────────────
            if BXT_MODE:
                try:
                    _ps_bxt  = ECIGetStartingTimePhase(self.node_id)
                    _pd_bxt  = GetPhaseDuration(self.node_id, current_phase, timeSta)
                    _rem_bxt = max(0.0, float(_pd_bxt) - (float(time) - float(_ps_bxt)))
                    (_best_type, _best_param, _best_r, _best_r_delta,
                     _best_sigma_out, _best_t_poz, _bxt_rows) = self.dctsp_bxt(
                        time, timeSta, acycle, bus_eta_s, veh_id,
                        current_phase, _no_act_delay, _sigma_in,
                        remaining_red_s=_rem_bxt)
                    _dctsp_rows = _bxt_rows
                    log_to_file(
                        f"[BXT] final inter={self.id} t={time:.1f} bus={veh_id} "
                        f"→ {_best_type}_{_best_param:.0f}s "
                        f"r={_best_r:.4f} Δr={_best_r_delta:+.4f}",
                        force=True)
                except Exception as _bxt_err:
                    log_to_file(
                        f"[BXT] error: {_bxt_err} — keeping greedy best",
                        force=True)

            # ── DCTSP-META_TSP system-optimal adaptive override ───────────────
            # When META_TSP_MODE=True, call dctsp_meta() which minimises total
            # system passenger delay with an adaptive bus weight that scales with
            # headway deviation.  Result fully replaces the greedy-best from the
            # discrete evaluation above.
            if META_TSP_MODE:
                try:
                    _ps_meta  = ECIGetStartingTimePhase(self.node_id)
                    _pd_meta  = GetPhaseDuration(self.node_id, current_phase, timeSta)
                    _rem_meta = max(0.0, float(_pd_meta) - (float(time) - float(_ps_meta)))
                    log_to_file(
                        f"[META_TSP] START inter={self.id} t={time:.1f} bus={veh_id} "
                        f"eta={bus_eta_s:.1f}s phase={current_phase} "
                        f"rem={_rem_meta:.1f}s no_act_delay={_no_act_delay:.1f}s "
                        f"sigma_in={_sigma_in:.1f}s",
                        force=True)
                    (_best_type, _best_param, _best_r, _best_r_delta,
                     _best_sigma_out, _best_t_poz, _meta_rows) = self.dctsp_meta(
                        time, timeSta, acycle, bus_eta_s, veh_id,
                        current_phase, _no_act_delay, _sigma_in,
                        remaining_red_s=_rem_meta)
                    _dctsp_rows = _meta_rows
                    log_to_file(
                        f"[META_TSP] RESULT inter={self.id} t={time:.1f} bus={veh_id} "
                        f"→ {_best_type}_{_best_param:.0f}s "
                        f"r={_best_r:.4f} Δr={_best_r_delta:+.4f}",
                        force=True)
                except Exception as _meta_err:
                    log_to_file(
                        f"[META_TSP] ERROR inter={self.id} t={time:.1f}: {_meta_err}",
                        force=True)

            # ── Entry record for measured delay feedback at checkout ───────────
            # Store for ALL strategies (MARL, SELFORG, ZIG, MP_ECTM) so
            # [POZ_MEASURED] log and terminal Q-update (MARL only) always have
            # the entry time.  MARL overrides this record inside the RL block
            # when its Q-table path runs; here we cover SELFORG, ZIG, MP_ECTM.
            if int(veh_id) not in _poz_action_log:
                _poz_action_log[int(veh_id)] = (
                    self.id, _best_type, _best_param, time, None, None)

            # Store predictions for validation at POZ checkout (pred vs actual).
            # Keyed by veh_id; overwritten if bus is re-detected (keeps freshest).
            _dctsp_pred_store[int(veh_id)] = (
                self.id, time, bus_eta_s,
                _ensemble_delay, _no_act_delay, _dd1_delay_s, _mb_delay_s)

            # ── Reward-cycle CSV (powers the State-Action Diagnosis chart) ────
            # Columns:
            #   reward       — actual raw reward (0–1 for INV_DELAY/V2X, pax·s for MARL)
            #   reward_delta — raw reward minus NO_ACTION reward (+ve = improvement)
            #   no_action_reward — raw NO_ACTION reward for this decision cycle
            #   other_delay_model_pax_s — OtherDelay shockwave model estimate (pax·s)
            #   measured_car_pax_s_cumul — cumulative intersection car delay from Aimsun
            #     (monotonically increasing; subtract consecutive rows for per-cycle delta)
            #   no_act_delay_s — _reward_estimate_no_action result (bus delay if no TSP)
            # Every bus×junction decision cycle writes one row per candidate action
            # (including NO_ACTION) so the diagnostics always total
            # n_buses × n_intersections rows for the chosen column.
            try:
                import csv as _csv_mod
                # Compute debug context values for this decision cycle.
                # NOTE: self.OtherDelay is always 0 for DCTSP (it is only populated
                # by the legacy GE_Objective_Function shockwave model which is not
                # called on the DCTSP code path).  Use the actual cross-traffic cost
                # model that drives DCTSP rewards instead:
                #   • MDN mode: _mdn_na_pax_s = total intersection pax·s under NO_ACTION
                #   • All other modes: _dctsp_cross_traffic_delay_s(bus_phase_duration)
                #     = UpFlowList-based pax·s cost for one full bus-phase of priority.
                _bp_dur_odm = float(getattr(self, 'BusPhaseDuration', 30) or 30)
                if MDN_DELAY_MODE and _mdn_na_pax_s > 0.0:
                    _other_delay_model_pax_s = _mdn_na_pax_s
                else:
                    _other_delay_model_pax_s = self._dctsp_cross_traffic_delay_s(_bp_dur_odm)
                # Store the RAW (NF=1) version for validation chart comparison.
                # _dctsp_cross_traffic_delay_s already multiplies by NETWORK_FACTOR,
                # which is a decision bias (not a calibration target).  The validation
                # chart should compare raw triangle vs. actual Aimsun — dividing by NF
                # here gives the NF=1 estimate so the 45° line is meaningful.
                _nf_val = max(float(NETWORK_FACTOR), 1.0)
                _other_delay_model_pax_s_nf1 = (
                    _mdn_na_pax_s if (MDN_DELAY_MODE and _mdn_na_pax_s > 0.0)
                    else _other_delay_model_pax_s / _nf_val
                )
                _measured_car_pax_s_cumul = 0.0
                if stats_ok and hasattr(self.stats, '_inter'):
                    _measured_car_pax_s_cumul = float(
                        self.stats._inter.get(self.id, {}).get('delay_car', 0.0) or 0.0)
                # Per-event delta (for direct model-vs-actual comparison in dashboard).
                global _reward_csv_prev_state
                _prev_cumul, _prev_t = _reward_csv_prev_state.get(self.id, (0.0, 0.0))
                _measured_car_pax_s_delta = max(0.0, _measured_car_pax_s_cumul - _prev_cumul)
                _interval_s = max(0.0, float(time) - _prev_t)
                _reward_csv_prev_state[self.id] = (_measured_car_pax_s_cumul, float(time))
                # Use file-existence check instead of a module global so that
                # each new timestamped CSV always gets a header, even if the
                # module was not reloaded between Aimsun experiments.
                _rchw = os.path.isfile(_REWARD_CYCLE_CSV) and os.path.getsize(_REWARD_CYCLE_CSV) > 0
                with open(_REWARD_CYCLE_CSV, "a", newline="", encoding="utf-8") as _rcf:
                    _rcw = _csv_mod.writer(_rcf)
                    if not _rchw:
                        _rcw.writerow([
                            "sim_time_s", "junction_id", "veh_id", "bus_eta_s",
                            "current_phase", "action",
                            "reward", "reward_delta", "no_action_reward",
                            "sigma_in_s", "sigma_out_s", "t_poz_s",
                            "bus_saved_pax_s", "other_inc_pax_s",
                            "no_strategy_delay_pax_s", "strategy_min_delay_pax_s",
                            "is_chosen",
                            "other_delay_model_pax_s", "other_delay_model_pax_s_nf1",
                            "measured_car_pax_s_cumul",
                            "no_act_delay_s", "bus_occ",
                            "dd1_delay_s", "mb_delay_s", "ensemble_delay_s",
                            "measured_car_pax_s_delta", "interval_s", "bp_dur_s",
                            "network_factor",
                        ])
                    # Map _best_type to the abbreviated CSV-row label (GR_5, ER_BP_10 etc.)
                    _type_to_prefix = {'GE': 'GE', 'INS': 'INS', 'GREEN_REALLOC': 'GR'}
                    if _best_type == 'NO_ACTION':
                        _chosen_label = 'NO_ACTION'
                    elif _best_type == 'EARLY_RED':
                        # ER_BP when on bus phase, ER when on cross phase
                        # Find the matching row in _dctsp_rows (ER_N or ER_BP_N)
                        _er_match = next(
                            (r[0] for r in _dctsp_rows
                             if r[0].startswith('ER') and abs(r[1] - _best_param) < 0.5
                             and r[2] == _best_r),
                            next((r[0] for r in _dctsp_rows
                                  if r[0].startswith('ER') and abs(r[1] - _best_param) < 0.5),
                                 f'ER_BP_{_best_param:.0f}'))
                        _chosen_label = _er_match
                    else:
                        _pfx = _type_to_prefix.get(_best_type, _best_type)
                        _chosen_label = f'{_pfx}_{_best_param:.0f}'
                    for _act, _param, _r, _so, _tp, _bps, _cpc, _nsd, _std in _dctsp_rows:
                        _rcw.writerow([
                            round(time, 1), self.id, int(veh_id or -1),
                            round(bus_eta_s, 1), current_phase,
                            _act,
                            round(_r, 4), round(_r - _r_na_raw, 4), round(_r_na_raw, 4),
                            round(_sigma_in, 1), round(_so, 1), round(_tp, 1),
                            round(_bps, 2), round(_cpc, 2),
                            round(_nsd, 2), round(_std, 2),
                            1 if _act == _chosen_label else 0,
                            round(_other_delay_model_pax_s, 2),
                            round(_other_delay_model_pax_s_nf1, 2),
                            round(_measured_car_pax_s_cumul, 2),
                            round(_no_act_delay, 2),
                            round(float(self.BusOcc), 1),
                            round(_dd1_delay_s, 2),
                            round(_mb_delay_s, 2),
                            round(_ensemble_delay, 2),
                            round(_measured_car_pax_s_delta, 2),
                            round(_interval_s, 1),
                            round(_bp_dur_odm, 1),
                            round(_nf_val, 1),
                        ])
            except Exception as _rce:
                log_to_file(f"[DCTSP_CSV] write error: {_rce}")

            # Record CPD signal for global aggregation (use delta: improvement over baseline)
            _record_intersection_reward(self.id, _best_r_delta)

            # ── Corridor wave-event (powers the Coordination Flow chart) ─────
            _coord_grp = (self._corridor_coord.name
                          if self._corridor_coord is not None else 'dctsp')
            _record_wave_event(
                time, _coord_grp,
                f"dctsp_{_best_type.lower()}",
                source_jct=self.id, target_jct=self.id,
                veh_id=int(veh_id or -1),
                eta_s=round(bus_eta_s, 1),
                note=(f"{_best_type}"
                      + (f"_{_best_param:.0f}s" if _best_type != 'NO_ACTION' else "")
                      + f"_r={_best_r:.4f}_Δr={_best_r_delta:+.4f}"),
            )

            if _best_type == 'NO_ACTION':
                self._reward_no_action_until = time + 5.0
                # Record: bus chose DO_NOTHING — guard still set so re-detection
                # in the same approach cycle doesn't trigger a second evaluation.
                self._dctsp_set_acted(veh_id, 'NO_ACTION', 0.0, time)
                if stats_ok:
                    self.stats.record_tsp_event(self.id, 'detection')
                    self.stats.record_tsp_skip(self.id, 'reward_no_action')
                _mark_detection_point(
                    self.id, int(veh_id or -1), 0.0, 0.0, time,
                    "harmony-no-ge-local",
                    {"force_write": True, "prearm_status": "skip",
                     "prearm_eta_s": round(bus_eta_s, 1),
                     "prearm_note": f"DCTSP NO_ACTION r={_best_r:.4f} Δr={_best_r_delta:+.4f}"})
                if COORDINATED_TSP and self._corridor_coord is not None:
                    try:
                        self._corridor_coord.notify_bus_granted(veh_id, self.id, time, None)
                    except Exception:
                        pass
                return

            if _best_type == 'GE':
                _ps   = ECIGetStartingTimePhase(self.node_id)
                _pd   = GetPhaseDuration(self.node_id, current_phase, timeSta)
                _rem  = max(0.0, _pd - (time - _ps))
                ECIChangeTimingPhase(self.node_id, current_phase,
                                     self.BusPhaseDuration + _best_param, timeSta)
                self.TimeToTerminateBusPhase = time + _rem + _best_param
                self.TSPStrategy  = 1; self.flag = 1
                self.TSPActiveTime = time + _best_param + 30
                self._tsp_cycle_grant_until = time + self.config.get('CycleTime', 135)
                self.last_tsp_action_time   = time
                self._ge_debt_s = _best_param
                # Guard: this bus has used its one action at this junction
                self._dctsp_set_acted(veh_id, 'GE', _best_param, time)
                _ge_events.append((time, self.id, _best_param, _best_r_delta))
                self.highlight_bus(veh_id)
                if stats_ok:
                    self.stats.record_tsp_event(self.id, 'detection')
                    self.stats.record_tsp_event(self.id, 'extension')
                    self.stats.record_tsp_extension_duration(self.id, _best_param)
                # ── observability: coordination-example + bus-delay objective ──
                _mark_detection_point(
                    self.id, int(veh_id or -1), 0.0, 0.0, time,
                    "harmony-ge-local",
                    {"force_write": True, "prearm_status": "action",
                     "prearm_eta_s": round(bus_eta_s, 1),
                     "prearm_note": f"DCTSP GE_{_best_param:.0f}s r={_best_r:.4f} Δr={_best_r_delta:+.4f}"})
                self.stats.store_objective_stats(
                    bus_delay  = max(0.0, _no_act_delay) * self.BusOcc,
                    other_delay= 0.0,
                    avg_pass_delay = abs(_best_r_delta) * self.BusOcc,
                )
                log_to_file(
                    f"[GREEN_GRANT] inter={self.id} t={time:.1f} bus={veh_id} "
                    f"eta={bus_eta_s:.1f}s type=DCTSP_GE GE={_best_param:.1f}s "
                    f"r={_best_r:.4f} Δr={_best_r_delta:+.4f} σ_in={_sigma_in:.0f}s",
                    force=True)
                if veh_id and veh_id > 0:
                    _acquire_focus(veh_id, self.id, time)
                if COORDINATED_TSP and self._corridor_coord is not None:
                    try:
                        self._corridor_coord.notify_bus_granted(veh_id, self.id, time, None)
                    except Exception:
                        pass
                _off = _aggregate_global_reward_as_offset_s(self.BusOcc)
                _apply_offset_to_next_intersection(self.id, _off)
                _reset_global_reward_buffer()
                return

            if _best_type == 'INS':
                self.previous_phase  = current_phase
                self.BusPhaseEndTime = time + _best_param
                ECIChangeTimingPhase(self.id, self.BusPhase, _best_param, timeSta)
                ECIChangeDirectPhase(self.id, self.BusPhase, timeSta, time, acycle, 0)
                self.TSPStrategy  = 2; self.flag = 2
                self.TSPActiveTime = time + _best_param + 30
                self._ge_debt_s   = _best_param
                self._tsp_cycle_grant_until = time + self.config.get('CycleTime', 135)
                self.last_tsp_action_time   = time
                # Guard: this bus has used its one action at this junction
                self._dctsp_set_acted(veh_id, 'INS', _best_param, time)
                self.highlight_bus(veh_id)
                if stats_ok:
                    self.stats.record_tsp_event(self.id, 'detection')
                    self.stats.record_tsp_event(self.id, 'insertion')
                    self.stats.record_tsp_insertion_duration(self.id, _best_param)
                    self.stats.record_tsp_insertion_wait(self.id, max(0.0, bus_eta_s))
                # ── observability: coordination-example + bus-delay objective ──
                _mark_detection_point(
                    self.id, int(veh_id or -1), 0.0, 0.0, time,
                    "harmony-ins-local",
                    {"force_write": True, "prearm_status": "action",
                     "prearm_eta_s": round(bus_eta_s, 1),
                     "prearm_note": f"DCTSP INS_{_best_param:.0f}s r={_best_r:.4f} Δr={_best_r_delta:+.4f}"})
                self.stats.store_objective_stats(
                    bus_delay  = max(0.0, _no_act_delay) * self.BusOcc,
                    other_delay= 0.0,
                    avg_pass_delay = abs(_best_r_delta) * self.BusOcc,
                )
                log_to_file(
                    f"[GREEN_GRANT] inter={self.id} t={time:.1f} bus={veh_id} "
                    f"eta={bus_eta_s:.1f}s type=DCTSP_INS BP={_best_param:.1f}s "
                    f"r={_best_r:.4f} Δr={_best_r_delta:+.4f} σ_in={_sigma_in:.0f}s",
                    force=True)
                if veh_id and veh_id > 0:
                    _acquire_focus(veh_id, self.id, time)
                if COORDINATED_TSP and self._corridor_coord is not None:
                    try:
                        self._corridor_coord.notify_bus_granted(veh_id, self.id, time, None)
                    except Exception:
                        pass
                _off = _aggregate_global_reward_as_offset_s(self.BusOcc)
                _apply_offset_to_next_intersection(self.id, _off)
                _reset_global_reward_buffer()
                return

            if _best_type == 'INS_POST':
                # Phase insertion after the current phase ends naturally.
                # Set the bus-phase duration; do NOT force a phase switch —
                # the signal sequence runs naturally to the bus phase.
                self.previous_phase  = current_phase
                self.BusPhaseEndTime = time + _best_param
                ECIChangeTimingPhase(self.id, self.BusPhase, _best_param, timeSta)
                # No ECIChangeDirectPhase: relies on natural sequence to bus phase.
                self.TSPStrategy  = 2; self.flag = 2
                self.TSPActiveTime = time + _best_param + 30
                self._ge_debt_s   = _best_param
                self._tsp_cycle_grant_until = time + self.config.get('CycleTime', 135)
                self.last_tsp_action_time   = time
                self._dctsp_set_acted(veh_id, 'INS_POST', _best_param, time)
                self.highlight_bus(veh_id)
                if stats_ok:
                    self.stats.record_tsp_event(self.id, 'detection')
                    self.stats.record_tsp_event(self.id, 'insertion')
                    self.stats.record_tsp_insertion_duration(self.id, _best_param)
                    self.stats.record_tsp_insertion_wait(self.id, max(0.0, bus_eta_s))
                _mark_detection_point(
                    self.id, int(veh_id or -1), 0.0, 0.0, time,
                    "harmony-ins-local",
                    {"force_write": True, "prearm_status": "action",
                     "prearm_eta_s": round(bus_eta_s, 1),
                     "prearm_note": (f"DCTSP INS_POST_{_best_param:.0f}s "
                                    f"r={_best_r:.4f} Δr={_best_r_delta:+.4f}")})
                self.stats.store_objective_stats(
                    bus_delay  = max(0.0, _no_act_delay) * self.BusOcc,
                    other_delay= 0.0,
                    avg_pass_delay = abs(_best_r_delta) * self.BusOcc,
                )
                log_to_file(
                    f"[GREEN_GRANT] inter={self.id} t={time:.1f} bus={veh_id} "
                    f"eta={bus_eta_s:.1f}s type=DCTSP_INS_POST BP={_best_param:.1f}s "
                    f"r={_best_r:.4f} Δr={_best_r_delta:+.4f} σ_in={_sigma_in:.0f}s",
                    force=True)
                if veh_id and veh_id > 0:
                    _acquire_focus(veh_id, self.id, time)
                if COORDINATED_TSP and self._corridor_coord is not None:
                    try:
                        self._corridor_coord.notify_bus_granted(veh_id, self.id, time, None)
                    except Exception:
                        pass
                _off = _aggregate_global_reward_as_offset_s(self.BusOcc)
                _apply_offset_to_next_intersection(self.id, _off)
                _reset_global_reward_buffer()
                return

            if _best_type == 'INS_PRETERM':
                # Phase insertion with immediate pre-termination of current phase.
                # 1. Truncate current phase to elapsed_s + INS_INTERGREEN_S.
                # 2. Set bus-phase duration and force immediate switch.
                _ps      = ECIGetStartingTimePhase(self.node_id)
                _elapsed = max(0.0, time - _ps)
                _trunc   = _elapsed + float(INS_INTERGREEN_S)
                ECIChangeTimingPhase(self.node_id, current_phase, _trunc, timeSta)
                self.previous_phase  = current_phase
                self.BusPhaseEndTime = time + _best_param
                ECIChangeTimingPhase(self.id, self.BusPhase, _best_param, timeSta)
                ECIChangeDirectPhase(self.id, self.BusPhase, timeSta, time, acycle, 0)
                self.TSPStrategy  = 2; self.flag = 2
                self.TSPActiveTime = time + _best_param + 30
                self._ge_debt_s   = _best_param
                self._tsp_cycle_grant_until = time + self.config.get('CycleTime', 135)
                self.last_tsp_action_time   = time
                self._dctsp_set_acted(veh_id, 'INS_PRETERM', _best_param, time)
                self.highlight_bus(veh_id)
                if stats_ok:
                    self.stats.record_tsp_event(self.id, 'detection')
                    self.stats.record_tsp_event(self.id, 'insertion')
                    self.stats.record_tsp_insertion_duration(self.id, _best_param)
                    self.stats.record_tsp_insertion_wait(self.id, max(0.0, bus_eta_s))
                _mark_detection_point(
                    self.id, int(veh_id or -1), 0.0, 0.0, time,
                    "harmony-ins-local",
                    {"force_write": True, "prearm_status": "action",
                     "prearm_eta_s": round(bus_eta_s, 1),
                     "prearm_note": (f"DCTSP INS_PRETERM_{_best_param:.0f}s "
                                    f"(trunc={_trunc:.1f}s) "
                                    f"r={_best_r:.4f} Δr={_best_r_delta:+.4f}")})
                self.stats.store_objective_stats(
                    bus_delay  = max(0.0, _no_act_delay) * self.BusOcc,
                    other_delay= 0.0,
                    avg_pass_delay = abs(_best_r_delta) * self.BusOcc,
                )
                log_to_file(
                    f"[GREEN_GRANT] inter={self.id} t={time:.1f} bus={veh_id} "
                    f"eta={bus_eta_s:.1f}s type=DCTSP_INS_PRETERM "
                    f"trunc={_trunc:.1f}s BP={_best_param:.1f}s "
                    f"r={_best_r:.4f} Δr={_best_r_delta:+.4f} σ_in={_sigma_in:.0f}s",
                    force=True)
                if veh_id and veh_id > 0:
                    _acquire_focus(veh_id, self.id, time)
                if COORDINATED_TSP and self._corridor_coord is not None:
                    try:
                        self._corridor_coord.notify_bus_granted(veh_id, self.id, time, None)
                    except Exception:
                        pass
                _off = _aggregate_global_reward_as_offset_s(self.BusOcc)
                _apply_offset_to_next_intersection(self.id, _off)
                _reset_global_reward_buffer()
                return

            if _best_type == 'EARLY_RED':
                # Early red: truncate the current non-bus phase early so the bus
                # phase arrives sooner in the natural signal cycle.  NO extra bus
                # green is inserted — the bus gets only its normally-scheduled green.
                # Unlike INS_PRETERM, we do NOT call ECIChangeDirectPhase; the
                # controller simply lets the natural phase sequence run from the
                # truncated current phase through to the bus phase.
                _ps_er   = ECIGetStartingTimePhase(self.node_id)
                _pd_er   = GetPhaseDuration(self.node_id, current_phase, timeSta)
                _rem_er  = max(0.0, float(_pd_er) - (float(time) - float(_ps_er)))
                _cut_er  = min(float(_best_param),
                               max(0.0, _rem_er - float(INS_INTERGREEN_S)))
                _elapsed_er = max(0.0, float(time) - float(_ps_er))
                _trunc_er   = _elapsed_er + (_rem_er - _cut_er)
                ECIChangeTimingPhase(self.node_id, current_phase, _trunc_er, timeSta)
                # Natural phase progression leads to bus phase; no forced switch.
                self.previous_phase = current_phase
                self.TSPStrategy    = 2; self.flag = 2
                self.TSPActiveTime  = time + (_rem_er - _cut_er) + 60.0
                self._tsp_cycle_grant_until = time + self.config.get('CycleTime', 135)
                self.last_tsp_action_time   = time
                self._dctsp_set_acted(veh_id, 'EARLY_RED', _cut_er, time)
                self.highlight_bus(veh_id)
                if stats_ok:
                    self.stats.record_tsp_event(self.id, 'detection')
                    self.stats.record_tsp_event(self.id, 'insertion')  # counted as TSP insertion
                    self.stats.record_tsp_insertion_duration(self.id, _cut_er)
                    self.stats.record_tsp_insertion_wait(self.id, max(0.0, bus_eta_s))
                _mark_detection_point(
                    self.id, int(veh_id or -1), 0.0, 0.0, time,
                    "harmony-ins-local",
                    {"force_write": True, "prearm_status": "action",
                     "prearm_eta_s": round(bus_eta_s, 1),
                     "prearm_note": (f"DCTSP EARLY_RED cut={_cut_er:.0f}s "
                                    f"(trunc={_trunc_er:.1f}s) "
                                    f"r={_best_r:.4f} Δr={_best_r_delta:+.4f}")})
                self.stats.store_objective_stats(
                    bus_delay  = max(0.0, _no_act_delay) * self.BusOcc,
                    other_delay= 0.0,
                    avg_pass_delay = abs(_best_r_delta) * self.BusOcc,
                )
                log_to_file(
                    f"[GREEN_GRANT] inter={self.id} t={time:.1f} bus={veh_id} "
                    f"eta={bus_eta_s:.1f}s type=DCTSP_EARLY_RED "
                    f"cut={_cut_er:.1f}s trunc={_trunc_er:.1f}s "
                    f"r={_best_r:.4f} Δr={_best_r_delta:+.4f} σ_in={_sigma_in:.0f}s",
                    force=True)
                if veh_id and veh_id > 0:
                    _acquire_focus(veh_id, self.id, time)
                if COORDINATED_TSP and self._corridor_coord is not None:
                    try:
                        self._corridor_coord.notify_bus_granted(veh_id, self.id, time, None)
                    except Exception:
                        pass
                _off = _aggregate_global_reward_as_offset_s(self.BusOcc)
                _apply_offset_to_next_intersection(self.id, _off)
                _reset_global_reward_buffer()
                return

            if _best_type == 'GREEN_REALLOC':
                _gr_right_phase = (current_phase == self.BusPhase)

                if _gr_right_phase:
                    # ── Right-phase GR: extend current bus phase (zero-cost GE) ──
                    # Apply as a GE on the active bus phase; the recovery from the
                    # next non-bus phase is implicit (we accepted zero car cost
                    # in the reward model).
                    _ps_gr   = ECIGetStartingTimePhase(self.node_id)
                    _pd_gr   = GetPhaseDuration(self.node_id, current_phase, timeSta)
                    ECIChangeTimingPhase(self.node_id, current_phase,
                                         self.BusPhaseDuration + _best_param, timeSta)
                    _rem_gr  = max(0.0, float(_pd_gr) - (float(time) - float(_ps_gr)))
                    self.TimeToTerminateBusPhase = time + _rem_gr + _best_param
                    self.TSPStrategy  = 1; self.flag = 1
                    self.TSPActiveTime = time + _best_param + 30
                    self._tsp_cycle_grant_until = time + self.config.get('CycleTime', 135)
                    self.last_tsp_action_time   = time
                    self._ge_debt_s = _best_param   # recovery scheduled implicitly
                    self._dctsp_set_acted(veh_id, 'GREEN_REALLOC', _best_param, time)
                    self.highlight_bus(veh_id)
                    if stats_ok:
                        self.stats.record_tsp_event(self.id, 'detection')
                        self.stats.record_tsp_event(self.id, 'extension')
                        self.stats.record_tsp_extension_duration(self.id, _best_param)
                    _mark_detection_point(
                        self.id, int(veh_id or -1), 0.0, 0.0, time,
                        "harmony-ge-local",
                        {"force_write": True, "prearm_status": "action",
                         "prearm_eta_s": round(bus_eta_s, 1),
                         "prearm_note": (f"DCTSP GREEN_REALLOC(right) ext={_best_param:.0f}s "
                                         f"r={_best_r:.4f} Δr={_best_r_delta:+.4f}")})
                    log_to_file(
                        f"[GREEN_GRANT] inter={self.id} t={time:.1f} bus={veh_id} "
                        f"eta={bus_eta_s:.1f}s type=DCTSP_GREEN_REALLOC_RIGHT "
                        f"ext={_best_param:.1f}s r={_best_r:.4f} Δr={_best_r_delta:+.4f} "
                        f"σ_in={_sigma_in:.0f}s",
                        force=True)
                    if veh_id and veh_id > 0:
                        _acquire_focus(veh_id, self.id, time)
                    if COORDINATED_TSP and self._corridor_coord is not None:
                        try:
                            self._corridor_coord.notify_bus_granted(veh_id, self.id, time, None)
                        except Exception:
                            pass
                    _off = _aggregate_global_reward_as_offset_s(self.BusOcc)
                    _apply_offset_to_next_intersection(self.id, _off)
                    _reset_global_reward_buffer()
                    return

                else:
                    # ── Wrong-phase GR: cut current non-bus phase (original path) ─
                    _ps_gr   = ECIGetStartingTimePhase(self.node_id)
                    _pd_gr   = GetPhaseDuration(self.node_id, current_phase, timeSta)
                    _rem_gr  = max(0.0, float(_pd_gr) - (float(time) - float(_ps_gr)))
                    _cut_gr  = min(float(_best_param),
                                   max(0.0, _rem_gr - float(INS_INTERGREEN_S)))
                    if _cut_gr <= 0.0:
                        self._reward_no_action_until = time + 5.0
                        self._dctsp_set_acted(veh_id, 'NO_ACTION', 0.0, time)
                        return
                    _elapsed_gr = max(0.0, float(time) - float(_ps_gr))
                    _trunc_gr   = _elapsed_gr + (_rem_gr - _cut_gr)
                    ECIChangeTimingPhase(self.node_id, current_phase, _trunc_gr, timeSta)

                    _bus_nom = float(getattr(self, 'BusPhaseDuration', 30) or 30)
                    _bus_new = max(float(self.config.get('MinGreen', 5.0)),
                                   _bus_nom - _cut_gr * float(GREEN_REALLOC_RECOVER_FRACTION))
                    ECIChangeTimingPhase(self.id, self.BusPhase, _bus_new, timeSta)

                    self.previous_phase = current_phase
                    self.TSPStrategy    = 2; self.flag = 2
                    self.TSPActiveTime  = time + (_rem_gr - _cut_gr) + 60.0
                    self._tsp_cycle_grant_until = time + self.config.get('CycleTime', 135)
                    self.last_tsp_action_time   = time
                    self._ge_debt_s = 0.0
                    self._dctsp_set_acted(veh_id, 'GREEN_REALLOC', _cut_gr, time)
                    self.highlight_bus(veh_id)
                    if stats_ok:
                        self.stats.record_tsp_event(self.id, 'detection')
                        self.stats.record_tsp_event(self.id, 'insertion')
                        self.stats.record_tsp_insertion_duration(self.id, _cut_gr)
                        self.stats.record_tsp_insertion_wait(self.id, max(0.0, bus_eta_s))
                    _mark_detection_point(
                        self.id, int(veh_id or -1), 0.0, 0.0, time,
                        "harmony-ins-local",
                        {"force_write": True, "prearm_status": "action",
                         "prearm_eta_s": round(bus_eta_s, 1),
                         "prearm_note": (f"DCTSP GREEN_REALLOC cut={_cut_gr:.0f}s "
                                         f"(bus_new={_bus_new:.1f}s) "
                                         f"r={_best_r:.4f} Δr={_best_r_delta:+.4f}")})
                    log_to_file(
                        f"[GREEN_GRANT] inter={self.id} t={time:.1f} bus={veh_id} "
                        f"eta={bus_eta_s:.1f}s type=DCTSP_GREEN_REALLOC "
                        f"cut={_cut_gr:.1f}s trunc={_trunc_gr:.1f}s bus_new={_bus_new:.1f}s "
                        f"r={_best_r:.4f} Δr={_best_r_delta:+.4f} σ_in={_sigma_in:.0f}s",
                        force=True)
                    if veh_id and veh_id > 0:
                        _acquire_focus(veh_id, self.id, time)
                    if COORDINATED_TSP and self._corridor_coord is not None:
                        try:
                            self._corridor_coord.notify_bus_granted(veh_id, self.id, time, None)
                        except Exception:
                            pass
                    _off = _aggregate_global_reward_as_offset_s(self.BusOcc)
                    _apply_offset_to_next_intersection(self.id, _off)
                    _reset_global_reward_buffer()
                    return
          except Exception as _dctsp_e:
            log_to_file(
                f"[DCTSP] inter={self.id} t={time:.1f} eval failed: {_dctsp_e} "
                f"— falling through to NO_ACTION",
                force=True)
            # Fall through: simulation continues unaffected; bus gets no TSP this step
        # ── end GLOBAL_REWARD_MODE path ───────────────────────────────────────

        # Action 0: NO_ACTION
        no_action_bus_delay = self._reward_estimate_no_action(time, timeSta, bus_eta_s)
        no_action_bus_cost = max(0.0, no_action_bus_delay) * max(safe_float(self.BusOcc), 0.0)
        density_no_action = self._reward_density_penalty(0.0)
        reward_no_action = 0.0
        _mpc_mode = (CONTROL_MODE == "MPC_TSP")
        _dens_live, _ge_cap_s, _allow_ins, _guard_mode = self._reward_density_guardrail(bus_eta_s)

        def _decision_score(immediate_reward, bus_saved, projected_debt_s, projected_offset_s, action_dur_s):
            if not _mpc_mode:
                return float(immediate_reward)
            try:
                _residual_bus = max(0.0, float(no_action_bus_cost) - max(0.0, float(bus_saved)))
                _occ = max(1.0, float(self._estimated_other_vehicle_occupancy()))
                _dens_term = max(0.0, float(_dens_live) - float(REWARD_DENSITY_SOFT_VKM))
                _terminal = (
                    - float(MPC_RESIDUAL_BUS_GAIN) * _residual_bus
                    - float(MPC_TERMINAL_DEBT_GAIN) * max(0.0, float(projected_debt_s)) * _occ
                    - float(MPC_TERMINAL_OFFSET_GAIN) * max(0.0, float(projected_offset_s)) * _occ
                    - float(MPC_TERMINAL_DENSITY_GAIN) * _dens_term * max(0.0, float(action_dur_s))
                )
                return float(immediate_reward) + float(MPC_DISCOUNT) * _terminal
            except Exception:
                return float(immediate_reward)

        decision_no_action = _decision_score(
            reward_no_action, -no_action_bus_cost, 0.0, 0.0, 0.0)

        best_action = "NO_ACTION"
        best_reward = reward_no_action
        best_decision_score = decision_no_action
        best_ge = 0.0
        _ge_skipped_cap = 0
        _ge_inapplicable_cycle = 0

        # Per-cycle reward log: accumulate one row per candidate, write once at end.
        _reward_rows = []
        # NO_ACTION: reward = -α·bus_cost; no savings on others; store baseline bus cost
        # in bus_saved_pax_s as a negative (cost, not saving) so analysts can read it.
        _reward_rows.append((
            "NO_ACTION", reward_no_action,
            -no_action_bus_cost, 0.0, 0.0, density_no_action, 0.0, 0,
            _ge_inapplicable_cycle, 0.0, 0.0, 0.0, decision_no_action))

        log_to_file(
            f"[REWARD_TSP] inter={self.id} t={time:.1f} bus={veh_id} "
            f"eta={bus_eta_s:.1f}s phase={current_phase} "
            f"R(NO_ACTION)={reward_no_action:.1f} "
            f"dens={_dens_live:.2f} guard={_guard_mode} ge_cap={_ge_cap_s:.1f} "
            f"ins_ok={1 if _allow_ins else 0}")

        if current_phase == self.BusPhase:
            # ── Evaluate GE candidates ────────────────────────────────────
            _ps = ECIGetStartingTimePhase(self.node_id)
            _pd = GetPhaseDuration(self.node_id, current_phase, timeSta)
            _remain = max(0.0, _pd - (time - _ps))
            next_red = time + _remain
            # Consume future_offset_s set by upstream GLOBAL_REWARD_MODE:
            # a positive offset means the upstream intersection had a good
            # CPD outcome and suggests we should allow a slightly longer GE.
            # Reset after reading so it only influences one cycle.
            _future_ge_bonus = max(0.0, getattr(self, 'future_offset_s', 0.0))
            if _future_ge_bonus > 0.0:
                self.future_offset_s = 0.0
                log_to_file(
                    f"[GLOBAL_REWARD] inter={self.id} consuming future_offset={_future_ge_bonus:.1f}s "
                    f"as GE cap bonus")
            else:
                _future_ge_bonus = 0.0
            if no_action_bus_delay <= REWARD_GE_MIN_DELAY_S:
                _ge_inapplicable_cycle = 1
                _reward_rows[0] = (
                    _reward_rows[0][0], _reward_rows[0][1], _reward_rows[0][2],
                    _reward_rows[0][3], _reward_rows[0][4], _reward_rows[0][5],
                    _reward_rows[0][6], _reward_rows[0][7], _ge_inapplicable_cycle,
                    _reward_rows[0][9], _reward_rows[0][10], _reward_rows[0][11], _reward_rows[0][12],
                )
                log_to_file(
                    f"[REWARD_TSP] inter={self.id} GE skipped: inapplicable "
                    f"(no_action_bus_delay={no_action_bus_delay:.2f}s <= {REWARD_GE_MIN_DELAY_S:.2f}s)")
            else:
                _effective_ge_cap = min(_ge_cap_s + _future_ge_bonus, MAX_GE_EXTENSION_S)
                for ge_s in REWARD_GE_CANDIDATES:
                    if ge_s > MAX_GE_EXTENSION_S:
                        continue
                    if ge_s > _effective_ge_cap:
                        _ge_skipped_cap += 1
                        continue
                    # NOTE: No hard recoverable cap here — the reward function already
                    # penalises cycle expansion via other_inc (delay on cross traffic).
                    # Capping by recoverable headroom was blocking all GE > 5 s when
                    # phases are short (6–8 s nominal), forcing avg_extension = 5.0 s.

                    reward, bus_saved, other_inc, side_inc, throughput_gap, future_penalty, projected_debt, projected_offset = self._reward_evaluate_ge(
                        ge_s, time, timeSta, bus_eta_s)
                    _decision = _decision_score(
                        reward, bus_saved, projected_debt, projected_offset, ge_s)
                    density_inc = self._reward_density_penalty(ge_s)
                    _infeasible = 1 if throughput_gap < -REWARD_THROUGHPUT_TOL else 0
                    _reward_rows.append((
                        f"GE_{ge_s:.0f}", reward, bus_saved, other_inc, side_inc,
                        density_inc, throughput_gap, _infeasible, _ge_inapplicable_cycle,
                        future_penalty, projected_debt, projected_offset, _decision,
                    ))

                    log_to_file(
                        f"[REWARD_TSP] inter={self.id} "
                        f"R(GE_{ge_s:.0f})={reward:.1f} "
                        f"bus_saved={bus_saved:.1f} other={other_inc:.1f} "
                        f"side={side_inc:.1f} density={density_inc:.1f} "
                        f"future={future_penalty:.1f} debt={projected_debt:.1f}s off={projected_offset:.1f}s "
                        f"score={_decision:.1f} "
                        f"side_mult={self._reward_side_multiplier(ge_s):.2f} "
                        f"act_cost={self._reward_action_cost_penalty('GE', ge_s):.2f} "
                        f"throughput_gap={throughput_gap:.2f}")

                    if _decision > best_decision_score:
                        best_decision_score = _decision
                        best_reward = reward
                        best_action = f"GE_{ge_s:.0f}"
                        best_ge = ge_s
        else:
            # ── Evaluate INSERTION ────────────────────────────────────────
            if not _allow_ins:
                self._reward_diag['ins_blocked_density_guard'] += 1
                log_to_file(
                    f"[REWARD_TSP] inter={self.id} INS skipped by density guard "
                    f"(dens={_dens_live:.2f}, mode={_guard_mode}, eta={bus_eta_s:.1f}s)")
            else:
                ins_dur = min(float(self.BP_upper_bound),
                              max(float(self.BP_lower_bound), bus_eta_s + 5.0))
                reward_ins, bus_saved, other_inc, side_inc, throughput_gap, future_penalty, projected_debt, projected_offset = self._reward_evaluate_insertion(
                    ins_dur, time, timeSta, bus_eta_s)
                _decision = _decision_score(
                    reward_ins, bus_saved, projected_debt, projected_offset, ins_dur)
                density_inc = self._reward_density_penalty(ins_dur + 5.0)
                _infeasible = 1 if throughput_gap < -REWARD_THROUGHPUT_TOL else 0
                _reward_rows.append((
                    f"INS_{ins_dur:.0f}", reward_ins, bus_saved, other_inc, side_inc,
                    density_inc, throughput_gap, _infeasible, _ge_inapplicable_cycle,
                    future_penalty, projected_debt, projected_offset, _decision,
                ))

                log_to_file(
                    f"[REWARD_TSP] inter={self.id} "
                    f"R(INS_{ins_dur:.0f})={reward_ins:.1f} "
                    f"bus_saved={bus_saved:.1f} other={other_inc:.1f} "
                    f"side={side_inc:.1f} density={density_inc:.1f} "
                    f"future={future_penalty:.1f} debt={projected_debt:.1f}s off={projected_offset:.1f}s "
                    f"score={_decision:.1f} "
                    f"side_mult={self._reward_side_multiplier(ins_dur + 5.0):.2f} "
                    f"act_cost={self._reward_action_cost_penalty('INS', ins_dur):.2f} "
                    f"throughput_gap={throughput_gap:.2f}")

                if _decision > best_decision_score:
                    best_decision_score = _decision
                    best_reward = reward_ins
                    best_action = f"INS_{ins_dur:.0f}"
                    best_ge = ins_dur

        # ── Write per-cycle reward CSV ────────────────────────────────────────
        global _reward_cycle_header_written
        try:
            _upflow_bus  = round(float(self.UpFlowList[0][0]), 1)  if self.UpFlowList.shape[1]  > 0 else 0.0
            _maxq_bus    = round(float(self.MaxQueueLength[0][0]), 1) if self.MaxQueueLength.shape[1] > 0 else 0.0
            _reddur_bus  = round(float(self.RedDurationList[0][0]), 1) if self.RedDurationList.shape[1] > 0 else 0.0
            with open(_REWARD_CYCLE_CSV, "a", newline="", encoding="utf-8") as _rcf:
                import csv as _csv_mod
                _rcw = _csv_mod.writer(_rcf)
                if not _reward_cycle_header_written:
                    _rcw.writerow([
                        "sim_time_s", "junction_id", "veh_id", "bus_eta_s",
                        "current_phase", "action",
                        "reward", "bus_saved_pax_s", "other_inc_pax_s", "side_inc_pax_s", "density_inc_pax_s",
                        "throughput_gap_veh", "throughput_infeasible",
                        "ge_inapplicable_cycle",
                        "future_penalty_pax_s", "projected_debt_s", "projected_offset_s",
                        "decision_score",
                        "is_chosen",
                        "upflow_bus_vph", "max_queue_bus_veh", "red_dur_bus_s",
                    ])
                    _reward_cycle_header_written = True
                for _act, _r, _bs, _oi, _si, _di, _tg, _inf, _ge_na, _fp, _pd, _po, _ds in _reward_rows:
                    _rcw.writerow([
                        round(time, 1), self.id, int(veh_id or -1),
                        round(bus_eta_s, 1), current_phase,
                        _act,
                        round(_r, 3), round(_bs, 3), round(_oi, 3), round(_si, 3), round(_di, 3),
                        round(_tg, 3), int(_inf),
                        int(_ge_na),
                        round(_fp, 3), round(_pd, 3), round(_po, 3),
                        round(_ds, 3),
                        1 if _act == best_action else 0,
                        _upflow_bus, _maxq_bus, _reddur_bus,
                    ])
        except Exception as _rce:
            log_to_file(f"[REWARD_CYCLE_CSV] write error: {_rce}")

        # ── Record detection (debounce-guarded) ──────────────────────────────
        if stats_ok:
            self.stats.record_tsp_event(self.id, 'detection')

        # ── Execute best action ───────────────────────────────────────────────
        if best_action == "NO_ACTION":
            _alt_rows = [
                _rw for _rw in _reward_rows
                if isinstance(_rw, tuple) and len(_rw) >= 2 and _rw[0] != "NO_ACTION"
            ]
            _metric_idx = 12 if _mpc_mode else 1
            _alt_best_reward = max((float(_rw[_metric_idx]) for _rw in _alt_rows), default=-1e9)
            _alt_best_action = "NONE"
            if _alt_rows:
                _alt_best_action = max(_alt_rows, key=lambda _rw: float(_rw[_metric_idx]))[0]

            _na_reason = "no_positive_action"
            if current_phase == self.BusPhase and _ge_inapplicable_cycle:
                _na_reason = "ge_inapplicable"
            elif current_phase != self.BusPhase and not _allow_ins:
                _na_reason = "ins_guard_block"
            elif _alt_best_reward > 0.01:
                _na_reason = "positive_alt_not_chosen"

            self._reward_diag['no_action'] += 1
            self._reward_diag[f"no_action_{_na_reason}"] += 1
            self._reward_diag['ge_skipped_cap'] += int(_ge_skipped_cap)
            if _alt_best_reward > 0.01:
                self._reward_diag['no_action_alt_positive'] += 1

            # Debounce: suppress re-evaluation for 5 s so we don't flood the
            # log with identical NO_ACTION decisions on every simulation step.
            self._reward_no_action_until = time + 5.0
            if stats_ok:
                self.stats.record_tsp_skip(self.id, 'reward_no_action')
            log_to_file(
                f"[REWARD_TSP] inter={self.id} t={time:.1f} bus={veh_id} "
                f"eta={bus_eta_s:.1f}s DECISION=NO_ACTION R={best_reward:.1f} score={best_decision_score:.1f} "
                f"reason={_na_reason} alt_best={_alt_best_action}:{_alt_best_reward:.1f} "
                f"(cost to others outweighs bus benefit)")
            # Record for Coordination Example chart (no-action path)
            _no_action_tier = (
                "harmony-no-ge-local"
                if current_phase == self.BusPhase
                else "harmony-no-ins-local"
            )
            _mark_detection_point(
                self.id, veh_id or -1, 0.0, 0.0, time,
                _no_action_tier,
                {
                    "force_write": True,
                    "prearm_status": "skip",
                    "prearm_eta_s": round(max(0.0, float(bus_eta_s)), 1),
                    "prearm_note": f"NO_ACTION R={best_reward:.1f}",
                },
            )
            # Still propagate corridor coordination
            if REWARD_ENABLE_PREARM and self._corridor_coord is not None and COORDINATED_TSP:
                try:
                    self._corridor_coord.notify_bus_granted(
                        veh_id, self.id, time, None)
                except Exception:
                    pass
            _emit_reward_diag_if_due()
            return

        if best_action.startswith("GE"):
            self._reward_diag['action_ge'] += 1
            self._reward_diag['ge_skipped_cap'] += int(_ge_skipped_cap)
            # Apply green extension
            _ps = ECIGetStartingTimePhase(self.node_id)
            _pd = GetPhaseDuration(self.node_id, current_phase, timeSta)
            remain = _pd - (time - _ps)
            ECIChangeTimingPhase(self.node_id, current_phase,
                                 self.BusPhaseDuration + best_ge, timeSta)
            self.TimeToTerminateBusPhase = time + remain + best_ge
            self.TSPStrategy  = 1
            self.flag         = 1
            self.TSPActiveTime = time + best_ge + 30
            self._tsp_cycle_grant_until = time + self.config.get('CycleTime', 135)
            self.last_tsp_action_time   = time
            self._ge_debt_s = best_ge
            self._ge_opt_GE = best_ge
            _ge_events.append((time, self.id, best_ge, best_reward))
            self.highlight_bus(veh_id)
            self.stats.record_tsp_event(self.id, 'extension')
            self.stats.record_tsp_extension_duration(self.id, best_ge)
            # Accumulate priority budget usage
            if not hasattr(self, '_priority_used_s'):
                self._priority_used_s = 0.0
                self._priority_window_start = time
            self._priority_used_s += best_ge
            _mark_detection_point(
                self.id, veh_id or -1, 0.0, 0.0, time,
                "harmony-ge-local",
                {
                    "force_write": True,
                    "prearm_status": "action",
                    "prearm_eta_s": round(max(0.0, float(bus_eta_s)), 1),
                    "prearm_note": f"GE {best_ge:.1f}s R={best_reward:.1f}",
                },
            )
            if veh_id and veh_id > 0:
                _acquire_focus(veh_id, self.id, time)
            if REWARD_ENABLE_PREARM and self._corridor_coord is not None and COORDINATED_TSP:
                try:
                    self._corridor_coord.notify_bus_granted(
                        veh_id, self.id, time, None)
                except Exception:
                    pass
            log_to_file(
                f"[REWARD_TSP] inter={self.id} t={time:.1f} bus={veh_id} "
                f"eta={bus_eta_s:.1f}s DECISION={best_action} GE={best_ge:.1f}s "
                f"R={best_reward:.1f} score={best_decision_score:.1f}")
            # ── GLOBAL_REWARD: push CPD signal to next intersection only ──
            if GLOBAL_REWARD_MODE:
                _off = _aggregate_global_reward_as_offset_s(self.BusOcc)
                _apply_offset_to_next_intersection(self.id, _off)
                _reset_global_reward_buffer()
            _emit_reward_diag_if_due()

        elif best_action.startswith("INS_"):
            self._reward_diag['action_ins'] += 1
            self._reward_diag['ge_skipped_cap'] += int(_ge_skipped_cap)
            # Apply phase insertion — first set the BusPhase duration so
            # Aimsun holds it for opt_BP seconds, then force the switch.
            self.previous_phase  = current_phase
            self.BusPhaseEndTime = time + best_ge
            ECIChangeTimingPhase(self.id, self.BusPhase, best_ge, timeSta)
            ECIChangeDirectPhase(self.id, self.BusPhase, timeSta, time, acycle, 0)
            self.TSPStrategy  = 2
            self.flag         = 2
            self.TSPActiveTime = time + best_ge + 30
            self._ge_debt_s   = best_ge   # spread cost across remaining phases
            self._tsp_cycle_grant_until = time + self.config.get('CycleTime', 135)
            self.last_tsp_action_time   = time
            self.highlight_bus(veh_id)
            self.stats.record_tsp_event(self.id, 'insertion')
            self.stats.record_tsp_insertion_duration(self.id, best_ge)
            self.stats.record_tsp_insertion_wait(self.id, max(0.0, bus_eta_s))
            # Accumulate priority budget usage
            if not hasattr(self, '_priority_used_s'):
                self._priority_used_s = 0.0
                self._priority_window_start = time
            self._priority_used_s += best_ge
            _mark_detection_point(
                self.id, veh_id or -1, 0.0, 0.0, time,
                "harmony-ins-local",
                {
                    "force_write": True,
                    "prearm_status": "action",
                    "prearm_eta_s": round(max(0.0, float(bus_eta_s)), 1),
                    "prearm_note": f"INS {best_ge:.1f}s R={best_reward:.1f}",
                },
            )
            if veh_id and veh_id > 0:
                _acquire_focus(veh_id, self.id, time)
            if REWARD_ENABLE_PREARM and self._corridor_coord is not None and COORDINATED_TSP:
                try:
                    self._corridor_coord.notify_bus_granted(
                        veh_id, self.id, time, None)
                except Exception:
                    pass
            log_to_file(
                f"[REWARD_TSP] inter={self.id} t={time:.1f} bus={veh_id} "
                f"eta={bus_eta_s:.1f}s DECISION=INS BP={best_ge:.1f}s "
                f"R={best_reward:.1f} score={best_decision_score:.1f}")
            # ── GLOBAL_REWARD: push CPD signal to next intersection only ──
            if GLOBAL_REWARD_MODE:
                _off = _aggregate_global_reward_as_offset_s(self.BusOcc)
                _apply_offset_to_next_intersection(self.id, _off)
                _reset_global_reward_buffer()
            _emit_reward_diag_if_due()

    def _reward_get_recoverable(self, current_phase, timeSta):
        """Compute recoverable headroom from upcoming phases (same as HARMONY cap logic)."""
        _min_floor = float(self.config.get('MinGreen', 5.0))
        _max_trim_frac = 0.50
        _phase_list = getattr(self, 'phase_list', [])
        if not _phase_list or current_phase not in _phase_list:
            return 999.0
        _ci = _phase_list.index(current_phase)
        _n = len(_phase_list)
        _upcoming = [_phase_list[(_ci + _k) % _n] for _k in range(1, _n)]
        _upcoming = [p for p in _upcoming if p != self.BusPhase and p != current_phase]
        _recoverable = 0.0
        for _ph in _upcoming:
            _nom = self._nominal_phase_durations.get(_ph)
            if _nom is None:
                try:
                    _nom = GetPhaseDuration(self.node_id, _ph, timeSta)
                except Exception:
                    _nom = 15.0
                if not _nom or _nom <= 0:
                    _nom = 15.0
            _nom = max(float(_nom), _min_floor)
            _hr = max(0.0, _nom - _min_floor)
            _hr = min(_hr, _nom * _max_trim_frac)
            _recoverable += _hr
        return _recoverable

    def run_normal(self, time, timeSta, acycle):
        """Passive baseline — data collection only, no signal changes.

        Still records bus detections (mark_detection_point + stats) so that
        NORMAL mode produces detection counts comparable to HARMONY, and the
        batch results show how many buses were 'seen' without TSP action.
        """

        # Reset reward buffer at start of each cycle if in global mode
        if GLOBAL_REWARD_MODE and self.id == min(controllers.keys()):
            _reset_global_reward_buffer()

        busTypePos = self.bus_type_pos

        # Primary: physical detector crossing this cycle
        busCallActive = any(
            AKIDetGetCounterCyclebyId(det, busTypePos) > 0
            for det in self.BusDet)
        # Fallback: position-based scan (detect_bus already ran this step)
        if not busCallActive:
            busCallActive = any(
                self.BusPresence[0][i] > 0
                for i in range(len(self.BusDet)))

        # ── Passive detection recording ───────────────────────────────────────
        # Track which detector slots are newly presenting a bus this step.
        # Use a set on self to avoid counting the same bus twice per approach.
        if not hasattr(self, '_normal_det_active'):
            self._normal_det_active = set()   # slots currently presenting

        _newly_detected = False
        for i, det in enumerate(self.BusDet):
            _presence = self.BusPresence[0][i] if i < len(self.BusPresence[0]) else 0
            _counter  = AKIDetGetCounterCyclebyId(det, busTypePos)
            _active   = (_presence > 0) or (_counter > 0)
            if _active and i not in self._normal_det_active:
                # New bus arrival at this detector slot
                self._normal_det_active.add(i)
                _newly_detected = True
                _vid = int(self.last_detected_bus_id) if hasattr(self, 'last_detected_bus_id') else -1
                _mark_detection_point(
                    junction_id=self.id,
                    veh_id=_vid,
                    x=0.0, y=0.0,
                    sim_time=time,
                    tier="NORMAL-detect",
                )
                self.stats.record_tsp_event(self.id, 'detection')
                # Check if the bus phase is currently green (natural green)
                _is_natural = False
                try:
                    _cur_ph = ECIGetCurrentPhase(self.id)
                    if _cur_ph == self.BusPhase:
                        _is_natural = True
                except Exception:
                    pass
                if _is_natural:
                    self.stats.record_tsp_skip(self.id, 'natural_green')
                else:
                    self.stats.record_tsp_skip(self.id, 'no_action')
                try:
                    self.stats.record_pt_bus_detection(self.id, _vid, time)
                except Exception:
                    pass
            elif not _active and i in self._normal_det_active:
                self._normal_det_active.discard(i)

        # Periodic diagnostic — log det counters + BusPresence every 5 minutes
        _diag_t = int(time) // 300
        if _diag_t != getattr(self, '_run_normal_diag_t', -1):
            self._run_normal_diag_t = _diag_t
            counters = [AKIDetGetCounterCyclebyId(d, busTypePos) for d in self.BusDet]
            presence = self.BusPresence[0].tolist()
            log_to_file(
                f"[NORMAL DIAG] t={time:.0f}s inter={self.id} "
                f"det_counters={counters} BusPresence={presence} "
                f"busCallActive={busCallActive} newly_det={_newly_detected}")

    def _apply_cycle_recovery(self, timeSta: float):
        """
        Proportionally shorten the remaining phases in the current cycle to
        recover the time stolen by a green extension.

        Algorithm
        ---------
        1. Build the ordered list of phases AFTER the current one in this cycle.
        2. For each candidate phase (skip BusPhase — already served):
               nominal  = ECIGetDurationsPhase(phase)
               min_dur  = config MinGreen or 5 s hard floor
               headroom = nominal - min_dur   (how much can be trimmed)
               fraction = headroom / total_headroom_remaining
               trim     = min(fraction * debt, headroom)
               new_dur  = nominal - trim
               ECIChangeTimingPhase(phase, new_dur, ...)
        3. Accumulate actual trimmed; update _ge_debt_s with any residual
           (can't always recover 100% if minimums bind).

        Both GE (flag==1) and phase insertion (flag==2) trigger this.
        For insertion, _ge_debt_s is set to opt_BP at insertion time so the
        cost is spread over remaining phases when the insertion ends.
        """
        # Global reward offset is now applied in run_reward_tsp immediately after
        # a GE/INS grant, targeting only the next downstream intersection.
        # Do NOT apply here — _apply_cycle_recovery fires too often (every cycle).

        if self._ge_debt_s <= 0.5:
            self._ge_debt_s = 0.0
            return

        current_phase = ECIGetCurrentPhase(self.node_id)
        phase_list    = getattr(self, 'phase_list', [])
        if not phase_list or current_phase not in phase_list:
            self._ge_debt_s = 0.0
            return

        # Build ordered list of phases still to run this cycle (after current)
        ci = phase_list.index(current_phase)
        n  = len(phase_list)
        upcoming = [phase_list[(ci + k) % n] for k in range(1, n)]
        # Exclude BusPhase (just completed) and current phase
        upcoming = [p for p in upcoming if p != self.BusPhase and p != current_phase]

        if not upcoming:
            self._ge_debt_s = 0.0
            return

        # Gather nominals (always from stored originals, never from a trimmed plan)
        # and minimum floors.
        min_floor   = float(self.config.get('MinGreen', 5.0))
        # Safety cap: never trim more than 50 % of any single phase's nominal.
        max_trim_frac = 0.50
        nominals  = {}
        headrooms = {}
        for ph in upcoming:
            # Prefer the stored nominal from before any trimming happened.
            nom = self._nominal_phase_durations.get(ph)
            if nom is None:
                try:
                    nom = GetPhaseDuration(self.node_id, ph, timeSta)
                except Exception:
                    nom = 15.0
                if not nom or nom <= 0:
                    nom = 15.0
                # Lock in the original value so subsequent GEs don't compound.
                self._nominal_phase_durations[ph] = float(nom)
            nom = max(float(nom), min_floor)
            hr  = max(0.0, nom - min_floor)
            # Apply 50 % cap
            hr  = min(hr, nom * max_trim_frac)
            nominals[ph]  = nom
            headrooms[ph] = hr

        total_headroom = sum(headrooms.values())
        if total_headroom < 0.5:
            # Phases already at minimum — can't recover
            self._ge_debt_s = 0.0
            return

        debt          = self._ge_debt_s
        total_trimmed = 0.0

        for ph in upcoming:
            hr = headrooms[ph]
            if hr <= 0.0 or debt <= 0.0:
                continue
            # Proportional share of the debt for this phase
            trim    = min(hr, debt * (hr / total_headroom))
            new_dur = nominals[ph] - trim
            try:
                ECIChangeTimingPhase(self.node_id, ph, new_dur, timeSta)
            except Exception:
                continue
            total_trimmed += trim
            debt          -= trim
            # Schedule restoration to nominal at the start of the next cycle.
            # This prevents permanent drift: trimmed durations only apply for
            # the recovery cycle, not all subsequent cycles.
            self._phases_to_restore[ph] = nominals[ph]

        self._ge_debt_s = max(0.0, debt)   # residual (if minimums bound)

        # Back-fill recovery amount into the most recent _ge_events entry
        # for this intersection so the schedule-recovery plot can show it.
        for _i in range(len(_ge_events) - 1, -1, -1):
            if _ge_events[_i][1] == self.id:
                _t, _iid, _ge, _rec = _ge_events[_i]
                _ge_events[_i] = (_t, _iid, _ge, _rec + total_trimmed)
                break

        if LOG_HARMONY:
            _vprint(
                f"[HARMONY] Cycle recovery inter={self.id} "
                f"GE={self._ge_opt_GE:.1f}s trimmed={total_trimmed:.1f}s "
                f"residual={self._ge_debt_s:.1f}s phases={upcoming} "
                f"restore_scheduled={list(self._phases_to_restore.keys())}"
            )
        else:
            log_to_file(
                f"[HARMONY] Cycle recovery inter={self.id} "
                f"GE={self._ge_opt_GE:.1f}s trimmed={total_trimmed:.1f}s "
                f"residual={self._ge_debt_s:.1f}s phases={upcoming}"
            )

    def restore_phase_if_needed(self, time, timeSta, acycle):
        global _focus_bus_id, _focus_jct_id, _focus_passed_jcts
        current_phase = ECIGetCurrentPhase(self.node_id)

        # ── Safety restore: force nominal plan at cycle boundary ────────────
        # If a prior recovery/update path missed restoration bookkeeping,
        # this guard reasserts nominal durations when BusPhase starts.
        # It prevents permanent drift of phase durations across cycles.
        if current_phase == self.BusPhase:
            if not getattr(self, '_nominal_safety_restore_fired', False):
                _n_safety = 0
                for _ph, _nom in (self._nominal_phase_durations or {}).items():
                    try:
                        _cur = float(GetPhaseDuration(self.node_id, _ph, timeSta) or 0.0)
                    except Exception:
                        _cur = float(_nom)
                    if abs(_cur - float(_nom)) > 0.5:
                        try:
                            ECIChangeTimingPhase(self.node_id, _ph, float(_nom), timeSta)
                            _n_safety += 1
                        except Exception:
                            pass
                if _n_safety > 0:
                    log_to_file(
                        f"[HARMONY] Nominal safety restore inter={self.id} restored {_n_safety} phase durations"
                    )
                self._nominal_safety_restore_fired = True
        else:
            self._nominal_safety_restore_fired = False

        # ── Restore phases trimmed by cycle recovery in the PREVIOUS cycle ───
        # When BusPhase next becomes current (start of a new cycle) we reset
        # any phases that were shortened for cycle recovery back to their
        # original nominal durations so trimming doesn't accumulate over time.
        if self._phases_to_restore:
            if current_phase == self.BusPhase:
                if not self._restore_fired_this_cycle:
                    _n_restored = 0
                    for _ph, _nom in self._phases_to_restore.items():
                        try:
                            ECIChangeTimingPhase(self.node_id, _ph, _nom, timeSta)
                            _n_restored += 1
                        except Exception:
                            pass
                    if _n_restored:
                        log_to_file(
                            f"[HARMONY] Nominal restore inter={self.id} "
                            f"restored {_n_restored} phases to plan durations"
                        )
                    self._phases_to_restore.clear()
                    self._restore_fired_this_cycle = True
            else:
                self._restore_fired_this_cycle = False

        # ── Flag 1: GREEN EXTENSION ─────────────────────────────────────────
        # Primary end: Aimsun naturally advanced past BusPhase (phase changed).
        # Fallback:    TimeToTerminateBusPhase elapsed (safety timer).
        if self.flag == 1:
            phase_ended = (current_phase != self.BusPhase)
            timed_out   = (time > self.TimeToTerminateBusPhase)
            if phase_ended or timed_out:
                ECIChangeTimingPhase(
                    self.id, self.BusPhase, self.BusPhaseDuration, timeSta)
                if timed_out and not phase_ended:
                    ECIEnableEventsActivatingPhase(
                        self.id, self.BusPhase + 1, 0.0, time)
                self.flag        = 0
                self.TSPStrategy = 0
                self.reset_bus_color(self.last_detected_bus_id)
                # Record POZ checkout for T̄_POZ tracking (DC TSP Eq. 6)
                if GLOBAL_REWARD_MODE:
                    _co_vid = int(getattr(self, 'last_detected_bus_id', -1) or -1)
                    if _co_vid > 0:
                        self._dctsp_record_poz_checkout(_co_vid, time)
                # ── Release global bus focus (only when wave truly idle) ───
                _defer_focus_release = False
                if self._corridor_coord is not None and COORDINATED_TSP:
                    try:
                        _same_focus_bus = (
                            _focus_bus_id > 0
                            and int(self.last_detected_bus_id or -1) == int(_focus_bus_id)
                        )
                        _coord_has_pending = (
                            bool(getattr(self._corridor_coord, '_pre_requests', {}))
                            or bool(getattr(self._corridor_coord, '_wave_active', False))
                        )
                        _defer_focus_release = _same_focus_bus and _coord_has_pending
                    except Exception:
                        _defer_focus_release = False
                if _defer_focus_release:
                    if _focus_jct_id >= 0 and _focus_jct_id != self.id:
                        _focus_passed_jcts.add(_focus_jct_id)
                    _focus_jct_id = self.id
                    if LOG_HARMONY:
                        _vprint(
                            f"[BUS_FOCUS] t={time:.1f} inter={self.id} "
                            f"defer release after GE (downstream wave pending)")
                else:
                    _release_focus(time, "harmony_ge_done")
                # ── Cycle recovery: spread the GE debt across remaining phases
                self._apply_cycle_recovery(timeSta)
                if LOG_HARMONY:
                    _vprint(
                        f"[HARMONY] GE ended | t={time:.1f}s "
                        f"reason={'phase_change' if phase_ended else 'timeout'} "
                        f"inter={self.id}")

        # ── Flag 2: PHASE INSERTION ─────────────────────────────────────────
        # Primary end: BusPhase naturally ended (Aimsun advanced past it).
        # Fallback:    BusPhaseEndTime elapsed.
        # In both cases: restore interrupted phase explicitly — Aimsun does
        # NOT return to the interrupted phase automatically after insertion.
        if self.flag == 2:
            phase_ended = (current_phase != self.BusPhase)
            timed_out   = (time > self.BusPhaseEndTime)
            if phase_ended or timed_out:
                ECIChangeTimingPhase(
                    self.id, self.BusPhase, self.BusPhaseDuration, timeSta)
                if (self.previous_phase
                        and self.previous_phase > 0
                        and current_phase != self.previous_phase):
                    ECIChangeDirectPhase(
                        self.id, self.previous_phase,
                        timeSta, time, acycle, 0)
                self.flag        = 0
                self.TSPStrategy = 0
                _defer_focus_release = False
                if self._corridor_coord is not None and COORDINATED_TSP:
                    try:
                        _same_focus_bus = (
                            _focus_bus_id > 0
                            and int(self.last_detected_bus_id or -1) == int(_focus_bus_id)
                        )
                        _coord_has_pending = (
                            bool(getattr(self._corridor_coord, '_pre_requests', {}))
                            or bool(getattr(self._corridor_coord, '_wave_active', False))
                        )
                        _defer_focus_release = _same_focus_bus and _coord_has_pending
                    except Exception:
                        _defer_focus_release = False
                if _defer_focus_release:
                    if _focus_jct_id >= 0 and _focus_jct_id != self.id:
                        _focus_passed_jcts.add(_focus_jct_id)
                    _focus_jct_id = self.id
                    if LOG_HARMONY:
                        _vprint(
                            f"[BUS_FOCUS] t={time:.1f} inter={self.id} "
                            f"defer release after INS (downstream wave pending)")
                else:
                    _release_focus(time, "harmony_ins_done")
                # ── Cycle recovery: recover the insertion's time cost from
                # the remaining phases this cycle (same as GE recovery).
                self._apply_cycle_recovery(timeSta)
                if LOG_HARMONY:
                    _vprint(
                        f"[HARMONY] Insertion ended | t={time:.1f}s "
                        f"reason={'phase_change' if phase_ended else 'timeout'} "
                        f"restored_phase={self.previous_phase} inter={self.id}")

    def collect_delay(self, time, timeSta=None):
        self.step_delay = 0.0
        weighted_delay  = 0.0
        # Use timeSta (stats interval start) for partial stats if available;
        # AKIEstGetParcialStatisticsSection expects the interval start time.
        stat_time = timeSta if timeSta is not None else time

        inter_state = self.stats._inter.get(self.id, {})
        main_secs   = set(inter_state.get('main_sections', []))
        side_secs   = set(inter_state.get('side_sections', []))

        # --- resolve side sections -------------------------------------------
        # Priority 1: already stored in inter_state (populated by Stats at init
        #             or by a previous collect_delay call below).
        # Priority 2: try the Stats topology method (PyANGKernel GKSystem).
        # Priority 3: fall back to the controller's own AAPI-based discovery
        #             (_cached_side_sections built by _auto_discover_side_sections)
        #             which uses AKIInfNetGetNbTurnsInNode / GetOriginSectionInTurn
        #             and is guaranteed to work in this Aimsun 26 environment.
        
        # --- resolve side sections (FIXED PRIORITY CHAIN) ---
        #    1️⃣ Always prefer controller AAPI discovery (correct section IDs)
        try:
            controller_side = set(self._get_side_sections())
        except Exception:
            controller_side = set()

        if controller_side:
            side_secs = controller_side
            inter_state['side_sections'] = list(sorted(side_secs))
            inter_state['side_sections_resolved'] = True

        # 2️⃣ Only fallback to stats topology if controller found nothing
        elif main_secs or self.incoming_sections:
            # Use whichever main set is available: stats-registered or topology-derived
            _main_for_topo = main_secs if main_secs else set(self.incoming_sections)
            try:
                resolved_side = self.stats._side_sections_from_topology(
                    self.id, list(_main_for_topo))
                side_secs = set(int(s) for s in resolved_side
                                if s and int(s) not in _main_for_topo)
                if side_secs:
                    inter_state['side_sections'] = list(sorted(side_secs))
                    inter_state['side_sections_resolved'] = True
            except Exception:
                side_secs = set()
        
        
        # --- resolve main sections -------------------------------------------
        # When inter_state has no main_sections (detector IDs were invalid at
        # init time), fall back to the controller's incoming_sections set, which
        # is derived live from the BusDet detector properties.
        if not main_secs:
            main_secs = set(self.incoming_sections)

        # Only subtract main from side if the side sections were NOT resolved
        # by Stats topology (PyANGKernel).  For topology-fallback junctions
        # (no detectors), main_secs contains ALL incoming sections from AAPI,
        # while side_secs was correctly derived by PyANGKernel.  Subtracting
        # would incorrectly remove legitimate side sections.
        if not inter_state.get('side_sections_resolved', False):
            side_secs -= main_secs
        else:
            # Side sections resolved by Stats topology — remove them from
            # main_secs to prevent double-counting delay.
            main_secs -= side_secs

        all_delay_secs = set(self.incoming_sections) | main_secs | side_secs

        # Refresh SideUpFlowList so the signal-timing delay estimator has current
        # arrival rates.  This runs every step in all modes (including NORMAL) —
        # previously it only ran inside update_queue_model (TSP processing only).
        if side_secs:
            try:
                self._sample_side_sections(time)
            except Exception:
                pass

        # One-time diagnostic: verify real sections, test AKIEst/AKIVehState access
        if not getattr(self, '_delay_secs_logged', False):
            self._delay_secs_logged = True
            _diag_side = {}
            for _ds in side_secs:
                _nveh_raw = -9999
                try:
                    _nveh_raw = int(AKIVehStateGetNbVehiclesSection(_ds, True))
                except Exception:
                    _nveh_raw = -9999
                _in_dynamic_sim = (_nveh_raw >= 0)

                _est_ok = False
                _est_report = -9999
                try:
                    _st = AKIEstGetGlobalStatisticsSection(_ds, self.car_type_pos)
                    _est_report = int(getattr(_st, 'report', -9999) or -9999)
                    _est_ok = (_st.report == 0)
                except Exception:
                    pass

                if _in_dynamic_sim:
                    _diag_side[_ds] = (
                        f"nveh={_nveh_raw},sim=dynamic,est={'ok' if _est_ok else f'report={_est_report}'}"
                    )
                else:
                    # Many side sections are virtual/non-microsim in this model.
                    # Negative nveh (e.g. -4002) is expected there; side delay is
                    # still collected via AKIEst global deltas and/or signal timing.
                    _diag_side[_ds] = (
                        f"nveh={_nveh_raw},sim=virtual,"
                        f"est={'ok' if _est_ok else f'report={_est_report}'},"
                        f"fallback=signal_timing"
                    )
            log_to_file(
                f"[DELAY_SECS] inter={self.id} "
                f"main={sorted(main_secs)} "
                f"side={sorted(side_secs)} "
                f"side_access={_diag_side}",
                force=True,
            )

        if not hasattr(self, '_cum_sec_prev'):
            self._cum_sec_prev = {}
        # Accumulate all vehicle IDs seen on side sections this call,
        # used for lazy pruning of the _side_stop_prev dict.
        _all_side_veh_ids = set()

        for sec in all_delay_secs:
            # A section is "main" if it is a known main corridor section.
            # Everything else (auto-discovered cross streets) is "side".
            # When both sets are empty this falls back to True (all main).
            is_main = (sec in main_secs) if (main_secs or side_secs) else True

            car_stat = AKIEstGetParcialStatisticsSection(
                sec, stat_time, self.car_type_pos)
            truck_stat = AKIEstGetParcialStatisticsSection(
                sec, stat_time, getattr(self.stats, '_truck_pos', -1))

            if car_stat.report == 0 and is_main:
                # ── Main section: AKIEst partial stats ─────────────────────
                # AKIEstGetParcialStatisticsSection counts vehicles that have
                # EXITED the section since stat_time.  During a GREEN step this
                # correctly captures delay for throughput vehicles.  During RED
                # it returns count=0 — those vehicles will be counted when they
                # eventually exit on green, so cumulative totals are correct.
                # We supplement with a per-vehicle scan so REAL-TIME delay
                # (needed for reward-based TSP) is also captured for vehicles
                # queued at red that haven't exited yet.
                bus_stat = AKIEstGetParcialStatisticsSection(
                    sec, stat_time, self.bus_type_pos)
                _truck_pos_m = getattr(self.stats, '_truck_pos', -1)
                car_d    = car_stat.DTa * car_stat.count * self.CarOcc
                bus_d    = bus_stat.DTa * bus_stat.count * self.BusOcc
                truck_d  = (
                    truck_stat.DTa * truck_stat.count * self.TruckOcc
                    if getattr(truck_stat, 'report', -1) == 0 and _truck_pos_m > 0
                    else 0.0
                )
                bus_cnt   = bus_stat.count
                car_cnt   = car_stat.count
                truck_cnt = (
                    truck_stat.count
                    if getattr(truck_stat, 'report', -1) == 0 and _truck_pos_m > 0
                    else 0
                )

                # Track distinct vehicle IDs from AKIEst exits (green phase).
                # This populates n_distinct_cars/trucks which stay 0 if only using
                # the per-vehicle scan (which only runs during red when count==0).
                # AKIEst gives count but not individual IDs, so we scan vehicles
                # periodically to add IDs — throttle to every 5s to limit overhead.
                if car_cnt > 0 or bus_cnt > 0 or truck_cnt > 0:
                    if not hasattr(self, '_distinct_last_scan_t'):
                        self._distinct_last_scan_t = -999.0
                    if time - self._distinct_last_scan_t >= 5.0:
                        self._distinct_last_scan_t = time
                        _inter_d2 = self.stats._inter.get(self.id, {})
                        try:
                            _n_d = max(int(AKIVehStateGetNbVehiclesSection(sec, True)), 0)
                            for _dvi in range(_n_d):
                                try:
                                    _dveh = AKIVehStateGetVehicleInfSection(sec, _dvi)
                                    if _dveh.report < 0:
                                        continue
                                    _dvid  = int(_dveh.idVeh)
                                    _dtype = int(_dveh.type)
                                    if _dtype == self.bus_type_pos:
                                        _inter_d2.get('_seen_bus_ids', set()).add(_dvid)
                                    elif _truck_pos_m > 0 and _dtype == _truck_pos_m:
                                        _inter_d2.get('_seen_truck_ids', set()).add(_dvid)
                                    else:
                                        _inter_d2.get('_seen_car_ids', set()).add(_dvid)
                                except Exception:
                                    pass
                        except Exception:
                            pass

                # Supplement: if this step has no exited vehicles (red phase),
                # use the per-vehicle scan to capture queued delay in real time.
                # The AKIEst path already accounts for exited vehicles, so the
                # per-vehicle scan is only used when count==0.
                if car_cnt == 0 and bus_cnt == 0:
                    _prof_m  = getattr(self, '_sec_profile', {}).get(sec)
                    _ff_s_m  = _prof_m['ff_time_s'] if _prof_m else getattr(
                        self, '_side_ff_cache', {}).get(sec, 10.0)
                    if not hasattr(self, '_main_stoptime_prev'):
                        self._main_stoptime_prev = {}
                    _n_main = max(int(AKIVehStateGetNbVehiclesSection(sec, True)), 0)
                    _inter_d = self.stats._inter.get(self.id, {})
                    for _mvi in range(_n_main):
                        try:
                            _mveh = AKIVehStateGetVehicleInfSection(sec, _mvi)
                            if _mveh.report < 0:
                                continue
                            _mvid  = int(_mveh.idVeh)
                            _mtype = int(_mveh.type)
                            _mkey  = (sec, _mvid)
                            # Track distinct vehicle IDs so n_distinct_cars/trucks
                            # are populated (otherwise they stay 0 forever).
                            if _mtype == self.bus_type_pos:
                                _inter_d.get('_seen_bus_ids', set()).add(_mvid)
                            elif _truck_pos_m > 0 and _mtype == _truck_pos_m:
                                _inter_d.get('_seen_truck_ids', set()).add(_mvid)
                            else:
                                _inter_d.get('_seen_car_ids', set()).add(_mvid)
                            _ent_t = float(
                                getattr(_mveh, 'SectionEntranceT', -1.0) or -1.0)
                            if 0.0 < _ent_t < time:
                                _dly_now = max(0.0, (time - _ent_t) - _ff_s_m)
                            else:
                                _dly_now = max(0.0, float(
                                    getattr(_mveh, 'CurrentStopTime', 0.0) or 0.0))
                            _prev_m   = self._main_stoptime_prev.get(_mkey, _dly_now)
                            _delta_m  = max(0.0, _dly_now - _prev_m)
                            self._main_stoptime_prev[_mkey] = _dly_now
                            if _delta_m <= 0.0:
                                continue
                            if _mtype == self.bus_type_pos:
                                bus_d   += _delta_m * self.BusOcc
                            elif _truck_pos_m > 0 and _mtype == _truck_pos_m:
                                truck_d += _delta_m * self.TruckOcc
                            else:
                                car_d   += _delta_m * self.CarOcc
                        except Exception:
                            pass

            elif not is_main:
                # ── Side section delay: three-priority measurement ──────────
                #
                # Side sections in this model are NOT in the dynamic vehicle
                # simulation (AKIVehStateGetNbVehiclesSection returns -4002 =
                # AKI_ERROR_SECTION_NOTEXIST).  They exist in Aimsun's routing
                # topology but cross-street demand is handled as virtual demand
                # that never places physical vehicles on road sections.
                #
                # Priority 1 — AKIEst global cumulative stats (timSta=0.0)
                #   Works even for non-physically-simulated sections when Aimsun
                #   has a statistics collector configured for the section.  The
                #   running DTa*count product increases monotonically; delta gives
                #   the per-step delay contribution from vehicles that DID exit.
                #
                # Priority 2 — Per-vehicle scan (AKIVehState)
                #   Only applicable when the section IS in the dynamic simulation
                #   (AKIVehState returns >= 0).  Captures queued vehicles that
                #   have not yet exited, including those stopped at red.
                #
                # Priority 3 — Signal-timing shockwave estimate (always-on)
                #   When neither of the above yields data, compute theoretical
                #   queue delay from the current signal phase state:
                #     delta = (arrival_rate / 3600) × red_elapsed_s × Occ
                #   This is the same model used by GE/BP objective functions and
                #   correctly accumulates during red, resets on cross-street green.
                #   Arrival rate comes from SideUpFlowList (maintained by
                #   _update_side_section_virtual_detectors); when that is also 0
                #   a conservative 300 veh/h default is used.
                #   This ensures non-zero side delay is always recorded throughout
                #   the run — even in NORMAL mode with no bus detection events.
                car_d = bus_d = truck_d = 0.0
                car_cnt = bus_cnt = truck_cnt = 0
                _truck_pos_s = getattr(self.stats, '_truck_pos', -1)
                _priority_used = "none"

                # ── Priority 1: AKIEst global cumulative delta ────────────
                if not hasattr(self, '_side_global_prev'):
                    self._side_global_prev = {}
                try:
                    _cg  = AKIEstGetGlobalStatisticsSection(sec, self.car_type_pos)
                    _bg  = AKIEstGetGlobalStatisticsSection(sec, self.bus_type_pos)
                    _p1_ok = (_cg.report == 0 and _bg.report == 0)
                    if _p1_ok:
                        _now_c = float(_cg.DTa * _cg.count) if _cg.count > 0 else 0.0
                        _now_b = float(_bg.DTa * _bg.count) if _bg.count > 0 else 0.0
                        _pc = self._side_global_prev.get((sec, 'c'), 0.0)
                        _pb = self._side_global_prev.get((sec, 'b'), 0.0)
                        car_d = max(0.0, _now_c - _pc) * self.CarOcc
                        bus_d = max(0.0, _now_b - _pb) * self.BusOcc
                        self._side_global_prev[(sec, 'c')] = _now_c
                        self._side_global_prev[(sec, 'b')] = _now_b
                        if _truck_pos_s > 0:
                            _tg = AKIEstGetGlobalStatisticsSection(sec, _truck_pos_s)
                            if _tg.report == 0 and _tg.count > 0:
                                _now_t = float(_tg.DTa * _tg.count)
                                _pt = self._side_global_prev.get((sec, 't'), 0.0)
                                truck_d = max(0.0, _now_t - _pt) * self.TruckOcc
                                self._side_global_prev[(sec, 't')] = _now_t
                        if car_d > 0.0 or bus_d > 0.0:
                            _priority_used = "akiest_global"
                except Exception:
                    _p1_ok = False

                # ── Priority 2: per-vehicle scan (only if section is in sim) ─
                _n_test = int(AKIVehStateGetNbVehiclesSection(sec, True))
                _in_sim = (_n_test >= 0)
                if _in_sim and car_d == 0.0 and bus_d == 0.0:
                    _prof = getattr(self, '_sec_profile', {}).get(sec)
                    _ff_s = _prof['ff_time_s'] if _prof else getattr(
                        self, '_side_ff_cache', {}).get(sec, 10.0)
                    _alive_keys = set()
                    for _vi in range(_n_test):
                        try:
                            _veh = AKIVehStateGetVehicleInfSection(sec, _vi)
                            if _veh.report < 0:
                                continue
                            _vid   = int(_veh.idVeh)
                            _vtype = int(_veh.type)
                            _key   = (sec, _vid)
                            _alive_keys.add(_key)
                            _ent_t = float(
                                getattr(_veh, 'SectionEntranceT', -1.0) or -1.0)
                            if 0.0 < _ent_t < time:
                                _delay_now = max(0.0, (time - _ent_t) - _ff_s)
                            else:
                                _delay_now = max(0.0, float(
                                    getattr(_veh, 'CurrentStopTime', 0.0) or 0.0))
                            _prev_d = self._side_stoptime_prev.get(_key, _delay_now)
                            _delta  = max(0.0, _delay_now - _prev_d)
                            self._side_stoptime_prev[_key] = _delay_now
                            _all_side_veh_ids.add(_vid)
                            if _delta <= 0.0:
                                continue
                            if _vtype == self.bus_type_pos:
                                bus_d   += _delta * self.BusOcc
                            elif _truck_pos_s > 0 and _vtype == _truck_pos_s:
                                truck_d += _delta * self.TruckOcc
                            else:
                                car_d   += _delta * self.CarOcc
                        except Exception:
                            pass
                    # Prune stale entries for this section
                    _stale = [k for k in self._side_stoptime_prev
                              if k[0] == sec and k not in _alive_keys]
                    for _k in _stale:
                        del self._side_stoptime_prev[_k]
                    if car_d > 0.0 or bus_d > 0.0:
                        _priority_used = "vehicle_scan"

                # ── Priority 3: signal-timing shockwave estimate ──────────
                # Always runs.  Provides non-zero side delay even for sections
                # not in the dynamic simulation.  Consistent with GE/BP
                # objective functions which use the same shockwave model.
                #
                # Allocate delay proportionally across vehicle types using
                # per-vehicle-type statistics from Priority 1 when available,
                # or fallback to default proportions (car: 70%, bus: 20%, truck: 10%).
                #
                # delta = (q_arr / 3600) × red_elapsed_s × Occ × (vtype_count / total_count)
                #
                # This correctly integrates: summing (q/3600)×r×Occ dr from r=0
                # to R gives (q/3600) × R²/2 × Occ = standard uniform delay.
                # The estimate is applied to supplement (not overwrite) measured
                # delay so Priority 1/2 data is never discarded.
                if car_d == 0.0 and bus_d == 0.0:
                    try:
                        _nid    = getattr(self, 'node_id', self.id)
                        _cur_ph = ECIGetCurrentPhase(_nid)
                        _bus_ph = int(getattr(self, 'BusPhase', 1) or 1)

                        # Cross-streets accumulate red-light delay during main
                        # corridor phases (bus phase and typically phase 2).
                        # Track cumulative red elapsed per section using a running
                        # counter so delay accumulates correctly across phase changes.
                        if not hasattr(self, '_side_red_elapsed'):
                            self._side_red_elapsed = {}
                            self._side_last_t      = {}

                        _last_t = self._side_last_t.get(sec, time)
                        _dt     = max(0.0, time - _last_t)
                        self._side_last_t[sec] = time

                        # Determine if cross-street is currently at red.
                        # Heuristic: cross-street is at red during the bus
                        # (main corridor) phase.  Reset counter on any other phase.
                        if _cur_ph == _bus_ph:
                            self._side_red_elapsed[sec] = (
                                self._side_red_elapsed.get(sec, 0.0) + _dt)
                        else:
                            # Cross-street may be green — reset accumulated red time
                            self._side_red_elapsed[sec] = 0.0

                        _red_el = self._side_red_elapsed.get(sec, 0.0)
                        if _red_el > 0.0:
                            # Arrival rate: prefer SideUpFlowList (from _sample_side_sections
                            # which uses 15% of main flow as fallback). If still 0, derive
                            # from main approach flow (UpFlowList[0]) × 15% ratio.
                            _side_secs_live = self._get_side_sections()
                            _side_flow      = 0.0
                            try:
                                _sidx = _side_secs_live.index(sec)
                                _sf   = float(self.SideUpFlowList[_sidx])
                                if _sf > 0.0:
                                    _side_flow = _sf
                            except Exception:
                                pass
                            if _side_flow <= 0.0:
                                # Estimate from main corridor approach flow (15% cross-street ratio)
                                try:
                                    _main_q = float(self.UpFlowList[0][0]) if hasattr(self, 'UpFlowList') and len(self.UpFlowList) > 0 else 0.0
                                    _side_flow = max(_main_q * 0.15, 400.0)
                                except Exception:
                                    _side_flow = 400.0  # urban minor cross-street default
                            
                            # Allocate delay across vehicle types.
                            # First try to get per-vehicle-type counts from Priority 1.
                            # If unavailable, use default proportions.
                            _c_car = 0.0
                            _c_bus = 0.0
                            _c_truck = 0.0
                            _c_total = 1.0   # avoid division by zero
                            _truck_pos_p3 = getattr(self.stats, '_truck_pos', -1)
                            try:
                                _cg = AKIEstGetGlobalStatisticsSection(sec, self.car_type_pos)
                                _bg = AKIEstGetGlobalStatisticsSection(sec, self.bus_type_pos)
                                if _cg.report == 0 and _bg.report == 0:
                                    _c_car   = float(_cg.count) if _cg.count > 0 else 0.0
                                    _c_bus   = float(_bg.count) if _bg.count > 0 else 0.0
                                    if _truck_pos_p3 > 0:
                                        _tg = AKIEstGetGlobalStatisticsSection(sec, _truck_pos_p3)
                                        _c_truck = float(_tg.count) if _tg.report == 0 and _tg.count > 0 else 0.0
                                    _c_total = _c_car + _c_bus + _c_truck
                                    if _c_total <= 0.0:
                                        _c_total = 1.0
                            except Exception:
                                pass
                            
                            # If counts are all zero, use fallback proportions
                            if _c_car <= 0.0 and _c_bus <= 0.0 and _c_truck <= 0.0:
                                _c_car   = 0.70   # 70% cars
                                _c_bus   = 0.20   # 20% buses
                                _c_truck = 0.10   # 10% trucks
                                _c_total = 1.0
                            
                            # Base delay: (q/3600) × red_elapsed × dt
                            _base_delay = (_side_flow / 3600.0) * _red_el * _dt
                            # Allocate to each type proportionally
                            car_d   = _base_delay * (_c_car / _c_total) * self.CarOcc if _c_total > 0 else 0.0
                            bus_d   = _base_delay * (_c_bus / _c_total) * self.BusOcc if _c_total > 0 else 0.0
                            truck_d = _base_delay * (_c_truck / _c_total) * self.TruckOcc if _c_total > 0 else 0.0
                            
                            _priority_used = (
                                f"signal_timing(red={_red_el:.0f}s,"
                                f"q={_side_flow:.0f},dt={_dt:.0f}s,"
                                f"split=c:{_c_car/max(_c_total,1):.2f},"
                                f"b:{_c_bus/max(_c_total,1):.2f},"
                                f"t:{_c_truck/max(_c_total,1):.2f})"
                            )
                    except Exception:
                        pass

                self._last_side_priority = _priority_used

            else:
                # ── Main section fallback: partial stats unavailable (warmup) ──
                # Use cumulative delta from AKIEstGetGlobalStatisticsSection.
                try:
                    car_cum = AKIEstGetCurrentStatisticsSection(
                        sec, self.car_type_pos)
                    bus_cum = AKIEstGetCurrentStatisticsSection(
                        sec, self.bus_type_pos)
                    truck_cum = AKIEstGetCurrentStatisticsSection(
                        sec, getattr(self.stats, '_truck_pos', -1))

                    if car_cum.report != 0:
                        car_cum = AKIEstGetGlobalStatisticsSection(
                            sec, self.car_type_pos)
                    if bus_cum.report != 0:
                        bus_cum = AKIEstGetGlobalStatisticsSection(
                            sec, self.bus_type_pos)
                    if getattr(self.stats, '_truck_pos', -1) > 0 and truck_cum.report != 0:
                        truck_cum = AKIEstGetGlobalStatisticsSection(
                            sec, getattr(self.stats, '_truck_pos', -1))

                    prev_car   = self._cum_sec_prev.get((sec, 'car'),   (0.0, 0))
                    prev_bus   = self._cum_sec_prev.get((sec, 'bus'),   (0.0, 0))
                    prev_truck = self._cum_sec_prev.get((sec, 'truck'), (0.0, 0))

                    car_total_now   = (car_cum.DTa   * car_cum.count)   if car_cum.report   == 0 else 0.0
                    bus_total_now   = (bus_cum.DTa   * bus_cum.count)   if bus_cum.report   == 0 else 0.0
                    truck_total_now = (
                        truck_cum.DTa * truck_cum.count
                        if getattr(truck_cum, 'report', -1) == 0 and getattr(self.stats, '_truck_pos', -1) > 0
                        else 0.0)

                    car_cnt   = max(0, (car_cum.count   if car_cum.report   == 0 else 0) - prev_car[1])
                    bus_cnt   = max(0, (bus_cum.count   if bus_cum.report   == 0 else 0) - prev_bus[1])
                    truck_cnt = max(0, (
                        (truck_cum.count if getattr(truck_cum, 'report', -1) == 0 else 0) - prev_truck[1]))

                    car_d   = max(0.0, car_total_now   - prev_car[0])   * self.CarOcc
                    bus_d   = max(0.0, bus_total_now   - prev_bus[0])   * self.BusOcc
                    truck_d = max(0.0, truck_total_now - prev_truck[0]) * self.TruckOcc

                    self._cum_sec_prev[(sec, 'car')]   = (
                        car_total_now,   car_cum.count   if car_cum.report   == 0 else prev_car[1])
                    self._cum_sec_prev[(sec, 'bus')]   = (
                        bus_total_now,   bus_cum.count   if bus_cum.report   == 0 else prev_bus[1])
                    self._cum_sec_prev[(sec, 'truck')] = (
                        truck_total_now,
                        truck_cum.count if getattr(truck_cum, 'report', -1) == 0 else prev_truck[1])

                except Exception:
                    car_d = bus_d = truck_d = 0.0
                    car_cnt = bus_cnt = truck_cnt = 0

            sec_delay = car_d + bus_d + truck_d
            weighted_delay += sec_delay

            # Throttled side-delay diagnostic (once per 60 s per section)
            if not is_main and sec_delay > 0.0:
                if not hasattr(self, '_side_delay_log_t'):
                    self._side_delay_log_t = {}
                _last_log = self._side_delay_log_t.get(sec, -999.0)
                if time - _last_log >= 60.0:
                    self._side_delay_log_t[sec] = time
                    log_to_file(
                        f"[SIDE_DELAY] inter={self.id} t={time:.0f} "
                        f"sec={sec} delay={sec_delay:.3f}pax·s "
                        f"method={getattr(self, '_last_side_priority', 'unknown')}"
                    )

            # For side sections the `bus_cnt` / `car_cnt` values are per-step
            # stopped-vehicle counts, NOT passage counts. Adding them to the
            # stats passages denominator would inflate PaxEquivPassages by
            # N_stopped_vehicles × N_steps (×1000 s of overcounting).
            # Side-section delay is captured in `delay_side` via `is_main=False`;
            # the passage/passenger denominators only need main-section counts.
            _pass_bus_cnt   = bus_cnt   if is_main else 0
            _pass_car_cnt   = car_cnt   if is_main else 0
            _pass_truck_cnt = truck_cnt if is_main else 0

            self.stats.add_section_delay_split(
                intersection_id   = self.id,
                weighted_delay    = sec_delay,
                bus_vehicle_count = _pass_bus_cnt,
                car_vehicle_count = _pass_car_cnt,
                truck_vehicle_count = _pass_truck_cnt,
                is_main           = is_main,
                bus_delay         = bus_d,
                car_delay         = car_d,
                truck_delay       = truck_d,
            )

            if not is_main and sec in side_secs:
                if not hasattr(self, '_side_red_counts'):
                    self._side_red_counts = {}
                if not hasattr(self, '_side_live_counts'):
                    self._side_live_counts = {}
                live_side_count = 0
                try:
                    live_side_count = max(int(AKIVehStateGetNbVehiclesSection(sec, True)), 0)
                except Exception:
                    live_side_count = 0
                self._side_live_counts[sec] = live_side_count
                self._side_red_counts[sec] = (
                    safe_float(self._side_red_counts.get(sec, 0.0))
                    + max(live_side_count, int(max(0, bus_cnt + car_cnt + truck_cnt)))
                )

        self.step_delay += weighted_delay

        # Prune _side_stop_prev: remove vehicle IDs not seen this call.
        # Only runs every ~60 s to avoid per-step overhead.
        if hasattr(self, '_side_stop_prev') and _all_side_veh_ids:
            if not hasattr(self, '_side_prune_t'):
                self._side_prune_t = time
            if time - self._side_prune_t > 60.0:
                self._side_stop_prev = {
                    k: v for k, v in self._side_stop_prev.items()
                    if k in _all_side_veh_ids}
                self._side_prune_t = time

        # Periodic delay debug log (every 60 s) — LOG_DELAY flag
        if LOG_DELAY:
            if not hasattr(self, '_delay_log_t'):
                self._delay_log_t = time
            if time - self._delay_log_t >= 60.0:
                _inter_d = self.stats._inter.get(self.id, {})
                _avg_den = self.stats._inter_dsf_avg(self.id, 'density_sum')
                _avg_spd = self.stats._inter_dsf_avg(self.id, 'speed_sum')
                _avg_flw = self.stats._inter_dsf_avg(self.id, 'flow_sum')
                _avg_que = self.stats._inter_dsf_avg(self.id, 'queue_sum')
                log_to_file(
                    f"[DELAY] inter={self.id} t={time:.0f} "
                    f"main_secs={sorted(main_secs)} "
                    f"side_secs={sorted(side_secs)} "
                    f"step_weighted={weighted_delay:.4f} "
                    f"avg_density={_avg_den:.2f}veh/km "
                    f"avg_speed={_avg_spd:.2f}km/h "
                    f"avg_flow={_avg_flw:.1f}veh/h "
                    f"avg_queue={_avg_que:.2f}veh "
                    f"cum_side_delay_s={_inter_d.get('delay_side', 0.0):.2f} "
                    f"cum_main_delay_s={_inter_d.get('delay_main', 0.0):.2f} "
                    f"side_veh_tracked={len(getattr(self, '_side_stop_prev', {}))}"
                )
                self._delay_log_t = time

    # =========================================================================
    # GROUP-BASED READINESS GUARD
    # =========================================================================

    def update(self, time, timeSta, acycle):
        if TSP_ACTIVE_INTERSECTIONS is not None and self.id not in TSP_ACTIVE_INTERSECTIONS:
            return

        try:
            # ── All other modes: phase-based tracking + TSP logic ─────────────
            current_phase = ECIGetCurrentPhase(self.node_id)
            if current_phase < 0:
                return

            # Phase-transition bookkeeping
            if current_phase != getattr(self, 'previous_phase', -1):
                prev_phase = getattr(self, 'previous_phase', -1)
                if prev_phase in self.PhaseIndex:
                    prev_idx = self.PhaseIndex[prev_phase]
                    if prev_idx < len(self.RedStartTimeList):
                        self.RedStartTimeList[prev_idx][:] = time
                        self.UpDetCountList[prev_idx][:] = 0.0
                        self.UpAveOccList[prev_idx][:]   = 0.0
                if current_phase in self.PhaseIndex:
                    idx = self.PhaseIndex[current_phase]
                    if idx < len(self.GreenStartTimeList):
                        self.GreenStartTimeList[idx][:] = time
                        dur = GetPhaseDuration(self.node_id, current_phase, timeSta)
                        if idx < len(self.NextRedStartTime):
                            self.NextRedStartTime[idx][:] = time + dur
                self.previous_phase = current_phase

            self.collect_detector_data()
            self.update_queue_model(time)
            self.detect_bus(time)

            # Periodic heartbeat (every 60 s) — controlled by LOG_HEARTBEAT flag
            if LOG_HEARTBEAT:
                _t60 = int(time) // 60
                if _t60 != getattr(self, '_last_log_min', -1):
                    self._last_log_min = _t60
                    log_to_file(
                        f"[HEARTBEAT] t={time:.0f}s inter={self.id} "
                        f"mode={CONTROL_MODE} phase={current_phase} "
                        f"flag={self.flag} TSPStrategy={self.TSPStrategy} "
                        f"TSPActiveTime={self.TSPActiveTime:.0f} "
                        f"BusPresence={self.BusPresence[0].tolist()} "
                        f"BusSpeed={[round(v,2) for v in self.BusSpeed[0].tolist()]} "
                        f"MaxQ={[round(v,1) for v in self.MaxQueueLength[0].tolist()]} "
                        f"UpFlow={[round(v,1) for v in self.UpFlowList[0].tolist()]}"
                    )

            if CONTROL_MODE == "NORMAL":
                self.run_normal(time, timeSta, acycle)

            elif CONTROL_MODE == "HARMONY":
                self.restore_phase_if_needed(time, timeSta, acycle)
                if time - self.last_tsp_action_time < self.tsp_cooldown_seconds:
                    if LOG_TSP_EVT and int(time) % 15 == 0:
                        _vprint(
                            f"[TSP COOLDOWN] inter={self.id} t={time:.1f} "
                            f"skipping HARMONY (remaining ~"
                            f"{self.tsp_cooldown_seconds-(time-self.last_tsp_action_time):.0f}s)")
                else:
                    _was_idle  = (self.TSPStrategy == 0)
                    tsp_active = self.check_bus_priority(time, timeSta, acycle)
                    if tsp_active and _was_idle:
                        self.last_tsp_action_time = time
                        if LOG_TSP_EVT:
                            _vprint(
                                f"[TSP] inter={self.id} HARMONY action t={time:.1f} "
                                f"next after {time+self.tsp_cooldown_seconds:.1f}s")

            elif CONTROL_MODE == "RL":
                tsp_active = self.check_bus_priority(time, timeSta, acycle)
                if not tsp_active:
                    self.run_rl(time, timeSta, acycle)
                self.restore_phase_if_needed(time, timeSta, acycle)

            elif CONTROL_MODE == "URTSP":
                if time - self.last_tsp_action_time < self.tsp_cooldown_seconds:
                    if LOG_TSP_EVT and int(time) % 10 == 0:
                        _vprint(
                            f"[TSP COOLDOWN] inter={self.id} t={time:.1f} "
                            f"skipping URTSP (remaining ~"
                            f"{self.tsp_cooldown_seconds-(time-self.last_tsp_action_time):.0f}s)")
                else:
                    self.run_urtsp(time, timeSta, acycle)

            elif CONTROL_MODE in ("REWARD_TSP", "DRL_DENSITY", "MPC_TSP"):
                self.run_reward_tsp(time, timeSta, acycle)

        except Exception as e:
            stop_simulation(f"update crashed inter={self.id} t={time:.1f}: {e}")
            import traceback
            log_to_file(traceback.format_exc())
            return 0


    # ── HARMONY check_bus_priority kept intact below ──────────────────
    def check_bus_priority(self, time, timeSta, acycle):
        if time < self.TSPActiveTime:
            return False

        # ── Proposal 5: early-bus truncation while GE is in service ──────────
        # DC TSP case-4: if an extension is active (TSPStrategy==1, flag==1)
        # and the next detected bus is early (σ < -25 % of mean), terminate
        # the extension immediately so the cycle tightens before the early bus.
        if self.flag == 1 and self.TSPStrategy == 1:
            _sigma_now  = self._hw_sigma_current
            _hw_mean_now = max(self._hw_mean_s, 30.0)
            _hw_hist     = len(self._hw_observed) >= 2
            if _hw_hist and _sigma_now < -0.25 * _hw_mean_now:
                _detected_bus = int(getattr(self, 'last_detected_bus_id', -1) or -1)
                if _detected_bus > 0 and _detected_bus != getattr(self, '_hw_last_truncated_veh', -1):
                    try:
                        _cp = ECIGetCurrentPhase(self.node_id)
                        _ps = ECIGetStartingTimePhase(self.node_id)
                        _elapsed_now = max(0.0, time - _ps)
                        _min_g = float(self.GE_lower_bound or 5.0)
                        _trunc = max(_elapsed_now + _min_g,
                                     self.BusPhaseDuration * 0.5)
                        ECIChangeTimingPhase(self.node_id, _cp, _trunc, timeSta)
                        self._hw_last_truncated_veh = _detected_bus
                        log_to_file(
                            f"[HARMONY] EARLY TRUNCATE | inter={self.id} t={time:.1f} "
                            f"bus={_detected_bus} σ={_sigma_now:.0f}s "
                            f"mean={_hw_mean_now:.0f}s trunc_dur={_trunc:.1f}s "
                            f"(proposal 5)",
                            force=True)
                    except Exception as _te:
                        log_to_file(f"[HARMONY] EARLY TRUNCATE failed inter={self.id}: {_te}")

        if self.flag != 0:
            return True
        # One TSP grant per cycle — prevents re-firing on the same bus
        if getattr(self, '_tsp_cycle_grant_until', -1.0) > time:
            return False

        # Read current phase ONCE — consistent across all detectors this step
        current_phase = ECIGetCurrentPhase(self.node_id)

        # Guard: negative phase means junction not under external control yet
        if current_phase < 0:
            # Log once per minute so we know this is happening
            _t60 = int(time) // 60
            if _t60 != getattr(self, '_last_phase_warn', -1):
                self._last_phase_warn = _t60
                log_to_file(
                    f"[WARN] inter={self.id} t={time:.0f}s ECIGetCurrentPhase={current_phase} "
                    f"— junction NOT under external control. "
                    f"Set junction signal control to 'External' in Aimsun model GUI "
                    f"(Properties → Signal Control → External API).")
            return False

        # ── Corridor pre-arm check (HARMONY coordination) ────────────────────
        # When the CorridorCoordinator has pre-armed this intersection, apply TSP
        # immediately using the Kalman ETA rather than waiting for local detector
        # presence. Bypasses harmony search — uses a fixed eta+buffer duration so
        # the bus is guaranteed to arrive during the granted phase.
        _prearm = getattr(self, '_harmony_prearm', None)
        if _prearm is not None and self.TSPStrategy == 0:
            _pa_veh, _pa_eta_t, _pa_issued_t = _prearm
            _eta_from_now = _pa_eta_t - time
            def _notify_coord_prearm_consumed():
                if self._corridor_coord is not None and COORDINATED_TSP:
                    try:
                        self._corridor_coord.notify_bus_granted(_pa_veh, self.id, time, None)
                    except Exception as _coord_e:
                        log_to_file(
                            f"[HARMONY COORD] notify_bus_granted failed "
                            f"inter={self.id} bus={_pa_veh}: {_coord_e}"
                        )
            # Clear stale or already-expired pre-arms.
            # Use a tight negative tolerance (-5 s) so that once the predicted
            # ETA has passed (bus should have arrived), the pre-arm is discarded
            # immediately and local Harmony detection is allowed to take over.
            # The old -20 s threshold created a deadlock window where the bus
            # was present but neither the pre-arm fired (eta < 0) nor local
            # Harmony ran (authority gate still active).
            _prearm_timeout_s = (
                float(getattr(self._corridor_coord, 'PRE_REQ_TIMEOUT_S', 90.0))
                if self._corridor_coord is not None else 90.0
            )
            if _eta_from_now < -5.0 or time - _pa_issued_t > _prearm_timeout_s:
                self._harmony_prearm = None
            elif 0.0 <= _eta_from_now <= getattr(self, '_eta_max_s', 90.0):
                # ── Fire immediately — no secondary hold ──────────────────────
                # The coordinator already accounts for PRE_GREEN_LEAD_S=50 s.
                # The old _PREARM_INS_WINDOW hold (≤ 35 s) wasted 15 s of setup
                # time and caused buses to arrive before the bus phase was ready.
                _prearm_dur = max(float(self.BP_lower_bound), _eta_from_now + 5.0)
                _prearm_dur = min(_prearm_dur, float(self.BP_upper_bound))
                self._harmony_prearm = None
                if LOG_HARMONY:
                    _vprint(
                        f"[HARMONY PREARM FIRE] inter={self.id} t={time:.1f} "
                        f"bus={_pa_veh} eta={_eta_from_now:.1f}s "
                        f"dur={_prearm_dur:.1f}s phase={'GE' if current_phase == self.BusPhase else 'INS'}"
                    )
                if current_phase == self.BusPhase:
                    # GE path — cap to MAX_GE_EXTENSION_S.
                    # If bus needs more extension than the hard cap, skip entirely.
                    _ge_needed = max(0.0, _eta_from_now + 5.0)
                    if _ge_needed > MAX_GE_EXTENSION_S:
                        if LOG_HARMONY:
                            _vprint(
                                f"[HARMONY COORD GE SKIP] inter={self.id} t={time:.1f} "
                                f"bus_eta={_eta_from_now:.1f}s needs GE={_ge_needed:.1f}s "
                                f"> MAX_GE={MAX_GE_EXTENSION_S:.0f}s — skipping")
                        self.stats.record_tsp_event(self.id, 'detection')
                        self.stats.record_tsp_skip(self.id, 'ge_trivial')
                        _notify_coord_prearm_consumed()
                    else:
                        _prearm_dur = min(_prearm_dur, MAX_GE_EXTENSION_S)
                        # If the current phase already ends after the bus arrives, skip.
                        try:
                            _ps_start  = ECIGetStartingTimePhase(self.node_id)
                            _ph_dur    = GetPhaseDuration(self.node_id, current_phase, timeSta)
                            _remain    = max(0.0, _ph_dur - (time - _ps_start))
                            _next_red  = time + _remain
                            _bus_arr   = time + _eta_from_now
                            if _bus_arr <= _next_red:
                                # Bus will make the natural green — no GE needed
                                log_to_file(
                                    f"[GREEN_GRANT] inter={self.id} t={time:.1f} "
                                    f"bus={_pa_veh} eta={_eta_from_now:.1f}s "
                                    f"type=NATURAL source=COORD_PREARM "
                                    f"(phase already green until {_next_red:.1f}s)",
                                    force=True)
                                if LOG_HARMONY:
                                    _vprint(
                                        f"[HARMONY COORD GE SKIP] inter={self.id} t={time:.1f} "
                                        f"bus_arr={_bus_arr:.1f}s <= next_red={_next_red:.1f}s "
                                        f"— natural green, skipping pre-arm GE")
                                self.stats.record_tsp_event(self.id, 'detection')
                                self.stats.record_tsp_skip(self.id, 'natural_green')
                                _notify_coord_prearm_consumed()
                            else:
                                ECIChangeTimingPhase(
                                    self.node_id, current_phase,
                                    self.BusPhaseDuration + _prearm_dur, timeSta)
                                self.TimeToTerminateBusPhase = time + _remain + _prearm_dur
                                self.TSPStrategy  = 1
                                self.flag         = 1
                                self.TSPActiveTime = time + _prearm_dur + 30
                                self._tsp_cycle_grant_until = time + self.config.get('CycleTime', 135)
                                self.last_tsp_action_time   = time
                                self._ge_debt_s = _prearm_dur
                                self._ge_opt_GE = _prearm_dur
                                _ge_events.append((time, self.id, float(_prearm_dur), 0.0))
                                log_to_file(
                                    f"[GREEN_GRANT] inter={self.id} t={time:.1f} "
                                    f"bus={_pa_veh} eta={_eta_from_now:.1f}s "
                                    f"type=COORD_GE source=PREARM GE={_prearm_dur:.1f}s",
                                    force=True)
                                if LOG_HARMONY:
                                    _vprint(
                                        f"[HARMONY COORD GE] inter={self.id} t={time:.1f} "
                                        f"prearm bus={_pa_veh} eta={_eta_from_now:.1f}s "
                                        f"GE={_prearm_dur:.1f}s")
                                self.stats.record_tsp_event(self.id, 'detection')
                                self.stats.record_tsp_event(self.id, 'extension')
                                self.stats.record_tsp_extension_duration(self.id, float(_prearm_dur))
                                _mark_detection_point(
                                    self.id, _pa_veh, 0.0, 0.0, time,
                                    "harmony-ge-prearm",
                                    {
                                        "force_write": True,
                                        "prearm_status": "action",
                                        "prearm_eta_s": round(max(0.0, float(_eta_from_now)), 1),
                                        "prearm_note": f"GE {float(_prearm_dur):.1f}s prearm",
                                    },
                                )
                                if _pa_veh and _pa_veh > 0:
                                    _acquire_focus(_pa_veh, self.id, time)
                                _notify_coord_prearm_consumed()
                                return True
                        except Exception as _e:
                            log_to_file(f"[HARMONY COORD GE] inter={self.id} failed: {_e}")
                else:
                    # Insertion path — only insert if the bus will miss the next natural BusPhase.
                    try:
                        _ps_now     = ECIGetStartingTimePhase(self.node_id)
                        _elapsed    = max(0.0, time - _ps_now)
                        _rem_cur    = max(0.0,
                            GetPhaseDuration(self.node_id, current_phase, timeSta) - _elapsed)
                        _time_to_bp = _rem_cur
                        try:
                            _ci  = self.phase_list.index(current_phase)
                            _bi  = self.phase_list.index(self.BusPhase)
                            _n   = len(self.phase_list)
                            _steps = (_bi - _ci) % _n
                            for _k in range(1, _steps):
                                _ph = self.phase_list[(_ci + _k) % _n]
                                _time_to_bp += GetPhaseDuration(self.node_id, _ph, timeSta)
                        except Exception:
                            _time_to_bp = float(self.config.get('CycleTime', 135))
                        _nat_end = _time_to_bp + self.BusPhaseDuration
                        if _eta_from_now <= _nat_end:
                            # Bus will catch the natural BusPhase — no insertion needed
                            log_to_file(
                                f"[GREEN_GRANT] inter={self.id} t={time:.1f} "
                                f"bus={_pa_veh} eta={_eta_from_now:.1f}s "
                                f"type=NATURAL source=COORD_PREARM "
                                f"(natural bus phase in {_time_to_bp:.1f}s)",
                                force=True)
                            if LOG_HARMONY:
                                _vprint(
                                    f"[HARMONY COORD INS SKIP] inter={self.id} t={time:.1f} "
                                    f"eta={_eta_from_now:.1f}s <= natural_end={_nat_end:.1f}s "
                                    f"— no pre-arm insertion needed")
                            self.stats.record_tsp_event(self.id, 'detection')
                            self.stats.record_tsp_skip(self.id, 'natural_green')
                            _notify_coord_prearm_consumed()
                        else:
                            _ins_wait_s = max(0.0, float(_eta_from_now))
                            self.previous_phase  = current_phase
                            # Hard cap on insertion duration
                            _prearm_dur = min(_prearm_dur, MAX_BP_INSERTION_S)
                            self.BusPhaseEndTime = time + _prearm_dur
                            ECIChangeTimingPhase(self.id, self.BusPhase, _prearm_dur, timeSta)
                            ECIChangeDirectPhase(
                                self.id, self.BusPhase, timeSta, time, acycle, 0)
                            self.TSPStrategy  = 2
                            self.flag         = 2
                            self.TSPActiveTime = time + _prearm_dur + 30
                            self._ge_debt_s   = float(_prearm_dur)  # cycle recovery
                            self._tsp_cycle_grant_until = time + self.config.get('CycleTime', 135)
                            self.last_tsp_action_time   = time
                            log_to_file(
                                f"[GREEN_GRANT] inter={self.id} t={time:.1f} "
                                f"bus={_pa_veh} eta={_eta_from_now:.1f}s "
                                f"type=COORD_INS source=PREARM BP={_prearm_dur:.1f}s",
                                force=True)
                            if LOG_HARMONY:
                                _vprint(
                                    f"[HARMONY COORD INS] inter={self.id} t={time:.1f} "
                                    f"prearm bus={_pa_veh} eta={_eta_from_now:.1f}s "
                                    f"BP={_prearm_dur:.1f}s")
                            self.stats.record_tsp_event(self.id, 'detection')
                            self.stats.record_tsp_event(self.id, 'insertion')
                            self.stats.record_tsp_insertion_duration(self.id, float(_prearm_dur))
                            self.stats.record_tsp_insertion_wait(self.id, _ins_wait_s)
                            _mark_detection_point(
                                self.id, _pa_veh, 0.0, 0.0, time,
                                "harmony-ins-prearm",
                                {
                                    "force_write": True,
                                    "prearm_status": "action",
                                    "prearm_eta_s": round(max(0.0, float(_eta_from_now)), 1),
                                    "prearm_note": f"INS {float(_prearm_dur):.1f}s prearm",
                                },
                            )
                            if _pa_veh and _pa_veh > 0:
                                _acquire_focus(_pa_veh, self.id, time)
                            _notify_coord_prearm_consumed()
                            return True
                    except Exception as _e:
                        log_to_file(f"[HARMONY COORD INS] inter={self.id} failed: {_e}")

        # ── Pre-arm authority gate ────────────────────────────────────────────
        # If a coordinator pre-arm is still live (bus en route and ETA > -5s),
        # suppress ALL local detection so the pre-arm remains the sole TSP
        # trigger for this junction.  This prevents local Harmony Search from
        # inserting/extending independently while the wave is orchestrated by
        # the CorridorCoordinator.  The -5 s stale threshold above guarantees
        # the gate clears as soon as the bus has arrived (ETA < -5 s), so a
        # bus that arrives earlier than predicted falls through to local Harmony.
        _lingering = getattr(self, '_harmony_prearm', None)
        if _lingering is not None:
            if LOG_HARMONY:
                _lpa_veh, _lpa_eta_t, _ = _lingering
                _lp_eta_rem = _lpa_eta_t - time
                _t60 = int(time) // 60
                if _t60 != getattr(self, '_prearm_gate_warn_t', -1):
                    self._prearm_gate_warn_t = _t60
                    _vprint(
                        f"[PREARM GATE] inter={self.id} t={time:.1f} "
                        f"bus={_lpa_veh} eta_rem={_lp_eta_rem:.1f}s — local detection suppressed")
            return False

        # ── TSP state snapshot (once per check, not per detector) ─────────────
        _diag_every = getattr(self, '_tsp_diag_t', -1)
        if int(time) != _diag_every:
            self._tsp_diag_t = int(time)
            _main_secs = self.incoming_sections
            _sec_info = []
            for _s in _main_secs:
                try:
                    _nv = AKIVehStateGetNbVehiclesSection(_s, False)
                    _sl = float(AKIInfNetGetSectionANGInf(_s).length)
                    _sec_info.append(f"sec={_s} n={_nv} len={_sl:.0f}m")
                except Exception as _e:
                    _sec_info.append(f"sec={_s} err={_e}")
            log_to_file(
                f"[TSP_DIAG] inter={self.id} t={time:.1f} "
                f"phase={ECIGetCurrentPhase(self.node_id)} flag={self.flag} "
                f"TSPStrat={self.TSPStrategy} "
                f"BusPresence={self.BusPresence[0].tolist()} "
                f"BusSpeed={[round(v,2) for v in self.BusSpeed[0].tolist()]} "
                f"UpFlow={[round(float(v),1) for v in self.UpFlowList[0].tolist()]} "
                f"UpDen={[round(float(v),2) for v in self.UpDenList[0].tolist()]} "
                f"MaxQ={[round(float(v),1) for v in self.MaxQueueLength[0].tolist()]} "
                f"RedDur={[round(float(v),1) for v in self.RedDurationList[0].tolist()]} "
                f"sections={_sec_info}"
            )

        # ── Approach-level debounce for detection STATISTICS ─────────────────
        # TSP *actions* (GE, insertion) fire regardless; only stat recording
        # is debounced so skip/detection counts reflect unique bus approaches
        # rather than every simulation step.  Debounce window = 30 s (roughly
        # one signal cycle).  Reset when a new bus is seen at this junction.
        _approach_debounce_s = 30.0
        _det_vid_now = self.last_detected_bus_id
        if _det_vid_now and _det_vid_now > 0:
            _last_rec_t = self._approach_det_t.get(_det_vid_now, -999.0)
            if (time - _last_rec_t) < _approach_debounce_s:
                # Already recorded stats for this bus approach recently.
                _detection_recorded_this_call = True   # suppress further stat writes
            else:
                self._approach_det_t[_det_vid_now] = time
                _detection_recorded_this_call = False
        else:
            _detection_recorded_this_call = False

        # Each detector slot may fire in the same call — count detection only once.
        _coord_notified_this_call = False

        def _notify_coord_bus_progress(veh_id: int, reason: str):
            """Propagate downstream coordination even when local action is natural green."""
            nonlocal _coord_notified_this_call
            if _coord_notified_this_call:
                return
            if self._corridor_coord is None or not COORDINATED_TSP:
                return
            try:
                self._corridor_coord.notify_bus_granted(veh_id, self.id, time, None)
                _coord_notified_this_call = True
                if LOG_CORRIDOR:
                    _vprint(
                        f"[HARMONY COORD] inter={self.id} t={time:.1f} "
                        f"bus={veh_id} propagated ({reason})"
                    )
            except Exception as _coord_e:
                log_to_file(
                    f"[HARMONY COORD] notify_bus_granted failed "
                    f"inter={self.id} bus={veh_id} reason={reason}: {_coord_e}"
                )

        def _log_local_decision(_tier: str, _note: str, _eta_s: float | None = None):
            """Write one debounced decision row so the dashboard can show it."""
            _vid = int(self.last_detected_bus_id or -1)
            if _vid <= 0:
                return
            if not hasattr(self, '_last_local_decision_log_t'):
                self._last_local_decision_log_t = {}
            _key = (_vid, _tier, _note)
            _last_t = self._last_local_decision_log_t.get(_key, -9999.0)
            if time - _last_t < 1.0:
                return
            self._last_local_decision_log_t[_key] = float(time)
            _meta = {
                "force_write": True,
                "prearm_status": "decision",
                "prearm_note": _note,
            }
            if _eta_s is not None:
                try:
                    _meta["prearm_eta_s"] = round(max(0.0, float(_eta_s)), 1)
                except Exception:
                    pass
            _mark_detection_point(self.id, _vid, 0.0, 0.0, time, _tier, _meta)

        def _fmt_noins_reason(_base: str, **_vals) -> str:
            """Compact, parseable reason string for NO_INS / NO_GE diagnostics."""
            _parts = [_base]
            for _k, _v in _vals.items():
                try:
                    if isinstance(_v, float):
                        _parts.append(f"{_k}={_v:.1f}")
                    else:
                        _parts.append(f"{_k}={_v}")
                except Exception:
                    _parts.append(f"{_k}=na")
            return " | ".join(_parts)

        def _system_risk_multiplier():
            """
            Congestion-aware side-cost inflation.

            Local objective deltas can still underestimate system-level harm when
            non-bus phases are already near saturation. Inflate side-cost in that
            regime so GE/INS requires a larger net benefit before granting.
            """
            try:
                _sat_flow = max(float(self.SaturationFlow), 1.0)
                _sat_den = max(float(getattr(self, 'SaturationDensity', 35.0) or 35.0), 1.0)

                _vc_vals = []
                for _pi in range(1, len(self.UpFlowList)):
                    _phase_flows = self.UpFlowList[_pi]
                    if _phase_flows is None or len(_phase_flows) == 0:
                        continue
                    _q = sum(max(0.0, float(_v)) for _v in _phase_flows) / max(len(_phase_flows), 1)
                    _vc_vals.append(_q / _sat_flow)
                _avg_vc = (sum(_vc_vals) / len(_vc_vals)) if _vc_vals else 0.0
                _max_vc = max(_vc_vals) if _vc_vals else 0.0

                _avg_den = 0.0
                try:
                    _avg_den = max(0.0, float(self.stats._inter_dsf_avg(self.id, 'density_sum') or 0.0))
                except Exception:
                    _avg_den = 0.0
                _den_ratio = _avg_den / _sat_den

                _vc_thr = float(self.config.get('RiskVcThreshold', 0.78))
                _den_thr = float(self.config.get('RiskDensityThreshold', 0.85))
                _vc_w = float(self.config.get('RiskVcWeight', 0.90))
                _den_w = float(self.config.get('RiskDensityWeight', 0.60))
                _max_mult = float(self.config.get('RiskMaxMultiplier', 2.20))

                _risk = 0.0
                _risk += max(0.0, _avg_vc - _vc_thr) * _vc_w
                _risk += max(0.0, _max_vc - (_vc_thr + 0.08)) * (_vc_w * 0.50)
                _risk += max(0.0, _den_ratio - _den_thr) * _den_w

                _mult = min(max(1.0, 1.0 + _risk), max(1.0, _max_mult))
                _diag = (
                    f"risk_mult={_mult:.2f}|avg_vc={_avg_vc:.2f}|"
                    f"max_vc={_max_vc:.2f}|den_ratio={_den_ratio:.2f}"
                )
                return _mult, _diag
            except Exception:
                return 1.0, "risk_mult=1.00"

        def _trace_objective(_mode: str, _decision: str, _reason: str,
                     _bus_eta_s=None, _time_to_bp_s=None, _natural_end_s=None,
                     _next_red_s=None, _ge_lb_s=None, _ge_ub_s=None, _opt_ge_s=None,
                     _bp_lb_s=None, _bp_ub_s=None, _opt_bp_s=None,
                     _delay_saved_pax_s=None, _delay_delta_pax_s=None,
                     _delay_base_pax_s=None, _delay_with_strategy_pax_s=None,
                     _note=""):
            # ── Validate bounds are reasonable before logging ──
            # GE window should never exceed MAX_GE_EXTENSION_S (10s hard cap)
            if _ge_ub_s is not None:
                _ge_ub_s = min(float(_ge_ub_s), MAX_GE_EXTENSION_S)
            if _ge_lb_s is not None and _ge_ub_s is not None:
                _ge_lb_s = min(float(_ge_lb_s), _ge_ub_s)
            # BP window should be reasonable (upper bound capped at MAX_BP_INSERTION_S)
            if _bp_ub_s is not None:
                _bp_ub_s = min(float(_bp_ub_s), MAX_BP_INSERTION_S)
            if _bp_lb_s is not None and _bp_ub_s is not None:
                _bp_lb_s = min(float(_bp_lb_s), _bp_ub_s)
            
            _record_objective_trace({
                "sim_time_s": round(float(time), 1),
                "junction_id": int(self.id),
                "veh_id": int(self.last_detected_bus_id or -1),
                "mode": str(_mode),
                "decision": str(_decision),
                "reason": str(_reason),
                "current_phase": int(current_phase),
                "bus_phase": int(self.BusPhase),
                "bus_eta_s": (round(float(_bus_eta_s), 3) if _bus_eta_s is not None else ""),
                "time_to_bp_s": (round(float(_time_to_bp_s), 3) if _time_to_bp_s is not None else ""),
                "natural_end_s": (round(float(_natural_end_s), 3) if _natural_end_s is not None else ""),
                "next_red_s": (round(float(_next_red_s), 3) if _next_red_s is not None else ""),
                "ge_lb_s": (round(float(_ge_lb_s), 3) if _ge_lb_s is not None else ""),
                "ge_ub_s": (round(float(_ge_ub_s), 3) if _ge_ub_s is not None else ""),
                "opt_ge_s": (round(float(_opt_ge_s), 3) if _opt_ge_s is not None else ""),
                "bp_lb_s": (round(float(_bp_lb_s), 3) if _bp_lb_s is not None else ""),
                "bp_ub_s": (round(float(_bp_ub_s), 3) if _bp_ub_s is not None else ""),
                "opt_bp_s": (round(float(_opt_bp_s), 3) if _opt_bp_s is not None else ""),
                "delay_saved_pax_s": (
                    round(float(_delay_saved_pax_s), 3) if _delay_saved_pax_s is not None else ""
                ),
                "delay_delta_pax_s": (
                    round(float(_delay_delta_pax_s), 3) if _delay_delta_pax_s is not None else ""
                ),
                "delay_base_pax_s": (
                    round(float(_delay_base_pax_s), 3) if _delay_base_pax_s is not None else ""
                ),
                "delay_with_strategy_pax_s": (
                    round(float(_delay_with_strategy_pax_s), 3)
                    if _delay_with_strategy_pax_s is not None else ""
                ),
                "no_strategy_delay_pax_s": (
                    round(float(_delay_base_pax_s), 3)
                    if _delay_base_pax_s is not None else ""
                ),
                "strategy_min_delay_pax_s": (
                    round(float(_delay_with_strategy_pax_s), 3)
                    if _delay_with_strategy_pax_s is not None else ""
                ),
                "delay_rule_pick": (
                    "ACTION" if (
                        _delay_base_pax_s is not None and
                        _delay_with_strategy_pax_s is not None and
                        float(_delay_with_strategy_pax_s) < float(_delay_base_pax_s)
                    ) else "SKIP"
                ),
                "wave_active": int(bool(self._corridor_coord and getattr(self._corridor_coord, '_wave_active', False))),
                "focus_bus_id": int(_focus_bus_id if _focus_bus_id > 0 else -1),
                "note": str(_note or ""),
            })

        # Iterate at least 1 slot: detect_bus() populates index 0 of
        # BusPresence/BusSpeed even when BusDet is empty (no physical detectors).
        _n_det_slots = max(len(self.BusDet), 1)
        for i in range(_n_det_slots):
            bus_speed = self.BusSpeed[0][i]
            if bus_speed <= 0:
                continue

            # ── Global bus focus gate ─────────────────────────────────────────
            # When the Kalman corridor coordinator has designated a focus bus,
            # all other buses still have their detection and stats recorded but
            # receive NO TSP strategy (GE/INS).  This is the enforcement point.
            _det_vid = self.last_detected_bus_id
            if _det_vid and _det_vid > 0 and _is_focus_blocked(_det_vid, self.id, time):
                if LOG_HARMONY:
                    _vprint(
                        f"[BUS_FOCUS] t={time:.1f} inter={self.id} "
                        f"v={_det_vid} SUPPRESSED — focus bus={_focus_bus_id}")
                # Record detection + skip for stats (non-focus bus)
                if not _detection_recorded_this_call:
                    self.stats.record_tsp_event(self.id, 'detection')
                    _detection_recorded_this_call = True
                self.stats.record_tsp_skip(self.id, 'focus_suppressed')
                _mark_detection_point(
                    self.id, _det_vid, 0.0, 0.0, time, "focus_suppress",
                    {"prearm_note": f"focus_bus={_focus_bus_id}"},
                )
                continue

            if current_phase == self.BusPhase:
                red_start        = self.RedStartTimeList[0][i]
                _ps = ECIGetStartingTimePhase(self.node_id)
                _pd = GetPhaseDuration(self.node_id, current_phase, timeSta)
                next_red_start = _ps + _pd
                # Use live remaining distance from ETA tracker if available
                eta_info   = getattr(self, '_bus_eta', {}).get(i)
                _det_dist_fallback = (
                    self.config["DetDistance"][0][i]
                    if self.config.get("DetDistance") and len(self.config["DetDistance"]) > 0
                       and i < len(self.config["DetDistance"][0])
                    else 200.0   # default ~200m upstream detection
                )
                live_dist  = eta_info[2] if eta_info else _det_dist_fallback

                bus_stopline_time = time + live_dist / bus_speed
                _bus_eta_now = bus_stopline_time - time

                # ── ETA horizon gate ─────────────────────────────────────────
                # If the bus is more than MAX_STRATEGY_ETA_S seconds away there
                # is nothing useful to do (GE_lb would exceed MAX_GE_EXTENSION_S,
                # INS lb would exceed BP_upper_bound).  Record the detection for
                # stats but skip all strategy computation.
                if _bus_eta_now > MAX_STRATEGY_ETA_S:
                    if not _detection_recorded_this_call:
                        self.stats.record_tsp_event(self.id, 'detection')
                        _detection_recorded_this_call = True
                    self.stats.record_tsp_skip(self.id, 'eta_horizon')
                    if LOG_HARMONY:
                        _vprint(
                            f"[HARMONY] ETA_SKIP | inter={self.id} "
                            f"eta={_bus_eta_now:.1f}s > MAX={MAX_STRATEGY_ETA_S:.0f}s — "
                            f"bus too far, recording detection only")
                    _trace_objective(
                        "GE", "SKIP", "eta_horizon",
                        _bus_eta_s=_bus_eta_now,
                        _next_red_s=(next_red_start - time),
                    )
                    continue

                if bus_stopline_time <= next_red_start:
                    # Bus will naturally clear on green — no TSP action needed
                    if not _detection_recorded_this_call:
                        self.stats.record_tsp_event(self.id, 'detection')
                        _detection_recorded_this_call = True
                    self.stats.record_tsp_skip(self.id, 'natural_green')
                    _log_local_decision(
                        "harmony-no-ge-local",
                        "NO_GE natural_green_current_phase",
                        bus_stopline_time - time,
                    )
                    _notify_coord_bus_progress(self.last_detected_bus_id, 'natural_green_current_phase')
                    log_to_file(
                        f"[GREEN_GRANT] inter={self.id} t={time:.1f} "
                        f"bus={self.last_detected_bus_id} "
                        f"type=NATURAL source=LOCAL "
                        f"(phase green until {next_red_start:.1f}s bus_arr={bus_stopline_time:.1f}s)",
                        force=True)
                    if LOG_HARMONY:
                        _vprint(
                            f"[HARMONY] NAT_GREEN | inter={self.id} "
                            f"bus_arr={bus_stopline_time:.1f}s < red={next_red_start:.1f}s "
                            f"— no action needed")
                    _trace_objective(
                        "GE", "SKIP", "natural_green_current_phase",
                        _bus_eta_s=(bus_stopline_time - time),
                        _next_red_s=(next_red_start - time),
                    )
                    continue

                if bus_stopline_time > next_red_start and self.TSPStrategy == 0:
                    GE_lb = bus_stopline_time - next_red_start

                    # ── Saturation / throughput guard ─────────────────────────────
                    # Global objective: minimise total pax delay WHILE maintaining
                    # maximum throughput.  Extending green at a saturated approach
                    # does NOT improve throughput (section is at capacity) but DOES
                    # harm side streets.  Skip GE when density exceeds 85 % of jam.
                    _sat_skip = False
                    try:
                        _cur_den = float(self.UpDenList[0][0]) if (
                            hasattr(self, 'UpDenList') and
                            self.UpDenList.shape[1] > 0 and
                            self.UpDenList[0][0] > 0) else 0.0
                        _jam_den = max(float(self.JamDensity), 1.0)
                        if _cur_den > 0.85 * _jam_den:
                            _sat_skip = True
                            if LOG_HARMONY:
                                _vprint(
                                    f"[HARMONY] GE SKIP | inter={self.id} "
                                    f"approach saturated ({_cur_den:.1f}/{_jam_den:.0f} veh/km) "
                                    f"— GE would not improve throughput")
                            if not _detection_recorded_this_call:
                                self.stats.record_tsp_event(self.id, 'detection')
                                _detection_recorded_this_call = True
                            self.stats.record_tsp_skip(self.id, 'ge_trivial')
                    except Exception:
                        pass
                    if _sat_skip:
                        continue

                    # ── Hard cap: skip if bus needs more extension than allowed ─
                    if GE_lb > MAX_GE_EXTENSION_S:
                        if LOG_HARMONY:
                            _vprint(
                                f"[HARMONY] GE SKIP | inter={self.id} "
                                f"needed={GE_lb:.1f}s > MAX_GE={MAX_GE_EXTENSION_S:.0f}s "
                                f"— bus too far, skipping extension")
                        if not _detection_recorded_this_call:
                            self.stats.record_tsp_event(self.id, 'detection')
                            _detection_recorded_this_call = True
                        self.stats.record_tsp_skip(self.id, 'ge_trivial')
                        _trace_objective(
                            "GE", "SKIP", "over_max_extension",
                            _bus_eta_s=(bus_stopline_time - time),
                            _next_red_s=(next_red_start - time),
                            _ge_lb_s=GE_lb,
                            _ge_ub_s=min(float(self.GE_upper_bound), MAX_GE_EXTENSION_S),
                        )
                        _log_local_decision(
                            "harmony-no-ge-local",
                            "NO_GE over_max_extension",
                            bus_stopline_time - time,
                        )
                        continue

                    _ge_ub = min(float(self.GE_upper_bound), MAX_GE_EXTENSION_S)

                    # ── Proposal 4: σ-graduated upper bound for harmony search ──────
                    # Scale _ge_ub proportionally to headway deviation so late buses
                    # can receive the full configured extension while nearly-on-time
                    # buses are capped closer to the minimum needed (GE_lb).
                    # Falls back to full _ge_ub when history is insufficient.
                    _hw_sigma_now  = self._hw_sigma_current
                    _hw_mean_now   = max(self._hw_mean_s, 30.0)
                    _hw_hist_now   = len(self._hw_observed) >= 2
                    if _hw_hist_now and _hw_sigma_now > 0:
                        _ext_frac_hw = min(1.0, _hw_sigma_now / _hw_mean_now)
                        _ge_lb_cfg   = float(self.GE_lower_bound) if self.GE_lower_bound > 0 else 5.0
                        _hw_ge_ub    = _ge_lb_cfg + _ext_frac_hw * (_ge_ub - _ge_lb_cfg)
                        # Never cap below GE_lb (the minimum needed to catch the light)
                        _ge_ub = min(_ge_ub, max(_hw_ge_ub, GE_lb))
                        if LOG_HARMONY:
                            _vprint(
                                f"[HARMONY σ-GRAD] inter={self.id} t={time:.1f} "
                                f"σ={_hw_sigma_now:.0f}s mean={_hw_mean_now:.0f}s "
                                f"frac={_ext_frac_hw:.2f} hw_ub={_hw_ge_ub:.1f}s "
                                f"effective_ub={_ge_ub:.1f}s (proposal 4)")

                    # Block local Harmony Search while coordinator wave is active.
                    # The wave manages this junction's TSP via the pre-arm mechanism.
                    if self._corridor_coord is not None and COORDINATED_TSP:
                        _wave_bus = int(getattr(self._corridor_coord, '_wave_veh_id', -1) or -1)
                        _this_bus = int(self.last_detected_bus_id or -1)
                        if self._corridor_coord._wave_active and _wave_bus > 0 and _wave_bus != _this_bus:
                            return False

                    opt_GE = harmony_search(
                        self.GE_Objective_Function, float(self.GE_lower_bound), _ge_ub,
                        self.max_iterations, self.harmony_memory_size,
                        self.hmcr, self.par, 5, time)
                    if math.isnan(opt_GE) or opt_GE < 0:
                        opt_GE = min(10.0, _ge_ub)

                    # Hard-cap result to MAX_GE_EXTENSION_S
                    opt_GE = min(opt_GE, MAX_GE_EXTENSION_S)

                    # ── Cap GE to what this cycle can actually recover ──────────
                    # Prevents granting 28 s of GE when the remaining phases
                    # only have 5 s of combined headroom — which would leave a
                    # massive irrecoverable debt and inflate cycle length.
                    _min_floor_ge  = float(self.config.get('MinGreen', 5.0))
                    _max_trim_frac = 0.50
                    _recoverable = 0.0
                    _phase_list    = getattr(self, 'phase_list', [])
                    if _phase_list and current_phase in _phase_list:
                        _ci = _phase_list.index(current_phase)
                        _n  = len(_phase_list)
                        _upcoming_ge = [
                            _phase_list[(_ci + _k) % _n]
                            for _k in range(1, _n)
                        ]
                        _upcoming_ge = [
                            p for p in _upcoming_ge
                            if p != self.BusPhase and p != current_phase
                        ]
                        _recoverable = 0.0
                        for _ph in _upcoming_ge:
                            _nom = self._nominal_phase_durations.get(_ph)
                            if _nom is None:
                                try:
                                    _nom = GetPhaseDuration(self.node_id, _ph, timeSta)
                                except Exception:
                                    _nom = 15.0
                                if not _nom or _nom <= 0:
                                    _nom = 15.0
                            _nom = max(float(_nom), _min_floor_ge)
                            _hr  = max(0.0, _nom - _min_floor_ge)
                            _hr  = min(_hr, _nom * _max_trim_frac)
                            _recoverable += _hr
                        if _recoverable > 0.5 and opt_GE > _recoverable:
                            if LOG_HARMONY:
                                _vprint(
                                    f"[HARMONY] GE cap | inter={self.id} "
                                    f"opt_GE={opt_GE:.1f}s → capped to "
                                    f"{_recoverable:.1f}s (cycle headroom limit)"
                                )
                            opt_GE = _recoverable

                    # After capping: verify extension is still sufficient to guarantee the bus
                    # makes the light. If the recoverable headroom is less than the minimum
                    # needed (GE_lb = bus_stopline_time − next_red_start), applying an
                    # insufficient extension is worse than no action — skip it instead.
                    if opt_GE < GE_lb:
                        if LOG_HARMONY:
                            _vprint(
                                f"[HARMONY] GE SKIP | inter={self.id} "
                                f"capped_GE={opt_GE:.1f}s < needed={GE_lb:.1f}s "
                                f"(cycle headroom {_recoverable:.1f}s insufficient "
                                f"— bus cannot be guaranteed through the light)")
                        if not _detection_recorded_this_call:
                            self.stats.record_tsp_event(self.id, 'detection')
                            _detection_recorded_this_call = True
                        self.stats.record_tsp_skip(self.id, 'ge_trivial')
                        _trace_objective(
                            "GE", "SKIP", "insufficient_cycle_headroom",
                            _bus_eta_s=(bus_stopline_time - time),
                            _next_red_s=(next_red_start - time),
                            _ge_lb_s=float(self.GE_lower_bound),
                            _ge_ub_s=_ge_ub,
                            _opt_ge_s=opt_GE,
                            _note=f"recoverable={_recoverable:.2f}|needed={GE_lb:.2f}",
                        )
                        _log_local_decision(
                            "harmony-no-ge-local",
                            "NO_GE insufficient_cycle_headroom",
                            bus_stopline_time - time,
                        )
                        continue

                    # Skip if harmony says extension is trivially small
                    if opt_GE < 0.5:
                        if LOG_HARMONY:
                            _vprint(
                                f"[HARMONY] GE skip | inter={self.id} "
                                f"opt_GE={opt_GE:.2f}s < 0.5 s — no action")
                        if not _detection_recorded_this_call:
                            self.stats.record_tsp_event(self.id, 'detection')
                            _detection_recorded_this_call = True
                        self.stats.record_tsp_skip(self.id, 'ge_trivial')
                        _trace_objective(
                            "GE", "SKIP", "not_optimal",
                            _bus_eta_s=(bus_stopline_time - time),
                            _next_red_s=(next_red_start - time),
                            _ge_lb_s=float(self.GE_lower_bound),
                            _ge_ub_s=_ge_ub,
                            _opt_ge_s=opt_GE,
                        )
                        _log_local_decision(
                            "harmony-no-ge-local",
                            "NO_GE not_optimal",
                            bus_stopline_time - time,
                        )
                        # Log wave event: bus detected, harmony evaluated GE but not beneficial
                        _grp = self._corridor_coord.name if self._corridor_coord else "local"
                        _record_wave_event(
                            time, _grp, "tsp_skip",
                            source_jct=self.id, target_jct=self.id,
                            veh_id=self.last_detected_bus_id or -1,
                            note="ge_not_optimal",
                        )
                        continue

                    # ── Delay-savings estimate (corrected split-accounting model) ──────
                    # BUG FIX: GE_Objective_Function(GE) never includes the bus-benefit
                    # term because BusDelay[0] doesn't depend on GE.  Comparing
                    # GE_Objective_Function(opt_GE) vs GE_Objective_Function(0) only
                    # measures the COST to other traffic, so GE always appears to
                    # increase total delay and is always suppressed.
                    #
                    # Corrected approach:
                    #   bus_benefit  = time the bus would actually wait at the stop line
                    #                  WITHOUT GE = (red_duration − GE_lb) × BusOcc
                    #                  where GE_lb = bus_stopline_time − next_red_start
                    #                  (NOT the full red_duration, because the bus has
                    #                   already missed GE_lb seconds of the red cycle)
                    #   side_cost    = GE_Objective_Function(opt_GE) – GE_Objective_Function(0)
                    #                = INCREMENTAL cost to other traffic at THIS intersection
                    #   net_saving   = bus_benefit – side_cost
                    #
                    # NOTE: delay_saved_pax_s is LOCAL to this intersection only.
                    # It does not capture corridor spillback / downstream congestion
                    # caused by phase-debt recovery shortening non-bus phases.
                    _raw_red_dur = (
                        float(self.RedDurationList[0][0])
                        if (hasattr(self, 'RedDurationList')
                            and len(self.RedDurationList) > 0
                            and len(self.RedDurationList[0]) > 0
                            and float(self.RedDurationList[0][0]) > 1.0)
                        else max(0.0, float(self.config.get('CycleTime', 135))
                                 - float(self.BusPhaseDuration))
                    )
                    # Bus actually waits (red_duration - GE_lb) at the stop line;
                    # GE_lb seconds of the red cycle already elapsed before bus arrives.
                    _actual_bus_wait_s = max(0.0, _raw_red_dur - GE_lb)
                    _bus_benefit_pax_s = _actual_bus_wait_s * self.BusOcc
                    _delay_with_ge     = self.GE_Objective_Function(float(opt_GE), time)
                    _delay_no_action   = self.GE_Objective_Function(0.0, time)
                    _side_cost_pax_s_raw = max(0.0, _delay_with_ge - _delay_no_action)
                    _risk_mult, _risk_diag = _system_risk_multiplier()
                    _side_cost_pax_s   = _side_cost_pax_s_raw * _risk_mult
                    _delay_delta_pax_s = _bus_benefit_pax_s - _side_cost_pax_s
                    _delay_saved_pax_s = max(0.0, _delay_delta_pax_s)
                    # For trace compatibility, map to legacy field names:
                    # delay_base_pax_s  ← bus benefit (what we save if bus catches green)
                    # delay_with_strategy_pax_s ← side cost (what others lose due to GE)
                    _delay_no_action   = _bus_benefit_pax_s   # re-assign for trace fields
                    _delay_with_ge     = _side_cost_pax_s     # re-assign for trace fields
                    if _delay_saved_pax_s <= 0.0:
                        # GE not worthwhile: side-street cost exceeds bus passenger benefit.
                        if not _detection_recorded_this_call:
                            self.stats.record_tsp_event(self.id, 'detection')
                            _detection_recorded_this_call = True
                        self.stats.record_tsp_skip(self.id, 'ge_trivial')
                        _trace_objective(
                            "GE", "SKIP", "no_delay_saving",
                            _bus_eta_s=(bus_stopline_time - time),
                            _next_red_s=(next_red_start - time),
                            _ge_lb_s=float(self.GE_lower_bound),
                            _ge_ub_s=_ge_ub,
                            _opt_ge_s=opt_GE,
                            _delay_saved_pax_s=0.0,
                            _delay_delta_pax_s=_delay_delta_pax_s,
                            _delay_base_pax_s=_delay_no_action,
                            _delay_with_strategy_pax_s=_delay_with_ge,
                            _note=(
                                f"bus_benefit={_bus_benefit_pax_s:.1f}|"
                                f"side_cost={_side_cost_pax_s:.1f}|raw_cost={_side_cost_pax_s_raw:.1f}|"
                                f"red_dur={_raw_red_dur:.1f}|ge_lb={GE_lb:.1f}|"
                                f"bus_wait={_actual_bus_wait_s:.1f}|bus_occ={self.BusOcc:.0f}|"
                                f"{_risk_diag}"
                            ),
                        )
                        continue

                    remain = GetPhaseDuration(self.node_id, current_phase, timeSta) \
                             - (time - ECIGetStartingTimePhase(self.node_id))
                    ECIChangeTimingPhase(self.node_id, current_phase,
                                         self.BusPhaseDuration + float(opt_GE), timeSta)
                    self.TimeToTerminateBusPhase = time + remain + opt_GE
                    self.TSPStrategy = 1
                    self.flag        = 1
                    self.TSPActiveTime = time + float(opt_GE) + 30
                    self._tsp_cycle_grant_until = time + self.config.get('CycleTime', 135)
                    self._ge_debt_s = float(opt_GE)
                    self._ge_opt_GE = float(opt_GE)
                    _ge_events.append((time, self.id, float(opt_GE), _delay_saved_pax_s))
                    log_to_file(
                        f"[GREEN_GRANT] inter={self.id} t={time:.1f} "
                        f"bus={self.last_detected_bus_id} "
                        f"eta={bus_stopline_time - time:.1f}s "
                        f"type=LOCAL_GE source=LOCAL GE={opt_GE:.1f}s "
                        f"pax_delay_saved={_delay_saved_pax_s:.1f}s",
                        force=True)
                    if LOG_HARMONY:
                        _vprint(
                            f"[HARMONY] GE | t={time:.1f}s inter={self.id} "
                            f"bus_eta={bus_stopline_time - time:.1f}s "
                            f"next_red={next_red_start - time:.1f}s "
                            f"opt_GE={opt_GE:.1f}s "
                            f"pax_saved={_delay_saved_pax_s:.1f}s")
                    _trace_objective(
                        "GE", "ACTION", "grant_extension",
                        _bus_eta_s=(bus_stopline_time - time),
                        _next_red_s=(next_red_start - time),
                        _ge_lb_s=float(self.GE_lower_bound),
                        _ge_ub_s=_ge_ub,
                        _opt_ge_s=opt_GE,
                        _delay_saved_pax_s=_delay_saved_pax_s,
                        _delay_delta_pax_s=_delay_delta_pax_s,
                        _delay_base_pax_s=_delay_no_action,
                        _delay_with_strategy_pax_s=_delay_with_ge,
                        _note=(
                            f"bus_benefit={_bus_benefit_pax_s:.1f}|"
                            f"side_cost={_side_cost_pax_s:.1f}|raw_cost={_side_cost_pax_s_raw:.1f}|"
                            f"net_saved={_delay_saved_pax_s:.1f}|"
                            f"red_dur={_raw_red_dur:.1f}|ge_lb={GE_lb:.1f}|"
                            f"bus_wait={_actual_bus_wait_s:.1f}|bus_occ={self.BusOcc:.0f}|"
                            f"{_risk_diag}"
                        ),
                    )
                    self.highlight_bus(self.last_detected_bus_id)
                    if not _detection_recorded_this_call:
                        self.stats.record_tsp_event(self.id, 'detection')
                        _detection_recorded_this_call = True
                    self.stats.record_tsp_event(self.id, 'extension')
                    self.stats.record_tsp_extension_duration(self.id, float(opt_GE))
                    _mark_detection_point(
                        self.id, self.last_detected_bus_id, 0.0, 0.0, time,
                        "harmony-ge-local",
                        {
                            "force_write": True,
                            "prearm_status": "action",
                            "prearm_eta_s": round(max(0.0, float(bus_stopline_time - time)), 1),
                            "prearm_note": f"GE {float(opt_GE):.1f}s local",
                        },
                    )
                    # Acquire global bus focus
                    if self.last_detected_bus_id and self.last_detected_bus_id > 0:
                        _acquire_focus(self.last_detected_bus_id, self.id, time)
                    # Notify corridor coordinator so it can Kalman-predict and
                    # pre-arm downstream intersections (HARMONY coordination).
                    if self._corridor_coord is not None and COORDINATED_TSP:
                        try:
                            self._corridor_coord.notify_bus_granted(
                                self.last_detected_bus_id, self.id, time, None)
                        except Exception:
                            pass
                    return True

            else:
                # ── Phase insertion need assessment ────────────────────────
                # Theory: only insert if bus will MISS the next natural BusPhase
                # green. Compute time from now to the natural next BusPhase start.
                bus_approaching = (
                    self.BusPresence[0][i] == 1
                    and bus_speed > 0
                )
                if not (current_phase in self.PhaseIndex
                        and bus_approaching
                        and self.TSPStrategy == 0):
                    continue

                # Time remaining in current phase
                _ps_now        = ECIGetStartingTimePhase(self.node_id)
                _elapsed       = max(0.0, time - _ps_now)
                _rem_current   = max(0.0,
                    GetPhaseDuration(self.node_id, current_phase, timeSta) - _elapsed)

                # Walk phase sequence from current to BusPhase
                _time_to_bp = _rem_current
                try:
                    _ci  = self.phase_list.index(current_phase)
                    _bi  = self.phase_list.index(self.BusPhase)
                    _n   = len(self.phase_list)
                    _steps = (_bi - _ci) % _n  # phases between current+1 and BusPhase
                    for _k in range(1, _steps):
                        _ph = self.phase_list[(_ci + _k) % _n]
                        _time_to_bp += GetPhaseDuration(self.node_id, _ph, timeSta)
                except (ValueError, Exception):
                    _time_to_bp = float(self.config.get('CycleTime', 135))

                # Bus ETA to stopline (seconds from now)
                _eta_info  = getattr(self, '_bus_eta', {}).get(i)
                _det_dist_fb = (
                    self.config['DetDistance'][0][i]
                    if self.config.get('DetDistance') and len(self.config['DetDistance']) > 0
                       and i < len(self.config['DetDistance'][0])
                    else 200.0
                )
                _bus_eta_s = _eta_info[1] if _eta_info else (_det_dist_fb / bus_speed)

                # ── ETA horizon gate ─────────────────────────────────────────
                if _bus_eta_s > MAX_STRATEGY_ETA_S:
                    if not _detection_recorded_this_call:
                        self.stats.record_tsp_event(self.id, 'detection')
                        _detection_recorded_this_call = True
                    self.stats.record_tsp_skip(self.id, 'eta_horizon')
                    _trace_objective(
                        "INS", "SKIP", "eta_horizon",
                        _bus_eta_s=_bus_eta_s,
                        _time_to_bp_s=_time_to_bp,
                    )
                    continue

                _bus_eta_effective_s = _bus_eta_s + float(INS_CLEARANCE_BUFFER_S)

                if LOG_HARMONY:
                    _vprint(
                        f"[INS DEBUG] inter={self.id} bus={self.last_detected_bus_id} "
                        f"eta={_bus_eta_s:.1f}s eta_eff={_bus_eta_effective_s:.1f}s "
                        f"(clr_buf={INS_CLEARANCE_BUFFER_S:.1f}s) to_bp={_time_to_bp:.1f}s "
                        f"bp_dur={self.BusPhaseDuration:.1f}s curr_phase={current_phase} "
                        f"bus_phase={self.BusPhase} strat={self.TSPStrategy}"
                    )

                # Insert when either:
                #  1) bus misses natural bus-phase window, OR
                #  2) bus would wait too long for next natural bus-phase start.
                _natural_bus_end = _time_to_bp + self.BusPhaseDuration
                _ins_trigger_margin_s = float(INS_TRIGGER_MARGIN_S)
                try:
                    _ins_trigger_margin_s = max(
                        float(INS_TRIGGER_MARGIN_MIN_S),
                        min(float(INS_TRIGGER_MARGIN_MAX_S),
                            float(INS_TRIGGER_MARGIN_S) + 0.15 * max(float(_bus_eta_s), 0.0))
                    )
                except Exception:
                    _ins_trigger_margin_s = float(INS_TRIGGER_MARGIN_S)
                _ins_trigger_threshold = _natural_bus_end - _ins_trigger_margin_s
                _wait_to_natural_s = max(0.0, _time_to_bp - _bus_eta_effective_s)
                _miss_natural_window = (_bus_eta_effective_s > _ins_trigger_threshold)
                _wait_too_long = (_wait_to_natural_s > float(INS_MAX_WAIT_TRIGGER_S))

                if (not _miss_natural_window) and (not _wait_too_long):
                    # Bus can catch the natural green — no insertion needed
                    if LOG_HARMONY:
                        _vprint(
                            f"[HARMONY] NO INSERT inter={self.id} "
                            f"bus_eta_eff={_bus_eta_effective_s:.1f}s <= "
                            f"threshold={_ins_trigger_threshold:.1f}s "
                            f"wait_to_bp={_wait_to_natural_s:.1f}s <= wait_thr={INS_MAX_WAIT_TRIGGER_S:.1f}s "
                            f"(natural_end={_natural_bus_end:.1f}s margin={_ins_trigger_margin_s:.1f}s) "
                            f"(to_bp={_time_to_bp:.1f}s + dur={self.BusPhaseDuration:.1f}s)")
                    if not _detection_recorded_this_call:
                        self.stats.record_tsp_event(self.id, 'detection')
                        _detection_recorded_this_call = True
                    self.stats.record_tsp_skip(self.id, 'natural_green')
                    _noins_note = _fmt_noins_reason(
                        "NO_INS natural_green_future_bus_phase",
                        eta_s=float(_bus_eta_s),
                        to_bp_s=float(_time_to_bp),
                        nat_end_s=float(_natural_bus_end),
                        bp_dur_s=float(self.BusPhaseDuration),
                    )
                    _log_local_decision(
                        "harmony-no-ins-local",
                        _noins_note,
                        _bus_eta_s,
                    )
                    if LOG_HARMONY:
                        _vprint(f"[HARMONY NO_INS] inter={self.id} {_noins_note}")
                    _trace_objective(
                        "INS", "SKIP", "natural_green_future_bus_phase",
                        _bus_eta_s=_bus_eta_s,
                        _time_to_bp_s=_time_to_bp,
                        _natural_end_s=_natural_bus_end,
                        _bp_lb_s=float(self.BP_lower_bound),
                        _bp_ub_s=float(self.BP_upper_bound),
                        _opt_bp_s=None,  # No optimization performed, skipped
                        _note=(
                            f"eta_eff={_bus_eta_effective_s:.1f};"
                            f"wait_to_bp={_wait_to_natural_s:.1f};"
                            f"wait_thr={INS_MAX_WAIT_TRIGGER_S:.1f}"
                        ),
                    )
                    _notify_coord_bus_progress(self.last_detected_bus_id, 'natural_green_future_bus_phase')
                    continue

                # Bus misses natural window OR wait is too long → evaluate insertion.
                if LOG_HARMONY:
                    _trigger_reason = (
                        "miss_natural_window" if _miss_natural_window else "wait_too_long"
                    )
                    _vprint(
                        f"[INS DEBUG] evaluate INS inter={self.id} bus={self.last_detected_bus_id} "
                        f"eta_eff={_bus_eta_effective_s:.1f}s > threshold={_ins_trigger_threshold:.1f}s "
                        f"(natural_end={_natural_bus_end:.1f}s margin={_ins_trigger_margin_s:.1f}s) "
                        f"wait_to_bp={_wait_to_natural_s:.1f}s reason={_trigger_reason}"
                    )
                # ── Prefer natural phase completion ───────────────────
                # If the current phase is nearly done (< 8s remaining),
                # defer the insertion to the natural transition — this
                # avoids abruptly cutting a phase that's about to end
                # and reduces disruption to other traffic.
                _NATURAL_COMPLETION_THRESHOLD = 8.0
                if _rem_current <= _NATURAL_COMPLETION_THRESHOLD and _rem_current > 0.5:
                    if LOG_HARMONY:
                        _vprint(
                            f"[HARMONY] INS DEFER | inter={self.id} "
                            f"phase_rem={_rem_current:.1f}s < {_NATURAL_COMPLETION_THRESHOLD:.0f}s "
                            f"— waiting for natural phase completion")
                    continue  # will re-evaluate next step when phase transitions

                # The lower bound must guarantee the bus will arrive and clear
                # during the inserted phase: use bus ETA + 2 s headway buffer.
                # If even this minimum exceeds the upper bound, the bus is too far
                # away for a practical insertion — skip rather than insert too short.
                _bp_lb_effective = max(float(self.BP_lower_bound), _bus_eta_s + 2.0)
                if _bp_lb_effective >= float(self.BP_upper_bound):
                    if LOG_HARMONY:
                        _vprint(
                            f"[HARMONY] INS SKIP | inter={self.id} "
                            f"bus_eta={_bus_eta_s:.1f}s → lb={_bp_lb_effective:.1f}s "
                            f">= BP_upper={self.BP_upper_bound:.0f}s "
                            f"— insertion impractical (bus too far away)")
                    if not _detection_recorded_this_call:
                        self.stats.record_tsp_event(self.id, 'detection')
                        _detection_recorded_this_call = True
                    self.stats.record_tsp_skip(self.id, 'ins_trivial')
                    _noins_note = _fmt_noins_reason(
                        "NO_INS impractical_upper_bound",
                        eta_s=float(_bus_eta_s),
                        lb_s=float(_bp_lb_effective),
                        ub_s=float(self.BP_upper_bound),
                    )
                    _log_local_decision(
                        "harmony-no-ins-local",
                        _noins_note,
                        _bus_eta_s,
                    )
                    if LOG_HARMONY:
                        _vprint(f"[HARMONY NO_INS] inter={self.id} {_noins_note}")
                    _trace_objective(
                        "INS", "SKIP", "impractical_upper_bound",
                        _bus_eta_s=_bus_eta_s,
                        _time_to_bp_s=_time_to_bp,
                        _natural_end_s=_natural_bus_end,
                        _bp_lb_s=float(self.BP_lower_bound),
                        _bp_ub_s=float(self.BP_upper_bound),
                        _opt_bp_s=None,
                    )
                    continue

                # Block local Harmony Search while coordinator wave is active.
                if self._corridor_coord is not None and COORDINATED_TSP:
                    _wave_bus = int(getattr(self._corridor_coord, '_wave_veh_id', -1) or -1)
                    _this_bus = int(self.last_detected_bus_id or -1)
                    if self._corridor_coord._wave_active and _wave_bus > 0 and _wave_bus != _this_bus:
                        return False

                opt_BP = harmony_search(
                    self.BP_Objective_Function, float(self.BP_lower_bound),
                    self.BP_upper_bound, self.max_iterations,
                    self.harmony_memory_size, self.hmcr, self.par, 5, time)

                # Skip if harmony says insertion phase is trivially short.
                # Special handling when BP_lower_bound=0 ("don't apply" option):
                #  • Lower bound becomes max(0, _bus_eta_s + 2.0)
                #  • If opt_BP < 10s and BP_lower_bound=0, treat as "not optimal" since
                #    we have the option to not insert, and short insertions are wasteful.
                _bp_min_viable = max(0.1, float(self.BP_lower_bound) - 0.5)
                _bp_lb_config = float(self.BP_lower_bound)
                
                if math.isnan(opt_BP):
                    if LOG_HARMONY:
                        _vprint(
                            f"[HARMONY] INS skip | inter={self.id} "
                            f"opt_BP=NaN — harmony search failed")
                    if not _detection_recorded_this_call:
                        self.stats.record_tsp_event(self.id, 'detection')
                        _detection_recorded_this_call = True
                    self.stats.record_tsp_skip(self.id, 'ins_trivial')
                    _noins_note = _fmt_noins_reason(
                        "NO_INS not_optimal",
                        eta_s=float(_bus_eta_s),
                        lb_s=float(_bp_lb_effective),
                        ub_s=float(self.BP_upper_bound),
                        opt_bp_s=-1.0,
                    )
                    _log_local_decision(
                        "harmony-no-ins-local",
                        _noins_note,
                        _bus_eta_s,
                    )
                    if LOG_HARMONY:
                        _vprint(f"[HARMONY NO_INS] inter={self.id} {_noins_note}")
                    _trace_objective(
                        "INS", "SKIP", "harmony_nan",
                        _bus_eta_s=_bus_eta_s,
                        _time_to_bp_s=_time_to_bp,
                        _natural_end_s=_natural_bus_end,
                        _bp_lb_s=float(self.BP_lower_bound),
                        _bp_ub_s=float(self.BP_upper_bound),
                        _opt_bp_s=opt_BP,
                    )
                    continue
                
                # Clamp to effective bounds
                opt_BP_clamped = max(float(_bp_lb_effective), min(float(opt_BP), float(self.BP_upper_bound)))
                
                # ── Skip if result is too short (< 10s) when BP_lower_bound=0 ──
                # When BP_lower_bound=0, it means "don't apply insertion" is a valid option.
                # If harmony finds opt_BP < 10s, that's not beneficial enough to justify
                # the insertion action — skip and let natural green or GE handle it.
                if _bp_lb_config <= 0.0 and opt_BP_clamped < 10.0:
                    if LOG_HARMONY:
                        _vprint(
                            f"[HARMONY] INS skip | inter={self.id} "
                            f"opt_BP={opt_BP_clamped:.2f}s < 10s with BP_lower_bound=0 "
                            f"— not optimal (no insertion option available)")
                    if not _detection_recorded_this_call:
                        self.stats.record_tsp_event(self.id, 'detection')
                        _detection_recorded_this_call = True
                    self.stats.record_tsp_skip(self.id, 'ins_trivial')
                    _noins_note = _fmt_noins_reason(
                        "NO_INS too_short",
                        eta_s=float(_bus_eta_s),
                        lb_s=0.0,
                        opt_bp_s=float(opt_BP),
                    )
                    _log_local_decision(
                        "harmony-no-ins-local",
                        _noins_note,
                        _bus_eta_s,
                    )
                    if LOG_HARMONY:
                        _vprint(f"[HARMONY NO_INS] inter={self.id} {_noins_note}")
                    _trace_objective(
                        "INS", "SKIP", "not_optimal_too_short",
                        _bus_eta_s=_bus_eta_s,
                        _time_to_bp_s=_time_to_bp,
                        _natural_end_s=_natural_bus_end,
                        _bp_lb_s=float(self.BP_lower_bound),
                        _bp_ub_s=float(self.BP_upper_bound),
                        _opt_bp_s=float(opt_BP),
                    )
                    continue
                
                if opt_BP_clamped < _bp_min_viable:
                    if LOG_HARMONY:
                        _vprint(
                            f"[HARMONY] INS skip | inter={self.id} "
                            f"opt_BP={opt_BP:.2f}s → clamped={opt_BP_clamped:.2f}s < {_bp_min_viable:.2f}s — below viable")
                    if not _detection_recorded_this_call:
                        self.stats.record_tsp_event(self.id, 'detection')
                        _detection_recorded_this_call = True
                    self.stats.record_tsp_skip(self.id, 'ins_trivial')
                    _noins_note = _fmt_noins_reason(
                        "NO_INS not_optimal",
                        eta_s=float(_bus_eta_s),
                        lb_s=float(_bp_lb_effective),
                        ub_s=float(self.BP_upper_bound),
                        opt_bp_s=float(opt_BP),
                    )
                    _log_local_decision(
                        "harmony-no-ins-local",
                        _noins_note,
                        _bus_eta_s,
                    )
                    if LOG_HARMONY:
                        _vprint(f"[HARMONY NO_INS] inter={self.id} {_noins_note}")
                    _trace_objective(
                        "INS", "SKIP", "not_optimal",
                        _bus_eta_s=_bus_eta_s,
                        _time_to_bp_s=_time_to_bp,
                        _natural_end_s=_natural_bus_end,
                        _bp_lb_s=float(self.BP_lower_bound),
                        _bp_ub_s=float(self.BP_upper_bound),
                        _opt_bp_s=float(opt_BP),
                    )
                    continue

                # Use clamped value for phase insertion
                opt_BP = opt_BP_clamped

                # Hard cap: never hold bus phase longer than MAX_BP_INSERTION_S
                opt_BP = min(float(opt_BP), MAX_BP_INSERTION_S)

                # ── Delay-savings estimate (corrected split-accounting model) ──────
                # Mirrors the GE fix: BP_Objective_Function's BusDelay term doesn't
                # encode the bus-benefit (avoided waiting for natural bus phase).
                # Bus benefit = time bus would wait for natural bus phase × BusOcc.
                # Side cost  = BP_Objective_Function(opt_BP) – BP_Objective_Function(0)
                #             = incremental cost to other traffic from the insertion.
                _ins_bus_benefit_pax_s = float(_time_to_bp) * self.BusOcc
                _ins_delay_with  = self.BP_Objective_Function(float(opt_BP), time)
                _ins_delay_base  = self.BP_Objective_Function(0.0, time)
                _ins_side_cost_raw = max(0.0, _ins_delay_with - _ins_delay_base)
                _ins_risk_mult, _ins_risk_diag = _system_risk_multiplier()
                _ins_side_cost   = _ins_side_cost_raw * _ins_risk_mult
                _ins_delay_delta = _ins_bus_benefit_pax_s - _ins_side_cost
                _ins_delay_saved = max(0.0, _ins_delay_delta)
                # Re-map for trace fields (legacy naming):
                _ins_delay_base  = _ins_bus_benefit_pax_s
                _ins_delay_with  = _ins_side_cost
                if _ins_delay_saved <= 0.0:
                    if not _detection_recorded_this_call:
                        self.stats.record_tsp_event(self.id, 'detection')
                        _detection_recorded_this_call = True
                    self.stats.record_tsp_skip(self.id, 'ins_trivial')
                    _trace_objective(
                        "INS", "SKIP", "no_delay_saving",
                        _bus_eta_s=_bus_eta_s,
                        _time_to_bp_s=_time_to_bp,
                        _natural_end_s=_natural_bus_end,
                        _bp_lb_s=float(self.BP_lower_bound),
                        _bp_ub_s=float(self.BP_upper_bound),
                        _opt_bp_s=float(opt_BP),
                        _delay_saved_pax_s=0.0,
                        _delay_delta_pax_s=_ins_delay_delta,
                        _delay_base_pax_s=_ins_delay_base,
                        _delay_with_strategy_pax_s=_ins_delay_with,
                        _note=(
                            f"bus_benefit={_ins_bus_benefit_pax_s:.1f}|"
                            f"side_cost={_ins_side_cost:.1f}|raw_cost={_ins_side_cost_raw:.1f}|"
                            f"time_to_bp={_time_to_bp:.1f}|bus_occ={self.BusOcc:.0f}|"
                            f"{_ins_risk_diag}"
                        ),
                    )
                    continue

                self.previous_phase  = current_phase
                self.BusPhaseEndTime = time + float(opt_BP)
                ECIChangeTimingPhase(self.id, self.BusPhase, float(opt_BP), timeSta)
                ECIChangeDirectPhase(
                    self.id, self.BusPhase, timeSta, time, acycle, 0)
                self.TSPStrategy   = 2
                self.flag          = 2
                self.TSPActiveTime = time + float(opt_BP) + 30
                self._ge_debt_s    = float(opt_BP)
                self._tsp_cycle_grant_until = time + self.config.get('CycleTime', 135)
                log_to_file(
                    f"[GREEN_GRANT] inter={self.id} t={time:.1f} "
                    f"bus={self.last_detected_bus_id} "
                    f"eta={_bus_eta_s:.1f}s "
                    f"type=LOCAL_INS source=LOCAL BP={opt_BP:.1f}s "
                    f"pax_delay_saved={_ins_delay_saved:.1f}s",
                    force=True)
                if LOG_HARMONY:
                    _vprint(
                        f"[HARMONY] INSERTION | t={time:.1f}s inter={self.id} "
                        f"bus_eta={_bus_eta_s:.1f}s > natural_end={_natural_bus_end:.1f}s "
                        f"opt_BP={opt_BP:.1f}s pax_saved={_ins_delay_saved:.1f}s")
                _trace_objective(
                    "INS", "ACTION", "grant_insertion",
                    _bus_eta_s=_bus_eta_s,
                    _time_to_bp_s=_time_to_bp,
                    _natural_end_s=_natural_bus_end,
                    _bp_lb_s=float(self.BP_lower_bound),
                    _bp_ub_s=float(self.BP_upper_bound),
                    _opt_bp_s=float(opt_BP),
                    _delay_saved_pax_s=_ins_delay_saved,
                    _delay_delta_pax_s=_ins_delay_delta,
                    _delay_base_pax_s=_ins_delay_base,
                    _delay_with_strategy_pax_s=_ins_delay_with,
                    _note=(
                        f"bus_benefit={_ins_bus_benefit_pax_s:.1f}|"
                        f"side_cost={_ins_side_cost:.1f}|raw_cost={_ins_side_cost_raw:.1f}|"
                        f"net_saved={_ins_delay_saved:.1f}|"
                        f"eta_eff={_bus_eta_effective_s:.1f};"
                        f"wait_to_bp={max(0.0, _time_to_bp - _bus_eta_effective_s):.1f};"
                        f"wait_thr={INS_MAX_WAIT_TRIGGER_S:.1f};"
                        f"{_ins_risk_diag}"
                    ),
                )
                self.highlight_bus(self.last_detected_bus_id)
                if not _detection_recorded_this_call:
                    self.stats.record_tsp_event(self.id, 'detection')
                    _detection_recorded_this_call = True
                self.stats.record_tsp_event(self.id, 'insertion')
                self.stats.record_tsp_insertion_duration(self.id, float(opt_BP))
                self.stats.record_tsp_insertion_wait(self.id, max(0.0, float(_bus_eta_s)))
                _mark_detection_point(
                    self.id, self.last_detected_bus_id, 0.0, 0.0, time,
                    "harmony-ins-local",
                    {
                        "force_write": True,
                        "prearm_status": "action",
                        "prearm_eta_s": round(max(0.0, float(_bus_eta_s)), 1),
                        "prearm_note": f"INS {float(opt_BP):.1f}s local",
                    },
                )
                # Acquire global bus focus
                if self.last_detected_bus_id and self.last_detected_bus_id > 0:
                    _acquire_focus(self.last_detected_bus_id, self.id, time)
                # Notify corridor coordinator for downstream pre-arming.
                if self._corridor_coord is not None and COORDINATED_TSP:
                    try:
                        self._corridor_coord.notify_bus_granted(
                            self.last_detected_bus_id, self.id, time, None)
                    except Exception:
                        pass
                return True

        # ── No GE or INS was applied this call ───────────────────────────────
        # Only cancel the coordination wave if the wave bus is NOWHERE in the
        # corridor — not just absent at the origin junction.  After the bus
        # passes the origin it is detected at downstream junctions; cancelling
        # here would kill pre-arms that those junctions still need.
        if (not _detection_recorded_this_call and
                not _coord_notified_this_call and
                self._corridor_coord is not None and COORDINATED_TSP):
            if (self._corridor_coord._wave_active and
                    self._corridor_coord._wave_origin == self.id):
                _wave_vid = int(getattr(self._corridor_coord, '_wave_veh_id', -1) or -1)

                # Check 1: is the wave bus visible at ANY corridor junction?
                _bus_seen_in_corridor = False
                if _wave_vid > 0:
                    for _jid in self._corridor_coord.inter_ids:
                        if _wave_vid in _tracking_zone_presence.get(_jid, {}):
                            _bus_seen_in_corridor = True
                            break
                    # Check 2: has the bus been observed at any downstream junction?
                    if not _bus_seen_in_corridor:
                        _obs = _bus_observed_jcts.get(_wave_vid)
                        if _obs:
                            _cc_ids = set(self._corridor_coord.inter_ids)
                            _served = getattr(self._corridor_coord, '_wave_served_ids', set())
                            # Bus observed downstream (any corridor junction not yet served)
                            if _obs & (_cc_ids - _served - {self.id}):
                                _bus_seen_in_corridor = True
                    # Check 3: Kalman predictor still has a live track
                    if not _bus_seen_in_corridor:
                        try:
                            _kf = self._corridor_coord._kalman_filters.get(_wave_vid)
                            if _kf is not None and (time - float(getattr(_kf, 'last_update_t', 0) or 0)) < 120.0:
                                _bus_seen_in_corridor = True
                        except Exception:
                            pass

                if not _bus_seen_in_corridor:
                    self._corridor_coord._wave_active     = False
                    self._corridor_coord._wave_veh_id     = -1
                    self._corridor_coord._wave_origin     = -1
                    self._corridor_coord._wave_served_ids = set()
                    self._corridor_coord._pre_requests.clear()
                    log_to_file(
                        f"[HARMONY WAVE CANCEL] inter={self.id} t={time:.1f} "
                        f"bus={_wave_vid} not found in any corridor zone or Kalman track "
                        f"— wave cancelled",
                        force=True)
                else:
                    if LOG_HARMONY:
                        _vprint(
                            f"[HARMONY WAVE KEEP] inter={self.id} t={time:.1f} "
                            f"bus={_wave_vid} still in corridor — wave maintained")
        return False

    def print_config_summary(self):
        """Comprehensive one-time logfile for debugging TSP logic"""
        log_to_file("=" * 80)
        log_to_file(f"[CONFIG SUMMARY] Intersection {self.id}")
        log_to_file(f"  BusPhase: {self.BusPhase} | Duration: {self.BusPhaseDuration}s")
        log_to_file(f"  PhaseIndex: {self.PhaseIndex}")
        log_to_file(f"  BusDet (NB-only): {self.BusDet}  ← must match DetDistance[0]")
        log_to_file(f"  BusCallDetectors: {self.urtsp_call_det_ids}")
        log_to_file(f"  UpDetList length: {len(self.UpDetList)} groups")
        for g, dets in enumerate(self.UpDetList):
            dd = self.DetDistance[g] if g < len(self.DetDistance) else "N/A"
            log_to_file(f"    Group {g}: {dets} | DetDistance: {dd}")
        log_to_file(f"  MainSections: {self.config.get('MainSections', [])}")
        log_to_file(f"  SideSections: {self.config.get('SideSections', [])}")
        log_to_file(f"  NumberOfLanes: {self.NumberOfLanes}")
        log_to_file(f"  Control mode: {CONTROL_MODE}")
        log_to_file("=" * 80)

    def GE_Objective_Function(self, GE, time):
        self._reset_harmony_work_arrays()
        _n_det_slots = max(len(self.BusDet), 1)
        # ── Phase 0 (Bus phase) ───────────────────────────────────────────────
        for i in range(_n_det_slots):
            self.HSMaxQueueLengthTime[0][i] = self.MaxQueueLengthTime[0][i]
            self.HSGreenStartTimeList[0][i] = self.GreenStartTimeList[0][i]
            self.HSMaxQueueLength[0][i]     = self.MaxQueueLength[0][i]
            self.HSRedDurationList[0][i]    = self.RedDurationList[0][i]
            self.HSQueueDissTime[0][i]      = self.QueueDissTime[0][i]
            self.HSMinQueueLength[0][i]     = self.MinQueueLength[0][i]
            self.HSMaxQueueLength[0][i]     = max(self.HSMaxQueueLength[0][i], 0.0)
            self.HSMinQueueLength[0][i]     = max(self.HSMinQueueLength[0][i], 0.0)
            _base_green_0 = float(self.BusPhaseDuration)
            self.TotalVeh[0][i] = (
                self.UpFlowList[0][i] *
                (self.HSRedDurationList[0][i] + _base_green_0 + GE) / 3600)
            if self.BusJoinQueueTime[0][i] <= self.HSMaxQueueLengthTime[0][i]:
                _w1 = abs(self.ShockwaveSpeed1List[0][i])
                _w2 = abs(self.ShockwaveSpeed2List[0][i])
                _bs = abs(self.BusSpeed[0][i])
                _denom_a = (_w1 + _bs) * _w2   # denominator of the queue-join term
                _denom_b = _w1 + _w2            # denominator of the travel-time term
                if _denom_a < 1e-6 or _denom_b < 1e-6:
                    self.BusDelay[0][i] = 0.0
                else:
                    self.BusDelay[0][i] = (
                        self.HSGreenStartTimeList[0][i]
                        + (_w1 * self.DetDistance[0][i]) / _denom_a
                        - (time + self.DetDistance[0][i] / _denom_b)
                    )
            else:
                self.BusDelay[0][i] = 0
            if self.HSQueueDissTime[0][i] < self.NextRedStartTime[0][i] + GE:
                self.OtherDelay[0][i] = max(0.0, (
                    (self.HSMaxQueueLength[0][i] * self.HSRedDurationList[0][i] / 2)
                    * (self.JamDensity - self.UpDenList[0][i]) / 1000
                    + ((self.HSQueueDissTime[0][i] - self.HSGreenStartTimeList[0][i])
                       * self.HSMaxQueueLength[0][i] / 2)
                    * (self.SaturationDensity - self.UpDenList[0][i]) / 1000))
            else:
                w3_ge = abs(self.ShockwaveSpeed3List[0][i])
                w4_ge = abs(self.ShockwaveSpeed4List[0][i])
                if w3_ge < 1e-6 or w4_ge < 1e-6:
                    self.OtherDelay[0][i] = 0.0
                else:
                    self.HSMinQueueLength[0][i] = max(0.0, (
                        (self.HSMaxQueueLength[0][i] / w3_ge
                         + self.HSMaxQueueLengthTime[0][i]
                         - self.NextRedStartTime[0][i] - GE) /
                        (1.0 / w3_ge + 1.0 / w4_ge)))
                    self.OtherDelay[0][i] = max(0.0, (
                        (self.HSMaxQueueLength[0][i] * self.HSRedDurationList[0][i] / 2)
                        * (self.JamDensity - self.UpDenList[0][i]) / 1000
                        + ((self.HSQueueDissTime[0][i] - self.HSGreenStartTimeList[0][i])
                           * self.HSMaxQueueLength[0][i]
                           - (self.HSQueueDissTime[0][i] - self.RedStartTimeList[0][i] - GE)
                           * self.HSMinQueueLength[0][i]) / 2
                        * (self.SaturationDensity - self.UpDenList[0][i]) / 1000))

        # ── Other phases (1..N) — project impact of extended green on their queues
        for i in range(1, len(self.UpDetList)):
            for j in range(len(self.UpDetList[i])):
                # Shift green start forward by actual cycle time + GE
                _cycle_s = float(self.config.get('CycleTime', 135))
                self.HSGreenStartTimeList[i][j] = self.GreenStartTimeList[i][j] + _cycle_s + GE
                self.HSRedDurationList[i][j]    = (
                    self.HSGreenStartTimeList[i][j] - self.RedStartTimeList[i][j])
                self.HSMaxQueueLengthTime[i][j] = self.MaxQueueLengthTime[i][j]
                self.HSQueueDissTime[i][j]      = self.QueueDissTime[i][j]
                self.HSMaxQueueLength[i][j]     = self.MaxQueueLength[i][j]
                self.HSMinQueueLength[i][j]     = self.MinQueueLength[i][j]

                # Use UpFlowList (section-scan fallback already applied)
                self.HSUpFlowList[i][j]  = self.UpFlowList[i][j]
                self.HSUpDenList[i][j]   = (
                    self.HSUpFlowList[i][j] * self.SaturationDensity / self.SaturationFlow
                    if self.SaturationFlow > 0 else 0.0)
                self.HSUpDenList[i][j] = min(
                    max(self.HSUpDenList[i][j], 0.0), self.JamDensity)
                self.HSShockwaveSpeed1List[i][j] = ShockwaveSpeed1(
                    self.HSUpFlowList[i][j], self.JamDensity, self.HSUpDenList[i][j])
                self.HSShockwaveSpeed3List[i][j] = ShockwaveSpeed3(
                    self.SaturationFlow, self.HSUpFlowList[i][j],
                    self.SaturationDensity, self.HSUpDenList[i][j])

                w1 = self.HSShockwaveSpeed1List[i][j]
                w2 = self.ShockwaveSpeed2List[i][j]
                w3 = self.HSShockwaveSpeed3List[i][j]
                w4 = self.ShockwaveSpeed4List[i][j]
                rd = self.HSRedDurationList[i][j]
                denom = abs(w2) - abs(w1)
                # Estimate other-phase base green = (cycle - bus_phase) / n_other_phases
                _n_other = max(len(self.UpDetList) - 1, 1)
                _base_green_i = max(
                    (float(self.config.get('CycleTime', 135)) - float(self.BusPhaseDuration)) / _n_other,
                    10.0)
                if denom <= 1e-6 or abs(w3) < 1e-6:
                    self.TotalVeh[i][j] = self.UpFlowList[i][j] * (rd + GE + _base_green_i) / 3600
                    continue

                self.HSMaxQueueLength[i][j]     = abs(w2) * abs(w1) * rd / denom
                self.HSMaxQueueLengthTime[i][j] = (
                    abs(w2) * rd / denom)
                self.HSQueueDissTime[i][j]      = (
                    abs(w1) * abs(w2) * rd /
                    (abs(w3) * (abs(w2) - abs(w1))))
                self.TotalVeh[i][j] = self.UpFlowList[i][j] * (rd + GE + _base_green_i) / 3600

                nrs = self.NextRedStartTime[i][j]
                if self.HSQueueDissTime[i][j] < nrs + GE:
                    self.OtherDelay[i][j] = max(0.0, (
                        abs(w1) * abs(w2) * rd / (abs(w2) - abs(w1)) / 2
                        * (self.JamDensity - self.HSUpDenList[i][j]) / 1000
                        + (self.HSQueueDissTime[i][j] - self.HSGreenStartTimeList[i][j])
                        * self.HSMaxQueueLength[i][j] / 2
                        * (self.SaturationDensity - self.HSUpDenList[i][j]) / 1000))
                else:
                    if abs(w3) > 1e-6 and abs(w4) > 1e-6:
                        self.HSMinQueueLength[i][j] = (
                            (self.HSMaxQueueLength[i][j] / abs(w3)
                             + self.HSMaxQueueLengthTime[i][j] - (nrs + GE))
                            / (1.0 / abs(w3) + 1.0 / abs(w4)))
                    self.HSMinQueueLength[i][j] = max(self.HSMinQueueLength[i][j], 0.0)
                    self.OtherDelay[i][j] = max(0.0, (
                        abs(w1) * abs(w2) * rd / (abs(w2) - abs(w1)) / 2
                        * (self.JamDensity - self.HSUpDenList[i][j]) / 1000
                        + ((self.HSQueueDissTime[i][j] - self.HSGreenStartTimeList[i][j])
                           * self.HSMaxQueueLength[i][j]
                           - (self.HSQueueDissTime[i][j] - nrs - GE)
                           * self.HSMinQueueLength[i][j]) / 2
                        * (self.SaturationDensity - self.HSUpDenList[i][j]) / 1000))

        # ── Side-street delay penalty ─────────────────────────────────────────
        # GE holds each side section at red for an extra GE seconds.
        # Triangle model: growth phase (w1 speed) + discharge phase (w3 speed).
        side_other_delay, side_total_veh = self._compute_side_delay_penalty(GE, _suppress_log=True)

        bus_delay_total   = self._safe_array_sum(self.BusDelay)
        base_other_delay  = self._safe_array_sum(self.OtherDelay)
        other_delay_total = base_other_delay + safe_float(side_other_delay)
        total_veh         = self._safe_array_sum(self.TotalVeh) + safe_float(side_total_veh)

        other_occ = self._estimated_other_vehicle_occupancy()
        _spillback_pax_s = self._compute_spillback_penalty(GE)

        # Apply REWARD_ALPHA/BETA/GAMMA weights so different batch experiments
        # actually produce different decisions.  Default 1.0/1.0/1.0 keeps the
        # unweighted behaviour; higher ALPHA prioritises the bus; higher BETA/GAMMA
        # protects other traffic more.
        total_pax_delay = (
            REWARD_ALPHA * bus_delay_total * self.BusOcc
            + REWARD_BETA  * base_other_delay  * other_occ
            + REWARD_GAMMA * safe_float(side_other_delay) * other_occ
            + _spillback_pax_s
        )

        # Global objective note: this function minimises total pax delay.
        # Protection against "gaming" (reducing delay by blocking traffic) comes from:
        #   1. REWARD_BETA × other_delay: penalises car/truck delay caused by GE
        #   2. REWARD_GAMMA × side_delay: penalises cross-street queuing
        #   3. _spillback_pax_s: penalises downstream saturation caused by phase debt
        # Together these ensure a GE that blocks traffic costs more than it saves.
        bus_delay_total, other_delay_total, total_veh, total_pax_delay = (
            self._finalize_objective_stats(
                bus_delay_total, other_delay_total, total_veh, total_pax_delay
            )
        )
        self.stats.store_objective_stats(
            bus_delay=bus_delay_total,
            other_delay=other_delay_total,
            avg_pass_delay=total_pax_delay)
        return total_pax_delay

    def BP_Objective_Function(self, GreenTime, time):
        """
        Bus-phase rotation (phase insertion) objective function.
        Mirrors BP_Objective_Function from Bus_priority_single_intersection_3.py,
        adapted for multi-intersection class with full debug logging.
        """
        self._reset_harmony_work_arrays()
        _n_det_slots = max(len(self.BusDet), 1)
        # ── Phase 0: Bus phase ─────────────────────────────────────────────────
        for i in range(_n_det_slots):
            # log_to_file(f"[HS BP_OBJ] inter={self.id} bus_det_idx={i} "
            #             f"UpDetCount={self.UpDetCountList[0][i]:.0f}")
            # Projected green start: now + 5s (insertion delay)
            self.HSGreenStartTimeList[0][i] = time + 5
            self.HSRedStartTimeList[0][i]   = self.RedStartTimeList[0][i]
            self.HSRedDurationList[0][i]    = (
                self.HSGreenStartTimeList[0][i] - self.HSRedStartTimeList[0][i])
            red_dur = max(self.HSRedDurationList[0][i], 1.0)

            # Use UpFlowList which already incorporates section-scan fallback
            # when physical detector counts are unavailable (returns 0).
            self.HSUpFlowList[0][i]          = self.UpFlowList[0][i]
            self.HSUpDenList[0][i]           = min(max(
                self.HSUpFlowList[0][i] * self.SaturationDensity / self.SaturationFlow
                if self.SaturationFlow > 0 else 0.0, 0.0), self.JamDensity)
            self.HSShockwaveSpeed1List[0][i] = ShockwaveSpeed1(
                self.HSUpFlowList[0][i], self.JamDensity, self.HSUpDenList[0][i])
            self.HSShockwaveSpeed3List[0][i] = ShockwaveSpeed3(
                self.SaturationFlow, self.HSUpFlowList[0][i],
                self.SaturationDensity, self.HSUpDenList[0][i])

            # log_to_file(f"[HS BP_OBJ] inter={self.id} i={i} "
            #             f"HSUpFlow={self.HSUpFlowList[0][i]:.1f} "
            #             f"HSUpDen={self.HSUpDenList[0][i]:.4f} "
            #             f"w1={self.HSShockwaveSpeed1List[0][i]:.4f} "
            #             f"w2={self.ShockwaveSpeed2List[0][i]:.4f} "
            #             f"w3={self.HSShockwaveSpeed3List[0][i]:.4f}")

            self.TotalVeh[0][i] = self.HSUpFlowList[0][i] * (red_dur + GreenTime) / 3600

            w1 = self.HSShockwaveSpeed1List[0][i]
            w2 = self.ShockwaveSpeed2List[0][i]
            denom = abs(w2) - abs(w1)
            if denom > 1e-6:
                self.HSMaxQueueLength[0][i] = (
                    abs(w2) * abs(w1) * (time + 5 - self.HSRedStartTimeList[0][i])
                    / denom)
                self.HSMaxQueueLengthTime[0][i] = (
                    self.HSRedStartTimeList[0][i]
                    + abs(w2) * (time + 5 - self.HSRedStartTimeList[0][i]) / denom)
                self.HSMaxQueueLength[0][i] = max(self.HSMaxQueueLength[0][i], 0.0)

        for i in range(_n_det_slots):
            w1 = self.HSShockwaveSpeed1List[0][i]
            w2 = self.ShockwaveSpeed2List[0][i]
            w3 = self.HSShockwaveSpeed3List[0][i]
            w4 = self.ShockwaveSpeed4List[0][i]
            denom = abs(w2) - abs(w1)

            if denom <= 1e-6 or abs(w3) < 1e-6:
                self.BusDelay[0][i]  = 0.0
                self.OtherDelay[0][i] = 0.0
                continue

            # log_to_file(f"[HS BP_OBJ] inter={self.id} i={i} "
            #             f"HSMaxQ={self.HSMaxQueueLength[0][i]:.1f} "
            #             f"HSMaxQTime={self.HSMaxQueueLengthTime[0][i]:.1f}")

            bus_speed = self.BusSpeed[0][i]
            if bus_speed > 0:
                # Time bus joins queue front
                self.BusJoinQueueTime[0][i] = (
                    (self.DetDistance[0][i]
                     - abs(w1) * (time - self.HSRedStartTimeList[0][i]))
                    / (bus_speed + abs(w1)) + time)

                # log_to_file(f"[HS BP_OBJ] inter={self.id} i={i} "
                #             f"BusJoinQTime={self.BusJoinQueueTime[0][i]:.1f} "
                #             f"HSMaxQTime={self.HSMaxQueueLengthTime[0][i]:.1f}")

                if self.BusJoinQueueTime[0][i] > self.HSMaxQueueLengthTime[0][i]:
                    # Bus arrives after max queue → no stop
                    self.BusStoplineTime[0][i] = time + self.DetDistance[0][i] / bus_speed
                    self.BusPhaseMinDuration[0][i] = (
                        self.BusStoplineTime[0][i] - self.HSGreenStartTimeList[0][i])
                    self.BusDelay[0][i] = 0.0

                    # log_to_file(f"[HS BP_OBJ] inter={self.id} i={i} "
                    #             f"case=no_stop_queue_clear BusStopline={self.BusStoplineTime[0][i]:.1f} "
                    #             f"MinDur={self.BusPhaseMinDuration[0][i]:.1f}")

                    for k in range(len(self.BusDet)):
                        w3k = abs(self.HSShockwaveSpeed3List[0][k])
                        w4k = abs(self.ShockwaveSpeed4List[0][k])
                        if w3k < 1e-6:
                            self.OtherDelay[0][k] = 0.0
                            continue
                        self.HSQueueDissTime[0][k] = (
                            self.HSMaxQueueLengthTime[0][k]
                            + self.HSMaxQueueLength[0][k] / w3k)
                        green_end = self.HSGreenStartTimeList[0][k] + GreenTime
                        if self.HSQueueDissTime[0][k] < green_end:
                            self.OtherDelay[0][k] = max(0.0, (
                                self.HSMaxQueueLength[0][k] * self.HSRedDurationList[0][k]
                                / 2 * (self.JamDensity - self.HSUpDenList[0][k]) / 1000
                                + (self.HSQueueDissTime[0][k]
                                   - self.HSGreenStartTimeList[0][k])
                                * self.HSMaxQueueLength[0][k] / 2
                                * (self.SaturationDensity - self.HSUpDenList[0][k]) / 1000))
                        else:
                            hsmin = 0.0
                            if w3k > 1e-6 and w4k > 1e-6:
                                nrs_k = self.HSNextRedStartTime[0][k]
                                hsmin = (
                                    (self.HSMaxQueueLength[0][k] / w3k
                                     + self.HSMaxQueueLengthTime[0][k] - (nrs_k + GreenTime))
                                    / (1.0 / w3k + 1.0 / w4k))
                            self.HSMinQueueLength[0][k] = max(hsmin, 0.0)
                            self.OtherDelay[0][k] = max(0.0, (
                                self.HSMaxQueueLength[0][k] * self.HSRedDurationList[0][k]
                                / 2 * (self.JamDensity - self.HSUpDenList[0][k]) / 1000
                                + ((self.HSQueueDissTime[0][k]
                                    - self.HSGreenStartTimeList[0][k])
                                   * self.HSMaxQueueLength[0][k]
                                   - (self.HSQueueDissTime[0][k] - green_end)
                                   * self.HSMinQueueLength[0][k]) / 2
                                * (self.SaturationDensity - self.HSUpDenList[0][k]) / 1000))

                else:
                    # Bus joins queue → compute discharge time
                    bus_pos = (self.DetDistance[0][i]
                               - bus_speed
                               * ((self.DetDistance[0][i]
                                   - abs(w1) * (time - self.RedStartTimeList[0][i]))
                                  / (bus_speed + abs(w1))))
                    bus_discharge = (
                        self.HSGreenStartTimeList[0][i] + bus_pos / abs(w2))
                    self.BusStoplineTime[0][i] = (
                        bus_discharge + bus_pos / abs(w3))
                    if self.BusStoplineTime[0][i] > self.HSGreenStartTimeList[0][i]:
                        self.BusPhaseMinDuration[0][i] = (
                            self.BusStoplineTime[0][i] - self.HSGreenStartTimeList[0][i])
                    self.BusDelay[0][i] = max(0.0,
                        self.HSGreenStartTimeList[0][i]
                        + (self.DetDistance[0][i]
                           - bus_speed * (self.DetDistance[0][i]
                                          - (self.HSGreenStartTimeList[0][i]
                                             - self.HSRedStartTimeList[0][i])
                                          * abs(w1))
                           / (bus_speed + abs(w1))) / abs(w2)
                        - (time + (self.DetDistance[0][i]
                                   - (self.HSGreenStartTimeList[0][i]
                                      - self.HSRedStartTimeList[0][i])
                                   * abs(w1))
                           / (bus_speed + abs(w1))))

                    # log_to_file(f"[HS BP_OBJ] inter={self.id} i={i} "
                    #             f"case=joins_queue bus_pos={bus_pos:.1f} "
                    #             f"BusDelay={self.BusDelay[0][i]:.2f}")

                    for k in range(len(self.BusDet)):
                        w1k = abs(self.HSShockwaveSpeed1List[0][k])
                        w2k = abs(self.ShockwaveSpeed2List[0][k])
                        w3k = abs(self.HSShockwaveSpeed3List[0][k])
                        if w3k < 1e-6 or (w2k - w1k) <= 1e-6:
                            self.HSQueueDissTime[0][k] = 0.0
                            self.OtherDelay[0][k] = 0.0
                            continue
                        self.HSQueueDissTime[0][k] = (
                            self.HSRedStartTimeList[0][k]
                            + w2k * self.HSRedDurationList[0][k] / (w2k - w1k)
                            + w2k * w1k * self.HSRedDurationList[0][k]
                            / ((w2k - w1k) * w3k))
                        green_end = self.HSGreenStartTimeList[0][k] + GreenTime
                        if self.HSQueueDissTime[0][k] < green_end:
                            self.OtherDelay[0][k] = max(0.0, (
                                (self.HSMaxQueueLength[0][k]
                                 * self.HSRedDurationList[0][k] / 2)
                                * (self.JamDensity - self.HSUpDenList[0][k]) / 1000
                                + ((self.HSQueueDissTime[0][k]
                                    - self.HSGreenStartTimeList[0][k])
                                   * self.HSMaxQueueLength[0][k] / 2)
                                * (self.SaturationDensity - self.HSUpDenList[0][k]) / 1000))
                        else:
                            self.OtherDelay[0][k] = max(0.0, (
                                (self.HSMaxQueueLength[0][k]
                                 * self.HSRedDurationList[0][k] / 2)
                                * (self.JamDensity - self.HSUpDenList[0][k]) / 1000
                                + ((self.HSQueueDissTime[0][k]
                                    - self.HSGreenStartTimeList[0][k])
                                   * self.HSMaxQueueLength[0][k] / 2)
                                * (self.SaturationDensity - self.HSUpDenList[0][k]) / 1000
                                - (self.HSQueueDissTime[0][k] - green_end) / 2
                                * (self.SaturationDensity - self.HSUpDenList[0][k]) / 1000))

        # ── Interrupted phase (OrderToTerminatePhase = previous_phase index) ──
        otp_phase = self.previous_phase  # phase being interrupted
        if otp_phase in self.PhaseIndex:
            otp_idx = self.PhaseIndex[otp_phase]
            # Detector groups can be empty after section-scan cleanup. Use the
            # available per-phase array width instead of assuming UpDetList has
            # a matching entry for every phase.
            _phase_slots = len(self.HSNextRedStartTime) if self.HSNextRedStartTime is not None else 0
            if _phase_slots <= 0:
                return -1000000000
            if otp_idx >= _phase_slots:
                otp_idx = 0
            _det_count = 0
            if otp_idx < len(self.UpDetList):
                _det_count = len(self.UpDetList[otp_idx])
            if _det_count <= 0:
                try:
                    _det_count = len(self.HSNextRedStartTime[otp_idx])
                except Exception:
                    _det_count = 0
            for j in range(_det_count):
                self.HSNextRedStartTime[otp_idx][j] = (
                    self.NextRedStartTime[otp_idx][j] + time + 5)
                self.HSGreenStartTimeList[otp_idx][j] = self.GreenStartTimeList[0][j]
                self.HSGreenDurationList[otp_idx][j] = (
                    self.HSNextRedStartTime[otp_idx][j]
                    - self.HSGreenStartTimeList[otp_idx][j])
                self.HSUpFlowList[otp_idx][j]          = self.UpFlowList[otp_idx][j]
                self.HSShockwaveSpeed1List[otp_idx][j] = self.ShockwaveSpeed1List[otp_idx][j]
                self.HSShockwaveSpeed3List[otp_idx][j] = self.ShockwaveSpeed3List[otp_idx][j]
                self.HSRedDurationList[otp_idx][j]     = self.RedDurationList[otp_idx][j]
                self.TotalVeh[otp_idx][j] = (
                    self.HSUpFlowList[otp_idx][j] * GreenTime / 3600)

                w1o  = self.HSShockwaveSpeed1List[otp_idx][j]
                w2o  = self.ShockwaveSpeed2List[otp_idx][j]
                w3o  = self.HSShockwaveSpeed3List[otp_idx][j]
                w4o  = self.ShockwaveSpeed4List[otp_idx][j]
                gd   = self.HSGreenDurationList[otp_idx][j]
                denom_o = abs(w2o) - abs(w1o)
                if abs(denom_o) < 1e-6 or abs(w3o) < 1e-6:
                    continue

                residual_cleared = (
                    self.MaxQueueLength[otp_idx][j]
                    - abs(w3o) * gd < 0)
                if residual_cleared:
                    self.HSMaxQueueLength[otp_idx][j] = (
                        abs(w2o) * abs(w1o) * GreenTime / denom_o)
                else:
                    self.HSMaxQueueLength[otp_idx][j] = self.MaxQueueLength[otp_idx][j]

                nrs_o = self.HSNextRedStartTime[otp_idx][j]
                q_diss_o = (
                    self.HSMaxQueueLengthTime[otp_idx][j]
                    + self.HSMaxQueueLength[otp_idx][j] / abs(w3o))
                if q_diss_o < nrs_o:
                    self.OtherDelay[otp_idx][j] = max(0.0, (
                        self.HSMaxQueueLength[otp_idx][j]
                        * self.HSRedDurationList[otp_idx][j] / 2
                        * (self.JamDensity - self.UpDenList[otp_idx][j]) / 1000
                        + (q_diss_o - self.HSGreenStartTimeList[otp_idx][j])
                        * self.HSMaxQueueLength[otp_idx][j] / 2
                        * (self.SaturationDensity - self.UpDenList[otp_idx][j]) / 1000))
                else:
                    if abs(w3o) > 1e-6 and abs(w4o) > 1e-6:
                        min_q = (
                            (self.HSMaxQueueLength[otp_idx][j] / abs(w3o)
                             + self.HSMaxQueueLengthTime[otp_idx][j] - nrs_o)
                            / (1.0 / abs(w3o) + 1.0 / abs(w4o)))
                        self.HSMinQueueLength[otp_idx][j] = max(min_q, 0.0)
                    self.OtherDelay[otp_idx][j] = max(0.0, (
                        self.HSMaxQueueLength[otp_idx][j]
                        * self.HSRedDurationList[otp_idx][j] / 2
                        * (self.JamDensity - self.UpDenList[otp_idx][j]) / 1000
                        + ((q_diss_o - self.HSGreenStartTimeList[otp_idx][j])
                           * self.HSMaxQueueLength[otp_idx][j]
                           - (q_diss_o - nrs_o)
                           * self.HSMinQueueLength[otp_idx][j]) / 2
                        * (self.SaturationDensity - self.UpDenList[otp_idx][j]) / 1000))

        # ── All other phases (not bus=0 and not interrupted) ──────────────────
        otp_idx_val = self.PhaseIndex.get(otp_phase, -1) if otp_phase in self.PhaseIndex else -1
        for i in range(len(self.UpDetList)):
            if i == 0 or i == otp_idx_val:
                continue
            for j in range(len(self.UpDetList[i])):
                self.HSRedStartTimeList[i][j]  = self.RedStartTimeList[i][j]
                self.HSRedDurationList[i][j]   = self.RedDurationList[i][j] + GreenTime + 5
                elapsed = max(time - self.HSRedStartTimeList[i][j], 1.0)
                self.HSUpFlowList[i][j]        = (
                    self.UpDetCountList[i][j] / elapsed * 3600)
                self.HSUpDenList[i][j] = min(
                    max(self.HSUpFlowList[i][j] * self.SaturationDensity / max(self.SaturationFlow, 1.0), 0.0),
                    self.JamDensity)
                self.TotalVeh[i][j]            = (
                    self.HSUpFlowList[i][j]
                    * (self.HSRedDurationList[i][j] + max(int(self.config.get('GE_upper_bound', 20)), 10)) / 3600)

                w1i = self.ShockwaveSpeed1List[i][j]
                w2i = self.ShockwaveSpeed2List[i][j]
                w3i = self.ShockwaveSpeed3List[i][j]
                w4i = self.ShockwaveSpeed4List[i][j]
                rd_i = self.HSRedDurationList[i][j]
                den_i = abs(w2i) - abs(w1i)
                if den_i <= 1e-6 or abs(w3i) < 1e-6:
                    continue

                self.HSMaxQueueLength[i][j] = (
                    abs(w1i) * abs(w2i) * (rd_i) / den_i)
                self.HSMaxQueueLength[i][j] = max(self.HSMaxQueueLength[i][j], 0.0)
                self.HSMaxQueueLengthTime[i][j] = (
                    self.HSRedStartTimeList[i][j]
                    + abs(w2i) * (rd_i + GreenTime + 5) / den_i)
                self.HSGreenStartTimeList[i][j] = (
                    self.HSRedStartTimeList[i][j] + self.HSRedDurationList[i][j])
                self.HSNextRedStartTime[i][j]   = (
                    self.HSGreenStartTimeList[i][j] + 40)
                q_diss_i = (
                    self.HSMaxQueueLengthTime[i][j]
                    + self.HSMaxQueueLength[i][j] / abs(w3i))
                nrs_i = self.HSNextRedStartTime[i][j]
                if q_diss_i > nrs_i:
                    min_qi = 0.0
                    if abs(w3i) > 1e-6 and abs(w4i) > 1e-6:
                        min_qi = (
                            (self.HSMaxQueueLength[i][j] / abs(w3i)
                             + self.HSMaxQueueLengthTime[i][j] - (nrs_i + GreenTime + 5))
                            / (1.0 / abs(w3i) + 1.0 / abs(w4i)))
                    self.HSMinQueueLength[i][j] = max(min_qi, 0.0)
                    self.OtherDelay[i][j] = max(0.0, (
                        self.HSMaxQueueLength[i][j] * rd_i / 2
                        * (self.JamDensity - self.UpDenList[i][j]) / 1000
                        + ((q_diss_i - self.HSGreenStartTimeList[i][j])
                           * self.HSMaxQueueLength[i][j]
                           - (q_diss_i - nrs_i) * self.HSMinQueueLength[i][j]) / 2
                        * (self.SaturationDensity - self.UpDenList[i][j]) / 1000))
                else:
                    self.OtherDelay[i][j] = max(0.0, (
                        self.HSMaxQueueLength[i][j] * rd_i / 2
                        * (self.JamDensity - self.UpDenList[i][j]) / 1000
                        + (q_diss_i - self.HSGreenStartTimeList[i][j])
                        * self.HSMaxQueueLength[i][j] / 2
                        * (self.SaturationDensity - self.UpDenList[i][j]) / 1000))

        # ── Side-street delay penalty ─────────────────────────────────────────
        # Phase insertion forces side sections to wait GreenTime + 5s extra.
        extra_red = GreenTime + 5.0
        side_other_delay_bp, side_total_veh_bp = self._compute_side_delay_penalty(extra_red, _suppress_log=True)

        bus_delay_total   = self._safe_array_sum(self.BusDelay)
        base_other_delay  = self._safe_array_sum(self.OtherDelay)
        other_delay_total = base_other_delay + safe_float(side_other_delay_bp)
        total_veh         = self._safe_array_sum(self.TotalVeh) + safe_float(side_total_veh_bp)

        other_occ = self._estimated_other_vehicle_occupancy()
        _spillback_pax_s_bp = self._compute_spillback_penalty(GreenTime)

        # Same REWARD weight application as GE_Objective_Function so batch
        # experiments with different ALPHA/BETA/GAMMA actually diverge.
        total_pax_delay = (
            REWARD_ALPHA * bus_delay_total * self.BusOcc
            + REWARD_BETA  * base_other_delay  * other_occ
            + REWARD_GAMMA * safe_float(side_other_delay_bp) * other_occ
            + _spillback_pax_s_bp
        )
        bus_delay_total, other_delay_total, total_veh, total_pax_delay = (
            self._finalize_objective_stats(
                bus_delay_total, other_delay_total, total_veh, total_pax_delay
            )
        )
        self.stats.store_objective_stats(
            bus_delay=bus_delay_total,
            other_delay=other_delay_total,
            avg_pass_delay=total_pax_delay)
        return total_pax_delay


# =============================================================================
# AIMSUN CALLBACKS
# =============================================================================

def AAPILoad():
    _vprint("=" * 60)
    if LOG_INIT: AKIPrintString(f"[TSP] Script loaded | mode={CONTROL_MODE}")
    if LOG_INIT: AKIPrintString(f"[TSP] Log file → {LOG_FILE}")
    if LOG_INIT: AKIPrintString(f"[TSP] Intersections configured: {list(INTERSECTIONS_CONFIG.keys())}")
    _vprint("=" * 60)
    log_to_file(f"[LOAD] AAPILoad complete | mode={CONTROL_MODE} | "
                f"n_intersections={len(INTERSECTIONS_CONFIG)}")
    return 0


# =============================================================================
# LEAN MODE: enforce disabled flags at init time so that run_config.py
# cannot accidentally re-enable legacy strategies in this fork.
# =============================================================================
if LEAN_MODE:
    # Strategies that are DISABLED in the lean fork:
    MDN_DELAY_MODE       = False   # Zhu 2026 MDN — not needed, use D/D/1
    META_TSP_MODE        = False   # META_TSP — not in lean scope
    REWARD_INV_DELAY_MODE = False  # inverse-delay reward variant
    QUEUE_MODEL_MODE     = False   # redundant with D/D/1 in bargaining path
    BXT_MODE             = False   # CTM Q-learning variant (use BARGAIN_SPM instead)
    GLOBAL_REWARD_MODE   = False   # aggregated reward — not in lean scope
    GROUP_BASED_BUS_PRIORITY = False  # legacy grouping layer
    REWARD_ENABLE_PREARM = False   # pre-arming unused in lean
    # CONTROL_MODE must be HARMONY or DRL_DENSITY for BARGAIN_SPM to be checked;
    # keep DRL_DENSITY as it is the path that reaches the BARGAIN/HS detection loop.
    # DYNAOPAC_HARMONY, MPC_TSP, URTSP are branch checks on CONTROL_MODE string,
    # which is never set to those values in the lean batch experiments.
# =============================================================================


def AAPIInit():
    global controllers, corridor_coordinators, _dynaropac_optimizer, _dynaropac_last_eval_t
    global _DYNAROPAC_DECISION_CSV, _dynaropac_decision_header_written

    # ── Refresh output file paths for this replication ────────────────────────
    # The module is loaded once per Aimsun session and reused across all batch
    # replications.  run_config.py is rewritten by the batch runner before each
    # run, so we re-read it here to get the correct experiment name and stamp
    # fresh output filenames — otherwise all runs append to the same CSV and
    # the dashboard cannot match bus tracking / detection data by experiment.
    global _CURRENT_EXPERIMENT, _BUS_TRACKING_CSV, _PRESENCE_SNAPSHOT_CSV
    global _DET_CSV, _WAVE_EVENTS_CSV
    global _DET_GEOJSON, _JUNC_CSV, _RUN_SUMMARY_TXT
    global _OFFSET_CSV, _offset_header_written, _QUEUE_SNAPSHOT_CSV, _NO_INS_SUMMARY_CSV
    global _OBJECTIVE_TRACE_CSV, _objective_trace_header_written
    try:
        _rc_path2 = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'run_config.py')
        _rc_ns2: dict = {}
        with open(_rc_path2, 'r') as _rc_f2:
            exec(_rc_f2.read(), _rc_ns2)
        _CURRENT_EXPERIMENT = str(_rc_ns2.get('CURRENT_EXPERIMENT',
                                               _rc_ns2.get('CURRENT_STRATEGY', 'UNKNOWN'))).strip()
        # ── Refresh reward-mode globals so the correct strategy is used even  ──
        # though this module is cached (loaded once, reused across replications).
        # run_config.py is rewritten by batch_runner before every run, so reading
        # it here gives the correct per-run values for the reward flags.
        # CRITICAL: GLOBAL_REWARD_MODE must also be refreshed here — the module-
        # level 'from run_config import GLOBAL_REWARD_MODE' only runs once on
        # first import (Python caches run_config in sys.modules), so without this
        # refresh every run after the first would use the stale first-run value.
        global GLOBAL_REWARD_MODE
        global REWARD_INV_DELAY_MODE, REWARD_V2X_MODE
        global INV_DELAY_EPSILON, INV_DELAY_CAR_WEIGHT, INV_DELAY_MIN_DELAY_S
        global V2X_MAX_BUS_OCC, V2X_CROWDING_SCALE, V2X_EPSILON, V2X_MIN_DELAY_S, V2X_BALANCE_FACTOR
        global REWARD_SELFORG_MODE, SELFORG_MIN_BUS_DELAY_S, SELFORG_BALANCE_FACTOR
        global SELFORG_MAX_SE_S, SELFORG_MIN_SE_S, SELFORG_SE_FRACTION, SELFORG_PHASE_OVERLAP_S
        GLOBAL_REWARD_MODE    = bool(_rc_ns2.get('GLOBAL_REWARD_MODE',    GLOBAL_REWARD_MODE))
        REWARD_INV_DELAY_MODE = bool(_rc_ns2.get('REWARD_INV_DELAY_MODE', REWARD_INV_DELAY_MODE))
        REWARD_V2X_MODE       = bool(_rc_ns2.get('REWARD_V2X_MODE',       REWARD_V2X_MODE))
        INV_DELAY_EPSILON     = float(_rc_ns2.get('INV_DELAY_EPSILON',    INV_DELAY_EPSILON))
        INV_DELAY_CAR_WEIGHT  = float(_rc_ns2.get('INV_DELAY_CAR_WEIGHT', INV_DELAY_CAR_WEIGHT))
        INV_DELAY_MIN_DELAY_S = float(_rc_ns2.get('INV_DELAY_MIN_DELAY_S', INV_DELAY_MIN_DELAY_S))
        V2X_MAX_BUS_OCC       = float(_rc_ns2.get('V2X_MAX_BUS_OCC',      V2X_MAX_BUS_OCC))
        V2X_CROWDING_SCALE    = float(_rc_ns2.get('V2X_CROWDING_SCALE',   V2X_CROWDING_SCALE))
        V2X_EPSILON           = float(_rc_ns2.get('V2X_EPSILON',          V2X_EPSILON))
        V2X_MIN_DELAY_S       = float(_rc_ns2.get('V2X_MIN_DELAY_S',      V2X_MIN_DELAY_S))
        V2X_BALANCE_FACTOR    = float(_rc_ns2.get('V2X_BALANCE_FACTOR',   V2X_BALANCE_FACTOR))
        # Network amplification factor — must be refreshed per-run so batch experiments
        # can set NETWORK_FACTOR=5.0 for ZIG/INV_DELAY without affecting other modes.
        global NETWORK_FACTOR
        NETWORK_FACTOR        = float(_rc_ns2.get('NETWORK_FACTOR',       NETWORK_FACTOR))
        REWARD_SELFORG_MODE     = bool(_rc_ns2.get('REWARD_SELFORG_MODE',     REWARD_SELFORG_MODE))
        SELFORG_MIN_BUS_DELAY_S = float(_rc_ns2.get('SELFORG_MIN_BUS_DELAY_S', SELFORG_MIN_BUS_DELAY_S))
        SELFORG_BALANCE_FACTOR  = float(_rc_ns2.get('SELFORG_BALANCE_FACTOR',  SELFORG_BALANCE_FACTOR))
        SELFORG_MAX_SE_S        = float(_rc_ns2.get('SELFORG_MAX_SE_S',        SELFORG_MAX_SE_S))
        SELFORG_MIN_SE_S        = float(_rc_ns2.get('SELFORG_MIN_SE_S',        SELFORG_MIN_SE_S))
        SELFORG_SE_FRACTION     = float(_rc_ns2.get('SELFORG_SE_FRACTION',     SELFORG_SE_FRACTION))
        SELFORG_PHASE_OVERLAP_S = float(_rc_ns2.get('SELFORG_PHASE_OVERLAP_S', SELFORG_PHASE_OVERLAP_S))
        global DCTSP_ZIG_MODE, ZIG_PHASE_OVERLAP_S, ZIG_BALANCE_FACTOR
        DCTSP_ZIG_MODE      = bool(_rc_ns2.get('DCTSP_ZIG_MODE',       DCTSP_ZIG_MODE))
        ZIG_PHASE_OVERLAP_S = float(_rc_ns2.get('ZIG_PHASE_OVERLAP_S', ZIG_PHASE_OVERLAP_S))
        ZIG_BALANCE_FACTOR  = float(_rc_ns2.get('ZIG_BALANCE_FACTOR',  ZIG_BALANCE_FACTOR))
        global MP_ECTM_MODE, MP_ECTM_DT_S, MP_ECTM_MIN_EXT_S, MP_ECTM_MAX_EXT_S
        global MP_ECTM_CAR_OCC, MP_ECTM_BALANCE_FACTOR
        MP_ECTM_MODE           = bool(_rc_ns2.get('MP_ECTM_MODE',           MP_ECTM_MODE))
        MP_ECTM_DT_S           = float(_rc_ns2.get('MP_ECTM_DT_S',          MP_ECTM_DT_S))
        MP_ECTM_MIN_EXT_S      = float(_rc_ns2.get('MP_ECTM_MIN_EXT_S',     MP_ECTM_MIN_EXT_S))
        MP_ECTM_MAX_EXT_S      = float(_rc_ns2.get('MP_ECTM_MAX_EXT_S',     MP_ECTM_MAX_EXT_S))
        MP_ECTM_CAR_OCC        = float(_rc_ns2.get('MP_ECTM_CAR_OCC',       MP_ECTM_CAR_OCC))
        MP_ECTM_BALANCE_FACTOR = float(_rc_ns2.get('MP_ECTM_BALANCE_FACTOR',MP_ECTM_BALANCE_FACTOR))
        global BXT_MODE, BXT_DT_S, BXT_EPSILON, BXT_ALPHA, BXT_GAMMA
        global BXT_CAR_OCC, BXT_BALANCE_FACTOR
        BXT_MODE           = bool(_rc_ns2.get('BXT_MODE',           BXT_MODE))
        BXT_DT_S           = float(_rc_ns2.get('BXT_DT_S',          BXT_DT_S))
        BXT_EPSILON        = float(_rc_ns2.get('BXT_EPSILON',        BXT_EPSILON))
        BXT_ALPHA          = float(_rc_ns2.get('BXT_ALPHA',          BXT_ALPHA))
        BXT_GAMMA          = float(_rc_ns2.get('BXT_GAMMA',          BXT_GAMMA))
        BXT_CAR_OCC        = float(_rc_ns2.get('BXT_CAR_OCC',        BXT_CAR_OCC))
        BXT_BALANCE_FACTOR = float(_rc_ns2.get('BXT_BALANCE_FACTOR', BXT_BALANCE_FACTOR))
        # ── Green reallocation (split planned bus green, no net add) ─────────
        global DCTSP_GREEN_REALLOC_MODE, GREEN_REALLOC_RECOVER_FRACTION
        DCTSP_GREEN_REALLOC_MODE = bool(_rc_ns2.get('DCTSP_GREEN_REALLOC_MODE', DCTSP_GREEN_REALLOC_MODE))
        GREEN_REALLOC_RECOVER_FRACTION = float(_rc_ns2.get('GREEN_REALLOC_RECOVER_FRACTION', GREEN_REALLOC_RECOVER_FRACTION))
        # ── Congestion gate (suppress TSP when network near saturation) ──────
        global DCTSP_CONGESTION_GATE, DCTSP_CONGESTION_GATE_FRACTION
        DCTSP_CONGESTION_GATE          = bool(_rc_ns2.get('DCTSP_CONGESTION_GATE',          DCTSP_CONGESTION_GATE))
        DCTSP_CONGESTION_GATE_FRACTION = float(_rc_ns2.get('DCTSP_CONGESTION_GATE_FRACTION', DCTSP_CONGESTION_GATE_FRACTION))
        # ── Multi-cycle saturation correction (HCM 2010 overflow, per-phase) ─
        global DCTSP_MULTI_CYCLE_X_THR, DCTSP_MULTI_CYCLE_X_FLOOR
        DCTSP_MULTI_CYCLE_X_THR   = float(_rc_ns2.get('DCTSP_MULTI_CYCLE_X_THR',   DCTSP_MULTI_CYCLE_X_THR))
        DCTSP_MULTI_CYCLE_X_FLOOR = float(_rc_ns2.get('DCTSP_MULTI_CYCLE_X_FLOOR', DCTSP_MULTI_CYCLE_X_FLOOR))
        # ── Bargaining-game SPM (TRC 2025) ───────────────────────────────────
        # CRITICAL: refresh every run so cached module defaults do not leak.
        global BARGAIN_SPM_MODE
        global BG_DET_LVL_IMM_S, BG_DET_LVL_NEAR_S, BG_DET_LVL_FAR_S
        global BG_BUS_W_IMM, BG_BUS_W_NEAR, BG_BUS_W_FAR, BG_BUS_W_VFAR
        global BG_SPM_RISK_WEIGHT, BG_EQ_FAIRNESS_WEIGHT
        global BG_MIN_BUS_DELAY_S, BG_MIN_GAIN_S
        BARGAIN_SPM_MODE      = bool(_rc_ns2.get('BARGAIN_SPM_MODE',      False))
        BG_DET_LVL_IMM_S      = float(_rc_ns2.get('BG_DET_LVL_IMM_S',     BG_DET_LVL_IMM_S))
        BG_DET_LVL_NEAR_S     = float(_rc_ns2.get('BG_DET_LVL_NEAR_S',    BG_DET_LVL_NEAR_S))
        BG_DET_LVL_FAR_S      = float(_rc_ns2.get('BG_DET_LVL_FAR_S',     BG_DET_LVL_FAR_S))
        BG_BUS_W_IMM          = float(_rc_ns2.get('BG_BUS_W_IMM',         BG_BUS_W_IMM))
        BG_BUS_W_NEAR         = float(_rc_ns2.get('BG_BUS_W_NEAR',        BG_BUS_W_NEAR))
        BG_BUS_W_FAR          = float(_rc_ns2.get('BG_BUS_W_FAR',         BG_BUS_W_FAR))
        BG_BUS_W_VFAR         = float(_rc_ns2.get('BG_BUS_W_VFAR',        BG_BUS_W_VFAR))
        BG_SPM_RISK_WEIGHT    = float(_rc_ns2.get('BG_SPM_RISK_WEIGHT',   BG_SPM_RISK_WEIGHT))
        BG_EQ_FAIRNESS_WEIGHT = float(_rc_ns2.get('BG_EQ_FAIRNESS_WEIGHT',BG_EQ_FAIRNESS_WEIGHT))
        BG_MIN_BUS_DELAY_S    = float(_rc_ns2.get('BG_MIN_BUS_DELAY_S',   BG_MIN_BUS_DELAY_S))
        BG_MIN_GAIN_S         = float(_rc_ns2.get('BG_MIN_GAIN_S',        BG_MIN_GAIN_S))
        global BG_TALL_BUS_LENGTH_M, BG_TALL_BUS_OCC_MULT, BG_CASCADE_MULT, BG_MB_WEIGHT
        global BG_NO_ACTION_BONUS_S
        BG_TALL_BUS_LENGTH_M  = float(_rc_ns2.get('BG_TALL_BUS_LENGTH_M', BG_TALL_BUS_LENGTH_M))
        BG_TALL_BUS_OCC_MULT  = float(_rc_ns2.get('BG_TALL_BUS_OCC_MULT', BG_TALL_BUS_OCC_MULT))
        BG_CASCADE_MULT       = float(_rc_ns2.get('BG_CASCADE_MULT',       BG_CASCADE_MULT))
        BG_MB_WEIGHT          = float(_rc_ns2.get('BG_MB_WEIGHT',          BG_MB_WEIGHT))
        BG_NO_ACTION_BONUS_S  = float(_rc_ns2.get('BG_NO_ACTION_BONUS_S',  BG_NO_ACTION_BONUS_S))
        # ── Schedule adherence and actual-load weighting ─────────────────────
        global BG_USE_ACTUAL_LOAD, BG_USE_SCHEDULE, BG_LATENESS_REF_S, BG_LATENESS_SENSITIVITY
        BG_USE_ACTUAL_LOAD      = bool(_rc_ns2.get('BG_USE_ACTUAL_LOAD',      BG_USE_ACTUAL_LOAD))
        BG_USE_SCHEDULE         = bool(_rc_ns2.get('BG_USE_SCHEDULE',         BG_USE_SCHEDULE))
        BG_LATENESS_REF_S       = float(_rc_ns2.get('BG_LATENESS_REF_S',      BG_LATENESS_REF_S))
        BG_LATENESS_SENSITIVITY = float(_rc_ns2.get('BG_LATENESS_SENSITIVITY', BG_LATENESS_SENSITIVITY))
        # ── Global discrete-time evaluation ──────────────────────────────────
        global GLOBAL_EVAL_DT, GLOBAL_GR_MODE, GLOBAL_GR_THRESHOLD_VEH, _global_eval_last_t
        GLOBAL_EVAL_DT          = float(_rc_ns2.get('GLOBAL_EVAL_DT',          GLOBAL_EVAL_DT))
        GLOBAL_GR_MODE          = bool(_rc_ns2.get('GLOBAL_GR_MODE',           GLOBAL_GR_MODE))
        GLOBAL_GR_THRESHOLD_VEH = float(_rc_ns2.get('GLOBAL_GR_THRESHOLD_VEH', GLOBAL_GR_THRESHOLD_VEH))
        _global_eval_last_t     = -999.0   # reset timer each run
        # ── Demand-adaptive threshold scaling ────────────────────────────────
        # BG_MIN_BUS_DELAY_S and BG_MIN_GAIN_S were tuned at scalar=1.0.
        # At lower demand the absolute pax·s savings are smaller (buses are not
        # delayed as much), so the gate would suppress all TSP actions even when
        # the intervention is still genuinely worthwhile.  Scale both thresholds
        # proportionally with CURRENT_DEMAND_SCALAR so:
        #   scalar=0.70 → thresholds ×0.70 (e.g. min_gain 5→3.5s)
        #   scalar=1.30 → thresholds ×1.30 (e.g. min_gain 5→6.5s — more selective)
        # This preserves the relative selectivity across the flow-sensitivity sweep.
        # NOTE: if BG_MIN_GAIN_S / BG_MIN_BUS_DELAY_S are passed explicitly in
        # reward_overrides, those already-read values are what gets scaled — the
        # explicit value is treated as the "scalar=1.0" reference.
        _demand_scalar_bg = float(_rc_ns2.get('CURRENT_DEMAND_SCALAR', 1.0))
        if abs(_demand_scalar_bg - 1.0) > 0.01:
            BG_MIN_BUS_DELAY_S = BG_MIN_BUS_DELAY_S * _demand_scalar_bg
            BG_MIN_GAIN_S      = BG_MIN_GAIN_S      * _demand_scalar_bg
            log_to_file(
                f"[BARGAIN_SPM] demand_scalar={_demand_scalar_bg:.2f} → "
                f"BG_MIN_BUS_DELAY_S={BG_MIN_BUS_DELAY_S:.2f}s "
                f"BG_MIN_GAIN_S={BG_MIN_GAIN_S:.2f}s (demand-scaled)")
        # ── Harmony-Search Extension (_HSExt variant) ────────────────────────
        # CRITICAL: HS_EXT_MODE must be refreshed here so the module-cached
        # default (False) does not persist across batch runs.
        global HS_EXT_MODE, HS_EXT_T_MIN, HS_EXT_T_MAX
        global HS_EXT_HMS, HS_EXT_HMCR, HS_EXT_PAR, HS_EXT_BW, HS_EXT_NITER
        HS_EXT_MODE  = bool(_rc_ns2.get('HS_EXT_MODE',  False))
        HS_EXT_T_MIN = float(_rc_ns2.get('HS_EXT_T_MIN', HS_EXT_T_MIN))
        HS_EXT_T_MAX = float(_rc_ns2.get('HS_EXT_T_MAX', HS_EXT_T_MAX))
        HS_EXT_HMS   = int(_rc_ns2.get('HS_EXT_HMS',    HS_EXT_HMS))
        HS_EXT_HMCR  = float(_rc_ns2.get('HS_EXT_HMCR', HS_EXT_HMCR))
        HS_EXT_PAR   = float(_rc_ns2.get('HS_EXT_PAR',  HS_EXT_PAR))
        HS_EXT_BW    = float(_rc_ns2.get('HS_EXT_BW',   HS_EXT_BW))
        HS_EXT_NITER = int(_rc_ns2.get('HS_EXT_NITER',  HS_EXT_NITER))
        # ── META_TSP: system-optimal all-traffic objective ────────────────────
        # CRITICAL: META_TSP_MODE must be refreshed here, otherwise the module-
        # cached default (False) is used for every run after the first, and the
        # strategy silently falls through to the MARL/RL path.
        global META_TSP_MODE
        global META_DT_S, META_BASE_BUS_WEIGHT, META_HW_SENSITIVITY, META_HW_REF_S
        global META_MIN_THRESHOLD_PAX_S, META_BALANCE_FACTOR, META_MIN_BUS_DELAY_S
        global META_OC_WEIGHT, META_CAR_OCC
        META_TSP_MODE            = bool(_rc_ns2.get('META_TSP_MODE',            META_TSP_MODE))
        META_DT_S                = float(_rc_ns2.get('META_DT_S',               META_DT_S))
        META_BASE_BUS_WEIGHT     = float(_rc_ns2.get('META_BASE_BUS_WEIGHT',    META_BASE_BUS_WEIGHT))
        META_HW_SENSITIVITY      = float(_rc_ns2.get('META_HW_SENSITIVITY',     META_HW_SENSITIVITY))
        META_HW_REF_S            = float(_rc_ns2.get('META_HW_REF_S',           META_HW_REF_S))
        META_MIN_THRESHOLD_PAX_S = float(_rc_ns2.get('META_MIN_THRESHOLD_PAX_S',META_MIN_THRESHOLD_PAX_S))
        META_BALANCE_FACTOR      = float(_rc_ns2.get('META_BALANCE_FACTOR',     META_BALANCE_FACTOR))
        # ── LEAN MODE: re-enforce disabled flags after run_config refresh ─────
        # run_config.py written by batch_runner cannot re-enable these in lean.
        if LEAN_MODE:
            META_TSP_MODE         = False
            MDN_DELAY_MODE        = False
            REWARD_INV_DELAY_MODE = False
            QUEUE_MODEL_MODE      = False
            BXT_MODE              = False
        META_MIN_BUS_DELAY_S     = float(_rc_ns2.get('META_MIN_BUS_DELAY_S',    META_MIN_BUS_DELAY_S))
        META_OC_WEIGHT           = float(_rc_ns2.get('META_OC_WEIGHT',          META_OC_WEIGHT))
        META_CAR_OCC             = float(_rc_ns2.get('META_CAR_OCC',            META_CAR_OCC))
        # ── MDN Delay Extension (Zhu et al. 2026) ────────────────────────────
        # CRITICAL: MDN_DELAY_MODE must be refreshed here — module-cached default
        # (False) would otherwise persist across batch runs, silently skipping the
        # MDN reward branch for every run after the first.
        global MDN_DELAY_MODE, MDN_DDT_POWER, MDN_N_COMPONENTS, MDN_EPSILON
        MDN_DELAY_MODE   = bool(_rc_ns2.get('MDN_DELAY_MODE',   MDN_DELAY_MODE))
        MDN_DDT_POWER    = float(_rc_ns2.get('MDN_DDT_POWER',   MDN_DDT_POWER))
        MDN_N_COMPONENTS = int(_rc_ns2.get('MDN_N_COMPONENTS',  MDN_N_COMPONENTS))
        MDN_EPSILON      = float(_rc_ns2.get('MDN_EPSILON',      MDN_EPSILON))
        # ── Queue-based delay (D/D/1 + Webster queue model) ─────────────────
        # CRITICAL: QUEUE_MODEL_MODE must be refreshed so that it doesn't
        # silently fall through to the MARL/MDN path on subsequent batch runs.
        global QUEUE_MODEL_MODE, QUEUE_MODEL_SAT_FLOW_VPH
        QUEUE_MODEL_MODE         = bool(_rc_ns2.get('QUEUE_MODEL_MODE',         QUEUE_MODEL_MODE))
        QUEUE_MODEL_SAT_FLOW_VPH = float(_rc_ns2.get('QUEUE_MODEL_SAT_FLOW_VPH', QUEUE_MODEL_SAT_FLOW_VPH))
        # ── MARL tuning params: wh and car_weight ─────────────────────────────
        global DCTSP_W_H, DCTSP_W_HEADWAY, DCTSP_W_PAX_DELAY, DCTSP_CAR_WEIGHT
        DCTSP_W_H          = float(_rc_ns2.get('DCTSP_W_H',         DCTSP_W_H))
        DCTSP_W_HEADWAY    = DCTSP_W_H
        DCTSP_W_PAX_DELAY  = 1.0 - DCTSP_W_H
        DCTSP_CAR_WEIGHT   = float(_rc_ns2.get('DCTSP_CAR_WEIGHT',  DCTSP_CAR_WEIGHT))
        print(f"[TSP] Reward mode: GLOBAL={GLOBAL_REWARD_MODE} "
              f"INV_DELAY={REWARD_INV_DELAY_MODE} "
              f"V2X={REWARD_V2X_MODE} car_w={INV_DELAY_CAR_WEIGHT} "
              f"inv_thr={INV_DELAY_MIN_DELAY_S}s v2x_thr={V2X_MIN_DELAY_S}s"
              f" SELFORG={REWARD_SELFORG_MODE} min_delay={SELFORG_MIN_BUS_DELAY_S}s"
              f" overlap={SELFORG_PHASE_OVERLAP_S}s"
              f" ZIG={DCTSP_ZIG_MODE} zig_overlap={ZIG_PHASE_OVERLAP_S}s"
              f" MP_ECTM={MP_ECTM_MODE} ectm_dt={MP_ECTM_DT_S}s"
              f" BXT={BXT_MODE} bxt_eps={BXT_EPSILON}"
              f" GREEN_REALLOC={DCTSP_GREEN_REALLOC_MODE} rec={GREEN_REALLOC_RECOVER_FRACTION:.2f}"
              f" BARGAIN_SPM={BARGAIN_SPM_MODE}"
              f" META_TSP={META_TSP_MODE} thr={META_MIN_THRESHOLD_PAX_S}pax·s"
              f" min_del={META_MIN_BUS_DELAY_S}s w_bus={META_BASE_BUS_WEIGHT}"
              f" MDN={MDN_DELAY_MODE} p={MDN_DDT_POWER} eps={MDN_EPSILON}"
              f" QUEUE_MODEL={QUEUE_MODEL_MODE} sat={QUEUE_MODEL_SAT_FLOW_VPH:.0f}"
              f" NET_FACTOR={NETWORK_FACTOR:.1f}"
              f" MARL_wh={DCTSP_W_H:.2f} car_w={DCTSP_CAR_WEIGHT:.2f}")
        log_to_file(f"[CONFIG] GLOBAL_REWARD_MODE={GLOBAL_REWARD_MODE} "
                    f"INV_DELAY={REWARD_INV_DELAY_MODE} V2X={REWARD_V2X_MODE} "
                    f"SELFORG={REWARD_SELFORG_MODE} ZIG={DCTSP_ZIG_MODE} "
                    f"MP_ECTM={MP_ECTM_MODE} BXT={BXT_MODE} "
                    f"GREEN_REALLOC={DCTSP_GREEN_REALLOC_MODE} rec={GREEN_REALLOC_RECOVER_FRACTION:.2f} "
                    f"BARGAIN_SPM={BARGAIN_SPM_MODE} "
                    f"META_TSP={META_TSP_MODE} "
                    f"MDN_DELAY={MDN_DELAY_MODE} mdn_p={MDN_DDT_POWER} mdn_eps={MDN_EPSILON} "
                    f"QUEUE_MODEL={QUEUE_MODEL_MODE} sat={QUEUE_MODEL_SAT_FLOW_VPH:.0f} "
                    f"NETWORK_FACTOR={NETWORK_FACTOR:.1f} "
                    f"MARL_wh={DCTSP_W_H:.2f} car_w={DCTSP_CAR_WEIGHT:.2f}")
        # ── RL state reset between runs ───────────────────────────────────────
        # _dctsp_pending_td holds vehicle-specific state from the previous run.
        # Vehicle IDs are not reused across runs, so always clear it.
        # _dctsp_q_table is preserved across replications of the SAME experiment
        # so the agent accumulates learning over seeds.  It is reset when the
        # experiment name changes (different reward scale → Q-values incompatible).
        global _dctsp_pending_td, _dctsp_q_table
        _dctsp_pending_td.clear()
        _poz_action_log.clear()   # stale vehicle IDs from previous run
        _rl_prev_exp = _dctsp_q_table.pop('__experiment__', None)
        if _rl_prev_exp != _CURRENT_EXPERIMENT:
            _dctsp_q_table.clear()
            _dctsp_bxt_q_table.clear()
            log_to_file(f"[DCTSP_RL] Q-table reset: {_rl_prev_exp!r} → {_CURRENT_EXPERIMENT!r}")
        else:
            _q_states = sum(len(v) for k, v in _dctsp_q_table.items() if k != '__experiment__')
            _bxt_states = sum(len(v) for v in _dctsp_bxt_q_table.values())
            log_to_file(f"[DCTSP_RL] Q-table retained for {_CURRENT_EXPERIMENT!r} "
                        f"({_q_states} MARL state-entries, {_bxt_states} BXT state-entries)")
        _dctsp_q_table['__experiment__'] = _CURRENT_EXPERIMENT
    except Exception as _rc_err:
        AKIPrintString(f"[TSP] WARNING: AAPIInit run_config refresh failed: {_rc_err}")
    _ts2 = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
    _BUS_TRACKING_CSV  = os.path.join(LOG_DIR, f"bus_positions_{_CURRENT_EXPERIMENT}_{_ts2}.csv")
    _PRESENCE_SNAPSHOT_CSV = os.path.join(LOG_DIR, f"presence_snapshot_{_CURRENT_EXPERIMENT}_{_ts2}.csv")
    _DET_CSV           = os.path.join(LOG_DIR, f"detection_points_{_CURRENT_EXPERIMENT}_{_ts2}.csv")
    _WAVE_EVENTS_CSV   = os.path.join(LOG_DIR, f"corridor_wave_events_{_CURRENT_EXPERIMENT}_{_ts2}.csv")
    _DET_GEOJSON       = os.path.join(LOG_DIR, f"detection_points_{_ts2}.geojson")
    _JUNC_CSV          = os.path.join(LOG_DIR, f"junction_centroids_{_ts2}.csv")
    _RUN_SUMMARY_TXT   = os.path.join(LOG_DIR, f"tsp_run_summary_{_ts2}.txt")
    _QUEUE_SNAPSHOT_CSV = os.path.join(LOG_DIR, f"queue_snapshot_{_CURRENT_EXPERIMENT}_{_ts2}.csv")
    _NO_INS_SUMMARY_CSV = os.path.join(LOG_DIR, f"no_ins_summary_{_CURRENT_EXPERIMENT}_{_ts2}.csv")
    _OFFSET_CSV = os.path.join(LOG_DIR, f"green_offsets_{_CURRENT_EXPERIMENT}_{_ts2}.csv")
    _offset_header_written = False
    _OBJECTIVE_TRACE_CSV = os.path.join(LOG_DIR, f"objective_trace_{_CURRENT_EXPERIMENT}_{_ts2}.csv")
    _objective_trace_header_written = False
    _DYNAROPAC_DECISION_CSV = os.path.join(LOG_DIR, f"dynaropac_decisions_{_CURRENT_EXPERIMENT}_{_ts2}.csv")
    _dynaropac_decision_header_written = False

    # ── Read-only model DB integrity preflight (fail-fast) ───────────────────
    if not _preflight_model_db_health():
        return -1

    # ── Reset per-run detection and tracking state ────────────────────────────
    global _marked_detections, _mark_calls_total, _mark_calls_written
    global _bus_zone_state, _bus_zone_entry_time, _bus_seen_ids, _bus_last_nearest_jct
    global _bus_line_id, _bus_track_last_t, _bus_track_header_written
    global _presence_snapshot_header_written
    global _geojson_features, _ge_events, _wave_events
    global _pt_line_jct_route, _pt_line_section_set, _sec_to_corridor_jct
    global _corridor_jct_incoming, _bus_observed_jcts
    global _bus_type_provisional
    global _last_dashboard_t
    global _queue_snap_last_t, _queue_snap_header_written
    _marked_detections.clear()
    _mark_calls_total        = 0
    _mark_calls_written      = 0
    _bus_zone_state.clear()
    _bus_zone_entry_time.clear()
    _bus_seen_ids.clear()
    _bus_last_nearest_jct.clear()
    _bus_line_id.clear()
    _bus_observed_jcts.clear()
    _bus_track_last_t        = -1e9
    _bus_track_header_written = False
    _presence_snapshot_header_written = False
    _queue_snap_last_t       = -1e9
    _queue_snap_header_written = False
    _geojson_features.clear()
    _ge_events.clear()
    _wave_events.clear()
    _pt_line_jct_route.clear()
    _pt_line_section_set.clear()
    _sec_to_corridor_jct.clear()
    _corridor_jct_incoming.clear()
    _last_dashboard_t        = -1e9
    _bus_type_provisional    = False

    # ── Deterministic Python RNG — makes harmony search repeatable ────────────
    # The Aimsun replication seed controls vehicle-level stochasticity; this
    # seeds the Python random module so harmony-search results are identical
    # across runs regardless of which Aimsun seed is selected.
    random.seed(12345)

    # ── Clear bus-detection polyline circles left from the previous run ────────
    if ALLOW_MODEL_CATALOG_WRITES:
        try:
            from PyANGKernel import GKSystem as _GKS
            _model = _GKS.getSystem().getActiveModel()
            if _model is not None:
                _pl_type = _model.getType("GKPolyline")
                _ann_type = _model.getType("GKAnnotation")
                _n = _clear_existing_markers(_model, [_pl_type, _ann_type])
                if _n and LOG_INIT:
                    AKIPrintString(f"[INIT] Cleared {_n} TSP marker(s) from previous run")
        except Exception:
            pass  # non-fatal — PyANGKernel may not be available in all environments
    else:
        log_to_file(
            "[INIT] Catalog writes disabled — skipping in-model marker cleanup",
            force=True,
        )
    dm = DemandMonitor()
    dm.print_demand("AAPIInit")
    for inter_id, config in INTERSECTIONS_CONFIG.items():
        try:
            stats.register_intersection(config)
            controllers[inter_id] = IntersectionController(config)
        except Exception as e:
            if LOG_INIT: AKIPrintString(f"[INIT] ERROR creating controller {inter_id}: {e}")

    # Clear any bus/car/truck type guesses that may have been left behind by a
    # previous run.  AAPIInit should always resolve these from the current model.
    stats._car_pos = -1
    stats._bus_pos = -1
    stats._truck_pos = -1

    # ── Initialise DynaROPAC network-wide optimizer ───────────────────────────
    if CONTROL_MODE == "DYNAOPAC_HARMONY":
        if _DYNAROPAC_AVAILABLE:
            _dynaropac_optimizer = DynaROPACOptimizer(
                time_interval=5.0,
                eta_min=10.0,
                eta_max=60.0,
                car_occupancy=1.5,
            )
            _dynaropac_last_eval_t = -999.0
            log_to_file("[INIT] DynaROPAC HARMONY optimizer initialised "
                        f"({len(controllers)} intersections, eval_interval={_DYNAROPAC_EVAL_INTERVAL_S}s)")
        else:
            log_to_file("[INIT] WARNING: DYNAOPAC_HARMONY requested but dynaropac_controller "
                        "import failed — falling back to HARMONY mode for TSP decisions")

    # ── Log phase-group summary for every GROUP_BASED / DYNAOPAC intersection ─
    if CONTROL_MODE in ("GROUP_BASED", "GROUP_BASED_URTSP", "GROUP_BASED_HARMONY", "DYNAOPAC", "DYNAOPAC_HARMONY"):
        if LOG_INIT:
            log_to_file("[INIT] ===== GROUP-BASED PHASE GROUP SUMMARY =====")
        for iid, ctrl in controllers.items():
            if ctrl.gb is not None:
                gb = ctrl.gb
                n_pg = len(gb.phase_groups)
                if LOG_INIT:
                    detail = " | ".join(
                        f"[{','.join(map(str,g))}](mg={sum(gb.max_green.get(s,40.) for s in g):.0f}s)"
                        for g in gb.phase_groups
                    )
                    log_to_file(
                        f"[INIT] jct={iid} sg_count={len(gb.all_sg)} "
                        f"phase_groups={n_pg} bus_sg={gb.bus_sg} tsp_mode={gb.tsp_mode} | {detail}"
                    )
                    AKIPrintString(
                        f"[INIT] jct={iid} phase_groups={n_pg} "
                        f"bus_sg={gb.bus_sg} bus_phase={gb._bus_aimsun_phase}"
                    )
            else:
                if LOG_INIT:
                    log_to_file(f"[INIT] jct={iid} — GroupBasedController NOT initialised")
                    AKIPrintString(f"[INIT] WARNING jct={iid} — GroupBasedController not initialised")

    # ── Build corridor coordinators from INTERSECTION_GROUPS ─────────────────
    # DYNAOPAC also builds coordinators (uses COORDINATED_TSP / COORDINATION_ALGO
    # to choose shockwave / kalman / adaptive pre-arm policy like GROUP_BASED_HARMONY)
    corridor_coordinators = []
    if CONTROL_MODE in ("GROUP_BASED", "GROUP_BASED_URTSP", "GROUP_BASED_HARMONY", "HARMONY", "DYNAOPAC", "DYNAOPAC_HARMONY"):
        if LOG_INIT:
            log_to_file(f"[INIT] Building corridor coordinators from {len(INTERSECTION_GROUPS)} group(s)")
        for gname, iids in INTERSECTION_GROUPS.items():
            coord = CorridorCoordinator(gname, iids, controllers)
            corridor_coordinators.append(coord)
        if LOG_INIT:
            AKIPrintString(
                f"[INIT] Corridor groups: "
                + ", ".join(
                    f"{c.name}({len(c.inter_ids)} intersections)"
                    for c in corridor_coordinators
                )
            )

    return 0


def _apply_config_patches(iid, config, ctrl, aimsun_n_phases):
    """
    Patch config dict and live controller attributes to match Aimsun's reality.

    Called once per intersection from validate_intersection_configs after the
    comparison is done.  Only writes a field when the live Aimsun value differs
    from what the config has — so a correct config is untouched.

    Patchable fields
    ----------------
    - NumberOfPhases       → from ECIGetNumberPhases
    - GreenPhaseDuration   → from GetPhaseDuration (each phase, 0-based timeSta)
    - SignalGroupIDList     → rebuilt from ECIGetNumberSignalGroupsPhase /
                              ECIGetSignalGroupId preserving config order where
                              IDs still exist, appending new ones at the end
    - PhaseIndex           → remapped so no value exceeds len(UpDetList)-1;
                              values that are out of range are clamped to 0
    - DetDistance          → wrapped to nested list if still flat
    - controller.PhaseIndex, controller.SignalGroupIDList, controller.phase_list
      updated to stay in sync with the patched config

    Cannot patch at runtime
    -----------------------
    - Control type (must be set in Aimsun GUI)
    - UpDetList / BusDet   (detector wiring, would need re-initialisation)
    """
    patches = []

    try:
        # ── 1. NumberOfPhases ─────────────────────────────────────────────
        if config.get('NumberOfPhases') != aimsun_n_phases:
            config['NumberOfPhases'] = aimsun_n_phases
            patches.append(f'NumberOfPhases → {aimsun_n_phases}')

        # ── 2. GreenPhaseDuration — refresh from Aimsun live plan ─────────
        live_durs = []
        for ph in range(1, aimsun_n_phases + 1):
            try:
                live_durs.append(round(GetPhaseDuration(iid, ph, 0.0), 1))
            except Exception:
                cfg_d = config.get('GreenPhaseDuration', [])
                live_durs.append(cfg_d[ph - 1] if ph - 1 < len(cfg_d) else 10.0)

        cfg_durs = config.get('GreenPhaseDuration', [])
        if live_durs != cfg_durs:
            config['GreenPhaseDuration'] = live_durs
            patches.append(f'GreenPhaseDuration → {live_durs}')

        # ── 3. SignalGroupIDList — rebuild from Aimsun, preserve config order
        live_sg_list = []
        for ph in range(1, aimsun_n_phases + 1):
            try:
                n_sg = ECIGetNbSignalGroupsPhaseofJunction(iid, ph, 0.0)
                ph_sgs = []
                for pos in range(1, n_sg + 1):
                    try:
                        ph_sgs.append(ECIGetSignalGroupPhaseofJunction(iid, ph, pos, 0.0))
                    except Exception:
                        pass
            except Exception:
                ph_sgs = []

            # Preserve config ordering for IDs that still exist; append new ones
            cfg_ph_sgs = (config.get('SignalGroupIDList', [])[ph - 1]
                          if ph - 1 < len(config.get('SignalGroupIDList', []))
                          else [])
            aimsun_set = set(ph_sgs)
            ordered = [sg for sg in cfg_ph_sgs if sg in aimsun_set]
            for sg in ph_sgs:
                if sg not in ordered:
                    ordered.append(sg)
            live_sg_list.append(ordered)

        if live_sg_list != config.get('SignalGroupIDList', []):
            config['SignalGroupIDList'] = live_sg_list
            patches.append(f'SignalGroupIDList rebuilt from Aimsun')
            if ctrl is not None:
                ctrl.SignalGroupIDList = live_sg_list

        # ── 4. PhaseIndex — clamp out-of-range values to 0 ───────────────
        up_det = config.get('UpDetList', [])
        n_groups = max(len(up_det), 1)
        phase_idx = dict(config.get('PhaseIndex', {}))
        clamped = {}
        for k, v in phase_idx.items():
            if v >= n_groups:
                phase_idx[k] = 0
                clamped[k] = v
        if clamped:
            config['PhaseIndex'] = phase_idx
            patches.append(f'PhaseIndex clamped {clamped} → 0 (UpDetList has {n_groups} group(s))')
            if ctrl is not None:
                ctrl.PhaseIndex = phase_idx

        # ── 5. DetDistance — ensure nested ───────────────────────────────
        dd = config.get('DetDistance', [])
        if dd and not isinstance(dd[0], (list, tuple)):
            config['DetDistance'] = [dd]
            patches.append(f'DetDistance wrapped to nested')
            if ctrl is not None:
                ctrl.DetDistance = config['DetDistance']
                ctrl.config['DetDistance'] = config['DetDistance']

        # ── 6. Sync controller phase_list ────────────────────────────────
        if ctrl is not None:
            new_pl = list(range(1, aimsun_n_phases + 1))
            if ctrl.phase_list != new_pl:
                ctrl.phase_list = new_pl
                patches.append(f'phase_list → {new_pl}')

    except Exception as ex:
        log_to_file(f'[PATCH] inter={iid} unexpected error: {ex}')
        _vprint(f'[PATCH] WARNING inter={iid}: patch step failed: {ex}')
        return

    if patches:
        msg = f'[PATCH] inter={iid} auto-corrected: ' + ' | '.join(patches)
        log_to_file(msg)
        _vprint(msg)
    else:
        log_to_file(f'[PATCH] inter={iid}: no patches needed')


def validate_intersection_configs():
    """
    Compare every field in INTERSECTIONS_CONFIG against live Aimsun values.

    Checks per intersection
    -----------------------
    1. Control type        — must be 2 or 3 (External API)
    2. Phase count         — ECIGetNumberPhases vs config NumberOfPhases / SignalGroupIDList length
    3. Phase durations     — GetPhaseDuration vs config GreenPhaseDuration
    4. Signal groups/phase — ECIGetNumberSignalGroupsPhase vs len(SignalGroupIDList[phase-1])
    5. Signal group IDs    — ECIGetSignalGroupId vs SignalGroupIDList values
    6. PhaseIndex sanity   — every value must be < len(UpDetList)
    7. DetDistance shape   — must be nested (list of lists) matching UpDetList shape

    Output: full detail to LOG_FILE, summary warnings to Aimsun console.
    """
    SEP  = '=' * 72
    sep2 = '-' * 72

    log_to_file(SEP)
    log_to_file('[VALIDATE] ===== INTERSECTION CONFIG VALIDATION =====')
    log_to_file(SEP)

    total_warnings = 0
    total_errors   = 0

    for iid, config in INTERSECTIONS_CONFIG.items():
        warnings = []
        errors   = []

        cfg_n_phases   = config.get('NumberOfPhases', len(config.get('SignalGroupIDList', [])))
        cfg_sg_list    = config.get('SignalGroupIDList', [])
        cfg_phase_idx  = config.get('PhaseIndex', {})
        cfg_up_det     = config.get('UpDetList', [])
        cfg_det_dist   = config.get('DetDistance', [])
        cfg_green_dur  = config.get('GreenPhaseDuration', [])

        log_to_file(sep2)
        log_to_file(f'[VALIDATE] Junction {iid}')

        # ── 1. Control type ───────────────────────────────────────────────
        try:
            ctrl_type = ECIGetControlType(iid)
            status = 'OK' if ctrl_type in (2, 3) else 'ERROR'
            log_to_file(f'  ControlType : {ctrl_type}  [{status}]  (expected 2 or 3 = External)')
            if ctrl_type not in (2, 3):
                errors.append(f'control type={ctrl_type} (not External)')
        except Exception as ex:
            errors.append(f'ECIGetControlType failed: {ex}')

        # ── 2. Phase count ────────────────────────────────────────────────
        try:
            aimsun_n = ECIGetNumberPhases(iid)
            match = 'OK' if aimsun_n == cfg_n_phases else 'MISMATCH'
            log_to_file(
                f'  Phases      : Aimsun={aimsun_n}  config={cfg_n_phases}  [{match}]')
            if match != 'OK':
                warnings.append(
                    f'phase count Aimsun={aimsun_n} vs config={cfg_n_phases}')
        except Exception as ex:
            errors.append(f'ECIGetNumberPhases failed: {ex}')
            aimsun_n = cfg_n_phases   # best-guess fallback

        # ── 3. Per-phase: duration, signal groups, SG IDs ─────────────────
        for ph in range(1, aimsun_n + 1):
            ph_idx = ph - 1   # 0-based index into config lists

            # Phase duration
            try:
                aimsun_dur = GetPhaseDuration(iid, ph, 0.0)
                if cfg_green_dur and ph_idx < len(cfg_green_dur):
                    cfg_dur = cfg_green_dur[ph_idx]
                    dur_ok  = abs(aimsun_dur - cfg_dur) < 1.0
                    log_to_file(
                        f'  Phase {ph:2d} dur : Aimsun={aimsun_dur:.1f}s  '
                        f'config={cfg_dur:.1f}s  '
                        f'[{"OK" if dur_ok else "MISMATCH"}]')
                    if not dur_ok:
                        warnings.append(
                            f'phase {ph} duration Aimsun={aimsun_dur:.1f}s '
                            f'vs config={cfg_dur:.1f}s')
                else:
                    log_to_file(
                        f'  Phase {ph:2d} dur : Aimsun={aimsun_dur:.1f}s  '
                        f'config=<not specified>')
            except Exception as ex:
                warnings.append(f'phase {ph} duration query failed: {ex}')

            # Signal group count per phase
            try:
                aimsun_sg_n = ECIGetNbSignalGroupsPhaseofJunction(iid, ph, 0.0)
                cfg_sg_n    = len(cfg_sg_list[ph_idx]) if ph_idx < len(cfg_sg_list) else 0
                sg_n_ok     = (aimsun_sg_n == cfg_sg_n)
                log_to_file(
                    f'  Phase {ph:2d} SGs : Aimsun={aimsun_sg_n}  '
                    f'config={cfg_sg_n}  '
                    f'[{"OK" if sg_n_ok else "MISMATCH"}]')
                if not sg_n_ok:
                    warnings.append(
                        f'phase {ph} SG count Aimsun={aimsun_sg_n} '
                        f'vs config={cfg_sg_n}')

                # Signal group IDs per phase
                aimsun_sgs = []
                for pos in range(1, aimsun_sg_n + 1):
                    try:
                        sg_id = ECIGetSignalGroupPhaseofJunction(iid, ph, pos, 0.0)
                        aimsun_sgs.append(sg_id)
                    except Exception:
                        aimsun_sgs.append(None)

                cfg_sgs = cfg_sg_list[ph_idx] if ph_idx < len(cfg_sg_list) else []
                aimsun_set = set(x for x in aimsun_sgs if x is not None)
                cfg_set    = set(cfg_sgs)
                missing_from_cfg    = aimsun_set - cfg_set
                extra_in_cfg        = cfg_set - aimsun_set

                log_to_file(
                    f'  Phase {ph:2d} IDs : Aimsun={sorted(aimsun_sgs)}  '
                    f'config={sorted(cfg_sgs)}')
                if missing_from_cfg:
                    warnings.append(
                        f'phase {ph} SGs in Aimsun but not config: {sorted(missing_from_cfg)}')
                    log_to_file(
                        f'           WARNING: SGs {sorted(missing_from_cfg)} '
                        f'in Aimsun but missing from config')
                if extra_in_cfg:
                    warnings.append(
                        f'phase {ph} SGs in config but not Aimsun: {sorted(extra_in_cfg)}')
                    log_to_file(
                        f'           WARNING: SGs {sorted(extra_in_cfg)} '
                        f'in config but not found in Aimsun')

            except Exception as ex:
                warnings.append(f'phase {ph} SG query failed: {ex}')

        # ── 4. PhaseIndex vs UpDetList range ──────────────────────────────
        n_det_groups = len(cfg_up_det)
        bad_pi = {k: v for k, v in cfg_phase_idx.items()
                  if v >= n_det_groups and n_det_groups > 0}
        if bad_pi:
            errors.append(
                f'PhaseIndex values {bad_pi} exceed UpDetList length {n_det_groups} '
                f'— will cause IndexError in objective functions')
            log_to_file(
                f'  PhaseIndex  : ERROR — values {bad_pi} out of range '
                f'for UpDetList length {n_det_groups}')
        else:
            log_to_file(
                f'  PhaseIndex  : OK (all values < UpDetList length {n_det_groups})')

        # ── 5. DetDistance shape ──────────────────────────────────────────
        if cfg_det_dist:
            if not isinstance(cfg_det_dist[0], (list, tuple)):
                warnings.append(
                    'DetDistance is flat — should be nested list matching UpDetList '
                    '(auto-fixed at runtime, but config should be corrected)')
                log_to_file(
                    f'  DetDistance : WARN flat list {cfg_det_dist} '
                    f'— auto-nested at runtime')
            else:
                log_to_file(f'  DetDistance : OK nested {cfg_det_dist}')

        # ── Summary for this intersection ─────────────────────────────────
        total_warnings += len(warnings)
        total_errors   += len(errors)

        if errors or warnings:
            _vprint(
                f'[VALIDATE] inter={iid} — '
                f'{len(errors)} error(s), {len(warnings)} warning(s)')
            for e in errors:
                _vprint(f'  [VALIDATE ERROR]   inter={iid}: {e}')
            for w in warnings:
                _vprint(f'  [VALIDATE WARN]    inter={iid}: {w}')
        else:
            _vprint(f'[VALIDATE] inter={iid} — OK')

        # ── Auto-patch: fix the config dict and live controller in-place ──
        # Only touches fields where Aimsun's live values differ from config.
        # Skips control-type errors (can't fix at runtime) and missing junctions.
        ctrl = controllers.get(iid)
        _apply_config_patches(iid, config, ctrl, aimsun_n)

    log_to_file(SEP)
    log_to_file(
        f'[VALIDATE] DONE — {total_errors} errors, {total_warnings} warnings '
        f'across {len(INTERSECTIONS_CONFIG)} intersections')
    log_to_file(f'[VALIDATE] Full detail in log: {LOG_FILE}')
    log_to_file(SEP)
    _vprint(
        f'[VALIDATE] Config check complete — '
        f'{total_errors} error(s), {total_warnings} warning(s). '
        f'See log: {LOG_FILE}')


def AAPISimulationReady():
    global controllers

    # ── Backup polyline marker clear (AAPIInit clear may fail if PyANGKernel
    #    is not yet bound; by SimulationReady the model is always accessible) ──
    try:
        from PyANGKernel import GKSystem as _GKS2
        _model2 = _GKS2.getSystem().getActiveModel()
        if _model2 is not None:
            _pl2   = _model2.getType("GKPolyline")
            _ann2  = _model2.getType("GKAnnotation")
            _n2    = _clear_existing_markers(_model2, [_pl2, _ann2])
            if _n2 and LOG_INIT:
                AKIPrintString(f"[SIMREADY] Cleared {_n2} TSP marker(s) from previous run")
    except Exception:
        pass  # non-fatal

    try:
        stats.finalise_init()
    except Exception as e:
        _vprint(f"[TSP] WARNING: finalise_init failed: {e}")

    validate_intersection_configs()

    # Junctions must be set to External/API control type in the Aimsun model
    # GUI before running — this cannot be done via the AAPI at runtime.
    # Verify each junction is actually under external control and warn if not.
    for iid in list(controllers.keys()):
        ctrl_type = ECIGetControlType(iid)
        if ctrl_type not in (2, 3):
            _vprint(
                f"[CONTROL] WARNING: junction {iid} control type={ctrl_type} "                f"— expected 2 or 3 (External). "                f"Set junction to 'External' control in the Aimsun model GUI.")

    # === REBUILD PHASE LIST NOW THAT JUNCTIONS ARE UNDER CONTROL ===
    for iid, ctrl in controllers.items():
        try:
            num_phases = ECIGetNumberPhases(iid)
            ctrl.phase_list = list(range(1, num_phases + 1))
            '''
            _vprint(f"[CONTROL] Junction {iid}: {num_phases} phases → {ctrl.phase_list}")
            '''
        except Exception as e:
            _vprint(f"[CONTROL] WARNING: could not get phases for {iid}: {e}")

    # === RE-INITIALISE GROUP-BASED CONTROLLERS WITH LIVE ECI DATA ===
    # AAPIInit runs before the simulation starts — ECI phase scan may return
    # nothing for junctions not yet active, producing an all-conflict matrix
    # and 1-SG-per-group structure.  Now that the sim is running, re-derive
    # from the live model to get correct phase-based compatibility groupings.
    if CONTROL_MODE in ("GROUP_BASED", "GROUP_BASED_URTSP", "GROUP_BASED_HARMONY", "HARMONY", "DYNAOPAC", "DYNAOPAC_HARMONY"):
        # ── Verify intersections are in External Control mode ─────────────────
        # GROUP_BASED uses ECIChangeSignalGroupState which requires control_type=2/3.
        # HARMONY does not — it rides on top of the normal plan.
        # If an intersection is not External, log a prominent warning.
        _bad_ctrl = []
        for iid, ctrl in controllers.items():
            if ctrl.gb is None:
                continue
            try:
                ct = ECIGetControlType(iid)
                ctrl.gb._external_control = (ct in (2, 3))
                if not ctrl.gb._external_control:
                    _bad_ctrl.append((iid, ct))
            except Exception:
                ctrl.gb._external_control = False
                _bad_ctrl.append((iid, '?'))
        if _bad_ctrl:
            _msg = (
                f"[GB] CRITICAL: {len(_bad_ctrl)} junction(s) NOT in External Control "
                f"mode — GROUP_BASED signals will NOT change (all-red or frozen). "
                f"Set control type = External in Aimsun for: "
                + ", ".join(f"jct={j}(type={t})" for j, t in _bad_ctrl)
            )
            log_to_file(_msg, force=True)   # always prints regardless of VERBOSE

        for iid, ctrl in controllers.items():
            if ctrl.gb is not None and getattr(ctrl.gb, '_external_control', True):
                try:
                    ctrl.gb.reinitialise_from_model()
                except Exception as e:
                    _vprint(f"[GB] WARNING jct={iid} reinitialise_from_model failed: {e}")

        # Compute corridor positions (metres along route) for Kalman coordination.
        # Junction XY is available now that the simulation is running.
        # We walk each corridor group in listed order, accumulating Euclidean
        # distance between consecutive junction centroids.  If XY cannot be
        # resolved for a junction, its position is estimated using the previous
        # gap + a 400 m nominal link length.
        if COORDINATED_TSP:
            NOMINAL_LINK_M = 400.0   # fallback inter-junction spacing
            for coord in corridor_coordinators:
                pos_map   = {}
                cum_pos   = 0.0
                prev_xy   = None
                # Iterate ALL route junctions (managed + unmanaged intermediates) so
                # that _signal_aware_eta can look up corridor positions for every
                # junction the bus passes through, not just the coordinated ones.
                for iid in coord.route_inter_ids:
                    gb = coord._ctrl_map.get(iid)
                    ic = coord._ic_map.get(iid)
                    # For intermediate route junctions not in _ctrl_map / _ic_map,
                    # fall back to the global controllers dict (they may have their
                    # own IntersectionController with XY data).
                    if gb is None and ic is None:
                        _fb = controllers.get(iid)
                        if _fb is not None:
                            ic = _fb
                    # Prefer GroupBasedController XY; fall back to HARMONY IC XY
                    try:
                        xy = gb._get_junction_xy() if gb else None
                        if xy is None and ic is not None:
                            xy = ic._get_junction_xy()
                    except Exception:
                        xy = None
                    if xy is not None and prev_xy is not None:
                        dx = xy[0] - prev_xy[0]
                        dy = xy[1] - prev_xy[1]
                        cum_pos += math.sqrt(dx*dx + dy*dy)
                    elif prev_xy is not None:
                        cum_pos += NOMINAL_LINK_M   # XY unavailable — use nominal
                    pos_map[iid] = cum_pos
                    if xy is not None:
                        prev_xy = xy
                    elif prev_xy is None:
                        prev_xy = (0.0, 0.0)  # anchor first junction at origin
                coord.set_corridor_positions(pos_map)
        else:
            log_to_file("[CORRIDOR] COORDINATED_TSP=False — Kalman pre-arming disabled")

    # ── Build PT-route-aware corridor maps (needs controllers + incoming_sections) ──
    try:
        _build_pt_line_corridor_routes()
    except Exception as _ptrb_e:
        log_to_file(f"[PT-ROUTE] WARNING: _build_pt_line_corridor_routes failed: {_ptrb_e}")

    scan_car_pos, scan_bus_pos, scan_truck_pos = _scan_named_vehicle_type_positions()
    pt_bus_pos = _infer_bus_type_pos_from_pt()
    bus_pos = pt_bus_pos if pt_bus_pos > 0 else (
        getattr(stats, '_bus_pos', -1) if getattr(stats, '_bus_pos', -1) > 0 else scan_bus_pos)

    # Resolve truck type: if name-based scan failed AND there are 3+ vehicle types,
    # use the type that is NOT bus and NOT the smallest-numbered (car) type.
    # For a 3-type model (Car=1, Truck=2, Bus=3) or (Car=1, Bus=2, Truck=3):
    # → truck = remaining position after removing bus and car assignments.
    truck_pos = getattr(stats, '_truck_pos', -1)
    if truck_pos <= 0:
        truck_pos = scan_truck_pos
    if truck_pos <= 0:
        nb_types = AKIVehGetNbVehTypes()
        if nb_types >= 3 and bus_pos > 0:
            # Assign truck = the type that is NOT bus and NOT smallest (assumed car)
            candidates = [p for p in range(1, nb_types + 1) if p != bus_pos]
            # Smallest remaining = car; others = truck candidates
            if len(candidates) >= 2:
                car_candidate = min(candidates)
                truck_candidates = [p for p in candidates if p != car_candidate]
                if truck_candidates:
                    truck_pos = truck_candidates[0]

    car_pos = getattr(stats, '_car_pos', -1)
    if car_pos <= 0 or car_pos == bus_pos:
        car_pos = _choose_car_type_pos(bus_pos, truck_pos, preferred_pos=scan_car_pos)

    log_to_file(
        f"[VEH TYPES] named_scan car={scan_car_pos} bus={scan_bus_pos} truck={scan_truck_pos} | "
        f"pt_inferred_bus={pt_bus_pos} | nb_types={AKIVehGetNbVehTypes()} | "
        f"using car={car_pos} bus={bus_pos} truck={truck_pos} hov={getattr(stats, '_hov_pos', -1)}")
    for ctrl in controllers.values():
        if car_pos > 0:
            ctrl.car_type_pos = car_pos
        if bus_pos > 0:
            ctrl.bus_type_pos = bus_pos
        if truck_pos > 0:
            ctrl.truck_type_pos = truck_pos
    if car_pos > 0:
        stats._car_pos = car_pos
    if bus_pos > 0:
        stats._bus_pos = bus_pos
    if truck_pos > 0:
        stats._truck_pos = truck_pos
    else:
        stats._truck_pos = -1

    # If bus type still unresolved, schedule a lazy recheck in PostManage
    # (PT vehicles may not exist yet at AAPIInit time)
    global _bus_type_needs_recheck
    global _bus_type_provisional
    _bus_type_needs_recheck = (bus_pos <= 0)
    _bus_type_provisional = _bus_type_needs_recheck
    if _bus_type_needs_recheck:
        log_to_file("[VEH TYPES] bus_pos unresolved at init — will retry from PT vehicles in first 120s")

    _log_startup_bus_demand_snapshot("AAPIInit")

    # ── Reset per-run one-action guard and OC state ───────────────────────────
    global _bus_acted_at_jct, _pending_oc_corrections
    _bus_acted_at_jct.clear()
    _pending_oc_corrections.clear()

    # ── Snapshot initial phase timings (read-only baseline for OC drift logging)
    # Captured once at the start of every replication; never overwritten.
    # All forward-OC adjustments log their delta against this baseline so you
    # can see cumulative phase drift over a simulation run.
    # NOTE: ECI phase queries may return zero at init time for junctions not yet
    # active; we capture best-effort values and log a count for verification.
    global _initial_phase_timings
    _initial_phase_timings = {}
    for _iid, _ctrl in controllers.items():
        _nid = getattr(_ctrl, 'node_id', _iid)
        try:
            _np = int(ECIGetNumberPhases(_nid) or 0)
            if _np > 0:
                _initial_phase_timings[_iid] = {}
                for _ph in range(1, _np + 1):
                    _dur = float(GetPhaseDuration(_nid, _ph, 0.0) or 0.0)
                    _initial_phase_timings[_iid][_ph] = max(0.0, _dur)
        except Exception:
            pass
    log_to_file(
        f"[INIT] Phase timing baseline snapshot: "
        f"{len(_initial_phase_timings)} junctions | "
        f"guard dicts cleared",
        force=True)

    '''
    _vprint(f"[TSP] Simulation ready | mode={CONTROL_MODE} | {len(controllers)} intersections under external control")
    '''
    return 0


def AAPIManage(time, timeSta, timeTrans, acycle):
    
    return 0


def AAPIPostManage(time, timeSta, timeTrans, acycle):
    # Lazy bus-type recheck: PT vehicles may not exist at AAPIInit time
    global _bus_type_needs_recheck
    global _bus_type_provisional
    global _dynaropac_last_eval_t, _dynaropac_decision_header_written
    if _bus_type_needs_recheck:
        # Try every 30 s for the first 600 s (10 min) to allow time for buses
        # to enter the network before giving up.  The original 120 s window was
        # too short — buses hadn't appeared yet when the recheck was abandoned.
        _recheck_interval = 30.0
        _recheck_limit    = 600.0
        if time <= _recheck_limit and int(time) % int(_recheck_interval) == 0:
            _pt_bus = _infer_bus_type_pos_from_pt()
            if _pt_bus > 0:
                _bus_type_needs_recheck = False
                _bus_type_provisional = False
                for ctrl in controllers.values():
                    ctrl.bus_type_pos = _pt_bus
                    if ctrl.gb is not None:
                        ctrl.gb.bus_type_pos = _pt_bus
                stats._bus_pos = _pt_bus

                # Resolve truck type NOW that bus is known.
                # Truck = the type position that is NOT bus and NOT the lowest
                # numbered (assumed car) — elimination method for 3-type models.
                _nb_t = AKIVehGetNbVehTypes()
                if stats._truck_pos <= 0 and _nb_t >= 3:
                    _other = [p for p in range(1, _nb_t + 1) if p != _pt_bus]
                    if len(_other) >= 2:
                        _car_guess = min(_other)   # smallest = car
                        _truck_guess = [p for p in _other if p != _car_guess]
                        if _truck_guess:
                            _trk = _truck_guess[0]
                            stats._truck_pos = _trk
                            for ctrl in controllers.values():
                                if not hasattr(ctrl, 'truck_type_pos') or ctrl.truck_type_pos <= 0:
                                    ctrl.truck_type_pos = _trk
                                if ctrl.gb is not None and (not hasattr(ctrl.gb, 'truck_type_pos') or ctrl.gb.truck_type_pos <= 0):
                                    ctrl.gb.truck_type_pos = _trk
                            # Also update car type if not resolved
                            if stats._car_pos <= 0 or stats._car_pos == _pt_bus:
                                stats._car_pos = _car_guess
                            log_to_file(
                                f"[VEH TYPES] truck resolved via elimination: "
                                f"car={stats._car_pos} bus={_pt_bus} truck={_trk}"
                            )

                log_to_file(
                    f"[VEH TYPES] lazy PT inference at t={time:.0f}: "
                    f"bus_type_pos={_pt_bus} car={stats._car_pos} truck={stats._truck_pos}"
                    f" — updated all controllers + GB sub-controllers"
                )
        elif time > _recheck_limit:
            _bus_type_needs_recheck = False
            log_to_file(
                f"[VEH TYPES] lazy recheck exhausted at t={time:.0f} "
                f"({_recheck_limit:.0f}s limit): bus_type_pos still unresolved. "
                f"Check vehicle type names in Aimsun model or add BUS_TYPE_POS "
                f"to INTERSECTIONS_CONFIG entry."
            )

    try:
        stats.track_bus_positions(time)
    except Exception as e:
        stop_simulation(f"track_bus_positions crashed t={time:.1f}: {e}")
        return 0

    # ── Continuous bus position log ───────────────────────────────────────
    if TRACK_BUS_POSITIONS:
        try:
            # Build junction XY lookup lazily and keep merging until all
            # junction centroids are resolved.
            global _jct_xy_cache
            if _jct_xy_cache is None or len(_jct_xy_cache) < len(controllers):
                _jxy = dict(_jct_xy_cache or {})
                for _iid, _ctrl in controllers.items():
                    if _iid in _jxy:
                        continue
                    try:
                        _xy = _ctrl._get_junction_xy()
                        if _xy is not None:
                            _zone_r = float(getattr(_ctrl, '_detection_zone_m',
                                          _ctrl.config.get('detection_zone_m', 250.0)))
                            _jxy[_iid] = (_xy[0], _xy[1], _zone_r)
                    except Exception:
                        pass
                if _jxy:
                    _jct_xy_cache = _jxy
            _track_all_bus_positions(time, _jct_xy_cache or {})
        except Exception:
            pass

    for inter_id, controller in controllers.items():
        try:
            # collect_delay runs identically for all modes — GROUP_BASED no longer
            # calls it internally (gb.step is detection + TSP overlay only).
            controller.collect_delay(time, timeSta)
        except Exception as e:
            stop_simulation(f"collect_delay crashed inter={inter_id} t={time:.1f}: {e}")
            return 0
        try:
            controller.update(time, timeSta, acycle)
        except Exception as e:
            stop_simulation(f"update crashed inter={inter_id} t={time:.1f}: {e}")
            return 0

    # ── Step corridor coordinators (after all individual controllers) ─────────
    for coord in corridor_coordinators:
        try:
            coord.step(time, timeSta)
        except Exception as e:
            log_to_file(f"[CORRIDOR] coordinator {coord.name} crashed t={time:.1f}: {e}")
        # ── Periodic forward-OC replan (DCTSP_MARL mode only) ────────────────
        try:
            coord.periodic_replan(time, timeSta, controllers)
        except Exception as _rp_e:
            log_to_file(f"[REPLAN] {coord.name} crashed t={time:.1f}: {_rp_e}")

    # ── Global discrete-time signal evaluation (car-queue GR without bus) ─────
    # When GLOBAL_GR_MODE=True, evaluate green reallocation at every intersection
    # on a fixed GLOBAL_EVAL_DT clock regardless of bus detection.  This
    # implements the global discrete-time extension of the MILP (comprehensive_mp.tex
    # Section 6): GR is always applicable (constraint gr_always) and can reduce
    # cross-approach queue imbalance even with no bus present.
    #
    # The heuristic: if the bus-phase queue (MaxQueueLength[0]) is less than
    # GLOBAL_GR_THRESHOLD_VEH below the mean cross-phase queue AND the controller
    # does NOT already have an active TSP action, reallocate
    # min(GR_delta, BG_NO_ACTION_BONUS_S/2) seconds from the most loaded cross
    # phase to the bus phase.  The reallocation is applied via ECIChangeSignalGroupDuration.
    # Bus-specific actions (GE, ER, PI) still require B_{i,t}=1 (bus present).
    global _global_eval_last_t
    if GLOBAL_GR_MODE and GLOBAL_EVAL_DT > 0.0 and (time - _global_eval_last_t) >= GLOBAL_EVAL_DT:
        _global_eval_last_t = time
        for _gev_iid, _gev_ctrl in controllers.items():
            try:
                # Skip if intersection is already under active TSP
                if getattr(_gev_ctrl, 'TSPStrategy', 0) != 0:
                    continue
                # Skip if bus is currently being handled (event-driven loop active)
                if getattr(_gev_ctrl, 'last_detected_bus_id', -1) > 0:
                    continue
                if TSP_ACTIVE_INTERSECTIONS and _gev_iid not in TSP_ACTIVE_INTERSECTIONS:
                    continue
                # Queue lengths per phase: MaxQueueLength[0] = bus phase
                _gq = np.asarray(getattr(_gev_ctrl, 'MaxQueueLength', []), dtype=float)
                if _gq.ndim == 0 or _gq.size == 0:
                    continue
                _bus_q = float(_gq.flat[0])
                # Cross-phase queues (all phases except bus phase index 0)
                _cross_q = _gq.flat[1:] if _gq.size > 1 else np.asarray([], dtype=float)
                _cross_q_arr = np.asarray(list(_cross_q), dtype=float)
                if _cross_q_arr.size == 0:
                    continue
                _mean_cross_q = float(np.mean(_cross_q_arr))
                # Imbalance: bus phase has more waiting than cross phases
                _imbalance = _bus_q - _mean_cross_q
                if _imbalance < float(GLOBAL_GR_THRESHOLD_VEH):
                    continue  # not enough imbalance to justify GR
                # Compute a conservative GR delta proportional to the imbalance
                _sat = max(float(getattr(_gev_ctrl, 'SaturationFlow', 1800.0)), 1.0)
                # 1 veh imbalance ≈ 3600/sat seconds of green time imbalance
                _gr_delta_s = min(
                    _imbalance * 3600.0 / _sat,
                    float(getattr(_gev_ctrl, 'dctsp_gr_max', 15.0))
                )
                if _gr_delta_s < 1.0:
                    continue  # too small to apply
                # Apply GR via ECIChangeGreenTimes if possible
                _gev_node = getattr(_gev_ctrl, 'node_id', -1)
                if _gev_node <= 0:
                    continue
                try:
                    ECIChangeGreenTimes(_gev_node, 0, _gr_delta_s, 0)
                    log_to_file(
                        f"[GLOBAL_GR] inter={_gev_iid} t={time:.1f} "
                        f"bus_q={_bus_q:.1f} cross_q={_mean_cross_q:.1f} "
                        f"imbalance={_imbalance:.1f}veh gr_delta={_gr_delta_s:.1f}s",
                        force=False)
                except Exception:
                    pass
            except Exception:
                pass

    # ── DYNAOPAC_HARMONY: network-wide delay-optimal phase duration search ──────
    # For each intersection, search candidate green extensions (0..MAX_GE in 1s
    # steps) and select the extension that minimises total person-delay.
    # If optimal extension < 0.5 s → record as detection pass (no action).
    # Applies only the single intersection with the greatest net saving.
    # Logs all candidates + delays to dynaropac_decisions_*.csv for plotting.
    if CONTROL_MODE == "DYNAOPAC_HARMONY" and _dynaropac_optimizer is not None:
        if time - _dynaropac_last_eval_t >= _DYNAROPAC_EVAL_INTERVAL_S:
            _dynaropac_last_eval_t = time
            try:
                _global_best_iid    = None
                _global_best_ge     = 0.0
                _global_best_saving = 0.0
                _dyn_log_rows       = []

                for _iid, _ctrl in controllers.items():
                    if TSP_ACTIVE_INTERSECTIONS and _iid not in TSP_ACTIVE_INTERSECTIONS:
                        continue
                    if getattr(_ctrl, 'TSPStrategy', 0) != 0:
                        continue  # already under active TSP
                    try:
                        _cur_phase = ECIGetCurrentPhase(_ctrl.node_id)
                        if _cur_phase < 0:
                            continue

                        # Build approach states from live section vehicle data
                        _approaches = {}
                        for _si, _sec in enumerate(getattr(_ctrl, 'incoming_sections', [])):
                            try:
                                _nveh = max(int(AKIVehStateGetNbVehiclesSection(_sec, False)), 0)
                                _sinf = AKIInfNetGetSectionANGInf(_sec)
                                _len_m = float(getattr(_sinf, 'length', 200.0) or 200.0)
                                _spd_ms = max(float(getattr(_sinf, 'speedLimit', 50.0) or 50.0) / 3.6, 0.1)
                                _sat = float(getattr(_ctrl, 'SaturationFlow', 1800.0))
                                _approaches[_si] = ApproachState(
                                    approach_id=_si,
                                    queue_length=float(_nveh),
                                    upstream_flow=min(_nveh * 3600.0 / 5.0, _sat),
                                    saturation_flow=_sat,
                                    approach_length=_len_m,
                                    average_speed=_spd_ms,
                                )
                            except Exception:
                                pass
                        if not _approaches:
                            continue

                        # Check if a bus is detected
                        _has_bus = (
                            hasattr(_ctrl, 'BusPresence') and
                            len(_ctrl.BusPresence) > 0 and
                            len(_ctrl.BusPresence[0]) > 0 and
                            max(_ctrl.BusPresence[0]) > 0
                        )
                        _buses_det = {}
                        if _has_bus:
                            try:
                                _spd = float(_ctrl.BusSpeed[0][0] or 0.5)
                                _eta_arr = list(getattr(_ctrl, '_bus_eta', {}).values())
                                _eta = float(_eta_arr[0][1]) if _eta_arr else 20.0
                                _buses_det[0] = BusState(
                                    bus_id=0,
                                    distance_to_stopline=max(_spd * _eta, 1.0),
                                    speed=max(_spd, 0.1),
                                    occupancy=float(getattr(_ctrl, 'BusOcc', 40.0)),
                                    eta=_eta,
                                )
                            except Exception:
                                pass

                        # Build minimal IntersectionState (single-phase view for extension search)
                        _phase_min = float(getattr(_ctrl, 'BusPhaseDuration', 6.0))
                        _phase_max = min(float(getattr(_ctrl, 'GE_upper_bound', 20.0)), MAX_GE_EXTENSION_S)
                        _stage = max(_phase_max * 2, 30.0)

                        _phases_def = {1: PhaseDefinition(
                            phase_id=1,
                            served_approaches=list(_approaches.keys()),
                            min_green=_phase_min,
                            max_green=_phase_min + _phase_max,
                            is_bus_phase=True,
                        )}
                        _istate = IntersectionState(
                            intersection_id=_iid,
                            phases=_phases_def,
                            approaches=_approaches,
                            current_phase=_cur_phase,
                            phase_start_time=float(ECIGetStartingTimePhase(_ctrl.node_id) or time),
                            elapsed_green=max(0.0, time - float(ECIGetStartingTimePhase(_ctrl.node_id) or time)),
                            buses_detected=_buses_det,
                        )

                        # Current phase duration (before extension)
                        _before_dur = float(GetPhaseDuration(_ctrl.node_id, _cur_phase, timeSta) or _phase_min)

                        # Search: try extension 0, 1, 2 ... max_ge (1-second steps)
                        _search_max = int(round(_phase_max))
                        _ext_delays  = []  # (extension_s, total_delay)
                        for _ext in range(0, _search_max + 1):
                            _sw = [float(_before_dur + _ext)]
                            _delay = _dynaropac_optimizer.calculate_delay(
                                _istate, [1], _sw, _stage, include_bus_priority=True)
                            _ext_delays.append((_ext, _delay))

                        # Select minimum delay extension
                        _best_ext, _best_delay = min(_ext_delays, key=lambda x: x[1])
                        _baseline_delay = _ext_delays[0][1]  # extension=0 = no action
                        _saving = _baseline_delay - _best_delay

                        # Log all candidates for this intersection
                        _ext_list   = [e for e, _ in _ext_delays]
                        _delay_list = [round(d, 2) for _, d in _ext_delays]
                        _dyn_log_rows.append({
                            "sim_time_s":    round(time, 1),
                            "junction_id":   _iid,
                            "cur_phase":     _cur_phase,
                            "before_dur_s":  round(_before_dur, 2),
                            "extensions_s":  str(_ext_list),
                            "delays_paxs":   str(_delay_list),
                            "best_ext_s":    round(_best_ext, 2),
                            "best_delay":    round(_best_delay, 2),
                            "baseline_delay":round(_baseline_delay, 2),
                            "saving_paxs":   round(_saving, 2),
                            "bus_detected":  int(bool(_buses_det)),
                            "applied":       0,  # updated below
                        })

                        if _saving > _global_best_saving and _best_ext >= 0.5:
                            _global_best_saving = _saving
                            _global_best_iid    = _iid
                            _global_best_ge     = float(_best_ext)

                    except Exception as _dh_inter_err:
                        log_to_file(f"[DYNAOPAC_HARMONY] inter={_iid} eval error: {_dh_inter_err}")
                        continue

                # Apply the best extension globally
                if _global_best_iid is not None:
                    _ctrl = controllers[_global_best_iid]
                    try:
                        _rem = GetPhaseDuration(_ctrl.node_id, ECIGetCurrentPhase(_ctrl.node_id), timeSta) \
                               - (time - ECIGetStartingTimePhase(_ctrl.node_id))
                        _new_dur = _ctrl.BusPhaseDuration + _global_best_ge
                        ECIChangeTimingPhase(_ctrl.node_id, ECIGetCurrentPhase(_ctrl.node_id),
                                             _new_dur, timeSta)
                        _ctrl.TimeToTerminateBusPhase = time + max(_rem, 0.0) + _global_best_ge
                        _ctrl.TSPStrategy  = 1
                        _ctrl.flag         = 1
                        _ctrl.TSPActiveTime = time + _global_best_ge + 30
                        _ctrl._ge_debt_s   = _global_best_ge
                        _ctrl.last_tsp_action_time = time
                        _ctrl.stats.record_tsp_event(_global_best_iid, 'detection')
                        _ctrl.stats.record_tsp_event(_global_best_iid, 'extension')
                        _ctrl.stats.record_tsp_extension_duration(_global_best_iid, _global_best_ge)
                        # Mark this row as applied
                        for _row in _dyn_log_rows:
                            if _row['junction_id'] == _global_best_iid:
                                _row['applied'] = 1
                        log_to_file(
                            f"[DYNAOPAC_HARMONY] t={time:.1f} applied GE={_global_best_ge:.1f}s "
                            f"jct={_global_best_iid} saving={_global_best_saving:.1f}pax-s"
                        )
                    except Exception as _dh_app_err:
                        log_to_file(f"[DYNAOPAC_HARMONY] apply failed jct={_global_best_iid}: {_dh_app_err}")
                # ── Also evaluate phase insertion for intersections with detected bus ─
                # Only consider INS when bus is detected but NOT already in BusPhase.
                _ins_best_iid     = None
                _ins_best_dur     = 0.0
                _ins_best_saving  = 0.0
                for _iid3, _ctrl3 in controllers.items():
                    if TSP_ACTIVE_INTERSECTIONS and _iid3 not in TSP_ACTIVE_INTERSECTIONS:
                        continue
                    if getattr(_ctrl3, 'TSPStrategy', 0) != 0:
                        continue
                    try:
                        _cur3 = ECIGetCurrentPhase(_ctrl3.node_id)
                        if _cur3 < 0 or _cur3 == getattr(_ctrl3, 'BusPhase', 1):
                            continue  # already on BusPhase — use GE, not INS
                        _has_bus3 = (
                            hasattr(_ctrl3, 'BusPresence') and
                            len(_ctrl3.BusPresence) > 0 and
                            len(_ctrl3.BusPresence[0]) > 0 and
                            max(_ctrl3.BusPresence[0]) > 0
                        )
                        if not _has_bus3:
                            continue
                        # Estimate bus ETA at this junction
                        _eta3_arr = list(getattr(_ctrl3, '_bus_eta', {}).values())
                        _eta3 = float(_eta3_arr[0][1]) if _eta3_arr else 20.0
                        if _eta3 < 5.0 or _eta3 > 60.0:
                            continue  # outside actionable window
                        # Evaluate: insert BusPhase for _eta3+buffer seconds
                        _bp_lb3  = max(float(getattr(_ctrl3, 'BP_lower_bound', 15)), _eta3 + 2.0)
                        _bp_ub3  = min(float(getattr(_ctrl3, 'BP_upper_bound', 30)), MAX_BP_INSERTION_S)
                        if _bp_lb3 >= _bp_ub3:
                            continue
                        # Build minimal state for INS delay calculation
                        _approaches3 = {}
                        for _si3, _sec3 in enumerate(getattr(_ctrl3, 'incoming_sections', [])):
                            try:
                                _nveh3 = max(int(AKIVehStateGetNbVehiclesSection(_sec3, False)), 0)
                                _sinf3 = AKIInfNetGetSectionANGInf(_sec3)
                                _len3  = float(getattr(_sinf3, 'length', 200.0) or 200.0)
                                _spd3  = max(float(getattr(_sinf3, 'speedLimit', 50.0) or 50.0) / 3.6, 0.1)
                                _sat3  = float(getattr(_ctrl3, 'SaturationFlow', 1800.0))
                                _approaches3[_si3] = ApproachState(
                                    approach_id=_si3,
                                    queue_length=float(_nveh3),
                                    upstream_flow=min(_nveh3 * 3600.0 / 5.0, _sat3),
                                    saturation_flow=_sat3,
                                    approach_length=_len3,
                                    average_speed=_spd3,
                                )
                            except Exception:
                                pass
                        if not _approaches3:
                            continue
                        _stage3 = max(_bp_ub3 * 2.0, 30.0)
                        _phases3 = {1: PhaseDefinition(
                            phase_id=1,
                            served_approaches=list(_approaches3.keys()),
                            min_green=_bp_lb3,
                            max_green=_bp_ub3,
                            is_bus_phase=True,
                        )}
                        _istate3 = IntersectionState(
                            intersection_id=_iid3,
                            phases=_phases3,
                            approaches=_approaches3,
                            current_phase=_cur3,
                            phase_start_time=float(ECIGetStartingTimePhase(_ctrl3.node_id) or time),
                            elapsed_green=max(0.0, time - float(ECIGetStartingTimePhase(_ctrl3.node_id) or time)),
                            buses_detected={},
                        )
                        # ── Harmony-like INS duration search ───────────────────
                        # Sweep _bp_lb3 .. _bp_ub3 in 1-second steps and pick
                        # the duration that minimises person-delay (mirrors the GE
                        # search loop approach used for green extension).
                        _best_ins_dur3   = _bp_lb3
                        _best_ins_delay3 = float('inf')
                        _sw_noins = [float(_bp_lb3)]
                        _noins_delay = _dynaropac_optimizer.calculate_delay(
                            _istate3, [1], _sw_noins, _stage3, include_bus_priority=True)
                        for _ins_candidate in range(int(_bp_lb3), int(_bp_ub3) + 1):
                            _ins_dur_f = float(_ins_candidate)
                            _sw_ins_c = [0.0, _ins_dur_f]
                            try:
                                _ins_delay_c = _dynaropac_optimizer.calculate_delay(
                                    _istate3, [1, 1], _sw_ins_c, _stage3, include_bus_priority=True)
                                if _ins_delay_c < _best_ins_delay3:
                                    _best_ins_delay3 = _ins_delay_c
                                    _best_ins_dur3   = _ins_dur_f
                            except Exception:
                                pass
                        _ins_saving3 = _noins_delay - _best_ins_delay3
                        if _ins_saving3 > _ins_best_saving:
                            _ins_best_saving = _ins_saving3
                            _ins_best_iid    = _iid3
                            _ins_best_dur    = _best_ins_dur3
                    except Exception:
                        pass

                # Pick the better of GE and INS globally
                if _ins_best_iid is not None and _ins_best_saving > _global_best_saving:
                    # Apply phase insertion
                    _ctrl_ins = controllers[_ins_best_iid]
                    try:
                        ECIChangeTimingPhase(_ctrl_ins.id, _ctrl_ins.BusPhase,
                                             float(_ins_best_dur), timeSta)
                        ECIChangeDirectPhase(_ctrl_ins.id, _ctrl_ins.BusPhase,
                                             timeSta, time, 0, 0)
                        _ctrl_ins.TSPStrategy  = 2
                        _ctrl_ins.flag         = 2
                        _ctrl_ins.TSPActiveTime = time + _ins_best_dur + 30
                        _ctrl_ins._ge_debt_s   = _ins_best_dur
                        _ctrl_ins.last_tsp_action_time = time
                        _ctrl_ins.stats.record_tsp_event(_ins_best_iid, 'detection')
                        _ctrl_ins.stats.record_tsp_event(_ins_best_iid, 'insertion')
                        _ctrl_ins.stats.record_tsp_insertion_duration(_ins_best_iid, _ins_best_dur)
                        for _row in _dyn_log_rows:
                            if _row['junction_id'] == _ins_best_iid:
                                _row['applied'] = 1
                        log_to_file(
                            f"[DYNAOPAC_HARMONY] t={time:.1f} applied INS={_ins_best_dur:.1f}s "
                            f"jct={_ins_best_iid} saving={_ins_best_saving:.1f}pax-s"
                        )
                        _global_best_iid = _ins_best_iid  # mark as actioned
                    except Exception as _ins_err:
                        log_to_file(f"[DYNAOPAC_HARMONY] INS apply failed jct={_ins_best_iid}: {_ins_err}")

                if _global_best_iid is None:
                    # No GE or INS was beneficial — cancel any active coordination wave
                    # so downstream junctions are freed for independent detection.
                    for _coord_c in corridor_coordinators.values():
                        if _coord_c._wave_active:
                            log_to_file(
                                f"[DYNAOPAC_HARMONY] t={time:.1f} no GE/INS — wave cancelled",
                                force=True)
                            _coord_c._wave_active     = False
                            _coord_c._wave_veh_id     = -1
                            _coord_c._wave_origin     = -1
                            _coord_c._wave_served_ids = set()
                            _coord_c._pre_requests.clear()
                    # Record detection passes for intersections with buses
                    for _iid2, _ctrl2 in controllers.items():
                        try:
                            if (hasattr(_ctrl2, 'BusPresence') and
                                    len(_ctrl2.BusPresence) > 0 and max(_ctrl2.BusPresence[0]) > 0):
                                _ctrl2.stats.record_tsp_event(_iid2, 'detection')
                                _ctrl2.stats.record_tsp_skip(_iid2, 'ge_trivial')
                        except Exception:
                            pass

                # Write decision log rows to CSV
                if _dyn_log_rows and _DYNAROPAC_DECISION_CSV:
                    try:
                        _write_header = not _dynaropac_decision_header_written
                        with open(_DYNAROPAC_DECISION_CSV, "a", newline="", encoding="utf-8") as _f:
                            _wcsv = csv.DictWriter(_f, fieldnames=list(_dyn_log_rows[0].keys()))
                            if _write_header:
                                _wcsv.writeheader()
                                _dynaropac_decision_header_written = True
                            _wcsv.writerows(_dyn_log_rows)
                    except Exception as _csv_err:
                        log_to_file(f"[DYNAOPAC_HARMONY] CSV write failed: {_csv_err}")

            except Exception as _dh_outer:
                log_to_file(f"[DYNAOPAC_HARMONY] eval loop failed t={time:.1f}: {_dh_outer}")

    # ── Incremental network stats sampling (every ~30s) ───────────────────────
    try:
        _all_secs = set(_network_stats_section_ids())
        if _all_secs:
            stats.accumulate_network_step(list(_all_secs), time)
    except Exception:
        pass

    # ── Per-intersection density/speed/flow sampling (every ~30s) ─────────
    try:
        stats.accumulate_intersection_step(time)
    except Exception:
        pass

    # ── Queue length snapshot every 60s (all intersections) ──────────────────
    try:
        _write_queue_snapshot(time)
    except Exception:
        pass

    # ── Live status dashboard ─────────────────────────────────────────────────
    global _last_dashboard_t
    if STATUS_DASHBOARD_INTERVAL_S > 0 and (time - _last_dashboard_t) >= STATUS_DASHBOARD_INTERVAL_S:
        _last_dashboard_t = time
        try:
            _print_status_dashboard(time)
        except Exception as _de:
            log_to_file(f"[DASH] dashboard error: {_de}")

    return 0


# =============================================================================
# LIVE STATUS DASHBOARD
# =============================================================================

def _print_status_dashboard(time: float):
    """
    Print a compact, always-readable status table to the Aimsun console.

    Example output (every STATUS_DASHBOARD_INTERVAL_S seconds):

      [DASH] t=  3600s ══════════════════════════════════════════════════════
      [DASH]  Junction   Phase    TSP       GE-debt  Bus   det/ext/ins
      [DASH]  ─────────────────────────────────────────────────────────────
      [DASH]  17249      3 / 6    GE        12.4 s   YES   3 / 2 / 0
      [DASH]  17383      5 / 7    IDLE       0.0 s    NO   1 / 1 / 0
      [DASH]  19363      1 / 3    IDLE       0.0 s    NO   0 / 0 / 0
      [DASH]  ─────────────────────────────────────────────────────────────
      [DASH]  Active TSP: 17249 (GE, 12.4 s debt)   Corridor wave: OFF
      [DASH] ══════════════════════════════════════════════════════════════
    """
    if STATUS_DASHBOARD_INTERVAL_S <= 0:
        return
    if not controllers:
        return

    _W  = 66     # total table width
    _SEP  = "─" * _W
    _DSEP = "═" * _W

    hh = int(time // 3600)
    mm = int((time % 3600) // 60)
    ss = int(time % 60)
    t_str = f"{hh:02d}:{mm:02d}:{ss:02d}"

    lines = []
    lines.append(f"[DASH] t={t_str}  " + _DSEP[len(t_str)+8:])
    lines.append(f"[DASH]  {'Junction':<10} {'Phase':<8} {'TSP':<10} {'Debt':>7}  {'Bus':<5} {'det/ext/ins':>11}")
    lines.append(f"[DASH]  " + _SEP)

    active_tsp  = []
    wave_active = any(getattr(c, '_wave_active', False)
                      for coord in corridor_coordinators
                      for c in [coord])

    for iid, ctrl in controllers.items():
        # ── Phase info ──────────────────────────────────────────────────
        try:
            cur_ph  = ECIGetCurrentPhase(ctrl.node_id)
            n_ph    = len(ctrl.phase_list) if ctrl.phase_list else "?"
            ph_str  = f"{cur_ph} / {n_ph}"
        except Exception:
            ph_str  = "?"

        # ── TSP flag ────────────────────────────────────────────────────
        flag = getattr(ctrl, 'flag', 0)
        if flag == 1:
            tsp_str = "GE"
        elif flag == 2:
            tsp_str = "INSERTION"
        else:
            # Check GB sub-controller state too
            gb = getattr(ctrl, 'gb', None)
            gb_state = getattr(gb, 'state', None) if gb else None
            if gb_state and gb_state != "IDLE":
                tsp_str = f"GB:{gb_state}"
            else:
                tsp_str = "IDLE"

        # ── GE debt ─────────────────────────────────────────────────────
        debt   = getattr(ctrl, '_ge_debt_s', 0.0)
        debt_s = f"{debt:5.1f} s" if debt > 0.1 else "  0.0 s"

        # ── Bus presence ────────────────────────────────────────────────
        try:
            bus_here = any(ctrl.BusPresence[0] > 0)
        except Exception:
            bus_here = False
        # Also check last detected bus (non -1 and recent)
        if not bus_here:
            bus_here = getattr(ctrl, 'last_detected_bus_id', -1) != -1

        bus_str = "YES" if bus_here else " NO"

        # ── TSP event counts from stats ──────────────────────────────────
        _si = getattr(stats, '_inter', {}).get(iid, {})
        n_det = _si.get('n_detections', 0)
        n_ext = _si.get('n_extensions',  0)
        n_ins = _si.get('n_insertions',  0)
        ev_str = f"{n_det} / {n_ext} / {n_ins}"

        lines.append(
            f"[DASH]  {iid:<10} {ph_str:<8} {tsp_str:<10} {debt_s:>7}  {bus_str:<5} {ev_str:>11}"
        )

        if tsp_str != "IDLE":
            active_tsp.append(f"{iid} ({tsp_str}, {debt:.1f}s debt)")

    lines.append(f"[DASH]  " + _SEP)

    # ── Summary line ─────────────────────────────────────────────────────────
    if active_tsp:
        tsp_summary = "Active TSP: " + ", ".join(active_tsp)
    else:
        tsp_summary = "Active TSP: none"

    wave_str = "ON" if wave_active else "OFF"
    lines.append(f"[DASH]  {tsp_summary:<42}  Corridor wave: {wave_str}")
    lines.append(f"[DASH] " + _DSEP)

    for ln in lines:
        AKIPrintString(ln)
        try:
            with open(LOG_FILE, "a", encoding="utf-8") as _lf:
                _lf.write(ln + "\n")
        except Exception:
            pass


# =============================================================================
# AIMSUN CANVAS OVERLAY — creates GKAnnotation objects in the network view
# =============================================================================

def _write_overlay_script(valid_feats: list) -> str:
    """
    Write a standalone Aimsun GUI Python script that creates GKPolyline circle
    markers for every detection point.  Returns the script path.

    Run it from Aimsun Next: Tools > Run Script  (or Scripts > Run Script File)
    """
    import json as _json

    script_path = _DET_GEOJSON.replace(".geojson", "_overlay_script.py")

    # Embed the coordinates directly so the script is self-contained
    pts_data = [
        {
            "x": float(f["geometry"]["coordinates"][0]),
            "y": float(f["geometry"]["coordinates"][1]),
            "label": (
                f"[{f['properties'].get('tier','?')}] "
                f"Bus {f['properties'].get('veh_id','?')} "
                f"jct {f['properties'].get('junction_id','?')} "
                f"t={f['properties'].get('sim_time_s','?')}s"
            ),
        }
        for f in valid_feats
    ]

    script = f'''\
"""
TSP Bus Detection Overlay Script
Generated automatically by intersection_controller.py

Run from Aimsun Next:  Tools > Run Script  (select this file)

Creates {len(pts_data)} GKPolyline circle markers in layer "TSP Bus Detections".
"""
import math
from PyANGKernel import GKSystem

CIRCLE_R = 8.0    # marker radius in model units (metres)
CIRCLE_N = 16     # polygon segments
LAYER_NAME = "TSP Bus Detections"

PTS = {_json.dumps(pts_data, indent=2)}


def _make_circle_pts(cx, cy):
    coords = []
    for k in range(CIRCLE_N + 1):
        angle = 2.0 * math.pi * k / CIRCLE_N
        coords.append((cx + CIRCLE_R * math.cos(angle),
                       cy + CIRCLE_R * math.sin(angle), 0.0))
    return coords


def _clear_existing_markers(model, gk_types):
    """
    Delete all marker objects whose name starts with a TSP marker prefix.

    Runs up to 3 sweep passes: deleting while iterating can invalidate the
    catalog snapshot, so a second/third pass catches anything missed.
    Uses catalog.remove() first (confirmed working in Aimsun Next 26).
    """
    _PREFIXES = ("[BUS]", "[WAVE]", "[SEC]", "[DET]", "[IC-detect]", "[NORMAL-detect]")
    if model is None:
        return 0
    if not isinstance(gk_types, (list, tuple)):
        gk_types = [gk_types]
    catalog = model.getCatalog()
    if catalog is None:
        return 0

    def _name_of(obj):
        for fn in ("getName", "getExternalName", "getLabel"):
            try:
                v = getattr(obj, fn)() or ""
                if v:
                    return v
            except Exception:
                pass
        return ""

    def _delete_one(obj):
        # catalog.remove() confirmed working in Aimsun Next 26; try others as
        # fallbacks for older/newer versions.
        for _fn in (
            lambda o: catalog.remove(o),
            lambda o: o.remove(),
            lambda o: catalog.removeObject(o),
            lambda o: catalog.unmanageObject(o),
            lambda o: model.remove(o),
            lambda o: model.deleteObject(o),
            lambda o: model.deleteObjectForever(o),
        ):
            try:
                _fn(obj)
                return True
            except AttributeError:
                pass
            except Exception:
                pass
        return False

    total_del = 0
    for _pass in range(3):   # up to 3 passes to catch catalog-iterator misses
        to_del = []
        for gk_type in gk_types:
            if gk_type is None:
                continue
            try:
                objs = catalog.getObjectsByType(gk_type)
            except Exception:
                continue
            if not objs:
                continue
            # Snapshot into a plain list immediately before any deletion
            obj_list = list(objs.values()) if isinstance(objs, dict) else list(objs)
            for obj in obj_list:
                if any(_name_of(obj).startswith(p) for p in _PREFIXES):
                    to_del.append(obj)

        if not to_del:
            break   # nothing left — done

        n_this_pass = sum(1 for o in to_del if _delete_one(o))
        total_del += n_this_pass
        if n_this_pass == 0:
            break   # deletion failing — don't loop

    return total_del


def run():
    model = GKSystem.getSystem().getActiveModel()
    if model is None:
        print("[overlay] ERROR: no active model")
        return

    pl_type = model.getType("GKPolyline")
    if pl_type is None:
        print("[overlay] ERROR: GKPolyline type not found in this model")
        return

    # Remove markers from any previous run before drawing new ones
    _clear_existing_markers(model, pl_type)

    # Find or create the layer
    # Aimsun Next 26: newObject(type) — one arg only; getCreateFolderForType(str)
    layer = None
    try:
        catalog = model.getCatalog()
        lyr_type = model.getType("GKLayer")
        if catalog and lyr_type:
            for lyr in (catalog.getObjectsByType(lyr_type) or []):
                if getattr(lyr, "getName", lambda: "")() == LAYER_NAME:
                    layer = lyr
                    break
        if layer is None and lyr_type:
            layer = model.newObject(lyr_type)
            if layer:
                for fn in ("setName", "setExternalName"):
                    try:
                        getattr(layer, fn)(LAYER_NAME); break
                    except Exception:
                        pass
                try:
                    folder = model.getCreateFolderForType("GKLayer")
                    model.addObjectToFolder(layer, folder)
                except Exception:
                    pass
    except Exception as e:
        print(f"[overlay] Layer setup failed: {{e}} — continuing without layer")

    # Get creation folder for polylines (string arg in Aimsun Next 26)
    pl_folder = None
    try:
        pl_folder = model.getCreateFolderForType("GKPolyline")
    except Exception:
        pass

    n_ok = n_fail = 0
    for pt in PTS:
        try:
            obj = model.newObject(pl_type)
            if obj is None:
                raise RuntimeError("newObject returned None")
            if pl_folder is not None:
                try:
                    model.addObjectToFolder(obj, pl_folder)
                except Exception:
                    pass

            coords = _make_circle_pts(pt["x"], pt["y"])

            set_ok = False
            if not set_ok:
                try:
                    obj.setPoints(coords); set_ok = True
                except Exception:
                    pass
            if not set_ok:
                try:
                    from PyANGKernel import GKPoint
                    gkpts = []
                    for cx, cy, cz in coords:
                        p = GKPoint(); p.x = cx; p.y = cy; p.z = cz
                        gkpts.append(p)
                    obj.setPoints(gkpts); set_ok = True
                except Exception:
                    pass
            if not set_ok:
                try:
                    for cx, cy, cz in coords:
                        obj.addPoint(cx, cy, cz)
                    set_ok = True
                except Exception:
                    pass

            for fn in ("setName", "setExternalName", "setLabel"):
                try:
                    getattr(obj, fn)(pt["label"]); break
                except Exception:
                    pass

            # Set bright red colour so circles are visible
            try:
                from PyANGKernel import GKColor
                obj.setColor(GKColor(220, 30, 30))
            except Exception:
                try:
                    from PyQt5.QtGui import QColor
                    obj.setColor(QColor(220, 30, 30))
                except Exception:
                    pass

            if layer:
                for fn in ("setLayer", "addToLayer"):
                    try:
                        getattr(obj, fn)(layer); break
                    except Exception:
                        pass

            n_ok += 1
        except Exception as e:
            n_fail += 1
            if n_fail == 1:
                print(f"[overlay] First marker failed: {{e}}")

    # Refresh the view
    try:
        GKSystem.getSystem().getGUI().getActiveView().update()
    except Exception:
        pass

    print(f"[overlay] Done: {{n_ok}} circles created, {{n_fail}} failed.")
    print(f"[overlay] Zoom out on the network canvas to see red circles.")
    print(f"[overlay] Or: Catalog panel > GEO objects to find them by name.")


run()
'''

    with open(script_path, "w", encoding="utf-8") as _sf:
        _sf.write(script)
    return script_path


def _overlay_detections_on_aimsun_map():
    """
    After simulation:
    1. Writes a standalone Aimsun GUI script that creates GKPolyline circle
       markers — run it via Tools > Run Script for instant canvas overlay.
    2. Attempts to create the markers directly (AAPI context — may be read-only).

    Uses PyANGKernel (bundled with Aimsun Next).  Any API mismatch is caught
    and logged — the function never raises.
    """
    if not OVERLAY_DETECTIONS_ON_MAP:
        return
    if not MARK_DETECTION_POINTS:
        return
    if not ALLOW_MODEL_CATALOG_WRITES:
        log_to_file(
            "[MAP] Catalog writes disabled (ALLOW_MODEL_CATALOG_WRITES=False). "
            "Skipping in-model marker creation/deletion; GeoJSON/script outputs only.",
            force=True,
        )
        return

    valid_feats = [
        f for f in _geojson_features
        if not (f["geometry"]["coordinates"][0] == 0.0
                and f["geometry"]["coordinates"][1] == 0.0)
    ]
    if not valid_feats:
        log_to_file("[MAP] No valid-coordinate detections — canvas overlay skipped", force=True)
        return

    # Always write the standalone script — works even if the direct AAPI path fails.
    try:
        _script_path = _write_overlay_script(valid_feats)
        log_to_file(
            f"[MAP] Overlay script written: {_script_path}\n"
            f"      → To show circles in Aimsun: Tools > Run Script > select that file",
            force=True
        )
    except Exception as _se:
        log_to_file(f"[MAP] Overlay script write failed: {_se}", force=True)

    try:
        from PyANGKernel import GKSystem
    except ImportError:
        log_to_file(
            "[MAP] PyANGKernel not available — use the overlay script above.",
            force=True
        )
        return

    try:
        model = GKSystem.getSystem().getActiveModel()
        if model is None:
            log_to_file("[MAP] getActiveModel() returned None — canvas overlay skipped", force=True)
            return
    except Exception as _ge:
        log_to_file(f"[MAP] Could not access Aimsun model: {_ge}", force=True)
        return

    try:
        # Try type names used across different Aimsun Next versions.
        # getType() returns None for unknown names — no exception raised.
        _ANN_NAMES = [
            "GKAnnotation", "GKNote", "GKLabel",
            "GKMapLabel", "GKTextAnnotation", "GKAnnotation3D",
        ]
        ann_type = None
        _ann_name_used = ""
        for _tn in _ANN_NAMES:
            _t = model.getType(_tn)
            if _t is not None:
                ann_type = _t
                _ann_name_used = _tn
                break

        _use_polyline = False
        if ann_type is None:
            # GKAnnotation not available — try GKPolyline circle markers instead
            _pl_type = model.getType("GKPolyline")
            if _pl_type is None:
                # No usable type found — log available types for diagnostics
                _PROBE = [
                    "GKNode", "GKSection", "GKDetector", "GKCentroid",
                    "GKAnnotation", "GKNote", "GKLabel", "GKMapLabel",
                    "GKPolyline", "GKPolygon", "GKBitmap", "GKObject",
                ]
                _found = [n for n in _PROBE if model.getType(n) is not None]
                log_to_file(
                    f"[MAP] No overlay type found (tried {_ANN_NAMES} + GKPolyline). "
                    f"Types present in this model: {_found}. "
                    f"Open the GeoJSON manually: File > Import > {_DET_GEOJSON}",
                    force=True
                )
                return
            _use_polyline = True
            log_to_file("[MAP] Using GKPolyline circles as detection markers", force=True)
        else:
            log_to_file(f"[MAP] Using annotation type '{_ann_name_used}'", force=True)

        # ── Clear markers from any previous simulation run ────────────────────
        _MARKER_PREFIXES = (
            "[BUS]", "[WAVE]", "[SEC]", "[DET]",
            "[IC-detect]", "[NORMAL-detect]",
        )
        _clear_type = _pl_type if _use_polyline else ann_type
        try:
            _catalog = model.getCatalog()
            _all_objs = _catalog.getObjectsByType(_clear_type) if _catalog else None
            _obj_list = (
                list(_all_objs.values()) if isinstance(_all_objs, dict)
                else list(_all_objs or [])
            )
            _n_cleared = 0
            for _old in _obj_list:
                _name = ""
                for _fn in ("getName", "getExternalName"):
                    try:
                        _name = getattr(_old, _fn)() or ""
                        if _name:
                            break
                    except Exception:
                        pass
                if any(_name.startswith(_p) for _p in _MARKER_PREFIXES):
                    try:
                        model.deleteObject(_old)
                        _n_cleared += 1
                    except Exception:
                        pass
            if _n_cleared:
                log_to_file(f"[MAP] Cleared {_n_cleared} marker(s) from previous run", force=True)
        except Exception as _ce:
            log_to_file(f"[MAP] Marker clear failed (non-fatal): {_ce}", force=True)


        # ── Tier → ASCII prefix (emoji may not render in all Aimsun builds) ─
        def _pfx(tier: str) -> str:
            if "IC-detect" in tier or "PT-coord" in tier:
                return "[BUS]"
            if "coord-prearm" in tier:
                return "[WAVE]"
            if "sec" in tier:
                return "[SEC]"
            return "[DET]"

        # ── Object creation helper (Aimsun Next 26 API) ───────────────────────
        # Confirmed signatures:
        #   model.newObject(gktype)                 — one arg, no parent/folder
        #   model.getCreateFolderForType(type_name) — takes str, not GKType
        #   model.addObjectToFolder(obj, folder)    — add to folder after creation
        def _create_obj(gktype, type_name: str):
            """Create and return a new model object, placed in its default folder."""
            obj = model.newObject(gktype)
            if obj is None:
                raise RuntimeError("model.newObject() returned None")
            # Place in the type's default creation folder
            try:
                _folder = model.getCreateFolderForType(type_name)
                model.addObjectToFolder(obj, _folder)
            except Exception:
                pass
            return obj

        # ── Try to find or create a dedicated layer ───────────────────────────
        _layer = None
        _LAYER_NAME = "TSP Bus Detections"
        try:
            # Iterate layers to find an existing one with this name
            _catalog = model.getCatalog()
            if _catalog is not None:
                for _lyr in (_catalog.getObjectsByType(model.getType("GKLayer")) or []):
                    if getattr(_lyr, 'getName', lambda: '')() == _LAYER_NAME:
                        _layer = _lyr
                        break
            # Create new layer if not found
            if _layer is None:
                _lyr_type = model.getType("GKLayer")
                if _lyr_type is not None:
                    try:
                        _layer = _create_obj(_lyr_type, "GKLayer")
                    except Exception:
                        _layer = None
                    for _set_fn in ("setName", "setExternalName"):
                        try:
                            getattr(_layer, _set_fn)(_LAYER_NAME)
                            break
                        except Exception:
                            pass
        except Exception:
            _layer = None   # proceed without a custom layer

        # ── Create one marker per detection ───────────────────────────────────
        import math as _math
        n_ok   = 0
        n_fail = 0

        # GKPolyline circle parameters
        _CIRCLE_R  = 8.0   # radius in model units (metres)
        _CIRCLE_N  = 16    # number of segments

        for feat in valid_feats:
            x     = float(feat["geometry"]["coordinates"][0])
            y     = float(feat["geometry"]["coordinates"][1])
            props = feat["properties"]
            tier  = str(props.get("tier", ""))
            vid   = props.get("veh_id", "?")
            jid   = props.get("junction_id", "?")
            t_s   = props.get("sim_time_s", "?")
            label = f"{_pfx(tier)} Bus {vid}  jct {jid}  t={t_s}s  [{tier}]"

            try:
                if _use_polyline:
                    # ── Draw a small circle using GKPolyline ──────────────────
                    # Build circle coordinates as plain Python tuples — avoids
                    # depending on GKPoints3D / GKPoint which vary across builds.
                    _coords = []
                    for _k in range(_CIRCLE_N + 1):   # +1 closes the circle
                        _angle = 2.0 * _math.pi * _k / _CIRCLE_N
                        _coords.append((
                            x + _CIRCLE_R * _math.cos(_angle),
                            y + _CIRCLE_R * _math.sin(_angle),
                            0.0
                        ))

                    obj = _create_obj(_pl_type, "GKPolyline")

                    # Try every known point-setting API in order of preference.
                    _pts_set = False

                    # Option A: setPoints with list of tuples (simplest)
                    if not _pts_set:
                        try:
                            obj.setPoints(_coords)
                            _pts_set = True
                        except Exception:
                            pass

                    # Option B: GKPoint objects in a plain list
                    if not _pts_set:
                        try:
                            from PyANGKernel import GKPoint as _GKP
                            _gk_pts = []
                            for _cx, _cy, _cz in _coords:
                                _p = _GKP(); _p.x = _cx; _p.y = _cy; _p.z = _cz
                                _gk_pts.append(_p)
                            obj.setPoints(_gk_pts)
                            _pts_set = True
                        except Exception:
                            pass

                    # Option C: addPoint one at a time (tuple variant)
                    if not _pts_set:
                        try:
                            for _cx, _cy, _cz in _coords:
                                obj.addPoint(_cx, _cy, _cz)
                            _pts_set = True
                        except Exception:
                            pass

                    # Option D: addPoint with GKPoint
                    if not _pts_set:
                        try:
                            from PyANGKernel import GKPoint as _GKP
                            for _cx, _cy, _cz in _coords:
                                _p = _GKP(); _p.x = _cx; _p.y = _cy; _p.z = _cz
                                obj.addPoint(_p)
                            _pts_set = True
                        except Exception:
                            pass

                    if not _pts_set:
                        raise RuntimeError("No working setPoints/addPoint API found for GKPolyline")

                    for _fn in ("setName", "setExternalName", "setLabel"):
                        try:
                            getattr(obj, _fn)(label)
                            break
                        except Exception:
                            pass
                else:
                    # ── Create annotation (GKAnnotation or equivalent) ────────
                    obj = _create_obj(ann_type, _ann_name_used)

                    _pos_set = False
                    try:
                        from PyANGKernel import GKPoint
                        _pt = GKPoint()
                        _pt.x = x; _pt.y = y; _pt.z = 0.0
                        obj.setPosition(_pt)
                        _pos_set = True
                    except Exception:
                        pass

                    if not _pos_set:
                        try:
                            obj.setPoints([(x, y, 0.0)])
                            _pos_set = True
                        except Exception:
                            pass

                    if not _pos_set:
                        try:
                            obj.setPosition((x, y, 0.0))
                        except Exception:
                            pass

                    for _fn in ("setLabel", "setText", "setName", "setExternalName"):
                        try:
                            getattr(obj, _fn)(label)
                            break
                        except Exception:
                            pass

                # ── Set colour (bright red so circles are visible) ────────────
                try:
                    from PyANGKernel import GKColor as _GKC
                    obj.setColor(_GKC(220, 30, 30))
                except Exception:
                    pass
                try:
                    from PyQt5.QtGui import QColor as _QC
                    obj.setColor(_QC(220, 30, 30))
                except Exception:
                    pass

                # ── Assign to layer (both paths) ──────────────────────────────
                if _layer is not None:
                    for _fn in ("setLayer", "addToLayer"):
                        try:
                            getattr(obj, _fn)(_layer)
                            break
                        except Exception:
                            pass

                n_ok += 1

            except Exception as _obj_e:
                n_fail += 1
                if n_fail == 1:
                    log_to_file(f"[MAP] Marker creation failed: {_obj_e}", force=True)
                if n_fail >= 2:
                    log_to_file("[MAP] Second failure identical — stopping canvas overlay", force=True)
                    break

        # ── Trigger a view refresh so circles appear immediately ──────────────
        try:
            GKSystem.getSystem().getGUI().getActiveView().update()
        except Exception:
            pass

        _marker_kind = "circle(s)" if _use_polyline else "annotation(s)"
        log_to_file(
            f"[MAP] Canvas overlay complete: {n_ok} {_marker_kind} created "
            f"({n_fail} failed) from {len(valid_feats)} detection points.\n"
            f"      → In Aimsun: zoom out on the network canvas to see red circles.\n"
            f"      → Or open the Catalog panel and look under GEO objects.",
            force=True
        )

    except Exception as _top_e:
        import traceback
        log_to_file(
            f"[MAP] Canvas overlay error: {_top_e}\n{traceback.format_exc()}",
            force=True
        )


def AAPIFinish():
    log_to_file("===== AAPIFinish =====")

    # ── Aggregate corridor coordinator pre-arm stats ───────────────────────────
    try:
        _combined_prearm = {"fired": 0, "success": 0, "missed": 0,
                             "expired": 0, "discarded": 0,
                             "late_success": 0, "late_success_delay_s": 0.0}
        for _coord in corridor_coordinators:
            _ps = getattr(_coord, '_prearm_stats', {})
            for _k in _combined_prearm:
                if _k == "late_success_delay_s":
                    _combined_prearm[_k] += float(_ps.get(_k, 0.0))
                else:
                    _combined_prearm[_k] += int(_ps.get(_k, 0))
        stats.record_prearm_stats(_combined_prearm)
        _fired = int(_combined_prearm.get("fired", 0) or 0)
        _succ = int(_combined_prearm.get("success", 0) or 0)
        _succ_pct = (100.0 * _succ / _fired) if _fired > 0 else 0.0
        log_to_file(f"[FINISH] prearm stats: {_combined_prearm}", force=True)
        log_to_file(
            f"[FINISH] prearm success rate: {_succ}/{_fired} = {_succ_pct:.1f}%",
            force=True,
        )
    except Exception as _pe:
        log_to_file(f"[FINISH] prearm stats error: {_pe}", force=True)

    # ── Collect network-level section statistics ───────────────────────────────
    try:
        # Use ALL network sections for global stats — this matches what Aimsun's
        # Statistics panel shows (network-wide density/flow/speed).
        _all_secs: set = set()
        try:
            _n_secs = int(AKIInfNetNbSectionsANG())
            for _si in range(_n_secs):
                _sid = int(AKIInfNetGetSectionANGId(_si))
                if _sid > 0:
                    _all_secs.add(_sid)
            log_to_file(
                f"[FINISH] network sections from AKIInfNet: {len(_all_secs)}",
                force=True,
            )
        except Exception as _net_e:
            log_to_file(
                f"[FINISH] AKIInfNetNbSectionsANG fallback: {_net_e}", force=True
            )
            # Fallback to approach sections from controllers + stats records
            for _ctrl in controllers.values():
                for _sec in getattr(_ctrl, 'incoming_sections', []):
                    if _sec and _sec > 0:
                        _all_secs.add(_sec)
            for _iid_data in getattr(stats, '_inter', {}).values():
                for _sec in _iid_data.get('main_sections', []):
                    if _sec and isinstance(_sec, int) and _sec > 0:
                        _all_secs.add(_sec)
                for _sec in _iid_data.get('side_sections', []):
                    if _sec and isinstance(_sec, int) and _sec > 0:
                        _all_secs.add(_sec)
        stats.collect_network_stats_at_finish(list(_all_secs))
        stats.collect_extra_section_stats(list(_all_secs))
        log_to_file(f"[FINISH] network stats collected ({len(_all_secs)} sections)", force=True)
        try:
            _net_flow = int(getattr(stats, '_net_total_flow_veh', 0) or 0)
            _net_den = float(getattr(stats, '_net_avg_density_vkm', 0.0) or 0.0)
            _net_spd = float(getattr(stats, '_net_avg_speed_kmh', 0.0) or 0.0)
            _net_dbg = dict(getattr(stats, '_net_debug', {}) or {})
            log_to_file(
                f"[FINISH] network kpis: flow={_net_flow} veh "
                f"density={_net_den:.4f} veh/km speed={_net_spd:.3f} km/h",
                force=True,
            )
            if _net_dbg:
                log_to_file(
                    "[FINISH] network debug: "
                    f"source={_net_dbg.get('source')} sim_time_s={_net_dbg.get('sim_time_s')} "
                    f"sections={_net_dbg.get('section_count')} stats_ok={_net_dbg.get('stats_ok_sections')} "
                    f"stats_zero={_net_dbg.get('stats_zero_sections')} snap_ok={_net_dbg.get('snapshot_ok_sections')} "
                    f"snap_with_veh={_net_dbg.get('snapshot_sections_with_vehicles')} "
                    f"snap_zero={_net_dbg.get('snapshot_zero_sections')} "
                    f"missing_len={_net_dbg.get('sections_missing_length')}",
                    force=True,
                )
            if _net_flow <= 0 and _net_den <= 0 and _net_spd <= 0:
                log_to_file(
                    "[FINISH] network kpis are all zero; check section stats API "
                    "availability and section coverage.",
                    force=True,
                )
        except Exception as _nk:
            log_to_file(f"[FINISH] network kpi log error: {_nk}", force=True)
    except Exception as _ne:
        log_to_file(f"[FINISH] network stats error: {_ne}", force=True)


    try:
        stats.print_results()
    except Exception as e:
        import traceback
        log_to_file(f"[FINISH] print_results error (non-fatal): {e}\n{traceback.format_exc()}", force=True)

    try:
        stats.save_results()
        log_to_file("[FINISH] stats saved OK", force=True)
    except Exception as e:
        import traceback
        log_to_file(f"[FINISH] save_results error: {e}\n{traceback.format_exc()}", force=True)

    try:
        # Write phase/timing HTML output
        html_path = os.path.join(LOG_DIR, f"phase_sequence_{_CURRENT_EXPERIMENT}_{timestamp}.html")
        write_phase_sequence_html(stats, html_path)
        log_to_file(f"[FINISH] phase/timing HTML written: {html_path}", force=True)
    except Exception as e:
        log_to_file(f"[FINISH] HTML output error: {e}", force=True)

    try:
        _gk = stats._global_kpis()
        _nat = int(_gk.get('n_tsp_natural_green', 0) or 0)
        _det = int(_gk.get('n_tsp_detections', 0) or 0)
        _nat_pct = (100.0 * _nat / _det) if _det > 0 else 0.0
        log_to_file(
            f"[FINISH] natural_green: {_nat}/{_det} = {_nat_pct:.1f}%",
            force=True,
        )
    except Exception:
        pass

    try:
        _write_run_summary()
        log_to_file(f"[FINISH] run summary written: {_RUN_SUMMARY_TXT}", force=True)
    except Exception as e:
        log_to_file(f"[FINISH] run summary error: {e}", force=True)

    try:
        _write_algorithm_explanation_tex()
        log_to_file(f"[FINISH] algorithm explanation written: {_ALGORITHM_EXPLANATION_TEX}", force=True)
    except Exception as e:
        log_to_file(f"[FINISH] algorithm explanation error: {e}", force=True)
    for controller in controllers.values():
        if CONTROL_MODE == "URTSP":
            log_to_file(controller.get_urtsp_summary())
    # ── Corridor summary ──────────────────────────────────────────────────────
    for coord in corridor_coordinators:
        log_to_file(f"[FINISH] {coord.summary()}")
    # ── Schedule-recovery plot ────────────────────────────────────────────────
    try:
        _plot_schedule_recovery()
    except Exception as _sre:
        log_to_file(f"[FINISH] schedule recovery plot error: {_sre}")

    # ── Flush detection-point GeoJSON ─────────────────────────────────────────
    if MARK_DETECTION_POINTS and _geojson_features:
        try:
            import json
            geojson = {
                "type": "FeatureCollection",
                "features": _geojson_features,
            }
            with open(_DET_GEOJSON, "w", encoding="utf-8") as _gf:
                json.dump(geojson, _gf, indent=2)
            log_to_file(
                f"[MARK] Detection GeoJSON written: {_DET_GEOJSON} "
                f"({len(_geojson_features)} points)"
            )
        except Exception as _ge:
            log_to_file(f"[MARK] GeoJSON write failed: {_ge}")

    # ── Detection-point diagnostics (always shown) ────────────────────────────
    log_to_file(
        f"[MARK DIAG] MARK_DETECTION_POINTS={MARK_DETECTION_POINTS} | "
        f"_mark_calls_total={_mark_calls_total} | "
        f"_mark_calls_written={_mark_calls_written} | "
        f"unique_pairs={len(_marked_detections)} | "
        f"geojson_features={len(_geojson_features)} | "
        f"CSV_path={_DET_CSV} | "
        f"CSV_exists={os.path.isfile(_DET_CSV)}",
        force=True
    )

    # ── Per-junction detection summary ───────────────────────────────────────
    # Shows exactly how many unique buses were detected at each junction, split
    # by tier (IC-detect, track-section, track-zone, focus, coord, etc.).
    # Useful for diagnosing "not seen" gaps in the dashboard.
    try:
        _det_by_jct: dict = {}  # {jct_id: {tier: count}}
        _det_buses_by_jct: dict = {}  # {jct_id: set(veh_id)}
        for (_dj, _dv) in _marked_detections:
            _det_buses_by_jct.setdefault(_dj, set()).add(_dv)
        # Also load tier breakdown from CSV
        if os.path.isfile(_DET_CSV):
            with open(_DET_CSV, "r", newline="", encoding="utf-8") as _df:
                for _dr in csv.DictReader(_df):
                    try:
                        _jid = int(float(_dr.get("junction_id", -1) or -1))
                        _tier = str(_dr.get("tier", "?") or "?")
                        if _jid > 0:
                            _det_by_jct.setdefault(_jid, {})
                            _det_by_jct[_jid][_tier] = _det_by_jct[_jid].get(_tier, 0) + 1
                    except Exception:
                        pass
        _total_det_buses = len(set(v for pairs in _det_buses_by_jct.values() for v in pairs))
        _total_active    = len(_bus_seen_ids)
        log_to_file(
            f"[DET SUMMARY] Active buses tracked: {_total_active} | "
            f"Unique buses detected at ≥1 junction: {_total_det_buses} | "
            f"PT route map: {len(_pt_line_jct_route)} lines / {len(_sec_to_corridor_jct)} sections",
            force=True)
        for _jid in sorted(_det_buses_by_jct.keys()):
            _n_det = len(_det_buses_by_jct[_jid])
            _tiers = _det_by_jct.get(_jid, {})
            _tier_str = " ".join(f"{t}:{n}" for t, n in sorted(_tiers.items()))
            log_to_file(
                f"[DET SUMMARY] jct={_jid}: {_n_det} unique buses detected | {_tier_str}",
                force=True)
        # Junctions with 0 detections
        _zero_jcts = [j for j in controllers if j not in _det_buses_by_jct]
        if _zero_jcts:
            log_to_file(
                f"[DET SUMMARY] Junctions with 0 detections: {sorted(_zero_jcts)}",
                force=True)
    except Exception as _ds_e:
        log_to_file(f"[DET SUMMARY] error building summary: {_ds_e}", force=True)

    # ── NO_INS summary by intersection (counts by reason) ───────────────────
    # Reads harmony-no-ins-local decision rows from the detection CSV and
    # aggregates reason buckets for fast diagnosis of insertion denials.
    try:
        _noins_by_jct: dict = {}
        _noins_total = 0
        if os.path.isfile(_DET_CSV):
            with open(_DET_CSV, "r", newline="", encoding="utf-8") as _nf:
                for _nr in csv.DictReader(_nf):
                    try:
                        _tier = str(_nr.get("tier", "") or "").strip()
                        if _tier != "harmony-no-ins-local":
                            continue
                        _jid = int(float(_nr.get("junction_id", -1) or -1))
                        if _jid <= 0:
                            continue
                        _note = str(_nr.get("prearm_note", "") or "").strip()
                        if not _note:
                            _note = str(_nr.get("note", "") or "").strip()
                        _reason = _note if _note else "unspecified"
                        if "|" in _reason:
                            _reason = _reason.split("|", 1)[0].strip()
                        if _reason.upper().startswith("NO_INS "):
                            _reason = _reason[7:].strip()
                        if not _reason:
                            _reason = "unspecified"
                        _noins_by_jct.setdefault(_jid, collections.Counter())[_reason] += 1
                        _noins_total += 1
                    except Exception:
                        continue

        if _noins_total > 0:
            with open(_NO_INS_SUMMARY_CSV, "w", newline="", encoding="utf-8") as _nof:
                _nw = csv.writer(_nof)
                _nw.writerow(["junction_id", "reason", "count"])
                for _jid in sorted(_noins_by_jct.keys()):
                    for _reason, _count in _noins_by_jct[_jid].most_common():
                        _nw.writerow([_jid, _reason, _count])

            log_to_file(
                f"[NO_INS SUMMARY] total_no_ins={_noins_total} | "
                f"junctions={len(_noins_by_jct)} | csv={_NO_INS_SUMMARY_CSV}",
                force=True,
            )
            for _jid in sorted(_noins_by_jct.keys()):
                _items = _noins_by_jct[_jid].most_common()
                _reason_txt = " | ".join(f"{_r}:{_c}" for _r, _c in _items)
                log_to_file(
                    f"[NO_INS SUMMARY] jct={_jid} total={sum(_noins_by_jct[_jid].values())} "
                    f"reasons={_reason_txt}",
                    force=True,
                )
        else:
            log_to_file(
                "[NO_INS SUMMARY] no harmony-no-ins-local rows in detection CSV",
                force=True,
            )
    except Exception as _nis_e:
        log_to_file(f"[NO_INS SUMMARY] error building summary: {_nis_e}", force=True)

    # ── Reward decision diagnostics summary ─────────────────────────────────
    # Aggregates per-intersection counters from _run_reward_tsp_evaluate so
    # we can explain why reward modes underperform relative to NO_TSP.
    try:
        if CONTROL_MODE in ("REWARD_TSP", "DRL_DENSITY", "MPC_TSP"):
            _diag_total = collections.Counter()
            _diag_rows = []
            for _jid, _ctrl in controllers.items():
                _d = getattr(_ctrl, '_reward_diag', None)
                if not _d:
                    continue
                _diag_total.update(_d)
                _eval = int(_d.get('eval', 0))
                _na = int(_d.get('no_action', 0))
                _ge = int(_d.get('action_ge', 0))
                _ins = int(_d.get('action_ins', 0))
                _diag_rows.append((_jid, _eval, _na, _ge, _ins, _d))

            if _diag_rows:
                log_to_file(
                    "[FINISH] reward diag total: "
                    f"eval={int(_diag_total.get('eval', 0))} "
                    f"no_action={int(_diag_total.get('no_action', 0))} "
                    f"ge={int(_diag_total.get('action_ge', 0))} "
                    f"ins={int(_diag_total.get('action_ins', 0))} "
                    f"noact_ge_inapp={int(_diag_total.get('no_action_ge_inapplicable', 0))} "
                    f"noact_ins_guard={int(_diag_total.get('no_action_ins_guard_block', 0))} "
                    f"noact_no_pos={int(_diag_total.get('no_action_no_positive_action', 0))} "
                    f"noact_pos_alt={int(_diag_total.get('no_action_positive_alt_not_chosen', 0))} "
                    f"ge_cap_skip={int(_diag_total.get('ge_skipped_cap', 0))}",
                    force=True,
                )

                _diag_rows.sort(key=lambda _x: _x[2], reverse=True)
                for _jid, _eval, _na, _ge, _ins, _d in _diag_rows[:12]:
                    _na_pct = (100.0 * _na / _eval) if _eval > 0 else 0.0
                    log_to_file(
                        f"[FINISH] reward diag jct={_jid}: "
                        f"eval={_eval} no_action={_na}({_na_pct:.1f}%) "
                        f"ge={_ge} ins={_ins} "
                        f"ge_inapp={int(_d.get('no_action_ge_inapplicable', 0))} "
                        f"ins_guard={int(_d.get('no_action_ins_guard_block', 0))} "
                        f"no_pos={int(_d.get('no_action_no_positive_action', 0))} "
                        f"pos_alt={int(_d.get('no_action_positive_alt_not_chosen', 0))} "
                        f"ge_cap_skip={int(_d.get('ge_skipped_cap', 0))}",
                        force=True,
                    )
            else:
                log_to_file("[FINISH] reward diag: no controller counters found", force=True)
    except Exception as _rdiag_e:
        log_to_file(f"[FINISH] reward diag summary error: {_rdiag_e}", force=True)

    # ── Bus-tracking diagnostics (always shown) ─────────────────────────────
    try:
        _bt_exists = os.path.isfile(_BUS_TRACKING_CSV)
        _bt_rows = 0
        _bt_uniq_bus = set()
        _bt_uniq_jct = set()
        _bt_events = {}
        if _bt_exists:
            with open(_BUS_TRACKING_CSV, "r", newline="", encoding="utf-8") as _bf:
                _br = csv.DictReader(_bf)
                for _r in _br:
                    _bt_rows += 1
                    try:
                        _v = int(float(_r.get("veh_id", 0) or 0))
                        if _v > 0:
                            _bt_uniq_bus.add(_v)
                    except Exception:
                        pass
                    try:
                        _j = int(float(_r.get("nearest_jct", -1) or -1))
                        if _j > 0:
                            _bt_uniq_jct.add(_j)
                    except Exception:
                        pass
                    _ev = str(_r.get("event", "track") or "track")
                    _bt_events[_ev] = int(_bt_events.get(_ev, 0)) + 1
        _ev_text = ", ".join(
            f"{_k}:{_bt_events[_k]}" for _k in sorted(_bt_events.keys())
        ) if _bt_events else "none"
        log_to_file(
            f"[BUS_TRACK DIAG] TRACK_BUS_POSITIONS={TRACK_BUS_POSITIONS} | "
            f"CSV_path={_BUS_TRACKING_CSV} | exists={_bt_exists} | "
            f"rows={_bt_rows} | unique_buses={len(_bt_uniq_bus)} | "
            f"unique_jcts={len(_bt_uniq_jct)} | events={_ev_text}",
            force=True,
        )
    except Exception as _bt_e:
        log_to_file(f"[BUS_TRACK DIAG] error: {_bt_e}", force=True)

    # ── Presence-snapshot diagnostics (always shown) ───────────────────────
    try:
        _ps_exists = os.path.isfile(_PRESENCE_SNAPSHOT_CSV)
        _ps_rows = 0
        _ps_uniq_bus = set()
        _ps_uniq_jct = set()
        _ps_scope = {}
        if _ps_exists:
            with open(_PRESENCE_SNAPSHOT_CSV, "r", newline="", encoding="utf-8") as _pf:
                _pr = csv.DictReader(_pf)
                for _r in _pr:
                    _ps_rows += 1
                    try:
                        _v = int(float(_r.get("veh_id", 0) or 0))
                        if _v > 0:
                            _ps_uniq_bus.add(_v)
                    except Exception:
                        pass
                    try:
                        _j = int(float(_r.get("junction_id", -1) or -1))
                        if _j > 0:
                            _ps_uniq_jct.add(_j)
                    except Exception:
                        pass
                    _sc = str(_r.get("scope", "") or "")
                    if _sc:
                        _ps_scope[_sc] = int(_ps_scope.get(_sc, 0)) + 1
        _scope_text = ", ".join(
            f"{_k}:{_ps_scope[_k]}" for _k in sorted(_ps_scope.keys())
        ) if _ps_scope else "none"
        log_to_file(
            f"[PRESENCE_SNAPSHOT DIAG] CSV_path={_PRESENCE_SNAPSHOT_CSV} | "
            f"exists={_ps_exists} | rows={_ps_rows} | "
            f"unique_buses={len(_ps_uniq_bus)} | unique_jcts={len(_ps_uniq_jct)} | "
            f"scope={_scope_text}",
            force=True,
        )
    except Exception as _ps_e:
        log_to_file(f"[PRESENCE_SNAPSHOT DIAG] error: {_ps_e}", force=True)

    # ── Corridor wave/coordinator event CSV ──────────────────────────────────
    # ── Global bus focus history CSV ──────────────────────────────────────────
    # Flush any still-active focus so the final event is not lost.
    if _focus_bus_id > 0:
        try:
            _t_now = float(AKIGetCurrentSimulationTime())
        except Exception:
            _t_now = float(AKIGetSimulationTime()) if 'AKIGetSimulationTime' in globals() else 0.0
        _release_focus(_t_now, "finish_flush")

    if _focus_history:
        try:

            _focus_csv = _DET_CSV.replace("detection_points_", "focus_history_")
            with open(_focus_csv, "w", newline="", encoding="utf-8") as _ff:
                _fw = csv.writer(_ff)
                _fw.writerow(["start_t", "end_t", "veh_id", "jct_id",
                              "outcome", "held_s"])
                for _fh in _focus_history:
                    _fw.writerow([
                        f"{_fh[0]:.1f}", f"{_fh[1]:.1f}",
                        _fh[2], _fh[3], _fh[4],
                        f"{_fh[1] - _fh[0]:.1f}",
                    ])
            log_to_file(
                f"[BUS_FOCUS] history CSV written: {_focus_csv} "
                f"({len(_focus_history)} events)", force=True)
        except Exception as _fe:
            log_to_file(f"[BUS_FOCUS] history CSV error: {_fe}", force=True)

    if _wave_events:
        try:
            with open(_WAVE_EVENTS_CSV, "w", newline="", encoding="utf-8") as _wf:
                _base_fields = [
                    "sim_time_s", "group", "event",
                    "source_jct", "target_jct", "veh_id",
                    "eta_s", "lead_s", "note",
                ]
                _extra_fields = sorted({
                    _k for _row in _wave_events for _k in _row.keys()
                    if _k not in _base_fields
                })
                _w = csv.DictWriter(_wf, fieldnames=_base_fields + _extra_fields)
                _w.writeheader()
                _w.writerows(_wave_events)
            log_to_file(
                f"[FINISH] corridor wave events written: {_WAVE_EVENTS_CSV} "
                f"({len(_wave_events)} rows)",
                force=True,
            )
        except Exception as _we:
            log_to_file(f"[FINISH] corridor wave event write error: {_we}", force=True)

    # ── Coordination diagnostics plot (shockwave/Kalman inputs by junction) ──
    try:
        import importlib
        import plot_coord_diagnostics as _pcd
        importlib.reload(_pcd)
        _pcd.run(wave_csv=_WAVE_EVENTS_CSV)
        log_to_file("[COORD DIAG] Shockwave/Kalman diagnostics plot written", force=True)
    except Exception as _cde:
        import traceback
        log_to_file(f"[COORD DIAG] Plot failed: {_cde}\n{traceback.format_exc()}", force=True)

    # Dump the bus_sg and tsp_mode of every GB controller so we can see if
    # detection is even plausible
    for _iid, _ctrl in controllers.items():
        _gb = getattr(_ctrl, 'gb', None)
        if _gb is not None:
            log_to_file(
                f"[MARK DIAG] jct={_iid} "
                f"bus_sg={getattr(_gb,'bus_sg',None)} "
                f"tsp_mode={getattr(_gb,'tsp_mode','?')} "
                f"bus_type_pos={getattr(_gb,'bus_type_pos','?')} "
                f"bus_det={getattr(_gb,'bus_det',[])} "
                f"incoming_secs={getattr(_gb,'incoming_sections',[])} "
                f"jxy_cache={getattr(_gb,'_junction_xy_cache',None)}",
                force=True
            )

    # ── Write junction centroids CSV ──────────────────────────────────────────
    # Collected from every controller's cached XY (IntersectionController and
    # GroupBasedController both store _junction_xy / _junction_xy_cache).
    # The plot script reads this to draw intersection markers as a reference frame.
    if MARK_DETECTION_POINTS:
        try:
            with open(_JUNC_CSV, "w", newline="", encoding="utf-8") as _jf:
                _jw = csv.writer(_jf)
                _jw.writerow(["junction_id", "x", "y", "cycle_time_s", "bus_phase", "bus_phase_duration_s"])
                for _jiid, _jctrl in controllers.items():
                    # Try cached value first; if not set, call _get_junction_xy()
                    # to resolve it now (the lazy cache may not have fired if no
                    # buses were detected at this junction this run).
                    _jxy = getattr(_jctrl, '_junction_xy', None)
                    if _jxy is None and hasattr(_jctrl, '_get_junction_xy'):
                        try:
                            _jxy = _jctrl._get_junction_xy()
                        except Exception:
                            pass
                    # GroupBasedController caches in gb._junction_xy_cache
                    if _jxy is None:
                        _gb = getattr(_jctrl, 'gb', None)
                        if _gb is not None:
                            _jxy = getattr(_gb, '_junction_xy_cache', None)
                            if _jxy is None and hasattr(_gb, '_get_junction_xy'):
                                try:
                                    _jxy = _gb._get_junction_xy()
                                except Exception:
                                    pass
                    if _jxy is not None:
                        _jcfg = INTERSECTIONS_CONFIG.get(_jiid, {})
                        _cycle_t = float(_jcfg.get('CycleTime', 0) or 0)
                        _bus_ph  = int(_jcfg.get('BusPhase', -1) or -1)
                        _bus_dur = float(_jcfg.get('BusPhaseDuration', 0) or 0)
                        _jw.writerow([_jiid, f"{_jxy[0]:.3f}", f"{_jxy[1]:.3f}",
                                      f"{_cycle_t:.1f}", _bus_ph, f"{_bus_dur:.1f}"])
            log_to_file(f"[MARK] Junction centroids written: {_JUNC_CSV}", force=True)
        except Exception as _je:
            log_to_file(f"[MARK] Junction centroids write failed: {_je}", force=True)

    # ── Plot detection points to PNG + HTML map (post-simulation) ─────────────
    if MARK_DETECTION_POINTS:
        if not os.path.isfile(_DET_CSV):
            log_to_file("[MARK] Detection plot skipped — no CSV (no buses detected?)", force=True)
        else:
            _script_dir = os.path.dirname(os.path.abspath(__file__))
            if _script_dir not in sys.path:
                sys.path.insert(0, _script_dir)
            try:
                import importlib
                import plot_detections as _pd
                importlib.reload(_pd)
                _junc_csv_arg = _JUNC_CSV if os.path.isfile(_JUNC_CSV) else None
                _pd.run(csv_path=_DET_CSV, junc_csv=_junc_csv_arg)
                log_to_file(f"[MARK] Detection plot written alongside {_DET_CSV}", force=True)
            except Exception as _pe:
                import traceback
                log_to_file(f"[MARK] Detection plot failed: {_pe}\n{traceback.format_exc()}", force=True)

            # ── Green-wave time-space dashboard ───────────────────────────────
            try:
                import importlib
                import plot_green_wave as _pgw
                importlib.reload(_pgw)
                _junc_csv_arg = _JUNC_CSV if os.path.isfile(_JUNC_CSV) else None
                _pgw.run(csv_path=_DET_CSV, junc_csv=_junc_csv_arg)
                log_to_file("[GREEN WAVE] Green-wave dashboard written", force=True)
            except Exception as _gwe:
                import traceback
                log_to_file(
                    f"[GREEN WAVE] Plot failed: {_gwe}\n{traceback.format_exc()}",
                    force=True
                )

            # ── Per-bus detail plots with missed-green diagnostics ─────────────
            try:
                import importlib
                import plot_bus_detail as _pbd
                importlib.reload(_pbd)
                _junc_csv_arg = _JUNC_CSV if os.path.isfile(_JUNC_CSV) else None
                _pbd.run(csv_path=_DET_CSV, junc_csv=_junc_csv_arg)
                log_to_file("[BUS DETAIL] Per-bus plots written", force=True)
            except Exception as _bde:
                import traceback
                log_to_file(
                    f"[BUS DETAIL] Plot failed: {_bde}\n{traceback.format_exc()}",
                    force=True
                )

            # ── Space-time green-wave diagram ─────────────────────────────────
            try:
                import importlib
                import plot_spacetime_wave as _pst
                importlib.reload(_pst)
                _junc_csv_arg = _JUNC_CSV if os.path.isfile(_JUNC_CSV) else None
                _pst.run(csv_path=_DET_CSV, junc_csv=_junc_csv_arg)
                log_to_file("[SPACETIME] Space-time diagram written", force=True)
            except Exception as _ste:
                import traceback
                log_to_file(
                    f"[SPACETIME] Plot failed: {_ste}\n{traceback.format_exc()}",
                    force=True
                )

            # ── Shockwave / queue-length dashboard ───────────────────────────
            try:
                import importlib
                import plot_shockwave as _psw
                importlib.reload(_psw)
                _junc_csv_arg = _JUNC_CSV if os.path.isfile(_JUNC_CSV) else None
                _wave_csv_arg = _WAVE_EVENTS_CSV if os.path.isfile(_WAVE_EVENTS_CSV) else None
                _psw.run(det_csv=_DET_CSV, junc_csv=_junc_csv_arg,
                         wave_csv=_wave_csv_arg)
                log_to_file("[SHOCKWAVE] Shockwave dashboard written", force=True)
            except Exception as _psw_e:
                import traceback
                log_to_file(
                    f"[SHOCKWAVE] Plot failed: {_psw_e}\n{traceback.format_exc()}",
                    force=True
                )

            # ── TSP objective trace dashboard ─────────────────────────────────
            try:
                import importlib
                import plot_tsp_objective_trace as _ptot
                importlib.reload(_ptot)
                _obj_trace_arg = (
                    _OBJECTIVE_TRACE_CSV if os.path.isfile(_OBJECTIVE_TRACE_CSV) else None
                )
                _obj_out = os.path.join(
                    os.path.dirname(os.path.abspath(__file__)), "tsp_objective_trace.html"
                )
                if _obj_trace_arg:
                    rows_ot = _ptot._load_objective_csv(_obj_trace_arg)
                    _ptot._build_html(rows_ot, _obj_trace_arg, _obj_out)
                    log_to_file(
                        f"[OBJ TRACE] Objective trace dashboard written ({len(rows_ot)} rows)",
                        force=True
                    )
                else:
                    log_to_file("[OBJ TRACE] No objective_trace CSV found — skipping", force=True)
            except Exception as _otot_e:
                import traceback
                log_to_file(
                    f"[OBJ TRACE] Dashboard failed: {_otot_e}\n{traceback.format_exc()}",
                    force=True
                )

            # ── Queue monitor dashboard ───────────────────────────────────────
            try:
                import importlib
                import plot_queue_monitor as _pqm
                importlib.reload(_pqm)
                _queue_csv_arg = _QUEUE_SNAPSHOT_CSV if os.path.isfile(_QUEUE_SNAPSHOT_CSV) else None
                _pqm.run(queue_csv=_queue_csv_arg, junc_csv=_JUNC_CSV)
                log_to_file("[QUEUE MON] Queue monitor dashboard written", force=True)
            except Exception as _pqm_e:
                import traceback
                log_to_file(
                    f"[QUEUE MON] Plot failed: {_pqm_e}\n{traceback.format_exc()}",
                    force=True
                )

            # ── HTML comparison dashboard (updates after every run) ────────────
            try:
                import importlib
                import generate_dashboard as _gd
                importlib.reload(_gd)
                _batch_csv = os.path.join(
                    os.path.dirname(os.path.abspath(__file__)), "batch_results.csv")
                _dash_dir = os.path.dirname(os.path.abspath(__file__))
                _gd.generate(
                    batch_csv=_batch_csv if os.path.isfile(_batch_csv) else None,
                    out_html=os.path.join(_dash_dir, "tsp_dashboard.html"),
                    log_dir=os.path.join(
                        os.path.dirname(os.path.abspath(__file__)), "logs")
                )
                # Backward-compatible alias: many workflows still open
                # plots_dashboard.html directly.
                _gd.generate(
                    batch_csv=_batch_csv if os.path.isfile(_batch_csv) else None,
                    out_html=os.path.join(_dash_dir, "plots_dashboard.html"),
                    log_dir=os.path.join(_dash_dir, "logs")
                )
                log_to_file("[DASHBOARD] HTML dashboards written: tsp_dashboard.html + plots_dashboard.html", force=True)
            except Exception as _dbe:
                import traceback
                log_to_file(
                    f"[DASHBOARD] Generation failed: {_dbe}\n{traceback.format_exc()}",
                    force=True
                )

            # ── Reward breakdown dashboard (updates after every DCTSP run) ────
            try:
                import importlib
                import plot_reward_breakdown as _prb
                importlib.reload(_prb)
                log_to_file("[REWARD_BREAKDOWN] reward_breakdown.html written", force=True)
            except Exception as _prb_e:
                import traceback
                log_to_file(
                    f"[REWARD_BREAKDOWN] Generation failed: {_prb_e}\n{traceback.format_exc()}",
                    force=True
                )

    # ── Aimsun canvas overlay — GKAnnotation markers in the network view ────────
    # Creates persistent markers visible in the Aimsun network editor.
    # Independent of the PNG/HTML outputs — runs even if those fail.
    if MARK_DETECTION_POINTS and _geojson_features:
        _overlay_detections_on_aimsun_map()
    elif OVERLAY_DETECTIONS_ON_MAP and not _geojson_features:
        log_to_file(
            f"[MAP] No detections collected — GeoJSON at {_DET_GEOJSON} for "
            "manual import via File > Import in Aimsun",
            force=True
        )

    # ── Regenerate signal timing diagram (always, after every run) ───────────
    try:
        import importlib
        _script_dir = os.path.dirname(os.path.abspath(__file__))
        _st_html = os.path.join(_script_dir, "signal_timing_diagram.html")
        _saved_argv = sys.argv[:]
        sys.argv = ["plot_signal_timing.py", LOG_DIR, _st_html]
        try:
            import plot_signal_timing as _pst_mod
            importlib.reload(_pst_mod)
            log_to_file(
                f"[FINISH] signal_timing_diagram.html regenerated -> {_st_html}",
                force=True,
            )
        finally:
            sys.argv = _saved_argv
    except Exception as _pst_e:
        log_to_file(
            f"[FINISH] signal timing diagram error: {_pst_e}",
            force=True,
        )

    # ── Dump RL Q-table to JSON for post-run visualization ───────────────────
    # Only written when GLOBAL_REWARD_MODE is on and a Q-table has been built.
    # File: logs/q_table_<EXPERIMENT>_<ts>.json
    # Format: {jct_id_str: {state_bin_str: [Q_a0,...,Q_a6], ...}, ...}
    if GLOBAL_REWARD_MODE and _dctsp_q_table:
        try:
            import json as _json_mod
            _qt_path = os.path.join(LOG_DIR,
                                    f"q_table_{_CURRENT_EXPERIMENT}_{timestamp}.json")
            # Serialise: int keys → str keys; tuple state → "s,e,d,p" str
            _qt_serial = {}
            for _jk, _jv in _dctsp_q_table.items():
                if _jk == '__experiment__':
                    continue
                _jstr = str(_jk)
                _qt_serial[_jstr] = {}
                if isinstance(_jv, dict):
                    for _sk, _sv in _jv.items():
                        _sstr = ','.join(str(x) for x in _sk) if isinstance(_sk, tuple) else str(_sk)
                        _qt_serial[_jstr][_sstr] = [round(q, 6) for q in _sv]
            _qt_meta = {
                '__meta__': {
                    'experiment': _CURRENT_EXPERIMENT,
                    'action_space': [f"{a[0]}_{int(a[1])}" if a[0] != 'NO_ACTION'
                                     else 'NO_ACTION'
                                     for a in DCTSP_RL_ACTION_SPACE],
                    'state_dims': ['sigma_bin(0-5)', 'eta_bin(0-3)',
                                   'delay_bin(0-3)', 'phase_bin(0-1)'],
                    'n_junctions': len(_qt_serial),
                    'n_state_entries': sum(len(v) for v in _qt_serial.values()),
                }
            }
            _qt_serial.update(_qt_meta)
            with open(_qt_path, 'w', encoding='utf-8') as _qtf:
                _json_mod.dump(_qt_serial, _qtf, indent=2)
            log_to_file(
                f"[RL] Q-table dumped → {_qt_path} "
                f"({_qt_meta['__meta__']['n_junctions']} junctions, "
                f"{_qt_meta['__meta__']['n_state_entries']} state entries)",
                force=True)
        except Exception as _qte:
            log_to_file(f"[RL] Q-table dump error: {_qte}", force=True)

    return 0


def AAPIUnLoad():
    return 0


